# What the guide made of a phrase the time machine could not read; cached per
# phrase so a typed word the poll re-sends every cycle costs one model call, not
# one per poll. A phrase mapped to undef is one the guide could not read either.
my %time_machine_guide_cache;

# The time machine's phrase turned into a moment. A written date and a recognized
# relative offset are read by subs::resolve_when / ago_calc; anything else - a
# phrase neither can read, or one that lands exactly on the epoch without naming
# it - is handed to the guide to interpret, and the view travels where it says.
sub time_machine_resolve {
	my ($spec, $timestamp) = @_;
	return $timestamp unless defined $spec && $spec =~ /\S/;
	my $ms = &subs::resolve_when($spec, $timestamp);
	# a date with a name still attached ("sept 11 attacks") is an event, not that
	# date: the guide reads it, and the plain date is kept only if it has nothing
	if (defined $ms && &subs::date_leftover($subs::resolve_when_residual)) {
		my $guide = &guide_time_machine($spec, $timestamp);
		$ms = $guide if defined $guide;
	}
	if (!defined $ms) {
		my $relative = 0;
		if ($spec =~ /^\s*(?:now|today|tomorrow|yesterday|tonight|tom|yes|mon|tue|wed|thu|fri|sat|sun)\s*$/i) { $relative = 1; }
		# a compact offset ("-3h", "3d 4h", "in 2h"); a spelled-out unit
		# ("6 months") is left to the guide, which reads the words
		elsif ($spec =~ /^\s*(?:in\s+)?[+-]?\d/ && $spec !~ /\b(?:second|minute|hour|day|week|month|year|decade|century)s?\b/i) { $relative = 1; }
		$ms = &subs::ago_calc($spec, $timestamp) if $relative;
	}
	if (!defined $ms) {
		# a time of day that is a habit ("breakfast", "next coffee time"): the hour
		# the person usually does it, from their own records, else a plain hour
		$ms = &subs::usual_ritual_time($spec, $timestamp);
	}
	if (!defined $ms) {
		# "<person>'s [Nth] birthday": a saved birthday first, then the guide, with
		# the years counted here
		$ms = &person_birthday_of($spec, $timestamp);
	}
	if (!defined $ms || ($ms == 0 && $spec !~ /\b(?:1970|epoch|unix)\b/i)) {
		my $guide = &guide_time_machine($spec, $timestamp);
		$ms = $guide if defined $guide;
	}
	$ms = $timestamp unless defined $ms;
	return $ms;
}

# A staged appointment's time, read the same way the time machine reads a typed
# time. A value already in milliseconds passes straight through; anything else
# ("in 20 minutes", "jul 16", "next friday") is resolved by the one resolver the
# clock uses, guide fallback and all, so a create lands where it says.
sub guide_when_ms {
	my ($when) = @_;
	my $now = &subs::rightNow();
	return $now unless defined $when && $when =~ /\S/;
	return $when + 0 if $when =~ /^\s*\d{12,}\s*$/;
	return &time_machine_resolve($when, $now);
}

# A length the person gave ("5 minutes", "lasts 2h") as the tree stores it. Read
# here rather than through time_abbrev_translator: that parser reads a compact unit
# ("5m", "1h") but treats a number followed by a spelled-out word as a bare number -
# minutes - so a model's "90 seconds" arrived as ninety minutes and "1 hour" as one
# minute. A model writes words, so both forms are read here, and a phrase may name
# several parts ("1 hour 30 minutes").
sub guide_duration_ms {
	my ($phrase, $type) = @_;
	return undef unless defined $phrase && $phrase =~ /\S/;
	my %mult = (
		ms => 1, millisecond => 1, milliseconds => 1,
		s => 1000, sec => 1000, secs => 1000, second => 1000, seconds => 1000,
		m => 60000, min => 60000, mins => 60000, minute => 60000, minutes => 60000,
		h => 3600000, hr => 3600000, hrs => 3600000, hour => 3600000, hours => 3600000,
		d => 86400000, day => 86400000, days => 86400000,
		w => 604800000, week => 604800000, weeks => 604800000,
	);
	my $total = 0;
	my $seen = 0;
	while ($phrase =~ /(\d+(?:\.\d+)?)\s*([a-z]*)/gi) {
		my ($n, $u) = ($1, lc($2 || ''));
		$u = 'm' if $u eq '';   # a bare number is minutes, as the app's own input reads it
		my $m = $mult{$u};
		if (!defined $m) {
			# a unit we do not know (months, years): let the app's own parser, whose
			# month/year handling counts real calendar days, read just this part
			my $ms = eval { &subs::time_abbrev_translator($n . $u, &subs::rightNow()) };
			next unless defined $ms && $ms =~ /^-?[0-9.]+$/;
			$m = int($ms) / $n;
		}
		$total += $n * $m;
		$seen = 1;
	}
	return undef unless $seen && $total > 0;
	# Time is an accrual: a start/record is stored as a NEGATIVE offset, so a
	# start/stop pair writes start - stop and a five-minute office visit is -300000ms.
	# Other types keep the plain length. Mirrors the appointment's own duration input,
	# whose start/record rule negates what the person typed.
	return (($type || '') =~ /^(?:start|record)$/) ? -int($total) : int($total);
}

# The words worth searching a phrase for: its nouns, with the small connective
# words dropped, so "the last time I had a beer" searches for "beer".
sub guide_time_keywords {
	my ($spec) = @_;
	$spec = lc($spec // '');
	$spec =~ s/['\x{2019}]\w+//g;   # drop contractions: "i'll" leaves "i"
	my %stop = map { $_ => 1 } qw(
		the a an of to in on at by for with about from into over after before
		my your their his her our its this that these those
		last first next previous following time times day date when
		was were is are am be been being
		did do does have had has i me you it we they he she them us
		and or but if then than so as
		saw see seen meet met went go got get
		what whats how who whom whose which please tell give show find
		will would shall should can could may might must
	);
	my @w = grep { length($_) > 1 && $_ =~ /^[a-z0-9_]+$/ && !$stop{$_} } split /\s+/, $spec;
	@w = @w[0 .. 4] if @w > 5;
	return @w;
}

# A one-line report of a help_search, for a prompt.
sub help_search_summary {
	my ($f) = @_;
	my @bits;
	push @bits, 'apps: ' . join(', ', map { $_->{'app'} } @{ $f->{'apps'} || [] }) if @{ $f->{'apps'} || [] };
	push @bits, 'names: ' . join(', ', @{ $f->{'named'} || [] }) if @{ $f->{'named'} || [] };
	push @bits, 'oldest match: ' . $f->{'first'}->{'when'} . ' (' . $f->{'first'}->{'app'} . ')' if $f->{'first'};
	push @bits, 'newest match: ' . $f->{'last'}->{'when'} . ' (' . $f->{'last'}->{'app'} . ')' if $f->{'last'};
	push @bits, 'next match from now: ' . $f->{'next'}->{'when'} . ' (' . $f->{'next'}->{'app'} . ')' if $f->{'next'};
	return @bits ? join('; ', @bits) : 'nothing found';
}

# The apps whose own padlock is a media padlock (per screen, per window).
our @media_unlock_apps = qw/gallery music folders/;

# The content tables the guide may search by name, beyond the appointments log.
# Only tables that hold the person's own words: the settings, credentials,
# device and cache tables are deliberately left out, so a secret cannot ride out
# to a model on a search.
our %help_search_tables = (
	notes           => [qw/text/],
	mailbox         => [qw/subject/],
	magazine        => [qw/title teaser/],
	model           => [qw/name description manufacturer/],
	option          => [qw/name description manufacturer/],
	subcategory     => [qw/name description manufacturer/],
	option_category => [qw/name/],
);

# One search over the person's records: the appointments that match (by app, file
# or notes), the files they carry, the first, newest and next such moments, and
# any named thing in the content tables. This is the read behind the guide's find
# action and the time machine's own fallback.
sub help_search($q, $device = undef) {
	$q = '' unless defined $q;
	my $like = '%' . join('%', split /\s+/, $q) . '%';
	my $now = &subs::rightNow();
	my (%apps, %files, %named, $first, $last, $next);
	my $visible_count = 0;
	my $fpat = join('.*', map { quotemeta } split /\s+/, lc $q);
	if (length $q) {
		my $rows = &subs::db_query('select app, uuid, file, notes, timestamp from appointments where (app like ? or file like ? or notes like ?) limit 80', $like, $like, $like)->hashes;
		foreach my $r ( @{$rows} ) {
			next unless help_app_visible($r->{'app'}, $device);
			$visible_count++;
			$apps{ $r->{'app'} }++ if $r->{'app'};
			my $fl = eval { decode_json $r->{'file'} } || [];
			foreach my $f ( @{$fl} ) {
				my $n = $f->{'name'} || $f->{'f'};
				next unless $n && lc($n) =~ /$fpat/i;
				$n =~ s{.*/}{};
				$files{ $n } = 1;
			}
			my $ts = $r->{'timestamp'};
			next unless defined $ts && $ts =~ /^\d+$/;
			$ts += 0;
			my $when = eval { localtime($ts / 1000)->strftime('%A %B %d, %Y') };
			next unless $when;
			my $hit = { app => $r->{'app'}, ts => $ts, when => $when };
			$first = $hit if !$first || $ts < $first->{'ts'};
			$last  = $hit if !$last  || $ts > $last->{'ts'};
			$next  = $hit if $ts >= $now && (!$next || $ts < $next->{'ts'});
		}
		foreach my $table ( sort keys %help_search_tables ) {
			my @cols = @{ $help_search_tables{$table} };
			my $where = join(' or ', map { "$_ like ?" } @cols);
			my $rs = eval { &subs::db_query("select " . join(', ', @cols) . " from $table where $where limit 20", (map { $like } @cols)) };
			next unless $rs;
			foreach my $r ( @{ $rs->hashes } ) {
				foreach my $col ( @cols ) {
					next unless defined $r->{$col} && $r->{$col} =~ /\S/ && $r->{$col} !~ /^\d+$/;
					$named{ $r->{$col} } = 1;
				}
			}
		}
	}
	my @apps = map { { app => $_, count => $apps{$_} } } sort { $apps{$b} <=> $apps{$a} } keys %apps;
	my @all = sort keys %files;
	@all = @all[0 .. 7] if @all > 8;
	my @named = sort keys %named;
	@named = @named[0 .. 15] if @named > 16;
	return { query => $q, count => $visible_count, apps => \@apps, files => \@all, named => \@named, first => $first, last => $last, next => $next };
}

# A person's birthday. "<name>'s [next|last] [Nth] birthday" (and "when is/was
# <name>'s birthday") names the annual occasion: the plain form is the next one to
# come, "was"/"last" the last one that passed, and the Nth the year they turn N -
# all counted here from the saved birthday (Configure -> App -> Birthdays). "when
# was <name> born" and "the day <name> was born" name the actual date. Failing a
# saved birthday the guide looks the person up (it knows "Abraham Lincoln's
# birthday"). undef when the phrase is none of these or the date cannot be found,
# so the guide still runs.
sub person_birthday_of {
	my ($spec, $timestamp) = @_;
	my ($name, $n, $mod, $tense) = ('', undef, '', '');
	my $annual = 0;
	if    ($spec =~ /^\s*(?:when\s+)?(?:was|is)\s+(.+?)\s+born\s*$/i)                 { ($name) = ($1); }
	elsif ($spec =~ /^\s*(?:the\s+)?(?:day|date)\s+(.+?)\s+(?:was|is)\s+born\s*$/i)   { ($name) = ($1); }
	elsif ($spec =~ /^\s*(?:what|which)\s+(?:day|date)\s+(?:was|is)\s+(.+?)\s+born\s*$/i) { ($name) = ($1); }
	elsif ($spec =~ /^\s*(?:when\s+(is|was)\s+|when['\x{2019}]s\s+)?(.+?)[\x{2019}']?s\s+(?:(next|last)\s+)?(?:(\d{1,3})\s*(?:st|nd|rd|th)\s+)?birthday\s*$/i) {
		($tense, $name, $mod, $n) = (lc($1 // ''), $2, lc($3 // ''), $4);
		$annual = 1;
	}
	else { return undef; }
	$name =~ s/^\s+|\s+$//g;
	return undef unless length $name;
	my $birth = &subs::saved_birthday_ms($name, $timestamp);
	$birth = &guide_time_machine($name . "'s birthday", $timestamp) unless defined $birth;
	return undef unless defined $birth;
	# "when was <name> born" / "the day <name> was born" name the actual date
	return $birth unless $annual;
	my @b = localtime($birth / 1000);
	# the occasion in a given year, at the birthday's own time of day
	my $in_year = sub {
		my ($year) = @_;
		return &subs::resolve_when(sprintf('%04d-%02d-%02d %02d:%02d:%02d', $year, $b[4] + 1, $b[3], $b[2], $b[1], $b[0]), $timestamp);
	};
	# "the Nth birthday" is the year they turn N
	return $in_year->($b[5] + 1900 + $n) if defined $n;
	# the occasion falls each year: the next one to come, or the last one that passed
	my @now = localtime($timestamp / 1000);
	my $this = $in_year->($now[5] + 1900);
	my $past = ($tense eq 'was') || ($mod eq 'last');
	if ($past) {
		return (defined $this && $this <= $timestamp) ? $this : $in_year->($now[5] + 1899);
	}
	return (defined $this && $this >= $timestamp) ? $this : $in_year->($now[5] + 1901);
}

# The time machine's own fallback: read a phrase neither a written date nor a
# relative offset could. The records are looked up first and handed to the guide,
# which answers with the moment it means - or, when the phrase asks the person's
# thing to be started, with an appointment it has it write (through
# appointment_writer, so alarms, budgets and any embedded relay all fire). No
# guide model on this machine leaves the phrase unread.
sub guide_time_machine {
	my ($spec, $timestamp) = @_;
	my $key = lc $spec;
	return $time_machine_guide_cache{$key} if exists $time_machine_guide_cache{$key};
	my $ms;
	my $model = &subs::setting_grabber({ app => 'mail', setting => 'help_assistant' });
	if ($model) {
		my $now_text = localtime(&subs::rightNow() / 1000)->strftime('%A, %B %d %Y, %I:%M%P');
		my @words = &guide_time_keywords($spec);
		my $dossier = '';
		if (@words) {
			my $found = &help_search(join(' ', @words));
			$dossier = 'Here is what their records show for "' . join(' ', @words) . '": ' . &help_search_summary($found) . '. ';
		}
		my $birthday = ($config->{'birthday'} ? ('Their birthday is ' . $config->{'birthday'} . '. ') : '');
		my $system = 'You are the time machine inside JawnOS. The person typed a phrase that names a moment, or asks you to start or log something. '
			. 'Right now it is ' . $now_text . ' in local time. ' . $birthday . $dossier
			. 'If the phrase names a person or an event, past or future ("Abraham Lincoln\'s birthday", "the day the Berlin Wall fell", "when the first world war ended"), use what you know of history and give the moment it names - including the hour and minute when history records one (the moment JFK was shot, the hour the armistice took effect). For a period or an era that has no single day (the American Revolution, the Renaissance), give the moment it began. '
			. 'If the phrase names no time of day, keep the present time of day. A bare amount of time with no direction ("6 months", "2 hours") points into the past; a leading minus points ahead. '
			. 'Reply with ONE JSON action and nothing else: '
			. '{"action":"time","when":"YYYY-MM-DD HH:MM:SS"} naming the moment the phrase means in local time, to travel there; '
			. 'or {"action":"create","app":"lunch","title":"Lunch","when":"in 20 minutes","type":"start","duration":"20 minutes"} to make an appointment, when they ask you to start, begin or log something ("type" is start, record or command for something the alarm fires; "duration" is how long it lasts, only when they say it - give a plain positive length, the tree stores it as the negative accrual itself). '
			. 'If the phrase names no moment and asks for nothing, reply {"action":"time","when":"unknown"}';
		my ($text, $err) = &subs::evaluation_model_call_role('help_assistant', $system, $spec, &subs::ai_role_thinking('help_assistant'));
		if ($text) {
			my $action = eval { decode_json $text };
			if (!$action && $text =~ /(\{.*\})/s) { $action = eval { decode_json $1 }; }
			$action = { action => 'time', when => $text } unless $action && $action->{'action'};
			my $act = $action->{'action'};
			if ($act eq 'create' && $spec =~ /\b(?:start|begin|log|record|add|create|schedule|make|new|remind)\b/i) {
				my $when_ms = &guide_when_ms($action->{'when'});
				my $app = &subs::unformat_name($action->{'app'} || $action->{'title'} || 'appointment');
				my $title = $action->{'title'} || '';
				my $type = $action->{'type'} || 'start';
				my $duration = &guide_duration_ms($action->{'duration'}, $type);
				# the Confirmation Requirement: unticked, the appointment is written at
				# once (through appointment_writer, so its alarm and any embedded relay
				# fire); ticked, it is staged for the person to confirm instead
				my $confirm = (&subs::setting_grabber({ app => '__president', setting => 'guide_confirm', device => 'all' }) // 'on');
				if ($confirm eq 'off') {
					my $appt = {
						uuid => &subs::random_string_creator(40),
						app => $app,
						type => $type,
						timestamp => $when_ms,
						server_time => &subs::rightNow(),
						notes => $title,
						source => 'guide',
						device => &subs::device_setter(),
					};
					$appt->{'duration'} = $duration if defined $duration;
					&appointment_writer(undef, $appt);
				}
				else {
					&guide_stage_appointment(undef, { app => $app, type => $type, timestamp => $when_ms, title => $title, duration => $action->{'duration'}, source => 'guide' });
				}
				$ms = $when_ms;
			}
			elsif ($act eq 'time') {
				my $w = $action->{'when'};
				if (defined $w && $w !~ /unknown/i) {
					# read the answer with the same resolver, so a year-1 or B.C. answer
					# ("0001-12-25", "-0044-03-15") lands right - str2time reads year 1
					# as 2001 and refuses a negative year
					my $r = &subs::resolve_when($w, $timestamp);
					if (!defined $r) {
						$w =~ s/\bat\b/ /gi;
						my $t = eval { str2time($w) };
						$r = $t * 1000 if $t;
					}
					$ms = $r if defined $r;
				}
			}
		}
	}
	$time_machine_guide_cache{$key} = $ms;
	return $ms;
}

sub timestamp_adjuster($c) {
	my $timestamp = $c->param('timestamp');
	my $time_machine = $c->param('time_machine');
	my $timeshift = $c->param('timeshift');
	my $ago = $c->param('ago');
	if ($time_machine) {
		$timestamp = &time_machine_resolve($time_machine,$timestamp);
	}
	if ($timeshift) {
		if ($timeshift =~ /[0-9]/gi) {
			$timestamp = &subs::ago_calc($timeshift,$timestamp);
		}
	}
	if ($ago) {
		$timestamp = &subs::ago_calc($ago,$timestamp);
	}
	return $timestamp;
}

post '/manager/take_picture' => sub($c) {
	my $timestamp = &timestamp_adjuster($c);
	my $camera = $c->param('camera');
	my $app = $c->param('app');
	my $uuid = $c->param('uuid');
	my ($file,$ocr);
	my $data = {
		app => $app,
		timestamp => $timestamp,
		camera => $camera,
		uuid => $uuid,
		duty => 'image',
		duuid => &subs::random_string_creator()
	};
	if ($timestamp >= &subs::rightNow() + 1000) {
		my $appt = &subs::db_select('appointments', undef, { app => $app, uuid => $uuid })->hashes->[0];
		my $duties = eval { return decode_json $appt->{'duties'} } || [];
		push @{$duties}, $data;
		@{$duties} = sort { $a->{'timestamp'} <=> $b->{'timestamp'} } @{$duties};
		my $next_duty = $duties->[0]->{'timestamp'};
		my $jduties = encode_json $duties;
		&subs::db_update('appointments', { duties => $jduties, next_duty => $next_duty, server_time => &subs::rightNow() }, { app => $app, uuid => $uuid });
		&subs::appt_alarm_setter(&subs::db_select('appointments', undef, { app => $app, uuid => $uuid })->hashes->[0]);
	}
	else {
		($file,$ocr) = &take_picture($c,$data);
	}
	&Websocket::send('server', { console => 'appointmentDetailGrabber(\'' . $app . '\',\'' . $uuid .'\');'});
	$c->render(json => { files => $file, ocr => $ocr });
};

# Claim unclaimed media onto an appointment: each named file row moves from its
# Camera-app holder onto the chosen appointment, and a holder emptied by the move
# is deleted. The media itself stays where it was sealed; only the row moves.
post '/manager/unclaimed/claim' => sub($c) {
	my $app = &subs::unformat_name($c->param('app') || '');
	my $uuid = $c->param('uuid') || '';
	my @file_uuids = grep { $_ } split /,/, ($c->param('file_uuids') || '');
	unless ($app && @file_uuids) { $c->render(json => { ok => 0, error => 'need app and file_uuids' }); return; }
	# the claim box hands over an app name; when no specific appointment was chosen,
	# file onto that app's most recent appointment row
	if (!$uuid) {
		my $latest = &subs::db_query('select uuid from appointments where app=? and uuid is not null order by server_time desc limit 1', $app)->hash;
		$uuid = $latest->{'uuid'};
	}
	unless ($uuid) { $c->render(json => { ok => 0, error => 'no such appointment to claim onto' }); return; }
	my $target = &subs::db_select('appointments', undef, { app => $app, uuid => $uuid })->hashes->[0];
	unless ($target) { $c->render(json => { ok => 0, error => 'no such appointment to claim onto' }); return; }

	my $holders = &subs::db_select('appointments', undef, { app => 'camera', source => 'unclaimed' })->hashes || [];
	my %taken = map { $_ => 1 } @file_uuids;
	my %owner;   # file_uuid -> 1 when it is really unclaimed here
	foreach my $h ( @{$holders} ) {
		my $of = eval { return decode_json $h->{'file'} } || [];
		foreach my $f ( @{$of} ) {
			$owner{ $f->{'uuid'} } = 1;
		}
	}

	my $tf = eval { return decode_json $target->{'file'} } || [];
	my @target_files = @{$tf};
	my $claimed = 0;
	foreach my $h ( @{$holders} ) {
		my $of = eval { return decode_json $h->{'file'} } || [];
		my @orig = @{$of};
		my @move = grep { $taken{ $_->{'uuid'} } && $owner{ $_->{'uuid'} } } @orig;
		foreach my $f ( @move ) {
			$f->{'appt_uuid'} = $uuid;
			push @target_files, $f;
			$claimed++;
		}
		my @left = grep { !$taken{ $_->{'uuid'} } } @orig;
		if (@move) {
			if (@left) {
				&subs::db_update('appointments', { file => encode_json(\@left), server_time => &subs::rightNow() }, { app => 'camera', uuid => $h->{'uuid'} });
			}
			else {
				&delete_app('camera', $h->{'uuid'}, $h->{'server_time'}, 'claimed');
			}
		}
	}

	unless ($claimed) { $c->render(json => { ok => 0, error => 'none of those files are unclaimed' }); return; }
	&subs::db_update('appointments', { file => encode_json(\@target_files), server_time => &subs::rightNow() }, { app => $app, uuid => $uuid });
	&centre_view_grabber({ c => $c, app => $app, timestamp => &subs::rightNow(), cached => 'no' });
	&centre_view_grabber({ c => $c, app => 'camera', timestamp => &subs::rightNow(), cached => 'no' });
	$c->render(json => { ok => 1, claimed => $claimed });
};

# List the unclaimed media waiting on the Camera app: a flat, newest-first list of
# every file row held by a source=unclaimed Camera appointment, with the id pair
# /file_open needs (appt_uuid + file_uuid) and the warranty it expires on.
get '/manager/unclaimed' => sub($c) {
	my $holders = &subs::db_select('appointments', undef, { app => 'camera', source => 'unclaimed' })->hashes || [];
	my @items;
	foreach my $h ( @{$holders} ) {
		my $files = eval { return decode_json $h->{'file'} } || [];
		foreach my $f ( @{$files} ) {
			next unless $f && $f->{'uuid'};
			my $name = $f->{'f'} || '';
			$name =~ s{.*/}{};
			push @items, {
				file_uuid  => $f->{'uuid'},
				appt_uuid  => $h->{'uuid'},
				type       => $f->{'type'} || &file_type_recognizer($f->{'f'} || '')->{'type'} || 'file',
				name       => $name,
				server_time => $f->{'server_time'} || $h->{'server_time'} || $h->{'timestamp'} || 0,
				warranty   => $h->{'warranty'} || 0,
			};
		}
	}
	@items = sort { ($b->{'server_time'} || 0) <=> ($a->{'server_time'} || 0) } @items;
	$c->render(json => { ok => 1, items => \@items });
};

# Search appointments by the name typed in the claim box: returns the distinct
# apps whose slug matches, bounded for the dropdown, so the claim route can file
# straight onto one (the claim route resolves the newest appointment row itself).
get '/manager/unclaimed/appointments' => sub($c) {
	my $search = &subs::unformat_name($c->param('search') || '');
	my @out;
	if (length $search) {
		my $rows = &subs::db_query('select distinct app from appointments where app is not null and app != ? and app like ? limit 50', '', '%' . $search . '%')->hashes || [];
		foreach my $r ( @{$rows} ) {
			next unless $r->{'app'};
			push @out, { app => $r->{'app'}, name => &subs::format_name($r->{'app'}) };
		}
	}
	$c->render(json => { ok => 1, appointments => \@out });
};

sub take_picture($c,$data) {
	my $uuid = $data->{'uuid'} || undef;
	my $timestamp = $data->{'timestamp'} || &subs::rightNow();
	my $server_time = &subs::rightNow();
	my $app = &subs::unformat_name($data->{'app'} || $c->param('app'));
	my $app_path = &subs::path_name($app);
	unless (&subs::session_suds($c)) {
		$c->stash('app' => $app);
		$c->stash('uuid' => $uuid);
	}
	if (!grep { $_ eq $data->{'camera'} } @{$gb::capabilities->{&subs::device_setter()}->{'camera'}}) {
		&remote_relay_request($c);
		return ('denial','denial');
	}


	my $camera = $data->{'camera'} || 0;
	my $warranty = &subs::ago_calc(&subs::setting_grabber({ app => 'app', setting => 'warranty' }) || &subs::setting_grabber({ app => 'me', setting => 'warranty' }), $server_time);
	my ($filename,$ocr);
	my ($db,$database,$sql) = &subs::database_grabber();
	my $folder = &subs::home(&subs::setting_grabber( { app => 'misc', setting => 'photo_location', device => $device } ));
	$filename = $folder . '/' . $app_path;


	my $resolution = &subs::setting_grabber({ app => 'misc', setting => 'photo_size' } ) || '1920x1080';
	`mkdir -p $filename` unless -e $filename;
	my $thumb = $filename . '/.thumbs/';
	`mkdir -p $thumb` unless -e $thumb;
	$thumb = $thumb . $app_path . '_' . $timestamp . '.jpg';
	$filename = $filename . '/' . $app_path . '_' . $timestamp;

	my $text_file = $filename;
	$filename = $filename . '.jpg';


	if ($device eq 'mobile' && ($camera eq 0 || $camera == 1)) {
		`termux-camera-photo -c $camera $filename`;
	}
	elsif ($device eq 'computer' && $camera eq 'webcam') {
		eval { `ffmpeg -i /dev/video0 $filename` };
	}
	if (-e $filename) {
		$ocr = &ocr_reader($c,$filename) unless $data->{'no_ocr'};
		`magick $filename -resize $resolution $filename` unless lc $resolution eq 'raw';
	}
	# A caller that only wants the picture (the People app's crest capture) takes
	# the raw file here; it is not filed as an appointment or sealed in place.
	if ($data->{'capture_only'}) {
		return ($filename, $ocr);
	}
	my $duration = $server_time - &subs::rightNow();
	my $u_data = { thumb => $thumb, server_time => &subs::rightNow(), f => $filename, uuid => &subs::random_string_creator(9), type => 'image', ocr => $ocr };
	$u_data = &thumbnail_creator($u_data);

	my $files = [$u_data];
	if ($uuid) {
		my $appt = &subs::db_select('appointments', undef, { uuid => $uuid, app => $app })->hashes->[0];
		my $pre_files = eval { return decode_json $appt->{'file'} } || [];
		push @{$files}, @{$pre_files};
		my $jfiles = encode_json $files;
		&subs::db_update('appointments', { encryption_standard => undef, duration => $duration, file => $jfiles, server_time => &subs::rightNow() }, { app => $app, uuid => $uuid });
	}
	else {
		$uuid = &subs::random_string_creator(20);
		my $jfiles = encode_json $files;
		my $write = {
			app => $app,
			type => 'image',
			file => $jfiles,
			timestamp => $timestamp,
			server_time => $server_time,
			uuid => $uuid,
			duration => $duration,
		};
		# a capture taken in the Camera app itself, not on an appointment, is
		# unclaimed media: it waits a week on the Camera app to be claimed
		if ($app eq 'camera') {
			$write->{'source'} = 'unclaimed';
			$write->{'warranty'} = &subs::rightNow() + (7 * 24 * 60 * 60 * 1000);
		}
		else {
			$write->{'warranty'} = $warranty;
		}
		&appointment_writer($c, $write);
	}
	my $jfiles = encode_json $files;
	&subs::file_encrypter({ app => $app });

	return ($jfiles,$ocr);
}

post '/manager/scan_document' => sub($c) {
	my $timestamp = &timestamp_adjuster($c);
	my $feed = $c->param('feed');
	my $app = $c->param('app');
	my $uuid = $c->param('uuid');
	my $scandata = {
		timestamp => $timestamp,
		feed => $feed,
		uuid => $uuid,
		app => $app,
		source => 'existing',
		duty => 'scan',
		duuid => &subs::random_string_creator()
	};
	my $file;
	if ($timestamp >= &subs::rightNow() + 1000) {
		my $appt = &subs::db_select('appointments', undef, { app => $app, uuid => $uuid })->hashes->[0];
		my $duties = eval { return decode_json $appt->{'duties'} } || [];
		push @{$duties}, $scandata;
		@{$duties} = sort { $a->{'timestamp'} <=> $b->{'timestamp'} } @{$duties};
		my $next_duty = $duties->[0]->{'timestamp'};
		my $jduties = encode_json $duties;
		&subs::db_update('appointments', { duties => $jduties, next_duty => $next_duty, server_time => &subs::rightNow() }, { app => $app, uuid => $uuid });
		&subs::appt_alarm_setter(&subs::db_select('appointments', undef, { app => $app, uuid => $uuid })->hashes->[0]);
