# The scanimage invocation for a feed, shared by the document scanner and the
# Market receipt reader so the two never drift. $feed is 'adf' or 'flatbed'
# (case-insensitive) and must be one the scanner declares; $file is the output
# base (an ADF pages itself with --batch and a %d suffix). Undef for a feed the
# scanner does not offer, which callers read as "this scanner cannot do that".
sub scanner_scan_command($feed, $file) {
	my $scanner = $config->{'scanners'}->[0];
	return undef unless $scanner && $file;
	my $printer = &subs::device_lister(&subs::rightNow(),'printer');
	my $address = ($printer && $printer->{'ip'}) ? "hpaio:/net/officejet_3830_series?ip=" . $printer->{'ip'} : $scanner->{'address'};
	my $resolution = $scanner->{'resolution'};
	my @feeds = map { lc } @{ $scanner->{'feeds'} || [] };
	$feed = lc($feed || '');
	if ($feed eq 'flatbed' && grep { $_ eq 'flatbed' } @feeds) {
		return "scanimage --format tiff --source Flatbed --batch=$file.tiff --mode Color -d $address --resolution=$resolution --progress";
	}
	if ($feed eq 'adf' && grep { $_ eq 'adf' } @feeds) {
		return "scanimage --format tiff --source ADF --batch=$file\_\%d.tiff --mode Color -d $address --resolution=$resolution --progress";
	}
	return undef;
}

# The page files one scanner run produced, in page order. An ADF run writes
# $base_1.tiff, $base_2.tiff, ... (the %d suffix); a flatbed run a single
# $base.tiff. mtime is not a trustworthy order for a fast feed, so a numbered
# page sorts by that number and an unnumbered page (the flatbed one) by name.
sub scanner_page_list($base) {
	my @files = grep { length } glob("$base*.tiff");
	return sort {
		my ($an) = $a =~ /_([0-9]+)\.tiff$/;
		my ($bn) = $b =~ /_([0-9]+)\.tiff$/;
		(defined $an && defined $bn) ? ($an <=> $bn) : ($a cmp $b);
	} @files;
}

sub scan($c,$scandata) {
	my $timestamp = $scandata->{'timestamp'};
	my $feed = $scandata->{'feed'};
	my $uuid = $scandata->{'uuid'};
	my $suds = &subs::session_suds($c);
	my $source = $scandata->{'source'};
	my $app = $scandata->{'app'} || $c->param('app');
	my $app_path = &subs::path_name($app);
	if (!grep { $_ eq $scandata->{'feed'} } @{ $gb::capabilities->{&subs::device_setter()}->{'scan'} || [] }) {
		&remote_relay_request($c);
		return 'denial';
	}
	my ($db,$database,$sql) = &subs::database_grabber();

	my $start_time = &subs::rightNow();
	my $folder = &subs::home(&subs::setting_grabber( { app => 'misc', setting => 'scan_location', device => $device } ));
	my $filename = $folder . '/' . $app_path;
	$filename = &subs::home($filename);
	`mkdir -p $filename` unless -e $filename;
	my $thumb_folder = $filename . '/.thumbs';
	`mkdir -p $thumb_folder` unless -e $thumb_folder;
	my $thumb = $thumb_folder . '/' . $app_path . '_' . $timestamp . '.jpg';
	my $file = $filename . '/' . $app_path . '_' . $timestamp;
	my $image_file = $file . '.jpg';
	&subs::subprocessor(sub {
    Mojo::IOLoop->reset;
		($db,$database,$sql) = &subs::database_grabber();
		my $command = &scanner_scan_command($feed, $file);
		my $caseworker = `$command`;
		sleep 1;
		my @scans = &scanner_page_list($file);
		my @filenames;
		my $count = 1;
		my $photo_size = &subs::setting_grabber({ app => 'misc', setting => 'scan_size', device => $device } ) || '1920x1080';
		foreach my $scan (@scans) {
			$file = $scan;
			$file =~ s/\.[^.]+$//;
			$image_file = $file . '.jpg';

			my @image_file = split /\//, $image_file;
			my $thumb_file = pop @image_file;
			$thumb = $thumb_folder . '/' . $thumb_file;


			my $ocr = &ocr_reader($c,$scan);
			if ($photo_size ne "Raw") {
				my $convert = `magick convert $scan -resize $photo_size $image_file`;

			}
			else {
				my $convert = `magick convert $scan $image_file`;
			}
			`shred -u $scan`;
			push @filenames, { f => $image_file , thumb => $thumb, ocr => $ocr};

			$count++;

		}
		my $fnames = [];
		foreach my $f ( @filenames ) {
			my $file_data = { server_time => &subs::rightNow(), ocr => $f->{'ocr'}, f => $f->{'f'}, thumb => $f->{'thumb'}, uuid => &subs::random_string_creator(10), type => 'document', 'of' => $f->{'f'} };
			$file_data = &thumbnail_creator($file_data);
			push @{$fnames}, $file_data;
		}

		if ($uuid) {
			my $appt = &subs::db_select('appointments', undef, { app => $app, uuid => $uuid })->hashes->[0];
			my $pre_files = eval { return decode_json $appt->{'file'} } || [];
			if (scalar @{$pre_files} > 0) {
				push @{$fnames}, @{$pre_files};
			}
		}


		my $filenames = encode_json $fnames;
		my $server_time = &subs::rightNow();
		my $duration = ($start_time - $server_time );
		if (@{$fnames} > 0) {
#			&subs::db_query('update appointments set server_time = ?, duration = ?, file = ?, encryption_standard = ? where app = ? and uuid = ?',
#				&subs::rightNow(),$duration, $filenames, undef, $app, $uuid );

			&subs::db_update('appointments' , { server_time => &subs::rightNow(), duration => $duration, file => $filenames, encryption_standard => undef }, { app => $app, uuid => $uuid });

			&Websocket::send('server', { console => 'appointmentDetailGrabber(\'' . $app . '\',\'' . $uuid .'\');'});
		}
		elsif ( scalar @filenames == 0 && $source ne 'existing' ) {
			&subs::db_delete('appointments', { uuid => $uuid });
			&Websocket::send('server', { console => '$(\'appointment_detail[app="' . $app . '"][uuid="' . $uuid . '"]\').remove();'});
		}
		&subs::file_encrypter({ app => $app });
	}, { name => 'document scanner' });
	&Websocket::send('server', { console => 'appointmentDetailGrabber(\'' . $app . '\',\'' . $uuid .'\');'});
	return encode_json [{ f => $image_file }];
}

sub ocr_reader($c,$filename) {
	my $text_file = $filename;
	`tesseract $filename $text_file`;
	$text_file = $text_file . '.txt';
	my $ocr = read_file($text_file);
	# Keep every printable character, including accented letters and CJK text.
	# Only the control bytes that OCR engines emit are removed; the old ASCII
	# filter silently erased whole languages from a scanned document.
	$ocr =~ s/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]+//g;
	$ocr = &subs::note_encrypter(&subs::session_suds($c),$ocr);
	`shred -u $text_file`;

	return $ocr;
}

sub play_audio($file) {
	&subs::subprocessor(sub {
		$file = &subs::terminal_name($file);
		if ( `ps -e | grep play` ) {
			`pkill play`;
		}
		else {
			&subs::subprocessor(sub {
		    Mojo::IOLoop->reset;
				`play "$file"`;
			}, { name => 'audio player' });
		}
	}, { name => "Audio file player" });
	return $file;
}

sub play_audio_stop($file) {
	`pkill play`;
	return $file;
}



get '/file_open' => sub($c) {
	my $data = &rock_and_roll($c);
#	$c->render(text => 'no') if $data eq 'no';
};


# The tag for a file response: path, inode, size and mtime. A reseal changes the
# ciphertext (and the tag); an unchanged file revalidates without any decryption.
sub file_cache_tag($file) {
	my @st = stat($file);
	return undef unless @st;
	return {
		etag => '"' . &subs::md5_sum(join(':', $file, $st[1], $st[7], $st[9])) . '"',
		mtime => $st[9],
	};
}

# Stamp an existing tag on a response that is about to carry the file.
sub file_response_headers($c, $file, $cache_control) {
	my $tag = &file_cache_tag($file);
	return 0 unless $tag;
	# Every path through rock_and_roll honours a Range request, so say so: a
	# media stack that does not see Accept-Ranges asks for the whole file (or
	# gives up) instead of seeking.
	$c->res->headers->accept_ranges('bytes');
	$c->res->headers->etag($tag->{'etag'});
	eval {
		require Mojo::Date;
		$c->res->headers->last_modified(Mojo::Date->new($tag->{'mtime'})->to_string);
	};
	$c->res->headers->cache_control($cache_control) if defined $cache_control && length $cache_control;
	return 1;
}

# Answer an unchanged file with a 304 before any bytes are read. Only called
# after authentication, so it cannot tell a stranger whether a path exists.
# Nothing is stamped unless the request really is a match, so a failed render is
# never given a tag a later request could revalidate against.
sub file_response_cache_headers($c, $file, $cache_control) {
	my $tag = &file_cache_tag($file);
	return 0 unless $tag;
	my $match = 0;
	my $etag = $tag->{'etag'};
	my $inm = $c->req->headers->if_none_match;
	if (defined $inm && length $inm) {
		$match = 1 if $inm eq '*' || $inm =~ /\Q$etag\E/;
	}
	else {
		my $ims = $c->req->headers->if_modified_since;
		if (defined $ims && length $ims) {
			my $since = eval {
				require Mojo::Date;
				Mojo::Date->new($ims)->epoch;
			};
			$match = 1 if defined $since && $tag->{'mtime'} <= $since;
		}
	}
	return 0 unless $match;
	return &file_response_headers($c, $file, $cache_control);
}

# The MIME an <audio>/<video> element can open, from the extension first (an
# mp4 can be either) and the sniffer's verdict second. /play and /file_open
# used to hand the data to render_file() without a type, and that helper
# answers "application/x-download" with "Content-Disposition: attachment".
# Desktop Chrome sniffs past that; Android's media stack does not - it refused
# the track outright. Only audio/video are listed here: everything else keeps
# the download disposition it had.
my %media_type_for_ext = (
	mp3 => 'audio/mpeg', m4a => 'audio/mp4', aac => 'audio/aac',
	wav => 'audio/wav', flac => 'audio/flac', oga => 'audio/ogg',
	ogg => 'audio/ogg', opus => 'audio/ogg',
	mp4 => 'video/mp4', m4v => 'video/mp4', mkv => 'video/x-matroska',
	webm => 'video/webm', mov => 'video/quicktime',
	wmv => 'video/x-ms-wmv', avi => 'video/x-msvideo',
	mpg => 'video/mpeg', mpeg => 'video/mpeg',
);
sub media_content_type($file, $verdict) {
	my $name = $file;
	$name =~ s/\.enc$//i;
	my @parts = split /\./, $name;
	my $ext = lc $parts[-1];
	return $media_type_for_ext{$ext} if $media_type_for_ext{$ext};
	return $verdict if defined $verdict && $verdict =~ m{^(?:audio|video)/};
	return undef;
}

# A media response is inline, so a phone's player receives it as the track and
# not as a download; every other file keeps render_file's attachment default.
sub media_render_args($file, $verdict) {
	my $type = &media_content_type($file, $verdict);
	return () unless defined $type && $type =~ m{^(?:audio|video)/};
	return (content_type => $type, content_disposition => 'inline');
}

# Android's /sdcard is a FUSE mount. Mojolicious's render_file(filepath => ...)
# hands the path to Mojo::Asset::File, whose sendfile/seek path never returns on
# that mount: the request is left open with no headers, so the phone's <video>
# sits at readyState 0 and the music player runs through the whole queue. A
# plain read/seek on the same path works (the /play as_is path proves it), so
# stream the bytes here instead - with the one Range a media element sends.
sub stream_fuse_media($c, $file) {
	my $type = &media_content_type($file, undef);
	return 0 unless defined $type && $type =~ m{^(?:audio|video)/};
	my $size = -s $file;
	return 0 unless defined $size && $size > 0;
	my ($start, $end, $code) = (0, $size - 1, 200);
	my $range = $c->req->headers->range;
	if (defined $range && length $range && $range =~ m/^bytes=(\d*)-(\d*)/) {
		my ($s, $e) = ($1, $2);
		if ($s eq '' && $e ne '') {
			my $want = int($e);
			$want = $size if $want > $size;
			$start = $size - $want;
			$end = $size - 1;
		}
		elsif ($s ne '') {
			$start = int($s);
			$end = ($e ne '') ? int($e) : $size - 1;
			$end = $size - 1 if $end >= $size;
		}
		if ($start > $end || $start >= $size) {
			$c->res->code(416);
			$c->res->headers->content_range('bytes */' . $size);
			$c->res->headers->accept_ranges('bytes');
			$c->res->body('');
			return 1;
		}
		$code = 206;
	}
	my $length = $end - $start + 1;
	return 0 unless open my $fh, '<:raw', $file;
	unless (seek($fh, $start, 0)) { close $fh; return 0; }
	my $name = $file;
	$name =~ s{.*/}{};
	$name =~ s/"/'/g;
	$c->res->code($code);
	$c->res->headers->content_type($type);
	$c->res->headers->content_disposition('inline; filename="' . $name . '"');
	$c->res->headers->content_length($length);
	$c->res->headers->content_range('bytes ' . $start . '-' . $end . '/' . $size) if $code == 206;
	&file_response_headers($c, $file, 'private, no-cache');
	my $remaining = $length;
	my $chunk = 256 * 1024;
	my $emit;
	$emit = sub {
		if ($remaining <= 0) { close $fh; $c->write(''); return; }
		my $want = $remaining < $chunk ? $remaining : $chunk;
		my $buf = '';
		my $got = read($fh, $buf, $want);
		if (!defined $got || $got <= 0) { close $fh; $c->write(''); return; }
		$remaining -= $got;
		$c->write($buf, $emit);
	};
	$emit->();
	return 1;
}

# Pump a sealed file to the client a chunk at a time, so a large video starts
# playing after the 16 KB probe instead of after the whole file is decrypted and
# copied. Content-Length is known (the ciphertext length, which is exactly what
# the old path served for nopad), so this is a plain body, not chunked encoding.
# Only the in-process ciphers reach here; the openssl fallback and PDFs keep the
# buffered path.
sub stream_sealed_file($c, $job, $file, $cache_control) {
	my $spec = $job->{'spec'};
	my $mode = $spec->{'family'} eq 'ctr' ? &subs::note_ctr_mode($spec) : &subs::note_cbc_mode($spec, 1);
	my $stream = eval { $mode->start_decrypt($job->{'key'}, $job->{'iv'}) };
	return 0 unless $stream;

	my $name = $file;
	$name =~ s{.*/}{};
	$name =~ s/\.enc$//i;
	utf8::decode($name) if !utf8::is_utf8($name);
	$name = &quote($name);
	$name = Encode::encode('UTF-8', $name) if eval { require Encode; 1 };

	my $content_type = &media_content_type($file, $job->{'verdict'}) || 'application/x-download';
	my $disposition = $content_type =~ m{^(?:audio|video)/} ? 'inline' : 'attachment';
	$c->res->code(200);
	$c->res->headers->content_type($content_type);
	$c->res->headers->content_disposition($disposition . ';filename=' . $name);
	$c->res->headers->accept_ranges('bytes');
	$c->res->headers->content_length($job->{'total'});
	&file_response_headers($c, $file, $cache_control);

	my $container = $job->{'container'};
	my ($offset, $end, $step) = (0, length($container) - 16, 1024 * 1024);
	my $emit;
	$emit = sub {
		if ($offset >= $end) { $c->write(''); return }
		my $take = $offset + $step > $end ? $end - $offset : $step;
		my $plain = eval { $stream->add(substr($container, 16 + $offset, $take)) };
		if (!defined $plain) {
			$c->app->log->error('sealed stream: ' . ($@ // 'decrypt failed'));
			$c->write('');
			return;
		}
		$offset += $take;
		if ($offset >= $end) {
			my $tail = eval { $stream->finish };
			$plain .= $tail if defined $tail && length $tail;
			$c->write($plain, sub { $c->write('') });
		}
		else { $c->write($plain, $emit) }
	};
	$emit->();
	return 1;
}

# Decrypt just the head of a sealed video for ffmpeg. The first frame needs the
# header and opening clusters, not the whole file; the caller falls back to a
# full decrypt when the prefix yields nothing (an mp4 whose moov atom is last).
sub sealed_thumb_prefix($filename, $job, $bytes) {
	my $spec = $job->{'spec'} or return 0;
	my $container = $job->{'container'};
	my $total = length($container) - 16;
	my $take = $bytes < $total ? $bytes : $total;
	my $block = $spec->{'ivlen'};
	$take = int($take / $block) * $block if $spec->{'family'} eq 'cbc';
	$take = $total if $take > $total;
	return 0 unless $take > 0;
	my $ct = substr($container, 16, $take);
	my $mode = $spec->{'family'} eq 'ctr' ? &subs::note_ctr_mode($spec) : &subs::note_cbc_mode($spec, 1);
	my $plain = eval { $mode->decrypt($ct, $job->{'key'}, $job->{'iv'}) };
	return 0 unless defined $plain && length $plain;
	write_file($filename, $plain);
	return 1;
}

# Write a sealed stream's whole plaintext to a path, a chunk at a time, so a
# two-hour film never has to sit in memory as one string.
sub sealed_file_to_path($job, $path) {
	my $spec = $job->{'spec'} or return 0;
	my $container = $job->{'container'};
	my $mode = $spec->{'family'} eq 'ctr' ? &subs::note_ctr_mode($spec) : &subs::note_cbc_mode($spec, 1);
	my $stream = eval { $mode->start_decrypt($job->{'key'}, $job->{'iv'}) };
	return 0 unless $stream;
	open(my $fh, '>', $path) or return 0;
	my ($offset, $end, $step) = (0, length($container) - 16, 1024 * 1024);
	while ($offset < $end) {
		my $take = $offset + $step > $end ? $end - $offset : $step;
		my $plain = eval { $stream->add(substr($container, 16 + $offset, $take)) };
		if (!defined $plain) { close $fh; return 0; }
		print $fh $plain;
		$offset += $take;
	}
	my $tail = eval { $stream->finish };
	print $fh $tail if defined $tail && length $tail;
	close $fh;
	return -s $path ? 1 : 0;
}

# The whole-track loudness baseline: one ffmpeg pass over the audio, measuring
# the mean and peak level. The mean is the track's own loudness; a single gain
# computed from it preserves the dynamics inside the track instead of squeezing
# dialogue and action towards each other every second.
sub media_loudness_measure_path($path) {
	my $out = '';
	eval {
		local $SIG{ALRM} = sub { die "loudness measurement timed out\n" };
		alarm 120;
		my $cmd = 'ffmpeg -nostats -i ' . &subs::terminal_name($path) . ' -vn -af volumedetect -f null - 2>&1';
		$out = `$cmd`;
		alarm 0;
	};
	alarm 0;
	return undef unless length $out;
	my ($mean, $max, $duration);
	foreach my $line ( split /\n/, $out ) {
		$mean = $1 if $line =~ /mean_volume:\s*(-?\d+(?:\.\d+)?) dB/;
		$max = $1 if $line =~ /max_volume:\s*(-?\d+(?:\.\d+)?) dB/;
		$duration = $1 if $line =~ /Duration:\s*(\d+:\d+:\d+(?:\.\d+)?)/;
	}
	return undef unless defined $mean;
	return { mean_volume => $mean + 0, max_volume => (defined $max ? $max + 0 : undef), duration => $duration };
}

sub media_loudness_key($path) {
	my @st = stat($path);
	require Digest::MD5;
	return 'loudness-' . Digest::MD5::md5_hex($path . ':' . ($st[7] || 0) . ':' . ($st[9] || 0));
}

sub media_loudness_cached($path) {
	my $key = &media_loudness_key($path);
	my $cached = &subs::cache_get({ app => 'music', context => 'loudness', subcontext => $key });
	return (ref $cached eq 'HASH' && defined $cached->{'mean_volume'}) ? $cached : undef;
}

# Answer with a cached measurement when there is one, otherwise measure the
# plaintext path and cache the result against the original file's identity.
sub media_loudness_response($c, $measure_path, $identity_path) {
	my $identity = defined $identity_path && length $identity_path ? $identity_path : $measure_path;
	my $cached = &media_loudness_cached($identity);
	if ($cached) {
		$c->render(json => { ok => 1, cached => 1, %{$cached} });
		return;
	}
	my $result = &media_loudness_measure_path($measure_path);
	if ($result) {
		&subs::cache_set({ app => 'music', context => 'loudness', subcontext => &media_loudness_key($identity), warranty => '-1y' }, $result);
		$c->render(json => { ok => 1, %{$result} });
		return;
	}
	$c->render(json => { ok => 0 });
	return;
}

# Making a thumbnail means decrypting the whole original and running
# ImageMagick inside the request. A gallery asks for a screenful at once, so
# every prefork worker ended up doing that (or sleeping on the per-appointment
# priority lock) and the UI's own requests waited behind them - the "web UI
# froze" reports. Only one generation runs per machine; a request that finds
# the slot taken answers at once with a placeholder, and the next view gets the
# finished thumbnail because it is stored in the appointment.
sub thumb_generation_slot {
	my $path = $gb::tmp_dir . '/thumb_generation.lock';
	open(my $fh, '>>', $path) or return undef;
	unless (flock($fh, LOCK_EX | LOCK_NB)) { close $fh; return undef; }
	return $fh;
}

sub thumb_placeholder {
	my ($c) = @_;
	# a 1x1 transparent PNG: a cheap answer while another request generates
	my $png = pack('H*', '89504e470d0a1a0a0000000d49484452000000010000000108060000001f15c4890000000b49444154789c6360000200000500017a5eab3f0000000049454e44ae426082');
	$c->res->headers->content_type('image/png');
	$c->res->headers->cache_control('no-store');
	$c->render(data => $png);
}

# A corrupt file or a stuck decoder used to hold the worker forever; a
# thumbnail is not worth an unanswered request.
sub run_thumb_command {
	my ($command) = @_;
	my $out = '';
	eval {
		local $SIG{ALRM} = sub { die "thumbnail command timed out\n" };
		alarm 20;
		$out = `$command`;
		alarm 0;
	};
	alarm 0;
	return $out;
}

sub rock_and_roll($c) {
	my $man = 'rejected';
	my $file = $c->param('file');
	if ($c->param('remote_uuid') && $c->param('remoted') ne 'yes') {
		$c->param('subprocess' => 'yes');
		my $result = &remote_relay_request($c);

		$result ? $c->render(data => $result) : $c->render(text => 'none');

		return;
	}
	# A thumbnail is a fixed frame of a file, so it can be cached; letting the
	# browser hold it keeps a repeat visit to the music library (which asks for a
	# thumbnail per song) from re-requesting every one. Captured before an existing
	# thumbnail swaps the file out and clears the parameter. The header itself is
	# set only on a successful response, so a rejected or 'none' one is not cached.
	my $wants_thumb = ($c->param('thumb') ? 1 : 0);
	# A hover preview asks for one frame at a position. It must be generated at
	# that position, not answered from the track's one cached cover thumbnail,
	# and it must not replace that cover.
	my $hover_position = $c->param('position');
	$hover_position = undef unless defined $hover_position && $hover_position =~ /^\d+(?:\.\d+)?$/;
	my ($db,$database,$sql) = &subs::database_grabber();

	my $mag;
	unless ( $c->session('authentication') eq 'approved' ) {
		my $uuid = $c->param('uuid');
		my $fq = &subs::db_query('select * from magazine where uuid = ?',$uuid );
		$mag = $fq->hashes->[0];
		if ($mag->{'status'} eq 'publish') {
			my $public = &subs::setting_grabber({ app => &subs::unformat_name($mag->{'title'}), setting => 'public' });

			if ($public eq 'on' && $mag->{'content'} =~ /$file/) {
				$man = 'approved';
			}
		}
	}
	else {
		$man = &authentication_passer($c);
	}
	if ($man eq 'approved') {
		my $tdir = $gb::tmp_dir;

		# Mojo has already decoded the query string, so use the parameter as-is. A
		# second uri_decode corrupts any name containing a literal %xx sequence
		# (100%20.mp3 -> 100 .mp3), which is exactly how a track failed to open.
		$file = $c->param('track') unless $file;
		if (!$file) {
			if ($c->param('appt_uuid') && $c->param('file_uuid') && $c->param('app')) {
				my $appt = &subs::db_select('appointments', undef, { uuid => $c->param('appt_uuid'), app => $c->param('app') })->hashes->[0];
				my $files = eval { return decode_json $appt->{'file'} } || [];
				foreach my $f ( @{$files} ) {
					if ($f->{'uuid'} eq $c->param('file_uuid')) {
						$file = $f->{'f'};
					}
				}
			}
		}
		my @ext = split /\./, $file;
		my $ext = $ext[-1];
		my $timestamp = $c->param('timestamp') || &subs::rightNow();
		my $filename = $file;
	#	return 'no' unless -e &subs::terminal_name($file);

		if ($c->param('as_is') && -e $file) {
			my $data = read_file($file);
			$data = encode_base64 $data;
			$data ? $c->render(data => $data) : $c->render(text => 'none');
			return;
		}
		elsif ($c->param('as_is')) {
			$c->render(text => 'not found');
			return;
		}
		my $app = &subs::unformat_name($c->param('app'));
		my $writer = {
			timestamp => $timestamp,
			app => &subs::unformat_name($mag->{'title'}) || $app,
			file => encode_json [ $file ],
			uuid => $mag->{'uuid'},
			type => 'file'
		};
		my @file_split = split /\//, $file;
		my $file_match = $file_split[-1];
		my $appt_q;
		if ($c->param('app_uuid')) {
			$appt_q = &subs::db_query('select * from appointments where uuid=? and app=? LIMIT 1',$c->param('app_uuid'), $app);
		}
		else {
			$appt_q = &subs::db_query('select * from appointments where file like ? and app=? and (server_time=? or timestamp=?) LIMIT 1','%' . $file_match . '%', $app,$timestamp,$timestamp);
		}
		my $appter = $appt_q->hashes;
		my $appt_server_time = $appter->[0]->{'server_time'};
		my $atf = eval { return decode_json $appter->[0]->{'file'} } || [];
		my $file_data = {};
		my $thumbnail_size = &subs::setting_grabber({ app => 'misc', setting => 'thumbnail_size' }) || 'none';
		foreach my $af ( @{$atf} ) {
			if ($file eq $af->{'f'}) {
				$appt_server_time = $af->{'server_time'};
				$file_data = $af;

				if ($af->{'thumb'} && $c->param('thumb') && $thumbnail_size ne 'none' && !defined $hover_position) {
					if (-e $af->{'thumb'} && (-s $af->{'thumb'}) > 100) {
						$file = $af->{'thumb'};
						$c->param('thumb' => undef);
					}
				}
			}
		}
		# A conditional request for an unchanged file stops here: no key walk, no
		# decryption, no body. The duty path is an internal collection (mail, file
		# information) and always wants the bytes, so it skips the revalidation.
		if (!$c->param('duty') && $file && -e $file && (!$wants_thumb || ($file_data->{'thumb'} && -e $file_data->{'thumb'}))) {
			my $cc = $wants_thumb ? 'private, max-age=3600' : 'private, no-cache';
			if (&file_response_cache_headers($c, $file, $cc)) {
				$c->res->code(304);
				$c->res->body('');
				return;
			}
		}
		# Do not decrypt an original and run ImageMagick while every other
		# worker is doing the same; a taken slot answers immediately instead.
		my $thumb_slot;
		if ($wants_thumb && $thumbnail_size ne 'none' && $file =~ /\.enc$/i
			&& $file_data->{'uuid'} && (!$file_data->{'thumb'} || !-e $file_data->{'thumb'})) {
			$thumb_slot = &thumb_generation_slot();
			unless ($thumb_slot) {
				&thumb_placeholder($c);
				return;
			}
		}
		if ($file =~ /\.enc$/gi) {
			# A measured track is answered before any decryption: the key walks and
			# the whole-file decrypt a sealed track needs are exactly what a cache
			# hit should skip.
			if ($c->param('loudness')) {
				if (my $cached = &media_loudness_cached($file)) {
					$c->render(json => { ok => 1, cached => 1, %{$cached} });
					return;
				}
			}
			my $encryption_standard = $appter->[0]->{'encryption_standard'} || &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard' }) || "aes-256-ctr";
			my @encryption_standards = ( $encryption_standard );
			if (!$appter->[0]->{'uuid'}) {
				my @file_splitter = split /\//, $file;

				# app=? is served by idx2_appts, so this leading-wildcard LIKE only
				# walks this app's rows; the first query above already uses a multi-index
				# OR on (app,server_time)/(app,timestamp). No table scan.
				$appt_q = &subs::db_query('select * from appointments where app = ? and file is not null and file like ?',$app,'%' . $file_splitter[-1] . '%' );
				my $apptser = $appt_q->hashes;
				# no `my` here: the timestamp found below belongs to the outer scope
				# and is what the credential history is filtered by.
				$appt_server_time = $apptser->[0]->{'server_time'};
				foreach my $at ( @{$apptser} ) {
					my $at_standard = $at->{'encryption_standard'};
					if (defined $at_standard && length $at_standard && !grep { $_ eq $at_standard } @encryption_standards) {
						push @encryption_standards, $at_standard;
					}
					my $atf = eval { return decode_json $at->{'file'} } || [];
					foreach my $af ( @{$atf} ) {
						if ($file eq ($af->{'file'} // $af->{'f'} // '')) {
							$appt_server_time = $af->{'server_time'};
							$file_data = $af;
							if ($af->{'thumb'} && $wants_thumb && $thumbnail_size ne 'none' && !defined $hover_position) {
								if (-e $af->{'thumb'} && (-s $af->{'thumb'}) > 100) {
									$file = $af->{'thumb'};
									$c->param('thumb' => undef);
								}
							}
						}
					}
				}
			}

			unless ($appt_server_time) {
				if (-e $file) {
					my @stat = stat($file);
					$appt_server_time = $stat[10] * 1000;
				}
			}
			my $suds = &subs::suds_grabber();
			my $passwords = &subs::db_query('select * from security where level != ? and level != ? and timestamp <= ? order by timestamp DESC','padlock','door',$appt_server_time);
			# Decrypt each stored credential once, then let sealed_file_open try them
			# against a 16 KB prefix instead of the whole file.
			my @secrets;
			# The current key is a candidate of its own: a file sealed while the
			# person was closing a window used the session suds, which need not be
			# one of the stored credentials below. WebM/thumb files here are sealed
			# with it, and without it they could not be opened at all.
			push @secrets, $suds if defined $suds && length $suds;
			foreach my $p ( @{ $passwords->hashes } ) {
				my $secret = &subs::decrypter($suds, $p->{'credential'}, $appt_server_time);
				push @secrets, $secret if defined $secret && length $secret;
			}
			# One Range is enough: read only the part the client asked for. A
			# thumbnail needs the whole file for ffmpeg/magick, and a PDF is handed
			# to the viewer whole, so those keep the full open.
			my $range;
			my $range_header = $c->req->headers->range;
			if (!$c->param('duty') && !$wants_thumb && $file !~ /\.pdf(?:\.enc)?$/i && defined $range_header && length $range_header) {
				if ($range_header =~ m/^bytes=(\d+)-(\d*)/) {
					my ($start, $end) = ($1, $2);
					if (!defined $end || !length $end) { $range = [ $start, undef ] }
					elsif ($end >= $start) { $range = [ $start, $end - $start + 1 ] }
				}
			}
			my $inspect = sub {
				# the plaintext's own magic, never the path: a webm that File::Type
				# calls octet-stream must still reject a wrong credential
				return &subs::plaintext_verdict($_[0]);
			};
			# A whole-file request for a big sealed file streams: the key is known
			# after the prefix probe, so the body can start before it is all decrypted.
			# A video thumbnail asks for the same pieces, but only to decrypt the head
			# of the file for ffmpeg rather than the whole thing.
			my $video_thumb = ($wants_thumb && $file =~ /\.(?:mp4|webm|mpg|mpeg|mov|mkv|avi)\.enc$/i) ? 1 : 0;
			my $want_stream = (!$range && ($video_thumb || (!$c->param('duty') && !$wants_thumb)) && $file !~ /\.pdf(?:\.enc)?$/i && (-s $file || 0) >= 2 * 1024 * 1024) ? 1 : 0;
			my $opened = &subs::sealed_file_open($file, \@secrets, \@encryption_standards, 1, $inspect, $range, $want_stream);
			if ($c->param('loudness') && $opened && !$opened->{'unsatisfiable'}) {
				my $base = $file;
				$base =~ s/\.enc$//i;
				my $ext = ($base =~ /\.([^.\/]+)$/) ? $1 : 'bin';
				my $tmp = $tdir . '/loudness_' . &subs::random_string_creator(20) . '.' . $ext;
				my $ok = 0;
				if ($opened->{'stream'}) { $ok = &sealed_file_to_path($opened, $tmp); }
				elsif (defined $opened->{'data'}) {
					write_file($tmp, $opened->{'data'});
					$ok = (-s $tmp) ? 1 : 0;
				}
				if ($ok) { &media_loudness_response($c, $tmp, $file); }
				else { $c->render(json => { ok => 0 }); }
				unlink $tmp;
				return;
			}
			if ($opened && $opened->{'stream'} && !$video_thumb) {
				if (&stream_sealed_file($c, $opened, $file, 'private, no-cache')) { return }
				# the stream could not start: fall back to the buffered body
				my $data = &subs::note_open_container($opened->{'container'}, $opened->{'secret'}, $opened->{'standard'}, 1);
				$c->render_file(data => $data) if defined $data && length $data;
				return;
			}
			if ($opened && $opened->{'unsatisfiable'}) {
				$c->res->code(416);
				$c->res->headers->content_range('bytes */' . $opened->{'total'});
				$c->res->headers->accept_ranges('bytes');
				$c->res->body('');
				return;
			}
			if ($opened) {
				my $data = $opened->{'data'};
				my $fd = $opened->{'verdict'};
				my $secret = $opened->{'secret'};
				my $filename = $file;
				$filename =~ s/\.enc$//i;
				my @ext = split /\./, $file;
				my $ext = $ext[-2];
				if ($c->param('duty')) {
							# The data URI is only read for images (the adopt list and the
							# file information card); building it for a video or PDF copied
							# the whole file for nothing.
							my $image;
							if (defined $fd && ($fd =~ m{^image/} || $file =~ /\.(?:jpe?g|png|bmp|gif|webp|tiff?)\.enc$/i)) {
								$image = 'data:' . $fd . ';base64,' . encode_base64($data,'');
							}
							return {
								data => $data,
								image => $image,
								fd => $fd,
								timestamp => $appt_server_time,
								ext => $ext
							};
						}
						elsif ($fd =~ /pdf/) {
							&file_response_headers($c, $file, 'private, no-cache');
							$data ? $c->render(format => 'pdf', data => $data) : $c->render(text => 'none');
							return;
						}
						else {
							my $full_data = $data;
							if ($c->param('thumb') eq 'ya') {

								my @filename = split /\./, $file;
								my $ext = $filename[-2];
								if (defined $hover_position || !(-e $file_data->{'thumb'} && (-s $file_data->{'thumb'}) > 100)) {
									my $filename = $tdir . '/' .&subs::random_string_creator(20) . '.' . $ext;
									if ($file =~ /webm/i) { $fd = 'video/webm'; }
									# The plaintext is already in hand for an image; for a sealed video
									# only the head is decrypted, and a prefix that yields no frame
									# falls back to the whole file below.
									if ($opened->{'stream'}) {
										&sealed_thumb_prefix($filename, $opened, 8 * 1024 * 1024);
									}
									else {
										write_file($filename, $full_data) if defined $full_data && length $full_data;
									}

									if ($file_data->{'type'} eq 'video' || grep { $_ eq $ext } qw/mp4 webm mpg mpeg mov mkv avi/ ) {
										my $seek = defined $hover_position ? sprintf('%.3f', $hover_position) : '00:00:00.010';
										my $command2 = 'ffmpeg -ss ' . $seek . ' -f ' . $ext . ' -i ' . $filename . ' -vframes 1 -c:v png -f image2pipe - | magick - -resize ' . $thumbnail_size . ' - ';
										$file_data->{'type'} = 'video';
										$data = &run_thumb_command($command2);
										if ($opened->{'stream'} && (!defined $data || !length $data)) {
											my $whole = &subs::note_open_container($opened->{'container'}, $opened->{'secret'}, $opened->{'standard'}, 1);
											if (defined $whole && length $whole) {
												write_file($filename, $whole);
												$data = &run_thumb_command($command2);
											}
										}
									}
									elsif ($file_data->{'type'} eq 'image' || grep { $_ eq $ext } qw/bmp tiff jpg png/) {
										if ($opened->{'stream'}) {
											my $whole = &subs::note_open_container($opened->{'container'}, $opened->{'secret'}, $opened->{'standard'}, 1);
											write_file($filename, $whole) if defined $whole && length $whole;
										}
										my $command2 = 'magick ' . $filename . ' -auto-orient -strip -resize ' . $thumbnail_size . ' -';
										$file_data->{'type'} = 'image';
										$data = &run_thumb_command($command2);
									}
									if ($file_data->{'uuid'} && $data && $thumbnail_size ne 'none' && !defined $hover_position) {
										pop @file_split;
										my $folder = join '/', @file_split;
										$folder = $folder . '/.thumbs';
										`mkdir -p $folder`;
										my $worker_id = &subs::random_string_creator(10);
										my $priority = $folder . '/priority.txt';
										my $pr = eval { return decode_json read_file($priority) } || {};
										until ($pr->{$appter->[0]->{'uuid'}}->{'state'} ne 'working' || $pr->{$appter->[0]->{'uuid'}}->{'time'} < &subs::rightNow() - 6000) {
											sleep .5;
											$pr = eval { return decode_json read_file($priority) } || {};
										}
										$pr->{$appter->[0]->{'uuid'}}->{'state'} = 'working';
										$pr->{$appter->[0]->{'uuid'}}->{'time'} = &subs::rightNow();
										$pr->{$appter->[0]->{'uuid'}}->{'worker'} = $worker_id;
										my $jpr = encode_json $pr;
										write_file($priority, $jpr);
										my $path = $folder . '/' . &subs::random_string_creator(23) . '.png.enc';

										$file_data->{'thumb'} = $path;
										$file_data->{'server_time'} = &subs::rightNow();
										$file_data = &subs::file_media_information($file_data,$filename);
										write_file($filename, $data);
										&subs::seal_file($filename, $path, $secret, $encryption_standard);
										my $appt = &subs::db_select('appointments', undef, { uuid => $appter->[0]->{'uuid'}, app => $appter->[0]->{'app'} })->hashes->[0];
										$atf = eval { return decode_json $appt->{'file'} } || [];
										my @natf = grep { $_->{'uuid'} eq $file_data->{'uuid'} } @{$atf};
										if (-e $natf[0]->{'thumb'}) { my $natfthumb = $natf[0]->{'thumb'}; `shred -u $natfthumb`; }
										@{$atf} = grep { $_->{'uuid'} ne $file_data->{'uuid'} } @{$atf};

										push @{$atf}, $file_data;
										my $jdata = encode_json $atf;
										&subs::db_update('appointments', { server_time => &subs::rightNow(), file => $jdata }, { uuid => $appter->[0]->{'uuid'}, app => $appter->[0]->{'app'} });
										$pr = eval { return decode_json read_file($priority) } || {};
										delete $pr->{$appter->[0]->{'uuid'}};
										if (scalar keys %{$pr} == 0) {`shred -u $priority`; }
										else {
											$jpr = encode_json $pr;
											write_file($priority, $jpr);
										}
									}
									&subs::subprocessor(sub {
								    Mojo::IOLoop->reset;

										`shred -u $filename`;
									}, { name => 'thumb shredder' });
								}
							}
							close($thumb_slot) if $thumb_slot;
							if (defined $hover_position && ($file_data->{'type'} // '') eq 'video') {
								$c->res->headers->cache_control('private, max-age=3600') if $data;
								$data ? $c->render_file(data => $data, content_type => 'image/png') : $c->render(text => 'none');
								return;
							}
							$data = $full_data unless (defined $data && length $data);
							$c->res->headers->accept_ranges('bytes');
							&file_response_headers($c, $file, $wants_thumb ? 'private, max-age=3600' : 'private, no-cache');
							my %media_args = &media_render_args($file, $fd);
							if (defined $opened->{'total'} && defined $opened->{'start'}) {
								# The slice is already decrypted. Drop the request's Range so the
								# render helper does not slice it a second time, and send 206.
								my $last_byte = $opened->{'start'} + $opened->{'length'} - 1;
								$c->res->headers->content_range('bytes ' . $opened->{'start'} . '-' . $last_byte . '/' . $opened->{'total'});
								$c->req->headers->remove('Range');
								$data ? $c->render_file(data => $data, status => 206, %media_args) : $c->render(text => 'none');
							}
							else {
								$data ? $c->render_file(data => $data, %media_args) : $c->render(text => 'none');
							}
							return;
						}
					}
		}
		elsif ($c->param('loudness') && -e $file) {
			&media_loudness_response($c, $file, $file);
			return;
		}
		elsif ($c->param('duty')) {
			my $data = read_file($file);
			my $fd = &subs::plaintext_verdict(substr($data, 0, 65536)) || 'application/octet-stream';
			my @ext = split /\./, $file;
			my $ext = $ext[-1];
			my $server_time;
			if (-e $file) {
				my @stat = stat($file);
				$server_time = $stat[10] * 1000;
			}
			return {
				data => $data,
				image => 'data:' . $fd . ';base64,' . encode_base64($data,''),
				fd => $fd,
				timestamp => $server_time,
				ext => $ext
			};
		}
		elsif ($device eq 'mobile') {
			if (-e $file) {
				&file_response_headers($c, $file, $wants_thumb ? 'private, max-age=3600' : 'private, no-cache');
				if ($c->param('subtitle')) {
					my $sub_file = $file . '.vtt';
					if (-e $sub_file) {
						my $data = read_file($sub_file);
						$sub_file ? $c->render_file(filepath => $sub_file, content_type => 'text/vtt', content_disposition => 'inline') : $c->render(text => 'WEBVTT');
						return;
					}
					else {
						my $command = 'ffmpeg -i ' . &subs::terminal_name($file) . ' -map 0:s:0 ' . &subs::terminal_name($sub_file);
						`$command`;
						if (-e $sub_file) {
							my $data = read_file($sub_file);
							$data ? $c->render_file(data => $data, content_type => 'text/vtt', content_disposition => 'inline') : $c->render(text => 'WEBVTT');
							return;
						}
						else {
							return $c->reply->not_found;
						}
					}
				}
				if ($c->param('thumb')) {
					my $data;
					if ($file_data->{'uuid'} && ! -e $file_data->{'thumb'} && $thumbnail_size ne 'none') {
						my ($destination,$asset,$type) = &subs::file_device_renamer({ file => $file, app => $appter->[0]->{'app'}, type => $file_data->{'type'}, is_thumb => 1 });
						$file_data->{'type'} = $type;
						$file_data->{'thumb'} = $destination . $asset;

						$file_data = &thumbnail_creator($file_data);
						$data = read_file($file_data->{'thumb'});
						$data ? $c->render(data => $data) : $c->render(text => 'none');
						return;
					}
					else {
						my $filename = $tdir . '/' . &subs::random_string_creator(20) . '.png';
						my $command = 'ffmpeg -ss 00:01:30.010 -i ' . &subs::terminal_name($file) . ' -vframes 1 -c:v png -f image2pipe - | magick - -resize 200x200 -';
						my $data = `$command`;
						if ($c->param('position')) {
							$data ? $c->render_file(data => $data, content_type => 'image/png') : $c->render(text => 'none');
						}
						else {
							$data ? $c->render_file(data => $data) : $c->render(text => 'none');
						}
						return;
					}
				}
				elsif (grep { $ext eq $_ } qw/xcf tiff/) {
					my $t_file = &subs::terminal_name($file);
					my $c_command = 'magick "' . $file . '[0]" -alpha on -background none -flatten -resize 256x256 png:-';
					my $converted = `$c_command`;
					my $data =  $converted;
					$c->render_file(data => $data);
				}
				else {
					# filepath streams the file and supports Range; reading it into a
					# scalar copied the whole thing and then copied it again into the asset.
					# The FUSE-backed storage paths take the manual streamer above.
					if ($file && $file =~ m{^/(?:sdcard|storage)/} && &stream_fuse_media($c, $file)) { return; }
					$file ? $c->render_file('filepath' => $file, &media_render_args($file, undef)) : $c->render(text => 'none');
					return;
				}
			}
		}
		else {
			if (-e $file) {
				&file_response_headers($c, $file, $wants_thumb ? 'private, max-age=3600' : 'private, no-cache');
				if ($c->param('subtitle')) {
					my $sub_file = $file . '.vtt';
					if (-e $sub_file) {
						my $data = read_file($sub_file);
						$sub_file ? $c->render_file(filepath => $sub_file, content_type => 'text/vtt', content_disposition => 'inline') : $c->render(text => 'WEBVTT');
						return;
					}
					else {
						my $command = 'ffmpeg -i ' . &subs::terminal_name($file) . ' -map 0:s:0 ' . &subs::terminal_name($sub_file);
						`$command`;
						if (-e $sub_file) {
							my $data = read_file($sub_file);
							$data ? $c->render_file(data => $data, content_type => 'text/vtt', content_disposition => 'inline') : $c->render(text => 'WEBVTT');
							return;
						}
						else {
							return $c->reply->not_found;
						}
					}
				}
				if ($c->param('thumb')) {
					my $data;
					if ($file_data->{'uuid'} && ! -e $file_data->{'thumb'} && $thumbnail_size ne 'none') {
						my ($destination,$asset,$type) = &subs::file_device_renamer({ file => $file, app => $appter->[0]->{'app'}, type => $file_data->{'type'}, is_thumb => 1 });
						$file_data->{'type'} = $type;
						$file_data->{'thumb'} = $destination . $asset;

						$file_data = &thumbnail_creator($file_data);
						$data = read_file($file_data->{'thumb'});
						$data ? $c->render(data => $data) : $c->render(text => 'none');
						return;
					}
					else {
						my $filename = $tdir . '/' . &subs::random_string_creator(20) . '.png';
						my $duration = $c->param('duration');
						my @folder = split /\//, $file;
						my $tfile = pop @folder;
						my $folder = join '/', @folder;
						my $thumb_folder = $folder . '/.thumbs';
						my $tfd = &subs::terminal_name($thumb_folder);
						`mkdir -p $tfd` unless -e $thumb_folder;
						my @tfile = split /\./, $tfile;
						pop @tfile;
						if ($c->param('chapter') eq 'ya') {
							$tfile = (join '.', @tfile) . ' ' . $c->param('id') . '.png';
							if ($c->param('end_time')) {
								$duration = (($c->param('end_time') - $c->param('start_time')) / 2 + $c->param('start_time'));
							}
							else {
								$duration = $c->param('start_time') + 5;
							}
						}
						else {
							$tfile = (join '.', @tfile) . '.png';
						}
						$tfile = $thumb_folder . '/' . $tfile;
						if ( -e $tfile && !$c->param('position')) {
							$data = read_file($tfile);
						}
						else {
							my $save = 1;
							if ($c->param('position')) {
								$duration = $c->param('position');
								$save = 0;
							}
							elsif ($c->param('chapter') ne 'ya') {
								if ($duration < 10) {
									$duration = '00:00:01.000';
								}
								elsif ($duration < 60) {
									$duration = '00:00:12.000';
								}
								elsif ($duration < 120) {
									$duration = '00:01:01.000';
								}
								else {
									$duration = '00:02:00.020';
								}
							}
							my $command = 'ffmpeg -ss ' . $duration . ' -i ' . &subs::terminal_name($file) . ' -vframes 1 -c:v png -f image2pipe - | magick - -resize 200x200 -';
							$data = `$command`;

							write_file($tfile, $data) if $save == 1;
						}
					}
					$data ? $c->render_file(data => $data) : $c->render(text => 'none');
					return;
				}
				elsif (grep { $ext eq $_ } qw/xcf tiff/) {
					my $t_file = &subs::terminal_name($file);
					my $c_command = 'magick "' . $file . '[0]" -alpha on -background none -flatten -resize 256x256 png:-';
					my $converted = `$c_command`;
					my $data =  $converted;
					$c->render_file(data => $data);
				}
				else {
					$file ? $c->render_file('filepath' => $file, &media_render_args($file, undef)) : $c->render(text => 'none');
					return;
				}
			}

			else {
				$c->render('text' => '');
				return;
			}
		}
		# A path this machine does not have (a photo kept on another machine, or
		# one that moved) used to fall out of the branches with no answer at all,
		# leaving the request open until the client gave up. One stale album
		# cover could pin a worker that way, and a few of them pinned the pool.
		unless ($c->res->body) {
			$c->res->code(404);
			$c->render(text => 'not found');
		}
	}
	else {
		# the gate may already have answered (a locked request for a file is
		# denied by the lock page); do not replace that answer with 'no'
		$c->render('text' => 'no') unless $c->res->code && $c->res->code == 423;
		return;
	}
}


sub appointment_writer($c,$app) {
	my ($appt_header,$db_written);
	$c = &subs::controller_builder() unless $c;
	# remembered before the stop/record branches rewrite type: only a start or a
	# stop can change which appointment (if any) owns the desktop theme
	my $theme_movement = $app->{'type'};
#	&subs::cache_delete({ app => $app->{'app'}, context => 'template' });
	$app->{'server_time'} = $app->{'server_time'} || $c->param('server_time') || &subs::rightNow();
	$app->{'timestamp'} = $app->{'server_time'} unless $app->{'timestamp'};
	$app->{'browser_tab_id'} = $c->param('browser_tab_id') if $c->param('browser_tab_id') && !$app->{'browser_tab_id'};
	my $remote_address = $app->{'remote_address'};
	delete $app->{'remote_address'};
	my $timestamp = $app->{'timestamp'};
	my $server_time = $app->{'server_time'};
	$app->{'device'} = $device;
	# a stop that names its session (managerReset sends the open session's uuid) is
	# remembered before the uuid is minted, so the stop closes exactly that row
	my $stop_target = $app->{'uuid'};
	$app->{'uuid'} = $app->{'uuid'} || &subs::random_string_creator(90);
	if ($app->{'timestamp'} <= $app->{'server_time'} + 1000) {
		$app->{'seen'} = 'yes';
	}
	my ($db,$database,$sql) = &subs::database_grabber();
	my $init = &subs::setting_initializer($app->{'app'},$app->{'timestamp'});
	$app->{'app'} = $init->{'app'};
	($app->{'app'},undef) = &subs::typesetter($app->{'app'});
	my $settings = &subs::settings_grabber({ app => $app->{'app'} });
	if ($app->{'type'} eq 'usual' || $app->{'type'} eq 'start' || $app->{'type'} eq 'record') {
		&subs::db_insert('appointments', $app);
		$appt_header = &subs::appt_header_printer({ app => $app->{'app'}, timestamp => $app->{'timestamp'} });
		$db_written = 1;
		my ($model,$options);
		($model,$options,$app->{'model'},$app->{'options'}) = &subs::usual_appointment_maker($app,$settings);
		if ($model->{'unit'} && !$app->{'unit'}) {
			$app->{'unit'} = $model->{'unit'};
		}
		if ($model->{'quantity'} && !$app->{'quantity'}) {
			$app->{'quantity'} = $model->{'quantity'};
		}
	}

	my $warranty_holder = $app->{'timestamp'} > $app->{'server_time'} ? $app->{'timestamp'} : $app->{'server_time'};
	$app->{'warranty'} = $app->{'warranty'} || &subs::ago_calc(($init->{'warranty'} || '-10y'), $warranty_holder);
	$app->{'project'} = $settings->{'t_project'} unless $app->{'project'};
	$app->{'pos'} = $settings->{'pos'} unless $app->{'pos'};


	if ($app->{'type'} eq 'record') {
		my $recording_type = &subs::setting_grabber({ app => $app->{'app'}, setting => 'record' });
		my $dat = { recorder => $recording_type };

		if ($recording_type eq 'video') {
			$app->{'seen'} = undef;
		#	$dat->{'camera'} = $camera;

		}
		elsif ($recording_type eq 'audio') {
			$app->{'seen'} = undef;
		}
		elsif ($recording_type eq 'screen') {
			$app->{'seen'} = undef;
		}
		elsif ($recording_type eq 'security') {
			&record_video({ app => $app->{'app'}, uuid => $app->{'uuid'}, timestamp => $app->{'timestamp'} }) if $app->{'seen'} eq 'yes';
		}
		else {
			&record_audio({ app => $app->{'app'}, uuid => $app->{'uuid'}, timestamp => $app->{'timestamp'} }) if $app->{'seen'} eq 'yes';
		}
		$app->{'data'} = encode_json $dat;
	}



	if ($app->{'uuid'} && 0) {
		my $pa = &subs::db_query('select * from appointments where uuid=?', $app->{'uuid'});
		my $prev = $pa->hashes->[0];
		if ($prev->{'app'}) {
			my $duration = ($prev->{'duration'} + (&subs::rightNow() - $prev->{'timestamp'}));
#			&subs::db_query('update appointments set duration=?, timestamp=? where uuid=?', $duration, $app->{'timestamp'}, $app->{'uuid'});
			&subs::db_update('appointments', { duration => $duration, timestamp => $app->{'timestamp'} }, { uuid => $app->{'uuid'}, app => $app->{'app'} });
		}
		else {
			&subs::db_insert('appointments', $app);
			$db_written = 1;
		}
	}
	if ($app->{'type'} eq 'stop') {
		# A stop's own timestamp is the moment it was pressed. One that is hours old
		# is not a press - it is a machine coming back and flushing actions it queued
		# while it was away, and applying it re-closes sessions the person stopped
		# long ago (their rows get a fresh server_time and read as just-stopped, and
		# the catch-up sweep below can close several of them at once). Those replays
		# are dropped: the session simply stays open for a live stop, which is the
		# harmless failure.
		# A stop that names its session is safe to apply however late it arrives: it
		# closes that one row and nothing else. The replay guard stays for a stop that
		# names none, where a late copy could still sweep up sessions it should not.
		my $ages_ms = &subs::rightNow() - (0 + ($app->{'timestamp'} || 0));
		if (!$stop_target && $app->{'timestamp'} && $ages_ms > &subs::stale_action_ms()) {
			$log->info('stale stop ignored for ' . $app->{'app'} . ': pressed ' . int($ages_ms / 60000) . ' minutes ago (a replayed action)')
				if $log;
				return {};
		}
		# Close the session the stop names and only it; a stop that names none - or one
		# this machine has not synced - closes the oldest open session. Resolved by the
		# same helper manager_reset uses, so both writers stop one and the same row
		# instead of each sweeping up every open session for the app.
		my $stop_row = &subs::stop_target_row($app->{'app'}, $stop_target, $app->{'timestamp'});
		return {} unless $stop_row;
		my $appts = [ $stop_row ];
		foreach my $appt ( @{$appts} ) {
			$app->{'type'} = 'stop';
			$app->{'duration'} = $appt->{'timestamp'} - $app->{'timestamp'};
			$app->{'uuid'} = $appt->{'uuid'};
			&subs::db_update('appointments', { stop_timestamp => $app->{'timestamp'}, stop_seen => 'yes', duration => $app->{'duration'}, type => $app->{'type'}, server_time => &subs::rightNow() }, { uuid => $appt->{'uuid'}, app => $app->{'app'} });
			$db_written = 1;
			$appt_header = &subs::appt_header_printer({ app => $app->{'app'}, timestamp => $app->{'timestamp'} });
			my $recording_type = &subs::setting_grabber({ app => $app->{'app'}, setting => 'record' }) || 'system';
			if ($appt->{'type'} eq 'record') {
				my $dat = eval { return decode_json $appt->{'data'} } || {};

				if ($dat->{'recorder'} eq 'security') {
					if ($app->{'seen'} eq 'yes') {
						&record_video_stop({ app => $app->{'app'}, timestamp => $appt->{'timestamp'}, uuid => $appt->{'uuid'} }) if $appt->{'uuid'};
						next;
					}
					else { $app->{'type'} = 'record'; };
				}
				elsif ($dat->{'recorder'} eq 'system') {
					if ($app->{'seen'} eq 'yes') {
						&record_audio_stop({ app => $appt->{'app'}, timestamp => $appt->{'timestamp'}, uuid => $appt->{'uuid'} }) if $appt->{'uuid'};
						next;
					}
					else { $a->{'type'} = 'record'; };
				}
				else {
					&Websocket::send('music', { console => 'jpStop(\'' . $appt->{'app'} . '\',\'' . $dat->{'recorder'} . '\',\'' . $appt->{'uuid'} . '\');' });
				}
			}



			&subs::intelligent_automation_toggle({ appt_uuid => $app->{'uuid'}, app => $app->{'app'}, 'state' => 'off', timestamp => $app->{'timestamp'}, remote_address => $remote_address });
			my $sources = &subs::db_select('appointments', undef, { source_uuid => $app->{'uuid'} })->hashes;
			my $options = eval { return decode_json $appt->{'options'} } || [];
			my $model = eval { return decode_json $appt->{'model'} } || {};
			push @{$options}, $model if $model->{'uuid'};

			my %so_seen;
			foreach my $so ( @{$sources} ) {
				next if $so_seen{ $so->{'uuid'} }++;
				push @{$sources}, @{&subs::db_select('appointments', undef, { source_uuid => $so->{'uuid'} })->hashes};
				if ( $so->{'type'} eq 'start' ) {
					my $dur = $so->{'timestamp'} - $timestamp;


					my @current_option = grep { $_->{'name'} eq $so->{'app'} } @{$options};
					my $co = $current_option[0];
					my $so_data = {
						duration => $dur,
						server_time => $server_time,
					};
					my $ts = $timestamp;
					if ($co->{'delay_stop'}) {
						my $t = &subs::time_abbrev_translator($co->{'delay_stop'});
						$ts = $ts + $t;
						$dur = $dur + $t;
						$so_data->{'duration'} = $dur;
						$so_data->{'stop_timestamp'} = $ts;
					}
					$so_data = { stop_timestamp => $ts, duration => $dur, server_time => $server_time };
					if ($ts <= &subs::rightNow()) {
						$so_data->{'type'} = $app->{'type'};
						$so_data->{'stop_seen'} = 'yes';
						$so_data->{'stop_timestamp'} = $app->{'timestamp'}
					}

					&subs::db_update('appointments', $so_data, { source_uuid => $so->{'source_uuid'}, uuid => $so->{'uuid'}, app => $so->{'app'} });
					&budget_runner($so->{'app'});
					&subs::intelligent_automation_toggle({ appt_uuid => $so->{'uuid'}, app => $so->{'app'}, 'state' => 'off', timestamp => $ts, remote_address => $remote_address });
					&Websocket::send('tab', { console => 'appointmentDetailGrabber(\'' . $so->{'app'} . '\',\'' . $so->{'uuid'} .'\');'});
				}
			}
			&subs::db_update('appointments', { stop_timestamp => $app->{'timestamp'}, stop_seen => 'yes', duration => $app->{'duration'}, type => $app->{'type'}, server_time => &subs::rightNow() }, { uuid => $appt->{'uuid'}, app => $app->{'app'} });
		}
	}
	elsif ($app->{'type'} eq 'image' || $app->{'type'} eq 'video') {
		my $appt = &subs::db_query('select type,file,timestamp,uuid from appointments where app = ? and timestamp <= ? and (type=? or type=?)', $app->{'app'}, $app->{'timestamp'}, 'start', 'record')->hashes->[0];
		my $uuid = $appt->{'uuid'};
		if ($uuid) {
			$app->{'type'} = $appt->{'type'};
			$app->{'timestamp'} = $appt->{'timestamp'};
			$app->{'uuid'} = $uuid;
			my $file = eval { return decode_json $appt->{'file'} } || [];
			my $new_file = eval { return decode_json $app->{'file'} } || [];
			push @{$file}, @{$new_file};
			$app->{'file'} = encode_json $file;
			&subs::db_update('appointments', $app,
			{
				uuid => $uuid,
				app => $app->{'app'}
			});
		} else {
			&subs::db_insert('appointments', $app);
		}
	}
	else {
		if ($app->{'type'} eq 'start' || $app->{'type'} eq 'record') {
			&subs::intelligent_automation_toggle({ appt_uuid => $app->{'uuid'}, app => $app->{'app'}, 'state' => 'on', timestamp => $app->{'timestamp'}, remote_address => $remote_address });
			if ($app->{'stop_timestamp'}) {
				&subs::intelligent_automation_toggle({ appt_uuid => $app->{'uuid'}, app => $app->{'app'}, 'state' => 'off', timestamp => $app->{'stop_timestamp'}, remote_address => $remote_address });
			}

			if ($app->{'type'} eq 'record') {
				my $jdata;

				my $recording_type = &subs::setting_grabber({ app => $app->{'app'}, setting => 'record' }) || 'system';
				my $dat = { recorder => $recording_type };
				if ($recording_type eq 'video') {
					$app->{'seen'} = undef;
					#$dat->{'camera'} = $camera;
				}
				elsif ($recording_type eq 'audio') {
					$app->{'seen'} = undef;
				}
				elsif ($recording_type eq 'screen') {
					$app->{'seen'} = undef;
				}
				elsif ($recording_type eq 'video_front') {
				#	$dat->{'camera'} = $camera;
				}
				elsif ($recording_type eq 'security') {
					&record_video({ app => $app->{'app'}, uuid => $app->{'uuid'}, timestamp => $app->{'timestamp'} }) if $app->{'seen'} eq 'yes';
				}
				else {
					&record_audio({ app => $app->{'app'}, uuid => $app->{'uuid'}, timestamp => $app->{'timestamp'} }) if $app->{'seen'} eq 'yes';
				}
				$app->{'data'} = encode_json $dat;

			}
		}
		if ($db_written == 1) {
			&subs::db_update('appointments', $app, { app => $app->{'app'}, uuid => $app->{'uuid'} });
		} else {
			&subs::db_insert('appointments', $app);
		}
	}
	# An invoice gets its own receive address as soon as it is written, so a
	# print or a public page already names it. Idempotent: a re-save keeps the
	# address the invoice already owns.
	if (($app->{'type'} || '') eq 'invoice' && ($app->{'uuid'} || '') ne '') {
		my $wallet = &subs::crypto_invoice_wallet('BTC');
		&subs::crypto_invoice_address({ app => $wallet->{'app'}, invoice => $app->{'uuid'} }) if $wallet;
	}
	# a transaction with an account is a money move, so it is written to the
	# warehouse ledger too; the budget and the warehouse then read one store
	&warehouse_money_mirror($app);
	&Websocket::send('tab', { console => 'calculator();' });
	&Websocket::send('tab', { console => 'appointmentDetailGrabber("' . $app->{'app'} . '","' . $app->{'uuid'} .'");' });
	&Websocket::send('tab', { console => 'continent_record({\'uuid\':\'' . $app->{'uuid'} . '\', \'app\':\'' . $app->{'app'} .'\',\'purpose\':\'app\',\'timestamp\':\'' . $app->{'timestamp'} . '\',\'navigation\':"once" });' });
	my $cv = &centre_view_grabber({ c => $c, app => &subs::unformat_name($app->{'app'}), timestamp => &subs::rightNow(), cached => 'no' });
	&budget_runner($app->{'app'});
	# every run: a scope on the each_run cadence queues an evaluation as soon as it
	# has run, throttled by a Minion lock so a burst is one run, not many
	&subs::evaluation_run_trigger($app->{'app'}, $app);

	if (1 == 1 && $app->{'app'}) {
		my $params = Mojo::Parameters->new(%{$app});
		$params = $params->to_string;
		my $url = '/manager/appointment/writer';# . $params;
		#&subs::subprocessor(sub {
		#	&remote_relay_request($c, { dissemination => 'yes', url => $url, params => $app, type => 'post', override => 'manual' });
		#});
	}

	&subs::appointment_theme_push() if (($theme_movement // '') =~ /^(?:start|stop|record)$/);

	return $app;
}

post '/manager/appointment/writer' => sub ($c) {
	my $parameters = $c->req->body_params->to_hash;
	my $movement = $parameters->{'type'} || $parameters->{'movement'} || '';
	unless (&peer_action_gate($c, &subs::peer_movement_action($movement))) {
		return $c->rendered(403);
	}
	my $peer = &peer_row_for_request($c);
	if ($peer && !&subs::peer_rate_ok($peer, 'action')) {
		return $c->rendered(429);
	}
	&appointment_writer($c,$parameters);
	$c->render(json => $parameters);
};




get '/i18n/ui-*code' => sub ($c) {
	my $code = $c->param('code') // '';
	$code =~ s/\.js\z//;
	$code = &language::valid($code);
	$c->res->headers->content_type('application/javascript; charset=UTF-8');
	$c->res->headers->cache_control('no-cache');
	my $file = 'i18n/ui-' . $code . '.json';
	my $json = $code eq 'en' || !-e $file ? '{}' : read_file($file);
	$c->render(text => 'window.jawnos_ui_lang = ' . $json . ';');
};

get '/privacy' => sub ($c) {
	# A public page: the homepage and the store both link here, and a visitor
	# has not been given a session yet. The controller and contact come from the
	# house's own settings, so the notice names a real person and address.
	my $cfg = eval { &subs::config_reader() } || {};
	my $controller = &subs::setting_grabber({ app => 'me', setting => 'my_name' })
		|| &subs::setting_grabber({ app => 'me', setting => 'name' })
		|| $cfg->{'name'} || 'the house';
	my $contact = $cfg->{'email'} || &subs::setting_grabber({ app => 'me', setting => 'email' }) || '';
	my @now = localtime();
	my $updated = sprintf('%04d-%02d-%02d', $now[5] + 1900, $now[4] + 1, $now[3]);
	$c->render(
		template => 'privacy',
		layout => undef,
		controller => $controller,
		contact => $contact,
		updated => $updated,
		store_name => &subs::setting_grabber({ app => 'me', setting => 'store_name' }) || '',
		device => &subs::device_setter(),
		config => $cfg,
	);
};

my (@appointments,@results);
get '/' => sub ($c) {
	my $homepage;
	my $user_agent = $c->req->headers->user_agent;
	my $remote_signatorial = $c->param('signatorial');
	my $signatorial = &subs::signatorial_designer();
	if ($c->param('signatorial')) {
		my $rs = &subs::decrypter(&subs::shorthand_name(&subs::rightNow(), 5) . &subs::shorthand_name($signatorial, 5), $remote_signatorial);

		if ($rs eq $signatorial) {
			$homepage = $signatorial;
		} else {
			$homepage = 'dunno';
		}
	} else {
		$homepage = &homepage_maker($c);
	}
	$c->render('text' => $homepage);
};

get '/manager/home' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $homepage = &homepage_maker($c);
	$homepage = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'home', contents => $homepage }, $timestamp);
	$c->render('text' => $homepage);
};

sub homepage_maker($c) {
	my ($db,$database,$sql) = &subs::database_grabber();
	unless ($database) {
		$c->render(template => 'guest_layouts/denial');
	}
	my $articulation;
	my $port = $c->req->url->base->port;
	my $server_time = &subs::rightNow();
	my $name = &subs::setting_grabber({ app => 'me', setting => 'my_name' }) || 'Home';
	$articulation = &subs::db_query('select * from magazine where status=? and timestamp <= ? and warranty >= ? order by timestamp DESC','publish', $server_time, $server_time);
	my $magazine_categories = [];# = $mag_cat->hashes;
	my $articles = $articulation->hashes;
	foreach my $mc ( @{$articles} ) {
		unless ( grep { $_->{'app'} eq $mc->{'category'} } @{$magazine_categories}) {
			push @{$magazine_categories}, { app => $mc->{'category'} };
		}
	}
	if ($c->param('category')) {
		$articulation = &subs::db_query('select * from magazine where status=? and category=? and timestamp <= ? and warranty >= ? order by timestamp DESC','publish',$c->param('category'), $server_time, $server_time);
	}
	else {
		$articulation = &subs::db_query('select * from magazine where status=? and timestamp <= ? and warranty >= ? order by timestamp DESC','publish', $server_time, $server_time);
	}
	$articles = $articulation->hashes;
	foreach my $mc ( @{$articles} ) {
		$mc->{'public'} = &subs::setting_grabber({ app => &subs::unformat_name($mc->{'title'}), setting => 'public' });

	}
	my $ws_url = 'wss://' . $c->req->url->base->host . ':' . $ENV{PORT_MSG} . '/manager/ws';
	my $mail_ws_url = 'wss://' . $c->req->url->base->host . ':' . $ENV{PORT_MSG} . '/mail/ws';
	my $paperboy_url = 'wss://' . $c->req->url->base->host . ':' . $ENV{PORT_MSG} . '/observer/ws';
	my ($website,$header) = &website_preloader($c);
	my $my_name = $c->param('name') || &subs::setting_grabber({ app => 'me', setting => 'my_name' });
	my %data = (
		template => 'homepage',
		title => $name,
		articles => $articles,
		mail_ws_url => $mail_ws_url,
		paperboy_url => $paperboy_url,
		website => $website,
		header => $header,
		my_name => $my_name,
		magazine_categories => $magazine_categories,
		config => &subs::config_reader(),
		device => &subs::device_setter(),
		string => $random_caching_string,
		pseudonyms => &pseudonym_maker('manager',''),
		ws_url => $ws_url,
		advertise_watching => &subs::setting_grabber({ app => 'me', setting => 'advertise_watching' })
	);
	unless ($c->param('window_maker')) {
		$data{'layout'} = 'homepage';
	}
	my $homepage = $c->render_to_string(
		%data
	);
	return $homepage;
}

get '/manager/register_grabber' => sub($c) {
	my $app = $c->param('app');
	my $timestamp = $c->param('timestamp');
	my $returner = &register_grabber($app);
	$c->render(json => $returner);
};

sub register_grabber($app) {
	my $timestamp = &subs::rightNow();
	my $returner = { timestamp => $timestamp };
	my $c = &subs::controller_builder();
	foreach my $att ( qw/model option option_category subcategory/ ) {
		$returner->{'html'} .= $c->render_to_string(
			template => 'pos/attributes',
			att => $att,
			a => $app
		);
	}
	return $returner
}

get '/manager/measures' => sub($c) {
	my $timestamp = $c->param('timestamp');
	# the live rate snapshot fills the PV column without waiting for the half-hour
	eval { &subs::crypto_measures_sync(); };
	my $settings = &subs::settings_grabber({ app => 'measures' });
	my $measures = eval { return decode_json $settings->{'measures'} } || $gb::measures;
	if ( scalar keys %{$measures} == 0 ) { $measures = $gb::measures; }
	my $written = 0;
	foreach my $m ( keys %{$measures} ) {
		unless ($measures->{$m}->{'uuid'}) {
			$measures->{$m}->{'uuid'} = &subs::random_string_creator(25);
			delete $measures->{$m}->{'symbol'};
			$written = 1;
		}
	}
	if ($written == 1) {
		my $jmeasures = encode_json $measures;
		&subs::setting_setter({ app => 'measures', setting => 'measures', value => $jmeasures });
	}
	my $contents = $c->render_to_string(
		template => '/measures/measures',
		timestamp => $timestamp,
		settings => $settings,
		measures => $measures
	);
	my $window = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'measures', contents => $contents }, $timestamp);

	$c->render(json => { window => $window });
};

post '/manager/measures/assign' => sub($c) {
	my $mc_measure = $c->param('mc_measure');
	my $mc_app = $c->param('mc_app');
	my $ms_measure = $c->param('ms_measure');
	my $ms_uuid = $c->param('ms_uuid');
	my $ms_name = $c->param('ms_name');

	my $measures = eval { return decode_json &subs::setting_grabber({ app => 'measures', setting => 'measures' }) };
	foreach my $m ( grep { $_ eq $ms_measure } keys %{$measures} ) {
		if ($measures->{$m}->{'uuid'} eq $ms_uuid) {

			my $ameasure = eval { return decode_json &subs::setting_grabber({ app => $mc_app, setting => 'app_measures' }) };

			if ($ameasure->{$mc_measure}) {
				$measures->{$m}->{'app'} = &subs::unformat_name($mc_app);
				$measures->{$m}->{'app_measure'} = &subs::unformat_name($mc_measure);
				$measures->{$m}->{'pv'} = $ameasure->{$measures->{$m}->{'app_measure'}}->{'value'} if $ameasure->{$measures->{$m}->{'app_measure'}}->{'value'};
			}
		}
	}
	my $jmeasures = encode_json $measures;
	&subs::setting_setter({ app => 'measures', setting => 'measures', value => $jmeasures });

	$c->render(json => $measures);
};

post '/manager/measures/edit' => sub($c) {
	my $measure = eval { return decode_json $c->param('measure') } || {};
	my $measures = eval { return decode_json &subs::setting_grabber({ app => 'measures', setting => 'measures' }) };
	foreach my $t ( qw/formulas types/ ) {
 		my @t = $measure->{$t} ? split ',', $measure->{$t} : ();

		$measure->{$t} = \@t;
	}
	if ($measure->{'m'}) {
		if ($measure->{'uuid'} eq 'new') {
			$measure->{'uuid'} = &subs::random_string_creator(26);
			until ( !$measures->{$measure->{'m'}} ) {
				$measure->{'m'} = '_' . $measure->{'m'};
			}
			$measures->{$measure->{'m'}} = $measure;
		} else {

		}

		my $jmeasures = encode_json $measures;
		&subs::setting_setter({ app => 'measures', setting => 'measures', value => $jmeasures });
	}

	$c->render(json => $measure);
};

post '/manager/measures/delete' => sub($c) {
	my $uuid = $c->param('uuid');
	my $measures = eval { return decode_json &subs::setting_grabber({ app => 'measures', setting => 'measures' }) } || {};
	foreach my $m ( keys %{$measures} ) {
		if ($measures->{$m}->{'uuid'} eq $uuid) {
			delete $measures->{$m};
		}
	}

	my $jmeasures = encode_json $measures;
	&subs::setting_setter({ app => 'measures', setting => 'measures', value => $jmeasures });
	$c->render(json => { measures => $measures });

};

# --- Market: the shopping side of the warehouse ---
# A vendor is an app whose part of speech (or second reading) is 'vendor', the way
# packaging reads the places. The shopping list is one JSON setting on the market
# app: rows of { uuid, text, kind (need|want), vendor, timestamp }.
sub market_vendors {
	my $rows = &subs::db_query("select distinct(app) from settings where setting in ('pos','mab') and value = ? order by app", 'vendor')->hashes;
	return [ map { $_->{'app'} } @{$rows} ];
}
# The registry of named lists (Grocery, Hardware, Clothing, ...) with the vendors
# each is shopped at, so a vendor's location can name the lists that apply there.
# Names come from the house's categories, so a list lines up with the budget's
# category rather than inventing a parallel scheme.
sub market_lists {
	my $raw = &subs::setting_grabber({ app => 'market', setting => 'market_lists' });
	my $lists = eval { return decode_json $raw } || {};
	return ref $lists eq 'HASH' ? $lists : {};
}
# The lists the dropdown offers: every category the house keeps, plus any list
# already in use. A category app is a list by default, so the names line up with
# the budget's categories.
sub market_lists_for_menu {
	my $learned = &market_lists();
	my %menu = map { $_ => { name => ($learned->{$_}->{'name'} || &subs::format_name($_)) } } keys %{$learned};
	my $cats = &subs::db_query("select distinct(app) from settings where setting in ('pos','mab') and value = ?", 'category')->hashes;
	foreach my $c ( @{$cats} ) {
		my $app = $c->{'app'};
		$menu{$app} ||= { name => &subs::format_name($app) };
	}
	return \%menu;
}
sub market_list_key {
	my ($name) = @_;
	return '' unless defined $name && $name ne '';
	return &subs::unformat_name($name);
}
# Remember that a list is shopped at a vendor, so a vendor's location names it.
sub market_lists_touch_vendor {
	my ($key, $name, $vendor) = @_;
	return unless $key && $vendor;
	my $lists = &market_lists();
	$lists->{$key} ||= { name => ($name || $key), vendors => {} };
	$lists->{$key}->{'name'} = $name if $name;
	$lists->{$key}->{'vendors'} ||= {};
	$lists->{$key}->{'vendors'}->{$vendor} = 1;
	&subs::setting_setter({ app => 'market', setting => 'market_lists', value => encode_json($lists) });
}
# --- barcodes: look a code up once, then name it in our terms ---
# The cache is one setting: { code => { raw, item, category, unit, at } }, so a
# code is looked up and consolidated the first time and is instant after.
sub market_barcodes {
	my $raw = &subs::setting_grabber({ app => 'market', setting => 'barcodes' });
	my $c = eval { return decode_json $raw } || {};
	return ref $c eq 'HASH' ? $c : {};
}
sub market_barcode_remember {
	my ($code, $map) = @_;
	return unless $code && ref $map eq 'HASH';
	my $c = &market_barcodes();
	$map->{'at'} = &subs::rightNow();
	$c->{$code} = $map;
	&subs::setting_setter({ app => 'market', setting => 'barcodes', value => encode_json($c) });
}
# A code the house already knows: an item app carrying it as its product code.
sub market_barcode_house {
	my ($code) = @_;
	my $row = &subs::db_query("select app from settings where setting in ('barcode','product_code') and value = ? limit 1", $code)->hashes->[0];
	return $row ? $row->{'app'} : undef;
}
# Ask a public catalogue what a code is. Best-effort and only for a code never
# seen before: an ISBN goes to Open Library, a retail code to UPCitemdb, and a
# failure never stops the scan (the code itself is kept until it is named).
sub market_barcode_lookup {
	my ($code) = @_;
	return undef unless $code =~ /^[0-9]{8,14}$/;
	my $ua = Mojo::UserAgent->new(connect_timeout => 4, inactivity_timeout => 6, request_timeout => 8);
	my $url = ($code =~ /^97[89][0-9]{10}$/) ? 'https://openlibrary.org/isbn/' . $code . '.json'
		: 'https://api.upcitemdb.com/prod/trial/lookup?upc=' . $code;
	my $res = eval { $ua->get($url)->result };
	return undef unless $res && $res->is_success;
	my $d = eval { return decode_json $res->body } || {};
	return ($code =~ /^97[89]/) ? $d->{'title'} : $d->{'items'}->[0]->{'title'};
}
# Fold a raw retail name into our terms: a house item name, a category the house
# keeps and a unit. The model does the naming; the categories and units are ours.
sub market_barcode_consolidate {
	my ($raw) = @_;
	return { item => &subs::unformat_name($raw || ''), category => '', unit => '' } unless defined $raw && $raw ne '';
	my $cats = &subs::db_query("select distinct(app) from settings where setting in ('pos','mab') and value = ?", 'category')->hashes;
	my @cats = map { $_->{'app'} } @{$cats};
	my ($text) = &subs::ai_chat_role('chatbot_model', [
		{ role => 'system', content => 'You fold a shop product into JawnOS\'s own naming. Answer with strict JSON only.' },
		{ role => 'user', content => 'Product: "' . $raw . '"\nCategories we keep: ' . join(', ', @cats)
			. '\nReturn ONLY JSON: {"item":"a short house name, one or two words","category":"one of the categories above, or empty","unit":"the unit it is sold in: each, kg, g, L, mL, m, or empty"}.' },
	]);
	my ($json) = ($text || '') =~ /(\{.*\})/s;
	my $out = eval { return decode_json $json } || {};
	my $name = &subs::unformat_name($out->{'item'} || $raw);
	return { item => $name, category => ($out->{'category'} || ''), unit => ($out->{'unit'} || '') };
}
sub market_barcode_resolve {
	my ($code) = @_;
	return undef unless defined $code && $code =~ /\S/;
	my $cache = &market_barcodes();
	return $cache->{$code} if $cache->{$code} && $cache->{$code}->{'item'};
	my $house = &market_barcode_house($code);
	my $map;
	if ($house) {
		$map = { item => $house, category => '', unit => '', raw => $house };
	}
	else {
		my $raw = &market_barcode_lookup($code);
		$map = &market_barcode_consolidate($raw);
		$map->{'raw'} = $raw if defined $raw && $raw ne '';
	}
	&market_barcode_remember($code, $map);
	return $map;
}

# The newest GPS fix the house holds (the phone writes continent rows), or nothing.
sub market_here {
	my $row = &subs::db_query("select latitude, longitude from continent where latitude is not null and latitude != '' order by cast(timestamp as integer) desc limit 1")->hashes->[0];
	return ($row && $row->{'latitude'} && $row->{'longitude'}) ? { latitude => $row->{'latitude'} + 0, longitude => $row->{'longitude'} + 0 } : undef;
}
# A vendor's own home plate, if it has one.
sub market_vendor_place {
	my ($vendor) = @_;
	return undef unless $vendor;
	my $hp = eval { return decode_json &subs::setting_grabber({ app => $vendor, setting => 'home_plate' }) } || {};
	return ($hp->{'latitude'} && $hp->{'longitude'}) ? { latitude => $hp->{'latitude'} + 0, longitude => $hp->{'longitude'} + 0 } : undef;
}
# The lists that apply where the house is now: a list whose vendors include one
# within the radius. At a supermarket that is the grocery list; at a big-box store
# several lists can be in range at once.
sub market_nearby_lists {
	my $here = &market_here();
	return [] unless $here;
	my $lists = &market_lists();
	my @near;
	foreach my $key ( sort keys %{$lists} ) {
		my $vendors = $lists->{$key}->{'vendors'} || {};
		foreach my $v ( sort keys %{$vendors} ) {
			my $place = &market_vendor_place($v);
			next unless $place;
			my $km = &help_distance_km($here->{'latitude'}, $here->{'longitude'}, $place->{'latitude'}, $place->{'longitude'});
			next unless defined $km && $km <= 0.3;
			push @near, { key => $key, name => ($lists->{$key}->{'name'} || $key), vendor => $v, distance_km => sprintf('%.3f', $km) };
			last;
		}
	}
	return \@near;
}

sub market_list {
	my $raw = &subs::setting_grabber({ app => 'market', setting => 'shopping_list' });
	my $list = eval { return decode_json $raw } || [];
	return [ grep { ref $_ eq 'HASH' && ($_->{'text'} || '') ne '' } @{$list} ];
}
sub market_save_list {
	my ($list) = @_;
	&subs::setting_setter({ app => 'market', setting => 'shopping_list', value => encode_json($list) });
	&Websocket::send('tab', { console => 'marketReload();' });
}
# Upgrade a matching list row to a need: what the warehouse asks, and what the
# sweep does on open.
sub market_upgrade_need {
	my ($text) = @_;
	return 0 unless defined $text && $text ne '';
	my $want = &subs::unformat_name($text);
	my $key = lc $text;
	my $list = &market_list();
	my $upgraded = 0;
	foreach my $it ( @{$list} ) {
		next unless lc($it->{'text'} || '') eq $key || &subs::unformat_name($it->{'text'} || '') eq $want;
		if (($it->{'kind'} || '') ne 'need') { $it->{'kind'} = 'need'; $upgraded++; }
	}
	&market_save_list($list) if $upgraded;
	return $upgraded;
}
# An item on the list the warehouse says is due: its own app's fixed-level quantity
# budget (6quantity) names the target, and on-hand below it is due.
sub market_item_due {
	my ($text) = @_;
	return 0 unless defined $text && $text ne '';
	my $item = &subs::unformat_name($text);
	my $b = eval { &Manager::budget_calculator({ app => $item, circumstance => 'quantity' }) };
	return 0 unless $b && $b->{'fixed'} && ($b->{'circumstance'} || '') eq 'quantity' && defined $b->{'budgeted'} && $b->{'budgeted'} ne '';
	return (($b->{'value'} || 0) < ($b->{'budgeted'} || 0)) ? 1 : 0;
}
# Every due row becomes a need: the list keeps its own books in step with the
# shelf without the warehouse reaching in.
sub market_sweep_needs {
	my $list = &market_list();
	my $upgraded = 0;
	foreach my $it ( @{$list} ) {
		next unless &market_item_due($it->{'text'});
		if (($it->{'kind'} || '') ne 'need') { $it->{'kind'} = 'need'; $upgraded++; }
	}
	&market_save_list($list) if $upgraded;
	return $upgraded;
}

sub market_maker {
	my ($c) = @_;
	my $vendor = &subs::unformat_name($c->param('vendor')) || '';
	my $list = &market_list();
	foreach my $it ( @{$list} ) {
		$it->{'due'} = &market_item_due($it->{'text'});
	}
	my $nearby = &market_nearby_lists();
	return $c->render_to_string(
		template => 'market/market',
		list => $list,
		vendors => &market_vendors(),
		vendor => $vendor,
		lists => &market_lists_for_menu(),
		nearby => $nearby,
		receipts => &market_receipts_prepared(),
		scan_feeds => &market_scan_feeds()
	);
}

get '/manager/market' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $contents = &market_maker($c);
	my $window = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'market', contents => $contents }, $timestamp);
	$c->render(json => { window => $window, html => $contents });
};

post '/manager/market/item_add' => sub($c) {
	my $text = $c->param('text') || '';
	$text =~ s/^\s+|\s+$//g;
	my $list_name = $c->param('list') || '';
	my $list_key = &market_list_key($list_name);
	my $vendor = &subs::unformat_name($c->param('vendor')) || '';
	return $c->render(json => { error => 'empty' }) unless $text ne '';
	my $list = &market_list();
	my $item = {
		uuid => &subs::random_string_creator(21),
		text => $text,
		kind => &market_item_due($text) ? 'need' : 'want',
		vendor => $vendor,
		list => $list_key,
		timestamp => &subs::rightNow(),
	};
	unshift @{$list}, $item;
	&market_save_list($list);
	&market_lists_touch_vendor($list_key, &subs::format_name($list_name), $vendor) if $list_key && $vendor;
	$c->render(json => { item => $item });
};

post '/manager/market/item_kind' => sub($c) {
	my $uuid = $c->param('uuid');
	my $kind = ($c->param('kind') || '') eq 'need' ? 'need' : 'want';
	my $list = &market_list();
	my $found;
	foreach my $it ( @{$list} ) {
		if (($it->{'uuid'} || '') eq $uuid) { $it->{'kind'} = $kind; $found = 1; }
	}
	&market_save_list($list) if $found;
	$c->render(json => { uuid => $uuid, kind => $kind });
};

post '/manager/market/item_delete' => sub($c) {
	my $uuid = $c->param('uuid');
	my $list = &market_list();
	my @kept = grep { ($_->{'uuid'} || '') ne $uuid } @{$list};
	&market_save_list(\@kept);
	$c->render(json => { uuid => $uuid });
};

# Tick an item off (pick) or drop it in the cart. Checkout turns the cart into
# purchases - each on the item's own app, so a house item app is born here - and
# Cancel just empties the cart back onto the list.
post '/manager/market/item_flag' => sub($c) {
	my $uuid = $c->param('uuid');
	my $is_cart = ($c->param('flag') || '') eq 'cart' ? 1 : 0;
	my $on = $c->param('on') ? 1 : 0;
	my $key = $is_cart ? 'cart' : 'picked';
	my $list = &market_list();
	my $found;
	foreach my $it ( @{$list} ) {
		next unless ($it->{'uuid'} || '') eq $uuid;
		if ($on) { $it->{$key} = 1; } else { delete $it->{$key}; }
		$found = 1;
	}
	&market_save_list($list) if $found;
	$c->render(json => { uuid => $uuid, flag => $key, on => $on });
};

post '/manager/market/cancel' => sub($c) {
	my $list = &market_list();
	foreach my $it ( @{$list} ) { delete $it->{'cart'}; }
	&market_save_list($list);
	$c->render(json => { ok => 1 });
};

post '/manager/market/checkout' => sub($c) {
	my $vendor_default = &subs::unformat_name($c->param('vendor')) || '';
	my $list = &market_list();
	# The cart leaves the list here, but nothing is written to the warehouse: the
	# transaction form opens filled with these lines and its Save records them,
	# so the quantity and the packaging are what the person actually bought.
	my @kept = grep { !$_->{'cart'} } @{$list};
	&market_save_list(\@kept);
	# The money side: one expense transaction on the list's category, handed to
	# the person to check and save. Each line carries record_item, so saving it
	# writes the purchase (and its stock move) with the edited quantity/unit.
	my $category = &market_list_key($c->param('list') || '');
	my (@lines, $total, $account, $vendor);
	foreach my $it ( @{$list} ) {
		next unless $it->{'cart'};
		$category = $it->{'list'} if $category eq '' && ($it->{'list'} || '') ne '';
		$account = $it->{'account'} if !$account && ($it->{'account'} || '') ne '';
		$vendor = $it->{'vendor'} if !$vendor && ($it->{'vendor'} || '') ne '';
		my $qty = ($it->{'quantity'} || 1) + 0;
		my $price = ($it->{'price'} || 0) + 0;
		$total += $price;
		push @lines, {
			uuid => &subs::random_string_creator(12),
			item => &subs::format_name($it->{'text'}),
			quantity => $qty,
			amount => $price,
			tax => 0,
			aux => 0,
			total => $price,
			unit => ($it->{'unit'} || 'each'),
			state => 'delivered',
			record_item => 'on',
		};
	}
	$vendor ||= $vendor_default;
	$category ||= &subs::unformat_name($lines[0]->{'item'}) if scalar @lines;
	$account ||= 'cash';
	my $storage;
	if (scalar @lines) {
		my %mov;
		foreach my $l ( @lines ) {
			$mov{ $l->{'uuid'} } = {
				item => $l->{'item'}, quantity => $l->{'quantity'},
				amount => $l->{'amount'}, tax => $l->{'tax'},
				aux => $l->{'aux'}, total => $l->{'total'},
				unit => $l->{'unit'}, state => $l->{'state'},
				record_item => 'on'
			};
		}
		$mov{'totals'} = { uuid => $lines[0]->{'uuid'}, vendor => $vendor, information => 'none', amount => $total, tax => 0, aux => 0, total => $total };
		$storage = { expense => \%mov };
	}
	$c->render(json => {
		items => scalar @lines,
		transaction => { app => $category, account => $account, vendor => $vendor, total => $total, storage => $storage },
	});
};

# The account apps: an app whose pos or mab is 'account' (the same discovery the
# transaction form and the budget use).
sub market_accounts {
	my $rows = &subs::db_query("select distinct(app) from settings where setting in ('pos','mab') and value = ? order by app", 'account')->hashes;
	return [ map { { app => $_->{'app'}, name => &subs::format_name($_->{'app'}) } } @{$rows} ];
}

# Every unit a transaction can name: the built-in measures plus the ones the
# Measures app has saved, so a packaging named on the spot is offered next time.
sub measures_all {
	my $stored = eval { return decode_json &subs::setting_grabber({ app => 'measures', setting => 'measures' }) } || {};
	my %all = (%{$gb::measures}, %{$stored});
	# The house keeps its own copy of the built-in units, so a formula seeded
	# with a typo shadowed every later correction in gb.pl (one litre was a
	# hundred millilitres, one gram a ten-thousandth of a kilogram). Repair only
	# the exact old strings, and lift the misspelled `fomulas` list, so a formula
	# a person has edited is left alone.
	my %fix = (
		'm' => { 'x * .0001km' => 'x * .001km' },
		'mi' => { 'x * 1689.344m' => 'x * 1609.344m' },
		'L' => { 'x * 100mL' => 'x * 1000mL' },
		'g' => { 'x * .0001kg' => 'x * .001kg' },
		'mg' => { 'x * .0001g' => 'x * .001g' },
		'tsp' => { 'x * .667oz' => 'x * .16667oz', 'x * .0625cup' => 'x * .02083333cup' },
		'oz' => {},
	);
	foreach my $k ( keys %fix ) {
		next unless ref $all{$k} eq 'HASH';
		if ( ref $all{$k}->{'fomulas'} eq 'ARRAY' && ref $all{$k}->{'formulas'} ne 'ARRAY' ) {
			$all{$k}->{'formulas'} = delete $all{$k}->{'fomulas'};
		}
		my $fs = $all{$k}->{'formulas'};
		next unless ref $fs eq 'ARRAY' && scalar keys %{ $fix{$k} };
		$all{$k}->{'formulas'} = [ map { defined $fix{$k}->{$_} ? $fix{$k}->{$_} : $_ } @{$fs} ];
	}
	foreach my $k ( keys %all ) {
		next unless ref $all{$k} eq 'HASH';
		$all{$k}->{'name'} = $k unless defined $all{$k}->{'name'} && $all{$k}->{'name'} ne '';
	}
	return \%all;
}

# Add a packaging/unit from the form that needs it. The new measure is saved so
# the picker offers it next time, and when the item is known the packaging is
# recorded on the item too (its `each` is what a restock plan counts).
post '/manager/market/packaging_add' => sub($c) {
	my $name = $c->param('name') || '';
	$name =~ s/^\s+|\s+$//g;
	return $c->render(json => { error => 'name the packaging' }) unless $name =~ /\S/;
	my $each = ($c->param('each') || '') =~ /[0-9]/ ? 0 + $c->param('each') : 1;
	my $key = &subs::unformat_name($name);
	$key = 'pack' unless length $key;
	my $measures = &measures_all();
	my $uuid;
	my $exists = 0;
	foreach my $k ( keys %{$measures} ) {
		next unless lc($k) eq $key || lc($measures->{$k}->{'name'} || '') eq lc($name);
		$uuid = $measures->{$k}->{'uuid'};
		$key = $k;
		$exists = 1;
		last;
	}
	my $stored = eval { return decode_json &subs::setting_grabber({ app => 'measures', setting => 'measures' }) } || {};
	unless ($exists) {
		$uuid = &subs::random_string_creator(26);
		$stored->{$key} = { %{ $gb::measures->{$key} || {} }, %{ $stored->{$key} || {} }, uuid => $uuid, name => $name };
		&subs::setting_setter({ app => 'measures', setting => 'measures', value => encode_json($stored) });
	}
	elsif (!$uuid) {
		$uuid = &subs::random_string_creator(26);
		$stored->{$key} = { %{ $gb::measures->{$key} || {} }, %{ $stored->{$key} || {} }, uuid => $uuid };
		&subs::setting_setter({ app => 'measures', setting => 'measures', value => encode_json($stored) });
	}
	my $item = &subs::unformat_name($c->param('item'));
	if ($item ne '') {
		my $packaging = eval { return decode_json &subs::setting_grabber({ app => $item, setting => 'packaging' }) } || {};
		$packaging->{$uuid} = { uuid => $uuid, name => $name, quantity => $each };
		&subs::setting_setter({ app => $item, setting => 'packaging', value => encode_json($packaging) });
	}
	$c->render(json => { unit => $key, name => &subs::format_name($name), uuid => $uuid, each => $each });
};

# The families a printed tender may name. A receipt that says "credit" can name a
# mastercard account, and "interac" a debit one, so a family with ONE account in
# it is enough to pick that account; an ambiguous family is left for the person.
my %market_payment_family = (
	cash => [ qw(cash) ],
	debit => [ qw(debit interac maestro) ],
	credit => [ qw(credit visa mastercard amex discover) ],
	crypto => [ qw(crypto bitcoin ethereum btc eth) ],
	cheque => [ qw(cheque check) ],
	gift => [ qw(gift) ],
);

# Guess which account a printed tender names. An exact word always wins (a
# mastercard account for a mastercard receipt); with no exact word, a family with
# a single account takes it (a receipt saying "credit" selects the only credit
# account, which may be a mastercard; "debit" selects the only interac one).
sub market_payment_account {
	my ($method) = @_;
	my $want = lc($method || '');
	$want =~ s/[^a-z0-9 ]//g;
	$want =~ s/^\s+|\s+$//g;
	return '' unless $want ne '';
	my $rows = &subs::db_query("select app, value from settings where setting = 'payment_type' and value is not null and value != ''")->hashes;
	my ($best, $best_len) = ('', 0);
	my %family_of;
	foreach my $r ( @{$rows} ) {
		my $t = lc($r->{'value'} || '');
		$t =~ s/[^a-z0-9 ]//g;
		$t =~ s/^\s+|\s+$//g;
		next unless $t ne '';
		my $fam = '';
		foreach my $f ( keys %market_payment_family ) {
			if (grep { $_ eq $t } @{ $market_payment_family{$f} }) { $fam = $f; last; }
		}
		$fam = $t unless $fam ne '';
		push @{ $family_of{$fam} }, { app => $r->{'app'}, type => $t };
		if (length($t) >= 3 && ($want eq $t || $want =~ /\b\Q$t\E\b/)) {
			if (length($t) > $best_len) { $best = $r->{'app'}; $best_len = length($t); }
		}
	}
	return $best if $best ne '';
	foreach my $fam ( sort keys %family_of ) {
		my @acc = @{ $family_of{$fam} };
		next unless scalar @acc == 1;
		my @words = @{ $market_payment_family{$fam} || [ $fam ] };
		foreach my $w ( @words ) {
			return $acc[0]->{'app'} if $want eq $w || $want =~ /\b\Q$w\E\b/;
		}
		return $acc[0]->{'app'} if $want =~ /\b\Q$fam\E\b/;
	}
	return '';
}

# The tabs in the house that can take a photo, so a computer can hand a barcode
# scan to a phone. A tab is a live `server` websocket row; its device type comes
# from the browser's user agent and the capability table says whether that type
# has a camera. The caller's own tab is left out (it is the one asking).
get '/manager/market/cameras' => sub($c) {
# a peer asks for this machine's own tabs; a person also gets the peers' tabs.
	# The local AJAX helper appends this machine's own signatorial to every request,
	# so the peer flag is what marks a real peer call (a bare signatorial was being
	# mistaken for one and answered 403).
	my $from_peer = ($c->param('peer') || '') eq 'yes';
	if ($from_peer) {
		my $peer_sig = $c->param('signatorial') || '';
		my $rm = ($peer_sig && &subs::db_select('remote_machines', undef, { signatorial => $peer_sig })->hashes->[0]);
		return $c->rendered(403) unless $rm && &subs::peer_verify($c, $rm);
	}
	my $me = $c->param('browser_tab_id') || '';
	my $since = &subs::rightNow() - 5000;
	my $rows = &subs::db_query("select browser_tab_id, user_agent, room, server_time from websockets where ( app = ? or app like ? ) and type = ? and server_time >= ? order by server_time desc", 'server', 'server@%', 'stayingAlive', $since)->hashes;
	my (%seen, @devices);
	foreach my $r ( @{$rows} ) {
		my $bti = $r->{'browser_tab_id'} || '';
		next unless $bti ne '' && $bti ne $me;
		next if $seen{$bti}++;
		my $type = &market_client_type($r->{'user_agent'});
		next unless scalar @{ $gb::capabilities->{$type}->{'camera'} || [] };
		my $label = ($r->{'room'} && $r->{'room'} ne '') ? &subs::format_name($r->{'room'}) : ($type eq 'mobile' ? 'Phone' : 'Computer');
		push @devices, { browser_tab_id => $bti, label => $label, type => $type, room => ($r->{'room'} || '') };
	}
	$c->render(json => { devices => \@devices }) if $from_peer;
	return if $from_peer;
	# A phone browsing its own jawn is a peer, not a local tab: ask each peer in
	# PARALLEL for the camera tabs it holds, with a short leash so a sleeping peer
	# cannot hold the chooser (sequential calls took long enough that Scan fell
	# back to the typed prompt).
	my @peers = grep { $_->{'manager'} } @{ &subs::db_select('remote_machines')->hashes };
	unless (scalar @peers) { $c->render(json => { devices => \@devices }); return; }
	my @promises;
	my @merged;
	my @peer_notes;
	my @uas;
	foreach my $rm ( @peers ) {
		my $peer = &remote_useragent_maker({ rm => $rm });
		my $ua = $peer->{'ua'};
		unless ($ua) {
			$ua = Mojo::UserAgent->new();
			$ua->on(start => sub { my ($ua, $tx) = @_; &subs::peer_sign_request($tx->req); });
		}
		$ua = $ua->insecure(1)->connect_timeout(2)->inactivity_timeout(4)->request_timeout(6);
		push @uas, $ua;
		my $url = ($peer->{'manager'} || $rm->{'manager'}) . '/manager/market/cameras?peer=yes&signatorial=' . &subs::signatorial_designer();
		my $m = $rm->{'ip'} || $rm->{'hostname'} || 'peer';
		(my $short = $m) =~ s/\.jonathanferwerda\.com$//;
		push @promises, $ua->get_p($url)->then(sub {
			my ($tx) = @_;
			my $keep_agent = $ua;  # the agent must outlive this promise
			my $res = $tx->result;
			unless ($res && $res->is_success) {
				push @peer_notes, { machine => $short, status => ($res ? $res->code : 'none'), error => ($tx->error ? ($tx->error->{'message'} || '') : '') };
				return;
			}
			my $data = eval { decode_json $res->body } || {};
			push @peer_notes, { machine => $short, status => $res->code, devices => scalar @{ $data->{'devices'} || [] } };
			foreach my $d ( @{ $data->{'devices'} || [] } ) {
				next unless ref $d eq 'HASH' && ($d->{'browser_tab_id'} || '') ne '';
				push @merged, { %$d, label => ($d->{'label'} || 'Device') . ' (' . $short . ')', machine => $m };
			}
		})->catch(sub { undef });
	}
	Mojo::Promise->all(@promises)->then(sub {
		push @devices, @merged;
		$c->render(json => { devices => \@devices, peers => \@peer_notes });
	})->catch(sub {
		push @devices, @merged;
		$c->render(json => { devices => \@devices, peers => \@peer_notes });
	});
	$c->render_later;
	&subs::request_busy_release($c);
};

# The device type a browser's user agent names. Only the types the capability
# table knows are returned; anything else is a computer (the house's default).
sub market_client_type {
	my ($ua) = @_;
	my $t = lc($ua || '');
	return 'mobile' if $t =~ /android|iphone|ipad|ipod|mobile/;
	return 'computer';
}

# Hand a barcode scan to another tab: it opens its camera over the whole screen,
# reads the first code it sees, restores the page and posts it, so the lookup is
# the same one a scan on this machine would do.
post '/manager/market/scan/remote' => sub($c) {
	# a peer may relay a scan to one of this machine's tabs (see the cameras route
	# for why the peer flag, not the signatorial alone, marks it)
	my $from_peer = ($c->param('peer') || '') eq 'yes';
	if ($from_peer) {
		my $peer_sig = $c->param('signatorial') || '';
		my $rm = ($peer_sig && &subs::db_select('remote_machines', undef, { signatorial => $peer_sig })->hashes->[0]);
		return $c->rendered(403) unless $rm && &subs::peer_verify($c, $rm);
	}
	my $bti = $c->param('browser_tab_id') || '';
	return $c->render(json => { error => 'no device' }) unless $bti =~ /\S/;
	my %pass = (
		session => ($c->param('session') || ''),
		device_id => ($c->param('device_id') || ''),
		origin_machine => ($c->param('origin_machine') || ''),
		list => ($c->param('list') || ''),
		vendor => ($c->param('vendor') || ''),
		rapid => ($c->param('rapid') || ''),
		origin_tab => ($c->param('origin_tab') || ''),
		origin_name => ($c->param('origin_name') || ''),
		stop => ($c->param('stop') || ''),
	);
	# a person picked a tab on a peer: hand the job to that peer's own manager
	my $machine = $c->param('machine') || '';
	if (!$from_peer && $machine ne '') {
		my $rm = &subs::db_select('remote_machines', undef, { ip => $machine })->hashes->[0]
			|| &subs::db_select('remote_machines', undef, { hostname => $machine })->hashes->[0];
		return $c->render(json => { error => 'no such machine' }) unless $rm;
		my $peer = &remote_useragent_maker({ rm => $rm });
		my $ua = $peer->{'ua'};
		unless ($ua) {
			$ua = Mojo::UserAgent->new();
			$ua->on(start => sub { my ($ua, $tx) = @_; &subs::peer_sign_request($tx->req); });
		}
		$ua = $ua->insecure(1)->connect_timeout(2)->inactivity_timeout(4)->request_timeout(6);
		my $url = ($peer->{'manager'} || $rm->{'manager'}) . '/manager/market/scan/remote?peer=yes&signatorial=' . &subs::signatorial_designer();
		my $res = eval { $ua->post($url => form => { %pass, browser_tab_id => $bti, timestamp => &subs::rightNow() })->result };
		return $c->render(json => $res && $res->is_success ? { ok => 1, machine => $machine } : { ok => 0, error => ($res ? ('the peer answered ' . $res->code) : 'the peer did not answer') });
	}
	my $opts = {
		session => $pass{'session'},
		device_id => $pass{'device_id'},
		origin_machine => $pass{'origin_machine'},
		list => $pass{'list'},
		vendor => $pass{'vendor'},
		rapid => 1,
		origin_tab => $pass{'origin_tab'},
	};
	if ($opts->{'origin_tab'} ne '') {
		my $row = &subs::db_select('websockets', undef, { browser_tab_id => $opts->{'origin_tab'}, app => 'server' })->hashes->[0];
		$opts->{'origin_name'} = $row ? ($row->{'room'} || '') : '';
	}
	&Websocket::send('server', {
		console => ($pass{'stop'} ? 'marketPhoneScanStop();' : 'marketPhoneCamera(' . encode_json($opts) . ');'),
		destination => $bti,
		timestamp => $c->param('timestamp') || &subs::rightNow()
	});
	# the page may be paused behind the phone's scan sheet: reach the bridge
	# natively so the sheet comes down even when JS cannot run
	&market_scan_native_stop() if $pass{'stop'};
	$c->render(json => { ok => 1, device => $bti });
};

# --- a scan session: a rapid-fire run of codes a person confirms at the end ---
# The machine that pressed Scan owns the list and the session. A phone on its own
# jawn forwards each code to it over the peer rail; Done puts the collected items
# on the list, Cancel throws them away and stops the phone's scanner.

sub market_scan_session {
	my $raw = &subs::setting_grabber({ app => 'market', setting => 'scan_session' });
	my $s = eval { return decode_json $raw } || {};
	return ref $s eq 'HASH' ? $s : {};
}

sub market_scan_session_save {
	my ($s) = @_;
	&subs::setting_setter({ app => 'market', setting => 'scan_session', value => encode_json($s) });
}

# A run can have several inputs at once (the computer's webcam and two phones,
# say). Each has a stable id so the page can add, replace or stop one without
# disturbing the others.
sub market_scan_device_id {
	my ($d) = @_;
	return '' unless ref $d eq 'HASH';
	return 'local' unless ($d->{'kind'} || '') eq 'remote';
	return ($d->{'machine'} || '') . '|' . ($d->{'browser_tab_id'} || '');
}

sub market_scan_session_devices {
	my ($s) = @_;
	my @d = grep { ref $_ eq 'HASH' && &market_scan_device_id($_) ne '' } @{ $s->{'devices'} || [] };
	@d = ($s->{'device'}) if !scalar @d && ref $s->{'device'} eq 'HASH' && &market_scan_device_id($s->{'device'}) ne '';
	return @d;
}

# One resolved code into a session. The phone's relay and this machine's own
# webcam reader both come through here, so a product is looked up in our terms
# once and lands in the run the same way.
sub market_scan_session_add {
	my ($s, $code) = @_;
	$code = '' unless defined $code;
	$code =~ s/\s+//g;
	return undef unless $code =~ /\S/;
	my $map = &market_barcode_resolve($code);
	my $item = $map->{'item'} || $code;
	my $it = {
		code => $code,
		item => $item,
		raw => ($map->{'raw'} || ''),
		category => ($map->{'category'} || ''),
		unit => ($map->{'unit'} || ''),
		at => &subs::rightNow(),
	};
	push @{ $s->{'items'} }, $it;
	&market_scan_session_save($s);
	return $it;
}

# The computer's own webcam, read by zbar. A session on this machine watches the
# camera in the background; each poll folds the codes the reader printed since the
# last one into the run. A phone has its own scanner, and a server has neither.
sub market_camera_dir { return '/tmp/jawn_market_camera'; }

sub market_camera_available {
	return 0 unless &subs::device_setter() eq 'computer';
	return 0 unless grep { $_ eq 'webcam' } @{ $gb::capabilities->{'computer'}->{'camera'} || [] };
	return 0 unless -e '/dev/video0';
	my $which = `command -v zbarcam 2>/dev/null`;
	return ($which =~ /\S/) ? 1 : 0;
}

sub market_camera_stop {
	my $pidfile = &market_camera_dir() . '/pid';
	return 0 unless -e $pidfile;
	open my $pf, '<', $pidfile or return 0;
	my $pid = <$pf>;
	close $pf;
	unlink $pidfile;
	return 0 unless $pid && $pid =~ /^([0-9]+)/;
	$pid = $1;
	return 0 unless &market_camera_is_reader($pid);
	kill('TERM', $pid);
	return 1;
}

# A reused pid must not be taken for our reader.
sub market_camera_is_reader {
	my ($pid) = @_;
	open my $cf, '<', "/proc/$pid/cmdline" or return 0;
	local $/;
	my $cmd = <$cf>;
	close $cf;
	return ($cmd && $cmd =~ /zbarcam/) ? 1 : 0;
}

# Is the reader this machine started still running?
sub market_camera_alive {
	my $pidfile = &market_camera_dir() . '/pid';
	return 0 unless -e $pidfile;
	open my $pf, '<', $pidfile or return 0;
	my $pid = <$pf>;
	close $pf;
	return ($pid && $pid =~ /^([0-9]+)/ && &market_camera_is_reader($1) && kill(0, $1)) ? 1 : 0;
}

# Start the reader for a fresh run: one zbarcam on the machine, writing each code
# it reads as a line, detached so the request can return at once.
sub market_camera_start {
	&market_camera_stop();
	my $dir = &market_camera_dir();
	`mkdir -p $dir` unless -e $dir;
	return 0 unless -d $dir;
	open my $codes, '>', $dir . '/codes'; close $codes;
	open my $log, '>', $dir . '/log'; close $log;
	my $pid = fork();
	return 0 unless defined $pid;
	if ($pid == 0) {
		eval { POSIX::setsid(); };
		$^F = 2;  # do not leak the manager's sockets into the reader
		open STDOUT, '>>', $dir . '/codes';
		open STDERR, '>>', $dir . '/log';
		exec('zbarcam', '--raw', '--nodisplay', '/dev/video0');
		exit 0;
	}
	open my $pf, '>', $dir . '/pid';
	print $pf $pid;
	close $pf;
	return $pid;
}

# Fold the lines the reader printed since the last poll into the session. zbar
# repeats a code while it stays in view, so the same read is ignored for a few
# seconds; a new item is taken at once.
sub market_camera_ingest {
	my ($s) = @_;
	return 0 unless ($s->{'camera'} || 0);
	# a run that was closed, or left open far too long, gives the camera back
	if (($s->{'status'} || '') ne 'scanning' || (($s->{'at'} || 0) + 0 > 0 && time - $s->{'at'} > 1800)) {
		&market_camera_stop();
		return 0;
	}
	my $file = &market_camera_dir() . '/codes';
	return 0 unless -e $file;
	my $offset = ($s->{'camera_offset'} || 0) + 0;
	my $size = -s $file;
	$offset = 0 if $size < $offset;
	open my $fh, '<', $file or return 0;
	seek($fh, $offset, 0);
	my @codes;
	while (my $line = <$fh>) {
		chomp $line;
		$line =~ s/^\s+|\s+$//g;
		next unless $line ne '';
		push @codes, $line;
	}
	my $new_offset = tell($fh);
	close $fh;
	$s->{'camera_offset'} = $new_offset;
	my $now = time;
	my $added = 0;
	foreach my $code ( @codes ) {
		if (($s->{'camera_last_code'} || '') eq $code && ($now - ($s->{'camera_last_at'} || 0)) < 5) { next; }
		$s->{'camera_last_code'} = $code;
		$s->{'camera_last_at'} = $now;
		&market_scan_session_add($s, $code);
		$added++;
	}
	&market_scan_session_save($s) if $new_offset != $offset || $added;
	return $added;
}

# Ask the Android app to put its scanner away. The page is paused behind Google's
# scan sheet, so the JS cannot do it; a broadcast reaches the bridge natively and
# it clears the sheet off the task.
sub market_scan_native_stop {
	return 0 unless &subs::device_setter() eq 'mobile';
	my $pid = fork();
	return 0 unless defined $pid;
	if ($pid == 0) {
		$^F = 2;
		open STDOUT, '>', '/dev/null';
		open STDERR, '>', '/dev/null';
		exec('am', 'broadcast', '-a', 'com.termux.app.SCAN_STOP', '-p', 'com.termux');
		exit 0;
	}
	return 1;
}

# What the session page shows: the raw names stay in the record, the printed ones
# are formatted here so no caller has to remember to unformat an app name.
sub market_scan_session_view {
	my ($s) = @_;
	my @items;
	foreach my $it ( @{ $s->{'items'} || [] } ) {
		next unless ref $it eq 'HASH';
		push @items, {
			%$it,
			formatted => &subs::format_name($it->{'item'} || ''),
			raw_formatted => &subs::format_name($it->{'raw'} || ''),
		};
	}
	my @devices;
	foreach my $d ( &market_scan_session_devices($s) ) {
		push @devices, {
			id => &market_scan_device_id($d),
			kind => ($d->{'kind'} || 'local'),
			label => ($d->{'label'} || (($d->{'kind'} || '') eq 'remote' ? 'Device' : 'this machine')),
			machine => ($d->{'machine'} || ''),
			browser_tab_id => ($d->{'browser_tab_id'} || ''),
		};
	}
	return {
		uuid => ($s->{'uuid'} || ''),
		status => ($s->{'status'} || ''),
		device => ($s->{'device'} || {}),
		devices => \@devices,
		camera => ($s->{'camera'} ? 1 : 0),
		items => \@items,
		count => scalar @items,
	};
}

# Tell a device/tab to start (or stop) its scanner. A peer is reached over the
# signed rail; a tab on this machine gets the console command directly.
sub market_scan_device_send {
	my ($c, $device, $s, $stop) = @_;
	my $bti = $device->{'browser_tab_id'} || '';
	my $machine = $device->{'machine'} || '';
	my %opts = (
		session => $s->{'uuid'},
		device_id => &market_scan_device_id($device),
		origin_machine => &subs::signatorial_designer(),
		list => ($s->{'list'} || ''),
		vendor => ($s->{'vendor'} || ''),
		rapid => 1,
	);
	if (($device->{'kind'} || '') eq 'remote' && $machine ne '') {
		my $rm = &subs::db_select('remote_machines', undef, { ip => $machine })->hashes->[0]
			|| &subs::db_select('remote_machines', undef, { hostname => $machine })->hashes->[0];
		return 0 unless $rm;
		my $peer = &remote_useragent_maker({ rm => $rm });
		my $ua = $peer->{'ua'};
		unless ($ua) {
			$ua = Mojo::UserAgent->new();
			$ua->on(start => sub { my ($ua, $tx) = @_; &subs::peer_sign_request($tx->req); });
		}
		$ua = $ua->insecure(1)->connect_timeout(2)->inactivity_timeout(4)->request_timeout(6);
		my $url = ($peer->{'manager'} || $rm->{'manager'}) . '/manager/market/scan/remote?peer=yes&signatorial=' . &subs::signatorial_designer();
		my $res = eval { $ua->post($url => form => { %opts, browser_tab_id => $bti, stop => ($stop ? 1 : 0), timestamp => &subs::rightNow() })->result };
		return ($res && $res->is_success) ? 1 : 0;
	}
	return 0 unless $bti ne '';
	&Websocket::send('server', {
		destination => $bti,
		console => ($stop ? 'marketPhoneScanStop();' : 'marketPhoneCamera(' . encode_json(\%opts) . ');'),
		timestamp => &subs::rightNow()
	});
	return 1;
}

post '/manager/market/scan/session/start' => sub($c) {
	my $device = eval { decode_json($c->param('device')) } || {};
	$device = { kind => 'local', label => 'this machine' } unless ref $device eq 'HASH' && (($device->{'kind'} || '') eq 'local' || ($device->{'kind'} || '') eq 'remote');
	my $s = {
		uuid => &subs::random_string_creator(20),
		at => &subs::rightNow(),
		status => 'scanning',
		device => $device,
		devices => [ $device ],
		list => (&market_list_key($c->param('list') || '') || ''),
		vendor => (&subs::unformat_name($c->param('vendor')) || ''),
		items => [],
	};
	if (($device->{'kind'} || '') eq 'local' && &market_camera_available()) {
		my $pid = &market_camera_start();
		if ($pid) {
			# zbarcam fails fast when the camera is busy or absent; do not claim a
			# live view the machine cannot give, so the browser can fall back
			select(undef, undef, undef, 0.4);
			if (&market_camera_alive()) {
				$s->{'camera'} = 1;
				$s->{'camera_offset'} = 0;
			}
			else { &market_camera_stop(); }
		}
	}
	&market_scan_session_save($s);
	&market_scan_device_send($c, $device, $s, 0) if ($device->{'kind'} || '') eq 'remote';
	$c->render(json => { session => &market_scan_session_view($s) });
};

# Add another input to a running run. Each device keeps its own scanner and the
# reads all land in the same session, so the webcam and two phones can scan at
# once; adding one already on the run restarts its scanner instead of doubling it.
post '/manager/market/scan/session/device/add' => sub($c) {
	my $device = eval { decode_json($c->param('device')) } || {};
	return $c->render(json => { error => 'no device' }) unless ref $device eq 'HASH' && (($device->{'kind'} || '') eq 'local' || ($device->{'kind'} || '') eq 'remote');
	my $s = &market_scan_session();
	return $c->render(json => { error => 'no session' }) unless ($s->{'uuid'} || '') ne '' && ($s->{'status'} || '') eq 'scanning';
	my $id = &market_scan_device_id($device);
	my @devices = grep { &market_scan_device_id($_) ne $id } &market_scan_session_devices($s);
	push @devices, $device;
	$s->{'devices'} = \@devices;
	$s->{'device'} = $devices[0];
	if (($device->{'kind'} || '') eq 'local') {
		if (&market_camera_available() && !($s->{'camera'} || 0)) {
			my $pid = &market_camera_start();
			if ($pid) {
				select(undef, undef, undef, 0.4);
				if (&market_camera_alive()) { $s->{'camera'} = 1; $s->{'camera_offset'} = 0; }
				else { &market_camera_stop(); }
			}
		}
	}
	else { &market_scan_device_send($c, $device, $s, 0); }
	&market_scan_session_save($s);
	$c->render(json => { session => &market_scan_session_view($s) });
};

# Stop one input and leave the rest of the run scanning.
post '/manager/market/scan/session/device/remove' => sub($c) {
	my $id = $c->param('id') || '';
	my $s = &market_scan_session();
	return $c->render(json => { error => 'no session' }) unless ($s->{'uuid'} || '') ne '';
	my @kept;
	my $removed;
	foreach my $d ( &market_scan_session_devices($s) ) {
		if (&market_scan_device_id($d) eq $id) { $removed = $d; next; }
		push @kept, $d;
	}
	return $c->render(json => { error => 'no such device' }) unless $removed;
	&market_scan_device_send($c, $removed, $s, 1) if (($removed->{'kind'} || '') eq 'remote');
	unless (grep { ($_->{'kind'} || '') eq 'local' } @kept) {
		&market_camera_stop() if ($s->{'camera'} || 0);
		delete $s->{'camera'};
	}
	$s->{'devices'} = \@kept;
	$s->{'device'} = $kept[0];
	&market_scan_session_save($s);
	$c->render(json => { session => &market_scan_session_view($s) });
};

post '/manager/market/scan/collect' => sub($c) {
	my $session = $c->param('session') || '';
	my $origin = $c->param('origin_machine') || '';
	# the phone: hand the code to the peer that started the session
	if ($origin ne '' && ($c->param('peer') || '') ne 'yes') {
		my $rm = &subs::db_select('remote_machines', undef, { signatorial => $origin })->hashes->[0];
		if ($rm) {
			my $peer = &remote_useragent_maker({ rm => $rm });
			my $ua = $peer->{'ua'};
			unless ($ua) {
				$ua = Mojo::UserAgent->new();
				$ua->on(start => sub { my ($ua, $tx) = @_; &subs::peer_sign_request($tx->req); });
			}
			$ua = $ua->insecure(1)->connect_timeout(2)->inactivity_timeout(4)->request_timeout(6);
			my $url = ($peer->{'manager'} || $rm->{'manager'}) . '/manager/market/scan/collect?peer=yes&signatorial=' . &subs::signatorial_designer();
			my $res = eval { $ua->post($url => form => {
				session => $session,
				barcode => ($c->param('barcode') || ''),
				stop => ($c->param('stop') ? 1 : 0),
				device_id => ($c->param('device_id') || ''),
				timestamp => &subs::rightNow()
			})->result };
			my $body = $res ? (eval { decode_json $res->body } || {}) : {};
			return $c->render(json => $body);
		}
	}
	if (($c->param('peer') || '') eq 'yes') {
		my $peer_sig = $c->param('signatorial') || '';
		my $rm = ($peer_sig && &subs::db_select('remote_machines', undef, { signatorial => $peer_sig })->hashes->[0]);
		return $c->rendered(403) unless $rm && &subs::peer_verify($c, $rm);
	}
	my $s = &market_scan_session();
	unless (($s->{'uuid'} || '') ne '' && $s->{'uuid'} eq $session) {
		return $c->render(json => { error => 'no such session' });
	}
	if ($c->param('stop')) {
		my $did = $c->param('device_id') || '';
		if ($did ne '') {
			my @kept = grep { &market_scan_device_id($_) ne $did } &market_scan_session_devices($s);
			if (scalar @kept) {
				$s->{'devices'} = \@kept;
				$s->{'device'} = $kept[0];
				unless (grep { ($_->{'kind'} || '') eq 'local' } @kept) {
					&market_camera_stop() if ($s->{'camera'} || 0);
					delete $s->{'camera'};
				}
				&market_scan_session_save($s);
				return $c->render(json => { ok => 1, stopped => $did, count => scalar @{ $s->{'items'} || [] } });
			}
		}
		&market_camera_stop() if ($s->{'camera'} || 0);
		delete $s->{'camera'};
		$s->{'status'} = 'cancelled';
		$s->{'items'} = [];
		&market_scan_session_save($s);
		return $c->render(json => { ok => 1, cancelled => 1 });
	}
	my $code = $c->param('barcode') || '';
	$code =~ s/\s+//g;
	return $c->render(json => { error => 'no code' }) unless $code =~ /\S/;
	my $it = &market_scan_session_add($s, $code);
	return $c->render(json => { error => 'no code' }) unless $it;
	$c->render(json => { ok => 1, item => { %$it, formatted => &subs::format_name($it->{'item'}) }, count => scalar @{ $s->{'items'} } });
};

get '/manager/market/scan/session' => sub($c) {
	my $s = &market_scan_session();
	&market_camera_ingest($s) if ($s->{'camera'} || 0);
	$c->render(json => &market_scan_session_view($s));
};

post '/manager/market/scan/session/done' => sub($c) {
	my $s = &market_scan_session();
	return $c->render(json => { error => 'no session' }) unless ($s->{'uuid'} || '') ne '';
	my $list = &market_list();
	my ($added, $linked) = (0, 0);
	foreach my $it ( @{ $s->{'items'} || [] } ) {
		next unless ref $it eq 'HASH';
		my $name = &subs::unformat_name($it->{'item'} || '');
		next unless $name ne '';
		my $init = &subs::setting_initializer($name, &subs::rightNow());
		$name = $init->{'app'} if $init->{'app'};
		my $found;
		foreach my $row ( @{$list} ) {
			next unless lc($row->{'text'} || '') eq lc($name) || &subs::unformat_name($row->{'text'} || '') eq $name;
			$row->{'kind'} = 'need' if &market_item_due($name);
			$found = 1;
			$linked++;
			last;
		}
		next if $found;
		unshift @{$list}, {
			uuid => &subs::random_string_creator(21),
			text => $name,
			barcode => ($it->{'code'} || ''),
			kind => &market_item_due($name) ? 'need' : 'want',
			vendor => ($s->{'vendor'} || ''),
			list => ($s->{'list'} || ''),
			unit => ($it->{'unit'} || ''),
			timestamp => &subs::rightNow(),
		};
		$added++;
	}
	&market_save_list($list);
	&market_lists_touch_vendor($s->{'list'}, &subs::format_name($s->{'list'}), $s->{'vendor'}) if ($s->{'list'} || '') ne '' && ($s->{'vendor'} || '') ne '';
	my $d = $s->{'device'} || {};
	foreach my $d ( &market_scan_session_devices($s) ) {
		&market_scan_device_send($c, $d, $s, 1) if (($d->{'kind'} || '') eq 'remote' || ($d->{'browser_tab_id'} || '') ne '');
	}
	&market_camera_stop() if ($s->{'camera'} || 0);
	delete $s->{'camera'};
	$s->{'status'} = 'done';
	$s->{'items'} = [];
	&market_scan_session_save($s);
	$c->render(json => { added => $added, linked => $linked });
};

post '/manager/market/scan/session/cancel' => sub($c) {
	my $s = &market_scan_session();
	return $c->render(json => { error => 'no session' }) unless ($s->{'uuid'} || '') ne '';
	foreach my $d ( &market_scan_session_devices($s) ) {
		&market_scan_device_send($c, $d, $s, 1) if (($d->{'kind'} || '') eq 'remote' || ($d->{'browser_tab_id'} || '') ne '');
	}
	&market_camera_stop() if ($s->{'camera'} || 0);
	delete $s->{'camera'};
	$s->{'status'} = 'cancelled';
	$s->{'items'} = [];
	&market_scan_session_save($s);
	$c->render(json => { cancelled => 1 });
};

# A scanned barcode: resolve it (house first, then a public catalogue, then our own
# naming), make sure the house item app exists, and put it on the list.
post '/manager/market/scan' => sub($c) {
	my $code = $c->param('barcode') || $c->param('code') || '';
	$code =~ s/\s+//g;
	return $c->render(json => { error => 'no code' }) unless $code =~ /\S/;
	my $map = &market_barcode_resolve($code);
	my $name = $map->{'item'} || $code;
	my $init = &subs::setting_initializer($name, &subs::rightNow());
	$name = $init->{'app'} if $init->{'app'};
	my $list_key = $c->param('list') || '';
	my $vendor = &subs::unformat_name($c->param('vendor')) || '';
	my $list = &market_list();
	my $row = {
		uuid => &subs::random_string_creator(21),
		text => $name,
		barcode => $code,
		kind => &market_item_due($name) ? 'need' : 'want',
		vendor => $vendor,
		list => &market_list_key($list_key),
		timestamp => &subs::rightNow(),
	};
	$row->{'unit'} = $map->{'unit'} if $map->{'unit'};
	unshift @{$list}, $row;
	&market_save_list($list);
	&market_lists_touch_vendor($row->{'list'}, &subs::format_name($list_key), $vendor) if $row->{'list'} && $vendor;
	# a scan handed over from another device tells the tab that asked that it landed
	my $origin = $c->param('origin_tab') || '';
	if ($origin ne '') {
		&Websocket::send('server', {
			destination => $origin,
			console => 'marketScanArrived();',
			timestamp => &subs::rightNow()
		});
	}
	$c->render(json => { item => $row, raw => $map->{'raw'}, category => $map->{'category'} });
};

# The warehouse (or anything that knows what needs buying) names an item; Market
# upgrades a matching row to a need.
post '/manager/market/need' => sub($c) {
	my $text = $c->param('item') || $c->param('text') || '';
	$c->render(json => { item => $text, upgraded => &market_upgrade_need($text) });
};

# Opening the Market reconciles the list with the warehouse: an item the shelf
# says is short is upgraded to a need. A POST, so a read never writes.
post '/manager/market/refresh' => sub($c) {
	&market_sweep_needs();
	my $timestamp = $c->param('timestamp');
	my $contents = &market_maker($c);
	my $window = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'market', contents => $contents }, $timestamp);
	$c->render(json => { window => $window, html => $contents });
};

# --- receipts: read a shop receipt into the cart ---
# A receipt is long, so it is scanned - the ADF feeds it in one pass - or
# photographed, and the vision model reads the pages into strict JSON. Each line
# is then matched to a house item: a printed code through the barcode cache, else
# the description folded into our terms by the same model that names a scan. The
# list is only touched once a person confirms, and confirming links each line to
# the list in the cart, so the familiar Checkout is still what writes purchases.

# Whether the house already has an app by this name (a scanned or typed item).
sub market_app_exists {
	my ($item) = @_;
	return 0 unless defined $item && $item ne '';
	my $row = &subs::db_query('select app from settings where app = ? limit 1', $item)->hashes->[0];
	return $row ? 1 : 0;
}

# The list row an item names, if the list already holds one (by our name or by
# what it was typed as).
sub market_list_row {
	my ($item) = @_;
	return undef unless defined $item && $item ne '';
	my $want = &subs::unformat_name($item);
	foreach my $it ( @{ &market_list() } ) {
		return $it if lc($it->{'text'} || '') eq lc($item) || &subs::unformat_name($it->{'text'} || '') eq $want;
	}
	return undef;
}

# Fold a receipt's unknown descriptions into our terms in ONE model call: a
# receipt has many lines, and one call each would be slow and wasteful. Returns
# a hash of description => house name, its misses left absent.
sub market_receipt_name_batch {
	my ($raws) = @_;
	my %out;
	return \%out unless $raws && scalar @{$raws};
	my $listed = join "\n", map { ($_ + 1) . ". " . $raws->[$_] } (0 .. $#{$raws});
	my ($text) = &subs::ai_chat_role('chatbot_model', [
		{ role => 'system', content => 'You name shop products for JawnOS. Give each one a short house name: the thing itself in one or two words (a milk carton is milk, a bar of soap is soap), never a category or a brand. Answer with strict JSON only.' },
		{ role => 'user', content => "Products:\n$listed\nReturn ONLY JSON: {\"names\":[{\"n\":the product number above,\"item\":\"a short house name, one or two words\"}]}." },
	]);
	my ($json) = ($text || '') =~ /(\{.*\})/s;
	my $o = eval { return decode_json $json } || {};
	foreach my $e ( @{ $o->{'names'} || [] } ) {
		next unless ref $e eq 'HASH';
		my $i = ($e->{'n'} || 0) - 1;
		next unless $i >= 0 && $i < scalar @{$raws};
		next unless ($e->{'item'} || '') =~ /\S/;
		$out{ $raws->[$i] } = &subs::unformat_name($e->{'item'});
	}
	return \%out;
}

# The pages of one receipt -> its lines as JSON. All pages go in one call so a
# total printed on the last page is read with the lines above it.
sub market_receipt_read {
	my ($pages) = @_;
	return (undef, 'no receipt image to read') unless $pages && scalar @{$pages};
	my $system = 'You read shop receipts for JawnOS and answer with strict JSON only, no prose.';
	my $ask = 'These images are the pages of ONE shop receipt, page one first. Return ONLY JSON: '
		. '{"vendor":"the shop name or empty","date":"YYYY-MM-DD or empty","total":the printed total as a number or null,'
		. '"payment_method":"the tender as printed (cash, debit, credit, visa, mastercard, amex, mobile, gift, other) or empty",'
		. '"payment_ref":"the card number\'s last 4 digits, or an approval/auth code printed with the tender, digits only, else empty",'
		. '"lines":[{"description":"the item text as printed, trimmed","code":"a barcode, UPC or ISBN printed on that line, digits only, else empty",'
		. '"qty":the quantity as a number (1 when not shown),"price":the line total as a number,"unit_price":the price per unit as a number or null}]}. '
		. 'Prices as plain numbers without symbols. Read the tender/payment rows only into payment_method and payment_ref, never as a line. Include only purchased lines; skip subtotal, tax, change, loyalty, savings and other summary rows.';
	my ($text, $err) = &subs::ai_chat_role('visual_assistant', [
		{ role => 'system', content => $system },
		{ role => 'user', content => $ask, images => $pages },
	], &subs::ai_role_thinking('visual_assistant'));
	return (undef, $err || 'the vision model returned nothing') unless $text;
	my ($json) = $text =~ /(\{.*\})/s;
	my $out = eval { return decode_json $json } || {};
	return (undef, 'the vision model did not return a JSON receipt') unless ref $out eq 'HASH';
	return ($out, undef);
}

# Read a receipt's lines into rows a person can confirm. A printed code resolves
# through the barcode cache; a description the house already keeps is taken as
# is; only the genuinely new descriptions are handed to the batch fold. Every row
# carries what it matched by, so the confirm panel can say why.
sub market_receipt_lines {
	my ($out) = @_;
	my @raw = grep { ref $_ eq 'HASH' } @{ $out->{'lines'} || [] };
	my (@rows, @need);
	foreach my $l ( @raw ) {
		next unless ($l->{'description'} || '') =~ /\S/ || ($l->{'code'} || '') =~ /\S/;
		my $desc = &subs::unformat_name($l->{'description'} || '');
		my $code = $l->{'code'} || '';
		$code =~ s/[^0-9]//g;
		my ($item, $raw, $how) = ('', $desc, '');
		if (length $code >= 8) {
			my $map = &market_barcode_resolve($code);
			if ($map && $map->{'item'}) { $item = $map->{'item'}; $raw = $map->{'raw'} || $desc; $how = 'barcode'; }
		}
		if (!$item && $desc ne '' && (&market_app_exists($desc) || &market_list_row($desc))) { $item = $desc; $how = 'known'; }
		push @need, $desc if !$item && $desc ne '';
		push @rows, { line => $l, desc => $desc, code => $code, raw => $raw, item => $item, how => $how };
	}
	my %named = %{ &market_receipt_name_batch(\@need) } if scalar @need;
	foreach my $r ( @rows ) {
		if (!$r->{'item'}) {
			my $n = $named{ $r->{'desc'} };
			if (!$n && $r->{'desc'} ne '') {
				my $map = &market_barcode_consolidate($r->{'desc'});
				$n = $map->{'item'} if $map && $map->{'item'};
			}
			$r->{'item'} = $n || $r->{'desc'} || $r->{'code'};
			$r->{'how'} ||= 'name';
		}
	}
	my @lines;
	foreach my $r ( @rows ) {
		next unless $r->{'item'} =~ /\S/;
		my $l = $r->{'line'};
		push @lines, {
			description => ($l->{'description'} || ''),
			raw => $r->{'raw'},
			item => $r->{'item'},
			item_formatted => &subs::format_name($r->{'item'}),
			code => $r->{'code'},
			qty => (defined $l->{'qty'} && $l->{'qty'} =~ /[0-9]/) ? 0 + $l->{'qty'} : 1,
			price => (defined $l->{'price'} && $l->{'price'} =~ /[0-9]/) ? 0 + $l->{'price'} : undef,
			unit_price => (defined $l->{'unit_price'} && $l->{'unit_price'} =~ /[0-9]/) ? 0 + $l->{'unit_price'} : undef,
			matched_by => $r->{'how'},
			on_list => (&market_list_row($r->{'item'}) ? 1 : 0),
		};
	}
	return \@lines;
}

# Run the scanner for a receipt, into the market app's own scan folder so the
# pages can be filed as a document afterwards. Synchronous, because the person is
# at the printer waiting, and bounded so a jam cannot wedge the request. A run is
# named by the caller's scan_id so a second request can watch its pages arrive.
# Returns (error, [jpg paths]).
sub market_receipt_scan {
	my ($feed, $scan_id) = @_;
	$scan_id = '' unless defined $scan_id;
	$scan_id =~ s/[^A-Za-z0-9]//g;
	$scan_id = &subs::rightNow() unless length $scan_id;
	my $filename = &subs::home(&subs::setting_grabber({ app => 'misc', setting => 'scan_location', device => $device }) . '/market');
	`mkdir -p $filename` unless -e $filename;
	my $base = $filename . '/receipt_' . $scan_id;
	my $command = &scanner_scan_command($feed, $base);
	return ('the scanner does not offer that feed', []) unless $command;
	$command =~ s/;\s*$//;
	# keep the scanner's own words: the progress view shows them live, and a run
	# that produced nothing says why instead of the old bare "no pages"
	my $log = $base . '.log';
	my $pidfile = $base . '.pid';
	my $cancelfile = $base . '.cancel';
	unlink $cancelfile if -e $cancelfile;
	# run it in the background so its pid is on disk - Cancel can then stop the
	# feed - and wait for it as before, so the request still answers when done
	`timeout 120 $command 2> $log & echo \$! > $pidfile; wait`;
	unlink $pidfile;
	my @tiffs = &scanner_page_list($base);
	my $discard = sub {
		unlink glob("$base*.tiff");
		unlink glob("$base.preview_*.jpg");
		unlink $log;
	};
	if (-e $cancelfile) {
		unlink $cancelfile;
		$discard->();
		return ('the scan was cancelled', []);
	}
	unless (scalar @tiffs) {
		my $why = &scanner_log_reason($log);
		$discard->();
		return ('the scanner produced no pages' . ($why ne '' ? ': ' . $why : ''), []);
	}
	my $photo_size = &subs::setting_grabber({ app => 'misc', setting => 'scan_size', device => $device }) || 'Raw';
	my @jpgs;
	foreach my $t ( @tiffs ) {
		my $jpg = $t;
		$jpg =~ s/\.tiff$/.jpg/;
		if ($photo_size ne 'Raw') { `magick convert $t -resize $photo_size $jpg`; }
		else { `magick convert $t $jpg`; }
		`shred -u $t`;
		push @jpgs, $jpg if -e $jpg;
	}
	unlink glob("$base.preview_*.jpg");
	unlink $log;
	return ('the scanned pages could not be read', []) unless scalar @jpgs;
	return (undef, \@jpgs);
}

# The last lines of a log, read from its tail so a chatty scanner (--progress
# writes a lot) does not make every poll slurp the whole file.
sub scanner_log_tail {
	my ($log, $bytes) = @_;
	$bytes ||= 4096;
	return () unless $log && -e $log;
	open(my $fh, '<', $log) or return ();
	my $size = -s $log;
	seek($fh, $size > $bytes ? $size - $bytes : 0, 0);
	my $tail = do { local $/; <$fh> };
	close $fh;
	return grep { /\S/ } split /[\r\n]+/, ($tail || '');
}

# The scanner's own last word on why a run produced nothing, in plain terms. The
# useful line is scanimage's error ("Document feeder out of documents", "Error
# during device I/O"), not the batch summary printed after it.
sub scanner_log_reason {
	my ($log) = @_;
	my @lines = &scanner_log_tail($log);
	my $why = '';
	foreach my $l ( @lines ) {
		$why = $l if $l =~ /scanimage:/;
	}
	return '' unless $why ne '';
	$why =~ s/^\s+|\s+$//g;
	$why =~ s/^scanimage:\s*//;
	$why =~ s/^sane_start:\s*//i;
	return 'the feeder has no paper' if $why =~ /out of documents|no documents/i;
	return 'the feeder could not pull the page (device I/O) - check it sits square in the tray, or use the flatbed' if $why =~ /device I\/O/i;
	return lcfirst $why;
}

# Save a bridged or uploaded receipt page into the market app's scan folder, so
# the paper can be filed like a scanned one. Returns the jpg path, or undef when
# it could not be converted.
sub market_receipt_store {
	my ($bytes) = @_;
	return undef unless $bytes && length $bytes;
	my $folder = &subs::home(&subs::setting_grabber({ app => 'misc', setting => 'scan_location', device => $device }) . '/market');
	`mkdir -p $folder` unless -e $folder;
	my $jpg = $folder . '/receipt_' . &subs::rightNow() . '.jpg';
	my $tmp = $jpg . '.in';
	write_file($tmp, $bytes);
	`magick convert $tmp $jpg 2>/dev/null`;
	unlink $tmp;
	return (-e $jpg && -s $jpg) ? $jpg : undef;
}

# Keep the receipt: its pages stay where the scanner put them (the market app's
# own folder) and a record of what it was - vendor, total, date, the lines read -
# is kept under the market app's own settings, beside the shopping list and the
# barcode cache rather than as an appointment, so nothing else about the app is
# touched by a receipt.
sub market_receipt_file {
	my ($data) = @_;
	my @files = grep { defined $_ && -e $_ } @{ $data->{'files'} || [] };
	return unless scalar @files;
	my $raw = &subs::setting_grabber({ app => 'market', setting => 'receipts' });
	my $receipts = eval { return decode_json $raw } || [];
	$receipts = [ grep { ref $_ eq 'HASH' } @{$receipts} ];
	my @lines;
	foreach my $l ( @{ $data->{'lines'} || [] } ) {
		next unless ref $l eq 'HASH';
		push @lines, {
			item => ($l->{'item'} || ''),
			qty => ($l->{'qty'} || 1),
			price => $l->{'price'},
		};
	}
	unshift @{$receipts}, {
		uuid => &subs::random_string_creator(20),
		at => &subs::rightNow(),
		date => ($data->{'date'} || ''),
		vendor => ($data->{'vendor'} || ''),
		total => (defined $data->{'total'} && $data->{'total'} =~ /[0-9]/) ? 0 + $data->{'total'} : undef,
		payment_method => ($data->{'payment_method'} || ''),
		payment_ref => ($data->{'payment_ref'} || ''),
		account => ($data->{'account'} || ''),
		files => \@files,
		lines => \@lines,
	};
	pop @{$receipts} while scalar @{$receipts} > 50;
	&subs::setting_setter({ app => 'market', setting => 'receipts', value => encode_json($receipts) });
}

# The scan feeds THIS machine can run: the capability table's answer for the host
# device. A computer has the ADF and the flatbed, a server neither, so the Market
# offers the scanner buttons only when this is non-empty (a phone reaching the
# house still scans on the computer that holds the scanner - the scan runs here).
sub market_scan_feeds {
	return [ @{ $gb::capabilities->{&subs::device_setter()}->{'scan'} || [] } ];
}

# The kept receipts, newest first (the raw `receipts` setting on the market app).
sub market_receipts {
	my $raw = &subs::setting_grabber({ app => 'market', setting => 'receipts' });
	my $receipts = eval { return decode_json $raw } || [];
	return [ grep { ref $_ eq 'HASH' } @{$receipts} ];
}

# The kept receipts prepared for the Market pane: the pages that are still on
# disk as /file_open links, and each receipt's lines ready to re-apply (so the
# pane can put the whole shop back on the list in one press).
sub market_receipts_prepared {
	my @out;
	foreach my $r ( @{ &market_receipts() } ) {
		my @files = grep { defined $_ && -e $_ } @{ $r->{'files'} || [] };
		my @pages;
		if ($r->{'uuid'}) {
			my $i = 0;
			foreach my $f ( @files ) {
				push @pages, { url => '/manager/market/receipt_page?uuid=' . $r->{'uuid'} . '&page=' . $i, path => $f };
				$i++;
			}
		}
		my @lines;
		foreach my $l ( @{ $r->{'lines'} || [] } ) {
			next unless ref $l eq 'HASH' && ($l->{'item'} || '') =~ /\S/;
			push @lines, { include => 1, item => $l->{'item'}, qty => (defined $l->{'qty'} ? $l->{'qty'} : 1), price => $l->{'price'} };
		}
		push @out, {
			%{$r},
			pages => \@pages,
			apply_json => encode_json(\@lines),
			files_json => encode_json(\@files),
		};
	}
	return \@out;
}

# Capture the receipt, then read it. The ADF feeds a long receipt in one pass,
# the flatbed takes a page at a time; without a feed, an uploaded or bridged
# image is read. Nothing is written here.
post '/manager/market/receipt' => sub($c) {
	my $feed = lc($c->param('feed') || '');
	my @pages;
	if ($feed eq 'adf' || $feed eq 'flatbed') {
		return $c->render(json => { error => 'this machine cannot scan' })
			unless grep { $_ eq $feed } @{ &market_scan_feeds() };
		my ($err, $paths) = &market_receipt_scan($feed, $c->param('scan_id'));
		return $c->render(json => { error => $err }) if $err;
		foreach my $p ( @{$paths} ) { push @pages, { base64 => encode_base64(read_file($p), ''), path => $p }; }
	}
	else {
		my @blobs;
		my $b64 = $c->param('image');
		# a bridged camera sends base64; an upload arrives as a file part, which
		# param() hands back as a Mojo::Upload, not a string
		if (defined $b64 && !ref $b64 && $b64 =~ /\S/) {
			$b64 =~ s/^data:[^,]*,//;
			my $bytes = b64_decode($b64);
			push @blobs, $bytes if $bytes && length $bytes;
		}
		foreach my $u ( @{ $c->req->uploads } ) {
			next unless ($u->headers->content_type || '') =~ m{^image/};
			my $b = $u->slurp;
			push @blobs, $b if $b && length $b;
		}
		foreach my $b ( @blobs ) { push @pages, { base64 => encode_base64($b, ''), bytes => $b }; }
	}
	return $c->render(json => { error => 'no receipt image was given' }) unless scalar @pages;
	# file the paper, so the receipt is kept beside the item apps it names
	my @files;
	foreach my $p ( @pages ) {
		if ($p->{'path'}) { push @files, $p->{'path'}; next; }
		my $saved = &market_receipt_store($p->{'bytes'});
		push @files, $saved if $saved;
	}
	my ($out, $err) = &market_receipt_read([ map { $_->{'base64'} } @pages ]);
	return $c->render(json => { error => $err }) if $err;
	my @images;
	my $page = 0;
	foreach my $f ( @files ) {
		next unless defined $f && -e $f;
		my $name = $f;
		$name =~ s{.*/}{};
		push @images, { page => $page, url => '/manager/market/receipt/image?file=' . $name };
		$page++;
	}
	$c->render(json => {
		vendor => &subs::unformat_name($out->{'vendor'} || ''),
		vendor_formatted => &subs::format_name($out->{'vendor'} || ''),
		date => $out->{'date'} || '',
		total => (defined $out->{'total'} && $out->{'total'} =~ /[0-9]/) ? 0 + $out->{'total'} : undef,
		payment_method => ($out->{'payment_method'} || ''),
		payment_ref => ($out->{'payment_ref'} || ''),
		account => &market_payment_account($out->{'payment_method'}),
		accounts => &market_accounts(),
		lines => &market_receipt_lines($out),
		files => \@files,
		images => \@images,
	});
};

# Confirm the read: link every line into the list and file the receipt. A row
# already on the list is ticked (what a shop does) and given the receipt's
# quantity and price; a row that is not is added in the cart. A printed code
# becomes the item's own product code, so the next scan of it is instant.
post '/manager/market/receipt/apply' => sub($c) {
	my $vendor = &subs::unformat_name($c->param('vendor')) || '';
	my $list_name = $c->param('list') || '';
	my $account = &subs::unformat_name($c->param('account')) || '';
	my $lines = eval { return decode_json $c->param('lines') } || [];
	return $c->render(json => { error => 'nothing to add' }) unless ref $lines eq 'ARRAY' && scalar @{$lines};
	my $now = &subs::rightNow();
	my $list_key = &market_list_key($list_name);
	my $list = &market_list();
	my (@added, $linked);
	foreach my $l ( @{$lines} ) {
		next unless ref $l eq 'HASH';
		next if defined $l->{'include'} && !$l->{'include'};
		my $item = &subs::unformat_name($l->{'item'} || $l->{'description'} || '');
		next unless $item ne '';
		my $init = &subs::setting_initializer($item, $now);
		$item = $init->{'app'} if $init->{'app'};
		my $code = $l->{'code'} || '';
		$code =~ s/[^0-9]//g;
		if (length $code >= 8 && !&market_barcode_house($code)) {
			&subs::setting_setter({ app => $item, setting => 'product_code', value => $code });
			&market_barcode_remember($code, { item => $item, category => '', unit => '', raw => $item });
		}
		my $found;
		foreach my $it ( @{$list} ) {
			next unless lc($it->{'text'} || '') eq lc($item) || &subs::unformat_name($it->{'text'} || '') eq $item;
			$it->{'picked'} = 1;
			$it->{'account'} = $account if $account;
			$it->{'quantity'} = 0 + $l->{'qty'} if defined $l->{'qty'} && $l->{'qty'} =~ /[0-9]/;
			$it->{'price'} = 0 + $l->{'price'} if defined $l->{'price'} && $l->{'price'} =~ /[0-9]/;
			$found = 1;
			$linked++;
			last;
		}
		next if $found;
		my $row = {
			uuid => &subs::random_string_creator(21),
			text => $item,
			kind => &market_item_due($item) ? 'need' : 'want',
			vendor => $vendor,
			list => $list_key,
			timestamp => &subs::rightNow(),
			cart => 1,
			quantity => (defined $l->{'qty'} && $l->{'qty'} =~ /[0-9]/) ? 0 + $l->{'qty'} : 1,
		};
		$row->{'price'} = 0 + $l->{'price'} if defined $l->{'price'} && $l->{'price'} =~ /[0-9]/;
		$row->{'account'} = $account if $account;
		$row->{'barcode'} = $code if length $code >= 8;
		unshift @{$list}, $row;
		push @added, $item;
	}
	&market_save_list($list);
	&market_lists_touch_vendor($list_key, &subs::format_name($list_name), $vendor) if $list_key && $vendor;
	my $files = eval { return decode_json $c->param('files') } || [];
	&market_receipt_file({ files => $files, lines => $lines, date => $c->param('date'), vendor => $vendor, total => $c->param('total'), payment_method => $c->param('payment_method'), payment_ref => $c->param('payment_ref'), account => $account }) if scalar @{$files};
	$c->render(json => { added => scalar @added, linked => $linked });
};

# A running scan's pages and the scanner's own log, for the confirm panel's live
# view. The scan POST blocks on the scanner, so this is answered by another
# worker while it runs; pages are converted to a preview jpg the moment their
# tiff appears, and the page number is kept stable so a lagging conversion does
# not shuffle what is already shown.
get '/manager/market/receipt/progress' => sub($c) {
	my $id = $c->param('scan_id') || '';
	$id =~ s/[^A-Za-z0-9]//g;
	return $c->render(json => { pages => [], log => [] }) unless length $id;
	my $folder = &subs::home(&subs::setting_grabber({ app => 'misc', setting => 'scan_location', device => $device }) . '/market');
	my $base = $folder . '/receipt_' . $id;
	my (@pages, %seen);
	my $n = 0;
	foreach my $t ( &scanner_page_list($base) ) {
		my $jpg = $base . '.preview_' . $n . '.jpg';
		`magick convert $t $jpg 2>/dev/null` unless -e $jpg;
		if (-e $jpg) {
			push @pages, { page => $n, url => '/manager/market/receipt/preview?scan_id=' . $id . '&page=' . $n };
			$seen{$n} = 1;
		}
		$n++;
	}
	# a finished page's own jpg is written before the vision read, so the paper
	# shows while the model is still working; scanimage's own page number is the
	# `_N` suffix (a flatbed page is the bare base name)
	foreach my $f ( grep { !/\.preview_/ } glob("$base*.jpg") ) {
		my $p = 0;
		$p = $1 - 1 if $f ne $base . '.jpg' && $f =~ /_([0-9]+)\.jpg$/;
		next if $seen{$p};
		my $name = $f;
		$name =~ s{.*/}{};
		push @pages, { page => $p, url => '/manager/market/receipt/image?file=' . $name };
		$seen{$p} = 1;
	}
	my @log = &scanner_log_tail($base . '.log');
	@log = @log[-6 .. -1] if scalar @log > 6;
	$c->render(json => { pages => \@pages, log => \@log });
};

# One page of a running scan, inline (the preview jpg the progress route made).
get '/manager/market/receipt/preview' => sub($c) {
	my $id = $c->param('scan_id') || '';
	$id =~ s/[^A-Za-z0-9]//g;
	my $page = $c->param('page') || 0;
	$page = 0 unless $page =~ /^[0-9]+$/;
	my $jpg = &subs::home(&subs::setting_grabber({ app => 'misc', setting => 'scan_location', device => $device }) . '/market/receipt_' . $id . '.preview_' . $page . '.jpg');
	unless (length $id && -f $jpg) { $c->rendered(404); return; }
	my $data = read_file($jpg);
	unless (defined $data && length $data) { $c->rendered(404); return; }
	$c->res->headers->content_type('image/jpeg');
	$c->res->headers->cache_control('no-store');
	$c->render(data => $data);
};

# A scanned or uploaded receipt page for the review panel, inline. /file_open
# hands a file back as a download, which an <img> will not show; only a
# receipt-named file in the market scan folder is served, never a path.
get '/manager/market/receipt/image' => sub($c) {
	my $name = $c->param('file') || '';
	unless ($name =~ /^receipt_[A-Za-z0-9_.-]+\.(?:jpg|jpeg|png)$/i && $name !~ /\.\./) { $c->rendered(404); return; }
	my $path = &subs::home(&subs::setting_grabber({ app => 'misc', setting => 'scan_location', device => $device }) . '/market/' . $name);
	unless (-f $path) { $c->rendered(404); return; }
	my $data = read_file($path);
	unless (defined $data && length $data) { $c->rendered(404); return; }
	$c->res->headers->content_type($data =~ /^\x89PNG/ ? 'image/png' : 'image/jpeg');
	$c->res->headers->cache_control('private, max-age=60');
	$c->render(data => $data);
};

# Stop a running scan. The worker running scanimage is blocked in its own shell,
# so the cancel is a marker plus a kill of that exact batch name; the scan then
# discards its pages and answers "cancelled" to the waiting request.
post '/manager/market/receipt/cancel' => sub($c) {
	my $id = $c->param('scan_id') || '';
	$id =~ s/[^A-Za-z0-9]//g;
	return $c->render(json => { cancelled => 0 }) unless length $id;
	my $folder = &subs::home(&subs::setting_grabber({ app => 'misc', setting => 'scan_location', device => $device }) . '/market');
	my $base = $folder . '/receipt_' . $id;
	write_file($base . '.cancel', 1);
	`pkill -f "receipt_$id" 2>/dev/null`;
	$c->render(json => { cancelled => 1 });
};

# A kept receipt's page for the receipts pane. /file_open hands a file back as a
# download (Content-Disposition: attachment), which an <img> will not show, so a
# receipt's own page is served inline here - and only a page that receipt
# recorded, never an arbitrary path.
get '/manager/market/receipt_page' => sub($c) {
	my $uuid = $c->param('uuid') || '';
	my $page = $c->param('page') || 0;
	$page = 0 unless $page =~ /^[0-9]+$/;
	my ($receipt) = grep { ($_->{'uuid'} || '') eq $uuid } @{ &market_receipts() };
	my $files = ($receipt && ref $receipt->{'files'} eq 'ARRAY') ? $receipt->{'files'} : [];
	my $file = $files->[$page] || '';
	unless ($file && -f $file) { $c->rendered(404); return; }
	my $data = read_file($file);
	unless (defined $data && length $data) { $c->rendered(404); return; }
	my $type = $data =~ /^\x89PNG/ ? 'image/png'
		: $data =~ /^\xFF\xD8\xFF/ ? 'image/jpeg'
		: $data =~ /^GIF8/ ? 'image/gif'
		: $data =~ /^RIFF....WEBP/s ? 'image/webp'
		: 'application/octet-stream';
	$c->res->headers->content_type($type);
	$c->res->headers->cache_control('private, max-age=60');
	$c->render(data => $data);
};

# A process viewer for the machine (the Monitor app): CPU/memory graphs plus the
# process list, read straight from /proc. The old start-menu htop figure came
# from `times` inside a prefork master that spent its life blocked in run(), so
# its numbers were nonsense; cumulative jiffies per pid plus a difference taken
# in the browser are correct no matter which prefork worker answers. On Termux
# the same reads work for JawnOS's own processes (shared UID); other apps'
# states are hidden and are simply skipped.
get '/manager/process_monitor' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $contents = $c->render_to_string(
		template => 'monitor/monitor',
		timestamp => $timestamp
	);
	my $window = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'process_monitor', contents => $contents }, $timestamp);
	$c->render(json => { window => $window });
};

get '/manager/process_monitor/data' => sub($c) {
	my $clk = 100;   # CLK_TCK

	# memory (KB)
	my ($mem_total, $mem_avail) = (0, 0);
	if (open(my $mf, '<', '/proc/meminfo')) {
		while (my $l = <$mf>) {
			$mem_total = $1 if $l =~ /^MemTotal:\s+(\d+)/;
			$mem_avail = $1 if $l =~ /^MemAvailable:\s+(\d+)/;
			last if $mem_total && $mem_avail;
		}
		close $mf;
	}

	# uptime, to turn each pid's starttime into an age. Android denies
	# /proc/uptime to apps, so the age is simply unknown there (-1).
	my $uptime;
	if (open(my $uf, '<', '/proc/uptime')) {
		my $ul = <$uf>;
		close $uf;
		$uptime = $1 if $ul && $ul =~ /^([\d.]+)/;
	}

	# per-core CPU: cumulative total and idle jiffies
	my @cpus;
	if (open(my $st, '<', '/proc/stat')) {
		while (my $l = <$st>) {
			next if $l =~ /^cpu\s/;               # the aggregate line
			last unless $l =~ /^cpu(\d+)\s+(.*)$/;
			my @v = split ' ', $2;
			my $idle = ($v[3] // 0) + ($v[4] // 0);   # idle + iowait
			my $total = 0;
			$total += ($_ // 0) for @v;
			push @cpus, { t => $total, i => $idle };
		}
		close $st;
	}

	my @procs;
	for my $d (glob('/proc/[0-9]*')) {
		(my $pid = $d) =~ s{.*/}{};
		open(my $sf, '<', "$d/stat") or next;
		my $line = <$sf>;
		close $sf;
		next unless defined $line;
		my $open = index($line, '(');
		my $close = rindex($line, ')');
		next if $open < 0 || $close < 0;
		my $comm = substr($line, $open + 1, $close - $open - 1);
		my @f = split ' ', substr($line, $close + 2);
		my $cmd = '';
		if (open(my $cf, '<', "$d/cmdline")) {
			local $/;
			$cmd = <$cf>;
			close $cf;
			$cmd =~ s/\0/ /g;
			$cmd =~ s/\s+$//;
		}
		$cmd = $comm if !defined $cmd || $cmd eq '';
		$cmd = substr($cmd, 0, 90);
		my $age = -1;
		if (defined $uptime && defined $f[19]) {
			$age = int($uptime - $f[19] / $clk);
			$age = 0 if $age < 0;
		}
		push @procs, { p => $pid, pp => $f[1], t => ($f[11] + $f[12]), r => $f[21], a => $age, n => $cmd };
	}
	# The Monitor's headline: what this machine is running and how it is doing.
	# The battery comes through the shared sampler so a two-second poll does not
	# spawn termux-battery-status each tick; everything else is read here.
	my ($dbm, $database) = &subs::database_grabber();
	my $load = '';
	if (open(my $lf, '<', '/proc/loadavg')) {
		my $l = <$lf>;
		close $lf;
		$load = $1 if $l && $l =~ /^([\d.]+ [\d.]+ [\d.]+)/;
	}
	my $running_jobs = &subs::db_query('select count(*) as c from sync_jobs where state = ?', 'running')->hashes->[0]->{'c'} || 0;
	my $last_job = &subs::db_query('select note, updated from sync_jobs order by cast(updated as integer) desc limit 1')->hashes->[0] || {};
	my $active_peers = &subs::db_query('select count(*) as c from remote_machines where connection = ?', 'active')->hashes->[0]->{'c'} || 0;
	# Include the ./jawn master, which health_process_count leaves out: this is the
	# number a person reads as "how many processes jawn is running".
	my $jawn_procs = scalar grep { ($_->{'n'} || '') =~ m{(?:^|/)(?:jawn|President\.pl|Manager\.pl|Websocket\.pl|teletype\.pl|watch\.pl|Music\.pl|Alarm\.pl|pen\.pl)\b} } @procs;
	my $health = {
		version => &subs::jawn_version(),
		processes => $jawn_procs,
		load => $load,
		uptime => $uptime,
		database => {
			bytes => ($database && -e $database) ? (-s $database) : 0,
			wal_bytes => ($database && -e $database . '-wal') ? (-s $database . '-wal') : 0,
		},
		running_jobs => $running_jobs + 0,
		last_job => { note => $last_job->{'note'} || '', updated => $last_job->{'updated'} || '' },
		peers_active => $active_peers + 0,
		battery => &subs::battery_sample(),
	};
	$c->render(json => { at => &subs::rightNow(), clk => $clk, mem_total => $mem_total, mem_avail => $mem_avail, cpus => \@cpus, procs => \@procs, health => $health });
};


# Group warehouse rows for the warehouse app. The warehouse holds both money
# and stock: a money row is one that names an account (or is denominated in a
# currency measure), everything else is stock grouped by place, then item,
# then unit. Used for the place view and for item search.
sub warehouse_grabber($opts) {
	my $search = $opts->{'search'};
	my $places = $opts->{'places'} || [];
	my $rows;
	if (defined $search && $search ne '') {
		$rows = &subs::db_query('select * from warehouse where item like ? order by timestamp asc', '%' . $search . '%')->hashes;
	}
	elsif (scalar grep { $_ ne 'all' } @{$places}) {
		my @ps = grep { $_ ne 'all' } @{$places};
		my $in = join ',', map { '?' } @ps;
		# money rows carry no place, so keep them in view alongside the picked places
		$rows = &subs::db_query("select * from warehouse where place in ($in) or place is null or place = '' order by timestamp asc", @ps)->hashes;
	}
	else {
		$rows = &subs::db_select('warehouse')->hashes;
	}
	my $warehouse = { places => {}, accounts => {}, items => {}, expires => {}, latest => {} };
	my %expires_cache;
	foreach my $r ( @{$rows} ) {
		my $unit = $r->{'unit'} || 'each';
		my $qty = &subs::numeric_formatter($r->{'quantity'}) + 0;
		# the three faces: stock on a place, a money move, and the balance anchors
		# (inventory). The anchors and stock belong to the Levels view; the money
		# moves are the Moves view's, so they are left out here to keep a
		# snapshot from being counted twice.
		my $kind = $r->{'kind'};
		$kind = ($r->{'type'} eq 'inventory' ? 'inventory' : (($r->{'account'} && $r->{'account'} ne '') ? 'money' : 'stock')) if !defined $kind || $kind eq '';
		if ($kind eq 'money') { next; }
		if ($kind eq 'inventory') {
			my $acct = $r->{'account'} || $r->{'item'} || 'cash';
			my $cur = $r->{'currency'} || $unit;
			$warehouse->{'accounts'}->{$acct}->{$cur} = ($warehouse->{'accounts'}->{$acct}->{$cur} || 0) + $qty;
		}
		elsif ($r->{'item'}) {
			my $item = $r->{'item'};
			my $place = ($r->{'place'} && $r->{'place'} ne '') ? $r->{'place'} : 'unplaced';
			$warehouse->{'places'}->{$place}->{$item}->{$unit} = ($warehouse->{'places'}->{$place}->{$item}->{$unit} || 0) + $qty;
			$warehouse->{'items'}->{$item}->{$place}->{$unit} = ($warehouse->{'items'}->{$item}->{$place}->{$unit} || 0) + $qty;
			unless (defined $expires_cache{$item}) {
				$expires_cache{$item} = &subs::warehouse_item_expires($item);
			}
			if ($expires_cache{$item}) {
				$warehouse->{'expires'}->{$item} = $expires_cache{$item};
				my $ts = &subs::numeric_formatter($r->{'timestamp'}) + 0;
				$warehouse->{'latest'}->{$item} = $ts if $ts > ($warehouse->{'latest'}->{$item} || 0);
			}
		}
	}
	return $warehouse;
}

# The warehouse as one ledger of moves, stock and money together. A stock row is
# already signed - a pull is negative, an addition positive - and a money move is
# the ledger row mirrored from the transaction that produced it (an expense is
# stored negative, an income positive, a transfer as both), so a single list says
# what left and what came in. The balance snapshots (kind inventory) are anchors,
# not moves, and are left out. Filters: places (stock only - money carries none),
# search, limit.
sub warehouse_moves($opts) {
	my $limit = $opts->{'limit'} || 300;
	my $search = $opts->{'search'};
	my @places = grep { defined $_ && $_ ne '' } @{ $opts->{'places'} || [] };
	my @moves;
	# stock moves: a stock row on a place, already signed
	my $wfilter = "where kind = 'stock'";
	my @wargs;
	if (scalar @places) {
		$wfilter .= ' and place in (' . join(',', map { '?' } @places) . ')';
		push @wargs, @places;
	}
	if (defined $search && $search ne '') { $wfilter .= ' and item like ?'; push @wargs, '%' . $search . '%'; }
	push @wargs, $limit;
	foreach my $r ( @{ &subs::db_query('select * from warehouse ' . $wfilter . ' order by timestamp desc limit ?', @wargs)->hashes } ) {
		my $j = eval { return decode_json($r->{'data'}) } || {};
		push @moves, {
			timestamp => &subs::numeric_formatter($r->{'timestamp'}) + 0,
			kind => 'stock',
			item => $r->{'item'},
			place => $r->{'place'},
			quantity => &subs::numeric_formatter($r->{'quantity'}) + 0,
			unit => $r->{'unit'} || 'each',
			reason => $j->{'reason'} || $r->{'type'} || 'stock',
			source => $j->{'source'},
			source_uuid => $j->{'source_uuid'} || $r->{'app_uuid'},
		};
	}
	# money moves: the ledger's own rows, mirrored from the transactions that
	# carried them, so both this view and the budget read one store
	my $mfilter = "where kind = 'money'";
	my @margs;
	if (defined $search && $search ne '') { $mfilter .= ' and (account like ? or app like ?)'; push @margs, ('%' . $search . '%') x 2; }
	push @margs, $limit;
	foreach my $r ( @{ &subs::db_query('select * from warehouse ' . $mfilter . ' order by timestamp desc limit ?', @margs)->hashes } ) {
		my $amt = $r->{'total'};
		$amt = $r->{'amount'} unless defined $amt && $amt =~ /[0-9]/;
		$amt = &subs::numeric_formatter($amt) + 0;
		next unless $amt;
		push @moves, {
			timestamp => &subs::numeric_formatter($r->{'timestamp'}) + 0,
			kind => 'money',
			item => $r->{'account'},
			place => '',
			quantity => $amt,
			unit => $r->{'currency'} || 'CAD',
			reason => $r->{'movement'},
			source => $r->{'app'},
			source_uuid => $r->{'uuid'},
			money => 1,
		};
	}
	@moves = sort { $b->{'timestamp'} <=> $a->{'timestamp'} } @moves;
	# each source is capped at $limit before the merge; the list is not capped
	# again, or a busy money stream would crowd out the stock moves behind it
	return \@moves;
}

# A money move is a warehouse row. Every transaction with an account is written
# to the warehouse as it is recorded - the same fields under the same names, so
# the budget can read the ledger without knowing it moved - and the row is keyed
# by the source transaction's uuid, so a re-write or a backfill cannot double it.
# kind='money' marks it; type and movement keep what the transaction was.
sub warehouse_money_mirror($row) {
	return &subs::warehouse_money_mirror($row);
}

get '/manager/warehouse' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $settings = &subs::settings_grabber({ app => 'warehouse' });
	my $chosen = eval { return decode_json $settings->{'place'} } || ['all'];
	my $places = [ @{$chosen} ];
	# default the levels view to wherever we currently are; the moves ledger
	# reads the places the user actually picked, so it does not hide older stock
	unless (grep { $_ ne 'all' } @{$places}) {
		my $current = &subs::current_place();
		$places = [ $current ] if $current;
	}
	$settings->{'place'} = $places;
	my $warehouse = &warehouse_grabber({ places => $places });
	# the ledger's other face: Moves lists every move (stock and money), Levels
	# the current sums; the window opens on whichever the setting names
	my $moves = (($settings->{'display'} || 'levels') eq 'moves') ? &warehouse_moves({ places => [ grep { $_ ne 'all' } @{$chosen} ], limit => 300 }) : undef;
	my $contents = $c->render_to_string(
		template => 'warehouse/warehouse',
		timestamp => $timestamp,
		settings => $settings,
		warehouse => $warehouse,
		moves => $moves,
		search => ''
	);
	my $window = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'warehouse', contents => $contents }, $timestamp);
	$c->render(json => { window => $window });
};

get '/manager/warehouse/listing' => sub($c) {
	my $search = &subs::unformat_name($c->param('search'));
	my $settings = &subs::settings_grabber({ app => 'warehouse' });
	my $places = eval { return decode_json $settings->{'place'} } || ['all'];
	# the ledger's other face: Levels is what is on hand now, Moves is every move
	# (stock and money) as it happened, signed
	if (($settings->{'display'} || 'levels') eq 'moves') {
		my @picked = grep { $_ ne 'all' } @{$places};
		my $moves = &warehouse_moves({ places => \@picked, search => $search, limit => 300 });
		my $html = $c->render_to_string(
			template => 'warehouse/moves',
			moves => $moves,
			search => $search || ''
		);
		$c->render(json => { html => $html, search => $search });
		return;
	}
	my $warehouse;
	if (defined $search && $search ne '') {
		$warehouse = &warehouse_grabber({ search => $search });
	}
	else {
		$warehouse = &warehouse_grabber({ places => $places });
	}
	my $html = $c->render_to_string(
		template => 'warehouse/listing',
		warehouse => $warehouse,
		places => $places,
		search => $search || ''
	);
	$c->render(json => { html => $html, search => $search });
};

get '/manager/warehouse/journal' => sub($c) {
	my $item = &subs::unformat_name($c->param('item'));
	my $source_uuid = $c->param('source_uuid');
	my ($q,$rows);
	if ($source_uuid) {
		# movements caused by a particular document (transaction/invoice)
		$item = '';
		$q = &subs::db_query('select * from warehouse where app_uuid=? order by timestamp desc limit 200', $source_uuid);
	}
	else {
		$q = &subs::db_query('select * from warehouse where item=? order by timestamp desc limit 200', $item);
	}
	$rows = $q ? $q->hashes : [];
	foreach my $r ( @{$rows} ) {
		$r->{'journal'} = eval { return decode_json $r->{'data'} } || {};
	}
	my $html = $c->render_to_string(
		template => 'warehouse/journal',
		item => $item,
		rows => $rows
	);
	$c->render(json => { html => $html, item => $item, count => scalar @{$rows} });
};

# What an item has on hand right now - what the warehouse Levels view shows, but
# readable by a page or an agent that is reasoning about buying more. Its
# packaging rides along, so a low figure can name the package that would cover
# it (a six-pack when two are left and the shop comes once a week).
get '/manager/warehouse/on_hand' => sub($c) {
	my $item = &subs::unformat_name($c->param('item'));
	my $stock = &subs::warehouse_stock_for($item);
	my $packaging = eval { return decode_json &subs::setting_grabber({ app => $item, setting => 'app_packaging' }) }
		|| eval { return decode_json &subs::setting_grabber({ app => $item, setting => 'packaging' }) }
		|| {};
	# a target turns the reading into a restock plan (how much of which pack to buy)
	my $target = $c->param('target');
	my $restock = (defined $target && $target =~ /[0-9]/) ? &subs::warehouse_restock_for($item, $target + 0) : undef;
	$c->render(json => { item => $item, on_hand => $stock, packaging => $packaging, restock => $restock });
};

get '/store' => sub ($c) {
	&store_maker($c);
};

get '/manager/store' => sub($c) {

	my $timestamp = $c->param('timestamp');

	my $contents = &store_maker($c);
	my $website = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'store', contents => $contents }, $timestamp);
	$c->render(text => $website);
};


sub store_maker($c) {
	my ($db,$database,$sql) = &subs::database_grabber();
	my $cat = &subs::db_query('select * from settings where (setting=? or setting =?) and value=? and device=?','pos', 'mab','category',$device);
	my $categories = $cat->hashes;
	my $timestamp = &subs::rightNow();
	my $settings = &subs::settings_grabber({ app => 'store' });
	# A category used to be one row per pos/mab setting, so the same category could
	# appear twice; and every category appeared whether or not it held anything.
	# Keep one of each and drop the ones with no visible item - an empty shelf is
	# not a destination, it is a dead end.
	my %store_seen;
	my @store_categories;
	foreach my $s ( @{$categories} ) {
		next if $store_seen{ $s->{'app'} }++;
		my $app = $s->{'app'};
		$s->{'settings'} = &subs::settings_grabber({ app => $app });
		$s->{'count'} = &store_category_item_count($app, $c->session('privilege'));
		next unless $s->{'count'} > 0;
		push @store_categories, $s;
	}
	$categories = [ sort { lc($a->{'app'}) cmp lc($b->{'app'}) } @store_categories ];
	my $store_item_total = 0;
	$store_item_total += $_->{'count'} foreach @{$categories};
	my $store_type_counts = &store_type_counts($c->session('privilege'), [ map { $_->{'app'} } @{$categories} ]);
	my $mail_ws_url = 'wss://' . $c->req->url->base->host . ':' . $ENV{PORT_MSG} . '/mail/ws';
	my $paperboy_url = 'wss://' . $c->req->url->base->host . ':' . $ENV{PORT_MSG} . '/observer/ws';
	my $ws_url = 'wss://' . $c->req->url->base->host . ':' . $ENV{PORT_MSG} . '/manager/ws';
	my $advertise_watching = &subs::setting_grabber({ app => 'me', setting => 'advertise_watching' });
	if ($c->param('window_maker') eq 'yes') {
		return $c->render_to_string(
			template => 'store/store',
			string => $random_caching_string,
			categories => $categories,
			item_total => $store_item_total,
			type_counts => $store_type_counts,
			ws_url => $ws_url,
			mail_ws_url => $mail_ws_url,
			paperboy_url => $paperboy_url,
			config => &subs::config_reader(),
			advertise_watching => $advertise_watching,
			my_name => $c->session('name'),
			pseudonyms => &pseudonym_maker('manager',''),
			window_maker => $c->param('window_maker'),
			settings => $settings
		);
	}
	else {
		$c->render(
			template => 'store/store',
			layout => 'store',
			string => $random_caching_string,
			categories => $categories,
			item_total => $store_item_total,
			type_counts => $store_type_counts,
			ws_url => $ws_url,
			mail_ws_url => $mail_ws_url,
			paperboy_url => $paperboy_url,
			config => &subs::config_reader(),
			advertise_watching => $advertise_watching,
			my_name => $c->session('name'),
			pseudonyms => &pseudonym_maker('manager',''),
			settings => $settings,
			window_maker => $c->param('window_maker')
		);
	}

}

# How many items a category holds, counting only the ones this viewer may see.
# The Store uses this to hide empty shelves and to print a count beside each one.
sub store_category_item_count {
	my ($category, $privilege) = @_;
	return 0 unless defined $category && length $category;
	my $sql = q{select count(*) as c from settings where setting='category' and value=? and device=?};
	my @args = ($category, $device);
	if (($privilege || '') ne 'citizen') {
		$sql .= q{ and app in (select app from settings where setting='public' and value='on' and device=?)};
		push @args, $device;
	}
	my $q = &subs::db_query($sql, @args);
	my $row = $q ? $q->hash : undef;
	return $row ? ($row->{'c'} + 0) : 0;
}

# One distinct item per type, so a chip can say how much it would show. A row
# that carries both a pos and a mab value must not be counted twice.
sub store_type_counts {
	my ($privilege, $category_apps) = @_;
	my %counts = map { $_ => 0 } @gb::store_types;
	my @cats = @{ $category_apps || [] };
	return \%counts unless scalar @cats;
	my $placeholders = join ',', map { '?' } @gb::store_types;
	my $cat_placeholders = join ',', map { '?' } @cats;
	# Count only items that actually sit on a shelf: an app wearing pos=event for
	# its own appointments is not a Store event.
	my $sql = "select value as type, count(distinct app) as c from settings where setting in ('pos','mab') and device=? and value in ($placeholders) and app in (select app from settings where setting='category' and device=? and value in ($cat_placeholders))";
	my @args = ($device, @gb::store_types, $device, @cats);
	if (($privilege || '') ne 'citizen') {
		$sql .= q{ and app in (select app from settings where setting='public' and value='on' and device=?)};
		push @args, $device;
	}
	$sql .= ' group by value';
	my $q = &subs::db_query($sql, @args);
	foreach my $r ( @{ $q ? $q->hashes : [] } ) {
		$counts{ $r->{'type'} } = $r->{'c'} + 0 if defined $r->{'type'};
	}
	return \%counts;
}

# Item counts for the direct children of a category (or of a subcategory). The
# $field is the settings key the items carry at that depth: `subcategory` for the
# first level, `subcategory1` for the next, and so on.
sub store_subcategory_counts {
	my ($category, $field, $privilege) = @_;
	$field = 'subcategory' unless defined $field && $field =~ /^subcategory\d*$/;
	$field = 'subcategory' if $field eq 'subcategory0';
	my $sql = "select value as name, count(*) as c from settings where setting=? and device=? and app in (select app from settings where setting='category' and value=? and device=?)";
	my @args = ($field, $device, $category, $device);
	if (($privilege || '') ne 'citizen') {
		$sql .= q{ and app in (select app from settings where setting='public' and value='on' and device=?)};
		push @args, $device;
	}
	$sql .= ' group by value';
	my $q = &subs::db_query($sql, @args);
	my %counts;
	foreach my $r ( @{ $q ? $q->hashes : [] } ) {
		$counts{ $r->{'name'} } = $r->{'c'} + 0 if defined $r->{'name'};
	}
	return \%counts;
}

get '/store/category_grabber' => sub ($c) {
	my $category = &subs::unformat_name($c->param('category'));
	my $subcategory = &subs::unformat_name($c->param('subcategory'));
	my $types = eval { return decode_json $c->param('types') } || [];
	my $count = &subs::numeric_formatter($c->param('count') || '');
	my $privilege = $c->session('privilege') || '';
	my ($db,$database,$sql) = &subs::database_grabber();
	my $itemq = &subs::db_query('select * from settings where setting=? and value=? and device=?','category',$category,$device);

	my $items = $itemq->hashes;
	$items = &store_item_merchandiser($items,$types);
	@{$items} = grep { ($_->{'settings'}->{'public'} || '') eq 'on' } @{$items} unless $privilege eq 'citizen';
	if ($subcategory) {
		@{$items} = grep { ($_->{'settings'}->{'subcategory' . $count} || '') eq $subcategory } @{$items};
	}
	if (scalar @{$types} > 0) {
		my @temp_items;
		foreach my $type ( @{$types} ) {
			push @temp_items, grep { $_->{'settings'}->{'pos'} eq $type || $_->{'settings'}->{'mab'} eq $type } @{$items};
		}
		@{$items} = @temp_items;
	}

	my $subcategories;
	if ($subcategory) {
		$subcategories = &subs::db_query('select * from subcategory where app=?', $subcategory)->hashes;
		$count++;
	}
	else {
		$subcategories = &subs::db_query('select * from subcategory where app=?', $category)->hashes;
	}
	my $depth_field = $count > 0 ? 'subcategory' . $count : 'subcategory';
	my $subcategory_counts = &store_subcategory_counts($category, $depth_field, $privilege);
	my @subcategory_rows;
	foreach my $sub ( @{$subcategories} ) {
		my $n = $subcategory_counts->{ $sub->{'name'} } || 0;
		next unless $n > 0;
		push @subcategory_rows, {
			name => $sub->{'name'},
			label => &subs::format_name($sub->{'name'}),
			count => $n + 0
		};
	}
	@subcategory_rows = sort { $b->{'count'} <=> $a->{'count'} || lc($a->{'name'}) cmp lc($b->{'name'}) } @subcategory_rows;

	my $rendered = $c->render_to_string(
		template => 'store/category',
		items => $items,
		category => $category
	);
	my $returner = {
		content => $rendered,
		category => $category,
		count => scalar @{$items},
		depth => $count + 0,
		subcategories => \@subcategory_rows
	};
	$c->render(json => $returner);
};

post '/store/search' => sub($c) {
	my $search = &subs::unformat_name($c->param('search'));
	my $timestamp = $c->param('timestamp');
	my $types = eval { return decode_json $c->param('types') } || [];
	my $privilege = $c->session('privilege') || '';
	my $items = &subs::db_query('select distinct(app) as app,* from settings where (setting= ? or setting = ?) and app like ? and device=?', 'pos', 'mab', '%' . $search . '%',$device)->hashes;
	my %seen;
	my @temp_items;
	foreach my $st ( @gb::store_types ) {
		# one row per item: an item with both pos and mab was listed twice
		push @temp_items, grep { ($_->{'value'} || '') eq $st && !$seen{ $_->{'app'} }++ } @{$items};
	}
	$items = &store_item_merchandiser(\@temp_items,$types);
	@{$items} = grep { ($_->{'settings'}->{'public'} || '') eq 'on' } @{$items} unless $privilege eq 'citizen';
	@{$items} = sort { lc($a->{'app'}) cmp lc($b->{'app'}) } @{$items};

	my $rendered = $c->render_to_string(
		template => 'store/category',
		items => $items,
	);
	my $returner = {
		content => $rendered,
		count => scalar @{$items}
	};
	$c->render(json => $returner);
};

sub markup_adjuster($markup) {
	if ($markup =~ /%$/gi) {
		$markup =~ s/[^0-9.]//gi;
		$markup = abs(($markup / 100)) + 1;
	}
	return $markup;
}

sub store_item_merchandiser($items,$types) {
	my $universal_markup = &subs::setting_grabber({ app => 'me', setting => 'markup' }) || '5%';
	my $markup = $universal_markup;
	if ($markup =~ /%$/gi) {
		$markup =~ s/[^0-9.]//gi;
		$markup = abs(($markup / 100));
	}

	foreach my $i ( @{$items} ) {
		$i->{'settings'} = &subs::settings_grabber({ app => $i->{'app'} });
		# What the card and the filter chips read. A type lives in either pos or mab
		# depending on how the item was entered; the first non-blank one is its face.
		my $type = $i->{'settings'}->{'pos'} || $i->{'settings'}->{'mab'} || 'product';
		$i->{'type'} = (grep { $_ eq $type } @gb::store_types) ? $type : 'product';
		$i->{'subcategory'} = $i->{'settings'}->{'subcategory'} || '';
		# The stored colour is kept as an accent, never as the card's fill: a shelf
		# painted in its own bright colour ignored the theme. Only a real hex value
		# is passed through, so a stray value cannot inject CSS.
		my $colour = $i->{'settings'}->{'colour'} || '';
		$colour =~ s/^\s+|\s+$//g;
		$i->{'colour'} = $colour =~ /^#?[0-9a-fA-F]{6}$/ ? ($colour =~ /^#/ ? $colour : '#' . $colour) : '';
		$markup = $i->{'settings'}->{'markup'} || $universal_markup;
		if ($markup =~ /%$/gi) {
			$markup =~ s/[^0-9.]//gi;
			$markup = abs(($markup / 100));
		}
		my $models = &subs::db_query('select * from model where app = ?', $i->{'app'})->hashes;
		my $options = &subs::db_query('select * from option where app = ?', $i->{'app'})->hashes;
		my $seen = 0;
		$i->{'price'} = &subs::numeric_formatter($i->{'price'});
		foreach my $mo ( @{$models}, @{$options} ) {
			# a blank quantity is no quantity at all; left as words it only earned a
			# warning and multiplied as zero anyway
			my $quantity = &subs::numeric_formatter($mo->{'quantity'});
			if ($mo->{'def'} eq 'on') {
				if ($mo->{'price'}) {
					$i->{'price'} += $mo->{'price'} * $quantity;
					$seen += 1;
				}
				elsif ($mo->{'cost'}) {
					$i->{'price'} += $mo->{'cost'} * $quantity * $markup;
					$seen += 1;
				}
			}
		}

		if ($seen == 0) {
			@{$i->{'models'}} = sort { $a->{'price'} cmp $b->{'price'} } @{$models};
			if (scalar @{$i->{'models'}} > 0) {
				if ($i->{'models'}[0]->{'price'}) {
					$i->{'price'} = &subs::numeric_formatter($i->{'models'}[0]->{'price'});
				}
				elsif ($i->{'models'}[0]->{'cost'}) {
					$i->{'price'} = $i->{'models'}[0]->{'cost'} * $markup;
				}
			}
		}
	}
	if (scalar @{$types} > 0) {
		my @temp_items;
		foreach my $type ( @{$types} ) {
			push @temp_items, grep { $_->{'settings'}->{'pos'} eq $type || $_->{'settings'}->{'mab'} eq $type } @{$items};
		}
		@{$items} = @temp_items;
	}
	return $items;

}

get '/store/item' => sub ($c) {
	my $item = {};
	my $manufacturer = &subs::unformat_name($c->param('manufacturer'));
	$item->{'app'} = &subs::unformat_name($c->param('item'));
	$item->{'settings'} = &subs::settings_grabber({ app => $item->{'app'} });
	my @manufacturers;
	$item->{'models'} = &subs::db_query('select * from model where app = ? order by price', $item->{'app'})->hashes;
	$item->{'options'} = &subs::db_query('select * from option where app = ?', $item->{'app'})->hashes;
	my $markup = &markup_adjuster($item->{'settings'}->{'markup'} || &subs::setting_grabber({ app => 'me', setting => 'markup' }) || '5%');

	if ($c->param('quote')) {
		my $q = eval { return decode_json $c->param('quote') } || {};
		foreach my $t ( keys %{$q->{'custom'}} ) {
			foreach my $mo ( @{$q->{'custom'}->{$t}} ) {
				unless ( grep { $mo->{'uuid'} eq $_->{'uuid'} } @{$item->{$t . 's'}}) {
				#	$mo->{'characteristics'} = eval { return encode_json $mo->{'characteristics'} } || undef;
					push @{$item->{$t . 's'}}, $mo
				}
			}
		}


		$item->{'quote'} = $q;
	}


	if (scalar @{$item->{'models'}} > 0) {
		if ($item->{'models'}[0]->{'markup'}) {
			$markup = &markup_adjuster($item->{'models'}[0]->{'markup'});
		}
		if ($item->{'models'}[0]->{'price'}) {
			$item->{'price'} = $item->{'models'}[0]->{'price'};
		}
		elsif ($item->{'models'}[0]->{'cost'}) {
			$item->{'price'} = $item->{'models'}[0]->{'cost'} * $markup;
			$item->{'cost'} = $item->{'models'}[0]->{'cost'};
		}
		else {
			$item->{'price'} = $item->{'settings'}->{'worth'} * $markup;
		}
		$item->{'models'}[0]->{'select'} = 'on';
		foreach my $m (@{$item->{'models'}}) {
			$m->{'table'} = 'model';
		}
	}
	else {
		$item->{'price'} = $item->{'settings'}->{'worth'} * $markup;
	}
	if (scalar @{$item->{'options'}} > 0) {
		foreach my $o (@{$item->{'options'}}) {
			$o->{'table'} = 'option';
		}
	}
	my $option_categories = {};
	foreach my $att ( @{$item->{'models'}}, @{$item->{'options'}} ) {
		if ($att->{'manufacturer'}) {
			push @manufacturers, $att->{'manufacturer'} unless grep { $_ eq $att->{'manufacturer'} } @manufacturers;
		}
		if ($att->{'markup'}) {
			$markup = &markup_adjuster($att->{'markup'});
		}
		if ($att->{'file'}) {
			$att->{'file'} = eval { return decode_json $att->{'file'} } || [];
		}
		if ($att->{'price'}) {

		}
		else {
			$att->{'price'} = &subs::numeric_formatter($att->{'cost'}) * $markup;
		}
		if ($att->{'discount'}) {
			if ($att->{'discount'} =~ /%$/gi) {
				$att->{'discount'} =~ s/[^0-9.]//gi;
				$att->{'discount'} = abs($att->{'price'} * ($att->{'discount'} / 100));
			}
			$att->{'discount'} = abs($att->{'discount'}) * -1;
		}
		$att->{'characteristics'} = eval { return decode_json $att->{'characteristics' } } || [];
		if (my @oc = grep { $_->{'name'} eq 'option_category' } @{$att->{'characteristics'}} ) {
			foreach my $o ( @oc ) {
				my $option_category = &subs::db_select('option_category', undef, { uuid => $o->{'value'} })->hashes;
				if ($option_category->[0]->{'file'}) {
					$option_category->[0]->{'file'} = eval { return decode_json $option_category->[0]->{'file'} } || [];
				}
				$option_category->[0]->{'characteristics'} = eval { return decode_json $option_category->[0]->{'characteristics'} } || [];
				$item->{'option_categories'}->{$option_category->[0]->{'name'}} = $option_category->[0];
				foreach my $occ ( @{$option_category->[0]->{'characteristics'}} ) {
					$item->{'option_categories'}->{$option_category->[0]->{'name'}}->{$occ->{'name'}} = $occ->{'value'};
				}
				push @{$option_categories->{$option_category->[0]->{'name'}}}, $att;
			}
			@{$att->{'characteristics'}} = grep { $_->{'name'} ne 'option_category' } @{$att->{'characteristics'}};
		}
		elsif ((!$att->{'option_category'} || $att->{'option_category'} eq '') && $att->{'table'} eq 'option') {
			push @{$option_categories->{'misc'}}, $att;
		}
	}
	if ($manufacturer) {
		@{$item->{'options'}} = grep { $_->{'manufacturer'} eq $manufacturer } @{$item->{'options'}};
		@{$item->{'models'}} = grep { $_->{'manufacturer'} eq $manufacturer } @{$item->{'models'}};
	}
	if ($item->{'settings'}->{'public'} eq 'on' || $c->session('privilege') eq 'citizen') {
		my $fapptsq = &subs::db_query('select file from appointments where app = ? and file is not null', $item->{'app'})->hashes;
		$item->{'files'} = [];
		foreach my $t ( qw/ specs description / ) {
			$item->{'settings'}->{$t} =~ s/\n/<br>/gi;
		}
		foreach my $f ( @{$fapptsq} ) {
			$f->{'files'} = eval { return decode_json $f->{'file'} } || [];
			foreach my $fi ( grep { $_->{'function'} ne 'receipt' } @{$f->{'files'}} ) {
				push @{$item->{'files'}}, $fi if -e $fi->{'f'} && $fi->{'visible'} ne 'unchecked';
			}
		}
		if (!$item->{'settings'}->{'main_image'} && scalar @{$item->{'files'}} > 0) {
			$item->{'settings'}->{'main_image'} = $item->{'files'}->[0]->{'f'};
		}
		$item->{'template'} = $c->render_to_string(
			template => 'store/item',
			item => $item,
			markup => $markup,
			option_categories => $option_categories,
			manufacturers => \@manufacturers,
			settings => &subs::settings_grabber({ app => 'store' }),
			c => $c
		);
	}
	else {
		$item = { template => $c->render_to_string(template => 'guest_layouts/denial') };
	}
	$c->render(json => $item);
};

