sub store_printer($data) {
	my $type = $data->{'type'};
	my $cx_uuid = $data->{'cx_uuid'};
	my $uuid = $data->{'uuid'};
	my $visibility = $data->{'visibility'};
	my $c = &subs::controller_builder();
	my $customer_s = &subs::db_select('settings', undef, { setting => 'uuid', value => $cx_uuid })->hashes->[0];
	my $cx_settings = &subs::settings_grabber({ app => $customer_s->{'app'} });
	my $print_date = 0;
	my $due = &subs::setting_grabber({ app => 'me', setting => 'payment_due_date' });
	my $due_date;
	my $cx = $cx_settings;
	$cx->{'app'} = $customer_s->{'app'};

	my $registers;
	if ( $uuid eq 'all' ) {
		$registers = &subs::db_select('appointments', undef, { type => $type, app => $cx->{'app'} })->hashes;
	}
	else {
		$registers = &subs::db_select('appointments', undef, { type => $type, app => $cx->{'app'}, uuid => $uuid })->hashes;
	}
	my (@i);
	my $totals = { price => 0, tax => 0, discount => 0, total => 0 };
	my $payments = [];
	foreach my $reg ( @{$registers} ) {
		$reg->{'data'} = eval { return decode_json $reg->{'data'} } || {};

		push @i, $reg->{'data'}->{'id'};
		foreach my $t ( qw/subtotal discount tax aux total balance/ ) {
			$totals->{$t} += $reg->{'data'}->{'numbers'}->{$t};
		}
		if ($reg->{'timestamp'} > $print_date) {
			$print_date = $reg->{'timestamp'};
			if ($due) {
				$due_date = &subs::ago_calc($due, $print_date);
			}
			else {
				$due_date = $print_date;
			}
		}
		if ($reg->{'data'}->{'payments'}) {
			push @{$payments}, @{$reg->{'data'}->{'payments'}};
		}
	}
	my $id = join '<br>', @i;

	my $address = $c->tx->local_address;
	my $device_domain = &subs::db_query('select domain from devices where domain is not null')->hashes->[0]->{'domain'};


	if ($device_domain) {
		$address = $device_domain;
	}
	elsif ($config->{'domain'}) {
		my @d = split '\.', $config->{'domain'};
		if (scalar @d > 2) {
			shift @d;
			$address = join '.', @d;
			my $ping = `timeout .5 ping -c 1 $address`;
			unless ($ping =~ /ttl/gi) {
				$address = $config->{'domain'};
			}
		}
		else {
			$address = $config->{'domain'};
		}
	}

	my $public_url = 'https://' . $address . ':3000/public_view/' . $type . '/' . $uuid . '/' . $cx_uuid;
	# the paper a letter carries is rendered by this house's own instance when
	# the config gives it a name here: the pdf is drawn where the code and the
	# theme are current, while the printed link keeps the public address
	my $pdf_url = $config->{'domain'} ? 'https://' . $config->{'domain'} . ':3000/public_view/' . $type . '/' . $uuid . '/' . $cx_uuid : $public_url;

	# One QR on the paper. For a single unpaid invoice with a Bitcoin wallet it
	# is the payment request (BIP21, exact amount) rather than the document link;
	# every other document keeps the link it had. Reading only: the public view
	# renders this too, and a GET must not allocate an address.
	my $pay;
	if (($type || '') eq 'invoice' && $uuid ne 'all' && scalar @{$registers} == 1) {
		my $balance = $registers->[0]->{'data'}->{'numbers'}->{'balance'} // 0;
		if ($balance > 0) {
			my $wallet = &subs::crypto_invoice_wallet('BTC');
			if ($wallet && ($wallet->{'asset'} || '') eq 'BTC') {
				my $alloc = &subs::crypto_invoice_address_read($wallet->{'app'}, $uuid);
				my $addr = ($alloc && defined $alloc->{'address'}) ? $alloc->{'address'} : '';
				$addr = $wallet->{'address'} || '' unless length $addr;
				my $rate = &subs::crypto_rate('BTC');
				if (length $addr && defined $rate && $rate > 0) {
					my $native = sprintf('%.8f', $balance / $rate);
					$pay = {
						address => $addr,
						asset => 'BTC',
						amount => &subs::crypto_amount_format($native, 'BTC'),
						uri => &subs::crypto_bip21_uri($addr, $native),
					};
				}
			}
		}
	}
	my $qr = $pay ? $pay->{'uri'} : $public_url;
	my $qr_img = &subs::crest_qr_png($qr);
	$qr_img = '' unless defined $qr_img && length $qr_img;
	$qr_img = 'data:image/png;base64,' . encode_base64($qr_img) if length $qr_img;

	my $returner = {
		template => '/store/printer/header',
		registers => $registers,
		type => $type,
		visibility => $visibility,
		uuid => $uuid,
		cx => $cx_settings,
		qr_code => $public_url,
		pdf_url => $pdf_url,
		qr_img => $qr_img,
		pay_note => $pay ? $pay->{'amount'} : '',
		pay_address => $pay ? $pay->{'address'} : '',
		id => $id,
		totals => $totals,
		payments => $payments,
		print_date =>	localtime( $print_date / 1000 )->strftime('%b %d %Y'),
		due_date => localtime( &subs::ago_calc($due, $print_date) / 1000 )->strftime('%b %d %Y')
	};


	return $returner;

}
get '/manager/store/customer_list' => sub($c) {
	my $cx = $c->param('cx');
	my $list_type = $c->param('list');
	my $type = $list_type;
	$type =~ s/s$//;
	my ($db) = &subs::database_grabber();
	my $customer = &subs::db_select('settings', undef, { setting => 'uuid', value => $cx })->hashes->[0];
	if ($customer->{'app'}) {
		my $totals = {};
		my $settings = &subs::settings_grabber({ app => $customer->{'app'}});
		my $list = &subs::db_select('appointments', undef, { type => $type, app => $customer->{'app'} })->hashes;
		foreach my $l ( @{$list} ) {
			$l->{$type} = eval { return decode_json $l->{'data'} } || {};
			foreach my $number ( keys %{$l->{$type}->{'numbers'}} ) {
				$totals->{$number} += $l->{$type}->{'numbers'}->{$number};
			}
		}
		my $content = $c->render_to_string(
			template => 'store/list',
			list => $list,
			type => $type,
			settings => $settings,
			customer => $customer,
			totals => $totals
		);
		$c->render(json => { content => $content, cx => $cx, list => $list, settings => $settings });
	}
	else {
		$c->render(json => { content => 'no' });
	}
};

get '/manager/store/customer_register' => sub($c) {
	my $cx = $c->param('cx');
	my $customer = &subs::db_select('settings', undef, { setting => 'uuid', value => $cx })->hashes->[0];
	unless ($customer->{'app'}) {
		$c->render(json => { content => 'no' });
		return;
	}
	my $settings = &subs::settings_grabber({ app => $customer->{'app'} });
	my $rows = &subs::db_select('appointments', undef, { app => $customer->{'app'} })->hashes;
	my (@documents, %totals);
	$totals{'total'} = $totals{'paid'} = $totals{'balance'} = $totals{'count'} = 0;
	foreach my $r ( @{$rows} ) {
		next unless ($r->{'type'} || '') eq 'invoice' || ($r->{'type'} || '') eq 'sale';
		my $d = eval { return decode_json $r->{'data'} } || {};
		my $n = $d->{'numbers'} || {};
		my $total = &subs::numeric_formatter($n->{'total'});
		my $balance = (defined $n->{'balance'} && $n->{'balance'} ne '') ? &subs::numeric_formatter($n->{'balance'}) : $total;
		$balance = 0 if $r->{'type'} eq 'sale';
		my $paid = $total - $balance;
		my @payments;
		foreach my $p ( @{ $d->{'payments'} || [] } ) {
			push @payments, {
				timestamp => &subs::numeric_formatter($p->{'timestamp'} || $p->{'server_time'} || 0),
				amount => &subs::numeric_formatter($p->{'amount'}),
				account => &subs::format_name($p->{'account'} || ''),
			};
		}
		@payments = sort { $a->{'timestamp'} <=> $b->{'timestamp'} } @payments;
		push @documents, {
			uuid => $r->{'uuid'},
			type => $r->{'type'},
			status => $r->{'status'},
			timestamp => &subs::numeric_formatter($r->{'timestamp'}),
			id => $d->{'id'} || '',
			item => &subs::format_name($d->{'item'} || ''),
			total => $total,
			paid => $paid,
			balance => $balance,
			payments => \@payments,
		};
		$totals{'total'} += $total;
		$totals{'paid'} += $paid;
		$totals{'balance'} += $balance;
		$totals{'count'}++;
	}
	@documents = sort { $b->{'timestamp'} <=> $a->{'timestamp'} } @documents;
	my $content = $c->render_to_string(
		template => 'store/register',
		documents => \@documents,
		totals => \%totals,
		customer => $customer,
		settings => $settings
	);
	$c->render(json => { content => $content, cx => $cx, count => scalar @documents });
};

get '/manager/store/customer_correspondence' => sub($c) {
	# A journal of the mail and chat this customer and the house exchanged. The
	# store's customer bar is a citizen's desk, so the vault key is available.
	unless (($c->session('privilege') || '') eq 'citizen') {
		$c->render(json => { content => 'no' });
		return;
	}
	my $cx = $c->param('cx');
	my $customer = &subs::db_select('settings', undef, { setting => 'uuid', value => $cx })->hashes->[0];
	unless ($customer->{'app'}) {
		$c->render(json => { content => 'no' });
		return;
	}
	my $app = $customer->{'app'};
	my $settings = &subs::settings_grabber({ app => $app });

	my %seen_id;
	my @contacts = grep { defined && length && !$seen_id{$_}++ } ($cx, $app, $settings->{'uuid'});
	my $tickets = &subs::db_query('select uuid from tickets where app=? or name=?', $app, $app)->hashes;
	foreach my $t ( @{$tickets} ) {
		push @contacts, $t->{'uuid'} if $t->{'uuid'} && !$seen_id{ $t->{'uuid'} }++;
	}
	my $email_lines = &subs::contact_lines('email', $app);
	my @emails = grep { defined && length } map { $_->{'value'} } @{ $email_lines->{$app} || [] };
	my $phone_lines = &subs::contact_lines('phone', $app);
	my @phones = grep { defined && length } map { &subs::contact_normalizer('phone', $_->{'value'}) } @{ $phone_lines->{$app} || [] };

	my (@where, @args);
	foreach my $value ( @contacts ) {
		push @where, 'contact = ?';
		push @args, $value;
	}
	push @where, 'person = ?';
	push @args, $app;
	if (scalar @emails) {
		push @where, 'email in (' . join(',', map { '?' } @emails) . ')';
		push @args, @emails;
	}
	if (scalar @phones) {
		push @where, 'phone in (' . join(',', map { '?' } @phones) . ')';
		push @args, @phones;
	}

	my $rows = [];
	if (scalar @where) {
		my $sql = 'select * from mailbox where (' . join(' or ', @where) . ") and coalesce(status, '') != 'ignored' order by timestamp desc limit 300";
		$rows = &subs::db_query($sql, @args)->hashes;
	}
	my $suds = &subs::session_suds($c) || &subs::suds_grabber();
	my %counts = (email => 0, chat => 0);
	my $last = 0;
	my $message_index = 0;
	foreach my $m ( @{$rows} ) {
		$message_index++;
		my $channel = $m->{'email'} ? 'email' : ($m->{'phone'} ? 'chat' : 'mail');
		$counts{$channel}++ if exists $counts{$channel};
		my $direction = (($m->{'status'} || '') =~ /^(sent|outbox|draft)$/) ? 'out' : 'in';
		my $subject = $m->{'subject'} || '';
		if ($subject && $suds) {
			$subject = &subs::note_decrypter($suds, $subject, $m->{'ost'}) || '';
		}
		my $body = $m->{'body'} || '';
		if ($body && $suds) {
			$body = &subs::note_decrypter($suds, $body, $m->{'ost'}) || '';
		}
		$subject =~ s/<[^>]+>/ /g;
		$body =~ s/<[^>]+>/ /g;
		$subject =~ s/\s+/ /g;
		$body =~ s/\s+/ /g;
		$subject =~ s/^\s+|\s+$//g;
		$body =~ s/^\s+|\s+$//g;
		my $preview = length($body) > 220 ? substr($body, 0, 220) . '…' : $body;
		$subject = substr($body, 0, 70) . (length($body) > 70 ? '…' : '') if $subject eq '' && $channel eq 'chat';
		my ($from, $to);
		if ($channel eq 'chat') {
			$from = $direction eq 'in' ? ($m->{'phone'} || '') : ($settings->{'phone'} || '');
			$to = $direction eq 'in' ? ($settings->{'phone'} || '') : ($m->{'phone'} || '');
		}
		else {
			$from = $direction eq 'in' ? ($m->{'email'} || $m->{'phone'} || '') : ($settings->{'email'} || $settings->{'phone'} || '');
			$to = $direction eq 'in' ? ($settings->{'email'} || $settings->{'phone'} || '') : ($m->{'email'} || $m->{'phone'} || '');
		}
		# The reader gets every preview. The full text rides along for the newest
		# messages only, so a mailbox of years does not become a page of megabytes.
		my $body_text = $message_index > 60 ? '' : $body;
		$body_text = substr($body_text, 0, 4000) . '…' if length($body_text) > 4000;
		$m->{'channel'} = $channel;
		$m->{'direction'} = $direction;
		$m->{'subject_text'} = $subject;
		$m->{'body_text'} = $body_text;
		$m->{'preview'} = $preview;
		$m->{'from_text'} = $from;
		$m->{'to_text'} = $to;
		$last = $m->{'timestamp'} if ($m->{'timestamp'} || 0) > $last;
	}
	my $content = $c->render_to_string(
		template => 'store/correspondence',
		messages => $rows,
		customer => $customer,
		settings => $settings,
		counts => \%counts,
		last => $last
	);
	$c->render(json => { content => $content, cx => $cx, count => scalar @{$rows} });
};

post '/manager/configure/attribute_copy' => sub($c) {
	my $uuid = $c->param('uuid');
	my $att = $c->param('att');
	my $app = &subs::unformat_name($c->param('app'));
	my $pre_app = &subs::unformat_name($c->param('pre_app'));
	my $returner = { app => $app, att => $att, uuid => $uuid, pre_app => $pre_app };

	my $attribute = &subs::db_select($att, undef, { uuid => $uuid, app => $pre_app })->hashes->[0];
	$attribute->{'characteristics'} = eval { return decode_json $attribute->{'characteristics'} } || [];
	if ($att eq 'option') {
		my @category = grep { $_->{'name'} eq 'option_category' } @{$attribute->{'characteristics'}};
		my $cat = $category[0];
		my $oc = &subs::db_select('option_category', undef, { app => $pre_app, uuid => $cat->{'value'} })->hashes->[0];

		my $oc_check = &subs::db_select('option_category', undef, { app => $app, name => $oc->{'name'} })->hashes;

		unless ( scalar @{$oc_check} > 0 ) {
			$oc->{'app'} = $app;
			$oc->{'server_time'} = &subs::rightNow();
			$oc->{'uuid'} = &subs::random_string_creator(100);
			&subs::db_insert('option_category', $oc);

		}
		else {
			$oc = $oc_check->[0];
		}
		$cat->{'value'} = $oc->{'uuid'};

		$returner->{'option_category'} = $oc;
	}
	$attribute->{'characteristics'} = encode_json $attribute->{'characteristics'};
	$attribute->{'server_time'} = &subs::rightNow();
	$attribute->{'uuid'} = &subs::random_string_creator(101);
	$attribute->{'app'} = $app;

	my $att_check = &subs::db_select($att, undef, { name => $attribute->{'name'}, app => $app })->hashes;

	if (scalar @{$att_check} > 0 ) {
		my $ac = $att_check->[0];
		$attribute->{'uuid'} = $ac->{'uuid'};
		&subs::db_update($att, $attribute, { uuid => $ac->{'uuid'}, app => $ac->{'app'}, name => $ac->{'name'} });
	}
	else {
		&subs::db_insert($att, $attribute);
	}
	$returner->{'template'} = $c->render_to_string(template => 'pos/attributes', att => $att, a => $app);

	$returner->{'attribute'} = $attribute;

	$c->render(json => $returner);

};

post '/manager/store/:att/save' => sub($c) {
	my $app = &subs::unformat_name($c->param('app'));
	my $name = &subs::unformat_name($c->param('name'));
	my $att = $c->stash('att');
	my $cost = $c->param('cost');
	my $price = $c->param('price');
	my $uuid = $c->param('uuid');
	my $timestamp = $c->param('timestamp');
	my $discount = $c->param('discount');
	my $unit = $c->param('unit') || $name;
	my $markup = $c->param('markup');
	my $category = $c->param('category');
	my $description = $c->param('description');
	my $manufacturer = $c->param('manufacturer');
	my $def = $c->param('def');
	my $def_month = $c->param('def_month');
	my $def_day = $c->param('def_day');
	my $def_hour = $c->param('def_hour');
	my $def_wday = $c->param('def_wday');
	my $save_app = $c->param('save_app');
	my $quantity = $c->param('quantity');
	my $delay_start = $c->param('delay_start');
	my $delay_stop = $c->param('delay_stop');

	if ($quantity =~ /[a-zA-Z]/) {
		my $gunit = $quantity;
		$gunit =~ s/[^a-zA-Z]//gi;
		$unit = $gunit if grep { $_ eq $gunit } keys %{$gb::measures};
		$quantity =~ s/[^0-9.]//gi;
	}

	if ($uuid ne 'new') {
		if ($def eq 'on' && $att eq 'model') {
#			&subs::db_update($att, { def => 'off' }, { app => $app })->hashes;
		}
	}

	my $server_time = &subs::rightNow();
	my $returner = {
		app => $app,
		name => $name,
		cost => $cost,
		price => $price,
		discount => $discount,
		markup => $markup,
		description => $description,
		uuid => &subs::random_string_creator(50),
		timestamp => $timestamp,
		server_time => $server_time,
		manufacturer => $manufacturer,
		def => $def,
		def_month => $def_month,
		def_day => $def_day,
		def_hour => $def_hour,
		def_wday => $def_wday,
		save_app => $save_app,
		quantity => $quantity,
		unit => $unit,
		delay_start => $delay_start,
		delay_stop => $delay_stop
	};


	$returner->{'category'} = $category if $att eq 'option_category' || $att eq	'subcategory';
	if ($uuid eq 'new') {
		&subs::db_insert($att, $returner);
	}
	else {
		$returner->{'uuid'} = $uuid;
		&subs::db_update($att, $returner, { uuid => $uuid });
	}

	my $attd = $att;
	$attd = s/_//gi;

	$returner->{'template'} = $c->render_to_string(template => 'pos/attributes', att => $att, a => $app);
	$c->render(json => $returner);
};

post '/manager/configure/attribute_upload' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $attribute = $c->param('attribute');
	my $uuid = $c->param('uuid');
	my $app = $c->param('app');
	my @uploads = @{$c->req->uploads};
	my $image;
	my $returner;
	my $att_files = &subs::db_select($attribute, undef, { uuid => $uuid, app => $app })->hashes->[0];
	my $atf = eval { return decode_json $att_files->{'file'} } || [];
	my (@uploaded_files,$linux_file,$upload_type);
	foreach my $u ( @uploads ) {

		my $server_time = &subs::rightNow();
		$timestamp++;
		my $filen = &subs::unformat_name($u->filename);
		my @f = split /\./, $filen;
		my $ext = pop @f;
		$filen = join '.', @f;
		my $fn = $filen . '_' . $timestamp . '.' . $ext;

		my $upload = {
			type => $u->headers->content_type,
			path => $u->asset->path,
			filename => $fn,
			size => $u->size,
		};

		$app = &subs::unformat_name($app);
		my $init = &subs::setting_initializer($app,$timestamp);
		$app = $init->{'app'};
		my $app_path = &subs::path_name($app);
		push @uploaded_files, $upload;
		my ($folder,$location);

		if ($upload->{'type'} =~ /audio/gi) {
			$upload_type = 'audio';
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'rec_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
		}
		elsif ($upload->{'type'} =~ /video/gi) {
			$upload_type = 'video';
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'video_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
		}
		elsif ($upload->{'type'} =~ /pdf/gi) {
			$upload_type = 'scan';
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'document_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
		}
		elsif ($upload->{'type'} =~ /application/gi) {
			$upload_type = 'software';
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'download_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
		}
		elsif ($upload->{'type'} =~ /image/gi) {
			$upload_type = 'image';
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'photo_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
		}
		else {
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'download_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
		}
		`mkdir -p $location` unless -e $location;
		my $filename = $location . '/' . $upload->{'filename'};
		$u->move_to($filename);
		$linux_file .= `file $filename`;

		if ($upload->{'filename'} =~ /avi$/gi) {
			my $old_filename = $filename;
			$filename =~ s/avi$|mkv$/mp4/;
			my $tn_o = &subs::terminal_name($old_filename);
			my $tn_f = &subs::terminal_name($filename);
			&subs::subprocessor(sub {
				`ffmpeg -i $tn_o $tn_f & exit /b`;
				`shred -u $tn_o`;
				&subs::file_encrypter({ app => $app });
			}, { name => "Video file converter" });
		}
		my $filing = { f => $filename, att => $attribute, att_uuid => $uuid, uuid => &subs::random_string_creator(18), type => $upload_type, server_time => &subs::rightNow() };
		push @{$returner}, $filing;
		push @{$atf}, $filing;


	}

	my $jfile = encode_json $returner;
	my $jafile = encode_json $atf;
	&subs::db_update($attribute, { file => $jafile, server_time => &subs::rightNow() }, { uuid => $uuid, app => $app });
	my $write = {
		timestamp => $timestamp,
		app => &subs::unformat_name($app),
		notes => &subs::note_encrypter(&subs::session_suds($c),$linux_file),
		type => $upload_type,
		file => $jfile,
		uuid => &subs::random_string_creator(20),
		duration => '1000'
	};
	&appointment_writer($c,$write);
	&subs::file_encrypter({ app => $app });
	$c->render(json => $returner);
};


post '/manager/store/attribute_characteristic_setter' => sub ($c) {
	my $timestamp = $c->param('timestamp');
	my $att = &subs::unformat_name($c->param('att'));
	my $app = $c->param('app');
	my $att_uuid = $c->param('att_uuid');
	my $uuid = $c->param('uuid');
	my $input = $c->param('input');
	my $value = $c->param('value');
	my $unit;
	if ($value =~ /[a-zA-Z0-9]/) {
		my $gunit = $value;
		$gunit =~ s/[^a-zA-Z]//gi;
		if (grep { $_ eq $gunit } keys %{$gb::measures}) {
			$unit = $gunit;
			$value =~ s/[^0-9.]//gi;
		}
	}



	my $type = $c->param('type');
	my ($db,$database) = &subs::database_grabber();
	my $attributes = &subs::db_select($att, ['uuid','characteristics',], { uuid => $att_uuid })->hashes;
	my $attr = $attributes->[0];
	my $chars = eval { return decode_json $attr->{'characteristics'} } || [];

	my $data = {
		uuid => &subs::random_string_creator(25),
		$input => $value,
		timestamp => $timestamp
	};



	if ($type eq 'select') {
		$data = {
			name => $input,
			value => $value,
			timestamp => $timestamp,
			uuid => $uuid
		};
		if ($uuid eq 'new') {
			my $measurement = $value;
			$measurement =~ s/[0-9.,-]//gi;
			$data->{'uuid'} = &subs::random_string_creator(25);

		}
		else {
			@{$chars} = grep { $_->{'uuid'} ne $uuid } @{$chars};

		}
	}
	elsif ($uuid eq 'new') {
	}
	else {
		my @cdata = grep { $_->{'uuid'} eq $uuid } @{$chars};
		@{$chars} = grep { $_->{'uuid'} ne $uuid } @{$chars};
		$cdata[0]->{$input} = $value;
		$cdata[0]->{'timestamp'} = $timestamp;
		$data = $cdata[0];
		$data->{'unit'} = $unit if $unit;
	}
	unshift @{$chars}, $data;
	my $json_chars = encode_json $chars;
	&subs::db_update($att, { characteristics => $json_chars }, { uuid => $att_uuid });
	$c->render(json => { template => $c->render_to_string(template => 'pos/attributes', att => $att, a => $app), attribute => $data });

};

