hook before_render => sub {
	$database = '';
};

# Static files (icons, css, js) get an ETag/Last-Modified but no Cache-Control,
# so browsers cached them heuristically and kept showing stale icons. Force a
# revalidation on every request: an unchanged file answers 304, a changed one a
# fresh 200, so a refresh always sees the latest. A STABLE ?string= is what lets
# the 304 happen - a random buster made every load a fresh URL and a full
# re-download.
hook after_static => sub {
	my ($c) = @_;
	$c->res->headers->cache_control('no-cache, max-age=0, must-revalidate');
};

# The manager view used to open ~44 separate <script> tags, a request each over
# HTTP/1.1. They are concatenated here in the order the layout wants and the
# result is memoised until a file changes (an mtime+size signature recomputed
# per request; the concat is redone only on a change). The individual files stay
# the source of truth - nothing is generated on disk. With a stable ?string= and
# the ETag below a repeat load revalidates to a 304, while a changed file (or a
# version bump) is served at once.
my @manager_bundle_files = qw(
	/js/manager/stored.js
	/js/manager/keyboard.js
	/js/manager/text_editor_variables.js
	/js/manager/texture.js
	/js/manager/clothesline.js
	/js/manager/dialog.js
	/js/manager/manager.js
	/js/manager/mapengine.js
	/js/manager/mapmarkers.js
	/js/music.js
	/js/images.js
	/js/manager/configure.js
	/js/manager/windows.js
	/js/manager/editor.js
	/js/manager/ide.js
	/js/manager/ide_code.js
	/js/mailbox.js
	/js/manager/email.js
	/js/manager/soft_keyboard.js
	/js/manager/chat.js
	/js/manager/pen.js
	/js/manager/clockfaceprinter.js
	/js/manager/leaderboardprinter.js
	/js/manager/calendarprinter.js
	/js/manager/continentprinter.js
	/js/manager/timelineprinter.js
	/js/manager/backgroundprinter.js
	/js/manager/taskbar.js
	/js/manager/taskbar_edit.js
	/js/manager/narratorprinter.js
	/js/manager/marker.js
	/js/pm.js
	/js/manager/terminal.js
	/js/manager/budget.js
	/js/manager/embedded.js
	/js/manager/travel.js
	/js/manager/studio.js
	/js/manager/synth_presets.js
	/js/manager/synth.js
	/js/manager/attributes.js
	/js/manager/inventory.js
	/js/manager/security.js
	/js/device.js
	/js/manager/tasks.js
	/js/store.js
	/js/manager/twirl.js
	/js/manager/transaction.js
	/js/manager/relational.js
	/js/manager/warehouse.js
	/js/manager/market.js
	/js/manager/measures.js
	/js/manager/monitor.js
	/js/manager/folders.js
	/js/manager/desk.js
	/js/manager/notes.js
	/js/manager/help.js
	/js/manager/coding.js
	/js/manager/agents.js
	/js/manager/camera.js
	/js/manager/phone.js
	/js/manager/people.js
);
my $manager_bundle_cache;

# Where the built bundle is memoised. The in-process cache below only ever helps
# the worker that built it: production runs several prefork workers and recycles
# each after `accepts`, so a per-process memo meant every fresh worker shelled
# out to terser again -- several seconds on the ~1.3MB concatenation -- and a
# page load stalled whenever it landed on a cold one. Sharing the built bytes on
# disk (keyed by the source signature) means terser runs once per code change for
# the whole machine, and every other worker just reads the file.
sub manager_bundle_paths {
	my $dir = &subs::home('~/.president');
	unless (-d $dir) {
		eval { require File::Path; File::Path::make_path($dir); };
	}
	$dir = '/tmp' unless -d $dir;
	return ($dir . '/manager_bundle.js', $dir . '/manager_bundle.sig');
}

# Minify the concatenation on the way out, so the readable files under public/js
# stay the source of truth for a person (or an agent) while the browser gets one
# small script. terser -c only: it strips whitespace and comments and folds
# constants, but never renames - the manager leans on names (HTML attributes call
# globals directly, and a few places hand eval() a string). If no minifier is
# found the plain concatenation is served, so this degrades to correct-but-bigger
# rather than broken. Point JAWN_JS_MINIFIER at another terser to override.
my $js_minifier;
sub js_minifier_command {
	return $js_minifier if defined $js_minifier;
	my @cands;
	unshift @cands, $ENV{'JAWN_JS_MINIFIER'} if $ENV{'JAWN_JS_MINIFIER'};
	push @cands, 'terser';
	push @cands, glob(&subs::home('~/.local/share/zed/languages/eslint/*/vscode-eslint/node_modules/.bin/terser'));
	foreach my $c (@cands) {
		next unless defined $c && length $c;
		if ($c =~ m{/}) {
			next unless -x $c;
		}
		else {
			my $found = `command -v $c 2>/dev/null`;
			chomp $found;
			next unless length $found;
			$c = $found;
		}
		return $js_minifier = $c if `$c --version 2>/dev/null` =~ /terser/i;
	}
	return $js_minifier = '';
}

sub js_minify {
	my ($text) = @_;
	my $cmd = js_minifier_command();
	return $text unless $cmd;
	my $tmp = '/tmp/jawn_bundle_' . $$ . '.js';
	my $out;
	eval {
		write_file($tmp, $text);
		if (open(my $fh, '-|', $cmd, $tmp, '-c')) {
			local $/;
			$out = <$fh>;
			close $fh;
			$out = undef unless $? == 0;
		}
		unlink $tmp;
	};
	unlink $tmp;
	return (defined $out && length $out > 1024) ? $out : $text;
}

get '/js/manager/bundle.js' => sub ($c) {
	my $dir = 'public';
	my $sig = '';
	foreach my $rel (@manager_bundle_files) {
		my @st = stat($dir . $rel);
		$sig .= $rel . ':' . ($st[9] // 0) . ':' . ($st[7] // 0) . ';';
	}
	my $etag = '"' . &subs::md5_sum($sig) . '"';
	$c->res->headers->etag($etag);
	$c->res->headers->cache_control('no-cache, max-age=0, must-revalidate');
	$c->res->headers->content_type('application/javascript');
	if (($c->req->headers->if_none_match // '') =~ /\Q$etag\E/) {
		$c->res->code(304);
		$c->res->body('');
		return $c->rendered(304);
	}
	unless ($manager_bundle_cache && $manager_bundle_cache->[0] eq $sig) {
		my ($path, $sigpath) = manager_bundle_paths();
		my $stored = '';
		if (-s $path && -s $sigpath) {
			my $stamp = eval { read_file($sigpath) } // '';
			$stamp =~ s/\s+\z//;
			$stored = eval { read_file($path) } // '' if $stamp eq $sig;
		}
		if (length $stored) {
			$manager_bundle_cache = [$sig, $stored];
		}
		else {
			my $raw = '';
			foreach my $rel (@manager_bundle_files) {
				my $src = eval { read_file($dir . $rel) } // '';
				$raw .= "\n;/* $rel */\n" . $src . "\n;\n";
			}
			my $built = js_minify($raw);
			# Payload first, signature last, so a reader that matches the signature
			# is guaranteed the matching payload. A lost race just rebuilds.
			eval {
				my $tmp = "$path.$$" . '.tmp';
				write_file($tmp, $built);
				rename($tmp, $path) or die "rename $tmp: $!";
				write_file($sigpath, $sig . "\n");
			};
			$manager_bundle_cache = [$sig, $built];
		}
	}
	$c->res->body($manager_bundle_cache->[1]);
	return $c->rendered(200);
};

sub password_maker($c) {
	my $sacred = $c->param('numerics');
	my @uploads = @{$c->req->uploads};
	my @numerics = split '', $sacred;
	my ($secret,$ass);
	my $count = scalar @numerics;
	if (scalar @uploads > 0) {
		foreach my $u ( @uploads ) {
			my $size = $u->size;
			if ($size > 10000000) {
				&subs::say_it('way too big of a file!');
				$c->rendered;
				return 'noway';
			}
		  $ass = $u->asset->slurp;
			$ass = encode_base64($ass, "");
			$ass =~ s/\\\n//gi;
			my @asset = split '', $ass;
			my $mid = scalar @asset / 2;
			my $low_mid = (scalar @asset * .3333);
			my $up_mid = (scalar @asset * .6666);
			my $keys = [];
			for (my $i = 1; $i <= $count; $i++) {
				my $d = ($i / scalar @numerics);
				if ($d =~ /\./) {
					my @s = split /\./, $d;
					$d = $s[0];
				}
				foreach my $nm ( ( $low_mid, $mid, $up_mid ) ) {
					my $n = ($nm / $i);
					if ($n =~ /\./) {
						my @s = split /\./, $n;
						$n = $s[0];
					}
					push @{$keys}, $n + $i;
					$secret = $secret . $asset[$n + $i] . $asset[$n + $i - 5];
				}
				$secret = $secret . $numerics[$i - 1];
			}
		}
	}
	if ($ass eq '') {
		$secret = $sacred;
	}
	return $secret;
}

# The login body: the password and identity fields ride the POST body, and the
# digest is appended to the query the peer signature covers. Length-prefixing
# keeps the canonical form unambiguous even if a value contains & or =.
sub sesh_body_digest {
	my ($fields) = @_;
	require Digest::SHA;
	my $sha = Digest::SHA->new(256);
	for my $k (qw(numerics president backup remote_timestamp manager_file)) {
		my $v = $fields->{$k} // '';
		$v = "$v";
		utf8::encode($v);
		$sha->add(length($v) . ':' . $v);
	}
	return $sha->hexdigest;
}

post '/sesh_check' => sub ($c) {
	my ($db,$database,$sql) = &subs::database_grabber();
	# A peer login binds its body to the signed query with a digest; the browser
	# Gate sends none, so only a login carrying one is checked.
	my $body_sha = $c->param('body_sha256') || '';
	if ($body_sha ne '') {
		my %fields = map { $_ => ($c->param($_) // '') } qw(numerics president backup remote_timestamp manager_file);
		unless (&sesh_body_digest(\%fields) eq $body_sha) {
			$log->info('sesh_check refused: body digest mismatch');
			$c->render(json => { authentication => 'denied', error => 'body digest mismatch' });
			return;
		}
	}
	my $secret = &password_maker($c);
	my $reject_count = $c->session('reject_count');
	my $start_time = &subs::rightNow();
	my $backup = $c->param('president') || $c->param('backup') || $c->param('bullshit');
	my $server_time = &subs::rightNow();
	my $timestamp = $c->param('timestamp') || &subs::rightNow();
	my $remote_timestamp = $c->param('remote_timestamp');
	my $me_warranty = &subs::ago_calc(&subs::setting_grabber({ app => 'customs', setting => 'warranty' }) || &subs::setting_grabber({ app => 'me', setting => 'warranty' }) || '-10d');
	my $t = localtime;
	my $db_exists = 0;
	$backup = &subs::home($backup);
	my $computer = $c->param('computer');
	my $local_address = $c->tx->local_address;
	my $remote_address = $c->tx->remote_address;
	my $encryption_standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard' } ) || "aes-256-ctr";
	if ($backup =~ /enc$/gi) {
		my $backup_file = $backup;
		$backup_file =~ s/.enc$//gi;
		$database = $backup_file . '.db';
		unless (-e $database && -s $database > 5000) {
			my $data = `tail $backup`;
			my @split_data = split $universal_splitter, $data;
			$encryption_standard = &subs::decrypter($secret, $split_data[1]);
			&subs::openssl_file_crypt('d', $encryption_standard, $secret, $backup, $database, 0, 1);

		}
		if (-e $database && -s $database > 5000) {
			$sql = Mojo::SQLite->new('sqlite:' . $database);
			if (eval { $sql->db }) {
				$db_exists = 1;
			}
			else {
				`shred -u $database`;
				$db_exists = 0;
			}
		}

	}
	elsif ($backup =~ /db$/) {
		$database = $backup;
		$sql = Mojo::SQLite->new('sqlite:' . $database);
		$db_exists = 1;
	}
	if ($db_exists == 1) {
		my ($db,$database) = &subs::database_grabber();

		&update_database($c);

	#	&subs::db_insert('appointments',{ warranty => $me_warranty, uuid => &subs::random_string_creator(40), app => "customs", type => "id", timestamp => $timestamp, server_time => $server_time }) if $db_exists == 1;
		# the password opens the door row; the key comes from this machine's
		# vault (login_gate falls back to the old password-is-the-key world
		# and migrates it on the spot)
		my ($authorized, $suds_key) = &subs::login_gate($secret);

		if ($authorized) {
			# A login that names a machine must prove the name with that machine's
			# key before the session is minted. A name already on the roster is
			# verified against its pinned key; a first contact is pinned from the key
			# it offers (the password already opened the door). A name that does not
			# verify refuses the login, so a password-holder cannot borrow another
			# machine's lease.
			my $claimed = lc($c->param('signatorial') || '');
			my $peer_row;
			if ($claimed =~ /^[0-9a-f]{16,64}$/) {
				$peer_row = &subs::db_select('remote_machines', undef, { signatorial => $claimed })->hash;
				# Only the new body-bound login carries a digest. A caller from the
				# previous version sends the name without one; it may still log in,
				# but its name is not proved and is not kept below.
				if ($peer_row && $body_sha ne '' && !&subs::peer_verify_strict($c, $peer_row)) {
					$log->info('sesh_check peer login refused: ' . $claimed . ' did not sign');
					$c->render(json => { authentication => 'denied', error => 'the peer did not sign' });
					return;
				}
			}
			app->sessions->samesite(undef);
			$c->session('authentication' => 'approved');
			# A peer logs in with the house password over the signed rail; mark
			# the session so the app gate lets remote_device_connect through
			# without a browser app key. A browser Gate login also sends
			# president/backup, so only neighbour/remote_timestamp (the peer rail)
			# marks a peer.
			my $peer_login = ($c->param('neighbour') || $c->param('remote_timestamp')) ? 1 : 0;
			if ($peer_login) {
				$c->session('peer' => 1);
				# Keep a name only when it was proved against a roster row. A first
				# contact has no row yet; the password opens the session but no name
				# is trusted until a row pins one.
				if ($peer_row && $body_sha ne '') {
					$c->session('peer_signatorial' => $claimed);
				}
				else {
					$c->session('peer_signatorial' => undef);
				}
			}
			# The password is a login, not a recovery share. It no longer seals a
			# copy of the house key: threshold shares (paper or device) are the way
			# back in when this machine's key file is gone.
			my $app_warranty = &subs::setting_grabber({ app => $c->param('app'), setting => 'warranty' });
			my $warranty = &subs::ago_calc($app_warranty || &subs::setting_grabber({ 'app' => 'me', 'setting' => 'login_warranty' } ) || '-3h',$server_time);
			$c->session('database' => $database);
			$c->session('suds_id' => &subs::suds_id($suds_key));
			$c->session('warranty' => $warranty);
			$c->session('string' => &subs::random_string_creator());
			$c->session('name') => &subs::setting_grabber({ app => 'me', setting => 'name' });
			$c->session('privilege' => ($peer_login ? 'resident' : 'guest'));
			# A password-only login is bootstrap/recovery: it can pair a device,
			# restore a backup or recover, never open the manager. The recovery
			# code or the app key is the way in, on this console or another.
			if ($peer_login) {
				$c->session('bootstrap' => undef);
			}
			else {
				$c->session('bootstrap' => 1);
			}
			$c->session('app' => $c->param('app'));


			my $debbie = eval { return &subs::db_select('settings', ['value'], { app => '__DEBRIEFING__', device => $device })->hash->{value} };
			my $deb = $debbie || encode_json [];
			my $duration = $start_time - &subs::rightNow();
		#	&subs::db_insert('appointments',{ warranty => $me_warranty, uuid => &subs::random_string_creator(40), app => "customs", type => "entry", timestamp => $timestamp, server_time => $server_time });
			my $d = { title => 'Your Majesty', app => 'customs', role => 'citizen', message => $remote_address, image => "/images/make believe/crown.png" };

			unless ($c->param('silence')) {
				&subs::say_it('your majesty');
				&notification_sender($d,$database);
			}
			my $hs = &subs::config_reader()->{'name'} || &subs::setting_grabber({ app => 'me', setting => 'computer_name' }) || '';
			if ($hs eq '') {
				$hs = `hostname`;
				chomp $hs;
			}
			# A phone's `hostname` is 'localhost'; give the peers a name a person
			# can pick out of a list instead of that placeholder.
			$hs = &subs::device_hostname_better($hs, '', $config->{'domain'});

			my $who = `whoami`;
			chomp $who;
		#	my $me = &me_setting_list();
			my $colour = '#' . &subs::random_colour_grabber();
			my $device_count = &subs::db_query('select count(*) from devices');
			my $bti = $c->stash('browser_tab_id');
			my $pwd = `pwd`;
			chomp $pwd;
			my $signatorial = &subs::signatorial_designer();
			my $js = {
				'authentication' => 'approved',
				hostname => $hs,
				username => $who,
				debriefer => $deb,
				port => $ENV{PORT_AHOY},
				ws_port => $ENV{PORT_MSG},
				alarm_port => $ENV{PORT_BELL},
				dock_port => $ENV{PORT_DOCK},
	#			me => $me,
				device => $device,
				database => $database,
				browser_tab_id => $bti,
				manager_file => &manager_file_maker($c->session('name')),
				signatorial => $signatorial,
				version => &subs::jawn_version(),
				pwd => $pwd,
				fqdn => (&subs::public_origin_host() || $config->{'domain'}),
				ssh_port => $config->{'ssh_port'},
				manager_colour => &subs::setting_grabber({ app => 'misc', setting => 'manager_background_colour', device => $signatorial }) || &subs::setting_grabber({ app => 'misc', setting => 'manager_background_colour' })
			};
			if (&subs::device_setter() eq 'server') {
				my $mirrors = &subs::db_select('remote_machines')->hashes;
				$js->{'mirrors'} = $mirrors;
			}
			my $archive;
			if ($config->{'archive_dir'}) {
				my $formatted_folder = &subs::home($config->{'archive_dir'});
				$js->{'archive_dir'} = $formatted_folder;
				my $df = `df -h $formatted_folder`;
				my @df = split /\n/, $df;
				my @first_line = split(/\s+/, $df[0]);
				my @data_line = split(/\s+/, $df[1]);
				my $disk = {};
				for ( my $n = 0; $n <= scalar @first_line; $n++) {
					$disk->{$first_line[$n]} = $data_line[$n];
				}
				$js->{'archive'} = {
					dir => $config->{'archive_dir'},
					disk => $disk
				};
				$log->info(Dumper $js->{'archive'});
			}


			$c->render(json => $js);
		}
		elsif ($reject_count > 2) {
			my $denial = $c->render_to_string(template => 'guest_layouts/denial', message => '... access denied.');
			$c->render(json => { 'authentication' => 'denial', denial => $denial });
		}
		else {
			$reject_count = $reject_count + 1;
			$c->session('reject_count' => $reject_count);
			my $visitor = $local_address eq $remote_address ? 'Me' : $computer || 'door';
			# a caller that asked for silence (a peer reconnecting) is refused
			# quietly: speaking on every attempt turned a stale neighbour link
			# into an alarm on the machine's own speakers.
			unless ($c->param('silence')) {
				&subs::say_it('Access denied: ' . $visitor);
			}
			&subs::db_insert('appointments',{ warranty => $me_warranty, uuid => &subs::random_string_creator(40), app => "customs", type => "reject", timestamp => $timestamp, server_time => $server_time }) if $db_exists == 1;
			$c->render(json => { 'authentication' => 'rejected'});
			$c->session('authentication' => 'rejected');
			$c->stash('browser_tab_id' => undef);
			$c->session('suds_id' => undef);
			unless ($c->param('silence')) {
				&subs::say_it('I reject: ' . $remote_address);
				&notification_sender({ app => 'customs', role => 'citizen', title => 'Access', message => 'DB open', image => "/images/make believe/explosion.png" },$database);
			}

		}
	}
	else {
			my $reject_count = $c->session('reject_count') + 1;
			$c->session('reject_count' => $reject_count);
			my $visitor = $local_address eq $remote_address ? 'Me' : 'door';
			unless ($c->param('silence')) {
				&subs::say_it('Access denied: ' . $visitor);
			}
			$c->render(json => { 'authentication' => 'rejected'});
			$c->session('authentication' => 'rejected');
			$c->session('suds_id' => undef);
			$c->stash('browser_tab_id' => undef);
			unless ($c->param('silence')) {
				&notification_sender({ app => 'customs', role => 'citizen', title => 'Access', message => 'DB Closed: ' . $c->tx->remote_address . '<br>' . $c->req->url->path, image => "/images/make believe/explosion.png" },$database);
			}
	}
};

get '/manager/debrief_grabber' => sub($c) {
	# a debrief is this browser's own store - personal data. Only an authenticated
	# session gets it back, and only its own ticket's snapshot; anyone at the gate
	# gets nothing.
	unless ($c->session('authentication') eq 'approved' && $c->session('ticket_uuid')) {
		$c->render(json => {});
		return;
	}
	my $ticket_uuid = $c->session('ticket_uuid');
	my ($db,$database,$sql) = &subs::database_grabber();
	my $q = &subs::db_query('select debriefer from tickets where uuid = ?', $ticket_uuid);
	my $debrief = $q->hashes->[0]->{'debriefer'};
	my $debriefer = decode_json $debrief || {};
	$c->render(json => $debriefer);
};

