# Type-ahead for the History app: a house has thousands of apps, so the list is
# searched on the server and only the matches travel.
get '/manager/crypto/apps' => sub($c) {
	my $q = $c->param('q') // '';
	$q =~ s/^\s+|\s+$//g;
	return $c->render(json => { apps => [] }) unless length $q;
	$q =~ s/[%_\\]//g;
	my @words = grep { length } split /\s+/, $q;
	return $c->render(json => { apps => [] }) unless scalar @words;
	my $pat = '%' . join('%', @words) . '%';
	my $rows = &subs::db_query("select distinct app from settings where app like ? order by app limit 500", $pat)->hashes;
	my $extra = &subs::db_query("select distinct app from appointments where app like ? order by app limit 200", $pat)->hashes;
	push @{$rows}, @{$extra};
	my $ql = lc $q;
	my (%seen, @out);
	foreach my $r ( @{$rows} ) {
		my $app = $r->{'app'};
		next unless defined $app && length $app;
		next if $seen{$app}++;
		my $name = &subs::format_name($app);
		push @out, {
			app => $app,
			name => $name,
			rank => (index(lc($app), $ql) == 0 || index(lc($name), $ql) == 0) ? 0 : 1,
		};
	}
	@out = sort { $a->{'rank'} <=> $b->{'rank'} || lc($a->{'name'}) cmp lc($b->{'name'}) } @out;
	splice(@out, 25) if scalar @out > 25;
	$c->render(json => { apps => \@out });
};

post '/manager/crypto/tracking_app' => sub($c) {
	my $value = $c->param('value') // '';
	$value =~ s/^\s+|\s+$//g;
	if (!length $value) {
		&subs::setting_deleter({ app => 'crypto', setting => 'tracking_app', device => 'all' });
		$c->render(json => { ok => 1, app => '', name => '' });
		return;
	}
	# An exact app key wins, then an exact formatted name; anything else is a new
	# name, normalised the way every other app name is.
	my $app = '';
	my $rows = &subs::db_query('select distinct app from settings where lower(app) = lower(?) limit 1', $value)->hashes;
	$app = $rows->[0]->{'app'} if $rows->[0];
	unless (length $app) {
		my $want = lc(&subs::format_name($value));
		my $all = &subs::db_query('select distinct app from settings order by app')->hashes;
		foreach my $r ( @{$all} ) {
			next unless lc(&subs::format_name($r->{'app'})) eq $want;
			$app = $r->{'app'};
			last;
		}
	}
	$app = lc(&subs::unformat_name($value)) unless length $app;
	&subs::setting_setter({ app => 'crypto', setting => 'tracking_app', value => $app, device => 'all' });
	if (&subs::crypto_tracking_on()) {
		eval { &subs::crypto_tracking_tick({ force => 1, create => 1 }) };
	}
	$c->render(json => { ok => 1, app => $app, name => &subs::format_name($app) });
};

# ---- crypto payments on a Store invoice -------------------------------------
# The seller shows a payment request, the buyer sends the coin, and the seller
# records it here. A payer's PAY1Z proof is checked against their crest and
# countersigned with the house's; the txid is carried, not chain-checked. The
# money side is an ordinary income transaction on the wallet account, so every
# statement keeps working.
sub house_bio_device {
	my ($except) = @_;
	my $rows = &subs::db_select('paired_devices', undef, { status => 'active' })->hashes;
	foreach my $d ( @{$rows} ) {
		next unless $d->{'bio_pubkey'} && length $d->{'bio_pubkey'};
		next if $except && ($d->{'uuid'} || '') eq $except;
		return $d;
	}
	return undef;
}

sub crypto_payment_digest {
	my ($uuid, $cx, $asset, $amount, $account, $txid, $proof) = @_;
	return &subs::sha256_hex(join("\x1f",
		$uuid // '', $cx // '', uc($asset // ''), $amount // '',
		$account // '', $txid // '', &subs::sha256_hex($proof // '')));
}

sub crypto_payment_request_get {
	my ($id) = @_;
	return undef unless defined $id && $id =~ /^[A-Za-z0-9]{8,64}$/;
	my $row = &subs::db_select('cache', undef, { uuid => $id, context => 'crypto_payment_request' })->hashes->[0];
	return undef unless $row;
	my $d = eval { decode_json($row->{'data'} || '') } || {};
	$d->{'id'} = $id;
	$d->{'at'} = $row->{'server_time'} || 0;
	return $d;
}

sub store_invoice_balance {
	my ($inv) = @_;
	my $data = eval { decode_json($inv->{'data'} || '') } || {};
	$data->{'numbers'} = {} unless ref $data->{'numbers'} eq 'HASH';
	$data->{'payments'} = [] unless ref $data->{'payments'} eq 'ARRAY';
	my $paid = 0;
	foreach my $p ( @{ $data->{'payments'} } ) {
		$paid += $p->{'amount'} if defined $p->{'amount'} && $p->{'amount'} =~ /[0-9]/;
	}
	my $balance = defined $data->{'numbers'}->{'balance'}
		? $data->{'numbers'}->{'balance'}
		: (($data->{'numbers'}->{'total'} || 0) - $paid);
	return ($data, $balance + 0, $paid + 0);
}

post '/manager/store/crypto_panel' => sub($c) {
	my $uuid = $c->param('uuid');
	my $cx = $c->param('cx_uuid');
	my $customer = ($cx && &subs::db_select('settings', undef, { setting => 'uuid', value => $cx })->hashes->[0]) || undef;
	unless ($customer && $customer->{'app'}) { return $c->render(json => { ok => 0, error => 'no customer' }); }
	my $inv = &subs::db_select('appointments', undef, { uuid => $uuid, app => $customer->{'app'} })->hashes->[0];
	unless ($inv && ($inv->{'type'} || '') eq 'invoice') { return $c->render(json => { ok => 0, error => 'no invoice' }); }
	my ($data, $balance) = &store_invoice_balance($inv);
	my $device_uuid = $c->session('device_uuid') || '';
	my $device = $device_uuid
		? &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]
		: undef;
	my $self_bio = ($device && $device->{'bio_pubkey'}) ? 1 : 0;
	my $bio_mode = $self_bio ? 'self' : (&house_bio_device($device_uuid) ? 'other' : 'none');
	# Every wallet on this invoice owns an address: the first time the payment
	# panel opens, an xpub wallet issues one; a wallet without one keeps its
	# single saved address.
	my $wallets = &subs::crypto_wallets_report();
	foreach my $w ( @{$wallets} ) {
		my $alloc = &subs::crypto_invoice_address({ app => $w->{'app'}, invoice => $uuid });
		if ($alloc && defined $alloc->{'address'} && length $alloc->{'address'}) {
			$w->{'address'} = $alloc->{'address'};
			$w->{'address_static'} = $alloc->{'static'} ? 1 : 0;
		}
		# the browser needs the address, never the key that derives the rest
		delete $w->{'xpub'};
	}
	my $html = $c->render_to_string(
		template => 'store/crypto_payment',
		invoice => $inv,
		invoice_data => $data,
		customer => $customer,
		wallets => $wallets,
		assets => &subs::crypto_enabled_assets(),
		balance => $balance,
		base => &subs::crypto_report_currency(),
		bio_mode => $bio_mode,
	);
	$c->render(json => { ok => 1, html => $html });
};

post '/manager/store/crypto_payment' => sub($c) {
	unless ($c->session('authentication') eq 'approved') {
		return $c->render(json => { ok => 0, error => 'sign in first' });
	}
	my $uuid = $c->param('uuid');
	my $cx = $c->param('cx_uuid');
	my $customer = ($cx && &subs::db_select('settings', undef, { setting => 'uuid', value => $cx })->hashes->[0]) || undef;
	unless ($customer && $customer->{'app'}) { return $c->render(json => { ok => 0, error => 'no customer' }); }
	my $app = $customer->{'app'};
	my $inv = &subs::db_select('appointments', undef, { uuid => $uuid, app => $app })->hashes->[0];
	unless ($inv && ($inv->{'type'} || '') eq 'invoice') { return $c->render(json => { ok => 0, error => 'no invoice' }); }
	my ($data, $balance) = &store_invoice_balance($inv);
	if ($balance <= 0) { return $c->render(json => { ok => 0, error => 'this invoice is already paid' }); }
	my $asset = &subs::crypto_asset(uc($c->param('asset') || ''));
	unless ($asset) { return $c->render(json => { ok => 0, error => 'choose a coin' }); }
	my $native = &subs::crypto_amount_number($c->param('amount'), $asset);
	unless (defined $native && $native > 0) { return $c->render(json => { ok => 0, error => 'enter the amount that was sent' }); }
	my $rate = &subs::crypto_rate($asset->{'code'});
	unless (defined $rate && $rate > 0) { return $c->render(json => { ok => 0, error => 'no ' . $asset->{'code'} . ' rate is loaded yet' }); }
	my $value = &subs::crypto_value($native, $asset->{'code'});
	unless (defined $value && $value > 0) { return $c->render(json => { ok => 0, error => 'the amount could not be valued' }); }
	my $account = &subs::unformat_name($c->param('account') || '');
	unless (&subs::crypto_account_asset($account) eq $asset->{'code'}) {
		return $c->render(json => { ok => 0, error => 'that account does not hold ' . $asset->{'code'} });
	}
	my $address = $c->param('address') || '';
	# The invoice owns the address, not the browser: a client cannot name a
	# different one. The submitted value is only a fallback for a wallet that
	# has no allocation at all (no xpub and no saved address).
	my $alloc = &subs::crypto_invoice_address({ app => $account, invoice => $uuid });
	$address = $alloc->{'address'} if $alloc && defined $alloc->{'address'} && length $alloc->{'address'};
	my $txid = $c->param('txid') || '';
	$txid =~ s/^\s+|\s+$//g;
	my $proof_code = $c->param('proof') || '';
	# A device with no fingerprint asks another device in the house. Its approval
	# is bound to this exact payment by the digest, so it cannot be moved to a
	# different amount or invoice.
	my $digest = &crypto_payment_digest($uuid, $cx, $asset->{'code'}, $native, $account, $txid, $proof_code);
	my $bio = &biometric_payment_confirmed($c);
	my $approval_id = $c->param('payment_request_id') || '';
	my $approved = 0;
	if (length $approval_id && $approval_id =~ /^[A-Za-z0-9]{8,64}$/) {
		my $req = &crypto_payment_request_get($approval_id);
		$approved = 1 if $req && ($req->{'approved_by'} || '') ne '' && ($req->{'digest'} || '') eq $digest;
	}
	unless ($bio->{'ok'} || $approved) {
		return $c->render(json => {
			ok => 0,
			need_biometric => 1,
			self => $bio->{'self'} ? 1 : 0,
			need_other_device => $bio->{'other'} ? 1 : 0,
			error => $bio->{'other'} ? 'another device must approve this payment' : 'fingerprint confirmation is needed',
		});
	}
	my ($proof, $payer, $verified) = ('', undef, $txid ? 'manual' : 'claimed');
	if (length $proof_code) {
		my $record = &subs::payment_proof_parse($proof_code);
		unless ($record && &subs::payment_proof_verify($record)) {
			return $c->render(json => { ok => 0, error => 'the payment proof did not verify' });
		}
		my $own = &subs::crest_record_read();
		my $proof_payee = ref $record->{'payee'} eq 'HASH' ? ($record->{'payee'}->{'uuid'} || '') : '';
		if (($own->{'uuid'} || '') ne '' && $proof_payee ne ($own->{'uuid'} || '')) {
			return $c->render(json => { ok => 0, error => 'the proof names another house as the payee' });
		}
		unless (uc($record->{'asset'} || '') eq $asset->{'code'}) {
			return $c->render(json => { ok => 0, error => 'the proof names a different coin' });
		}
		unless (&subs::payment_amount_matches($record->{'amount'}, $native)) {
			return $c->render(json => { ok => 0, error => 'the proof amount does not match' });
		}
		my $suds = &subs::session_suds($c);
		my $priv = $suds ? &subs::crest_key_read($suds) : undef;
		if (defined $priv && length $priv == 32) {
			$record = &subs::payment_proof_countersign($record, $priv);
			$verified = 'crest';
		}
		else {
			$verified = 'crest-unsigned';
		}
		$proof = encode_json($record);
		$payer = ref $record->{'payer'} eq 'HASH' ? $record->{'payer'} : undef;
	}
	# A proof proves the key signed; the roster says whether the house has met that
	# crest before. The seller sees the difference and decides whether to accept.
	my $payer_known = (ref $payer eq 'HASH' && length($payer->{'uuid'} || '') && &subs::crest_peer_find($payer->{'uuid'})) ? 1 : 0;
	my $ts = &timestamp_adjuster($c) || &subs::rightNow();
	my $server_time = &subs::rightNow();
	my $tx_uuid = &subs::random_string_creator(40);
	my $tx = {
		app => $app,
		account => $account,
		movement => 'income',
		type => 'transaction',
		timestamp => $ts,
		server_time => $server_time,
		uuid => $tx_uuid,
		amount => $value,
		total => $value,
		tax => 0,
		aux => 0,
		currency => &subs::crypto_report_currency(),
		item => &subs::unformat_name('Crypto ' . $asset->{'code'}),
		data => encode_json({
			crypto => {
				asset => $asset->{'code'},
				amount => $native,
				rate => $rate,
				rate_at => $server_time,
				txid => $txid,
				value => $value,
			},
		}),
	};
	&subs::db_insert('appointments', $tx);
	&warehouse_money_mirror($tx);
	my $payment = {
		account => $account,
		uuid => &subs::random_string_creator(12),
		appt_uuid => $tx_uuid,
		amount => $value,
		timestamp => $ts,
		server_time => $server_time,
		asset => $asset->{'code'},
		asset_amount => $native,
		rate => $rate,
		txid => $txid,
		address => $address,
		payer => $payer,
		proof => $proof,
		verified => $verified,
		payer_known => $payer_known,
	};
	push @{ $data->{'payments'} }, $payment;
	my $new_balance = $balance - $value;
	# A second send cannot be stopped on the chain, but it must not become a
	# negative balance: the invoice closes at zero and the excess is reported so
	# the seller can return it deliberately.
	my $overpaid = $new_balance < -0.005 ? -$new_balance : 0;
	$payment->{'overpaid'} = $overpaid if $overpaid > 0;
	$new_balance = 0 if $new_balance < 0;
	$new_balance = 0 if abs($new_balance) < 0.005;
	$data->{'numbers'}->{'balance'} = $new_balance;
	my $status = $new_balance <= 0 ? 'completed' : 'open';
	&subs::db_update('appointments', { data => encode_json($data), status => $status, server_time => $server_time }, { uuid => $uuid, app => $app });
	&Websocket::send('server', { console => "appointmentDetailGrabber('" . $app . "','" . $uuid . "');" });
	$c->render(json => {
		ok => 1,
		payment => { %{$payment}, proof => undef },
		balance => $new_balance,
		status => $status,
		overpaid => $overpaid,
		verified => $verified,
		payer => $payer,
		payer_known => $payer_known,
	});
};

# A device without a fingerprint asks the house: this stores what is being
# approved (by digest) and prompts every fingerprinted device. The first
# approval wins; the record route checks it before writing.
post '/manager/crypto/payment_request' => sub($c) {
	unless ($c->session('authentication') eq 'approved') {
		return $c->render(json => { ok => 0, error => 'sign in first' });
	}
	my $uuid = $c->param('uuid');
	my $cx = $c->param('cx_uuid');
	my $customer = ($cx && &subs::db_select('settings', undef, { setting => 'uuid', value => $cx })->hashes->[0]) || undef;
	unless ($customer && $customer->{'app'}) { return $c->render(json => { ok => 0, error => 'no customer' }); }
	my $app = $customer->{'app'};
	my $inv = &subs::db_select('appointments', undef, { uuid => $uuid, app => $app })->hashes->[0];
	unless ($inv && ($inv->{'type'} || '') eq 'invoice') { return $c->render(json => { ok => 0, error => 'no invoice' }); }
	my ($data, $balance) = &store_invoice_balance($inv);
	if ($balance <= 0) { return $c->render(json => { ok => 0, error => 'this invoice is already paid' }); }
	my $asset = &subs::crypto_asset(uc($c->param('asset') || ''));
	unless ($asset) { return $c->render(json => { ok => 0, error => 'choose a coin' }); }
	my $native = &subs::crypto_amount_number($c->param('amount'), $asset);
	unless (defined $native && $native > 0) { return $c->render(json => { ok => 0, error => 'enter the amount that was sent' }); }
	my $account = &subs::unformat_name($c->param('account') || '');
	# The approval is for this invoice's own address; make sure it exists.
	&subs::crypto_invoice_address({ app => $account, invoice => $uuid }) if length $account;
	my $txid = $c->param('txid') || '';
	$txid =~ s/^\s+|\s+$//g;
	my $proof = $c->param('proof') || '';
	my $digest = &crypto_payment_digest($uuid, $cx, $asset->{'code'}, $native, $account, $txid, $proof);
	my $now = &subs::rightNow();
	&subs::db_query("delete from cache where context = 'crypto_payment_request' and server_time < ?", $now - 900000);
	my $id = &subs::random_string_creator(24);
	my $summary = $native . ' ' . $asset->{'code'} . ' for invoice ' . ($data->{'id'} || '');
	&subs::db_insert('cache', {
		uuid => $id,
		context => 'crypto_payment_request',
		app => '__president',
		data => encode_json({
			at => $now, requester => $c->session('device_uuid') || '',
			digest => $digest, summary => $summary,
			asset => $asset->{'code'}, amount => $native,
			invoice => $data->{'id'} || '', uuid => $uuid, cx => $cx,
		}),
		server_time => $now,
		timestamp => $now,
		device => 'all',
	});
	my $devices = &subs::db_select('paired_devices', undef, { status => 'active' })->hashes;
	my @targets = map { $_->{'uuid'} } grep { $_->{'bio_pubkey'} && length $_->{'bio_pubkey'} } @{$devices};
	&Websocket::send('server', {
		crypto_payment_prompt => 1,
		request_id => $id,
		source_device => $c->session('device_uuid') || '',
		summary => $summary,
		amount => $native,
		asset => $asset->{'code'},
		invoice => $data->{'id'} || '',
		targets => \@targets,
		timestamp => $now,
	});
	$c->render(json => { ok => 1, id => $id, targets => scalar @targets });
};

post '/manager/crypto/payment_approve' => sub($c) {
	my $id = $c->param('request_id') || '';
	return $c->render(json => { ok => 0, error => 'no request' }) unless $id =~ /^[A-Za-z0-9]{8,64}$/;
	my $device_uuid = $c->param('device_uuid') || $c->session('device_uuid') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]) || undef;
	return $c->render(json => { ok => 0, error => 'not paired' }) unless $device && $device->{'bio_pubkey'};
	my $nonce = $c->param('nonce') || '';
	my $signature = $c->param('signature') || '';
	return $c->render(json => { ok => 0, error => 'no challenge' }) unless length $nonce && length $signature;
	return $c->render(json => { ok => 0, error => 'no challenge' }) unless &biometric_nonce_take('pay', $device_uuid, $nonce, 600000);
	my $msg = join("\n", 'crypto-payment', $device_uuid, $id, $nonce);
	unless (&subs::ecdsa_verify($device->{'bio_pubkey'}, $msg, $signature)) {
		return $c->render(json => { ok => 0, error => 'not accepted' });
	}
	my $request = &crypto_payment_request_get($id);
	return $c->render(json => { ok => 0, error => 'no request' }) unless $request;
	return $c->render(json => { ok => 0, error => 'already approved' }) if ($request->{'approved_by'} || '') ne '';
	$request->{'approved_by'} = $device_uuid;
	$request->{'approved_name'} = $device->{'name'} || '';
	$request->{'approved_at'} = &subs::rightNow();
	&subs::db_update('cache', { data => encode_json($request), server_time => &subs::rightNow() }, { uuid => $id, context => 'crypto_payment_request' });
	&Websocket::send('server', { crypto_payment_approved => 1, request_id => $id, approved_by => $device->{'name'} || $device_uuid, timestamp => &subs::rightNow() });
	$c->render(json => { ok => 1 });
};

get '/manager/crypto/payment_request' => sub($c) {
	my $request = &crypto_payment_request_get($c->param('id'));
	return $c->render(json => { ok => 0, error => 'no request' }) unless $request;
	my $expired = (&subs::rightNow() - ($request->{'at'} || 0)) > 300000 ? 1 : 0;
	$c->render(json => {
		ok => 1,
		approved => ($request->{'approved_by'} || '') ne '' ? 1 : 0,
		by => $request->{'approved_name'} || '',
		expired => $expired,
	});
};

# The payer's half of a payment proof: this house signs what it sent, naming the
# seller's crest (a UUID or a CREST1Z code). The seller's Store panel verifies
# and countersigns it. A txid is carried, not chain-checked.
post '/manager/crypto/proof_build' => sub($c) {
	unless ($c->session('authentication') eq 'approved') {
		return $c->render(json => { ok => 0, error => 'sign in first' });
	}
	my $own = &subs::crest_record_read();
	my $suds = &subs::session_suds($c);
	my $priv = $suds ? &subs::crest_key_read($suds) : undef;
	unless (($own->{'uuid'} || '') ne '' && defined $priv && length $priv == 32) {
		return $c->render(json => { ok => 0, error => 'this house has no crest key to sign with — unlock the house key first' });
	}
	my $asset = &subs::crypto_asset(uc($c->param('asset') || ''));
	unless ($asset) { return $c->render(json => { ok => 0, error => 'choose a coin' }); }
	my $amount = &subs::crypto_amount_number($c->param('amount'), $asset);
	unless (defined $amount && $amount > 0) { return $c->render(json => { ok => 0, error => 'enter the amount that was sent' }); }
	my $address = $c->param('address') || '';
	my $txid = $c->param('txid') || '';
	$txid =~ s/^\s+|\s+$//g;
	my $ref = $c->param('ref') || '';
	$ref =~ s/^\s+|\s+$//g;
	my $memo = $c->param('memo') || '';
	my $payee_value = $c->param('payee') || '';
	$payee_value =~ s/^\s+|\s+$//g;
	my ($payee_uuid, $payee_pubkey, $payee_name) = ('', '', '');
	if ($payee_value =~ /^CREST1/i) {
		my $rec = &subs::crest_code_parse($payee_value);
		unless ($rec && &subs::crest_verify_record($rec)) {
			return $c->render(json => { ok => 0, error => 'the seller\'s crest code did not verify' });
		}
		$payee_uuid = $rec->{'uuid'} || '';
		$payee_pubkey = $rec->{'pubkey'} || '';
		$payee_name = $rec->{'name'} || '';
	}
	else {
		$payee_uuid = $payee_value;
		unless ($payee_uuid =~ /^[A-Za-z0-9_-]{8,64}$/) {
			return $c->render(json => { ok => 0, error => 'enter the seller\'s crest uuid (the seller\'s crypto panel shows it)' });
		}
		my $entry = &subs::crest_peer_find($payee_uuid);
		if ($entry && ref $entry->{'crest'} eq 'HASH') {
			$payee_pubkey = $entry->{'crest'}->{'pubkey'} || '';
			$payee_name = $entry->{'crest'}->{'name'} || '';
		}
	}
	my $record = {
		format => 'jawnos-payment',
		version => 1,
		payer => {
			uuid => $own->{'uuid'},
			pubkey => $own->{'pubkey'},
			name => $own->{'name'} || '',
			fingerprint => $own->{'fingerprint'} || '',
		},
		payee => { uuid => $payee_uuid, pubkey => $payee_pubkey, name => $payee_name },
		asset => $asset->{'code'},
		amount => $amount,
		address => $address,
		txid => $txid,
		ref => $ref,
		at => &subs::rightNow(),
		memo => $memo,
	};
	my $signed = &subs::payment_proof_build($record, $priv);
	unless ($signed) { return $c->render(json => { ok => 0, error => 'the proof could not be signed' }); }
	my $code = &subs::payment_proof_code($signed);
	unless ($code) { return $c->render(json => { ok => 0, error => 'the proof could not be packed' }); }
	$c->render(json => {
		ok => 1,
		code => $code,
		payer => $record->{'payer'},
		payee => $record->{'payee'},
		verified => &subs::payment_proof_verify($signed) ? 1 : 0,
	});
};

get '/manager/crypto/qr' => sub($c) {
	my $text = $c->param('text') || '';
	return $c->rendered(400) unless length $text && length $text <= 500;
	my $png = &subs::crest_qr_png($text);
	unless (defined $png && length $png) { return $c->rendered(503); }
	$c->res->headers->content_type('image/png');
	$c->render(data => $png);
};

# The transaction form converts a native amount as the person types it; this
# hands the browser the same snapshot the server writes with.
get '/manager/crypto/rates' => sub($c) {
	my $r = &subs::crypto_rates_read();
	my $base = &subs::crypto_report_currency();
	my $rates = $r->{'rates'} || {};
	my $to = $rates->{$base};
	my %out;
	foreach my $a ( @{ &subs::crypto_assets() } ) {
		my $from = $rates->{ $a->{'code'} };
		$out{ $a->{'code'} } = $from / $to if defined $from && defined $to && $to > 0;
	}
	$c->render(json => {
		enabled => &subs::crypto_enabled() ? 1 : 0,
		at => $r->{'at'} || 0,
		source => $r->{'source'} || '',
		base => $base,
		rates => \%out,
	});
};

# ---- OAuth2 clients (Configure -> Plat -> OAuth2) ---------------------------
# One entry per app registration; several mail accounts can share one.
get '/manager/configure/oauth_panel' => sub($c) {
	$c->render(text => $c->render_to_string('configure/oauth_clients'));
};
post '/manager/configure/oauth_client/add' => sub($c) {
	my $clients = &subs::oauth_clients();
	push @{$clients}, { uuid => &subs::random_string_creator(15), name => 'New client', provider => 'microsoft' };
	&subs::oauth_clients_store($clients);
	$c->render(json => { result => 'ok' });
};
post '/manager/configure/oauth_client/save' => sub($c) {
	my $uuid = $c->param('uuid') || '';
	my $field = $c->param('field') || '';
	my $value = $c->param('value');
	$value = '' unless defined $value;
	my $clients = &subs::oauth_clients();
	my ($client) = grep { ($_->{'uuid'} || '') eq $uuid } @{$clients};
	return $c->render(json => { result => 'no client' }) unless $client;
	return $c->render(json => { result => 'bad field' }) unless $field =~ /^(name|provider|client_id|client_secret|tenant|scope)$/;
	$value = &subs::note_encrypter(&subs::session_suds($c), $value) if $field eq 'client_secret';
	$client->{$field} = $value;
	&subs::oauth_clients_store($clients);
	$c->render(json => { result => 'ok' });
};
post '/manager/configure/oauth_client/remove' => sub($c) {
	my $uuid = $c->param('uuid') || '';
	my $clients = &subs::oauth_clients();
	@{$clients} = grep { ($_->{'uuid'} || '') ne $uuid } @{$clients};
	&subs::oauth_clients_store($clients);
	$c->render(json => { result => 'ok' });
};

# ---- DNS credentials (Configure -> Plat -> DNS) ----------------------------
# The provider a certificate is issued through. A wildcard can only be proved
# by DNS-01, which needs no inbound port - the only challenge a machine behind
# NAT can pass. The token is sealed with the house key, the same as an OAuth
# client secret, so it syncs as ciphertext and is never shown again.
get '/manager/configure/dns_panel' => sub($c) {
	$c->render(text => $c->render_to_string('configure/dns_clients'));
};

post '/manager/configure/dns_client/add' => sub($c) {
	my $clients = &tls::dns_clients();
	push @{$clients}, { uuid => &subs::random_string_creator(15), name => 'New provider', provider => 'cloudflare', zone => '' };
	&tls::dns_clients_store($clients);
	$c->render(json => { result => 'ok' });
};

post '/manager/configure/dns_client/save' => sub($c) {
	my $uuid = $c->param('uuid') || '';
	my $field = $c->param('field') || '';
	my $value = $c->param('value');
	$value = '' unless defined $value;
	my $clients = &tls::dns_clients();
	my ($client) = grep { ($_->{'uuid'} || '') eq $uuid } @{$clients};
	return $c->render(json => { result => 'no client' }) unless $client;
	return $c->render(json => { result => 'bad field' }) unless $field =~ /^(name|provider|zone|token|key|secret)$/;
	if ($field =~ /^(?:token|key|secret)$/) {
		return $c->render(json => { result => 'empty' }) unless length $value;
		$value = &tls::dns_seal($value, &subs::session_suds($c));
	}
	$client->{$field} = $value;
	# A different provider cannot use the old one's secrets: drop them so a
	# Cloudflare token is never sent to GoDaddy by accident.
	if ($field eq 'provider') {
		foreach my $k ( qw/token key secret/ ) { $client->{$k} = ''; }
	}
	&tls::dns_clients_store($clients);
	$c->render(json => { result => 'ok' });
};

post '/manager/configure/dns_client/remove' => sub($c) {
	my $uuid = $c->param('uuid') || '';
	my $clients = &tls::dns_clients();
	@{$clients} = grep { ($_->{'uuid'} || '') ne $uuid } @{$clients};
	&tls::dns_clients_store($clients);
	$c->render(json => { result => 'ok' });
};

post '/manager/configure/dns_client/test' => sub($c) {
	my $client = &tls::dns_client($c->param('uuid') || '');
	return $c->render(json => { result => 'no client' }) unless $client;
	my ($ok, $message) = &tls::dns_check($client);
	$c->render(json => { result => ($ok ? 'ok' : 'error'), message => $message });
};

# Cloudflare is the one provider the AI panel also holds a token for, so either
# direction copies it, sealed. No other provider's credential is shared.
post '/manager/configure/dns_client/from_ai' => sub($c) {
	my $client = &tls::dns_client($c->param('uuid') || '');
	return $c->render(json => { result => 'no client' }) unless $client;
	return $c->render(json => { result => 'error', message => 'Cloudflare only' }) unless ($client->{'provider'} || '') eq 'cloudflare';
	my $suds = &subs::session_suds($c);
	my $stored = &subs::setting_grabber({ app => 'mail', setting => 'cloudflare_token' });
	return $c->render(json => { result => 'error', message => 'no Cloudflare token under Plat -> AI' }) unless length $stored;
	my $plain = eval { &subs::note_decrypter($suds, $stored) } || '';
	$plain = $stored unless length $plain;
	my $clients = &tls::dns_clients();
	my ($row) = grep { ($_->{'uuid'} || '') eq $client->{'uuid'} } @{$clients};
	$row->{'token'} = &tls::dns_seal($plain, $suds);
	&tls::dns_clients_store($clients);
	$c->render(json => { result => 'ok' });
};

post '/manager/configure/dns_client/to_ai' => sub($c) {
	my $client = &tls::dns_client($c->param('uuid') || '');
	return $c->render(json => { result => 'no client' }) unless $client;
	return $c->render(json => { result => 'error', message => 'Cloudflare only' }) unless ($client->{'provider'} || '') eq 'cloudflare';
	my $plain = &tls::dns_plain($client->{'token'});
	return $c->render(json => { result => 'error', message => 'save a token first' }) unless length $plain;
	my $suds = &subs::session_suds($c);
	&subs::setting_setter({ app => 'mail', setting => 'cloudflare_token', value => &subs::note_encrypter($suds, $plain) });
	$c->render(json => { result => 'ok' });
};

# ---- the house's public names ----------------------------------------------
# config.json's `domain` stays the loopback the house calls itself on. These two
# routes own the public side: the zone (which is also the WebAuthn RP ID) and the
# name each machine answers on, keyed by signatorial so one machine can name all
# of them.
post '/manager/configure/domain/house' => sub($c) {
	my $v = $c->param('domain') || '';
	$v =~ s/^\s+|\s+$//g;
	$v =~ s{^https?://}{}i;
	$v =~ s{/.*$}{};
	$v =~ s{:\d+$}{};
	return $c->render(json => { result => 'error', message => 'a domain like example.com' }) unless $v =~ /^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/i;
	$v = lc $v;
	&subs::setting_setter({ app => '__president', setting => 'house_domain', device => 'all', value => $v });
	$c->render(json => { result => 'ok', domain => $v });
};

post '/manager/configure/domain/host' => sub($c) {
	my $sig = $c->param('signatorial') || '';
	my $host = $c->param('host') || '';
	$host =~ s/^\s+|\s+$//g;
	$host =~ s{^https?://}{}i;
	$host =~ s{/.*$}{};
	$host =~ s{:\d+$}{};
	$host = lc $host;
	my $house = &subs::house_domain();
	return $c->render(json => { result => 'error', message => 'set the house domain first' }) unless length $house;
	$sig = lc $sig;
	return $c->render(json => { result => 'error', message => 'not a signatorial' }) unless $sig =~ /^[0-9a-f]{8,64}$/;
	if (length $host) {
		return $c->render(json => { result => 'error', message => 'must be under ' . $house }) unless $host eq $house || $host =~ /\.\Q$house\E$/;
		return $c->render(json => { result => 'error', message => 'letters, digits, dots and hyphens only' }) unless $host =~ /^[a-z0-9.-]+$/;
	}
	my $map = &subs::device_hosts();
	if (length $host) { $map->{$sig} = $host; }
	else { delete $map->{$sig}; }
	&subs::setting_setter({ app => '__president', setting => 'device_hosts', device => 'all', value => encode_json($map) });
	$c->render(json => { result => 'ok', host => $host });
};

# ---- passkeys (WebAuthn) ---------------------------------------------------
# Registration needs a signed-in session and a person; login is the one thing
# that must work before anyone is signed in, so those two routes are public in
# app_public_path. A passkey session is marked webauthn so the app gate admits
# it: a key held by the platform, bound to this house's origin, is a stronger
# door than a ticket and is exactly what the gate exists to protect.
sub webauthn_person($c) {
	my $uuid = $c->session('person_uuid') || '';
	if (length $uuid) {
		my $p = &subs::db_select('people', undef, { uuid => $uuid, status => 'active' })->hash;
		return $p if $p;
	}
	my $dev = $c->session('app_device') || $c->session('device_uuid') || '';
	if (length $dev) {
		my $p = &subs::person_for_device($dev);
		return $p if $p;
	}
	return undef;
}

get '/manager/webauthn/list' => sub($c) {
	return $c->render(json => { ok => 0, error => 'not signed in' }) unless ($c->session('authentication') || '') eq 'approved';
	my $p = &webauthn_person($c);
	my @out = map {
		{
			id          => $_->{'id'},
			name        => $_->{'name'} || 'Passkey',
			person_uuid => $_->{'person_uuid'} || '',
			person_name => $_->{'person_name'} || '',
			created     => $_->{'created'} || 0,
			last_used   => $_->{'last_used'} || 0,
			mine        => ($p && ($_->{'person_uuid'} || '') eq $p->{'uuid'}) ? 1 : 0,
		}
	} @{ &webauthn::credentials() };
	$c->render(json => {
		ok          => 1,
		rp          => &webauthn::rp_id(),
		person      => ($p ? { uuid => $p->{'uuid'}, name => $p->{'name'} } : undef),
		credentials => \@out,
	});
};

post '/manager/webauthn/register/begin' => sub($c) {
	return $c->render(json => { ok => 0, error => 'not signed in' }) unless ($c->session('authentication') || '') eq 'approved';
	my $p = &webauthn_person($c);
	return $c->render(json => { ok => 0, error => 'this device is not assigned to a person yet - assign it in Security -> People first' }) unless $p;
	my $rp = &webauthn::rp_id();
	return $c->render(json => { ok => 0, error => 'set the house domain first (Configure -> Plat -> DNS)' }) unless length $rp;
	my $challenge = &webauthn::challenge_put('register', { person_uuid => $p->{'uuid'} });
	my @exclude = map { { type => 'public-key', id => $_->{'id'}, transports => [ qw(internal hybrid) ] } }
		grep { ($_->{'person_uuid'} || '') eq $p->{'uuid'} } @{ &webauthn::credentials() };
	$c->render(json => {
		ok => 1,
		publicKey => {
			rp => { name => 'JawnOS', id => $rp },
			user => { id => &webauthn::user_handle($p->{'uuid'}), name => $p->{'name'}, displayName => $p->{'name'} },
			challenge => $challenge,
			pubKeyCredParams => [ { type => 'public-key', alg => -7 }, { type => 'public-key', alg => -8 } ],
			timeout => 120000,
			attestation => 'none',
			authenticatorSelection => { residentKey => 'preferred', userVerification => 'preferred' },
			excludeCredentials => \@exclude,
		},
	});
};

post '/manager/webauthn/register/finish' => sub($c) {
	return $c->render(json => { ok => 0, error => 'not signed in' }) unless ($c->session('authentication') || '') eq 'approved';
	my $p = &webauthn_person($c);
	return $c->render(json => { ok => 0, error => 'no person' }) unless $p;
	my $cd = $c->param('client_data') || '';
	my $jd = eval { decode_json(&webauthn::b64u_decode($cd)) } || {};
	my $challenge = $jd->{'challenge'} || '';
	my $payload = &webauthn::challenge_take('register', $challenge);
	return $c->render(json => { ok => 0, error => 'the challenge expired - try again' }) unless $payload && ($payload->{'person_uuid'} || '') eq $p->{'uuid'};
	my ($reg, $err) = &webauthn::verify_registration($cd, $c->param('attestation'), $challenge, &webauthn::origin_of($c));
	return $c->render(json => { ok => 0, error => $err }) unless $reg;
	my $name = $c->param('name') || 'Passkey';
	$name =~ s/^\s+|\s+$//g;
	$name = 'Passkey' unless length $name;
	$name = substr($name, 0, 60);
	my $list = &webauthn::credentials();
	@{$list} = grep { ($_->{'id'} || '') ne $reg->{'id'} } @{$list};
	push @{$list}, {
		id          => $reg->{'id'},
		key         => $reg->{'key'},
		person_uuid => $p->{'uuid'},
		person_name => $p->{'name'},
		name        => $name,
		sign_count  => $reg->{'sign_count'},
		aaguid      => $reg->{'aaguid'},
		transports  => 'internal,hybrid',
		created     => &subs::rightNow(),
		last_used   => 0,
	};
	&webauthn::credentials_store($list);
	$log->info('webauthn: registered a passkey for ' . $p->{'name'} . ' (' . $reg->{'id'} . ')');
	$c->render(json => { ok => 1, id => $reg->{'id'} });
};

post '/manager/webauthn/remove' => sub($c) {
	return $c->render(json => { ok => 0, error => 'not signed in' }) unless ($c->session('authentication') || '') eq 'approved';
	my $p = &webauthn_person($c);
	my $id = $c->param('id') || '';
	return $c->render(json => { ok => 0, error => 'no person' }) unless $p;
	my $list = &webauthn::credentials();
	my ($cred) = grep { ($_->{'id'} || '') eq $id } @{$list};
	return $c->render(json => { ok => 0, error => 'no such passkey' }) unless $cred;
	return $c->render(json => { ok => 0, error => 'that passkey belongs to someone else' }) unless ($cred->{'person_uuid'} || '') eq $p->{'uuid'};
	@{$list} = grep { ($_->{'id'} || '') ne $id } @{$list};
	&webauthn::credentials_store($list);
	$log->info('webauthn: removed a passkey for ' . $p->{'name'});
	$c->render(json => { ok => 1 });
};

post '/manager/webauthn/login/begin' => sub($c) {
	my $rp = &webauthn::rp_id();
	my $list = &webauthn::credentials();
	return $c->render(json => { ok => 0, error => 'no passkeys on this house' }) unless length $rp && scalar @{$list};
	my $challenge = &webauthn::challenge_put('login', {});
	my @allow = map { { type => 'public-key', id => $_->{'id'}, transports => [ qw(internal hybrid) ] } } @{$list};
	$c->render(json => {
		ok => 1,
		publicKey => {
			challenge => $challenge,
			rpId => $rp,
			timeout => 120000,
			userVerification => 'preferred',
			allowCredentials => \@allow,
		},
	});
};

post '/manager/webauthn/login/finish' => sub($c) {
	my $ip = $c->tx->remote_address || '?';
	my $fails = &subs::db_query('select count(*) as n from cache where context = ? and uuid like ? and server_time > ?', 'webauthn_fail', $ip . ':%', &subs::rightNow() - 300000)->hash->{'n'} || 0;
	return $c->render(json => { ok => 0, error => 'too many attempts - wait five minutes' }) if $fails >= 10;
	my $id = $c->param('id') || '';
	my $cred = &webauthn::credential_by_id($id);
	if (!$cred) { &subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'webauthn_fail', app => '__president', server_time => &subs::rightNow(), timestamp => &subs::rightNow() }); return $c->render(json => { ok => 0, error => 'no such passkey' }); }
	my $cd = $c->param('client_data') || '';
	my $jd = eval { decode_json(&webauthn::b64u_decode($cd)) } || {};
	my $challenge = $jd->{'challenge'} || '';
	my $payload = &webauthn::challenge_take('login', $challenge);
	return $c->render(json => { ok => 0, error => 'the challenge expired - try again' }) unless $payload;
	my ($res, $err) = &webauthn::verify_assertion($cred, $cd, $c->param('auth_data'), $c->param('signature'), $challenge, &webauthn::origin_of($c));
	if (!$res) {
		&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'webauthn_fail', app => '__president', server_time => &subs::rightNow(), timestamp => &subs::rightNow() });
		$log->info('webauthn: login refused for ' . $id . ' from ' . $ip . ': ' . $err);
		return $c->render(json => { ok => 0, error => $err });
	}
	my $list = &webauthn::credentials();
	foreach my $row ( @{$list} ) {
		next unless ($row->{'id'} || '') eq $id;
		$row->{'sign_count'} = $res->{'sign_count'};
		$row->{'last_used'} = &subs::rightNow();
	}
	&webauthn::credentials_store($list);
	my $p = &subs::db_select('people', undef, { uuid => $cred->{'person_uuid'}, status => 'active' })->hash;
	my $now = &subs::rightNow();
	my ($db, $database) = &subs::database_grabber();
	my $warranty = &subs::ago_calc(&subs::setting_grabber({ app => 'me', setting => 'login_warranty' }) || '-12h', $now);
	$c->session(authentication => 'approved');
	$c->session(webauthn => 1);
	$c->session(source => 'webauthn');
	$c->session(bootstrap => undef);
	$c->session(person_uuid => $cred->{'person_uuid'});
	$c->session(name => ($p ? $p->{'name'} : $cred->{'person_name'}));
	$c->session(privilege => ($p && $p->{'privilege'}) ? $p->{'privilege'} : 'guest');
	$c->session(warranty => $warranty);
	$c->session(server_time => $now);
	$c->session(string => &subs::random_string_creator());
	$c->session(database => $database) if $database;
	my $suds = eval { &subs::suds_grabber() };
	$c->session(suds_id => &subs::suds_id($suds)) if $suds;
	$c->session('app' => undef);
	$c->session('app_device' => undef);
	&subs::db_query('delete from cache where context = ? and uuid like ?', 'webauthn_fail', $ip . ':%');
	$log->info('webauthn: login for ' . ($p ? $p->{'name'} : $cred->{'person_name'} || '?') . ' from ' . $ip . ' clone=' . ($res->{'clone'} ? 1 : 0));
	$c->render(json => { ok => 1, redirect => '/manager', person => ($p ? $p->{'name'} : $cred->{'person_name'}), clone => ($res->{'clone'} ? 1 : 0) });
};

# Issue or renew from the panel. Local only and signatorial-gated: the run
# writes DNS records and restarts the tree when the certificate changes.
post '/manager/tls/issue' => sub($c) {
	my $sig = $c->param('signatorial') || '';
	return $c->render(json => { ok => 0, error => 'not authorised' }) unless length $sig && $sig eq &subs::signatorial_designer();
	my $ip = $c->tx->remote_address || '';
	return $c->render(json => { ok => 0, error => 'local only' }) unless $ip eq '127.0.0.1' || $ip eq '::1' || $ip eq '::ffff:127.0.0.1';
	&tls::tls_status_write({ at => POSIX::strftime('%Y-%m-%d %H:%M', localtime), ok => 0, message => 'issuing' });
	&subs::subprocessor(sub {
		system($^X, 'scripts/tls_issue.pl', '--renew');
	}, { name => 'tls issue' });
	$c->render(json => { ok => 1 });
};

get '/manager/tls/status' => sub($c) {
	$c->render(json => &tls::tls_status_read());
};

post '/manager/configure/me_setting' => sub($c) {
	my $value = $c->param('value');
	if ($value =~ /\%$/gi) {
		$value =~ s/\%$//gi;
		$value = ($value / 100) + 1;
	}
	my $setting = &subs::setting_setter({
		app => 'me',
		setting => $c->param('setting'),
		value => $value,
		device => $c->param('device'),
		timestamp => $c->param('timestamp')
	});
	$c->render(json => $setting);
};


sub me_setting_list() {
	my ($db,$database,$sql) = &subs::database_grabber();

	my @settings = qw/mugshot log_me my_name home_plate currency tax information budget_alarm computer_name unit activity_timeout login_warranty warranty room_count duration worth pos advertise_watching gallery_appts/;
	my $settings = {};

	foreach my $dt ( @gb::device_types ) {
		foreach my $s (@settings) {
			my $res = eval {return &subs::db_select('settings', ['value'], { app => 'me', setting => $s, device => $dt })->hash->{value} };
			$settings->{$dt}->{$s} = $res;
		}
	}
	return $settings;
}

sub store_setting_list() {
	my ($db,$database,$sql) = &subs::database_grabber();

	my @settings = qw/store_name slogan logo markup sales_tax address email phone tax_number doc_notes payment_due_date/;
	my $settings = {};

	foreach my $dt ( @gb::device_types ) {
		foreach my $s (@settings) {
			my $res = eval {return &subs::db_select('settings', ['value'], { app => 'me', setting => $s, device => $dt })->hash->{value} };
			$settings->{$dt}->{$s} = $res;
		}
	}
