# A typed contact list (phones/emails): the editor the nfc list wears, one row
# per number or address with a type - mobile, home, work, or a custom label. The
# uuid names the row so a field change and a delete both find the same one, and
# a uuid nobody holds yet starts a new row.
sub contact_list_row_finder {
	my ($app, $list) = @_;
	my $rows = eval { return decode_json &subs::setting_grabber({ app => $app, setting => $list }) } || [];
	$rows = [ $rows ] if ref $rows eq 'HASH';
	$rows = [] unless ref $rows eq 'ARRAY';
	return $rows;
}
post '/manager/configure/contact/setting' => sub($c) {
	my $app = $c->param('app');
	my $list = ($c->param('list') || '') eq 'emails' ? 'emails' : 'phones';
	my $field = $c->param('field') || '';
	my $value = $c->param('value');
	$value = '' unless defined $value;
	my $uuid = $c->param('uuid') || '';
	return $c->render(json => { error => 'bad field' }) unless grep { $field eq $_ } qw/type label value/;

	my $rows = &contact_list_row_finder($app, $list);
	my ($row) = grep { ($_->{'uuid'} || '') eq $uuid } @{$rows};
	unless ($row) {
		$row = { uuid => $uuid, type => 'mobile', label => '', value => '' };
		push @{$rows}, $row;
	}
	$row->{$field} = $value;
	&subs::setting_setter({ app => $app, setting => $list, value => encode_json $rows });
	$c->render(json => $row);
};

post '/manager/configure/contact/delete' => sub($c) {
	my $app = $c->param('app');
	my $list = ($c->param('list') || '') eq 'emails' ? 'emails' : 'phones';
	my $uuid = $c->param('uuid') || '';
	my $rows = &contact_list_row_finder($app, $list);
	my $before = scalar @{$rows};
	@{$rows} = grep { ($_->{'uuid'} || '') ne $uuid } @{$rows};
	&subs::setting_setter({ app => $app, setting => $list, value => encode_json $rows }) if scalar @{$rows} != $before;
	$c->render(json => { app => $app, uuid => $uuid });
};

post '/manager/nfc/read' => sub($c) {
	my $jmessage = $c->param('message');
	my $serial = $c->param('serial');
	my $last_write = $c->param('last_write');
	my $timestamp = $c->param('timestamp');
	my $benign = $c->param('benign');
	my $response = { status => 'unknown' };
	my $uuid = $c->param('uuid') || &subs::random_string_creator(25);
	$c->param('uuid' => $uuid );
	# A relayed copy is a peer's copy of the tap. It carries the reader's action
	# (nfc_actions, keyed by the message uuid), so it applies the same start or
	# stop the reading machine chose instead of recomputing one from its own,
	# possibly unsynced, toggle state. Non-stop actions write under the tap uuid,
	# so every copy names the same row and the mesh converges on it rather than
	# collecting duplicates.
	my $relayed = ($c->param('relay_id') || ($c->param('remoted') || '') eq 'yes' || ($c->param('dissemination') || '') eq 'yes' || $c->param('source_signatorial')) ? 1 : 0;
	my $relayed_actions = ($relayed && $c->param('nfc_actions')) ? (eval { decode_json $c->param('nfc_actions') } || {}) : {};
	my $actions = {};
	my $msg = eval { return decode_json $jmessage } || [];

	foreach my $message ( @{$msg} ) {
		if (ref $message eq 'HASH' && defined $message->{'crest_code'}) {
			my $result = &people_crest_import_code($c, $message->{'crest_code'});
			$response->{'status'} = $result->{'ok'}
				? ($result->{'construct_app'}
					? ('Crest: ' . ($result->{'construct_name'} || ''))
					: ('Crest imported: ' . ($result->{'crest'}->{'name'} || '')))
				: ('Crest import failed: ' . ($result->{'error'} || 'unknown'));
			if ($result->{'ok'}) {
				$response->{'crest_uuid'} = $result->{'crest'}->{'uuid'} || '';
				$response->{'crest_known'} = $result->{'known'} ? 1 : 0;
				$response->{'construct_app'} = $result->{'construct_app'} if length($result->{'construct_app'} || '');
			}
			next;
		}
		my $nfcs = &subs::db_query('select * from settings where setting=? and value like ? and device=?', 'nfc', '%' . $message->{'uuid'} . '%', &subs::device_setter())->hashes->[0];
		my $app = $nfcs->{'app'};
		my $settings = &subs::settings_grabber({ app => $app });

		my $nfc = eval { return decode_json $nfcs->{'value'} } || [];
		my ($n) = grep { $_->{'uuid'} eq $message->{'uuid'} } @{$nfc};
		$n->{'serials'} = [] unless $n->{'serials'};
		if ($n->{'uuid'}) {
			if ($timestamp - $last_write < 1000) {
				$response->{'status'} = 'writing serial';


				push @{$n->{'serials'}}, $serial unless grep { $_ eq $serial } @{$n->{'serials'}};
				$response->{'serials'} = $n->{'serials'};
			} else {
				if (1 == 1 || grep { $_ eq $serial } @{$n->{'serials'}}) {
					my ($type,$target);
					if ($relayed) {
						my $action = $relayed_actions->{$message->{'uuid'}} || {};
						$type = $action->{'type'};
						$target = $action->{'target'};
						# a stop with no named session has nothing to close, and the
						# unnamed fallback could close a different, stale row here
						$type = undef if $type && $type eq 'stop' && !$target;
					}
					else {
						$type = $n->{'control'};
						my $tog = &subs::appt_toggle_checker($app);
						if ($type eq 'start' || $type eq 'record') {
							# The house keeps one tag per app, and the same tag is the stop:
							# a tap while the app's session is open closes it (the stop names
							# that session below, so it never sweeps another app's rows).
							# With nothing open the tap starts as usual.
							if ($tog eq 'on') {
								$type = 'stop';
								$tog = 'off';
							}
							else {
								$tog = 'on';
							}
						}
						elsif ($type eq 'command') {
							if ($tog eq 'on') {
								if ($settings->{'kill'}) {
									$type = 'kill';
									$tog = 'off';
								}
								else {
									$tog = 'off';
									$type = 'stop';
								}
							}
							else {
								$tog = 'on';
							}
						}
						# A stop names the session the header shows (the newest open row),
						# never the tag/message uuid. Every other action uses the tap uuid,
						# which travels with the relay so every machine writes one row.
						$target = ($type eq 'stop') ? &subs::open_session_uuid($nfcs->{'app'}) : $uuid;
					}

					if ($type) {
						$response->{'status'} = $nfcs->{'app'} . ' ' . $type;
						if ($benign ne 'on') {
							$n->{'taps'} += 1;
							$actions->{$message->{'uuid'}} = { type => $type, target => $target } unless $relayed || ($type eq 'stop' && !$target);
							&appointment_writer($c, {
								app => $nfcs->{'app'},
								type => $type,
								timestamp => $timestamp,
								uuid => $target
							});
						}
					}
				}
			}
			my $jn = encode_json $nfc;
			&subs::setting_setter({ app => $nfcs->{'app'}, setting => 'nfc', value => $jn });
		}
	}
	# the actions are known now, so a peer can apply exactly these; a benign read
	# relays an empty map and acts nowhere. The map rides the relay explicitly:
	# $c->param writes a combined copy that remote_relay_request does not read.
	my $relay_actions = $relayed ? $c->param('nfc_actions') : encode_json $actions;
	my $relay_extra = { dissemination => 'yes' };
	$relay_extra->{'nfc_actions'} = $relay_actions if defined $relay_actions;
	&subs::subprocessor(sub {
    Mojo::IOLoop->reset;
		&remote_relay_request($c, $relay_extra);
	}, { name => 'nfc remote relay' });
	$c->render(json => $response);
};

post '/manager/nfc/write' => sub($c) {
	my $uuid = $c->param('uuid');
	my $app = $c->param('app');
	my $type = $c->param('type');
	my $signatorial = $c->param('signatorial');
	my $nfc = eval { return decode_json &subs::setting_grabber({ app => $app, setting => 'nfc' }) } || [];

	my ($n) = grep { $_->{'uuid'} eq $uuid } @{$nfc};
	push @{$n->{'serials'}}, { timestamp => &subs::rightNow(), signatorial => $signatorial };


	$c->render(json => { nfc => $n });
};


post '/manager/leave' => sub($c) {
	&leave($c);
	my ($db,$database,$sql) = &subs::database_grabber();
	my $restore_list;
	unless (-e $database && -s $database > 5000) {
		$restore_list = &subs::restore_list();
	}
	$database = '';
	unless (-e $database) {
		if ($c->param('restore_list')) {
			my $list = $c->param('restore_list');
			$restore_list = &subs::restore_list($list);
			@{$restore_list} = grep { $_->{'filename'} =~ /enc$/gi } @{$restore_list};
		}
	}

	$c->render(
		template => 'gate',
		layout => 'gate',
		restore_list => $restore_list,
		# the gate carries no home path: it is shown before anyone has signed in, and
		# a field prefilled with the person's own directory hands a visitor their name
		start_dir => '',
		config => { 'gate' => {'background_colour' => 'grey' } },
	);
};

# A public Gate page. This is what an app with no key opens to pair itself:
# the app gate lets /gate through, and this route deliberately does not run
# authentication_passer, so the pairing door and the recovery door are reachable
# before any session (and while the house is locked). Without it the app-required
# page's "Pair this device" link was a Mojolicious 404.
get '/gate' => sub($c) {
	my ($db,$database) = &subs::database_grabber();
	my $restore_list = [];
	unless (-e $database) {
		if ($c->param('restore_list')) {
			my $list = $c->param('restore_list');
			$restore_list = &subs::restore_list($list);
			@{$restore_list} = grep { $_->{'filename'} =~ /enc$/gi } @{$restore_list};
		}
	}
	$c->render(
		template => 'gate',
		layout => 'gate',
		restore_list => $restore_list,
		start_dir => '',
		config => { 'gate' => { 'background_colour' => ($config->{'gate'}->{'background_colour'} || 'grey') } },
	);
};

sub leave($c) {
	if (!$c) {
		$c = &subs::controller_builder();
		$c->session('authentication', &subs::suds_grabber());
		$c->req->url->path('/manager/leave');
	}
	my ($db,$database,$sql) = &subs::database_grabber();
	&subs::say_it('leave');
	&remote_relay_request($c, { mode => 'emergency' });
	my $timestamp = $c->param('timestamp') || &subs::rightNow();
	$c->param('reason' => 'leave');
	my $server_time = &subs::rightNow();

	&subs::db_delete('settings',{app => '__DEBRIEFING__', device => $device});
	&subs::db_delete('settings',{app => 'keyboard'});
	&subs::db_delete('settings',{app => 'watch', setting => 'patience' });
#	&subs::db_delete('remote_machines');
	my $hostname = `hostname`;
	chomp($hostname);
	if ($c->param('debriefer')) {
		my $d = $c->param('debriefer');
		my $settings = decode_json $d;
		&subs::db_insert('settings', {
			app => '__DEBRIEFING__',
			timestamp => $timestamp,
			setting => $hostname,
			value => $d,
			device => $device,
			uuid => &subs::random_string_creator(20)
		});
	}
	my $warranty = &subs::ago_calc(&subs::setting_grabber({ app => 'customs', setting => 'warranty' }) || &subs::setting_grabber({ app => 'me', setting => 'warranty' }) || '-10d', $timestamp);
	&subs::db_insert('appointments', { warranty => $warranty, uuid => &subs::random_string_creator(40), app => "customs", type => "depart", timestamp => $timestamp, server_time => $server_time });
	&subs::backup_now($c);
	`shred -u $database`;
	`shred -u $database-shm`;
	`shred -u $database-wal`;
	`shred -u $logfile`;
	delete $c->session->{'authentication'};
	delete $c->session->{'database'};
	delete $c->session->{'suds_id'};
	delete $c->session->{'device_uuid'};
	delete $c->session->{'reject_count'};
	delete $c->session->{'browser_tab_id'};
	delete $c->session->{'browser_tab'};
	$gb::suds = undef;

	$gb::database_holder = undef;
	&subs::say_it('Goodbye');
	$sql = undef;
}

post '/manager/lock_session' => sub($c) {
	my $scope = $c->param('scope') || '';
	my $posted = $c->param('device_uuid') || '';
	# The page identifies with the uuid in its localStorage, which can be newer
	# than the session's (a re-pair, or another tab's pairing). Locking the
	# session's uuid then targeted a screen the page no longer claimed, and the
	# overlay's target check ignored it - "I locked it and still have access".
	# Adopt the posted, roster-validated device so the lock and the page agree.
	if ($posted && &subs::db_select('paired_devices', undef, { uuid => $posted, status => 'active' })->hashes->[0]) {
		$c->session('device_uuid' => $posted);
	}
	&lock_session($c, 1, $scope);
	# a single-screen lock stays on that screen; only an explicit whole-house
	# lock is handed to the peers
	&remote_relay_request($c) if $scope eq 'all';
	# The screen that pressed the lock shows its own overlay from this reply.
	# The websocket push is the cross-screen path, but on a handheld its unix
	# socket can be owned by another worker, so the send silently went nowhere
	# and the screen that locked stayed open until a reload ("it didn't lock").
	my $target = $scope eq 'all' ? '' : ($c->session('device_uuid') || $posted || '');
	my $html = $c->render_to_string(
		template => 'locked_screen',
		target => $target,
		fingerprint => (&fingerprint_available() && &padlock_request_is_local($c)) ? 1 : 0,
		biometric => &biometric_enrolled_for($c->session('device_uuid') || $target)
	);
	$c->render(json => { ok => 1, target => $target, html => $html });
};
sub lock_session($c, $explicit = 0, $scope = '') {
	$scope ||= '';
	my $now = &subs::rightNow();
	my $device_uuid = $c->session('device_uuid') || '';
	# The screen that is locking, so a device lock closes only its own windows.
	my $browser_tab_id = $c->session('browser_tab_id') || $c->param('browser_tab_id') || '';
	# pl_time is a house-wide stamp, so it is sealed under the house key, not a
	# session's copy: a fresh tab must be able to read the same timer.
	my $suds = &subs::suds_grabber() || &subs::session_suds($c) || $gb::suds;
	my ($db) = &subs::database_grabber();

	# The phone key talks to the server while the padlock is up. Those calls are
	# not a fresh lock: running the lock again would replace the screen under the
	# person's hand and re-expire the session a screen that just turned it had
	# already opened.
	my $path = $c->req->url->path;
	return 0 if ($path eq '/manager/security/padlock_phone_show' ||
		$path eq '/manager/security/padlock_request_cancel' ||
		$path eq '/manager/security/media_lock' ||
		$path eq '/manager/security/padlock_challenge' ||
		$path eq '/manager/security/padlock_unlock' ||
		$path eq '/manager/security/padlock_key_show_peer' ||
		$path eq '/manager/security/padlock_state' ||
		$path eq '/manager/security/fingerprint_unlock' ||
		$path eq '/manager/security/fingerprint_unlock_status' ||
		$path eq '/manager/security/biometric_challenge' ||
		$path eq '/manager/security/biometric_unlock' ||
		$path eq '/manager/security/padlock_key');

	# A request that started while the lock screen was up can reach here after
	# another screen has already turned the lock. Re-read the stored time (the
	# request's setting memo may be older than that unlock) and leave it be.
	unless ($explicit) {
		my $fresh_row = &subs::db_query("select value from settings where app = ? and setting = ? order by server_time desc limit 1", '__president', 'pl_time')->hashes->[0];
		# No stamp at all means this machine has never been locked since the gate
		# was set. That is open, not an expired window: starting a lock here is
		# what made a peer with a fresh database show the whole house locked.
		return 0 unless $fresh_row;
		my $fresh = &padlock_time_value($suds, $fresh_row->{'value'}) || 0;
		return 0 if $fresh > $now;
	}

	# An inactivity lock on a screen with no device identity has no target. It
	# used to be treated as a whole-house lock, which re-stamped pl_time on
	# every request, deleted every device's unlock row, and closed the same app
	# windows again and again. The page's own padlock_state adopts its device;
	# until then, leave this request alone.
	return 0 if (!$explicit && !$device_uuid);

	# A single tap locks this device only. A double tap (scope=all) or the
	# inactivity timeout is the whole-house lock. A screen opened after a
	# whole-house lock carries its own timer, so the overlay skips it. (An
	# inactivity lock from a screen with no identity returned above; without
	# that, it re-locked the house, and closed windows, on every request.)
	my $whole_house = (!$explicit || $scope eq 'all' || !$device_uuid) ? 1 : 0;
	my $close_tab = $whole_house ? undef : $browser_tab_id;
	my $overlay_target = '';
	my @unlocked;
	my $activity_timeout = &subs::setting_grabber({ app => 'me', setting => 'activity_timeout' }) || '-2h';
	$activity_timeout = abs &subs::time_abbrev_translator($activity_timeout);
	if ($whole_house) {
		&subs::setting_setter({ app => '__president', setting => 'pl_time', value => $now });
		# a house-wide lock supersedes every screen's own row; a stale row
		# outlives the house stamp and keeps that screen locked forever
		&subs::db_delete('security', { level => 'padlock_device' });
		if ($scope eq 'all') {
			&subs::db_query('delete from settings where app = ? and setting = ?', '__president', 'padlock_device_time');
		}
		else {
			my $open_rows = &subs::db_select('settings', undef, { app => '__president', setting => 'padlock_device_time' })->hashes || [];
			foreach my $r ( @{$open_rows} ) {
				my $d = $r->{'device'} || '';
				next unless $d;
				my $until = eval { &padlock_time_value($suds, $r->{'value'}) } || 0;
				push @unlocked, $d if $until && $until > $now;
			}
		}
	}
	else {
		&subs::setting_setter({ app => '__president', setting => 'pl_time', value => $now + $activity_timeout });
		&subs::db_delete('security', { level => 'padlock_device', uuid => $device_uuid });
		&subs::db_insert('security', { level => 'padlock_device', credential => '', timestamp => $now, server_time => $now, uuid => $device_uuid });
		&padlock_device_clear_time($device_uuid);
		$overlay_target = $device_uuid;
	}
	# A media grant belongs to one screen. A whole-house lock drops every
	# screen's grants on this machine; a single-screen lock drops only its own,
	# so locking here never shuts another screen's or a peer's padlock.
	my @open_media;
	if ($whole_house) {
		my $rows = &subs::db_query('select distinct app from cache where context = ?', 'media_unlock')->hashes || [];
		@open_media = map { $_->{'app'} } @{$rows};
		# a row left by the old house-wide secret still counts as an open one
		foreach my $legacy_app ( @media_unlock_apps ) {
			push @open_media, $legacy_app if &subs::setting_grabber({ app => $legacy_app, setting => 'combo_unlock' });
		}
		&subs::db_query('delete from cache where context = ?', 'media_unlock');
	}
	else {
		my $rows = &subs::db_query('select distinct app from cache where context = ? and device = ?', 'media_unlock', $device_uuid)->hashes || [];
		@open_media = map { $_->{'app'} } @{$rows};
		&media_unlock_clear($device_uuid);
	}
	# the old house-wide secret never stands again; a stale row from before the
	# per-screen grants would otherwise keep a peer's window open
	&subs::db_query('delete from settings where setting = ? and app in (?,?,?)', 'combo_unlock', @media_unlock_apps);
	foreach my $media_app ( @open_media ) {
		next unless grep { $_ eq $media_app } @media_unlock_apps;
		&subs::window_closer($media_app, $close_tab);
	}

	my $player = &subs::cache_get({ app => 'music', context => 'player' });
	if ($player->{'unlocked'} == 1) {
		&subs::cache_delete({ app => 'music', context => 'player' });
		&subs::cache_delete({ app => 'music', context => 'content' });
		&subs::window_closer('music', $close_tab);
	}
	my $websockets = &subs::db_query('select * from websockets','stayingAlive')->hashes;
	my $port = $c->req->url->base->port;

	foreach my $ws ( @{$websockets} ) {
		# A device lock closes only the locking screen's windows; a whole-house
		# lock still closes them everywhere.
		if (!$whole_house && (!$close_tab || ($ws->{'browser_tab_id'} || '') ne $close_tab)) {
			next;
		}
		if ($ws->{'href'} =~ /\Q$port/gi) {
			my $settings = &subs::settings_grabber({ app => $ws->{'app'}, settings => [ 'visibility' ] });
			if ($settings->{'visible'} ne 'checked') {
				&subs::window_closer($ws->{'app'}, $close_tab);
			}
		}
		elsif (!$ws->{'room'}) {
			&subs::db_delete('websockets', { uuid => $ws->{'uuid'} });
		}
	}

	my $padlock = &subs::db_query('select * from security where level = ?', 'padlock')->hashes;

	if (scalar @{$padlock} > 0 && $now > $c->session('last_padlock') + 5000) {
		my $attempts = &subs::note_decrypter(&subs::session_suds($c), &subs::setting_grabber({ app => '__president', setting => 'padlock_pulls' }));
		my $pl = $c->render_to_string(template => 'locked_screen', target => $overlay_target, fingerprint => (&fingerprint_available() && &padlock_request_is_local($c)) ? 1 : 0, biometric => &biometric_enrolled_for($overlay_target || $c->session('device_uuid')));
		my $colour = &subs::random_colour_grabber();
		my $taunt_size = scalar @gb::taunts;
		my $taunts = $gb::taunts[rand($taunt_size)];
		&Websocket::send('server', { padlock => $pl, taunts => $taunts, attempts => $attempts, colour => $colour, target => $overlay_target, unlocked => \@unlocked });
		# A lock shows itself on the screen that locked. It deliberately does NOT
		# broadcast the unlock page to every other device: doing that on every
		# lock (once per five seconds while a locked screen kept talking) pulled
		# phones and laptops onto a black page, added a history entry, and left
		# their images stale. Another device is asked only when the person presses
		# Unlock on the locked screen, which calls padlock_phone_show.
	#	$c->render(template => 'padlock', mode => 'locker');
	#	my $path = $c->req->url->path;
	#	unless $path eq '/manager/security/padlock_pull'
		$c->session('last_padlock' => $now );
	}

	return 1;
}



