		my @jonathans = split "\n";
		my @jawns = [];

		foreach my $jonathan ( @jonathans ) {
			push @jawns, {
				file => $jonathan
			};
		}
	}
	my $advertise_watching = &subs::setting_grabber({ app => 'me', setting => 'advertise_watching' });
