get '/manager/start_menu' => sub($c) {
	my $start_menu = &start_menu_maker($c);
	$c->render(json => $start_menu);
};

# A press in the app menu says what it opened, and the recent list - the app
# menu's front page - is written from it, so the next open leads with it.
post '/manager/start_menu/used' => sub($c) {
	my $recent = &start_menu_used($c->param('used'));
	$c->render(json => { recent => $recent });
};

# The X on a recent item takes the app back off the list, which is only ever
# the cache rewritten without it.
post '/manager/start_menu/forget' => sub($c) {
	my $recent = &start_menu_forget($c->param('forget'));
	$c->render(json => { recent => $recent });
};

# The apps the start menu was last used to open, freshest first. The app menu
# is a recent list and the shelf rail is how everything else is reached, so
# it lives in the president's cache like the System view's snapshot; cache entries are
# per device, so each screen keeps its own list. The warranty is asked for
# outright: __president has no warranty setting, and the fallback resolves to
# "now", which the alarm's cache purge then deletes a minute later.
sub start_menu_recent() {
	my $recent = &subs::cache_get({ app => '__president', context => 'start_menu', subcontext => 'recent' });
	return [ ref $recent eq 'ARRAY' ? @{$recent} : () ];
}

# A press's key is the button's id, or its hint when it has none. It is a
# cache value that the list renders back into the page, so the press and the
# forget both cut it down to plain words first.
sub start_menu_key_clean($key) {
	# Keep the letters of every script: the key names a button in the recent
	# list, and an app called 中文 or Café must not become an empty string.
	$key =~ s/[^\p{L}\p{M}\p{N} _\-]//g;
	$key =~ s/^\s+//; $key =~ s/\s+$//;
	return substr($key, 0, 60);
}

# The freshest ten are kept.
sub start_menu_used($key) {
	$key = &start_menu_key_clean($key);
	return &start_menu_recent() unless length $key;
	my $recent = &start_menu_recent();
	@{$recent} = grep { $_ ne $key } @{$recent};
	unshift @{$recent}, $key;
	pop @{$recent} while scalar @{$recent} > 10;
	&subs::cache_set({ app => '__president', context => 'start_menu', subcontext => 'recent', warranty => '-1y' }, $recent);
	return $recent;
}

# What the X on an item asks for: the app leaves the list, whatever its place.
sub start_menu_forget($key) {
	$key = &start_menu_key_clean($key);
	return &start_menu_recent() unless length $key;
	my $recent = [ grep { $_ ne $key } @{ &start_menu_recent() } ];
	&subs::cache_set({ app => '__president', context => 'start_menu', subcontext => 'recent', warranty => '-1y' }, $recent);
	return $recent;
}

sub start_menu_maker($c) {
	my $returner = {};
	my $menu = $c->param('menu');

	# Opening the System view is what asks the levels loop for quick passes.
	&subs::levels_fast_request() if ($menu || '') eq 'view';
	my $html = $c->render_to_string(
		template => 'start_menu/start_menu',
		parking_lot => &parking_lot_grabber($c),
		config => &subs::config_reader(),
		padlock => &subs::db_select('security', ['level'], { level => 'padlock' })->hashes,
		menu => $menu,
		recent => &start_menu_recent()
	);
	# Static files carry no Cache-Control, so browsers cached the icons
	# heuristically and kept showing stale ones. Version the local images
	# so the start menu always pulls the current set.
	my $v = &subs::rightNow();
	my $set = &subs::icon_set();
	if ($set) {
		$html =~ s{src="(/[^"]*\.(?:png|jpe?g|gif))"}{'src="' . &subs::icon_for($1, $set) . '"'}ge;
	}
	$html =~ s/"([^"]*\.(?:png|jpe?g|gif|svg))"/"$1?v=$v"/g;
	$returner = { html => $html };

	return $returner;
}

sub parking_lot_grabber($c) {
	my $parking_lot = {};
	my $spaces = &subs::db_query('select * from websockets where room is not null')->hashes;

	foreach my $pl ( @{$spaces} ) {
		my $others = &subs::db_select('websockets', undef, { browser_tab_id => $pl->{'browser_tab_id'} })->hashes;
		foreach my $ot ( @{$others} ) {
			if ($ot->{'music_data'}) {
				$pl->{'music_data'} = $ot->{'music_data'};
			}
			elsif ($ot->{'jp_data'}) {
				$pl->{'jp_data'} = $ot->{'jp_data'};
			}
		}
		$parking_lot->{$pl->{'room'}} = $pl;
	}
	return $parking_lot;
}

get '/manager/start_menu/htop_viewer' => sub($c) {
	# The card is on screen: keep the house levels loop on its quick cadence.
	&subs::levels_fast_request();
	my $cache = &subs::cache_get({ app => '__president', context => 'htop', subcontext => 'current' });
	# The card is a house-wide levels view: this machine, every peer that
	# answered the last levels pass, and the embedded boards any of them can
	# see. It reads the cached snapshot so a sleeping board cannot hold the menu.
	my $levels = &subs::levels_snapshot();
	my $html = $c->render_to_string(
		template => 'start_menu/htop',
		cache => $cache,
		levels => $levels
	);
	$c->render(json => { html => $html });
};


sub website_preloader($c) {
	my ($website,$header);

	if ($c->param('app')) {
		my $advertise_watching = &subs::setting_grabber({ app => 'me', setting => 'advertise_watching' });
		my $app = $c->param('app');
		$header = &subs::appt_header_printer({ app => $app });
		my $timestamp = $c->param('timestamp') || &subs::rightNow();
		my $appts = &log_reader({ app => $app, view => 'centre_view', timestamp => $timestamp  });
		$website = $c->render_to_string(
			template => 'appointment_wrapper',
			appts => $appts,
			appointments => [ $app ],
			timestamp => $timestamp,
			device => $device,
			from => 'centre_view',
			config => &subs::config_reader(),
			measures => $gb::measures,
			advertise_watching => $advertise_watching,
			header => $header
		);
		$website = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => $app, contents => $website }, $timestamp);
		$c->stash('website' => $website);
	}
	return ($website,$header);
}


sub pseudonym_maker($context,$app) {
	my $icon_set = &subs::icon_set();
	my $set_key = $context . '.' . $icon_set;
	if (my $ps = &subs::cache_get({ app => 'me', context => 'pseudonyms', subcontext => $set_key })) {
		# the console panel is now called sessions - migrate older cached lists
		my $renamed = 0;
		# names this build no longer ships (the beacon went away), dropped from
		# any list cached before the change
		my %retired = map { $_ => 1 } qw/beacon/;
		my @kept = grep { !$_->{'name'} || !$retired{$_->{'name'}} } @{$ps};
		if (scalar @kept != scalar @{$ps}) { $ps = \@kept; $renamed = 1; }
		foreach my $p ( @{$ps} ) {
			if ($p->{'name'} && $p->{'name'} eq 'console') {
				$p->{'name'} = 'sessions';
				$renamed = 1;
			}
		}
		if ($renamed) { &subs::cache_set({ app => 'me', context => 'pseudonyms', subcontext => $set_key }, $ps); }
		return $ps;
	}
	my $pseudonyms = [
		{ status => 'on', name => "remote_control", icon => "Froggoli", speech => 'Ribbit' },
		{ status => 'on', name => "delorean", icon => "Mr. Sun", speech => 'Run for it Marty!' },
		{ status => 'on', name => "walkboy", icon => "headphones", speech => 'av room' },
		{ status => 'on', name => "keyboard", icon => "keyboard", speech => 'typewriter' },
		{ status => 'on', name => "calculator", icon => "calculator", speech => 'calculator' },
		{ status => 'on', name => "notifications", icon => "bell", speech => 'where are your friends now?' },
		{ status => 'on', name => "sessions", icon => "windows", speech => 'i watch the baytch' },
		{ status => 'on', name => "controller", icon => "heart", speech => 'Run for it Marty!' },
		# the ledger's own types wear the set's glyphs of the same name: a quote,
		# an invoice, the encrypt stamp and the rest of the appointment types
		# that had no pseudonym (they showed no icon in the details and the
		# timeline until now)
		{ status => 'on', name => "invoice", icon => "invoice" },
		{ status => 'on', name => "quote", icon => "quote" },
		{ status => 'on', name => "encrypt", icon => "encrypt" },
		{ status => 'on', name => "assign", icon => "assign" },
		{ status => 'on', name => "reset", icon => "reset" },
		{ status => 'on', name => "software", icon => "software" },
		{ status => 'button', name => 'record', icon => 'record', classmates => "medium_thumb save_appointment", colour => '#ffec1f', place => 'top' },
		{ status => 'button', name => 'text', icon => 'love letter', colour => '#ffec1f', place => 'top' },
		{ status => 'button', name => 'start', icon => 'play', classmates => "medium_thumb save_appointment", colour => '#ffec1f', place => 'top' },
		{ status => 'button', name => 'prev', icon => 'prev', classmates => "medium_thumb time_jump", colour => '#ffec1f', place => 'top' },
