get '/manager/download_file' => sub ($c) {
	my $file = $c->param('file');
	my $app = $c->param('app');
	my $uuid = $c->param('uuid');
	my $timestamp = $c->param('timestamp');
	my $server_time = $c->param('server_time');
	my ($db,$database,$sql) = &subs::database_grabber();
	my $appt = &subs::db_query('select * from appointments where app = ? and uuid = ?', $app, $uuid)->hashes->[0];
	my $encryption_standard = $appt->{'encryption_standard'};
	my $saved_file = eval { return decode_json $appt->{'file'} } || [{}];
	@{$saved_file} = grep { $_->{'f'} eq $file } @{$saved_file};

	my ($data,$filename);
	if (-e $file) {
		if ($file =~ /\.enc$/gi) {
			my $suds = &subs::session_suds($c);
			my $passwords = &subs::db_query('select * from security where level != ? and level != ? order by server_time DESC', 'padlock', 'door');
			my $pwords = $passwords->hashes;

			foreach my $p ( @{$pwords} ) {
				my $secret = &subs::decrypter($suds, $p->{'credential'});
				my $process_data = &subs::openssl_file_read($encryption_standard, $secret, $file, 0, 1);
				my $type_from_data = &subs::plaintext_verdict($process_data);
				if (defined $type_from_data) {
					$data = $process_data;

					my @file = split '/', $file;
					$filename = $file[-1];
					$filename =~ s/\.enc//gi;
					$filename = $saved_file->[0]->{'of'} if $saved_file->[0]->{'of'};
					last;
				}
			}
		}
		else {
			$data = read_file($file);
			my @file = split '/', $file;
			$filename = $file[-1];
			$filename = $saved_file->[0]->{'of'} if $saved_file->[0]->{'of'};
		}
		$c->render_file(data => $data, filename => $filename);
	}
	else {
		$c->render(text => 'Not Found');
	}
};


post '/manager/upload_file' => sub ($c) {
	my ($db,$database,$sql) = &subs::database_grabber();
	my @uploads = @{$c->req->uploads};
	my $timestamp = $c->param('timestamp') - 1;
	my $duration = $c->param('duration');
	my $app = $c->param('app');
	my $uuid = $c->param('uuid') || &subs::random_string_creator(22);
	my $seen_appts = [];
	my $notes;
	my @uploaded_files;
	my @uuids;
	if ($c->param('uuid')) {
		$seen_appts = &subs::db_select('appointments', undef, { uuid => $uuid })->hashes;
		if (scalar @{$seen_appts} > 0) {
			my $appt = $seen_appts->[0];
			my $of = eval { return decode_json $appt->{'file'} } || [];
			push @uploaded_files, @{$of};
			$app = $appt->{'app'};
			$notes = &subs::note_decrypter(&subs::session_suds($c), $appt->{'notes'},$appt->{'server_time'}) . '<br>';
			$timestamp = $appt->{'timestamp'};
		}
	}
	my $returner = { uuid => $uuid, app => $app, timestamp => $timestamp };

	my $upload_type;
	my $linux_file;
	my $resolution = &subs::setting_grabber({ app => 'misc', setting => 'photo_size' } ) || '1920x1080';
	foreach my $u ( @uploads ) {
		my $is_enc = 0;
		my $server_time = &subs::rightNow();
		$timestamp++;
		my $filen = &subs::unformat_name($u->filename);
		my @f = split /\./, $filen;
		if (lc $f[-1] eq 'enc') {
			$is_enc = 1;
			pop @f;
		}
		my $ext = pop @f;
		$filen = join '.', @f;
		my $fn = $filen . '_' . $timestamp . '.' . $ext;

		my $upload = {
			type => $u->headers->content_type,
			path => $u->asset->path,
			filename => $fn,
			size => $u->size,
		};
		$app = $upload->{'filename'} unless $c->param('app');
		$app = &subs::unformat_name($app);
		my $init = &subs::setting_initializer($app,$timestamp);
		$app = $init->{'app'};
		my $app_path = &subs::path_name($app);

		my ($folder,$location,$thumb);

		if ($upload->{'type'} =~ /audio/gi) {
			$upload_type = 'audio';
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'rec_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
		}
		elsif ($upload->{'type'} =~ /video/gi || lc $ext eq 'webm' || lc $ext eq 'avi' || lc $ext eq 'mp4' || lc $ext eq 'mov' || lc $ext eq 'mkv') {
			$upload_type = 'video';
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'video_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
			$thumb = $location . '/.thumbs';

		}
		elsif ($upload->{'type'} =~ /image/gi || lc $ext eq 'jpg' || lc $ext eq 'png') {
			$upload_type = 'image';
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'photo_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
			$thumb = $location . '/.thumbs';
		}
		elsif ($upload->{'type'} =~ /pdf/gi) {
			$upload_type = 'scan';
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'document_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
		}
		elsif ($upload->{'type'} =~ /application/gi) {
			$upload_type = 'software';
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'download_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
		}

		else {
			$folder = &subs::setting_grabber( { app => 'misc', setting => 'download_location', device => $device } );
			$location = &subs::home($folder) . '/' . $app_path;
		}
		`mkdir -p $location` unless -e $location;
		my $filename = $location . '/' . $upload->{'filename'};
		my $new_uuid = &subs::random_string_creator(13);
		if ($is_enc == 1) {
			$filename = $filename . '.enc';
			push @uuids, $new_uuid;
		}
		$u->move_to($filename);
		my $ocr;
		if ($upload_type eq 'image') {
			`magick $filename -resize $resolution $filename` unless lc $resolution eq 'raw';
			$ocr = &ocr_reader($c,$filename);
		}
		$linux_file .= `file $filename` . "\n";
		if ($upload->{'filename'} =~ /avi$|mkv$/gi) {
			my $old_filename = $filename;
			$filename =~ s/avi$|mkv$/mp4/;
			my $tn_o = &subs::terminal_name($old_filename);
			my $tn_f = &subs::terminal_name($filename);
			&subs::subprocessor(sub {
				`ffmpeg -i $tn_o $tn_f & exit /b`;
				`shred -u $tn_o`;
				&subs::file_encrypter({ app => $app });
			}, { name => "Video file converter" });
		}

		my $u_data = { server_time => &subs::rightNow(), ocr => $ocr, f => $filename, uuid => $new_uuid, type => $upload_type };

		if ($thumb) {
			`mkdir -p $thumb` unless -e $thumb;

			$u_data->{'thumb'} = $thumb . '/' . $upload->{'filename'};
			$u_data = &thumbnail_creator($u_data);
		}
		push @uploaded_files, $u_data;
	}
	my $jfile = encode_json \@uploaded_files;

	if (@{$seen_appts} > 0) {
		&subs::db_update('appointments', {
			timestamp => $timestamp,
			notes => &subs::note_encrypter(&subs::session_suds($c),$notes . $linux_file),
			file => $jfile,
			uuid => $uuid,
			duration => $duration || '1000',
			encryption_standard => undef,
		},
		{
			uuid => $uuid,
			app => $app
		});
		&Websocket::send($app, { console => 'appointmentDetailGrabber(\'' . $app . '\',\'' . $uuid .'\');' });
	}
	else {
		my $write = {
			timestamp => $timestamp,
			app => &subs::unformat_name($app),
			notes => &subs::note_encrypter(&subs::session_suds($c),$notes . $linux_file),
			type => $upload_type || $c->param('type') || 'upload',
			file => $jfile,
			uuid => $uuid,
			duration => $duration || '1000',
			browser_tab_id => $c->param('browser_tab_id')
		};

		# a capture taken in the Camera app itself, not on an appointment, is
		# unclaimed media: it waits a week on the Camera app to be claimed
		if (&subs::unformat_name($app) eq 'camera') {
			$write->{'source'} = 'unclaimed';
			$write->{'warranty'} = &subs::rightNow() + (7 * 24 * 60 * 60 * 1000);
		}

		&appointment_writer($c,$write);
	}
	&subs::file_encrypter({ app => &subs::unformat_name($app) });

	$returner->{'cv'} = &centre_view_grabber({ c => $c, app => &subs::unformat_name($app), timestamp => $timestamp, cached => 'no' });
	# the files just written, so a caller (the chat's paperclip) can carry them
	# on the message without asking again
	$returner->{'file'} = $jfile;


	$c->render(json => $returner);
};

sub thumbnail_creator($data) {
	if ($data->{'thumb'}) {
		$data = &subs::file_media_information($data,$data->{'f'});

		my $thumbnail_size = &subs::setting_grabber({ app => 'misc', setting => 'thumbnail_size' }) || 'none';
		if ($thumbnail_size ne 'none') {
			my $filename = $data->{'f'};
			my $upload_type = $data->{'type'};
			my $thumb = $data->{'thumb'};
			my @filename = split /\./, $filename;
			my $ext = $filename[-1];

			my @thumb = split /\./, $thumb;
			pop @thumb;
			push @thumb, 'png';
			$thumb = join '.', @thumb;
			$data->{'thumb'} = $thumb;
			if ($upload_type eq 'video') {
				my $command2 = 'ffmpeg -ss 00:00:00.010 -i ' . $filename . ' -vframes 1 -c:v png -f image2pipe - | magick - -resize ' . $thumbnail_size . ' ' . $thumb;
				`$command2`;
			}
			elsif ($upload_type eq 'image' || $upload_type eq 'document') {
				my $command2 = 'magick ' . $filename . ' -auto-orient -strip -resize ' . $thumbnail_size . ' ' . $thumb;
				`$command2`;
			}
			else {
				return $data;
			}
		}
	}

	if ($data->{'app_uuid'} && $data->{'file_uuid'}) {
		my $appt = &subs::db_query('select * from appointments where uuid = ? and file is not null', $data->{'app_uuid'} )->hashes->[0];
		my $files = eval { return decode_json $appt->{'file'} } || [];
		if (scalar @{$files} > 0) {
			my $written = 0;
			foreach my $f ( @{$files} ) {
				if ($f->{'uuid'} eq $data->{'file_uuid'}) {
					$f->{'thumb'} = $data->{'thumb'};
					$f->{'server_time'} = &subs::rightNow();
					$written = 1;
				}
			}
			if ($written == 1) {
				my $jfile = encode_json $files;
				&subs::db_update('appointments', { file => $jfile, server_time => &subs::rightNow() }, { uuid => $appt->{'uuid'}, app => $appt->{'app'} });
			}
		}
	}
	delete $data->{'app_uuid'};
	delete $data->{'file_uuid'};

	return $data;
}

post '/manager/configure/image_function' => sub($c) {
	my $app = $c->param('app');
	my $file_uuid = $c->param('file_uuid');
	my $app_uuid = $c->param('app_uuid');
	my $function = $c->param('func');
	my $appt = &subs::db_select('appointments', undef, { app => $app, uuid => $app_uuid })->hashes->[0];
	my $files = eval { return decode_json $appt->{'file'} } || [];

	my $maps = eval { return decode_json &subs::setting_grabber({ app => 'travel', setting => 'maps' }) } || [];
	my $backgrounds = eval { return decode_json &subs::setting_grabber({ app => 'marker', setting => 'backgrounds' }) } || [];
	my $diagrams = eval { return decode_json &subs::setting_grabber({ app => 'embedded', setting => 'diagrams' }) } || [];
	my $receipts = eval { return decode_json &subs::setting_grabber({ app => 'budget', setting => 'receipts' }) } || [];
	my $signatorials = eval { return decode_json &subs::setting_grabber({ app => 'customs', setting => 'signatorials' }) } || [];
	unless ($function eq 'map') {
		@{$maps} = grep { $_->{'uuid'} ne $file_uuid } @{$maps};
	}
	unless ($function eq 'background') {
		@{$backgrounds} = grep { $_->{'uuid'} ne $file_uuid } @{$backgrounds};
	}
	unless ($function eq 'diagram') {
		@{$diagrams} = grep { $_->{'uuid'} ne $file_uuid } @{$diagrams};
	}
	unless ($function eq 'receipt') {
		@{$receipts} = grep { $_->{'uuid'} ne $file_uuid } @{$receipts};
	}
	unless ($function eq 'signatorial') {
		@{$signatorials} = grep { $_->{'uuid'} ne $file_uuid } @{$signatorials};
	}

	foreach my $fi ( @{$files} ) {
		if ( $fi->{'uuid'} eq $file_uuid) {
			$fi->{'function'} = $function;
			$fi->{'app'} = $app;
			$fi->{'app_uuid'} = $appt->{'uuid'};
			if ($function eq 'map') {
				push @{$maps}, $fi;
			}
			elsif ($function eq 'background') {
				push @{$backgrounds}, $fi;
			}
			elsif ($function eq 'diagram') {
				push @{$diagrams}, $fi;
			}
			elsif ($function eq 'receipt') {
				push @{$receipts}, $fi;
			}
			elsif ($function eq 'signatorial') {
				push @{$signatorials}, $fi;
			}
		}
	}

	my $jmaps = encode_json $maps;
	my $jbacks = encode_json $backgrounds;
	my $jdiagrams = encode_json $diagrams;
	my $jreceipts = encode_json $receipts;
	my $jsignatorials = encode_json $signatorials;
	&subs::setting_setter({ app => 'travel', setting => 'maps', value => $jmaps });
	&subs::setting_setter({ app => 'marker', setting => 'backgrounds', value => $jbacks });
	&subs::setting_setter({ app => 'embedded', setting => 'diagrams', value => $jdiagrams });
	&subs::setting_setter({ app => 'budget', setting => 'receipts', value => $jreceipts });
	&subs::setting_setter({ app => 'customs', setting => 'signatorials', value => $jsignatorials });
	my $jfile = encode_json $files;
	$appt->{'file'} = $jfile;
	$appt->{'server_time'} = &subs::rightNow();

	&subs::db_update('appointments', $appt, { uuid => $appt->{'uuid'}, app => $appt->{'app'} });

	$c->render(json => $appt);
	&image_function_sanity_check();
};

post '/manager/configure/image_function_tool' => sub($c) {
	my $app_uuid = $c->param('app_uuid');
	my $app = $c->param('app');
	my $file_uuid = $c->param('file_uuid');
	my $tool = $c->param('tool');
	my $value = $c->param('value');
	my $translate = $c->param('translate');
	$value = eval { return decode_json $value } || {};

	my $maps = eval { return decode_json &subs::setting_grabber({ app => 'travel', setting => 'maps' }) } || [];
	my $appt = &subs::db_select('appointments', undef, { app => $app, uuid => $app_uuid })->hashes->[0];

	my $files = eval { return decode_json $appt->{'file'} } || [];

	my $home_plate = eval { return decode_json &subs::setting_grabber({ app => $value->{'legend'}, setting => 'home_plate' }) } || {};
	if ($tool eq 'home_plate') {
		foreach my $hp ( keys %{$home_plate} ) {
			$value->{$hp} = $home_plate->{$hp};
		}
	}
	elsif ($tool eq 'scale') {
		if ($value->{'legend'} =~ /[a-zA-z]/gi) {
			# a legend with units is stored as metres; a conversion that fails
			# keeps the text - the client shows it, and the server's ppm/mpp
			# maths reads a non-number as "no scale" rather than dividing by it
			my ($fo,$ev,$uom,$format) = &formula_calculator($value->{'legend'} . ' to m' );
			$value->{'legend'} = $ev if defined $ev && $ev =~ /^\s*[0-9.]+\s*$/;
		}
	}
	foreach my $fi ( @{$files} ) {
		$fi->{$tool} = $value if $fi->{'uuid'} eq $file_uuid;
	}
	foreach my $map ( @{$maps} ) {
		$map->{$tool} = $value if $map->{'uuid'} eq $file_uuid;
	}
	$value->{'formatted_legend'} = &subs::format_name($value->{'legend'});

	my $jmaps = encode_json $maps;
	my $jfiles = encode_json $files;

	&subs::setting_setter({ app => 'travel', setting => 'maps', value => $jmaps });
	&subs::db_update('appointments', { server_time => &subs::rightNow(), file => $jfiles }, { app => $appt->{'app'}, uuid => $appt->{'uuid'} });

	$c->render(json => $value);
};

# Decrypt a sealed file's bytes, trying each security credential the way
# rock_and_roll does. Returns undef when none open it.
sub sealed_file_bytes {
	my ($suds, $file) = @_;
	return read_file($file) unless $file =~ /\.enc$/i;
	my $standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard' }) || 'aes-256-ctr';
	my @secrets;
	push @secrets, $suds if defined $suds && length $suds;
	my $pwords = &subs::db_query('select * from security where level != ? and level != ? order by server_time DESC', 'padlock', 'door')->hashes;
	foreach my $p ( @{$pwords} ) {
		my $secret = &subs::decrypter($suds, $p->{'credential'});
		push @secrets, $secret if defined $secret && length $secret;
	}
	# The configured standard is the likely one; the rest are only probed if it
	# does not open the file. This used to fork openssl once per credential.
	my @standards = ( $standard );
	foreach my $s ( @{ &subs::note_encryption_standards() } ) {
		push @standards, $s unless grep { $_ eq $s } @standards;
	}
	my $opened = &subs::sealed_file_open($file, \@secrets, \@standards, 0, sub { return &subs::plaintext_verdict($_[0]); });
	return $opened ? $opened->{'data'} : undef;
}

sub travel_map_record {
	my ($uuid) = @_;
	my $maps = eval { return decode_json &subs::setting_grabber({ app => 'travel', setting => 'maps' }) } || [];
	my ($map) = grep { $_->{'uuid'} eq $uuid } @{$maps};
	return ($map, $maps);
}

# A scale legend read off a map ("500 ft") is ground truth only once it is metres:
# the engine measures pixels-per-metre off it, so a plain number is what gets stored.
sub map_legend_metres {
	my ($text) = @_;
	return undef unless defined $text && length $text;
	return undef unless $text =~ /(\d[\d.,]*)\s*([a-zA-Z]+)/;
	(my $n = $1) =~ s/,//g;
	my $u = lc $2;
	my %f = (
		m => 1, metre => 1, meter => 1, metres => 1, meters => 1,
		km => 1000, kilometre => 1000, kilometer => 1000, kilometres => 1000, kilometers => 1000,
		cm => 0.01, mm => 0.001,
		ft => 0.3048, foot => 0.3048, feet => 0.3048,
		mi => 1609.344, mile => 1609.344, miles => 1609.344,
		in => 0.0254, inch => 0.0254, inches => 0.0254,
	);
	return undef unless exists $f{$u};
	return sprintf('%.3f', $n * $f{$u});
}

# The pair of helpers a person setting a map wants: read the scale legend off the
# image (local tesseract), or ask the vision model for the legend and how far the
# picture is off north-up. Both open the sealed image first.
post '/manager/configure/map_helper' => sub($c) {
	my $uuid = $c->param('file_uuid');
	my $mode = $c->param('mode') || 'ocr';
	my ($map) = &travel_map_record($uuid);
	unless ($map && $map->{'f'}) { $c->render(json => { error => 'no such map' }); return; }
	my ($destination,$asset) = &subs::file_device_renamer({ file => $map->{'f'}, app => $map->{'app'}, type => $map->{'type'} });
	my $path = &subs::home($destination . $asset);
	unless (-e $path) { $c->render(json => { error => 'the map image is not on this machine' }); return; }
	my $bytes = &sealed_file_bytes(&subs::session_suds($c), $path);
	unless (defined $bytes && length $bytes) { $c->render(json => { error => 'could not open the map image' }); return; }

	my $tmp = '/tmp/jawn_map_' . &subs::random_string_creator(8) . '.png';
	write_file($tmp, $bytes);

	if ($mode eq 'vision') {
		my $model = &subs::setting_grabber({ app => 'mail', setting => 'visual_assistant' }) || &subs::setting_grabber({ app => '__president', setting => 'visual_assistant' });
		unless ($model) { unlink $tmp; $c->render(json => { error => 'no vision model is set (Configure, Plat, Vision)' }); return; }
		my $system = 'You label a single map screenshot for JawnOS. The map is meant to be north-up.';
		my $ask = 'Return ONLY JSON, no prose: {"legend":"the scale-bar text exactly as printed (e.g. 200 m or 1 km), or empty","rotate":degrees to turn the image CLOCKWISE so its north points up (a number; 0 if already north-up),"bar":{"x1":0.0,"y1":0.0,"x2":0.0,"y2":0.0}}. For bar, give the two ends of the scale bar as fractions of the image width and height, each between 0 and 1 (x1,y1 the left end, x2,y2 the right end). Judge the rotation from the map content (roads, labels, the graticule), not from the scale bar, which is drawn horizontally however the map is turned.';
		my ($text, $err) = &subs::ai_chat_role('visual_assistant', [ { role => 'system', content => $system }, { role => 'user', content => $ask, images => [ encode_base64($bytes, '') ] } ], &subs::ai_role_thinking('visual_assistant'));
		unlink $tmp;
		unless ($text) { $c->render(json => { error => $err || 'the vision model returned nothing' }); return; }
		my ($json) = $text =~ /(\{.*\})/s;
		my $out = eval { return decode_json $json } || {};
		# a map may print more than one bar (500 ft and 200 m); keep the first
		my $legend = $out->{'legend'} // '';
		$legend =~ s/\s+/ /g; $legend =~ s/^\s+|\s+$//g;
		$legend = $1 if $legend =~ /(\d[\d.,]*\s*(?:km|m|cm|ft|mi|metres?|meters?|kilometres?|kilometers?|miles?|feet|foot)\b)/i;
		my $metres = &map_legend_metres($legend);
		$c->render(json => { legend => ($metres // $legend), legend_text => $legend, rotate => $out->{'rotate'}, bar => $out->{'bar'}, raw => $text });
		return;
	}

	my $base = '/tmp/jawn_map_ocr_' . &subs::random_string_creator(8);
	`tesseract "$tmp" "$base" 2>/dev/null`;
	my $ocr = (-e $base . '.txt') ? read_file($base . '.txt') : '';
	unlink $tmp; unlink $base . '.txt';
	my @cands;
	while ($ocr =~ /(\d[\d.,]*\s*(?:km|m|cm|ft|mi|metres?|meters?|kilometres?|kilometers?|miles?|feet|foot)\b)/gi) {
		push @cands, $1;
	}
	my $metres = &map_legend_metres($cands[0]);
	$c->render(json => { legend => ($metres // $cands[0]), legend_text => $cands[0], candidates => \@cands, text => $ocr });
};

post '/manager/configure/map_rotate' => sub($c) {
	my $uuid = $c->param('file_uuid');
	my $rotate = 0 + ($c->param('rotate') || 0);
	my ($map, $maps) = &travel_map_record($uuid);
	unless ($map) { $c->render(json => { error => 'no such map' }); return; }
	foreach my $m ( @{$maps} ) { $m->{'rotate'} = $rotate if $m->{'uuid'} eq $uuid; }
	&subs::setting_setter({ app => 'travel', setting => 'maps', value => encode_json $maps });
	$c->render(json => { rotate => $rotate });
};

# A thin test bed for the multimodal chat layer: hand it a model, a prompt and some
# media - uploads named 'media', or base64 / data: values in image / audio / video /
# files - and it hands back the reply as parts. Nothing routes through it; it is
# here to poke ai_chat while the media features grow.
any '/manager/ai_chat' => sub($c) {
	my $model = $c->param('model') || &subs::setting_grabber({ app => 'mail', setting => 'chatbot_model' });
	unless ($model) { $c->render(json => { error => 'no model given, and no default chatbot model is set' }); return; }
	my $prompt = $c->param('prompt') || 'Describe what you are given.';
	my $system = $c->param('system');
	my $msg = { role => 'user', content => $prompt };
	foreach my $key ( qw/images image audio video files/ ) {
		my $v = $c->param($key);
		next unless defined $v && length $v;
		$msg->{$key} = $v;
	}
	foreach my $u ( @{ $c->req->uploads('media') } ) {
		my $ct = ($u->headers->content_type || 'application/octet-stream');
		my $data = encode_base64($u->slurp, '');
		my $key = $ct =~ m{^image/} ? 'images' : $ct =~ m{^audio/} ? 'audio' : $ct =~ m{^video/} ? 'video' : 'files';
		push @{ $msg->{$key} }, { data => $data, mime => $ct };
	}
	my @msgs = ( ($system ? { role => 'system', content => $system } : ()), $msg );
	# A vision or chat model can take a minute; the uploads are already read
	# above, so only the model call runs in the child.
	&subs::render_in_subprocess($c, sub {
		my ($parts, $err) = &subs::ai_chat_parts($model, \@msgs);
		return { parts => $parts, err => $err, used => $subs::ai_last_model };
	}, sub {
		my ($c, $r) = @_;
		$r ||= {};
		if ($r->{'err'}) { $c->render(json => { model => $model, error => $r->{'err'} }); return; }
		$c->render(json => { model => $model, model_used => $r->{'used'}, parts => $r->{'parts'} });
	});
};

# Clear a provider's stand-down, so its paid models are offered again at once.
post '/manager/configure/ai_availability_clear' => sub($c) {
	my $bucket = $c->param('bucket') || '';
	unless ($bucket =~ /^[a-z_]+$/) { $c->render(json => { error => 'bad bucket' }); return; }
	&subs::setting_setter({ app => '__president', setting => 'ai_' . $bucket . '_unavailable', value => 0 });
	$c->render(json => { bucket => $bucket, cleared => 1 });
};



sub image_function_sanity_check() {
	my $maps = eval { return decode_json &subs::setting_grabber({ app => 'travel', setting => 'maps' }) } || [];
	my $backgrounds = eval { return decode_json &subs::setting_grabber({ app => 'marker', setting => 'backgrounds' }) } || [];
	my $diagrams = eval { return decode_json &subs::setting_grabber({ app => 'handbook', setting => 'diagrams' }) } || [];
	foreach my $map ( @{$maps} ) {
		unless ( -e $map->{'f'} ) {
			@{$maps} = grep { $_->{'uuid'} ne $map->{'uuid'} } @{$maps};
		}
	}

	foreach my $background ( @{$backgrounds} ) {
		unless ( -e $background->{'f'} ) {
			@{$backgrounds} = grep { $_->{'uuid'} ne $background->{'uuid'} } @{$backgrounds};
		}
	}

	foreach my $diagram ( @{$diagrams} ) {
		unless ( -e $diagram->{'f'} ) {
			@{$diagrams} = grep { $_->{'uuid'} ne $diagram->{'uuid'} } @{$diagrams};
		}
	}

	my $jmaps = encode_json $maps;
	my $jbacks = encode_json $backgrounds;
	my $jdiagrams = encode_json $diagrams;

	&subs::setting_setter({ app => 'travel', setting => 'maps', value => $jmaps });
	&subs::setting_setter({ app => 'marker', setting => 'backgrounds', value => $jbacks });
	&subs::setting_setter({ app => 'handbook', setting => 'diagrams', value => $jdiagrams });
}

