# A quick, plain-language reading of one cell of the inventory - its value, the
# pace it is on if the app keeps a budget, how it sits against the recent
# periods, and what the activity was made of - written by the same model the
# evaluation uses. The panel asks for it after it has drawn, so a slow model
# only leaves the summary a moment late rather than holding the window shut.
get '/manager/inventory/summary' => sub($c) {
	my $data = {
		app => &subs::unformat_name($c->param('app')),
		scope => $c->param('scope'),
		zone => $c->param('zone'),
		timestamp => $c->param('timestamp'),
		start => $c->param('start_timestamp'),
		end => $c->param('end_timestamp'),
	};
	# Hovering a row asks for a summary per cell, and each is a model call. The
	# child does the waiting; this worker keeps serving the panel in between.
	&subs::render_in_subprocess($c, sub {
		return &inventory_cell_summary($data);
	}, sub {
		my ($c, $returner) = @_;
		$c->render(json => ($returner || { summary => '', error => 'the summary did not answer' }));
	});
};

sub inventory_cell_summary($data) {
	my $app = $data->{'app'};
	my $scope = &subs::timespan_widener($data->{'scope'} || '') || 'week';
	my $zone = $data->{'zone'} || 'this';
	my $settings = &subs::settings_grabber({ app => $app });
	my $display = $settings->{'s_display'} || 'occurences';
	my $timestamp = $data->{'timestamp'} || &subs::rightNow();
	my ($start, $end) = ($data->{'start'}, $data->{'end'});
	unless ($start && $end) {
		($start, $end) = &father_time({ scope => $scope, ts => $zone, lock => $settings->{'s_lock'}, timestamp => $timestamp });
	}
	my $appts;
	my $value;
	if ($display eq 'duration') {
		# a session that crossed the edge of this window spent part of its time in
		# it even though it started before the window began
		$appts = &subs::db_query("select * from appointments where (app = ? or model = ?) and cast(timestamp as integer) < ? and (cast(timestamp as integer) >= ? or type in ('start','record') or (cast(timestamp as integer) + abs(cast(coalesce(duration,0) as real))) > ?) order by timestamp", $app, $app, $end, $start, $start)->hashes;
		$value = &inventory_window_value($appts, $display, $settings, $start, $end, $timestamp);
	}
	else {
		$appts = &subs::db_query('select * from appointments where (app = ? or model = ?) and cast(timestamp as integer) >= ? and cast(timestamp as integer) < ? order by timestamp', $app, $app, $start, $end)->hashes;
		$value = &inventory_window_value($appts, $display, $settings);
	}
	my $format = sub {
		my $n = shift;
		return '-' unless defined $n;
		return &subs::duration_sayer($n / 1000) if $display eq 'duration';
		return &subs::price_formatter($n) if $display eq 'total';
		return sprintf('%.1f', $n);
	};
	# the budget this cell is held against, and the pace when it is the period now
	# running - the same reading the inventory cell and its colour come from
	my $budget;
	if ($settings->{'budget'} && $settings->{'budget'} =~ /[0-9]/) {
		my $b = &budget_calculator({
			app => $app, budget => $settings->{'budget'}, circumstance => $display,
			value => $value, scope => $scope, ts => $zone, settings => $settings
		});
		if ($b->{'budgeted'} && ($b->{'circumstance'} || '') eq $display) {
			$budget = {
				budgeted => $b->{'formatted_budgeted'},
				status => $b->{'status'},
				($zone eq 'this' && defined $b->{'elapsed'} && $b->{'elapsed'} < 1 ? (
					on_track => $b->{'on_track'},
					progress_percent => $b->{'progress'},
					due_by_now => $b->{'formatted_on_target'},
					projected => $b->{'formatted_projected'},
				) : ()),
			};
		}
	}
	# the recent periods of the same clock, so the reading can say rising or falling
	my $trends = &subs::evaluation_period_trends($app, 8);
	# what the number was made of: the appointment types that ran in the window
	my $made = &subs::db_query('select type, count(*) as c from appointments where (app = ? or model = ?) and cast(timestamp as integer) >= ? and cast(timestamp as integer) < ? group by type order by c desc', $app, $app, $start, $end)->hashes;
	my @made_of = map { { type => ($_->{'type'} || 'record'), count => ($_->{'c'} + 0) } } @{$made}[0 .. ($#{$made} > 4 ? 4 : $#{$made})];
	my $briefing = {
		app => $app,
		scope => $scope,
		period => &subs::formatted_time($start) . ' to ' . &subs::formatted_time($end),
		period_is_current => ($zone eq 'this' ? 1 : 0),
		measure => $display,
		value => $format->($value),
		($budget ? (budget => $budget) : ()),
		($trends->{$scope} ? (recent_periods_counts => $trends->{$scope}) : ()),
		(scalar @made_of ? (made_of => \@made_of) : ()),
	};
	my $system = 'You summarise one period of one app\'s activity for someone glancing at a single statistic in JawnOS, a house that logs its life as timed appointments. A briefing follows: the app, the clock the period is on (scope: minute, hour, day, week, month or year), the period itself and whether it is the one now running (period_is_current), the measure the cell shows (measure) and its value, the budget if the app keeps one (budgeted, plus on_track, progress_percent, due_by_now and projected when the period is current), the recent counts of the same clock (recent_periods_counts, oldest first, the newest written count/percent so a part-run period is not read as a fall), and what the activity was made of (made_of: the appointment types that ran and how many). Write two to four short sentences, plain and specific, no headings, no bullets and no preamble: what the value is; whether it is on track for its budget, reading the pace when the period is current; how it sits against the recent periods (rising, falling, steady), naming the turn if there is one; and what most made up the number. Do not restate the labels or the raw figures as a list - say what they mean. Use only the numbers given.';
	my $model = &subs::setting_grabber({ app => 'mail', setting => 'eval_assistant' });
	my ($text, $error);
	if ($model) {
		($text, $error) = &subs::evaluation_model_call_role('eval_assistant', $system, encode_json($briefing), &subs::ai_role_thinking('eval_assistant'));
	}
	else {
		$error = 'no evaluation model is chosen';
	}
	unless ($text) {
		# a plain fallback the panel can always show when the model is away
		$text = 'This ' . $scope . ' shows ' . $format->($value) . '.';
		if ($budget) {
			$text .= ' The budget is ' . $budget->{'budgeted'} . '.';
			$text .= ' On track: ' . $budget->{'on_track'} . ' (' . $budget->{'progress_percent'} . '% in; ' . $budget->{'due_by_now'} . ' due, projecting ' . $budget->{'projected'} . ').' if defined $budget->{'on_track'};
		}
		$text .= ' Recent periods, oldest first: ' . $trends->{$scope} . '.' if $trends->{$scope};
		$text .= ' Mostly ' . join(', ', map { $_->{'type'} . ' x' . $_->{'count'} } @made_of) . '.' if scalar @made_of;
	}
	return { summary => $text, error => $error, briefing => $briefing };
}

# The part of an appointment's span that lies inside [start, end): an appointment
# runs from its timestamp for its duration, and a session that crosses a period's
# edge belongs to both periods by the time actually spent in each - 23:36 to
# 02:30 gives the first day 24 minutes and the next 2 hours 30, rather than the
# whole night to the day it started. The caller sets duration for a running
# session (there is none in the row while it is open).
sub appointment_overlap {
	my ($appt, $start, $end) = @_;
	my $from = ($appt->{'timestamp'} || 0) + 0;
	my $to = $from + abs($appt->{'duration'} || 0);
	my $lo = $from > $start ? $from : $start;
	my $hi = $to < $end ? $to : $end;
	return $hi > $lo ? $hi - $lo : 0;
}

# The next local midnight after a moment, as epoch milliseconds. The calendar
# date is stepped by hand because Time::Local refuses an out-of-range day (32)
# and normalising through it would croak on the last day of a month.
sub next_local_midnight {
	my $ms = shift;
	my @lt = localtime(int($ms / 1000));
	my ($mday, $mon, $year) = @lt[3, 4, 5];
	my @days = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31);
	my $y = $year + 1900;
	$days[1] = 29 if ($y % 4 == 0 && ($y % 100 != 0 || $y % 400 == 0));
	$mday++;
	if ($mday > $days[$mon]) {
		$mday = 1;
		$mon++;
		if ($mon > 11) { $mon = 0; $year++; }
	}
	return timelocal(0, 0, 0, $mday, $mon, $year) * 1000;
}

# Allocate a session's time across the allocation view's components by when it
# was actually spent: the hour of the day, weekday, day of the month and the
# rest each get their part, instead of the whole session landing on the one it
# started in. Seconds and minutes repeat on a fixed clock, so whole cycles are
# added once and only the remainder is walked; the longer components step from
# one local boundary to the next. A span past a year is one bad row rather than
# a distribution, so it stays on the components it started in.
sub allocation_duration_add {
	my ($returner, $appt, $display, $display_options) = @_;
	my $from = ($appt->{'timestamp'} || 0) + 0;
	my $to = $from + abs($appt->{'duration'} || 0);
	return if $to <= $from;

	my $add = sub {
		my ($scope, $key, $amount) = @_;
		return unless defined $key && $amount > 0;
		my $bucket = $returner->{$key}->{$scope} ||= {};
		$bucket->{$display} = ($bucket->{$display} || 0) + $amount;
		$bucket->{'formatted_duration'} = &subs::duration_sayer($bucket->{$display} / 1000) if $display eq 'duration';
		foreach my $d ( @{$display_options || []} ) {
			my $name = $d->{'name'};
			my $value = $bucket->{$name};
			if ($value > $returner->{'highest'}->{$scope}->{$name}) {
				$returner->{'highest'}->{$scope}->{$name} = $value;
			}
			elsif ($returner->{'highest'}->{$scope}->{$name} == undef) {
				$returner->{'highest'}->{$scope}->{$name} = $value;
			}
			if ($value < $returner->{'lowest'}->{$scope}->{$name}) {
				$returner->{'lowest'}->{$scope}->{$name} = $value;
			}
			elsif ($returner->{'lowest'}->{$scope}->{$name} == undef) {
				$returner->{'lowest'}->{$scope}->{$name} = $value;
			}
		}
	};

	if ($to - $from > 366 * 86400000) {
		my @lt = localtime(int($from / 1000));
		my %key = (
			second => $lt[0], minute => $lt[1], hour => $lt[2],
			mday => $lt[3], month => $lt[4] + 1, year => $lt[5] + 1900,
			wday => $lt[6], yday => $lt[7], isdst => $lt[8]
		);
		foreach my $scope ( qw/second minute hour mday month year wday yday isdst/ ) {
			$add->($scope, $key{$scope}, $to - $from);
		}
		return;
	}

	foreach my $cycle ( [ 'second', 60, 1000 ], [ 'minute', 3600, 60000 ] ) {
		my ($scope, $values, $step) = @{$cycle};
		my $period = $values * $step;
		my $full = int(($to - $from) / $period);
		for (my $v = 0; $full > 0 && $v < $values; $v++) {
			$add->($scope, $v, $full * $step);
		}
		my $cursor = $from + $full * $period;
		while ($cursor < $to) {
			my $next = int($cursor / $step) * $step + $step;
			my $end = $next < $to ? $next : $to;
			$add->($scope, int($cursor / $step) % $values, $end - $cursor);
			$cursor = $end;
		}
	}

	# hour of day and daylight saving change at the top of a local hour
	my $cursor = $from;
	while ($cursor < $to) {
		my @lt = localtime(int($cursor / 1000));
		# the time already spent in this local hour, taken off the clock rather
		# than rebuilt with timelocal, so an hour that daylight saving repeats or
		# skips still steps one real hour and never asks for hour 24
		my $elapsed = $lt[1] * 60000 + $lt[0] * 1000 + ($cursor % 1000);
		my $next = $cursor - $elapsed + 3600000;
		$next = $cursor + 3600000 if $next <= $cursor;
		my $end = $next < $to ? $next : $to;
		$add->('hour', $lt[2], $end - $cursor);
		$add->('isdst', $lt[8], $end - $cursor);
		$cursor = $end;
	}

	# the calendar components change at local midnight
	$cursor = $from;
	while ($cursor < $to) {
		my @lt = localtime(int($cursor / 1000));
		my $next = &next_local_midnight($cursor);
		$next = $cursor + 86400000 if $next <= $cursor;
		my $end = $next < $to ? $next : $to;
		$add->('mday', $lt[3], $end - $cursor);
		$add->('month', $lt[4] + 1, $end - $cursor);
		$add->('year', $lt[5] + 1900, $end - $cursor);
		$add->('wday', $lt[6], $end - $cursor);
		$add->('yday', $lt[7], $end - $cursor);
		$cursor = $end;
	}
}

# the value one window shows for the inventory's chosen measure, the way the
# inventory buckets it (a running session read to now, a measure read off the
# appointment's own readings). A duration is read only for the part inside the
# window when the caller names its edges.
sub inventory_window_value($appts, $display, $settings, $start, $end, $view_now) {
	my $value = 0;
	my $now = $view_now || &subs::rightNow();
	foreach my $a ( @{$appts} ) {
		if ($display eq 'occurences') { $value += 1; }
		elsif ($display eq 'duration') {
			my $d = abs($a->{'duration'} || 0);
			$d = $now - $a->{'timestamp'} if ($a->{'type'} eq 'start' || $a->{'type'} eq 'record') && $a->{'timestamp'} && $a->{'timestamp'} < $now;
			if (defined $start && defined $end) {
				my $copy = { %{$a}, duration => $d };
				$d = &appointment_overlap($copy, $start, $end);
			}
			$value += $d;
		}
		elsif ($display eq 'total') { $value += abs($a->{'total'} || 0); }
		elsif ($display eq 'quantity') { $value += abs($a->{'quantity'} || 0); }
		else {
			my $measures = eval { decode_json $a->{'measures'} } || [];
			foreach my $m ( @{$measures} ) {
				$value += $m->{$display} if defined $m->{$display} && $m->{$display} =~ /[0-9]/;
			}
		}
	}
	return $value;
}

get '/manager/inventory/details' => sub($c) {
	my $app = &subs::unformat_name($c->param('app'));
	my $s_scroll = $c->param('s_scroll');
	if ($s_scroll != 0) {
		&subs::setting_setter({ app => $app, setting => 's_scroll', value => $s_scroll });
	}
	my $settings = &subs::settings_grabber({ app => $app });
	my $returner = &inventory_details($c, $settings);
	$c->render(json => $returner);
};

sub inventory_details($c,$settings) {
	my $app = $c->param('app');
	my $server_time = &subs::rightNow();
	my $timestamp = $c->param('timestamp');
	# The windows are built from this request's moment, so a running session is
	# read to that moment too. Using the later server time left a sliver of the
	# session past every "Nnext" window's opening edge, which put a second or so
	# of duration on every future scope.
	my $view_now = ($timestamp && $timestamp =~ /^[0-9]+$/) ? $timestamp : $server_time;
	my $appts = [];
	if ($c->param('display')) {
		$settings->{'s_display'} = $c->param('display');
		$settings->{'s_movement'} = $c->param('movement');
		$settings->{'s_scope_count'} = $c->param('scope_count');
		$settings->{'s_visual'} = $c->param('visual');
		$settings->{'s_calc'} = $c->param('calc');
		$settings->{'s_lock'} = $c->param('lock');
	}
	# the canvas a walk happened on lends its unit to the page button: the fresh
	# gesture carries it on the request, the setting keeps it for the loads after
	my $page_scope = $c->param('page_scope') || $settings->{'s_page_scope'} || '';

	unless ($settings->{'s_display'}) {
		&subs::setting_setter({ app => $app, setting => 's_display', value => 'occurences'});
		$settings->{'s_display'} = 'occurences';
	}
	my $s_display = $settings->{'s_display'};
	$settings->{'s_movement'} = eval { decode_json $settings->{'s_movement'} } || ['all'];
	$appts = &subs::db_query('select * from appointments where app = ? or model = ? order by timestamp', $app, $app)->hashes;
	my $movements = [ 'all' ];
	my %movement_seen = ( all => 1 );
	foreach my $a ( @{$appts} ) {
		push @{$movements}, $a->{'type'} unless $movement_seen{$a->{'type'}}++;
	}
	push @{$movements}, 'start' unless $movement_seen{'start'};
	if ($settings->{'s_movement'} == undef || grep { $_ eq 'all' } @{$settings->{'s_movement'}} ) {
	}
	else {
		my $new_appts = [];
		foreach my $sm ( @{$settings->{'s_movement'}} ) {
			push @{$new_appts}, grep { $_->{'type'} eq $sm } @{$appts};
		}
		$appts = $new_appts;
	}
	my @display_options;
	foreach my $k ( keys %{$gb::budget_modes} ) {
		my $formatted_name = &subs::format_name($k);
		if ($k eq 'quantity') {
			$formatted_name = $formatted_name . ' (' . $settings->{'unit'} . ')';
		}
		my $bm = { name => $k, formatted_name => $formatted_name };
		push @display_options, $bm;

	}
	my $am = eval { return decode_json $settings->{'app_measures'} } || {};
	foreach my $ameas ( keys %{$am} ) {
		my $formatted_name = &subs::format_name($ameas);
		if ($am->{$ameas}->{'unit'}) {
			$formatted_name = $formatted_name . ' (' . $am->{$ameas}->{'unit'} . ')';
		}
		push @display_options, { name => $ameas, formatted_name => $formatted_name } unless grep { $_->{'name'} eq $ameas } @display_options;
	}
	# A measure remembers its own reading: steps is summed, weight averaged. The
	# app's s_calc is only the fallback for one that was never set, and while a
	# measure is displayed its own calc is the one in force - so the statistic, the
	# budget and the panel all agree without re-picking. measure_calc_json rides
	# out to the calc select, so the client knows which ones are measures.
	my %measure_calc;
	foreach my $ameas ( keys %{$am} ) {
		my $mc = &subs::setting_grabber({ app => $app, setting => 'measure_calc', subsetting => $ameas });
		$mc = $settings->{'s_calc'} unless (defined $mc && length $mc);
		$mc = 'sum' unless (defined $mc && length $mc);
		$measure_calc{$ameas} = $mc;
	}
	$settings->{'s_calc'} = $measure_calc{$s_display} if defined $measure_calc{$s_display};
	my $is_measure = defined $measure_calc{$s_display};
	my $measure_calc_json = encode_json(\%measure_calc);

	my @time_scopes;
	my @time_widths;
	my $scope_page = 0;
	my $scope_page_max = 24;

	my @time_lengths = qw/minute hour day week month year/;
	if ($settings->{'s_visual'} eq 'allocation') {
		@time_scopes = undef;
		for (my $n = 0; $n <= 366; $n++) {
			push @time_scopes, $n;
		}
		@time_lengths = qw/second minute hour mday month year wday yday isdst/;
		@time_widths = ( 60, 60, 24, 31, 12, 150, 7, 365, 2 );
	}
	else {
		# the page of periods the rows cover: now first, then the blocks before
		# it (or the ones past next) as a graph is scrolled sideways
		$scope_page = $settings->{'s_scope_page'} || 0;
		$scope_page = $scope_page_max if $scope_page > $scope_page_max;
		$scope_page = -$scope_page_max if $scope_page < -$scope_page_max;
		@time_scopes = &subs::time_scope_page({ count => $settings->{'s_scope_count'} || 30, page => $scope_page });
	}

	if ($c->param('scope')) {
		my $scope = &subs::unformat_name($c->param('scope'));
		my $return_n = 0;
		for ( my $n = 0; $n <= scalar @time_lengths; $n++ ) {
			if ( $time_lengths[$n] eq $scope ) { $return_n = $n - 1; }
			if ($c->param('zone')) {
				if ($return_n > 1) {
					my @timey_widths = ( 60, 24, 7, 30, 12, 10 );
					@time_scopes = ('this','last');
					push @time_widths, $timey_widths[$return_n];
					for (my $n = 2; $n <= $timey_widths[$return_n]; $n++) {
						push @time_scopes, $n . 'last';
					}

				}
			}
		}
		@time_lengths = grep { $_ eq $time_lengths[$return_n] } @time_lengths;
	}
	# when the app happens, as profiles for the "when" wheel: by the hour of the
	# day and by the day of the week, read off the appointments themselves
	my @hour_profile = (0) x 24;
	my @weekday_profile = (0) x 7;
	foreach my $a ( @{$appts} ) {
		next unless ($a->{'timestamp'} || '') =~ /[0-9]/;
		my @lt = localtime( ($a->{'timestamp'} + 0) / 1000 );
		$hour_profile[$lt[2]]++;
		$weekday_profile[$lt[6]]++;
	}
	my @revised_time_scopes = @time_scopes;
	my $returner = {
		longest => $appts->[0],
		shortest => $appts->[0],
		betweens => [],
		between_total => 0,
		between_average => 0,
		longest_between => {},
		shortest_between => {},
		first_seen => $appts->[0],
		'last_seen' => $appts->[0],
		first_recorded => {},
		last_recorded => {},
		average_duration => 0,
		total_duration => 0,
		total_occurences => 0,
		settings => $settings,
		scopes => \@time_scopes,
		time_lengths => \@time_lengths,
		time_widths => \@time_widths,
		timestamp => $timestamp,
		scope_page => $scope_page,
		scope_page_max => $scope_page_max,
		page_scope => $page_scope,
		app => $app,
		hour_profile => \@hour_profile,
		weekday_profile => \@weekday_profile,
		budget_status => {},
	};
	my $bmt = scalar grep { $_ eq $s_display } keys %{$gb::budget_modes};
	# duration_sayer re-parses and re-formats its argument on every call, but the
	# window loops ask for the same handful of values thousands of times
	my %duration_sayer_cache;
	my $duration_sayer = sub {
		my $value = shift;
		my $key = defined $value ? $value : '';
		return $duration_sayer_cache{$key} if exists $duration_sayer_cache{$key};
		return $duration_sayer_cache{$key} = &subs::duration_sayer($value);
	};
	# measures only feed the two custom-measure paths below, so the JSON decode can
	# be skipped entirely for the budget-mode displays
	my $measures_required = ($settings->{'s_visual'} eq 'allocation') || ($bmt == 0);

	if ( scalar @{$appts} > 0 ) {
		# the time windows only depend on the request timestamp, so they are computed
		# once here instead of calling father_time for every appointment
		my @time_windows;
		if ($settings->{'s_visual'} eq 'historical' || $settings->{'s_visual'} eq '') {
			foreach my $ts (@time_scopes) {
				foreach my $scope (@time_lengths) {
					my ($bt, $temp_timestamp) = &father_time({
						scope => $scope,
						ts => $ts,
						lock => $settings->{'s_lock'},
						timestamp => $timestamp
					});
					push @time_windows, [ $ts, $scope, $bt, $temp_timestamp ];
				}
			}
		}
		# constant time membership test for measures promoted to their own appointment
		my %appt_uuids;
		$appt_uuids{$_->{'uuid'}} = 1 for @{$appts};
		foreach my $a ( @{$appts} ) {
			if ($measures_required && $a->{'measures'} && !$a->{'measure_dejsonified'}) {
				$a->{'measures'} = eval { return decode_json $a->{'measures'} } || [];
				$a->{'measure_dejsonified'} = 1;
			}
			if (($a->{'type'} eq 'start' || $a->{'type'} eq 'record')) {
				if ($a->{'timestamp'} < $view_now) {
					$a->{'duration'} = $view_now - $a->{'timestamp'};
				}
				else {
					$a->{'duration'} = &subs::time_abbrev_translator($settings->{'duration'});
				}
			}
			$a->{'duration'} = abs $a->{'duration'};
			# where the session ends: read once so a window that cannot overlap it
			# costs only the two comparisons below
			my $ends_at = ($a->{'timestamp'} || 0) + ($a->{'duration'} || 0);
			if (($s_display eq 'total') && ($a->{'total'} == 0 || $a->{'total'} == undef)) {
				next;
			}
			if ($settings->{'s_visual'} eq 'historical' || $settings->{'s_visual'} eq '') {
				foreach my $window (@time_windows) {
					# half open [bt, tt): an instant on an edge belongs to the window
					# it opens, so the windows never overlap and never leave a gap
					my $starts_here = ($a->{'timestamp'} >= $window->[2] && $a->{'timestamp'} < $window->[3]);
					# A session that runs over a period's edge belongs to both periods:
					# its occurrence stays with the one it started in, but its time is
					# counted where it was actually spent. Other readings are instants and
					# stay in the window they open.
					my $overlap = 0;
					if ($s_display eq 'duration' && $a->{'timestamp'} < $window->[3] && $ends_at > $window->[2]) {
						$overlap = &appointment_overlap($a, $window->[2], $window->[3]);
					}
					next unless $starts_here || $overlap > 0;
					{
						# only unpack the matching windows: unpacking all of them is most of
						# what this loop spends its time on
						my ($ts, $scope, $bt, $temp_timestamp) = @{$window};
						# ||= creates the bucket: a plain read of the chain would leave it undef
						my $bucket = $returner->{$ts}->{$scope} ||= {};
						if ($a->{'measures'} && $bmt == 0 ) {

							foreach my $measure ( @{$a->{'measures'}} ) {
								unless ($measure->{$s_display} || $measure->{$s_display} == 0) {
									last;
								}
								foreach my $mk ( grep { $_ ne 'uuid' } keys %{$measure} ) {

									if ($measure->{'ts'} && $measure->{'ts'} ne '') {
										$measure->{'timestamp'} = $measure->{'ts'};
										delete $measure->{'ts'};
									}
									# out once tt arrives, to match the appointment test above
									if (($measure->{'timestamp'} < $bt || $measure->{'timestamp'} >= $temp_timestamp) && $s_display eq $mk) {

										unless ($appt_uuids{$measure->{'uuid'}}) {
											my $new_measure = {
												app => $a->{'app'},
												timestamp => $measure->{'timestamp'} || $measure->{'ts'},
												type => 'measure',
												uuid => $measure->{'uuid'},
												measures => encode_json [ $measure ],
											};
											push @{$appts}, $new_measure;
											$appt_uuids{$new_measure->{'uuid'}} = 1;
										#	@{$a->{'measures'}} = grep { $_->{'uuid'} ne $measure->{'uuid'} } @{$a->{'measures'}};
											next;
										}
										$measure = undef;
									}
									else {
										if (($measure->{$mk} || $measure->{$mk} == 0) && $measure->{$s_display}  eq $measure->{$mk}) {

											$bucket->{$mk . '_occurences'} += 1;
											if ($settings->{'s_calc'} eq 'average' ) {
												$bucket->{'t_' . $mk} += $measure->{$mk};
												my $sprinter = "%.2f";
												if ($measure->{$mk} < 1 && $measure->{$mk} > -1) {
													$sprinter = "%.4f";
												}

												# a zero measure is an average like any other: the divisor
												# is how many it has seen, never the measure itself
												$bucket->{$mk} = sprintf($sprinter, $bucket->{'t_' . $mk} / $bucket->{$mk . '_occurences'});
												$bucket->{$mk} = 0 unless defined $bucket->{$mk};
											}
											elsif ($settings->{'s_calc'} eq 'high') {
												$bucket->{$mk} = $measure->{$mk} unless $bucket->{$mk};

												if ($measure->{$mk} > $bucket->{$mk}) {
													$bucket->{$mk} = $measure->{$mk};
												}
											}
											elsif ($settings->{'s_calc'} eq 'low') {
												$bucket->{$mk} = $measure->{$mk} unless $bucket->{$mk};
												if ($measure->{$mk} < $bucket->{$mk}) {
													$bucket->{$mk} = $measure->{$mk};
												}
											}
											else {
												$bucket->{$mk} += $measure->{$mk};# if $measure->{$mk} != undef;

											}
											$returner->{'total'}->{$scope}->{$mk} += 1;
										}
									}
								}
							}
						}
						elsif ($bmt > 0) {

							if ($s_display eq 'quantity') {
								if ($a->{'unit'} ne $settings->{'unit'}) {
									my $neg = 0;
									if ($a->{'quantity'} < 0) { $neg = 1; }
									$a->{'quantity'} = abs $a->{'quantity'};
									my ($formula,$evaluation,$uom,$format) = &formula_calculator($a->{'quantity'} . $a->{'unit'} . ' to ' . $settings->{'unit'});
									$a->{'quantity'} = $evaluation unless $evaluation == 0;
									$a->{'quantity'} = (abs $a->{'quantity'}) * -1 if $neg == 1;
									$a->{'unit'} = $settings->{'unit'} unless $evaluation == 0;
								}
							}

							my $amount = ($s_display eq 'duration') ? $overlap : $a->{$s_display};

							if ($settings->{'s_calc'} eq 'average' ) {
								$bucket->{'t_' . $s_display} += $amount;
								$bucket->{'c_' . $s_display} += 1;
								my $sprinter = "%.2f";
								if ($amount < 1 && $amount > -1) {
									$sprinter = "%.4f";
								}
								$bucket->{$s_display} = sprintf($sprinter, $bucket->{'t_' . $s_display} / $bucket->{'c_' . $s_display});
								if ($bucket->{$s_display} == 0) {
									$bucket->{$s_display} = 0;
								}
							}
							elsif ($settings->{'s_calc'} eq 'high') {
								$bucket->{$s_display} = 0 unless $bucket->{$s_display};
								if ($amount > $bucket->{$s_display}) {
									$bucket->{$s_display} = $amount;
								}
							}
							elsif ($settings->{'s_calc'} eq 'low') {
								$bucket->{$s_display} = $amount unless $bucket->{$s_display};
								if ($amount < $bucket->{$s_display}) {
									$bucket->{$s_display} = $amount;
								}
							}
							else {
								$bucket->{$s_display} += $amount unless $s_display eq 'occurences';
							}
						}
						$bucket->{'timestamp'} = $a->{'timestamp'} if $starts_here;
						$bucket->{'occurences'} += 1 if $starts_here;# unless $s_display eq 'occurences';
						$a->{'occurences'} = 1;

						$bucket->{'formatted_duration'} = $duration_sayer->((abs $bucket->{'duration'}) / 1000);
				#		$bucket->{'total'} += abs $a->{'total'} if $a->{'total'};
				#		$bucket->{'amount'} += abs $a->{'amount'} if $a->{'amount'};
						# the "Nnext" windows reach past this period from the request on,
						# so they hold what it and "next" hold again, and the per period
						# totals and average leave them out
						if ($ts !~ /^[0-9]+next/) {
							my $contribution = ($s_display eq 'duration') ? $overlap : abs $a->{$s_display};
							$returner->{'total'}->{$scope}->{$s_display} += $contribution;
							$returner->{'count'}->{$scope}->{$s_display} += 1;
							$returner->{'average'}->{$scope}->{$s_display} = sprintf("%.2f", $returner->{'total'}->{$scope}->{$s_display} / $returner->{'count'}->{$scope}->{$s_display});
						}
						# a measure reads its budget value from its own calc (sum or average),
						# not only when the display is summed; a base reading still wants sum
						if ($settings->{'budget'} && $bucket->{$s_display} != 0 && ($settings->{'s_calc'} eq 'sum' || $is_measure)) {
							unless ($returner->{'autocalc'}) {
								$returner->{'autocalc'} = &subs::cache_get({ app => $returner->{'app'}, context => 'autocalc', subcontext => $s_display });
							}
							my $budget = &budget_calculator({
								app => $returner->{'app'},
								budget => $settings->{'budget'},
								circumstance => $s_display,
								value => $bucket->{$s_display},
								scope => $scope,
								ts => $ts,
								appts => $appts,
								settings => $settings
							});

							if ($bucket->{$s_display} && $ts eq 'this' &&
								&subs::timespan_widener($budget->{'scope_name'}) eq &subs::timespan_widener($scope) && $budget->{'is_scope'} eq 'yes' &&
									$s_display eq $budget->{'circumstance'}) {

								$returner->{'cachable'} = $budget if $budget->{'colour'};
							}


							$bucket->{'budget'} = $budget;
							$returner->{'budgets'} = $budget->{'budgets'};
							$returner->{'budget_status'}->{$scope}->{$s_display}->{'expected'} += $budget->{'expected'};
							$returner->{'budget_status'}->{$scope}->{$s_display}->{'actual'} += $budget->{'actual'};

							$returner->{'budget_status'}->{$scope}->{$s_display} = &budget_status_maker($returner->{'budget_status'}->{$scope}->{$s_display});
						}

						if ($s_display eq 'occurences') {
							$returner->{'average'}->{$scope}->{$s_display} = sprintf("%.2f", $returner->{'total'}->{$scope}->{$s_display} / scalar grep { $_ !~ /^[0-9]+next/ } @time_scopes);
						}
						foreach my $d ( @display_options ) {
							my $name = $d->{'name'};
							my $value = $bucket->{$name};
							if ($value > $returner->{'highest'}->{$scope}->{$name}) {
								$returner->{'highest'}->{$scope}->{$name} = $value;
							}
							elsif ($returner->{'highest'}->{$scope}->{$name} == undef) {
								$returner->{'highest'}->{$scope}->{$name} = $value;
							}
							if ($value < $returner->{'lowest'}->{$scope}->{$name}) {
								$returner->{'lowest'}->{$scope}->{$name} = $value;
							}
							elsif ($returner->{'lowest'}->{$scope}->{$name} == undef) {
								$returner->{'lowest'}->{$scope}->{$name} = $value;
							}
							$bucket->{'start_timestamp'} = $bt;
							$bucket->{'end_timestamp'} = $temp_timestamp;

						}
					}
				}
			}
			elsif ($settings->{'s_visual'} eq 'allocation') {
				my @localtime = localtime($a->{'timestamp'} / 1000);
				if ($a->{'measures'}) {
					foreach my $measure ( @{$a->{'measures'}} ) {
						foreach my $mk ( keys %{$measure} ) {
							unless ($measure->{$s_display} || $measure->{$s_display} == 0) {
								last;
							}

							if (!$measure->{'uuid'}) {
								$measure->{'uuid'} = &subs::random_string_creator(15);
							}
							if ($measure->{'ts'} && $measure->{'ts'} ne '') {
								$measure->{'timestamp'} = $measure->{'ts'};
								delete $measure->{'ts'};
							}

							if ($s_display eq $mk) {
								unless ($appt_uuids{$measure->{'uuid'}}) {
									my $new_measure = {
										app => $a->{'app'},
										timestamp => $measure->{'timestamp'} || $measure->{'ts'},
										type => 'measure',
										uuid => $measure->{'uuid'} || &subs::random_string_creator(8),
										$mk => $measure->{$s_display},
										measures => encode_json [ $measure ],
									};
									push @{$appts}, $new_measure;
									$appt_uuids{$new_measure->{'uuid'}} = 1;
									undef $a;
								}
								$measure = undef;
							}
						}
					}
				}
				next unless $a->{'uuid'};
				# a split duration has already been added to every component the
				# session touched, so the start bucket takes only its occurrence
				my $split_duration = ($s_display eq 'duration' && ($settings->{'s_calc'} || 'sum') eq 'sum');
				&allocation_duration_add($returner, $a, $s_display, \@display_options) if $split_duration;
				for (my $n = 0; $n <= scalar @time_lengths; $n++) {
					if (($a->{$s_display} || $a->{$s_display} == 0) || ( $bmt > 0 )) {
						my $scope = $time_lengths[$n];
						my $ts = $localtime[$n];
						if ($scope eq 'month') { $ts += 1; }
						if ($scope eq 'year') { $ts += 1900; }
						my $bucket = $returner->{$ts}->{$scope} ||= {};
					#	if ($scope eq 'wday') { $ts += 1; }
						$bucket->{'occurences'} += 1;
						if ($settings->{'s_calc'} eq 'average' ) {
							$bucket->{'t_' . $s_display} += $a->{$s_display};
							$bucket->{$s_display} = sprintf("%.2f", $bucket->{'t_' . $s_display} / $bucket->{'occurences'});
							if ($bucket->{$s_display} == 0) {
								$bucket->{$s_display} = 0;
							}
						}
						elsif ($settings->{'s_calc'} eq 'high') {
							$bucket->{$s_display} = $a->{$s_display} unless $bucket->{$s_display};
							if ($a->{$s_display} > $bucket->{$s_display}) {
								$bucket->{$s_display} = $a->{$s_display};
							}
						}
						elsif ($settings->{'s_calc'} eq 'low') {
							$bucket->{$s_display} = $a->{$s_display} unless $bucket->{$s_display};
							if ($a->{$s_display} < $bucket->{$s_display}) {
								$bucket->{$s_display} = $a->{$s_display};
							}
						}
						else {
							$bucket->{$s_display} += $a->{$s_display} unless $split_duration;

						}
						$bucket->{'formatted_duration'} = $duration_sayer->((abs $bucket->{'duration'}) / 1000);
						$bucket->{'total'} += $a->{'total'};
						unless ($bmt > 0) {
							#$bucket->{$s_display} += $a->{$s_display};
						}

						foreach my $d ( @display_options ) {
							my $name = $d->{'name'};
							my $value = $bucket->{$name};
							if ($value > $returner->{'highest'}->{$scope}->{$name}) {
								$returner->{'highest'}->{$scope}->{$name} = $value;
							}
							elsif ($returner->{'highest'}->{$scope}->{$name} == undef) {
								$returner->{'highest'}->{$scope}->{$name} = $value;
							}
							if ($value < $returner->{'lowest'}->{$scope}->{$name}) {
								$returner->{'lowest'}->{$scope}->{$name} = $value;
							}
							elsif ($returner->{'lowest'}->{$scope}->{$name} == undef) {
								$returner->{'lowest'}->{$scope}->{$name} = $value;
							}
						}
					}
				}
			}
			if (abs $a->{'duration'} > abs $returner->{'longest'}->{'duration'}) {
				$returner->{'longest'} = $a;
			}
			if (abs $a->{'duration'} < abs $returner->{'shortest'}->{'duration'}) {
				$returner->{'shortest'} = $a;
			}
			my $between = $a->{'timestamp'} - $returner->{'last_seen'}->{'timestamp'};
			if ($between > $returner->{'longest_between'}->{'duration'}) {
				$returner->{'longest_between'} = clone $a;
				$returner->{'longest_between'}->{'duration'} = $between;
			}
			if ($between < $returner->{'shortest_between'}->{'duration'} || $returner->{'shortest_between'}->{'duration'} == undef) {
				$returner->{'shortest_between'} = clone $a;
				$returner->{'shortest_between'}->{'duration'} = $between;
			}
			push @{$returner->{'betweens'}}, $between;
			$returner->{'last_seen'} = $a;

			if ($a->{'server_time'} > $returner->{'last_recorded'}->{'server_time'}) {
				$returner->{'last_recorded'} = $a;
			}
			if ($a->{'server_time'} < $returner->{'first_recorded'}->{'server_time'} || $returner->{'first_recorded'}->{'server_time'} == undef) {
				$returner->{'first_recorded'} = $a;
			}
			$returner->{'total_duration'} += abs $a->{'duration'};
			$returner->{'total_occurences'} += 1;

		}
		$returner->{'average_duration'} = eval { $returner->{'total_duration'} / $returner->{'total_occurences'} } || undef;

		foreach my $betweens ( @{$returner->{'betweens'}} ) {
			$returner->{'between_total'} += $betweens;
		}
		$returner->{'between_average'} = eval { $returner->{'between_total'} / $returner->{'total_occurences'} } || undef;
	}
	# A row stays only if it holds something for what is on screen. A period that
	# reaches past now can catch a stray future-dated appointment and come back as
	# a bucket that carries no value for the chosen display - a note dated years
	# ahead lands in the year rows that reach it - and that empty row should not
	# take up space in the table or the graph.
	foreach my $ts ( @time_scopes ) {
		my $row = $returner->{$ts};
		my $holds = 0;
		if ($row) {
			foreach my $scope ( @time_lengths ) {
				next unless $row->{$scope} && ref $row->{$scope} eq 'HASH';
				if (defined $row->{$scope}->{$s_display}) { $holds = 1; last; }
			}
		}
		@revised_time_scopes = grep { $_ ne $ts } @revised_time_scopes unless $holds;
	}
	my @sb;
	foreach my $s ( @display_options ) {
		push @sb, $s->{'name'} unless grep { $_ eq $s->{'name'} } keys %{$gb::budget_modes};
	}
	my $jsb = encode_json \@sb;

	@time_scopes = @revised_time_scopes;
	push @time_scopes, qw/average total/;
	if ($returner->{'budgets'}->{$s_display}) {
		&subs::cache_set({ app => $returner->{'app'}, context => 'budget', subcontext => $returner->{'cachable'}->{'circumstance'} },$returner->{'cachable'});
	}
	&Websocket::send('tab', $returner->{'sendable'});
	&subs::appt_header_printer({ app => $returner->{'app'} });
	undef $returner->{'sendable'};
	undef $returner->{'cachable'};
	$returner->{'evaluation'} = &subs::cache_get({ app => $app, context => 'evaluation' });

	$returner->{'content'} = $c->render_to_string(
		template => 'apps/inventory',
		app => $app,
		returner => $returner,
		appts => $appts,
		settings => $settings,
		time_scopes => \@time_scopes,
		time_lengths => \@time_lengths,
		movements => $movements,
		display_options => \@display_options,
		measure_calc_json => $measure_calc_json,
		evaluation => $returner->{'evaluation'}
	);
	return $returner;
}

sub father_time($data) {
	my $start_time = &subs::rightNow();

	my $scope = $data->{'scope'};
	my $ts = $data->{'ts'};
	my $lock = $data->{'lock'} || 'off';
	my $timestamp = $data->{'timestamp'};
	my ($bt, $temp_timestamp);
	# how many periods an "Nnext" window spans, zero for the other ts values
	my $reach = 0;
	# a caller can ask for a window that many periods wide instead of one,
	# keeping its far edge (the budget's multiplier)
	my $periods = $data->{'periods'} || 1;
	# Months and years are calendar periods: their length is whichever month is
	# being crossed, February included. The others keep the plain span below.
	my $widener = &subs::timespan_widener($scope) || '';
	my $calendar_unit = $widener =~ /^months?$/i ? 'month' : $widener =~ /^years?$/i ? 'year' : undef;
	my $scope_count = $scope;
	$scope_count =~ s/[^0-9.]//g;
	$scope_count = 1 unless length $scope_count;
	$scope_count += 0;

	# A window is only good for the timestamp it was built from: handing the
	# same one to a later request is what put January's month on screen just
	# after midnight on the first.
	if ($gb::father_time->{$scope}->{$ts}->{$lock}->{$periods}->{'timestamp'} == $timestamp &&
		$gb::father_time->{$scope}->{$ts}->{$lock}->{$periods}->{'st'} > $start_time - 10000) {
		$bt = $gb::father_time->{$scope}->{$ts}->{$lock}->{$periods}->{'bt'};
		$temp_timestamp = $gb::father_time->{$scope}->{$ts}->{$lock}->{$periods}->{'tt'};
		$gb::father_time->{$scope}->{$ts}->{$lock}->{$periods}->{'st'} = $start_time;
	}
	else {
		if ($ts eq 'this') {
			$temp_timestamp = $timestamp;
		}
		elsif ($ts =~ 'last') {
			if ($calendar_unit) {
				my $back = 1;
				$back = $1 if $ts =~ /^(\d+)/;
				$temp_timestamp = &subs::calendar_shift($timestamp, -$back * $scope_count, $calendar_unit);
			}
			else {
				$temp_timestamp = &subs::time_span($scope, $timestamp);
				if ($ts =~ /(^[0-9])/) {
					my $tas = $ts;
					$tas =~ s/last//gi;
					# the number itself: the words run out at forty, and the pages
					# of periods walk well past that
					$temp_timestamp = &subs::time_span($tas . $scope, $timestamp);
				}
			}
		}
		elsif ($ts =~ 'next') {
			if ($calendar_unit) {
				my $ahead = 1;
				if ($ts =~ /^(\d+)/) { $reach = $1 + 0; $ahead = $reach; }
				$temp_timestamp = &subs::calendar_shift($timestamp, $ahead * $scope_count, $calendar_unit);
			}
			else {
				# the span this scope is worth: "next" is the span after this one,
				# "Nnext" is the next N spans counting this one, so 2next in week is
				# this week plus next week
				my $span_bt = &subs::time_span($scope, $timestamp);
				my $span = $timestamp - $span_bt;
				$temp_timestamp = $span + $timestamp;
				if ($ts =~ /(^[0-9])/) {
					my $tas = $ts;
					$tas =~ s/next//gi;
					$reach = $tas + 0;
					$temp_timestamp = $timestamp + $span * $reach;
				}
			}
		}

		if ($lock eq 'on' && grep { &subs::timespan_widener($scope) =~ /\Q$_\E/i } qw/minute hour day week month year/) {
			# Locked windows are counted in whole periods off the one the request
			# is in: "last" is the period before this one, "2next" is this one and
			# the next, and the number in a scope such as "3day" widens them.  The
			# periods come off the calendar, since a day is not always 24 hours
			# long and millisecond steps drift across daylight saving.
			my $unit = lc $scope;
			$unit =~ s/[^a-zA-Z]//gi;
			my $multiplier = $scope;
			$multiplier =~ s/[^0-9.]//gi;
			$multiplier = 1 unless $multiplier;
			my $shift = 0;
			my $units = $multiplier;
			if ($ts =~ 'last') {
				$shift = -1;
				$shift = -$1 if $ts =~ /^(\d+)/;
			}
			elsif ($ts =~ 'next') {
				if ($ts =~ /^(\d+)/ && $1 > 1) { $units = $multiplier * $1 }
				else { $shift = 1 }
			}
			if ($periods > 1) {
				$shift -= ($periods - 1) * $units;
				$units *= $periods;
			}
			my $at = localtime($timestamp / 1000);
			my $period_start = sub {
				my $offset = shift;
				if ($unit eq 'minute') {
					return timelocal(0, $at->min, $at->hour, $at->mday, $at->mon - 1, $at->year) * 1000 + $offset * 60000;
				}
				if ($unit eq 'hour') {
					return timelocal(0, 0, $at->hour, $at->mday, $at->mon - 1, $at->year) * 1000 + $offset * 3600000;
				}
				if ($unit eq 'year') {
					return timelocal(0, 0, 0, 1, 0, $at->year + $offset) * 1000;
				}
				if ($unit eq 'month') {
					my $index = $at->year * 12 + ($at->mon - 1) + $offset;
					return timelocal(0, 0, 0, 1, $index % 12, int($index / 12)) * 1000;
				}
				if ($unit eq 'week') {
					# weeks start on Sunday, so step off the Sunday of this week
					my $sunday = timegm(0, 0, 0, $at->mday, $at->mon - 1, $at->year) - $at->strftime('%w') * 86400;
					my @date = gmtime($sunday + 7 * $offset * 86400);
					return timelocal(0, 0, 0, $date[3], $date[4], $date[5]) * 1000;
				}
				my @date = gmtime(timegm(0, 0, 0, $at->mday, $at->mon - 1, $at->year) + $offset * 86400);
				return timelocal(0, 0, 0, $date[3], $date[4], $date[5]) * 1000;
			};
			$bt = $period_start->($shift);
			# A window that names periods ahead counts from the request: the part
			# of this period already spent is behind the row and belongs to "this",
			# not to the rows past it.  The far edge stays the period the name
			# counts to, and the unlocked windows already start here.
			$bt = $timestamp if ($ts =~ /next/ && $bt < $timestamp);
			$temp_timestamp = $period_start->($shift + $units);
		}
		else {
			if ($calendar_unit) {
				$bt = $reach > 1 ? $timestamp : &subs::calendar_shift($temp_timestamp, -$scope_count, $calendar_unit);
				$bt = &subs::calendar_shift($temp_timestamp, -$scope_count * $periods, $calendar_unit) if $periods > 1;
			}
			else {
				$bt = $reach > 1 ? $timestamp : &subs::time_span($scope, $temp_timestamp);
				$bt = $temp_timestamp - ($temp_timestamp - $bt) * $periods if $periods > 1;
			}
		}
	}

	$gb::father_time->{$scope}->{$ts}->{$lock}->{$periods} = { bt => $bt, tt => $temp_timestamp, st => $start_time, timestamp => $timestamp };

	return ($bt,$temp_timestamp);
}


get '/manager/icons' => sub($c) {
	# the desktop's own buttons are rendered with whichever icon set was active at
	# the time, so when the set changes the browser asks what the new one calls
	# each of the paths it is already showing. A live theme change passes refresh,
	# because the worker handling this request may still hold the other cut in
	# its short memo.
	&subs::icon_set_forget() if $c->param('refresh');
	my $paths = eval { decode_json $c->param('paths') } || [];
	my %icons;
	foreach my $p ( @{$paths} ) {
		next unless defined $p && $p =~ m{^/};
		$icons{$p} = &subs::icon_for($p);
	}
	$c->render(json => { icons => \%icons });
};

post '/manager/configure/colour_update' => sub($c) {
	# The theme stopped repainting appointments on its own, so this is the
	# deliberate version of it, per device: colours that are no longer part of the
	# theme get a stable theme colour for that app, the rest are left alone.
	my $device = $c->param('device') || &subs::device_setter();
	my $rows = &subs::db_query('select distinct app, value from settings where setting = ? and device = ?', 'colour', $device)->hashes;
	my $updated = 0;
	foreach my $row ( @{$rows} ) {
		my $app = $row->{'app'};
		next unless $app;
		next if grep { lc($_) eq lc($app) } @gb::protected;
		my $colour = &subs::theme_colour_grabber({ app => $app, existing => $row->{'value'}, device => $device });
		$updated++ if defined $colour && lc($colour) ne lc($row->{'value'} || '');
	}
	# the desk top and the stored clothesline both paint from caches, so rebuild them
	# the same way a single colour change does before telling the browsers to redraw
	&subs::hang_to_dry() if $updated;
	&Websocket::send('server', { console => 'if (typeof calculator === "function") { calculator(); }' }) if $updated;
	$c->render(json => { updated => $updated, device => $device });
};

get '/manager/configure/appointment_list' => sub($c) {
	my ($db,$database,$sql) = &subs::database_grabber();
	my $results = &subs::db_query("select distinct app from settings where setting=? and value=?",'visible','checked');
	my $appointments = $results->hashes;
	foreach my $a (@{$appointments}) {
		$a->{'app'} = &subs::unformat_name($a->{'app'});
		$a->{'formatted_name'} = &subs::format_name($a->{'app'});
	}
	$c->render(
		template => 'configure/appointment_lister',
		appts => $appointments,
		timestamp => &subs::rightNow()
	);
};

get '/manager/configure/appointment_display' => sub($c) {
	my $app = &subs::unformat_name($c->param('app'));
	my $appts = &log_reader({ app => $app, view => 'appointment_display' });
	my $abilities = $gb::abilities;
	my $setting = eval { return decode_json $c->param('setting') } || [];
	if (scalar @{$setting} > 0) {
		$abilities = {};
		foreach my $s ( @{$setting} ) {
			$abilities->{$s} = $gb::abilities->{$s} if $gb::abilities->{$s};
		}
	}
	my $config_window = $c->param('config');
	my $preferred_appts = {};

	my $measures = eval { return decode_json $appts->{$app}->{'setting'}->{'app_measures'} } || {};
	foreach my $m ( keys %{$measures} ) {

	}
	$appts->{$app}->{'setting'}->{'measures'} = join ',', keys %{$measures};
	$appts->{$app}->{'setting'}->{'app_measures'} = $measures;

	my $packaging = eval { return decode_json $appts->{$app}->{'setting'}->{'packaging'} } || {};
	$appts->{$app}->{'setting'}->{'app_packaging'} = $packaging;
	$appts->{$app}->{'setting'}->{'packaging'} = join ',', map { $_ = $packaging->{$_}->{'name'} } keys %{$packaging};

	my $home_plate = eval { return decode_json $appts->{$app}->{'setting'}->{'home_plate'} } || {};
	$appts->{$app}->{'setting'}->{'app_home_plate'} = $home_plate;
	$appts->{$app}->{'setting'}->{'home_plate'} = $home_plate->{'latitude'} . ' ' . $home_plate->{'longitude'};


	foreach my $k (keys %{$appts}) {
		if ($k =~ /^__/) {
			next;
		}
		else {
			$preferred_appts->{$k} = $appts->{$k}
		}
	}
	$c->render(
		template => 'configure/appointment_list',
		appts => $preferred_appts,
		'pos' => $gb::pos,
		'abilities' => $abilities,
		config_window => $config_window,
		app_themes => &subs::app_theme_map(),
		timestamp => &subs::rightNow()
	);
};

post '/manager/configure/permissions' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my ($av_data);
	if ($c->param('avData')) {
		$av_data = decode_json($c->param('avData'));
	}
	my $constraints = $c->param('constraints');
	foreach my $av (@{$av_data}) {
		if ($av->{'kind'} eq 'audioinput') {
			$av->{'icon'} = 'microphone';
		}
		elsif ($av->{'kind'} eq 'videoinput') {
			$av->{'icon'} = 'monitor';
		}
		elsif ($av->{'kind'} eq 'audiooutput') {
			$av->{'icon'} = 'speaker';
		}
	}
	# On the phone the browser prompts are not the whole story: the termux-*
	# commands need Android runtime permissions too, so also raise the JawnOS API
	# grant-all screen, which owns them (it is exported for exactly this).
	if (&subs::device_setter() eq 'mobile') {
		system('/system/bin/am', 'start', '-n', 'com.termux.api/com.termux.api.JawnGrantAllActivity');
	}
	$c->render(json => { av_data => $av_data, constraints => $constraints });
};

get '/manager/configure' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my ($db,$database,$sql) = &subs::database_grabber();

	my $browser_tab = $c->param('browser_tab');
	my $browser_tab_id = $c->param('browser_tab_id');

	my $web_query = &subs::db_query('select * from websockets where browser_tab_id = ?',$browser_tab_id);
	my $websockets = $web_query->hashes;
	my $pseudonyms = &pseudonym_maker('config','');

	my $content = $c->render_to_string(
		template => 'configure/configure',
		config => &subs::config_reader(),
		device => $device,
		websockets => $websockets,
		pseudonyms => $pseudonyms,
	);
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'configure', title => 'Configure', contents => $content },$timestamp);
	$c->render(text => $contents);
};


post '/manager/configure' => sub ($c) {

	my $app = $c->param('app');
#	&subs::cache_delete({ app => $app });
	my $setting = $c->param('setting');
	my $value = $c->param('value');
	my $timestamp = $c->param('timestamp');
	my $source = $c->param('source');
	# a destructive rename plans its history drops before the rows are relabelled,
	# then tombstones them under the unified name once the rename has run
	my $history_plan;
	my $renamed_to;
	if ($setting eq 'measures') {
		$setting = 'app_measures';
		my $measures = eval { decode_json &subs::setting_grabber({ app => $app, setting => 'app_measures' }) } || {};
		my @potentials = split ',', $value;

		foreach my $p ( @potentials ) {
			unless ($measures->{$p}) {
				$measures->{$p} = 0;
			}
		}
		foreach my $m ( keys %{$measures} ) {
			unless ( grep { $_ eq $m } @potentials ) {
				delete $measures->{$m};
			}
		}

		$value = encode_json $measures;
	}
	if (grep { $setting eq $_ } qw/ollama_key cloudflare_token openai_key anthropic_key xai_key google_key mistral_key groq_key openrouter_key deepseek_key/ ) {
		$log->info($value);
		$value = &subs::note_encrypter(&subs::suds_grabber(), $value);
		$log->info($value);
	}
	# a rename into a name the house already knows is a merge: the two apps'
	# settings meet on one row each, so the panel picks which value wins per
	# setting (and which merge naturally) before the rename runs. A conflict is
	# only something to choose, though: two apps that share no setting simply join,
	# and reporting a conflict over an empty list left the panel's own button
	# re-asking forever - a rename that visibly did nothing at all.
	if ($setting eq 'name_change') {
		my $new_app = &subs::unformat_name($value);
		$renamed_to = $new_app;
		my $choices = eval { return decode_json $c->param('choices') } || {};
		my $appt_policy = $c->param('appt_policy') || '';
		my $target = &subs::db_query('select 1 from settings where app = ? limit 1', $new_app)->hashes->[0];
		my $target_appts = &subs::db_query('select 1 from appointments where app = ? limit 1', $new_app)->hashes->[0];
		my $pairs = &subs::name_change_pairs($app, $new_app);
		# the panel is also worth showing when only the history overlaps: it is
		# where the per-side summary and the history policy live
		if (($target || $target_appts) && !scalar keys %{$choices} && !$appt_policy && (scalar @{$pairs} || $target_appts)) {
			my $history = &subs::name_change_history($app, $new_app);
			$c->render(json => { conflict => 1, app => $app, new => $new_app, pairs => $pairs, appointments => $history });
			return;
		}
		if ($appt_policy && $appt_policy ne 'keep_all' && $appt_policy ne 'flag') {
			$history_plan = &subs::name_change_history_plan($app, $new_app, $appt_policy);
			if ($history_plan && $history_plan->{'count'}) {
				# a destructive history policy is the one write worth a fresh snapshot
				my $fresh = eval { &subs::records_backup_ensure_fresh(600000) };
				&subs::log_writer('name merge backup ' . (($fresh && $fresh->{'fresh'}) ? ($fresh->{'path'} || 'fresh') : 'FAILED')
					. ' before ' . $app . ' -> ' . $new_app . ' policy=' . $appt_policy);
			}
		}
		&subs::name_change_apply($app, $new_app, $choices) if scalar keys %{$choices};
	}
	my $setting_data = { app => $app, setting => $setting, value => $value, timestamp => $timestamp, source => 'panel' };
	# an appointment type's theme is a property of the type, not of the machine
	# that happened to pick it: keep it on the house-wide row
	$setting_data->{'device'} = 'all' if $setting eq 'theme';
	&subs::setting_setter($setting_data);
	# the rename has relabelled the surviving rows, so a planned drop can now be
	# tombstoned under the name every peer will be using
	&subs::name_change_history_apply_plan($renamed_to, $history_plan) if $history_plan && $renamed_to;
	# changing the theme of an app that is running re-paints the desktop now
	&subs::appointment_theme_push() if $setting eq 'theme';
	undef @appointments;
	my $appts = &log_reader({ app => $c->param('app'), view => 'appointment_display' });
	my $measures = eval { decode_json $appts->{$app}->{'setting'}->{'app_measures'} } || {};
	$appts->{$app}->{'setting'}->{'measures'} = join ',', keys %{$measures};
	$appts->{$app}->{'setting'}->{'app_measures'} = $measures;

	my $packaging = eval { decode_json $appts->{$app}->{'setting'}->{'packaging'} } || {};
	$appts->{$app}->{'setting'}->{'app_packaging'} = $packaging;
	$appts->{$app}->{'setting'}->{'packaging'} = join ',', map { $_ = $packaging->{$_}->{'name'} } keys %{$packaging};

	my $home_plate = eval { return decode_json $appts->{$app}->{'setting'}->{'home_plate'} } || {};
	$appts->{$app}->{'setting'}->{'app_home_plate'} = $home_plate;
	$appts->{$app}->{'setting'}->{'home_plate'} = $home_plate->{'latitude'} . ' ' . $home_plate->{'longitude'};

	if ($setting eq 'enc' && $value eq 'on') {
		&subs::file_encrypter({ app => $app });
	}
	elsif ($setting eq 'enc' && $value eq 'off') {
		&subs::file_decrypter({ app => $app });
	}



	my $preferred_appts = {};
	foreach my $k (keys %{$appts}) {
		if ($k =~ /^__/) {
			next;
		}
		else {
			$preferred_appts->{$k} = $appts->{$k}
		}
	}
	if ($setting eq 'navigation') {
		$value = &subs::time_abbrev_translator($value, $timestamp);
	}

	&Websocket::send($app, { console => '$(\'.appointment[app="' . $app . '"]\').attr(\'' . $setting . '\', \'' . $value . '\');' });
	if ($source eq 'panel') {

		my $window = &centre_view_grabber({ c => $c, app => $c->param('app'), timestamp => $timestamp, cached => 'no' });
		$c->render(text => $window);

	}
	else {
		$c->render(
			template => 'configure/appointment_list',
			appts => $preferred_appts,
			abilities => $gb::abilities,
			app_themes => &subs::app_theme_map(),
			timestamp => &subs::rightNow()
		);
	}
};



# The Sys panel is loaded with the whole browser localStorage in the request. As a
# GET that rode the query string, which the manager caps at MOJO_MAX_LINE_SIZE
# (64k) - once localStorage grew past it the request was answered by the Gate page
# and injected into the panel, so Sys "would not load". Accept POST too so the
# panel can send that payload in the body.
any '/manager/configure/system_list' => sub($c) {
	my $local_storage = eval { return decode_json $c->param('local_storage') } || {};
	my $settings = { };
	my ($db,$database,$sql) = &subs::database_grabber();
	foreach my $dt ( @gb::device_types ) {
		$settings->{$dt} = &subs::settings_grabber({ app => '__president', device => $dt });
	}
	my $stats = [];
	# list the tables from the metadata table instead of shelling out to the
	# sqlite3 binary on every load of the system settings page
	my $table_names = &subs::db_query("select name from sqlite_master where type = 'table' order by name")->hashes;
	foreach my $row ( @{$table_names} ) {
		my $d = $row->{'name'};
		my $results = &subs::db_query('select count(*) from ' . $d);
		push @{$stats}, { formatted_table => &subs::format_name($d), table => $d, count => $results->hash->{'count(*)'} };
	}
	push @{$stats}, { formatted_table => 'Downloads', table => 'download', count => &subs::setting_grabber({ app => '__president', setting => 'download_count' }) || 0 };

	my $evaluation = &subs::cache_get({ app => '__president', context => 'evaluation' }) || {};

	my $last_restart = -e $duty_file ? read_file($duty_file) : &subs::rightNow();
	$last_restart =~ s/\s+$// if defined $last_restart;

	$settings->{$device}->{'stats'} = $stats;
	$c->render(
		template => '/configure/system_setting_list',
		stats => $stats,
		local_storage => $local_storage,
		evaluation => $evaluation,
		ai_house => &subs::ai_house_report(),
		ai_balance => &subs::ai_balance_report(),
		settings => $settings,
		last_restart => $last_restart,
		device => $device
	);
};

