post '/manager/configure/new_database' => sub($c) {
	my ($db,$database) = &subs::database_grabber();
	&subs::db_query('VACUUM');
	my $timestamp = $c->param('timestamp');
	$c->param('reason' => 'new_database');
	$c->render(text => $database) unless $c->param('credential');
	my $president = $c->param('president');
	$president = &subs::home($president);
	my $old_db = $database;
	my $download_location = &subs::home('~/.president');
	my $temp_folder = &subs::home($download_location . '/' . &subs::random_string_creator(10)) . '/';
	`mkdir -p $temp_folder` unless -e "$temp_folder";

	$database = $temp_folder . $president . '.db';
	my $enc_file = $temp_folder . $president . '.enc';
	my $secret = $c->param('credential');
	my $credential = &subs::session_suds($c);
	my $misc_setting_list = &misc_setting_list();
	my $server_time = &subs::rightNow();
	`touch $database`;
	my $schema_file = $temp_folder . 'schema.sql';
	# the statistics and sequence tables are internal: replaying their CREATE is
	# a parse error ("object name reserved for internal use: sqlite_sequence"),
	# and SQLite builds them again where they are wanted
	`sqlite3 $old_db .schema | grep -vE 'sqlite_stat|sqlite_sequence' > $schema_file`;
	my $command = `sqlite3 $database < $schema_file`;
	`shred -u $schema_file`;
	$sql = Mojo::SQLite->new('sqlite:' . $database);
	$db = $sql->db;
	$db->query('PRAGMA cache_size = -200000');
	$db->query('PRAGMA synchronous = NORMAL');
	$db->query('PRAGMA mmap_size=266435456');
	$db->query('PRAGMA temp_store=MEMORY');
	$db->query('PRAGMA busy_timeout = 5000;');
	my $secretive = &subs::encrypter($secret,$secret);
	my $warranty = &subs::ago_calc(&subs::setting_grabber({ app => 'me', setting => 'warranty' }) || '-10d', $timestamp);

	$db->insert('security', { level => 1, database => $database, timestamp => $timestamp, server_time => $server_time, credential => $secretive, uuid => &subs::random_string_creator(30) });
	# the door: the password sealed with itself, apart from the key canary, so a
	# later password change never re-keys this house
	$db->insert('security', { level => 'door', database => $database, timestamp => $timestamp, server_time => $server_time, credential => $secretive, uuid => &subs::random_string_creator(30) });
	foreach my $set ( qw/misc/ ) {
		my $settings = &subs::db_select('settings', undef, { app => $set })->hashes;
		foreach my $s ( @{$settings} ) {
			$db->insert('settings', $s);
		}
	}

	my $data = &qrcode_generator({
		timestamp => $timestamp + 1,
		app => '__president',
		name => 'citizen',
		privilege => 'citizen',
		project => 'personal',
		debriefer => '{}',
		nic => 'lo',
		warranty => '-100y',
		db => $db,
		database => $database
	});
	$db->insert('tickets', $data);

	my $backup = `sqlite3 $database ".backup '$database.1.db'"`;
	my $encryption_standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard' } ) || "aes-256-ctr";
	my $encrypt = &subs::openssl_file_crypt('e', $encryption_standard, $secret, $database . '.1.db', $enc_file, 0, 1);
	my $appendage = $universal_splitter . &subs::encrypter($secret,$encryption_standard);
	`echo "$appendage" >> $enc_file`;
#	my $devices = &subs::device_lister($timestamp);

#	&subs::backup_now($c);
	`shred -u $database`;
#	`shred -u $database.1.db`;
	`shred -u $database-shm`;
	`shred -u $database-wal`;
	my $new_enc_file = &subs::database_dir() . '/' . $president . '.enc';
	`mv -v $enc_file $new_enc_file`;
#	`rm -R $temp_folder`;
#	$database = $old_db;
	&subs::say_it('New Database ' . $c->param('president'));
	$c->render(text => $database);
};


post '/manager/configure/restore_now' => sub($c) {
	my $filename = $c->param('filename');
	my $path = $filename;
	$c->param('reason' => 'restore_database');
	my ($db) = &subs::database_grabber();
	my $credentials = &subs::db_select('security', ['level','credential'], {  });
	my $creds = $credentials->hashes;
	@{$creds} = grep { $_->{'level'} ne 'padlock' } @{$creds};
	@{$creds} = reverse @{$creds};
	my $disposition->{'status'} = 'fail';
	my $encryption_standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard' } ) || "aes-256-ctr";
	foreach my $cred ( @{$creds} ) {
		my $cr = &subs::decrypter(&subs::session_suds($c),$cred->{'credential'});
		if ($path =~ /enc$/gi) {
			$filename =~ s/.enc$//gi;
			my $t_database = &subs::database_path() . '.restoring';
#			my $scrypt = `printf "$cr" | scrypt dec -P $path $t_database`;
			my $data = `tail $path`;
			my @split_data = split $universal_splitter, $data;
			$encryption_standard = &subs::decrypter($cr, $split_data[1]);
			my $scrypt = &subs::openssl_file_crypt('d', $encryption_standard, $cr, $path, $t_database, 0, 1);
			if (-s $t_database > 5000) {
				&subs::backup_now($c);
				`shred -u $database`;
				`shred -u $database-shm`;
				`shred -u $database-wal`;
				`mv -v $t_database $database`;
				$sql = Mojo::SQLite->new('sqlite:' . $database);
				my $db = $sql->db;

				my $secret = &subs::decrypter($cr,&subs::db_select('security', ['credential'], { level => 1 })->hash->{credential});
				if (secure_compare $cr, $secret) {
					$disposition->{'disposition'} = $database;
					&subs::vault_seed($secret, 1);
					$c->session('suds_id' => &subs::suds_id($secret));
					$c->session('database' => $database);
					$disposition->{'status'} = 'succeed';
					last;
				}
				else {
					$c->session('authentication' => 'rejected');
				}
			}
		}
	}

	$disposition = encode_json $disposition;
	$c->render(text => $disposition);
};



get '/manager/configure/database_vacuum' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $html = "You are about to clean up settings from the following orphaned apps<br><br>";

	my @unique_settings = &database_vacuum_bag();

	foreach my $us ( @unique_settings ) {
		$html .= '<input type="checkbox" checked="checked" app="' . $us . '" class="database_vacuum_checkbox">' . &subs::format_name($us) . "<br>";
	}

	$html .= '<img src="/images/decipherable/vacuum.png" id="database_vacuum_confirm" class="medium_thumb">';
	$html = "Your house is clean!" if scalar @unique_settings == 0;
	$c->render(json => { html => $html });
};

sub database_vacuum_bag() {
	my @protection = @gb::protected;
	push @protection, keys %{$gb::known_appts};
	my $settings = &subs::db_query('select * from settings where setting !=?', 'uuid')->hashes;

	foreach my $protect ( @protection ) {
		@{$settings} = grep { $_->{'app'} ne $protect } @{$settings};
	}
	my $appts = &subs::db_query('select distinct(app) from appointments')->hashes;
	my @unique_settings;
	foreach my $s ( @{$settings} ) {
		unless ( grep { $_->{'app'} eq $s->{'app'} } @{$appts} ) {
			push @unique_settings, $s->{'app'} unless grep { $_ eq $s->{'app'} } @unique_settings;
		}
	}
	return @unique_settings;
}

post '/manager/configure/database_vacuum_confirm' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $checkboxes = $c->param('checkboxes');
	$checkboxes = eval { return decode_json $checkboxes } || [];
	my $html = "You have cleaned:<br><br>";
	foreach my $us ( @{$checkboxes} ) {
		&subs::db_delete('settings', { app => $us });
		$html .= &subs::format_name($us) . "<br>";
	}

	$html .= '
		';
	$c->render(json => { html => $html });
};

get '/manager/configure/database_doctor' => sub($c) {
	my ($db,$database,$sql) = &subs::database_grabber();
	my $returner = { tables => [], auuid => &subs::random_string_creator(20) };
	my $tables = `sqlite3 $database .tables`;
	@{$returner->{'tables'}} = split ' ', $tables;


	$returner->{'html'} = '<h2>You are about to perform surgery on ' . $database . '</h2>
		<h4>This process is irreversible, unless you have backups or whatever!</h4>';
	foreach my $table ( @{$returner->{'tables'}} ) {
		my $counter = &subs::db_query('select count(*) from ' . $table);
		my $count = $counter->hash->{'count(*)'};
		$returner->{'count'}->{$table} = $count;
		my $existing = &subs::db_query('select * from ' . $table)->hashes;
		my $delta = ($count - scalar @{$existing});
		my $colour = 'black';
		my $repairable = [];
		if ($delta != 0) {
			$colour = 'red';
			#if ($existing->[-1]->{'app'}) {
				my $repairs = &subs::db_query('select distinct(app) from ' . $table)->hashes;
				if ($table eq 'settings') {
				#	push @{$repairs}, ({ app => 'me' }, { app => 'misc' }, { app => '__president' });
				}
				foreach my $a ( @{$repairs} ) {
					my $ok = &subs::db_select($table, undef, { app => $a->{'app'} })->hashes;
					push @{$repairable}, @{$ok};
			#	}
			}
		}


		$returner->{'html'} .= '<span style="color:' . $colour .';"><b><u style="font-size:20px;"> ' . $table . '</u> Count:</b> ' . $count . ' <b>Shows:</b> ' . scalar @{$existing} . ' <b>Delta:</b> ' . $delta;
		if (scalar @{$repairable} > 0) {
			$returner->{'html'} .= ' <b>Repair: </b>' . scalar @{$repairable};
		}
		$returner->{'html'} .= '</span><br>';
	}
	$returner->{'html'} .= '
		<img src="/images/jbuttons/doctor.png" id="database_doctor_confirm" class="medium_thumb">';
	$c->render(json => $returner);
};

post '/manager/configure/database_doctor_confirm' => sub($c) {
	my ($db,$database,$sql) = &subs::database_grabber();
	my $auuid = $c->param('auuid') || &subs::random_string_creator(20);

	my $returner = { tables => [], count => {} };
	my $html = '<h2>Now repairing ' . $database . '</h2><br><h4></h4><br>';
	&Websocket::send('server', { yellow => $html, uuid => $auuid });
	my $download_location = &subs::home('~/.president');
	my $temp_folder = &subs::home($download_location . '/' . &subs::random_string_creator(10));
	`mkdir -p $temp_folder` unless -e "$temp_folder";
	my $ndatabase = $temp_folder . '/' . &subs::random_string_creator(21) . '.db';
	my $tdatabase = $temp_folder . '/' . &subs::random_string_creator(20) . '.db';
	`touch $tdatabase`;
	`touch $ndatabase`;
	`sqlite3 $database .schema | grep -vE 'sqlite_stat|sqlite_sequence' > $temp_folder/schema.sql`;
	my $backup = `sqlite3 $database ".backup '$tdatabase'"`;

	my $command = `sqlite3 $ndatabase < $temp_folder/schema.sql`;
	my $nsql = Mojo::SQLite->new('sqlite:' . $ndatabase);
	my $ndb = $nsql->db;
	my $tsql = Mojo::SQLite->new('sqlite:' . $tdatabase);
	my $tdb = $tsql->db;
	my $tables = `sqlite3 $ndatabase .tables`;
	@{$returner->{'tables'}} = split ' ', $tables;

	foreach my $table ( @{$returner->{'tables'}} ) {
		my $counter = $tdb->query('select count(*) from ' . $table);
		my $count = $counter->hash->{'count(*)'};
		$returner->{'count'}->{$table} = $count;

		my $existing = $tdb->query('select * from ' . $table)->hashes;
		if (scalar @{$existing} != $count) {
			my $html = '<h2>Now repairing ' . $count . ' ' . $table . '</h2><br><h4></h4><br>';
			&Websocket::send('server', { yellow => $html, uuid => $auuid });

			my $repairable = [];
			#if ($existing->[-1]->{'app'}) {
				my $repairs = $tdb->query('select distinct(app) from ' . $table)->hashes;
				foreach my $a ( @{$repairs} ) {
					my $ok = $tdb->select($table, undef, { app => $a->{'app'} })->hashes;
					foreach my $okay ( @{$ok} ) {
						my $check = $tdb->select($table, $okay)->hashes;
						if (scalar @{$check} == 0) {
							eval { $ndb->insert($table, $okay) };
						}
						else {

						}

					}
					push @{$repairable}, @{$ok};
				}
			#}

		}
		else {
			my $html = '<h2>Now inserting ' . $count . ' ' . $table . '</h2><br><h4></h4><br>';
			&Websocket::send('server', { yellow => $html, uuid => $auuid });
			foreach my $i ( @{$tdb->select($table, undef, {})->hashes} ) {
				$ndb->insert($table, $i);
			}
		}
	}
	$backup = `sqlite3 $ndatabase ".backup '$database'"`;
	`shred -u $temp_folder/schema.sql`;
	`shred -u $tdatabase`;
	`shred -u $ndatabase`;
	`rm -R $temp_folder`;
	$c->render(json => $returner);
};

get '/manager/configure/vacuum_app' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $app = $c->param('app');
	my $html = '<h2>You are about to delete</h2><h1>' . &subs::format_name($app) . '</h1>
		<h4>This process is irreversible, unless you have backups or whatever!</h4>
		<img src="/images/decipherable/vacuum.png" id="vacuum_app_confirm" app="'. $app . '" class="medium_thumb">';

	$c->render(text => $html );
};

post '/manager/configure/vacuum_app_confirm' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $app = $c->param('app');
	&subs::vacuum_app($app);
	&deletion_registration({ table => 'appointments', app => $app, scope => 'vacuum' });
	my $html = '<h1>' . &subs::format_name($app) . ' is gone forever!</h1>
	<h4>I hope you thought long and hard about it!</h4>';
	$c->render(text => $html );
};


post '/manager/configure/merge_database' => sub($c) {

	my $filename = $c->param('filename');
	my $action = $c->param('action');
	&subs::subprocessor(sub {
    Mojo::IOLoop->reset;
		my $configuration = {
			file => $filename,
			signatorial => &subs::signatorial_designer(),
			misc_settings => &misc_setting_list()
		};
		my $disposition = &merge_database($c,$configuration);
		my $temporary_file = $disposition->{'temporary_file'};
		#`shred -u $temporary_file` if -e $temporary_file;
		#`shred -u $temporary_file-shm` if -e $temporary_file;
		#`shred -u $temporary_file-wal` if -e $temporary_file;
		$disposition = encode_json $disposition;
	}, { name => 'merge database' });
	my $disposition = { status => 'working' };
	$c->render(json => $disposition);
};

# Merge one table's rows into the live database. The row source is a closure so the
# encrypted-snapshot path (rowid batches from a temp SQLite) and the row-stream path
# share every table-specific rule: uuid upsert, protected settings, utility
# controller keys, window state, continent temporary rows, file mirrors, deletions.
# The body keeps its original `next` statements: a one-pass ROW label makes a row's
# `next` leave just that row, while a `next` inside a nested loop still binds to it.
sub merge_table_rows {
	my ($ctx, $q, $next_row, $results_size, $count, $table_total, $expected) = @_;
	my $configuration = $ctx->{'configuration'};
	my $misc_settings = $ctx->{'misc_settings'};
	my $device = $ctx->{'device'};
	my $deletions = $ctx->{'deletions'};
	# A row this machine deleted stays deleted even when a stale peer still
	# carries it. The peer's own list covers the first minute, but a machine
	# that only serves (and never pulls) keeps sending the old row forever; the
	# durable tombstone in sync_log is what makes the local deletion final. A
	# `single` tombstone drops the whole row; a `file` tombstone removes just
	# the named attachment, so an appointment with surviving photos stays.
	my (%tombstone_single, %tombstone_file);
	if ($q eq 'appointments' || $q eq 'mailbox') {
		foreach my $tomb ( @{ &subs::db_query('select uuid, scope, additional from sync_log where tbl = ?', $q)->hashes || [] } ) {
			my $scope = $tomb->{'scope'} || '';
			if ($scope eq 'single') { $tombstone_single{$tomb->{'uuid'}} = 1; }
			elsif ($scope eq 'file') {
				my $extra = eval { return decode_json $tomb->{'additional'} } || {};
				$tombstone_file{$tomb->{'uuid'}}->{$extra->{'file_uuid'}} = 1 if $extra->{'file_uuid'};
			}
		}
	}
	my $universal_settings = $ctx->{'universal_settings'};
	my $updateables = $ctx->{'updateables'};
	my $sync_job = $ctx->{'sync_job'};
	my $auuid = $ctx->{'auuid'};
	my $colour = $ctx->{'colour'};
	my $merge_short = 0;
	# A peer on newer code can carry a column this database has not been migrated for.
	# The insert then fails ("table X has no column named Y") and the same batch is
	# pulled again on every tick - the column equivalent of the unknown-table skip in
	# sync_rows_pull. Drop the columns this table does not have; `uuid` always stays
	# because it names the row.
	my %local_columns = map { $_->{'name'} => 1 } @{ &subs::db_query('select name from pragma_table_info(?)', $q)->hashes || [] };
	my %skewed_columns;
						if ($sync_job) {
							my $shown = $expected || $results_size;
							my %step = (label => 'merge ' . $q, state => 'running', current => 0);
							$step{'total'} = $shown if $shown;
							$step{'note'} = $shown . ' row' . ($shown == 1 ? '' : 's') if $shown;
							&subs::sync_job_step($sync_job, 'merge:' . $q, \%step);
						}
						#&subs::say_it('Now merging ' . $results . ' ' .$q);
						my $progress = $count / $table_total * 100;
						my $html = '<h3>Now merging ' . ($expected || $results_size) . ' ' . $q . '</h3><br>';
						&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour,
							progress => int($count / (($table_total) || 1) * 100), state => 'running' });
						my $percentage = 0;
						my $last_percent = 0;
						my $last_alert = &subs::rightNow();
						my $job_alert = $last_alert;
						my $start_time = $last_alert;
						# Book-keeping for the audit trail: a table can report "N/N done"
						# while an insert silently failed inside the eval below. Count what
						# the snapshot held, what the cursor actually yielded, and what
						# landed, so a short merge names itself in the log instead of
						# looking complete.
						my $rows_read = 0;
						my $rows_inserted = 0;
						my $rows_updated = 0;
						my @insert_errors;
						# Read the snapshot in bounded batches instead of holding one cursor
						# across the loop. Every row does app-database work (select, insert,
						# sync_job writes); if any of those finishes the snapshot's statement
						# - which is what the log showed: every table read exactly one row,
						# the rest silently lost - a materialised batch is immune. It also
						# keeps a whole table's rows out of memory.
	my $merge_one = sub {
		my ($r, $n) = @_;
		ROW: for my $once (1) {
			if (%local_columns && ref $r eq 'HASH') {
				my @unknown = grep { $_ ne 'uuid' && !$local_columns{$_} } keys %{$r};
				if (@unknown) {
					delete @{$r}{@unknown};
					$skewed_columns{$_} = 1 for @unknown;
				}
			}
							my @resulters = @{&subs::db_select($q, undef, { uuid => $r->{'uuid'} })->hashes};
							my $h = $resulters[0];
							next ROW if ($q eq 'appointments' || $q eq 'mailbox') && $tombstone_single{$r->{'uuid'}};
							$percentage = $results_size ? sprintf("%.2f", $n / $results_size * 100) : 0;
							if ($sync_job && &subs::rightNow() >= ($job_alert + 250)) {
								my %progress = (current => $n);
								# A row stream has no snapshot size (`$results_size` is 0); keep
								# the total the map or first batch already named instead of
								# overwriting it with zero.
								$progress{'total'} = $results_size || $expected if ($results_size || $expected);
								&subs::sync_job_step($sync_job, 'merge:' . $q, \%progress);
								$job_alert = &subs::rightNow();
							}
							if ($r->{'timestamp'}) {
								if ($percentage >= $last_percent && $results_size > 1 && &subs::rightNow() >= ($last_alert + 250)) {
									my $speed = abs sprintf("%.2f", $n / ($start_time - &subs::rightNow()) * 1000);
									my $remaining = &subs::duration_sayer(((&subs::rightNow() - $start_time) / $percentage) * (100 - $percentage) / 1000);
									my $html = '<b style="font-size:20px">' . $n . ' / ' . $results_size . ' ' . &subs::format_name($q) . ' ' . $percentage . '% @ ' . $speed . '/sec ' . $remaining . '</b><br>' .
										'<progress style="width:70%;height:60px;" value="' . $n . '" max="' . $results_size . '"></progress>';
									$last_percent = $percentage;
									$last_alert = &subs::rightNow();
									&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
								}
								if ($q eq 'websites') {
									&web_history_deleter($r->{'app'});
								}
								if ($q eq 'continent') {
									if ($r->{'type'} eq 'temporary' && $r->{'app'} eq '__president') {
										# A local row AT LEAST this new wins. The sync copies server_time
										# verbatim, so a peer echoes our own temporary row back with the
										# very same stamp; the old strict `>` did not count that as newer,
										# so it deleted the fresh row and then the generic merge below
										# skipped the re-insert (its @resulters still held the deleted
										# row, and server_time was not greater). A phone's own fix then
										# vanished seconds after every navigation run and it borrowed a
										# peer's place instead - the public place that only a manual
										# fix corrected. `>=` keeps the row we hold.
										my $continents = &subs::db_query('select * from continent where app = ? and type = ? and signatorial = ? and cast(server_time as integer) >= cast(? as integer)', $r->{'app'}, $r->{'type'}, $r->{'signatorial'}, $r->{'server_time'})->hashes;
										if (scalar @{$continents} > 0) {
											next;
										}
										# The incoming row is genuinely newer: keep one temporary row per
										# signatorial by dropping our older copies, but never the row the
										# merge is about to write (its uuid is in @resulters above; only
										# the insert/update at the foot of this block can put it back).
										my $older = &subs::db_query('select uuid from continent where app = ? and type = ? and signatorial = ? and uuid != ?', $r->{'app'}, $r->{'type'}, $r->{'signatorial'}, ($r->{'uuid'} || ''))->hashes;
										foreach my $old ( @{$older} ) {
											&subs::db_delete('continent', { uuid => $old->{'uuid'} });
										}
									}
								}
								if ($q eq 'settings') {
									# Window/tab state is the machine's own view, not a setting: a
									# peer's snapshot must never open or move a window here.
									if (($r->{'setting'} || '') =~ /^(?:open_tabs|scrollTop|jopen|dimensions)$/) { next; }
									# The utility controller keeps every machine's jobs in one blob keyed
									# by that machine's signatorial. The generic whole-row replace below
									# would let whichever peer synced last win outright, wiping the other
									# machines' keys (their runtimes then reseed to the built-in
									# defaults - the "jobs all turned off" that started this). Merge the
									# blob per key instead: union the keys, and for a key both sides
									# hold keep the one whose __settings.last_change is newer (ours is
									# always authoritative for our own signatorial).
									if (($r->{'setting'} || '') eq 'utility_controller' && ($r->{'app'} || '') eq '__president') {
										my $sig = &subs::signatorial_designer();
										my %device_key = map { $_ => 1 } @gb::device_types;
										my $local = eval { decode_json &subs::setting_grabber({ app => '__president', setting => 'utility_controller', benign => 1 }) } || {};
										my $theirs = eval { decode_json $r->{'value'} } || {};
										my $merged = {};
										foreach my $k ( keys %{$local} ) { $merged->{$k} = $local->{$k}; }
										foreach my $k ( keys %{$theirs} ) {
											# our own row and the vestigial device-type rows are never taken from
											# a peer: our row is authoritative (the runtime reads only it, keyed
											# by our signatorial), and a device-type row must not be resurrected
											# once pruned. Only other machines' rows merge by last_change.
											next if $k eq $sig || $device_key{$k};
											if (!$merged->{$k}) { $merged->{$k} = $theirs->{$k}; next; }
											my $la = $merged->{$k}->{'__settings'}->{'last_change'} || 0;
											my $lb = $theirs->{$k}->{'__settings'}->{'last_change'} || 0;
											$merged->{$k} = $theirs->{$k} if $lb > $la;
										}
										my $jmerged = encode_json $merged;
										my $jcur = encode_json $local;
										if ($jmerged ne $jcur) {
											# name any navigation toggle this merge is about to change, per row -
											# a third machine's stale copy must not read a job off unnoticed
											foreach my $k ( keys %{$merged} ) {
												my $was = $local->{$k}->{'navigation'}->{'toggle'} // '-';
												my $now = $merged->{$k}->{'navigation'}->{'toggle'} // '-';
												&subs::log_writer('utility merge: ' . substr($k, 0, 8) . ' navigation ' . $was . '->' . $now . ' from ' . substr($r->{'signatorial'} // '?', 0, 8)) if $was ne $now;
											}
											&subs::setting_setter({ app => '__president', setting => 'utility_controller', value => $jmerged, server_time => &subs::rightNow(), sync => 1 });
										}
										next;
									}
									$universal_settings->{$r->{'app'}} = &subs::settings_grabber({ app => $r->{'app'}, device => $device, benign => 1 }) unless $universal_settings->{$r->{'app'}};
									my $protected = 0;
									foreach my $pr ( @gb::protected ) {
										if ($r->{'app'} eq $pr) {
											$protected = 1;
										}
									}
									#next if $protected == 1;
									unless ($universal_settings->{$r->{'app'}}->{'unique'} eq 'checked' || $protected == 1) {
										# A row we already hold at the peer's own server_time counts as present:
										# the write below copies the peer's server_time verbatim, so with a strict
										# '>' the test was false again on the very next sync and every one of
										# the ~29k settings rows was deleted and reinserted, every sync, forever
										# (the 'Now merging N settings' that looked stuck). '>=' skips the row we
										# already hold, and still lets a genuinely newer peer value land.
										my $time_check = $r->{'subsetting'} ? &subs::db_query('select app,setting,value from settings where app=? and setting=? and subsetting = ? and server_time >= ?',
												$r->{'app'}, $r->{'setting'}, $r->{'subsetting'}, $r->{'server_time'})->hashes :
											&subs::db_query('select app,setting,value from settings where app=? and setting=? and server_time >= ?',
												$r->{'app'}, $r->{'setting'}, $r->{'server_time'})->hashes;
										if (scalar @{$time_check} == 0) {
											eval {
												&subs::setting_setter({
													app => $r->{'app'},
													setting => $r->{'setting'},
													value => $r->{'value'},
													server_time => $r->{'server_time'},
													uuid => &subs::random_string_creator(20),
													device => $device,
													subsetting => $r->{'subsetting'},
													sync => 1
												});
											};
										}
										# Do not reload the app's whole settings map for every row: a
										# pull carries hundreds of changed settings, and each reload
										# copies every value of that app (some are multi-megabyte
										# blobs). One load per app is enough to answer `unique`.
										next;
									}
								#	&subs::setting_setter($r);
									next;
								}
								if ($q eq 'security') {
									if ($r->{'level'} == 1) {
										my $sec_uuid = &subs::db_select('security', ['uuid'], { level => 1 })->hash->{uuid};
										$r->{'level'} = 2 unless $sec_uuid eq $r->{'uuid'};
									}
								}

								if ($r->{'app'} && ($r->{'measures'} || $h->{'measures'})) {
									my $r_measures = eval { return decode_json $r->{'measures'} } || [];
									my $h_measures = eval { return decode_json $h->{'measures'} } || [];
									my $change = 0;
									foreach my $h_m ( @{$h_measures} ) {
										my @r_m = grep { $_->{'uuid'} eq $h_m->{'uuid'} } @{$r_measures};
										my $r_m = $r_m[0];
										$r_m->{'timestamp'} = $r_m->{'timestamp'} || $r_m->{'ts'} || $r_m->{'server_time'};
										if (scalar @r_m == 0) {
											push @{$r_measures}, $h_m;
											$change = 1;
										}
										elsif ($h_m->{'timestamp'} > $r_m->{'timestamp'}) {
											@{$r_measures} = grep { $_->{'uuid'} ne $h_m->{'uuid'} } @{$r_measures};
											push @{$r_measures}, $h_m;
											$change = 1;
										}
										$r->{'measures'} = encode_json $r_measures if $change == 1;
									}
								}

								if ($configuration->{'remote'}->{'manager'} && $r->{'app'} && ($r->{'file'} || $h->{'file'}) && $r->{'type'} ne 'snapshot' && $r->{'type'} ne 'backup' && $r->{'account'} ne 'gallery') {
									my $files = eval { return decode_json $r->{'file'} } || [];
									my $h_files = eval { return decode_json $h->{'file'} } || [];
									if (eval { $files->{'f'} }) { $files = [ $files ]; }
									if (eval { $h_files->{'f'} }) { $h_files = [ $h_files ]; }
									if ($q eq 'appointments') {
										$universal_settings->{$r->{'app'}}->{'enc'} = &subs::setting_grabber({ app => $r->{'app'}, device => $device, benign => 1 }) unless $universal_settings->{$r->{'app'}}->{'enc'};
										if ($universal_settings->{$r->{'app'}}->{'enc'} eq 'on' && !$r->{'encryption_standard'} && $r->{'server_time'} > &subs::ago_calc('10m', &subs::rightNow()) && scalar @{$files} > 0) {
											next;
										}
									}

									if (scalar @resulters > 0) {
										foreach my $home_file ( @{$h_files} ) {
											if ($home_file->{'server_time'} <= $r->{'server_time'} ) {
												unless ( grep { $home_file->{'uuid'} eq $_->{'uuid'} } @{$files}) {
												#	&delete_file({ app => $h->{'app'}, app_uuid => $h->{'uuid'}, file_uuid => $home_file->{'uuid'} });
													push @{$files}, $home_file;
													$r->{'server_time'} = &subs::rightNow();
												}
											}
											else {
												unless ( grep { $home_file->{'uuid'} eq $_->{'uuid'} } @{$files}) {
													push @{$files}, $home_file;
												}
											}
										}
									}
									if ($q eq 'appointments' && $tombstone_file{$r->{'uuid'}}) {
										my $strip = $tombstone_file{$r->{'uuid'}};
										my $before = scalar @{$files};
										@{$files} = grep { !$strip->{ $_->{'uuid'} } } @{$files};
										next ROW if $before > scalar @{$files} && scalar @{$files} == 0;
									}
									my $file_count = 0;
									foreach my $fi ( @{$files} ) {
										$file_count++;
										foreach my $file_type ( qw/f thumb/ ) {
											next unless $fi->{$file_type};
											my $file = $fi->{$file_type};
											$last_percent = $percentage;
											# A row stream (the v3 pull) has no snapshot size to divide
											# by: `$results_size` is 0 there, and the file-carry progress
											# is display-only. Guard both divisors so a pulled row with an
											# attachment cannot kill the merge.
											$percentage = sprintf("%.2f", ($n + ($file_count / scalar @{$files})) / ($results_size || 1) * 100);


											if ($percentage >= $last_percent && $results_size > 0 && &subs::rightNow() >= ($last_alert + 250)) {
												my $speed = abs sprintf("%.2f", $n / ((($start_time - &subs::rightNow()) || 1)) * 1000);
												my $remaining = $percentage ? &subs::duration_sayer(((&subs::rightNow() - $start_time) / $percentage) * (100 - $percentage) / 1000) : 'unknown';
												my $html = '<b style="font-size:20px">' . sprintf("%.2f", ($n + ($file_count / scalar @{$files}))) . ' / ' . $results_size . ' ' . &subs::format_name($q) . ' ' . $percentage . '% @ ' . $speed . '/sec ' . $remaining .'</b><br>' .
													'<progress style="width:70%;height:60px;" value="' . $n . '" max="' . $results_size . '"></progress>';
												$last_percent = $percentage;
												$last_alert = &subs::rightNow();
												&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
											}
											my ($destination,$asset,$type) = &subs::file_device_renamer({ file => $file, app => $r->{'app'}, misc_settings => $misc_settings, type => $fi->{'type'} });
											$fi->{'type'} = $type unless $fi->{'type'};
											my $dest = $destination . $asset;

											if (my @h_fil = grep { $_->{'uuid'} eq $fi->{'uuid'} } @{$h_files} ) {
												my $h_file = $h_fil[0];

												my ($hdestination,$hasset) = &subs::file_device_renamer({ file => $h_file->{$file_type}, app => $h->{'app'}, misc_settings => $misc_settings, type => $h_file->{'type'} });
												unless ($asset eq $hasset) {
													if (-e $destination . $hasset) {
														my $hassethoff = $destination . $hasset;
														`shred -u $hassethoff`;
													}
												}
											}

											unless (-e $dest) {
												`mkdir -p $destination`;
												$destination = $destination . $asset;
												if ($configuration->{'remote'}) {
													#$file = url_unescape $file;
													my $url = $configuration->{'remote'}->{'manager'} . '/file_open?timestamp=' . $r->{'server_time'} . '&as_is=yes&file=' . $file;
													my $file_data = $configuration->{'remote'}->{'ua'}->get($url)->result;
													if ($file_data) {
														unless ($file_data->body eq 'not found') {
															my $fd = $file_data->body;
															$fd = decode_base64 $fd;
															write_file($dest,$fd);
														}
													}
												}
											}
											$file = $dest;
											$fi->{$file_type} = $file;
										}
									}
									$r->{'file'} = encode_json $files;
								}
								unless ( grep { ($_->{'uuid'} eq $r->{'uuid'} ) && $_->{'table'} eq $q && ($_->{'scope'} || '') ne 'file' } @{$deletions} ) {
									if (scalar @resulters == 0) {
										my $inserted = eval { &subs::db_insert($q,$r)};
										if ($@) { push @insert_errors, ($r->{'uuid'} || '?') . ': ' . ($@ =~ s/\s+/ /gr); }
										elsif ($inserted) { $rows_inserted++; }
										else { push @insert_errors, ($r->{'uuid'} || '?') . ': refused'; }
									}
									else {
										$rows_updated++ if $h->{'server_time'} < $r->{'server_time'};
										eval { &subs::db_update($q,$r, { uuid => $r->{'uuid'} } ) } unless $h->{'server_time'} >= $r->{'server_time'};
									}
									if ($q eq 'appointments' && (!$h->{'server_time'} || $r->{'server_time'} > $h->{'server_time'})) {
										push @{$updateables}, { app => $r->{'app'}, uuid => $r->{'uuid'} } unless grep { $_->{'app'} eq $r->{'app'} } @{$updateables};
									}
								}
							}
		}
	};
	for (my $n = 0; !$results_size || $n < $results_size; $n++) {
		my $r = $next_row->();
		last unless $r;
		$rows_read++;
		$merge_one->($r, $n);
	}
						my $short = ($results_size && $rows_read < $results_size) ? ' SHORT' : '';
						# An insert that failed is not a merged table, for the same reason a
						# short read is not: claiming success stores the peer's picture in
						# `sync_seen` and the missing rows are never asked for again. Report
						# both, and let the pull retry.
						my $merge_errors = scalar @insert_errors;
						$merge_short = 1 if $short || $merge_errors;
						my $errors = $merge_errors ? ' errors=' . join(' | ', @insert_errors[0 .. ($#insert_errors > 2 ? 2 : $#insert_errors)]) : '';
						my $skew = scalar keys %skewed_columns ? ' skipped-columns=' . join(',', sort keys %skewed_columns) : '';
						&subs::log_writer('merge ' . $q . ': snapshot=' . $results_size . ' read=' . $rows_read . ' inserted=' . $rows_inserted . ' updated=' . $rows_updated . $short . $errors . $skew);
						if ($sync_job) {
							&subs::sync_job_step($sync_job, 'merge:' . $q, { state => ($short || $merge_errors) ? 'failed' : 'done', current => ($results_size || $rows_read), total => ($results_size || $rows_read), note => $short ? 'read ' . $rows_read . ' of ' . $results_size : ($merge_errors ? $merge_errors . ' row errors' : '') });
						}
	return $merge_short;
}

# The post-merge work shared by the snapshot path and the row-stream path: refresh
# the header/budget for appointments that moved, apply the deletions that came with
# the pull, and drop the relational caches an app's settings invalidate.
sub merge_finish {
	my ($ctx) = @_;
	my $configuration = $ctx->{'configuration'} || {};
	my $updateables = $ctx->{'updateables'} || [];
	my $auuid = $ctx->{'auuid'};
	my $colour = $ctx->{'colour'};
	my $percentage = 0;
	my $last_percent = 0;
	my $last_alert = &subs::rightNow();
	my $start_time = $last_alert;
	my $results_size = scalar @{$updateables};
	for (my $n = 0; $n < $results_size; $n++) {
		my $u = $updateables->[$n];
		next unless ref $u eq 'HASH' && $u->{'app'};
		&budget_runner($u->{'app'});
		&subs::appt_header_printer({ app => $u->{'app'}, timestamp => &subs::rightNow() });
		&Websocket::send('tab', { console => 'appointmentDetailGrabber(\'' . $u->{'app'} . '\',\'' . $u->{'uuid'} .'\');' });
		$percentage = sprintf("%.2f", $n / $results_size * 100);
		$percentage = .0000001 if $percentage == 0;
		if ($percentage >= $last_percent && $results_size > 1 && &subs::rightNow() >= ($last_alert + 250)) {
			my $speed = abs sprintf("%.2f", $n / ($start_time - &subs::rightNow()) * 1000);
			my $remaining = &subs::duration_sayer(((&subs::rightNow() - $start_time) / $percentage) * (100 - $percentage) / 1000);
			my $html = '<b style="font-size:20px">' . $n . ' / ' . $results_size . ' ' . &subs::format_name('informations') . ' ' . $percentage . '% @ ' . $speed . '/sec ' . $remaining . '</b><br>' .
				'<progress style="width:70%;height:60px;" value="' . $n . '" max="' . $results_size . '"></progress>';
			$last_percent = $percentage;
			$last_alert = &subs::rightNow();
			&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
		}
	}
	&deletion_performer($configuration->{'remote'}->{'deletions'}) if $configuration->{'remote'};
}

# Merge an encrypted snapshot: the full-migration / deep-gimme / v2 path. A normal
# v3 delta never gets here - `sync_rows_pull` feeds the same merge_table_rows and
# merge_finish directly from the row batches.
sub merge_database($c,$configuration) {
	&update_database($c);
	my $filename = $configuration->{'file'};
	my $remote_misc_settings = $configuration->{'misc_settings'};
	my $misc_settings = &misc_setting_list();
	my $device = &subs::device_setter();
	my $deletions = eval { return decode_json $configuration->{'remote'}->{'deletions'} } || [];

	my $rdel = &subs::db_select('remote_machines', [ 'deletions' ], {})->hashes;
	foreach my $rd ( @{$rdel} ) {
		my $all_deletions = eval { return decode_json $rd->{'deletions'} } || [];
		push @{$deletions}, @{$all_deletions};
	}


	my $port = $config->{'ssh_port'};
	my $auuid = &subs::random_string_creator(10);
	my $colour = $configuration->{'colour'};
	my $html = '<h3>Starting Merge ' . $filename . '</h3>';
	&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
	my ($db,$database) = &subs::database_grabber();
	my $disposition->{'status'} = 'fail';
	# A table the cursor could not finish is not a merge. `remote_upgrade` writes
	# the peer's picture into `sync_seen` after a successful merge, so reporting
	# succeed after a short read made a partial pull look like a full
	# reconciliation - the next tick then skipped the table and the rows stayed
	# missing. Keep the disposition honest so the pull retries.
	my $merge_short = 0;
	my $path = $filename;
	my $download_location = &subs::home('~/.president');
	my $temp_folder = &subs::home($download_location . '/' . &subs::random_string_creator(10));
	`mkdir -p $temp_folder` unless -e "$temp_folder";
	my $temporary_file = $temp_folder . '/tmpman.db';
	my $credentials = &subs::db_query('select level,credential from security where level != ? order by server_time DESC', 'padlock');
	my $creds = $credentials->hashes;
	my $signatorial = &subs::signatorial_designer();
	my $last_update_time = &subs::db_select('backups', undef, { recipient => $signatorial, signatorial => $configuration->{'signatorial'} })->hashes->[-1];
	$last_update_time = $last_update_time->{'server_time'} || 0;
	$last_update_time = $configuration->{'gimme'} if $configuration->{'gimme'};
	@{$creds} = grep { $_->{'level'} ne 'padlock' } @{$creds};
	@{$creds} = reverse @{$creds};
	my $encryption_standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard' } ) || "aes-256-ctr";
	my @updateables;
	my $suds = &subs::session_suds($c) || &subs::suds_grabber();
	my $merge_ctx;
	foreach my $cred ( @{$creds} ) {
		my $crud = &subs::decrypter($suds,$cred->{'credential'});
		my $html = '<h3>Testing Keys</h3>';

		&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
		if ($path =~ /enc$/gi) {
			my $data = `tail $path`;

			my @split_data = split $universal_splitter, $data;

			unless ($data =~ /\Q$universal_splitter/gi) {
				# The marker is appended after the ciphertext. If it is not in the tail,
				# the file we downloaded is not the finished container (truncated, or
				# not the archive at all) - say so instead of silently skipping the key.
				$log->error('merge container: standard marker missing; tail=' . length($data) . ' bytes') if $log;
				next;
			}

			$encryption_standard = &subs::decrypter($crud, $split_data[1]);
			&subs::openssl_file_crypt('d', $encryption_standard, $crud, $path, $temporary_file, 1, 1);

			my $tsql = Mojo::SQLite->new('sqlite:' . $temporary_file);
			my $decrypted_size = (-s $temporary_file) || 0;
			my $snapshot_db = eval { $tsql->db ? 1 : 0 };
			my $snapshot_ok = ($decrypted_size > 5000 && $snapshot_db && $tsql->dsn !~ /:$/) ? 1 : 0;
			# A merged table leaves a "merge <table>" line; a pull that never gets
			# there has failed at the container itself, and used to leave only "merge
			# did not finish" with no reason. Say which credential opened what.
			$log->error('merge snapshot: level=' . ($cred->{'level'} || '?') . ' archive=' . ((-s $path) || 0)
				. ' decrypted=' . $decrypted_size . ' db=' . ($snapshot_db ? 1 : 0) . ' dsn=' . $tsql->dsn) if $log && !$snapshot_ok;
			if ($snapshot_ok) {
				my $tdb = $tsql->db;

				my $backups = &subs::db_query('select * from backups order by server_time DESC' )->hashes;

				my $start_server_time = 0;
				if ( scalar @{$backups} > 1 ) {
					$start_server_time = $backups->[1]->{'server_time'};
				}

				my $html = '<h3>Now merging</h3>';
				&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
				$disposition->{'temporary_file'} = $temporary_file;
				my $stats = [];
				my $tables = `sqlite3 $temporary_file .tables`;

				my @u = sort split ' ', $tables;

				my $count = 0;
				my $universal_settings = {};
				my $sync_job = $configuration->{'sync_job'};
				&subs::sync_job_update($sync_job, { phase => 'merge', current => 0, total => scalar @u }) if $sync_job;
				$merge_ctx = {
					configuration => $configuration,
					misc_settings => $misc_settings,
					device => $device,
					deletions => $deletions,
					universal_settings => $universal_settings,
					updateables => \@updateables,
					sync_job => $sync_job,
					auuid => $auuid,
					colour => $colour,
				};
				foreach my $q ( @u ) {
					next if grep { $q eq $_ } @{$gb::forbidden->{'tables'}};
					# Count first, then read the snapshot's rows in bounded batches. A
					# full convergence carries a whole table (110k appointments), so
					# ->hashes on everything would hold it all in memory on top of the
					# merge; the batch reader below keeps one page at a time.
					my $results_size = ($tdb->query('select count(*) as c from ' . $q)->hash->{'c'} || 0) + 0;
					if ($results_size > 0) {
						$count++;
						&subs::sync_job_update($sync_job, { current => $count }) if $sync_job;
						my @merge_batch;
						my $merge_rowid = 0;
						my $merge_all;
						my $next_row = sub {
							unless (scalar @merge_batch) {
								return undef if $merge_all;
								my $rows = eval { $tdb->query('select rowid as __merge_rowid, * from ' . $q . ' where rowid > ? order by rowid limit 500', $merge_rowid)->hashes };
								if (!$rows) {
									# a table without a rowid (a view) is read whole, once
									$merge_all = 1;
									$rows = $tdb->query('select * from ' . $q)->hashes;
								}
								@merge_batch = @{$rows || []};
								return undef unless scalar @merge_batch;
							}
							my $row = shift @merge_batch;
							$merge_rowid = delete $row->{'__merge_rowid'} if exists $row->{'__merge_rowid'};
							return $row;
						};
						my $short = &merge_table_rows($merge_ctx, $q, $next_row, $results_size, $count, scalar @u);
						$merge_short = 1 if $short;
					}
					$disposition->{'disposition'} = $database;
					$disposition->{'status'} = $merge_short ? 'failed' : 'succeed';
					my $known_backup = &subs::db_select('backups', undef, { uuid => $backups->[0]->{'uuid'} })->hashes;
					if ($known_backup->[0]->{'reason'} =~ /remote/gi) {
						my $defunct_backups = &subs::db_query('delete from backups where recipient=? and signatorial=? and destination=? and server_time < ? and uuid != ?',
							$backups->[0]->{'recipient'}, $backups->[0]->{'signatorial'}, $backups->[0]->{'destination'}, $backups->[0]->{'server_time'}, $backups->[0]->{'uuid'});
						$disposition->{'backup_uuid'} = $backups->[0]->{'uuid'};
					}
				}
				last;
			}
		}
	}
	&merge_finish($merge_ctx) if $merge_ctx;
	&Websocket::send('tab', { yellow => 'close', 'close' => 'yes', uuid => $auuid, colour => $colour });
	&subs::say_it('fail') unless $disposition->{'status'} eq 'succeed';
	`shred -u $temporary_file` if -e $temporary_file;
	`shred -u $temporary_file-shm` if -e $temporary_file;
	`shred -u $temporary_file-wal` if -e $temporary_file;
	`rm -R $temp_folder`;
	return $disposition;
}



# --- Bank statement import and reconciliation ------------------------------
# A statement is read into dated, signed lines, matched against the money the
# ledger already holds for one account, and shown as a screen where a person
# settles the rest. Reconciling writes the statement's ending balance as an
# inventory anchor, which is the number the Budget balance is measured from.
sub bank_date_ms {
	my ($d,$order) = @_;
	return undef unless defined $d && length $d;
	$d =~ s/^\s+|\s+$//g;
	$d =~ s/[\x{2018}\x{2019}']/\//g;   # a QIF year separator (10/14'26)
	$d =~ s/[T ].*$//;                   # drop a time part
	$d =~ s/\..*$//;
	my ($y,$m,$day);
	if ($d =~ /^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/) { ($y,$m,$day) = ($1,$2,$3); }
	elsif ($d =~ /^(\d{4})(\d{2})(\d{2})/) { ($y,$m,$day) = ($1,$2,$3); }
	elsif ($d =~ /^(\d{1,2})[\-\/., ]*([A-Za-z]{3,})[\-\/., ]*(\d{2,4})/) {
		# a bank that spells the month out (Libro writes 19Oct2026)
		my %month = ( jan=>1, feb=>2, mar=>3, apr=>4, may=>5, jun=>6, jul=>7, aug=>8, sep=>9, oct=>10, nov=>11, dec=>12 );
		my $mm = $month{ lc substr($2,0,3) };
		return undef unless $mm;
		($day,$m) = ($1,$mm);
		my $yy = $3;
		$y = $yy < 100 ? ($yy < 70 ? 2000 + $yy : 1900 + $yy) : $yy;
	}
	elsif ($d =~ /^([A-Za-z]{3,})[\-\/., ]*(\d{1,2})[\-\/., ]*(\d{2,4})/) {
		my %month = ( jan=>1, feb=>2, mar=>3, apr=>4, may=>5, jun=>6, jul=>7, aug=>8, sep=>9, oct=>10, nov=>11, dec=>12 );
		my $mm = $month{ lc substr($1,0,3) };
		return undef unless $mm;
		($m,$day) = ($mm,$2);
		my $yy = $3;
		$y = $yy < 100 ? ($yy < 70 ? 2000 + $yy : 1900 + $yy) : $yy;
	}
	elsif ($d =~ /^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})/) {
		my ($a,$b,$yy) = ($1,$2,$3);
		if (($order || 'mdy') eq 'dmy') { ($day,$m) = ($a,$b); } else { ($m,$day) = ($a,$b); }
		$y = $yy < 100 ? ($yy < 70 ? 2000 + $yy : 1900 + $yy) : $yy;
	}
	else { return undef; }
	return undef unless $m >= 1 && $m <= 12 && $day >= 1 && $day <= 31 && $y >= 1900 && $y <= 2200;
	my $ms = eval { timelocal(0,0,12,$day,$m-1,$y) };
	return undef unless defined $ms;
	return $ms * 1000;
}

sub bank_amount_value {
	my $v = shift;
	return undef unless defined $v;
	$v =~ s/[^\d.,()\-+]//g;
	return undef unless $v =~ /\d/;
	my $neg = ($v =~ /^\s*\(/ || $v =~ /-\s*$/ || $v =~ /^-/) ? 1 : 0;
	$v =~ s/[()+\s]//g;
	$v =~ s/-//g;
	# a decimal comma (1.234,56 or 12,34) versus a thousands comma
	if ($v =~ /,(\d{1,2})$/) { $v =~ s/\.//g; $v =~ s/,/./; }
	else { $v =~ s/,//g; }
	return undef unless $v =~ /^\d+(?:\.\d+)?$/;
	$v = $neg ? -$v : $v;
	return $v + 0;
}

sub bank_csv_rows {
	my $text = shift;
	$text =~ s/\r\n/\n/g;
	$text =~ s/\r/\n/g;
	my @rows;
	foreach my $line ( split /\n/, $text ) {
		next unless length $line;
		my $commas = () = $line =~ /,/g;
		my $semis = () = $line =~ /;/g;
		my $tabs = () = $line =~ /\t/g;
		my $d = ',';
		$d = ';' if $semis > $commas && $semis >= $tabs;
		$d = "\t" if $tabs > $commas && $tabs > $semis;
		my @fields;
		my $field = '';
		my $quoted = 0;
		my @ch = split //, $line;
		for (my $i = 0; $i <= $#ch; $i++) {
			my $ch = $ch[$i];
			if ($quoted) {
				if ($ch eq '"') {
					if ($i < $#ch && $ch[$i+1] eq '"') { $field .= '"'; $i++; }
					else { $quoted = 0; }
				}
				else { $field .= $ch; }
			}
			elsif ($ch eq '"') { $quoted = 1; }
			elsif ($ch eq $d) { push @fields, $field; $field = ''; }
			else { $field .= $ch; }
		}
		push @fields, $field;
		push @rows, \@fields;
	}
	return \@rows;
}

sub bank_csv_column_map {
	my $header = shift;
	my %map;
	for (my $i = 0; $i < scalar @{$header}; $i++) {
		my $h = lc($header->[$i] // '');
		$h =~ s/^\s+|\s+$//g;
		$map{'date'} = $i if !defined $map{'date'} && $h =~ /date/;
		$map{'description'} = $i if !defined $map{'description'} && $h =~ /desc|payee|memo|detail|narrative|name/;
		$map{'debit'} = $i if !defined $map{'debit'} && $h =~ /debit|withdraw|money out|paid out/;
		$map{'credit'} = $i if !defined $map{'credit'} && $h =~ /credit|deposit|money in|paid in/;
		$map{'amount'} = $i if !defined $map{'amount'} && $h =~ /amount|value/;
		$map{'balance'} = $i if !defined $map{'balance'} && $h =~ /balance/;
	}
	return \%map;
}

sub bank_statement_parse_csv {
	my ($text,$date_order) = @_;
	my $rows = &bank_csv_rows($text);
	my $lines = [];
	my $file_balance;
	my @balances;
	my $start = 0;
	my $map;
	# a bank export often opens with a name or an account number before the
	# column headings, so look a few rows in for a heading this can read
	for (my $r = 0; $r < scalar @{$rows} && $r < 10; $r++) {
		my $candidate = &bank_csv_column_map($rows->[$r]);
		if (defined $candidate->{'date'} && (defined $candidate->{'amount'} || defined $candidate->{'debit'} || defined $candidate->{'credit'})) {
			$map = $candidate;
			$start = $r + 1;
			last;
		}
	}
	unless ($map) {
		my $width = 0;
		for (my $r = 0; $r < scalar @{$rows} && $r < 10; $r++) {
			$width = scalar @{$rows->[$r]} if scalar @{$rows->[$r]} > $width;
		}
		$map = $width >= 4 ? { date => 0, description => 1, debit => 2, credit => 3 } : { date => 0, description => 1, amount => 2 };
	}
	for (my $r = $start; $r < scalar @{$rows}; $r++) {
		my $row = $rows->[$r];
		my $ts = &bank_date_ms($row->[$map->{'date'}], $date_order);
		next unless defined $ts;
		my $amount;
		if (defined $map->{'amount'} && defined $row->[$map->{'amount'}]) {
			$amount = &bank_amount_value($row->[$map->{'amount'}]);
		}
		else {
			my $debit = defined $map->{'debit'} ? &bank_amount_value($row->[$map->{'debit'}]) : undef;
			my $credit = defined $map->{'credit'} ? &bank_amount_value($row->[$map->{'credit'}]) : undef;
			$amount = defined $debit ? -abs($debit) : (defined $credit ? abs($credit) : undef);
		}
		next unless defined $amount;
		next if $amount == 0;
		my $description = defined $map->{'description'} ? ($row->[$map->{'description'}] // '') : '';
		$description =~ s/^\s+|\s+$//g;
		unless (length $description) {
			$description = join ' ', grep { defined && length && $_ !~ /^[\s\d.,$()\-+]+$/ } @{$row};
		}
		if (defined $map->{'balance'}) {
			my $b = &bank_amount_value($row->[$map->{'balance'}]);
			push @balances, [ $ts, $b, $amount ] if defined $b;
		}
		push @{$lines}, { timestamp => $ts, amount => $amount, description => $description };
	}
	# The balance column runs after each row's transaction, so the closing
	# balance is the one at the newest end of a file we do not know the
	# direction of. The running balance itself says which end that is: on a
	# newest-first file row i's balance equals the next row's plus row i's
	# amount, and the other way round on an oldest-first file.
	if (scalar @balances == 1) {
		$file_balance = $balances[0]->[1];
	}
	elsif (scalar @balances > 1) {
		my ($down,$up) = (0,0);
		for (my $i = 0; $i < $#balances; $i++) {
			my ($b0,$b1) = ($balances[$i]->[1], $balances[$i+1]->[1]);
			my ($a0,$a1) = ($balances[$i]->[2], $balances[$i+1]->[2]);
			$down++ if abs($b0 - ($b1 + $a0)) < 0.005;
			$up++ if abs($b1 - ($b0 + $a1)) < 0.005;
		}
		$file_balance = ($up > $down) ? $balances[-1]->[1] : $balances[0]->[1];
	}
	@{$lines} = sort { $a->{'timestamp'} <=> $b->{'timestamp'} } @{$lines};
	return ($lines, $file_balance, undef, undef);
}

sub bank_statement_parse_qif {
	my ($text,$date_order) = @_;
	my $lines = [];
	my %cur;
	foreach my $l ( split /\n/, $text ) {
		$l =~ s/\r$//;
		if ($l =~ /^\^/) {
			my $ts = &bank_date_ms($cur{'date'}, $date_order);
			my $amount = &bank_amount_value($cur{'amount'});
			if (defined $ts && defined $amount && $amount != 0) {
				my $description = join ' ', grep { defined && length } ($cur{'payee'}, $cur{'memo'});
				push @{$lines}, { timestamp => $ts, amount => $amount, description => $description };
			}
			%cur = ();
			next;
		}
		my ($k,$v) = ($l =~ /^(.)(.*)$/s);
		next unless $k;
		if ($k eq 'D') { $cur{'date'} = $v; }
		elsif ($k eq 'T' || $k eq 'U') { $cur{'amount'} = $v if !defined $cur{'amount'} || $k eq 'T'; }
		elsif ($k eq 'P') { $cur{'payee'} = $v; }
		elsif ($k eq 'M') { $cur{'memo'} = $v; }
	}
	@{$lines} = sort { $a->{'timestamp'} <=> $b->{'timestamp'} } @{$lines};
	my $error = scalar @{$lines} ? undef : 'No QIF transactions were found.';
	return ($lines, undef, $error, undef);
}

sub bank_statement_parse_ofx {
	my ($text,$date_order) = @_;
	my $lines = [];
	while ($text =~ m{<STMTTRN>(.*?)(?:</STMTTRN>|(?=<STMTTRN>)|$)}gis) {
		my $body = $1;
		my ($d) = $body =~ m{<DTPOSTED>\s*([0-9]+)}i;
		my ($a) = $body =~ m{<TRNAMT>\s*([-0-9.,]+)}i;
		my ($n) = $body =~ m{<NAME>\s*([^<\r\n]*)}i;
		my ($m) = $body =~ m{<MEMO>\s*([^<\r\n]*)}i;
		my $ts = &bank_date_ms($d, $date_order);
		my $amount = &bank_amount_value($a);
		next unless defined $ts && defined $amount && $amount != 0;
		my $description = join ' ', grep { defined && length } ($n, $m);
		push @{$lines}, { timestamp => $ts, amount => $amount, description => $description };
	}
	my ($file_balance);
	if ($text =~ m{<LEDGERBAL>(.*?)(?:</LEDGERBAL>|$)}is) {
		my $block = $1;
		my ($bal) = $block =~ m{<BALAMT>\s*([-0-9.,]+)}i;
		$file_balance = &bank_amount_value($bal);
	}
	# the closing balance is as of the statement's end, which the bank states
	# itself; the last transaction often sits a day or two earlier
	my $statement_end;
	if ($text =~ m{<LEDGERBAL>.*?<DTASOF>\s*([0-9]{8,14})}is) {
		$statement_end = &bank_date_ms($1, $date_order);
	}
	if (!defined $statement_end && $text =~ m{<DTEND>\s*([0-9]{8,14})}i) {
		$statement_end = &bank_date_ms($1, $date_order);
	}
	@{$lines} = sort { $a->{'timestamp'} <=> $b->{'timestamp'} } @{$lines};
	my $error = scalar @{$lines} ? undef : 'No OFX transactions were found.';
	return ($lines, $file_balance, $error, $statement_end);
}

sub bank_statement_parse {
	my ($filename,$text,$date_order) = @_;
	my $ext = lc($filename // '');
	$ext =~ s/.*\.//;
	return &bank_statement_parse_qif($text,$date_order) if $ext eq 'qif' || $text =~ /^!Type:/im;
	return &bank_statement_parse_ofx($text,$date_order) if $ext eq 'ofx' || $ext eq 'qfx' || $ext eq 'qbo' || $text =~ /<OFX>/i;
	return &bank_statement_parse_csv($text,$date_order);
}

# The money the ledger already holds for the account at the statement's end:
# its last inventory anchor plus every transaction after it. Purchase rows are
# breakdowns, not moves, so only type='transaction' is read.
sub bank_ledger_balance {
	my ($account,$end) = @_;
	my $anchor = &subs::db_query("select amount, timestamp from appointments where account=? and movement='inventory' and type='transaction' and cast(timestamp as integer) <= cast(? as integer) order by cast(timestamp as integer) desc limit 1", $account, $end)->hashes->[0];
	my $balance = $anchor ? ($anchor->{'amount'} || 0) + 0 : 0;
	my $since = $anchor ? ($anchor->{'timestamp'} || 0) + 0 : 0;
	my $sum = &subs::db_query("select coalesce(sum(cast(total as real)),0) as s from warehouse where kind='money' and type='transaction' and movement != 'inventory' and account=? and cast(timestamp as integer) >= cast(? as integer) and cast(timestamp as integer) <= cast(? as integer)", $account, $since, $end)->hashes->[0];
	$balance += ($sum->{'s'} || 0) + 0;
	return $balance;
}

# Pair each bank line with at most one ledger row of the same amount within three
# days; the closest date wins. A line the ledger only partly holds - an e-transfer
# whose service charge was recorded on its own, as Libro writes it - is then
# settled from the few rows that make it up, and the screen records only the
# remainder. Rows left over are the money in Budget that the statement does not
# show.
sub bank_reconcile_match {
	my ($lines,$candidates) = @_;
	my $used = {};
	my $near = sub {
		my $line = shift;
		return grep {
			!$used->{$_->{'uuid'}}
			&& abs((($_->{'timestamp'} || 0) + 0) - $line->{'timestamp'}) <= 3 * 86400000
		} @{$candidates};
	};
	foreach my $line ( sort { $a->{'timestamp'} <=> $b->{'timestamp'} } @{$lines} ) {
		my @near = grep { abs((($_->{'total'} || 0) + 0) - $line->{'amount'}) < 0.005 } &{$near}($line);
		next unless scalar @near;
		@near = sort { abs((($a->{'timestamp'} || 0) + 0) - $line->{'timestamp'}) <=> abs((($b->{'timestamp'} || 0) + 0) - $line->{'timestamp'}) } @near;
		my $match = $near[0];
		$used->{$match->{'uuid'}} = 1;
		$line->{'match'} = $match;
	}
	# a line made of more than one recorded move: take same-signed rows nearest
	# the line until it is covered; anything still short is what Record writes
	foreach my $line ( grep { !$_->{'match'} } sort { $a->{'timestamp'} <=> $b->{'timestamp'} } @{$lines} ) {
		my $sign = $line->{'amount'} < 0 ? -1 : 1;
		my $remaining = $line->{'amount'} + 0;
		my @parts;
		my @near = sort { abs((($a->{'timestamp'} || 0) + 0) - $line->{'timestamp'}) <=> abs((($b->{'timestamp'} || 0) + 0) - $line->{'timestamp'}) }
			grep {
				my $a = (($_->{'total'} || 0) + 0);
				$a != 0 && (($a < 0 ? -1 : 1) == $sign) && abs($a) <= abs($remaining) + 0.005
			} &{$near}($line);
		foreach my $candidate ( @near ) {
			my $a = (($candidate->{'total'} || 0) + 0);
			next if abs($a) > abs($remaining) + 0.005;
			push @parts, $candidate;
			$used->{$candidate->{'uuid'}} = 1;
			$remaining -= $a;
			last if abs($remaining) < 0.005;
		}
		next unless scalar @parts;
		$line->{'parts'} = \@parts;
		# a cent or two of rounding (Libro's $4.00 fee against a $3.99 row) is the
		# same move, not a remainder worth writing
		$line->{'settled'} = 1 if abs($remaining) <= 0.05;
		$line->{'record_amount'} = $line->{'settled'} ? 0 : $remaining;
	}
	my @outstanding = grep { !$used->{$_->{'uuid'}} } @{$candidates};
	return \@outstanding;
}

# The merchant memory: the app a description has consistently been filed under.
# It reads the old transactions' vendor (Libro writes 77 Vape Wyoming as
# 77_vape), then their item, then their app, and matches those words against a
# statement line. A suggestion is only a default - the line still waits to be
# confirmed.
sub bank_merchant_tokens {
	my $s = shift || '';
	$s = lc $s;
	$s =~ s/[^a-z0-9]+/ /g;
	return grep { length } split ' ', $s;
}

sub bank_merchant_memory {
	my $rows = &subs::db_query("select app, vendor, item, movement, count(*) as n from warehouse where kind='money' and type='transaction' and movement in ('income','expense') group by app, vendor, item, movement")->hashes || [];
	my @memory;
	my %stop = map { $_ => 1 } qw(cash account payment purchase transfer deposit withdrawal online pos card debit credit the and inc ltd of for at);
	foreach my $r ( @{$rows} ) {
		my $text = ($r->{'vendor'} && length $r->{'vendor'}) ? $r->{'vendor'}
			: (($r->{'item'} && length $r->{'item'}) ? $r->{'item'} : ($r->{'app'} || ''));
		my @tokens = grep { !$stop{$_} } &bank_merchant_tokens($text);
		next unless scalar @tokens;
		push @memory, {
			tokens => \@tokens, app => ($r->{'app'} || ''), vendor => ($r->{'vendor'} || ''),
			item => ($r->{'item'} || ''), movement => ($r->{'movement'} || ''), n => (($r->{'n'} || 0) + 0)
		};
	}
	return \@memory;
}

sub bank_merchant_lookup {
	my ($memory,$description,$movement) = @_;
	my %bank = map { $_ => 1 } &bank_merchant_tokens($description);
	return undef unless scalar keys %bank;
	my $best;
	foreach my $c ( @{$memory} ) {
		next unless (($c->{'movement'} || '') eq ($movement || ''));
		my $overlap = grep { $bank{$_} } @{$c->{'tokens'}};
		# a multi-word merchant needs more than one shared word: 'Service Fee'
		# must not become the passport office just because both say service
		my $need = scalar @{$c->{'tokens'}} >= 2 ? 2 : 1;
		next if $overlap < $need;
		my $score = $overlap / scalar @{$c->{'tokens'}};
		next if $score < 0.5;
		if (!$best || $score > $best->{'score'} + 0.0001 || (abs($score - $best->{'score'}) < 0.0001 && $c->{'n'} > $best->{'n'})) {
			$best = { %{$c}, score => $score };
		}
	}
	return $best;
}

# The pair of two legs of one transfer is the other side of the same move, so a
# missing leg is recorded as that transfer rather than as a new expense.
sub bank_reconcile_result {
	my ($account,$lines,$filename,$file_balance,$parse_error,$statement_end) = @_;
	my ($min,$max);
	foreach my $l ( @{$lines} ) {
		$min = $l->{'timestamp'} if !defined $min || $l->{'timestamp'} < $min;
		$max = $l->{'timestamp'} if !defined $max || $l->{'timestamp'} > $max;
	}
	my $start = defined $min ? $min : &subs::rightNow();
	my $end = defined $max ? $max : &subs::rightNow();
	# the statement's last day is the window's end, so a line stamped noon does
	# not push the end into the next morning and an anchor is written for the day
	# the closing balance belongs to
	if (defined $min) {
		my @s = localtime($min / 1000);
		my $midnight = eval { timelocal(0,0,0,$s[3],$s[4],$s[5]) };
		$start = $midnight * 1000 if defined $midnight;
	}
	if (defined $max) {
		my @e = localtime($max / 1000);
		my $night = eval { timelocal(59,59,23,$e[3],$e[4],$e[5]) };
		$end = $night * 1000 if defined $night;
	}
	# an OFX statement states the moment its closing balance belongs to; prefer
	# that over the last transaction's day (Libro closes two days after the last
	# transaction on the file)
	if (defined $statement_end) {
		my @e = localtime($statement_end / 1000);
		my $night = eval { timelocal(59,59,23,$e[3],$e[4],$e[5]) };
		$end = $night * 1000 if defined $night;
	}
	my $candidates = &subs::db_query("select * from warehouse where kind='money' and type='transaction' and account=? and movement != 'inventory' and cast(timestamp as integer) >= cast(? as integer) and cast(timestamp as integer) <= cast(? as integer) order by timestamp", $account, $start - 5 * 86400000, $end + 86400000)->hashes;
	my $outstanding = &bank_reconcile_match($lines, $candidates);
	my @inside = grep { (($_->{'timestamp'} || 0) + 0) >= $start && (($_->{'timestamp'} || 0) + 0) <= $end } @{$outstanding};
	my $anchor = &subs::db_query("select amount, timestamp from appointments where account=? and movement='inventory' and type='transaction' and cast(timestamp as integer) <= cast(? as integer) order by cast(timestamp as integer) desc limit 1", $account, $end)->hashes->[0];
	# money before the last inventory anchor is already in that one figure, not
	# itemised, so a statement line from that stretch cannot match and must not
	# be offered as something to record (that would write it twice)
	if ($anchor) {
		my $anchor_ts = ($anchor->{'timestamp'} || 0) + 0;
		foreach my $l ( @{$lines} ) {
			next if $l->{'match'} || $l->{'settled'};
			if (($l->{'timestamp'} + 0) <= $anchor_ts) {
				$l->{'covered'} = 1;
				$l->{'record_amount'} = 0;
			}
		}
	}
	# A transfer recorded on the other account alone (one leg of the pair was
	# lost) is the counterpart of this line: recording the line as a transfer
	# supplies the missing leg and leaves the other account's balance alone.
	my $counterparts = &subs::db_query("select * from warehouse where kind='money' and type='transaction' and movement='transfer' and account != ? and cast(timestamp as integer) >= cast(? as integer) and cast(timestamp as integer) <= cast(? as integer) order by timestamp", $account, $start - 3 * 86400000, $end + 3 * 86400000)->hashes;
	my %app_seen;
	my @app_choices;
	foreach my $l ( @{$lines} ) {
		next if $l->{'match'} || $l->{'settled'} || $l->{'covered'};
		my $amount = defined $l->{'record_amount'} ? $l->{'record_amount'} + 0 : $l->{'amount'} + 0;
		next if abs($amount) < 0.005;
		my @near = grep {
			abs((($_->{'total'} || 0) + 0) + $amount) < 0.005
			&& abs((($_->{'timestamp'} || 0) + 0) - $l->{'timestamp'}) <= 3 * 86400000
		} @{$counterparts};
		$l->{'counterpart'} = $near[0] if scalar @near;
		$l->{'movement'} = $l->{'counterpart'} ? 'transfer' : ($amount < 0 ? 'expense' : 'income');
		$l->{'app_default'} = $l->{'counterpart'} ? $l->{'counterpart'}->{'account'} : $account;
	}
	# a merchant the house has paid before supplies a default app; the line is
	# still shown with Record/Ignore so the person confirms it
	my $memory = &bank_merchant_memory();
	foreach my $l ( @{$lines} ) {
		next if $l->{'match'} || $l->{'settled'} || $l->{'covered'} || $l->{'counterpart'};
		my $suggestion = &bank_merchant_lookup($memory, $l->{'description'}, $l->{'movement'});
		next unless $suggestion;
		$l->{'suggested_app'} = $suggestion->{'app'};
		$l->{'suggested_vendor'} = $suggestion->{'vendor'};
		$l->{'suggested_item'} = $suggestion->{'item'};
		$l->{'suggested_count'} = $suggestion->{'n'};
		$l->{'app_default'} = $suggestion->{'app'} if $suggestion->{'app'} && length $suggestion->{'app'};
	}
	foreach my $choice ( $account, map { $_->{'account'} } @{$counterparts} ) {
		next unless defined $choice && length $choice && !$app_seen{$choice}++;
		push @app_choices, $choice;
	}
	foreach my $row ( @{ &subs::db_query("select app, count(*) as c from appointments where type in ('transaction','purchase') and app is not null and app != '' group by app order by c desc limit 150")->hashes || [] } ) {
		next if !defined $row->{'app'} || !length $row->{'app'} || $app_seen{$row->{'app'}}++;
		push @app_choices, $row->{'app'};
	}
	my ($matched_count,$unmatched_count,$covered_count,$matched_total,$unmatched_total,$covered_total) = (0,0,0,0,0,0);
	foreach my $l ( @{$lines} ) {
		if ($l->{'covered'}) { $covered_count++; $covered_total += $l->{'amount'}; }
		elsif ($l->{'match'} || $l->{'settled'}) { $matched_count++; $matched_total += $l->{'amount'}; }
		else { $unmatched_count++; $unmatched_total += $l->{'amount'}; }
	}
	my $outstanding_total = 0;
	$outstanding_total += (($_->{'total'} || 0) + 0) for @inside;
	my $ledger_balance = &bank_ledger_balance($account, $end);
	my $statement_balance = defined $file_balance ? $file_balance : '';
	my $delta;
	my $delta_defined = 0;
	if (defined $file_balance) { $delta = $file_balance - $ledger_balance; $delta_defined = 1; }
	my $settings = &subs::settings_grabber({ app => $account, benign => 1 });
	return {
		account => $account,
		filename => $filename,
		parse_error => $parse_error,
		lines => $lines,
		outstanding => \@inside,
		app_choices => \@app_choices,
		statement_end => $end,
		statement_start => $start,
		ledger_balance => $ledger_balance,
		statement_balance => $statement_balance,
		delta => $delta,
		delta_defined => $delta_defined,
		matched_count => $matched_count,
		unmatched_count => $unmatched_count,
		covered_count => $covered_count,
		matched_total => $matched_total,
		unmatched_total => $unmatched_total,
		covered_total => $covered_total,
		outstanding_total => $outstanding_total,
		last_inventory_amount => $anchor ? ($anchor->{'amount'} || 0) + 0 : undef,
		last_inventory_time => $anchor ? ($anchor->{'timestamp'} || 0) + 0 : undef,
		currency => $settings->{'currency'} || &subs::setting_grabber({ app => 'misc', setting => 'currency', benign => 1 }) || '[]'
	};
}

# Write the decisions of a reconciliation: each line left on Record becomes a
# transaction, then the statement's closing balance becomes the account's newest
# inventory anchor. Nothing is read back from the browser to decide this, so the
# same routine can run on a copy of the database in a test.
sub budget_reconcile_apply {
	my ($account,$statement_end,$ending,$lines) = @_;
	$lines = [] unless ref $lines eq 'ARRAY';
	my $currency = &subs::setting_grabber({ app => $account, setting => 'currency', benign => 1 });
	$currency = &subs::setting_grabber({ app => 'misc', setting => 'currency', benign => 1 }) unless defined $currency && length $currency;
	my $server_time = &subs::rightNow();
	my $recorded = 0;
	foreach my $line ( @{$lines} ) {
		next unless (($line->{'action'} || '') eq 'record');
		my $amount = (defined $line->{'record_amount'} && $line->{'record_amount'} ne '') ? &bank_amount_value($line->{'record_amount'}) : &bank_amount_value($line->{'amount'});
		next unless defined $amount && $amount != 0;
		my $movement = $line->{'movement'} || ($amount < 0 ? 'expense' : 'income');
		$movement = ($amount < 0 ? 'expense' : 'income') unless $movement eq 'expense' || $movement eq 'income' || $movement eq 'transfer';
		my $app = &subs::unformat_name($line->{'app'} || $account);
		$app = $account unless length $app;
		my $item = (defined $line->{'item'} && length $line->{'item'}) ? $line->{'item'} : ($line->{'description'} || 'imported');
		my $vendor = $line->{'vendor'} || '';
		my $uuid = &subs::random_string_creator(40);
		my $row = {
			app => $app,
			timestamp => $line->{'timestamp'},
			type => 'transaction',
			movement => $movement,
			account => $account,
			amount => $amount,
			total => $amount,
			item => &subs::unformat_name($item),
			vendor => &subs::unformat_name($vendor),
			uuid => $uuid,
			server_time => $server_time,
			currency => $currency
		};
		&subs::db_insert('appointments', $row);
		&subs::warehouse_money_mirror($row);
		$recorded++;
	}
	my $anchored = 0;
	my $balance = &bank_amount_value($ending);
	if (defined $balance && defined $statement_end && $statement_end =~ /[0-9]/) {
		# a statement that closes today ends at midnight tonight; the anchor is
		# written no later than now so it is the balance the panel reads at once
		my $anchor_time = $statement_end + 0;
		$anchor_time = $server_time if $anchor_time > $server_time;
		my $uuid = &subs::random_string_creator(40);
		my $row = {
			app => $account,
			timestamp => $anchor_time,
			type => 'transaction',
			movement => 'inventory',
			account => $account,
			amount => $balance,
			total => $balance,
			uuid => $uuid,
			server_time => $server_time,
			currency => $currency
		};
		&subs::db_insert('appointments', $row);
		# the warehouse keeps the anchor beside it, as the transaction form does
		&subs::db_insert('warehouse', {
			kind => 'inventory',
			type => 'transaction',
			movement => 'inventory',
			app => $account,
			account => $account,
			item => $account,
			quantity => $balance,
			amount => $balance,
			total => $balance,
			uuid => &subs::random_string_creator(40),
			app_uuid => $uuid,
			timestamp => $anchor_time,
			server_time => $server_time
		});
		$anchored = 1;
	}
	foreach my $circumstance ( keys %{$gb::budget_modes} ) {
		&subs::cache_delete({ app => $account, context => 'budget', subcontext => $circumstance });
	}
	&subs::cache_delete({ app => $account, context => 'template' });
	return { recorded => $recorded, anchored => $anchored, balance => &bank_ledger_balance($account, &subs::rightNow()) };
}

# --- Financial statements --------------------------------------------------
# The cash-basis statements read the same ledger the Budget view does: each
# account's money moves (type='transaction'), grouped by the app that carries
# the category. Nothing here writes.
sub accounting_moves {
	my ($accounts,$from,$to) = @_;
	my @rows;
	foreach my $a ( @{$accounts} ) {
		next unless defined $a && length $a;
		push @rows, @{ &subs::db_query("select * from warehouse where kind='money' and type='transaction' and movement != 'inventory' and account=? and cast(timestamp as integer) >= cast(? as integer) and cast(timestamp as integer) <= cast(? as integer) order by timestamp", $a, $from, $to)->hashes || [] };
	}
	return \@rows;
}

# Open invoices (not quotes) at a moment, with the balance and the age of each.
# There is no due date on an invoice, so the age is counted from the day it was
# written; the screen says so.
sub accounting_receivables {
	my $to = shift;
	my $returner = { rows => [], total => 0, count => 0, buckets => { current => 0, '31_60' => 0, '61_90' => 0, 'over_90' => 0 } };
	my $rows = &subs::db_query("select * from appointments where type='invoice' and cast(timestamp as integer) <= cast(? as integer) order by timestamp", $to)->hashes || [];
	foreach my $doc ( @{$rows} ) {
		my $data = eval { decode_json $doc->{'data'} } || {};
		my $numbers = $data->{'numbers'} || {};
		my $paid = 0;
		foreach my $p ( @{$data->{'payments'} || []} ) {
			$paid += (($p->{'amount'} || 0) + 0);
		}
		my $balance = defined $numbers->{'balance'} ? ($numbers->{'balance'} + 0) : (($numbers->{'total'} || 0) + 0) - $paid;
		next if $balance <= 0.005;
		my $issued = ($doc->{'timestamp'} || 0) + 0;
		my $age = int(($to - $issued) / 86400000);
		$age = 0 if $age < 0;
		my $bucket = $age <= 30 ? 'current' : $age <= 60 ? '31_60' : $age <= 90 ? '61_90' : 'over_90';
		$returner->{'total'} += $balance;
		$returner->{'buckets'}->{$bucket} += $balance;
		$returner->{'count'}++;
		push @{$returner->{'rows'}}, {
			app => $doc->{'app'},
			uuid => $doc->{'uuid'},
			id => $data->{'id'},
			timestamp => $issued,
			age => $age,
			bucket => $bucket,
			total => ($numbers->{'total'} || 0) + 0,
			paid => $paid,
			balance => $balance
		};
	}
	@{$returner->{'rows'}} = sort { $b->{'age'} <=> $a->{'age'} } @{$returner->{'rows'}};
	return $returner;
}

# Open bills at a moment. A bill is a money row on the payables account (money
# owed, not money moved); a payment is a bank move that names the bill it
# settles in source_uuid. There is no due date on a bill, so the age is counted
# from the day it was written; the screen says so.
sub accounting_payables {
	my $to = shift;
	# a schedule whose date has come is a real bill; make them before reading
	&payable_schedule_run();
	# a payment notification becomes a bill and its payment with no prompt
	&notification_payable_autobook();
	my $returner = { rows => [], total => 0, count => 0, paid_count => 0, buckets => { current => 0, '31_60' => 0, '61_90' => 0, over_90 => 0 } };
	my $bills = &subs::db_query("select * from warehouse where kind='money' and type='transaction' and movement='payable' and cast(timestamp as integer) <= cast(? as integer) order by timestamp", $to)->hashes || [];
	my $payments = &subs::db_query("select * from warehouse where kind='money' and type='transaction' and movement='payment' and cast(timestamp as integer) <= cast(? as integer)", $to)->hashes || [];
	my %settled;
	foreach my $p ( @{$payments} ) {
		next unless $p->{'source_uuid'};
		$settled{$p->{'source_uuid'}} += abs(($p->{'total'} || 0) + 0);
	}
	foreach my $bill ( @{$bills} ) {
		my $total = abs(($bill->{'total'} || 0) + 0);
		next if $total < 0.005;
		my $paid = $settled{$bill->{'uuid'}} || 0;
		my $balance = $total - $paid;
		if ($balance <= 0.005) { $returner->{'paid_count'}++; next; }
		my $issued = ($bill->{'timestamp'} || 0) + 0;
		my $age = int(($to - $issued) / 86400000);
		$age = 0 if $age < 0;
		my $bucket = $age <= 30 ? 'current' : $age <= 60 ? '31_60' : $age <= 90 ? '61_90' : 'over_90';
		$returner->{'total'} += $balance;
		$returner->{'buckets'}->{$bucket} += $balance;
		$returner->{'count'}++;
		push @{$returner->{'rows'}}, {
			uuid => $bill->{'uuid'},
			app => $bill->{'app'},
			vendor => $bill->{'vendor'},
			item => $bill->{'item'},
			timestamp => $issued,
			age => $age,
			bucket => $bucket,
			total => $total,
			paid => $paid,
			balance => $balance
		};
	}
	@{$returner->{'rows'}} = sort { $b->{'age'} <=> $a->{'age'} } @{$returner->{'rows'}};
	return $returner;
}

# --- Recurring bills -------------------------------------------------------
# A schedule is a template, not a bill. It lives in a setting so it needs no
# table of its own, and each due date becomes a real bill keyed by the schedule
# and that date, so running the schedules twice cannot double a bill.
sub payable_schedules {
	my $raw = &subs::setting_grabber({ app => 'budget', setting => 'payable_schedules' });
	my $list = eval { decode_json $raw || '[]' } || [];
	return [ grep { ref $_ eq 'HASH' } @{$list} ];
}

sub payable_schedules_save {
	my $list = shift || [];
	&subs::setting_setter({ app => 'budget', setting => 'payable_schedules', value => encode_json($list) });
}

sub payable_next_date {
	my ($ts,$every,$anchor_day) = @_;
	$every = 'monthly' unless defined $every && length $every;
	# The same interval reader the appointment schedule uses: months and years
	# step through the calendar, so a 31st bill shortens to February's last day
	# and returns to the 31st afterwards.
	my $next = &subs::schedule_next($ts,$every,$anchor_day);
	return defined $next ? $next : &subs::calendar_shift($ts,1,'month',$anchor_day);
}

sub payable_schedule_run {
	my $now = &subs::rightNow();
	my $list = &payable_schedules();
	my ($changed,$made) = (0,0);
	foreach my $s ( @{$list} ) {
		next if (($s->{'active'} || 'on') eq 'off');
		my $guard = 0;
		# A schedule read from words carries its dates outright. The queue's first
		# entry is the next bill; every due date already past is filled in here.
		if (ref $s->{'dates'} eq 'ARRAY') {
			my @queue = sort { $a <=> $b } grep { defined $_ } @{ $s->{'dates'} };
			while (@queue && $queue[0] <= $now && $guard++ < 240) {
				my $due = shift @queue;
				my $uuid = 'sched-' . $s->{'uuid'} . '-' . $due;
				my $exists = &subs::db_query("select 1 from warehouse where kind='money' and uuid=? limit 1", $uuid)->hashes->[0];
				unless ($exists) {
					my $total = ($s->{'amount'} || 0) + 0;
					my $tax = ($s->{'tax'} || 0) + 0;
					&subs::db_insert('warehouse', {
						kind => 'money', type => 'transaction', movement => 'payable',
						account => 'accounts_payable', app => ($s->{'app'} || 'unknown'),
						vendor => ($s->{'vendor'} || ''), item => ($s->{'item'} || ''),
						amount => $total, tax => $tax, total => $total,
						currency => ($s->{'currency'} || ''),
						uuid => $uuid, source_uuid => $s->{'uuid'},
						timestamp => $due, server_time => &subs::rightNow()
					});
					$made++;
				}
			}
			$s->{'dates'} = [ @queue ];
			$s->{'next'} = @queue ? $queue[0] : 0;
			if (!@queue) { $s->{'active'} = 'off'; $s->{'finished'} = 1; }
			$changed = 1;
			next;
		}
		my $until = ($s->{'until'} || 0) + 0;
		while ((($s->{'next'} || 0) + 0) <= $now && $guard++ < 240) {
			my $due = $s->{'next'} + 0;
			# a horizon ends the schedule before its next occurrence
			last if $until && $due >= $until;
			my $uuid = 'sched-' . $s->{'uuid'} . '-' . $due;
			my $exists = &subs::db_query("select 1 from warehouse where kind='money' and uuid=? limit 1", $uuid)->hashes->[0];
			unless ($exists) {
				my $total = ($s->{'amount'} || 0) + 0;
				my $tax = ($s->{'tax'} || 0) + 0;
				&subs::db_insert('warehouse', {
					kind => 'money', type => 'transaction', movement => 'payable',
					account => 'accounts_payable', app => ($s->{'app'} || 'unknown'),
					vendor => ($s->{'vendor'} || ''), item => ($s->{'item'} || ''),
					amount => $total, tax => $tax, total => $total,
					currency => ($s->{'currency'} || ''),
					uuid => $uuid, source_uuid => $s->{'uuid'},
					timestamp => $due, server_time => &subs::rightNow()
				});
				$made++;
			}
			$s->{'next'} = &payable_next_date($due, $s->{'every'}, $s->{'anchor_day'});
			$changed = 1;
		}
		# the horizon has passed, so the schedule has run its course; the bills
		# it already made stay, and Delete removes the row if it is no longer wanted
		if ($until && (($s->{'next'} || 0) + 0) >= $until) {
			$s->{'active'} = 'off';
			$s->{'finished'} = 1;
			$changed = 1;
		}
	}
	&payable_schedules_save($list) if $changed;
	return $made;
}

# --- Notifications that name a payment -------------------------------------
# A bank's "you spent $29.38 at PUBLIC MOBILE SELF" is a bill that has already
# been paid. Match it, suggest the app the house has used for that merchant, and
# offer one OK. The bill's uuid is derived from the notification's own key, so a
# notification stored twice (the phone and the mirror) is still one bill.
sub notification_account {
	my $n = shift;
	my $key = $n->{'key'} || '';
	my ($package) = $key =~ /\|([A-Za-z0-9_.]+)\|/;
	my %known = ( 'ca.koho' => 'koho', 'com.koho' => 'koho' );
	my $account = $known{lc($package || '')};
	if (!$account && ($n->{'message'} || '') =~ /spendable/i) { $account = 'koho'; }
	return undef unless $account && length $account;
	my $row = &subs::db_query("select 1 from settings where app=? and setting in ('pos','mab') and value='account' limit 1", $account)->hashes->[0];
	return $row ? $account : undef;
}

sub notification_bill_uuid {
	my $n = shift;
	my $seed = $n->{'key'} || $n->{'uuid'} || '';
	return 'note-' . &subs::md5_sum($seed);
}

# What a notification names: an amount and the merchant it was paid to. It is
# only a payment when a spending verb sits beside the amount, so "you have $0.00
# left" is not one.
sub notification_payment_of {
	my $n = shift;
	my $msg = $n->{'message'} || '';
	return undef unless $msg =~ /\b(spent|paid|purchase[d]?|charged|debited|payment made)\b/i;
	return undef unless $msg =~ /\$\s?([0-9][0-9,]*\.[0-9]{2})/;
	my $amount = $1;
	$amount =~ s/,//g;
	$amount += 0;
	return undef unless $amount > 0;
	my $merchant;
	if ($msg =~ /\bat\s+([A-Za-z0-9][^.\n]*?)(?:\.|\n|$)/) { $merchant = $1; }
	elsif (($n->{'title'} || '') !~ /transaction made/i) { $merchant = $n->{'title'}; }
	return undef unless $merchant;
	$merchant =~ s/^\s+//; $merchant =~ s/\s+$//; $merchant =~ s/^(the)\s+//i;
	return undef unless length $merchant;
	return { amount => $amount, merchant => $merchant };
}

sub payable_dismissed_keys {
	my $list = eval { decode_json &subs::setting_grabber({ app => 'budget', setting => 'payable_dismissed' }) || '[]' } || [];
	return map { $_ => 1 } @{$list};
}

# Remember that a notification is not a bill. The undo of a booked notification
# is the same decision, so a key dismissed here is never booked again.
sub payable_dismiss_add {
	my @keys = grep { defined $_ && length $_ } @_;
	return 0 unless scalar @keys;
	my $list = eval { decode_json &subs::setting_grabber({ app => 'budget', setting => 'payable_dismissed' }) || '[]' } || [];
	my %have = map { $_ => 1 } @{$list};
	my $changed = 0;
	foreach my $key ( @keys ) {
		next if $have{$key}++;
		push @{$list}, $key;
		$changed++;
	}
	&subs::setting_setter({ app => 'budget', setting => 'payable_dismissed', value => encode_json($list) }) if $changed;
	return $changed;
}

# The same calendar day, in the house's own local time. A statement line is
# stamped with the purchase date, so an import and the notification that
# announced it share a day even when the import ran hours later.
sub notification_same_day {
	my ($a,$b) = @_;
	return 0 unless $a && $b;
	my @x = localtime(int($a / 1000));
	my @y = localtime(int($b / 1000));
	return ($x[5] == $y[5] && $x[4] == $y[4] && $x[7] == $y[7]) ? 1 : 0;
}

# Has this purchase already been written as money leaving the account? A
# statement import, a reconciliation or a typed transaction records the same
# payment as an expense; a bill and its payment on top of that would take the
# money out twice. The match is the account, the amount and the day, and the
# merchant when the recorded row names one. The day is what keeps today's coffee
# from looking like yesterday's.
sub notification_already_recorded {
	my ($n,$payment,$account) = @_;
	my $timestamp = ($n->{'timestamp'} || 0) + 0;
	return 0 unless $timestamp;
	my $rows = &subs::db_query(
		"select vendor, item, timestamp from warehouse where kind='money' and type='transaction' and movement='expense' and account=? and abs(cast(total as real) + ?) < 0.005 and abs(cast(timestamp as integer) - ?) <= ? limit 20",
		$account, $payment->{'amount'}, $timestamp, 36 * 3600000)->hashes || [];
	return 0 unless scalar @{$rows};
	my %want = map { $_ => 1 } &bank_merchant_tokens($payment->{'merchant'});
	foreach my $row ( @{$rows} ) {
		next unless &notification_same_day(($row->{'timestamp'} || 0) + 0, $timestamp);
		my @known = &bank_merchant_tokens($row->{'vendor'} || $row->{'item'} || '');
		# a recorded row that names a merchant has to name this one; a row that
		# names nothing is taken on the amount and the day alone
		return 1 if scalar @known && grep { $want{$_} } @known;
		return 1 unless scalar @known;
	}
	return 0;
}

# Book every qualifying notification. This is the clickless path: a payment the
# bank has already made is a bill raised and settled in the same breath, so it
# needs no prompt. Only a notification from a bank account the house knows is
# booked, because that is what makes the payment leg real money leaving an
# account. The bill's uuid comes from the notification's key, so a duplicate row
# (phone and mirror) books once, and a row already booked is skipped.
sub notification_payable_autobook {
	my $rows = shift;
	$rows = &subs::db_query('select * from notifications order by cast(timestamp as integer) desc limit 400')->hashes || [] unless $rows;
	my %dismissed = &payable_dismissed_keys();
	my ($memory,$made);
	foreach my $n ( @{$rows} ) {
		my $payment = &notification_payment_of($n);
		next unless $payment;
		my $key = $n->{'key'} || $n->{'uuid'};
		next unless $key && length $key;
		next if $dismissed{$key};
		my $account = &notification_account($n);
		next unless $account;
		my $bill_uuid = &notification_bill_uuid($n);
		next if &subs::db_query("select 1 from warehouse where kind='money' and uuid=? limit 1", $bill_uuid)->hashes->[0];
		next if &notification_already_recorded($n, $payment, $account);
		$memory = &bank_merchant_memory() unless defined $memory;
		my $suggestion = &bank_merchant_lookup($memory, $payment->{'merchant'}, 'expense');
		my $app = $suggestion ? ($suggestion->{'app'} || '') : '';
		$app = &subs::unformat_name($payment->{'merchant'}) unless length $app;
		$app = 'unknown' unless length $app;
		my $vendor = &subs::unformat_name($payment->{'merchant'});
		# a title like "Transaction made" names no item; the vendor is the item then
		my $item = &subs::unformat_name($n->{'title'} || '');
		$item = '' if $item =~ /^transaction_made$/i;
		my $timestamp = ($n->{'timestamp'} || 0) + 0;
		$timestamp = &subs::rightNow() unless $timestamp;
		my $currency = &subs::setting_grabber({ app => $app, setting => 'currency' });
		$currency = &subs::setting_grabber({ app => $account, setting => 'currency' }) unless defined $currency && length $currency;
		&subs::db_insert('warehouse', {
			kind => 'money', type => 'transaction', movement => 'payable',
			account => 'accounts_payable', app => $app, vendor => $vendor, item => $item,
			amount => $payment->{'amount'}, tax => 0, total => $payment->{'amount'},
			currency => $currency,
			uuid => $bill_uuid, source_uuid => $key,
			timestamp => $timestamp, server_time => &subs::rightNow()
		});
		&subs::db_insert('warehouse', {
			kind => 'money', type => 'transaction', movement => 'payment',
			account => $account, app => $app, vendor => $vendor, item => $item,
			amount => $payment->{'amount'} * -1, total => $payment->{'amount'} * -1,
			currency => $currency,
			source_uuid => $bill_uuid, uuid => 'notepay-' . &subs::md5_sum($key),
			timestamp => $timestamp, server_time => &subs::rightNow()
		});
		$made++;
	}
	return $made || 0;
}

# The bills the notifications made, newest first, so the screen can show what it
# booked and offer an undo.
sub notification_booked_bills {
	my $limit = shift || 10;
	my $rows = &subs::db_query("select w.*, (select p.account from warehouse p where p.kind='money' and p.movement='payment' and p.source_uuid=w.uuid order by p.timestamp limit 1) as pay_account from warehouse w where w.kind='money' and w.movement='payable' and substr(w.uuid,1,5)='note-' order by cast(w.timestamp as integer) desc limit ?", $limit)->hashes || [];
	return $rows;
}

# The accrual side of the statements. Income and expenses are what the journal
# posted - an invoice's revenue, a bill's cost, a stocked item's cost of goods -
# so the income statement agrees with the Trial Balance. A row whose account is
# a bank account outside the chosen set is left out, so the account filter still
# means something; invoices and bills have no bank account and are house-wide.
sub accounting_journal_report {
	my ($accounts,$from,$to,$pfrom,$pto) = @_;
	my @selected = grep { defined $_ && length $_ } @{$accounts || []};
	my $filter = ' and (j.account = \'\' or j.account = \'accounts_payable\'' .
		(scalar @selected ? ' or j.account in (' . join(',', map { '?' } @selected) . ')' : '') . ')';
	my $window = sub {
		my ($a,$b) = @_;
		return &subs::db_query(
			'select j.account_code, a.name, a.type, ' .
			'sum(cast(j.debit as real)) as d, sum(cast(j.credit as real)) as c ' .
			'from journal j left join ledger_accounts a on a.code = j.account_code ' .
			'where cast(j.timestamp as integer) >= cast(? as integer) and cast(j.timestamp as integer) <= cast(? as integer)' . $filter .
			' group by j.account_code, a.name, a.type', $a, $b, @selected)->hashes || [];
	};
	my $cur = $window->($from,$to);
	my $pri = $window->($pfrom,$pto);
	my (%income,%expense,%cogs,%pincome,%pexpense,%pcogs);
	my %names;
	my ($tax_in,$tax_out,$ptax_in,$ptax_out) = (0,0,0,0);
	foreach my $pair ( [ $cur, \%income, \%expense, \%cogs, \$tax_in, \$tax_out ],
		[ $pri, \%pincome, \%pexpense, \%pcogs, \$ptax_in, \$ptax_out ] ) {
		my ($rows,$inc,$exp,$cog,$tin,$tout) = @{$pair};
		foreach my $r ( @{$rows} ) {
			my $code = $r->{'account_code'};
			my $name = $r->{'name'} || $code;
			my $type = $r->{'type'} || '';
			my $d = ($r->{'d'} || 0) + 0;
			my $c = ($r->{'c'} || 0) + 0;
			$names{$code} = $name;
			if ($type eq 'income') { $inc->{$code} += $c - $d; }
			elsif ($type eq 'expense') {
				if ($code =~ /^6/) { $cog->{$code} += $d - $c; }
				else { $exp->{$code} += $d - $c; }
			}
			elsif ($code eq '2100') { $$tin += $c; $$tout += $d; }
		}
	}
	my $rows_for = sub {
		my ($now,$before) = @_;
		my @out;
		foreach my $code ( sort keys %{$now} ) {
			my $amount = $now->{$code};
			my $prior = $before->{$code} || 0;
			next if abs($amount) < 0.005 && abs($prior) < 0.005;
			push @out, { code => $code, name => ($names{$code} || $code), amount => $amount, prior => $prior };
		}
		return [ sort { $b->{'amount'} <=> $a->{'amount'} } @out ];
	};
	my $income_rows = $rows_for->(\%income,\%pincome);
	my $cogs_rows = $rows_for->(\%cogs,\%pcogs);
	my $expense_rows = $rows_for->(\%expense,\%pexpense);
	my $sum = sub { my $t = shift; my $s = 0; $s += $_ for values %{$t}; return $s; };
	my ($income_total,$cogs_total,$expense_total) = ($sum->(\%income),$sum->(\%cogs),$sum->(\%expense));
	my ($pincome_total,$pcogs_total,$pexpense_total) = ($sum->(\%pincome),$sum->(\%pcogs),$sum->(\%pexpense));
	# the balance sheet: the journal's own account balances at the moment
	my $bal = &subs::db_query(
		'select j.account_code, a.name, a.type, sum(cast(j.debit as real)) as d, sum(cast(j.credit as real)) as c ' .
		'from journal j left join ledger_accounts a on a.code = j.account_code ' .
		'where cast(j.timestamp as integer) <= cast(? as integer)' . $filter .
		' group by j.account_code, a.name, a.type', $to, @selected)->hashes || [];
	my (@asset_rows,@liability_rows);
	my ($assets,$liabilities,$receivables_balance) = (0,0,0);
	foreach my $r ( @{$bal} ) {
		my $code = $r->{'account_code'};
		my $type = $r->{'type'} || '';
		my $net = (($r->{'d'} || 0) + 0) - (($r->{'c'} || 0) + 0);
		next if abs($net) < 0.005;
		my $name = $r->{'name'} || $code;
		if ($type eq 'asset') {
			if ($code eq '1100') { $receivables_balance = $net; next; }
			if ($net > 0) { push @asset_rows, { code => $code, name => $name, balance => $net }; $assets += $net; }
			else { push @liability_rows, { code => $code, name => $name, balance => -$net }; $liabilities += -$net; }
		}
		elsif ($type eq 'liability') {
			my $owed = -$net;
			if ($owed > 0) { push @liability_rows, { code => $code, name => $name, balance => $owed }; $liabilities += $owed; }
			else { push @asset_rows, { code => $code, name => $name, balance => -$owed }; $assets += -$owed; }
		}
	}
	@asset_rows = sort { $a->{'code'} <=> $b->{'code'} } @asset_rows;
	@liability_rows = sort { $a->{'code'} <=> $b->{'code'} } @liability_rows;
	$assets += $receivables_balance;
	return {
		income => $income_rows, cogs => $cogs_rows, expense => $expense_rows,
		income_total => $income_total, cogs_total => $cogs_total, expense_total => $expense_total,
		gross_profit => $income_total - $cogs_total,
		prior_income_total => $pincome_total, prior_cogs_total => $pcogs_total, prior_expense_total => $pexpense_total,
		prior_gross_profit => $pincome_total - $pcogs_total,
		tax_in => $tax_in, tax_out => $tax_out,
		assets => \@asset_rows, liabilities => \@liability_rows,
		assets_total => $assets, liabilities_total => $liabilities,
		receivables_balance => $receivables_balance
	};
}

sub accounting_reports {
	my $args = shift;
	my $accounts = $args->{'accounts'} || [];
	my ($from,$to) = (($args->{'from'} || 0) + 0, ($args->{'to'} || 0) + 0);
	my $span = $to - $from;
	$span = 1 if $span <= 0;
	my ($pfrom,$pto) = ($from - $span, $from);
	my $moves = &accounting_moves($accounts, $from, $to);
	my $prior = &accounting_moves($accounts, $pfrom, $pto);
	# the statements' accrual side is the journal; bring it up to date first
	&subs::accounting_journal_maybe_rebuild();
	my $accrual = &accounting_journal_report($accounts, $from, $to, $pfrom, $pto);
	my $income_total = $accrual->{'income_total'};
	my $expense_total = $accrual->{'expense_total'};
	my $cogs_total = $accrual->{'cogs_total'};
	my $prior_income_total = $accrual->{'prior_income_total'};
	my $prior_expense_total = $accrual->{'prior_expense_total'};
	my $prior_cogs_total = $accrual->{'prior_cogs_total'};
	my @income_rows = @{$accrual->{'income'}};
	my @expense_rows = @{$accrual->{'expense'}};
	my @cogs_rows = @{$accrual->{'cogs'}};
	# every account's own activity in the window, opening to closing
	my @activity;
	my ($cash_opening,$cash_closing,$cash_prior_opening) = (0,0,0);
	foreach my $a ( sort @{$accounts} ) {
		my $opening = &bank_ledger_balance($a, $from);
		my $closing = &bank_ledger_balance($a, $to);
		my ($in,$out,$transfer) = (0,0,0);
		foreach my $t ( @{$moves} ) {
			next unless (($t->{'account'} || '') eq $a);
			my $total = ($t->{'total'} || 0) + 0;
			if (($t->{'movement'} || '') eq 'income') { $in += $total; }
			elsif (($t->{'movement'} || '') eq 'expense') { $out += -$total; }
			elsif (($t->{'movement'} || '') eq 'payment') { $out += -$total; }
			elsif (($t->{'movement'} || '') eq 'transfer') { $transfer += $total; }
		}
		$cash_opening += $opening;
		$cash_closing += $closing;
		$cash_prior_opening += &bank_ledger_balance($a, $pfrom);
		push @activity, { app => $a, opening => $opening, in => $in, out => $out, transfer => $transfer, closing => $closing };
	}
	# cash flow: the operating moves, the transfers' net, and whatever the
	# inventory anchors changed (the residual is what makes it tie)
	my ($op_in,$op_out,$transfers) = (0,0,0);
	foreach my $t ( @{$moves} ) {
		my $total = ($t->{'total'} || 0) + 0;
		if (($t->{'movement'} || '') eq 'income') { $op_in += $total; }
		elsif (($t->{'movement'} || '') eq 'expense') { $op_out += -$total; }
		elsif (($t->{'movement'} || '') eq 'payment') { $op_out += -$total; }
		elsif (($t->{'movement'} || '') eq 'transfer') { $transfers += $total; }
	}
	my ($prior_in,$prior_out,$prior_transfers) = (0,0,0);
	foreach my $t ( @{$prior} ) {
		my $total = ($t->{'total'} || 0) + 0;
		if (($t->{'movement'} || '') eq 'income') { $prior_in += $total; }
		elsif (($t->{'movement'} || '') eq 'expense') { $prior_out += -$total; }
		elsif (($t->{'movement'} || '') eq 'payment') { $prior_out += -$total; }
		elsif (($t->{'movement'} || '') eq 'transfer') { $prior_transfers += $total; }
	}
	my $change = $cash_closing - $cash_opening;
	my $adjustment = $change - ($op_in - $op_out + $transfers);
	# the prior period closes where this one opens, so its closing cash is this
	# window's opening figure
	my $prior_change = $cash_opening - $cash_prior_opening;
	my $prior_adjustment = $prior_change - ($prior_in - $prior_out + $prior_transfers);
	# balance sheet: the journal's account balances; an overdrawn bank account
	# is a liability, and the receivable line is the journal's own 1100
	my $ar = &accounting_receivables($to);
	my @asset_rows = @{$accrual->{'assets'}};
	my @liability_rows = @{$accrual->{'liabilities'}};
	my $assets = $accrual->{'assets_total'};
	my $liabilities = $accrual->{'liabilities_total'};
	return {
		income => \@income_rows,
		expense => \@expense_rows,
		cogs => \@cogs_rows,
		income_total => $income_total,
		expense_total => $expense_total,
		cogs_total => $cogs_total,
		gross_profit => $income_total - $cogs_total,
		prior_gross_profit => $prior_income_total - $prior_cogs_total,
		prior_cogs_total => $prior_cogs_total,
		net_income => $income_total - $cogs_total - $expense_total,
		prior_income_total => $prior_income_total,
		prior_expense_total => $prior_expense_total,
		prior_net_income => $prior_income_total - $prior_cogs_total - $prior_expense_total,
		tax_in => $accrual->{'tax_in'},
		tax_out => $accrual->{'tax_out'},
		activity => \@activity,
		activity_totals => { opening => $cash_opening, in => $op_in, out => $op_out, transfer => $transfers, closing => $cash_closing },
		assets => \@asset_rows,
		liabilities => \@liability_rows,
		assets_total => $assets,
		liabilities_total => $liabilities,
		equity => $assets - $liabilities,
		receivables => $ar,
		receivables_balance => $accrual->{'receivables_balance'},
		cash => {
			opening => $cash_opening,
			closing => $cash_closing,
			in => $op_in,
			out => $op_out,
			transfers => $transfers,
			change => $change,
			adjustment => $adjustment,
			prior_opening => $cash_prior_opening,
			prior_closing => $cash_opening,
			prior_in => $prior_in,
			prior_out => $prior_out,
			prior_transfers => $prior_transfers,
			prior_change => $prior_change,
			prior_adjustment => $prior_adjustment
		}
	};
}

get '/manager/budget' => sub($c) {
	my $totals = {};
	my $tally = {};
	my $budgets = {};
	my $new_settings = eval { return decode_json $c->param('new_settings') } || {};
	foreach my $ns ( keys %{$new_settings} ) {
		if ($new_settings->{$ns} =~ /[A-Za-z0-9.,-]/gi) {
			if ($ns =~ /_time/gi) {
				$new_settings->{$ns} = &subs::ago_calc($new_settings->{$ns}, &subs::rightNow());
			}
			&subs::setting_setter({ app => 'budget', setting => $ns, value => $new_settings->{$ns} });
		}
		else {
			&subs::setting_deleter({ app => 'budget', setting => $ns });
		}
	}
	my @dollas = qw/amount tax aux total/;
	my @categories = qw/category subcategory/;
	my $categories = { };
	for (my $n = 1; $n <= 100; $n++) {
		my $u = 'subcategory' . $n;
		push @categories, $u;
	#	$categories->{$u} = {};
	}

	my $timestamp = $c->param('timestamp');
	my $time_machine = $c->param('time_machine');

	my $settings = &subs::settings_grabber({ app => 'budget' });
	my $display = $c->param('display') || $settings->{'display'};
	# the display used to carry a budget table; the app is a set of financial
	# statements now, so an old saved budget view lands on the income statement
	$display = 'income_statement' if !defined $display || $display eq '' || $display eq 'budgets';
	if ($settings->{$display . '_display'} ne '') {
		my $d = eval { decode_json $settings->{$display . '_displays'} };
		foreach my $k ( keys %{$d->{$settings->{$display . '_display'}}} ) {
			$c->param($k, $d->{$settings->{$display . '_display'}}->{$k});
			&subs::setting_setter({ app => 'budget', setting => $k, value => $d->{$settings->{$display . '_display'}}->{$k} });
		}
		$d->{$settings->{$display . '_display'}}->{$display . '_display'} = $settings->{$display . '_display'};
		$settings = &subs::settings_grabber({ app => 'budget' });
	}
	my $display_categorization = $settings->{'display_categorization'};
	my $scope = $settings->{'scope'} || 'hour';
	my $movement = eval { decode_json $c->param('movement') || $settings->{'movement'} } || ['all'];

	my $project = eval { decode_json $c->param('projects') || $settings->{'projects'} } || ['all'];
	my $account = eval { decode_json $c->param('accounts') || $settings->{'accounts'} } || ['all'];
	my $columns = eval { decode_json $c->param('columns') || $settings->{'columns'} } || ['all'];
	my $timeshift = $c->param('timeshift');
	my ($db,$database,$sql) = &subs::database_grabber();
	my @columns = qw/app when occurences occurence_budget duration duration_budget duration_percent total_budget manufacturer item vendor account project amount tax aux total/;
	my $tr = {};

	my @time_scopes = ('next', 'this','last');
	my @time_widths;

	my @time_lengths = qw/minute hour day week month year/;
	if ($settings->{'s_visual'} eq 'allocation') {
		@time_scopes = undef;
		for (my $n = 0; $n <= 366; $n++) {
			push @time_scopes, $n;
		}
		@time_lengths = qw/second minute hour mday month year wday yday isdst/;
		@time_widths = ( 60, 60, 24, 31, 12, 150, 7, 365, 2 );
	}
	else {
		for (my $n = 2; $n <= 30; $n++) {
			push @time_scopes, $n . 'last';
			unshift @time_scopes, $n . 'next';
		}
	}


	my ($bt,$t1,$t2);
	# a father_time window ends on the next period's first instant, so that bound
	# is exclusive; an end_time the user picked stays inclusive
	my $t2_comp = '<=';
	if ($settings->{'start_time'} || $settings->{'end_time'}) {
		$bt = $settings->{'start_time'};
		$t2 = $settings->{'end_time'};
		if ($settings->{'start_time'} && !$settings->{'end_time'}) {
			$t2 = &subs::rightNow();
		}
		elsif (!$settings->{'start_time'} && $settings->{'end_time'}) {
			$bt = &subs::rightNow();
		}
	}
	else {
		if ($time_machine) {
			$timestamp = &time_machine_resolve($time_machine,$timestamp);
		}
		if ($timeshift) {
			$timestamp = &subs::ago_calc($timeshift,$timestamp);
		}
		$bt = &subs::time_span($scope, $timestamp); #timestamp at beginning
		$t1 = ($timestamp - $bt);
		$t2 = ($timestamp);
		# the multiplier widens the window in whole periods, the same way the
		# inventory's Nnext windows read it
		($bt, $t2) = &father_time({
			scope => $scope,
			ts => $settings->{'time_when'},
			lock => $settings->{'s_lock'},
			timestamp => $timestamp,
			periods => $settings->{'when_multiplier'} || 1
		});
		$t2_comp = '<';
	}
	my $total_duration = $t2 - $bt;
	my $last_inventory = $bt;
	my $accountals = &subs::db_query('select distinct(app) from settings where (setting=? or setting =?) and value=? order by app', 'pos', 'mab', 'account');
	my $accounts = $accountals->hashes;

	push @{$accounts}, { app => 'gallery' };
	unshift @{$accounts}, { app => 'all' };

	my $all_accounts = $accounts;
	unless (grep { $_ eq 'all' } @{$account}) {
		my @acco;
		foreach my $a ( @{$account} ) {
			push @acco, grep { $_->{'app'} eq $a } @{$accounts};
		}
	$accounts = \@acco;
	}

	my $acc = {};

	my $all_columns = \@columns;
	if (grep { $_ eq 'all' } @{$columns}) {
		$columns = $all_columns;
	}

	my $projections = &subs::db_query('select distinct(app) from settings where (setting=? or setting=?) and value=? order by app', 'pos', 'mab', 'project');
	my $projects = $projections->hashes;
	unshift @{$projects}, { app => 'all' };
	my $all_projects = $projects;
	unless (grep { $_ eq 'all' } @{$project}) {
		my @proj;
		foreach my $a ( @{$project} ) {
			push @proj, grep { $_->{'app'} eq $a } @{$projects};
		}
		$projects = \@proj;
	}

	# the invoices display is a document ledger, not a money tally: collect the
	# documents once. (The old code ran this query inside the account loop as well,
	# which returned the same unrestricted window once per account and multiplied
	# every transaction - and its total - by the number of accounts.)
	my $documents = [];
	if ($display eq 'invoices') {
		my $docr = &subs::db_query("select * from appointments where type in ('invoice','quote') and timestamp >= ? and timestamp $t2_comp ? order by timestamp desc", $last_inventory, $t2)->hashes;
		foreach my $doc ( @{$docr} ) {
			$doc->{'data'} = eval { return decode_json $doc->{'data'} } || {};
			my $numbers = $doc->{'data'}->{'numbers'} || {};
			my $paid = 0;
			foreach my $p ( @{$doc->{'data'}->{'payments'} || []} ) {
				$paid += $p->{'amount'} if defined $p->{'amount'} && $p->{'amount'} =~ /[0-9]/;
			}
			$doc->{'paid'} = $paid;
			$doc->{'balance'} = defined $numbers->{'balance'} ? $numbers->{'balance'} : ($numbers->{'total'} || 0) - $paid;
			$doc->{'formatted_type'} = &subs::format_name($doc->{'type'});
			$doc->{'formatted_item'} = &subs::format_name($doc->{'data'}->{'item'});
			$doc->{'formatted_total'} = &subs::price_formatter($numbers->{'total'} || 0);
			$doc->{'formatted_paid'} = &subs::price_formatter($paid);
			$doc->{'formatted_balance'} = &subs::price_formatter($doc->{'balance'});
			$doc->{'formatted_status'} = $doc->{'status'} ? &subs::format_name($doc->{'status'}) : ($doc->{'type'} eq 'quote' ? 'Draft' : 'Open');
			$totals->{'documents'}->{'count'}++;
			$totals->{'documents'}->{$doc->{'type'}}->{'count'}++;
			foreach my $key ( qw/total paid balance/ ) {
				my $value = $key eq 'total' ? ($numbers->{'total'} || 0) : $key eq 'paid' ? $paid : $doc->{'balance'};
				$totals->{'documents'}->{$key} += $value;
				$totals->{'documents'}->{$doc->{'type'}}->{$key} += $value;
			}
		}
		push @{$documents}, @{$docr};
	}
	my $transactions;
	foreach my $accounting ( @{$accounts}) {
		next if $acc->{$accounting->{'app'}};
		$accounting->{'balance'} = 0;
		$accounting->{'settings'} = &subs::settings_grabber({ app => $accounting->{'app'} });
		my $inventory = &subs::db_query('select * from appointments where app=? and type=? and movement=? order by timestamp', $accounting->{'app'}, 'transaction','inventory');
		my $inv = $inventory->hashes;
		my $final_t = {};
		foreach my $i ( @{$inv} ) {
			if ($i->{'timestamp'} < $bt) {
				$accounting->{'balance'} = $i->{'amount'};
				$accounting->{'starting_balance'} = $i->{'amount'};
				push @{$accounting->{'journals'}}, { amount => $accounting->{'balance'}, timestamp => $i->{'timestamp'} };
				$last_inventory = $i->{'timestamp'};
				$final_t = $i;
				$final_t->{'timestamp'} = $bt;
			}
		}
#		push @{$transactions}, $final_t if $final_t->{'timestamp'};
		# the money moves now come from the warehouse ledger; the balance anchors
		# (inventory-movement appointments) are kept where they are for now, so the
		# statement is unchanged while the money it tallies lives on the ledger
		my $money_moves = &subs::db_query("select * from warehouse where kind = 'money' and account = ? and timestamp >= ? and timestamp $t2_comp ? order by timestamp",
			$accounting->{'app'},$last_inventory,$t2)->hashes;
		my $money_anchors = &subs::db_query("select * from appointments where account = ? and type != ? and movement = ? and timestamp >= ? and timestamp $t2_comp ? order by timestamp",
			$accounting->{'app'}, 'inventory', 'inventory', $last_inventory,$t2)->hashes;
		push @{$transactions}, sort { $a->{'timestamp'} <=> $b->{'timestamp'} } (@{$money_moves}, @{$money_anchors});
		if (grep { $_ eq 'all' } @{$movement}) {

		}
		else {
			my $transactionality = [];
			foreach my $m ( @{$movement} ) {
				push @{$transactionality}, grep { $_->{'type'} eq $m } @{$transactions};
			}
			$transactions = $transactionality;
		}
		$last_inventory = $bt;
		$acc->{$accounting->{'app'}} = $accounting;
	}
	unless ( grep { $_ eq 'all' } @{$project} ) {
		my $tp = [];
		foreach my $tr ( @{$project} ) {
			push @{$tp}, grep { $_->{'project'} eq $tr } @{$transactions};
		}
		$transactions = $tp;
	}

	foreach my $t ( @{$transactions} ) {
		if ($t->{'movement'} eq 'inventory') {
			$acc->{$t->{'account'}}->{'balance'} = $t->{'amount'};
			push @{$acc->{$t->{'account'}}->{'journals'}}, { amount => $acc->{$t->{'account'}}->{'balance'}, timestamp => $t->{'timestamp'} };
			$last_inventory = $t->{'timestamp'};
			next;
		}
		$tally->{$t->{'app'}} = {
			income => [],
			expense => [],
			transfer => [],
			totals => {},
			settings => &subs::settings_grabber({ app => $t->{'app' } })
		} unless $tally->{$t->{'app'}};


		my $pushable = $display_categorization;

		if ($display_categorization eq 'category') {
			$pushable = $tally->{$t->{'app'}}->{'settings'}->{'category'};
			if ($pushable eq '') {
				$pushable = 'unknown';
			}
		}
		elsif ($display_categorization eq undef || $display_categorization eq '') {
			$pushable = $t->{'app'};
		}
		else {
			$pushable = $t->{$display_categorization};
		}

		$tally->{$pushable} = {
			income => [],
			expense => [],
			transfer => [],
			totals => { },
			settings => &subs::settings_grabber({ app => $pushable })
		} unless $tally->{$pushable};

	#	$t->{'movement'} = 'expense' unless $t->{'movement'};
		$acc->{$t->{'account'}}->{'balance'} = $acc->{$t->{'account'}}->{'balance'} + $t->{'total'};
		push @{$acc->{$t->{'account'}}->{'journals'}}, { amount => $acc->{$t->{'account'}}->{'balance'}, timestamp => $t->{'timestamp'} };
		if ($t->{'timestamp'} < $bt) {
			$acc->{$t->{'account'}}->{'starting_balance'} = $acc->{$t->{'account'}}->{'balance'};
		}
		elsif ($t->{'timestamp'} >= $bt && $t->{'timestamp'} <= $t2) {
			foreach my $dolla (@dollas) {
				for (my $ca = 0; $ca <= scalar @categories; $ca++) {
					my $cat = $categories[$ca];
					my $cath = $cat;
					if ($tally->{$t->{'app'}}->{'settings'}->{$cat}) {
						my $distinct = $tally->{$t->{'app'}}->{'settings'}->{$cat};
						if (0 == 0) {
							$cath = $distinct;
						}
						unless ($categories->{$cath}->{'info'}->{$distinct}) {
							$categories->{$cath}->{'info'}->{$distinct} = &subs::settings_grabber({ app => $tally->{$t->{'app'}}->{'settings'}->{$cat} });
						}
						if ($ca > 1) {
							$cath = $categories->{$cath}->{'info'}->{'subcategory' . ($ca - 1)};
						}
						elsif ($ca > 0) {
							$cath = $categories->{$cath}->{'info'}->{'category'};
						}
						$categories->{$cath}->{$tally->{$t->{'app'}}->{'settings'}->{$cat}}->{'ca'} = $ca;
						if ($dolla eq 'amount') {
							push @{$categories->{$cath}->{$tally->{$t->{'app'}}->{'settings'}->{$cat}}->{'list'}}, $t;
						}
						$categories->{$cath}->{$tally->{$t->{'app'}}->{'settings'}->{$cat}}->{$dolla} += $t->{$dolla} if $t->{$dolla} =~ /[0-9]/;
					}
				}
			}
			if ($t->{'movement'} eq 'income') {
				$t->{'t'} = 'income';
				$t->{'occurences'} = 1;
				$t->{'duration'} = abs $t->{'duration'};
				foreach my $dolla ( @dollas ) {
					$t->{$dolla} = abs $t->{$dolla} if $t->{$dolla} =~ /[0-9]/;
				}
				foreach my $col ( @columns ) {
					$totals->{'income'}->{$col} += $t->{$col} unless $t->{$col} =~ /[a-zA-Z]/ || $t->{$col} !~ /[0-9]/;
				}
			}
			elsif ($t->{'movement'} eq 'transfer') {
				$t->{'t'} = 'transfer';
				$t->{'occurences'} = 1;
				$t->{'duration'} = abs $t->{'duration'};
				#unless (grep { $_->{'uuid'} eq $t->{'uuid'} } @{$tally->{$t->{'app'}}->{$t->{'movement'}}}) {
					foreach my $col ( @columns ) {
						$totals->{'transfer'}->{$col} += $t->{$col} unless $t->{$col} =~ /[a-zA-Z]/ || $t->{$col} !~ /[0-9]/;
					}
				#}
			}
			elsif ($t->{'movement'} eq 'expense') {
				$t->{'t'} = 'expense';
				$t->{'movement'} = 'expense';
				$t->{'occurences'} = 1;
				$t->{'duration'} = (abs $t->{'duration'}) * -1;
				foreach my $dolla ( @dollas ) {
					$t->{$dolla} = ($t->{$dolla});# * -1;
				}
				foreach my $col ( @columns ) {
					$totals->{'expense'}->{$col} += $t->{$col} unless $t->{$col} =~ /[a-zA-Z]/ || $t->{$col} !~ /[0-9]/;
				}
			}
			foreach my $col ( @columns ) {
				unless ($t->{$col} =~ /[a-zA-Z]/ || $t->{$col} !~ /[0-9]/) {
					$totals->{'total'}->{$col} += $t->{$col};
					$tally->{$pushable}->{'totals'}->{$t->{'movement'}}->{$col} += $t->{$col};
				}
			}
			push @{$tally->{$pushable}->{$t->{'movement'}}}, $t;
			@{$tally->{$pushable}->{$t->{'movement'}}} = sort { $b->{'timestamp'} <=> $a->{'timestamp'} } @{$tally->{$pushable}->{$t->{'movement'}}};
		}
	}
	foreach my $d ( keys %{$gb::transaction_types} ) {
		$totals->{$d}->{'duration_percent'} = &subs::percent_formatter(abs $totals->{$d}->{'duration'} / $total_duration);
		$totals->{$d}->{'duration'} = &subs::duration_sayer(abs $totals->{$d}->{'duration'} / 1000);
	}
	foreach my $app ( keys %{$tally} ) {
		foreach my $dr ( keys %{$gb::budget_modes} ) {
			my $budget = &budget_calculator({
				app => $app,
				budget => $tally->{$app}->{'settings'}->{'budget'},
				circumstance => $dr,
				scope => $scope,
				value => $tally->{$app}->{'totals'}->{$dr},
				settings => $tally->{$app}->{'settings'}
			});
			$tally->{$app}->{'budget'}->{$dr} = $budget if $budget->{'eval'};
		}
	}
	if ($display eq 'budgets') {
		$settings->{'budget_displays'} = eval { return decode_json $settings->{'budget_displays'} } || {};
	}
	elsif ($display eq 'statement') {
		$settings->{'statement_displays'} = eval { return decode_json $settings->{'statement_displays'} } || {};
	}
	elsif ($display eq 'daily_sheet') {
		$settings->{'daily_sheet_displays'} = eval { return decode_json $settings->{'daily_sheet_displays'} } || {};
	}
	my @display_options = (
		[ 'income_statement', &subs::ui('Income Statement') ],
		[ 'balance_sheet', &subs::ui('Balance Sheet') ],
		[ 'cash_flow', &subs::ui('Cash Flow') ],
		[ 'account_activity', &subs::ui('Account Activity') ],
		[ 'trial_balance', &subs::ui('Trial Balance') ],
		[ 'statement', &subs::ui('Ledger') ],
		[ 'receivables', &subs::ui('Receivables') ],
		[ 'payables', &subs::ui('Payables') ],
		[ 'invoices', &subs::ui('Invoices') ],
		[ 'daily_sheet', &subs::ui('Day Book') ],
		[ 'reconcile', &subs::ui('Reconcile') ]
	);
	my %known_display = map { $_->[0] => 1 } @display_options;
	$display = 'income_statement' unless $known_display{$display};
	my $reports = {};
	my $trial = {};
	my $payables = {};
	my $schedules = [];
	my $notification_booked = [];
	my @payable_apps;
	if ($display eq 'trial_balance') {
		# the journal is derived; bring it up to date before reading it so the
		# screen never shows the picture from before the last transaction
		&subs::accounting_journal_maybe_rebuild();
		$trial = &subs::accounting_trial_balance($t2);
	}
	if ($display eq 'payables') {
		$payables = &accounting_payables($t2);
		$schedules = &payable_schedules();
		$notification_booked = &notification_booked_bills(10);
		@payable_apps = map { $_->{'app'} } @{ &subs::db_query("select distinct(app) as app from warehouse where kind='money' and app is not null and app != '' order by app")->hashes || [] };
	}
	if ($display eq 'income_statement' || $display eq 'balance_sheet' || $display eq 'cash_flow' || $display eq 'account_activity' || $display eq 'receivables') {
		my @report_accounts = map { $_->{'app'} } grep { $_->{'app'} ne 'all' && $_->{'app'} ne 'gallery' } @{$accounts};
		$reports = &accounting_reports({ accounts => \@report_accounts, from => $bt, to => $t2 });
	}
	my $period_span = $t2 - $bt;
	my $period_start_label = POSIX::strftime('%b %e, %Y', localtime($bt / 1000));
	my $period_end_label = POSIX::strftime('%b %e, %Y', localtime($t2 / 1000));
	my $prior_start_label = POSIX::strftime('%b %e, %Y', localtime(($bt - $period_span) / 1000));
	my $prior_end_label = $period_start_label;
	my $data = {
