		timeshift => $timeshift,
		display => $display,
		start => $bt,
		end => $t2,
		total_duration => $total_duration,
		settings => $settings,
		all_columns => $all_columns,
		columns => $columns,
		dollas => \@dollas,
		time_scopes => \@time_scopes,
		time_lengths => \@time_lengths,
		displays => \@display_options,
		reports => $reports,
