get '/manager/budget/current_information' => sub($c) {
	my $app = $c->param('app');
	my $timestamp = $c->param('timestamp');
	my $circumstance = $c->param('circumstance');

	my $ci = &budget_current_information($app,$circumstance,$timestamp);

	$c->render(text => $ci->{'template'});
};

# A circumstance's own reading, written the way the budget panel shows it: a base
# mode (occurences, duration, total, quantity) wears that mode's formatter, and a
# measure wears its own name, the way the autocalc writes one ("8681.139steps").
# The lookup is guarded on purpose: a bare chained deref of an absent measure
# would autovivify the key in %{$gb::budget_modes}, and then every later
# budget_calculator in this process would take the measure for a base mode and
# skip reading it (its budget value came back undef).
sub budget_value_formatter {
	my ($circumstance, $value) = @_;
	my $mode = $gb::budget_modes->{$circumstance};
	if ($mode && $mode->{'formatted'}) {
		my $formatted = eval { &{$mode->{'formatted'}}($value) };
		return $formatted if defined $formatted;
	}
	return sprintf("%.3f", $value) . $circumstance;
}

sub budget_current_information($app,$circumstance,$timestamp) {

	my $autocalc = &subs::cache_get({ app => $app, context => 'autocalc', subcontext => $circumstance });
	my $budget = &subs::cache_get({ app => $app, context => 'budget', subcontext => $circumstance });
	unless ($autocalc->{$budget}) {
		$autocalc = &Manager::budget_autocalc({
			app => $app,
			circumstance => $circumstance,
		});
	}

	# Both comparisons are read for the same share of the period, so an hour or a
	# day only part done is not held against the whole of its budget and its whole
	# typical. A completed (or rolling) window has share 1 and reads as before.
	my $share = (defined $budget->{'elapsed'} && $budget->{'elapsed'} >= 0 && $budget->{'elapsed'} < 1) ? $budget->{'elapsed'} : 1;
	my $typical = $autocalc->{$budget->{'scope_name'}}->{'result'} || 0;
	my $budget_share = ($budget->{'budgeted'} || 0) * $share;
	my $typical_share = $typical * $share;
	my $value = $budget->{'value'} || 0;
	my $ov = sprintf("%.5f", $typical_share - $budget_share);
	my $improvement = {
		share => $share,
		difference => $value - $budget_share,
		overall => &budget_value_formatter($circumstance, $ov),
		formatted_difference => &budget_value_formatter($circumstance, $value - $budget_share),
		percentage => eval { return &subs::percent_formatter(($value - $budget_share) / $typical_share) } || 0,
		overall_percentage => eval { return &subs::percent_formatter(($typical_share - $budget_share) / $typical_share) } || 0
	};
	my $goal = &goal_reading($app, $circumstance);
	my $c = &subs::controller_builder();
	my $template = $c->render_to_string(
		template => 'apps/budget_current_information',
		circumstance => $circumstance,
		improvement => $improvement,
		budget => $budget,
		autocalc => $autocalc,
		goal => $goal
	);
	return { template => $template, circumstance => $circumstance, improvement => $improvement, autocalc => $autocalc, budget => $budget, goal => $goal };
}

sub budget_runner($app) {
	&subs::subprocessor(sub {
		my ($db) = &subs::database_grabber();
		my $scope;
		my $timestamp = &subs::rightNow();
		my $budgets = &subs::db_query('select distinct(app) as app,* from settings where app=? and setting = ? and device = ? and value is not null',$app,'budget', $device)->hashes;
		my $sb = eval { return decode_json &subs::setting_grabber({ app => $app, setting => 'special_budgets' }) } || [];
		my $am = eval { return decode_json &subs::setting_grabber({ app => $app, setting => 'app_measures' }) } || {};
		# the base readings, any special budgets, and the app's measures: a measure
		# budget (19869steps/week, 175weight/month) is a budget like any other and
		# gets its light the same way
		my @budget_modes = ( @{$sb}, keys %{$gb::budget_modes}, keys %{$am} );
		foreach my $b ( @{$budgets} ) {
			my $app = $b->{'app'};
			my @buds = split /,/, $b->{'value'};
			foreach my $circumstance ( @budget_modes ) {
				my $cache_budget = &subs::cache_get({ app => $app, context => 'budget', subcontext => $circumstance });
				if ($cache_budget->{'scope'}) {
					$scope = $cache_budget->{'scope'};
				}
				foreach my $bud ( @buds ) {
					my @bt = split '/', $bud;
					$scope = $bt[-1];

					my $budget = &Manager::budget_calculator({
						app => $app,
						circumstance => $circumstance,
						scope => $scope,
						budget => $bud
					});
					if ($budget->{'is_scope'} && $circumstance eq $budget->{'circumstance'}) {
						&subs::cache_set({ app => $app, context => 'budget', subcontext => $circumstance }, $budget);
						my $msg = {
							app => $app,
							type => 'budget',
							budget => {
								colour => $budget->{'colour'},
								circumstance => $budget->{'circumstance'},
							}
						};
						&Websocket::send('tab', $msg);
						my $ci = &budget_current_information($app,$circumstance,$timestamp);
						&Websocket::send('tab', {
							type => 'html',
							content => $ci->{'template'},
							selector => '.budget_current_information[app="' . $app .'"][circumstance="' . $circumstance . '"]'
						});

					}
				}
			}
		}
		&centre_view_grabber({ app => &subs::unformat_name($app), timestamp => &subs::rightNow(), cached => 'no' });

	}, { name => 'budget runner' });
}


# The calc a measure reads with: its own remembered one (steps sum, weight
# average), else the app's s_calc as the fallback. Used wherever a measure's
# value is taken - the budget runner, the panel - so a steps budget and a weight
# budget read right at the same time, whatever the display is showing.
sub measure_calc_for {
	my ($app, $measure, $fallback) = @_;
	my $calc = &subs::setting_grabber({ app => $app, setting => 'measure_calc', subsetting => $measure });
	$calc = $fallback unless (defined $calc && length $calc);
	return (defined $calc && length $calc) ? $calc : 'sum';
}


# One budget/goal entry read apart: a leading "<=" or ">=" says which way it
# runs (under is good, or over is good), the number is the target, the name that
# follows is the measure ($ for money, absent for occurences), and "/<scope>"
# makes it a rate rather than a fixed level.
sub budget_entry_parse {
	my $entry = shift;
	my $direction = 'floor';
	my $e = $entry;
	if ($e =~ s/^<=//) { $direction = 'ceiling'; }
	elsif ($e =~ s/^>=//) { $direction = 'floor'; }
	my ($body, $scope) = split '/', $e, 2;
	my ($value, $measure);
	if ($body =~ /^\$(.*)$/) { $measure = '$'; $value = $1; }
	elsif ($body =~ /^([0-9.\-]+)([a-zA-Z_]*)$/) { $value = $1; $measure = $2; }
	else { $value = $body; $measure = ''; }
	return { raw => $entry, direction => $direction, value => $value, measure => $measure, scope => $scope, fixed => (defined $scope ? 0 : 1) };
}

# The measure's own trend: a least-squares line through its readings, as
# value-per-day, with the latest reading and the reading count. The stretch it
# reads is the floor given unless the measure is recorded more sparsely than
# that: the window is widened to about a dozen readings when the median gap
# between them is longer than the floor of a dozen dozen, so a level recorded
# once a month or once a year is not judged on the few points a fixed 90 days
# would hold. Times are measured from the first reading so the huge millisecond
# stamps do not cancel the fit.
sub measure_trend($app, $measure, $floor_days) {
	my $floor = ($floor_days || 90) * 86400000;
	my $appts = &subs::db_query('select timestamp,measures from appointments where app = ? and measures is not null order by timestamp desc limit 600', $app)->hashes;
	my @pts;
	foreach my $a ( @{$appts} ) {
		my $ms = eval { return decode_json $a->{'measures'} } || [];
		foreach my $m ( @{$ms} ) {
			next unless defined $m->{$measure} && $m->{$measure} =~ /[0-9]/;
			push @pts, [ ($a->{'timestamp'} + 0), ($m->{$measure} + 0) ];
		}
	}
	@pts = sort { $a->[0] <=> $b->[0] } @pts;
	return (undef, undef, scalar @pts) if scalar @pts < 2;
	# how often it is recorded: the median gap over the recent readings
	my @gaps;
	for (my $i = $#pts; $i > 0 && scalar @gaps < 50; $i--) {
		my $g = $pts[$i][0] - $pts[$i-1][0];
		push @gaps, $g if $g > 0;
	}
	my $window = $floor;
	if (scalar @gaps) {
		my @sorted = sort { $a <=> $b } @gaps;
		my $gap = $sorted[int($#sorted / 2)];
		my $span = $gap * 12;
		$window = $span if $span > $window;
	}
	# fit the readings the window reaches back over, so a sparsely kept level is
	# read over the long stretch it needs and a dense one stays on its recent pace
	my $cut = $pts[-1][0] - $window;
	my @fit = grep { $_->[0] >= $cut } @pts;
	@fit = @pts if scalar @fit < 2;
	my $t0 = $fit[0][0];
	my ($n, $sx, $sy, $sxx, $sxy) = (0, 0, 0, 0, 0);
	foreach my $p ( @fit ) {
		my $x = $p->[0] - $t0;
		$n++; $sx += $x; $sy += $p->[1]; $sxx += $x * $x; $sxy += $x * $p->[1];
	}
	my $denom = $n * $sxx - $sx * $sx;
	return (undef, $fit[-1][1], scalar @pts) if $denom == 0;
	my $slope = ($n * $sxy - $sx * $sy) / $denom;
	return ($slope * 86400000, $fit[-1][1], scalar @pts);
}

# A goal read for one circumstance: the target, where the measure stands now, and
# - the part a budget cannot give a scopeless entry - when the current trend
# carries it to the goal. A trend moving the wrong way has no date.
sub goal_reading($app, $circumstance) {
	my $raw = &subs::setting_grabber({ app => $app, setting => 'goals' });
	return undef unless ($raw || '') =~ /\S/;
	my $entry;
	foreach my $e ( split ',', $raw ) {
		my $p = &budget_entry_parse($e);
		if ($p->{'measure'} eq $circumstance) { $entry = $e; last; }
	}
	return undef unless defined $entry;
	my $reading = &budget_calculator({ app => $app, circumstance => $circumstance, budget => $entry });
	my $target = $reading->{'budgeted'};
	my $current = $reading->{'value'};
	my $dir = $reading->{'direction'} || 'floor';
	my ($slope, $last, $samples) = &measure_trend($app, $circumstance, 90);
	my ($eta_days, $reached);
	# a scoped goal is a rate and already has a period pace; the date-to-goal is
	# what a fixed (scopeless) level is missing
	if ($reading->{'fixed'} && defined $target) {
		my $need = ($dir eq 'ceiling') ? ($current - $target) : ($target - $current);
		if ($need <= 0) { $reached = 1; $eta_days = 0; }
		elsif ($slope) {
			my $toward = ($dir eq 'ceiling') ? -$slope : $slope;
			$eta_days = ($toward > 0) ? ($need / $toward) : undef;
		}
	}
	my $eta_text;
	if ($reached) { $eta_text = 'reached'; }
	elsif (defined $eta_days) { $eta_text = localtime((&subs::rightNow() + $eta_days * 86400000) / 1000)->strftime('%b %d, %Y at %l:%M%P'); $eta_text =~ s/\s+/ /g; }
	return {
		entry => $entry,
		direction => $dir,
		target => $target,
		current => $current,
		slope => $slope,
		samples => ($samples || 0),
		eta_days => $eta_days,
		eta_text => $eta_text,
	};
}


sub budget_calculator($data) {
	my $app = $data->{'app'};

	my $circumstance = $data->{'circumstance'};
	# A measure is any circumstance that is not one of the base budget modes,
	# worked out once with a key test that never autovivifies a measure into the
	# modes (which would make this very test, and later ones, read it wrong).
	my $is_measure = ( scalar grep { $_ eq $circumstance } keys %{$gb::budget_modes} ) == 0;
	my $value = $data->{'value'};
	my $scope = $data->{'scope'};
	# the window the reading is for: the caller says when it is one of the blocks
	# before or after now, so a pace is only read off the one now running
	my $ts = $data->{'ts'} || 'this';
	my $settings = $data->{'settings'} || &subs::settings_grabber({ app => $app });
	my $timestamp = $data->{'timestamp'} || &subs::rightNow();
	my $returner = { app => $app, scope_name => &subs::timespan_widener($scope), value => $value };
	my $budget = $data->{'budget'};
	my $server_time = &subs::rightNow();
	$budget = $data->{'budget'} || &subs::setting_grabber({ 'app' => $app, setting => 'budget' }) unless $data->{'budget'} =~ /[0-9]/gi;
	my @budgets = split ',', $budget;
	foreach my $b ( @budgets ) {
		$returner->{'app'} = $app;
		$returner->{'budget'} = $b;
		# A leading "<=" or ">=" says which way the goal runs: under is good (a
		# ceiling, like a weight to hold at or below) or over is good (a floor, like
		# steps to reach). Nothing, and a bare number, is a floor.
		my $direction = 'floor';
		if ($b =~ s/^<=//) { $direction = 'ceiling'; }
		elsif ($b =~ s/^>=//) { $direction = 'floor'; }
		$returner->{'direction'} = $direction;
		my @bud = split '/', $b;
		next unless $bud[-1];
		# No "/scope" is a fixed level, not a rate: a weight sits at a target, it
		# does not accumulate, so it is read against the column's own window and is
		# never prorated (the pace is what made a 160 lb budget project 756 lb).
		my $fixed = scalar(@bud) == 1 ? 1 : 0;
		$returner->{'fixed'} = $fixed;
		if ($fixed) {
			# A fixed entry ("180weight") has no "/scope"; the only scope it can
			# honour is the caller's, and only when it names a time span. The old
			# test accepted any number+letters, so `180weight` became the window
			# `weight`; timespan_widener then stripped the digits and father_time
			# asked time_span for 'weight', which dies and killed every pull after
			# its merge.
			my $window = 'month';
			if ($scope && $scope =~ /^[0-9]*[a-zA-Z]+$/ && &subs::time_span_length($scope)) {
				$window = $scope;
			}
			$window = 1 . $window unless $window =~ /^[0-9]/;
			$returner->{'scope_name'} = &subs::timespan_widener($window);
			$returner->{'duration'} = &subs::time_abbrev_translator($window, $server_time);
			$returner->{'scope'} = $returner->{'duration'};
		}
		else {
			$bud[-1] = 1 . $bud[-1] unless $bud[-1] =~ /[0-9]/;
			# time_span_length knows the word spans; an abbreviated scope ("1w",
			# "3d", "1M") is widened to its word with its count kept first, so a
			# weekly budget is not silently read as a month. A scope that still
			# does not resolve must not reach time_span either.
			unless (&subs::time_span_length($bud[-1])) {
				my $count = $bud[-1];
				$count =~ s/[^0-9]//g;
				$count = 1 unless length $count;
				my $widened = $count . &subs::timespan_widener($bud[-1]);
				$bud[-1] = &subs::time_span_length($widened) ? $widened : '1month';
			}
			$returner->{'scope_name'} = &subs::timespan_widener($bud[-1]);
			$returner->{'duration'} = &subs::time_abbrev_translator($bud[-1],&subs::rightNow());
			# The scope is the column the caller read, not the budget's own period:
			# the value handed in is that column's total, so the target and the actual
			# are held per millisecond of that column. A bare word ("week") needs its
			# count before the translator sees it.
			my $caller_span = $scope ? (($scope =~ /[0-9]/) ? $scope : 1 . $scope) : '';
			unless ($scope) {
				$returner->{'scope'} = $returner->{'duration'} ;
			}
			else {
				$returner->{'scope'} = &subs::time_abbrev_translator($caller_span, &subs::rightNow()) || $returner->{'duration'};
			}
		}
		# A fixed quantity budget is a level to keep on hand, not a rate of the
		# appointment stream (the scoped form reads that stream): read the warehouse's
		# signed stock for the item, so its light says whether the shelf holds what it
		# should.
		my $handled;
		if ($circumstance eq 'quantity' && $fixed) {
			$value = &subs::warehouse_on_hand($app, $settings);
			$returner->{'value'} = $value;
			$handled = 1;
		}
		unless ($value || $handled) {
			my ($db) = &subs::database_grabber();
			my $appts = $data->{'appts'};
			# A duration is read over the budget's own window even when the caller
			# passed the appointments, so a session that crossed the window's edge
			# offers only the time spent inside it.
			my ($window_bt, $window_end);
			if (!$appts || $circumstance eq 'duration') {
				my $ft_data = {
					scope => $returner->{'scope_name'},
					ts => 'this',
					lock => $settings->{'s_lock'},
					timestamp => $timestamp
				};
				($window_bt, $window_end) = &father_time($ft_data);
			}
			unless ($appts) {
				my @params = ( $app, $window_end );
				my $query = 'select * from appointments where app = ? and timestamp < ? ';
				if ($circumstance eq 'duration') {
					# a session overlaps this window when it starts before the window
					# ends and stops after it begins; a running session has no stored
					# duration, so it is read to now and always overlaps a past window
					$query .= "and (timestamp >= ? or type in ('start','record') or (cast(timestamp as integer) + abs(cast(coalesce(duration,0) as real))) > ?) ";
					push @params, $window_bt, $window_bt;
				}
				else {
					$query .= 'and timestamp >= ? ';
					push @params, $window_bt;
				}

				if ($settings->{'s_movement'}) {
					my $bail = 0;
					unless ($settings->{'sss_movement'}) {
						$settings->{'sss_movement'} = eval { return decode_json $settings->{'s_movement'} } || [];
					}
					$bail = 1 if grep { $_ eq 'all' } @{$settings->{'sss_movement'}};
					if ($bail == 0) {
						if (scalar @{$settings->{'sss_movement'}} > 0 ) { $query .= 'and ( '; }
						my $first_movement = 1;
						foreach my $sm ( @{$settings->{'sss_movement'}} ) {
							$query .= $first_movement ? 'type = ? ' : ' or type = ? ';
							$first_movement = 0;
							push @params, $sm;
						}
						if (scalar @{$settings->{'sss_movement'}} > 0 ) { $query .= ' ) '; }
					}
				}
				$query .= ' order by timestamp DESC';
				$appts = &subs::db_query($query, @params)->hashes;
				# a duration list is not reused for the next budget entry, since that
				# entry may name a different window; a caller's own list is left alone
				$data->{'appts'} = $appts unless $circumstance eq 'duration';
			}

			my ($m_sum, $m_count) = (0, 0);
			foreach my $appt ( @{$appts} ) {
				if ($circumstance eq 'duration') {
					if ($appt->{'type'} eq 'start' || $appt->{'type'} eq 'record') {
						$appt->{'duration'} = $server_time - $appt->{'timestamp'};
					}
					my $spent = abs($appt->{'duration'} || 0);
					if (defined $window_bt && defined $window_end) {
						$spent = &appointment_overlap($appt, $window_bt, $window_end);
					}
					$value += $spent;
				}
				elsif ($circumstance eq 'occurences') {
					$value += 1;
				}
				elsif ($circumstance eq 'total') {
					# the block above is only entered when no value was passed in, so
					# there is nothing to guard against here: starting from zero, every
					# row's total is added, the way the display reads the column
					$value += abs( $appt->{'total'} || 0 );
				}
				elsif ($circumstance eq 'quantity') {
					# the stream the app's movement filter names - beer's poured amount,
					# not its purchases - read as a magnitude, the way a total budget
					# reads the money
					$value += abs( $appt->{'quantity'} || 0 );
				}
				else {
					# a measure: sum, or average, it across the window's appointments -
					# the measure decides (steps summed, weight averaged), so its
					# budget reads right whatever the display is showing.
					next unless $appt->{'measures'};
					unless ($appt->{'measured'}) {
						$appt->{'measures'} = eval { return decode_json $appt->{'measures'} } || [];
						$appt->{'measured'} = 'yes';
					}
					foreach my $m ( @{$appt->{'measures'}} ) {
						next unless defined $m->{$circumstance};
						$m_sum += $m->{$circumstance};
						$m_count++;
					}
				}
			}
			# a measure is not a base mode: its value is the summed or averaged
			# measure, per the measure's own calc
			if ($is_measure) {
				# a fixed level (no scope) is a level, so it reads as an average whatever
				# the measure's own calc is; a rate reads with the measure's calc
				my $mcalc = $fixed ? 'average' : &measure_calc_for($app, $circumstance, $settings->{'s_calc'});
				$value = ( $mcalc eq 'average' && $m_count ) ? ($m_sum / $m_count) : $m_sum;
			}
			$value = 0 if scalar @{$appts} == 0;
			$returner->{'value'} = $value;
		}
		if ($bud[0] =~ /^\$/gi) {
			my $bu = $bud[0];
			$bu =~ s/\$//gi;
			$returner->{'budgets'}->{'total'} = $b;
			if ($circumstance eq 'total') {
				$returner->{'circumstance'} = 'total';
				$returner->{'budgeted'} = abs $bu;
				$returner->{'formatted_value'} = abs $value;
				last;
			}
		}
		elsif ($bud[0] =~ /[a-zA-Z]/gi) {

			if ($circumstance eq 'duration') {
				$returner->{'budgets'}->{'duration'} = $b;
				$returner->{'circumstance'} = 'duration';
				$bud[0] = 1 . $bud[0] unless $bud[0] =~ /[0-9]/;
				$returner->{'budgeted'} = &subs::time_abbrev_translator($bud[0],&subs::rightNow());
				if ($value != 0) {
					$returner->{'formatted_value'} = &subs::duration_sayer($value / 1000);
				}
				else {
					$returner->{'formatted_value'} = 0;
				}
				last;
			}
			elsif ($is_measure) {
				$returner->{'budget_name'} = $bud[0];
				$returner->{'budget_name'} =~ s/[0-9.]//gi;
				next unless $returner->{'budget_name'} eq $circumstance;
				$returner->{'budgeted'} = $bud[0];
				$returner->{'budgets'}->{$circumstance} = $b;
				$returner->{'circumstance'} = $circumstance;

				$returner->{'budgeted'} =~ s/[^0-9.]//gi;
				$returner->{'formatted_value'} = sprintf("%.3f", $value) . $circumstance;
				last;
			}
			elsif ($circumstance eq 'quantity') {
				# a quantity budget names itself the way a measure does
				# ("3.400quantity/week"), so a bare number stays an occurences budget
				my $quantity_name = $bud[0];
				$quantity_name =~ s/[^a-zA-Z]//gi;
				next unless $quantity_name eq 'quantity';
				$returner->{'budgets'}->{'quantity'} = $b;
				$returner->{'circumstance'} = 'quantity';
				$returner->{'budgeted'} = $bud[0];
				$returner->{'budgeted'} =~ s/[^0-9.]//gi;
				$returner->{'formatted_value'} = sprintf("%.3f", $value) . $circumstance;
				last;
			}
		}
		else {
			$returner->{'budgets'}->{'occurences'} = $b;

			if ($circumstance eq 'occurences') {
				$returner->{'circumstance'} = 'occurences';
				$returner->{'budgeted'} = $bud[0];
				$returner->{'formatted_value'} = abs $value;
				last;
			}
		}
	}

	if ($returner->{'budget'} && $returner->{'budgeted'}) {
		if ($returner->{'duration'} eq $returner->{'scope'} && $returner->{'circumstance'} eq $circumstance) {
			$returner->{'is_scope'} = 'yes';
		}

		$returner->{'expected'} = sprintf("%.19f",$returner->{'budgeted'} / $returner->{'duration'});
		$returner->{'formatted_budgeted'} = sprintf("%.3f", $returner->{'expected'} * $returner->{'scope'}) . ($is_measure ? $circumstance : '') . '/' . $returner->{'scope_name'};
		$returner->{'formatted_budgeted'} = &subs::duration_sayer($returner->{'expected'} * $returner->{'duration'} / 1000) . '/' . $returner->{'scope_name'} if $circumstance eq 'duration';
		$returner->{'actual'} = sprintf("%.19f", $returner->{'value'} / $returner->{'scope'});
		$returner->{'threshold'} = $returner->{'expected'} * $returner->{'scope'};
		$returner->{'eval'} = $returner->{'actual'} - $returner->{'expected'};
		$returner->{'timestamp'} = $timestamp;
		if ($scope && !$returner->{'fixed'} && $returner->{'scope'} != $returner->{'duration'} && $returner->{'circumstance'} eq $circumstance) {
			# The caller read a column of another width. The reading is still held
			# against that column - the expected and the actual are rates per
			# millisecond, so they compare across windows - but it is not the
			# budget's own period, so the panel must not cache it as one.
			$returner->{'is_scope'} = 'no';
		}
		# A budget locked to the calendar is read against a period still running:
		# on Monday a week holds a seventh of its value, so holding that part against
		# the whole week's target would call an on-pace start a collapse and leave
		# nothing meaningful to read until the week is done. The pace is read
		# instead - the part of the period the moment stands at - and the target is
		# prorated by that same part, so being on track means the value has reached
		# its share of the period so far, and the projection carries the pace to the
		# period's end. An unlocked window rolls a whole period back from now, so it
		# is already run and its pace is 1, as is any block before or after now.
		# Every column is read this way, not only the one the budget is set to: a
		# weekly budget graphed over the month is still a part-run month, and its
		# column reads the same way (the target was scaled to the column above).
		#
		# The first stretch of a period carries no target, since so little is due that
		# a single blip reads as far ahead of pace, and that stretch is often spent
		# asleep or otherwise away from it. The budget is spread over what is left: a
		# day's first two fifths are the night (so its target only starts around nine
		# in the morning), an hour's first quarter, and the longer clocks their first
		# tenth. The projection keeps the exact elapsed, so it still reads the whole
		# period rather than only the part not slept through.
		my %pace_floor = ( hour => 0.25, day => 0.4, week => 0.1, month => 0.1, year => 0.1 );
		my $unit = $scope ? &subs::timespan_widener($scope) : $returner->{'scope_name'};
		my $elapsed = 1;
		if ($ts eq 'this' && ($settings->{'s_lock'} || '') eq 'on' && $unit =~ /^(?:hour|day|week|month|year)$/) {
			(undef, undef, $elapsed) = &subs::period_bounds($unit, $timestamp);
		}
		# a fixed level is not a period being run: it is not prorated, and its pace
		# is not carried anywhere
		$elapsed = 1 if $returner->{'fixed'};
		my $floor = $pace_floor{$unit} // 0.1;
		my $early = ($elapsed > 0 && $elapsed <= $floor) ? 1 : 0;
		my $pace_elapsed = $early ? 0 : (($elapsed - $floor) / (1 - $floor));
		$pace_elapsed = 0 if $pace_elapsed < 0;
		$pace_elapsed = 1 if $pace_elapsed > 1;
		# the whole target the column's value is held against - already scaled to the
		# column's own period when the budget is set to a different one
		my $full_target = $returner->{'expected'} * $returner->{'scope'};
		$returner->{'elapsed'} = $elapsed;
		$returner->{'early'} = $early;
		$returner->{'pace_floor'} = $floor;
		$returner->{'progress'} = sprintf('%.0f', $elapsed * 100);
		$returner->{'on_target'} = sprintf('%.19f', $full_target * $pace_elapsed);
		$returner->{'on_track'} = ($returner->{'value'} >= $returner->{'on_target'}) ? 'yes' : 'no';
		$returner->{'projected'} = $elapsed > 0 ? sprintf('%.19f', $returner->{'value'} / $elapsed) : $returner->{'value'};
		my $pace_format = sub {
			my $n = shift;
			return '-' unless defined $n;
			return &subs::duration_sayer($n / 1000) if $circumstance eq 'duration';
			return &subs::price_formatter($n) if $circumstance eq 'total';
			return sprintf('%.1f', $n);
		};
		$returner->{'formatted_projected'} = $pace_format->($returner->{'projected'});
		$returner->{'formatted_on_target'} = $early ? '0' : $pace_format->($returner->{'on_target'});
		# The status and the graph line are held against the share of the target due
		# by now, not the whole of it, so an on-pace start reads as on pace rather
		# than a collapse; formatted_budgeted still names the whole period.
		$returner->{'full_expected'} = $returner->{'expected'};
		$returner->{'threshold'} = $full_target * $pace_elapsed;
		if ($early) {
			$returner->{'expected'} = 0;
		}
		elsif ($elapsed > 0 && $elapsed < 1 && $returner->{'expected'} > 0) {
			$returner->{'expected'} = sprintf('%.19f', $returner->{'expected'} * $pace_elapsed);
		}
		$returner->{'eval'} = $returner->{'actual'} - $returner->{'expected'};
		$returner = &budget_status_maker($returner);
		# A ceiling reads the mirror of the floor the status table is written for:
		# at or under the target is settled, over it is the alarm. Re-read the status
		# from the value against the target, not from the ratio.
		if (($returner->{'direction'} || 'floor') eq 'ceiling') {
			my $target = $returner->{'budgeted'} || 0;
			my $value = $returner->{'value'} || 0;
			# a hair of float noise either side of the target is still the target
			my $epsilon = $target * .0000000001;
			$returner->{'on_track'} = ($value <= $target + $epsilon) ? 'yes' : 'no';
			my $ceiling = 'budgeted';
			if ($target > 0 && $value > $target * 1.2) { $ceiling = 'overkill'; }
			elsif ($target > 0 && $value > $target + $epsilon) { $ceiling = 'burnt_out'; }
			# landing exactly on the target spends the whole allowance without
			# passing it - an accomplishment, not merely within budget
			elsif ($target > 0 && $value >= $target - $epsilon) { $ceiling = 'accomplished'; }
			$returner = &{$gb::budget_statuses->{$ceiling}->{'notifier'}}($returner);
		}
	}
	else {
	#	$returner = {};
	}
	return $returner;
}


sub budget_status_maker($returner) {
	# a target of nothing - a period only just opened, or a budget of zero - has
	# nothing to fall behind: the value is read as on track, rather than the
	# ratio's 0 >= 0 landing on "overkill"
	if (!defined $returner->{'expected'} || $returner->{'expected'} <= 0) {
		return &{$gb::budget_statuses->{'budgeted'}->{'notifier'}}($returner);
	}
	my $status;
	if ($returner->{'actual'} < $returner->{'expected'} - ( $returner->{'expected'} * .0000000001) && $returner->{'actual'} >= $returner->{'expected'} - ($returner->{'expected'} * .2)) {
		$status = 'budgeted';
		$returner->{'synth'} = 'play -v .3 "| sox -n -p synth .51 sine 391 && play | sox -n -p synth .51 triangle 500"';
	}
	elsif ($returner->{'actual'} >= $returner->{'expected'} * 2) {
		$status = 'overkill';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .51 pinknoise 1125 && play | sox -n -p synth .51 whitenoise 100"';
	}
	elsif ($returner->{'actual'} >= $returner->{'expected'} * 1.2) {
		$status = 'burnt_out';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .51 square 125 && play | sox -n -p synth .51 square 100"';
	}
	elsif ($returner->{'actual'} >= $returner->{'expected'}) {
		$status = 'accomplished';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .26 pluck 329.64 && play | sox -n -p synth .26 pluck 391.99 && play | sox -n -p synth .26 pluck 369.99 && play | sox -n -p synth .26 pluck 293.672"';
	}
	elsif ($returner->{'actual'} <= $returner->{'expected'} / 4) {
		$status = 'abandoned';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .51 triangle 261.64 && play | sox -n -p synth .51 triangle 261.64"';
	}
	elsif ($returner->{'actual'} <= $returner->{'expected'} / 2) {
		$status = 'neglected';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .26 saw 349.23 && play | sox -n -p synth .26 saw 329.63 && play | sox -n -p synth .26 saw 415.3 && play | sox -n -p synth .26 saw 439.99"';
	}
	elsif ($returner->{'actual'} <= $returner->{'expected'}) {
		$status = 'achievable';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .26 pluck 293.67 && play | sox -n -p synth .26 pluck 349.23 && play | sox -n -p synth .26 pluck 349.23 && play | sox -n -p synth .26 pluck 311.13"';
	}
	$returner = &{$gb::budget_statuses->{$status}->{'notifier'}}($returner);

	return $returner;
}

get '/manager/budget/autocalc' => sub($c) {
	my $app = $c->param('app');
	my $timestamp = $c->param('timestamp');
	my $circumstance = $c->param('circumstance');
	&subs::cache_delete({ app => $app, context => 'autocalc', subcontext => $circumstance });
	&subs::cache_delete({ app => $app, context => 'budget', subcontext => $circumstance });
	my $returner = &budget_autocalc({
		app => $app,
		circumstance => $circumstance,
	});
	$c->render(json => $returner );
};

sub budget_autocalc($data) {
	my $app = $data->{'app'};
	my $scope = $data->{'scope'};
	my $circumstance = $data->{'circumstance'};
	my $timestamp = $data->{'timestamp'};
	my $server_time = &subs::rightNow();
	if (my $cache = &subs::cache_get({ app => $app, context => 'autocalc', subcontext => $circumstance })) {
		return $cache;
	}
	my $returner = {
		minute => { symbol => 'm' },
		hour => { symbol => 'h' },
		day => { symbol => 'd' },
		week => { symbol => 'w' },
		month => { symbol => 'M' },
		year => { symbol => 'y' },
	};
	my $settings = &subs::settings_grabber({ app => $app });
	# The six windows this reads, named once so 'data' (added below) is never
	# mistaken for one of them.
	my @windows = keys %{$returner};
	# A measure is any circumstance the base modes do not name (the same test
	# budget_calculator uses), so 'quantity' reads as the base mode it is; a measure
	# reads with its own calc (steps summed, weight averaged).
	my $is_measure = ( scalar grep { $_ eq $circumstance } keys %{$gb::budget_modes} ) == 0;
	my $mcalc = $is_measure ? &measure_calc_for($app, $circumstance, $settings->{'s_calc'}) : undef;
	# The whole history, not the last thousand: a window can reach a year back, and
	# the cap left the long scopes reading only the recent stretch. Read by
	# timestamp (app,timestamp is indexed) and only the columns the sum needs.
	my $cols = 'timestamp,type';
	$cols .= ',duration' if $circumstance eq 'duration';
	$cols .= ',total' if $circumstance eq 'total';
	$cols .= ',quantity' if $circumstance eq 'quantity';
	$cols .= ',measures' if $is_measure;
	my $appts = $data->{'appts'} || &subs::db_query("select $cols from appointments where app = ? order by timestamp ASC", $app)->hashes;
	if ($scope && $timestamp) {
		my $duration = &subs::time_abbrev_translator(1 . $scope, $server_time);
		my $beginning = $server_time - ( $duration * ($settings->{'s_scope_count'} || 1) );
		@{$appts} = grep { $_->{'timestamp'} > $beginning } @{$appts};
	}
	# The app's own movement filter names the stream a budget reads (beer's poured
	# amount, not its purchases), so the recommendation reads that same stream -
	# 'all', or no filter at all, keeps every appointment.
	my $movement = $settings->{'s_movement'} ? ( eval { return decode_json $settings->{'s_movement'} } || [] ) : [];
	if (scalar @{$movement} && !grep { $_ eq 'all' } @{$movement}) {
		my %wanted = map { $_ => 1 } @{$movement};
		@{$appts} = grep { $wanted{ $_->{'type'} || '' } } @{$appts};
	}

	# Sum the value each appointment offers the reading, and note the span it was
	# offered over: the typical amount in a window is that sum spread over the span,
	# so a 'week' reading is what a week holds. An appointment that carries no such
	# measure offers a measure's reading nothing, and does not stretch its span.
	my $total = 0;
	my $samples = 0;
	my ($first, $last);
	foreach my $appt ( @{$appts} ) {
		my ($value, $count) = (0, 0);
		if ($circumstance eq 'occurences') {
			$value = 1;
		}
		elsif ($circumstance eq 'duration') {
			$value = abs( $appt->{'duration'} || 0 );
		}
		elsif ($circumstance eq 'total') {
			$value = $appt->{'total'} + 0;
		}
		elsif ($circumstance eq 'quantity') {
			$value = abs( $appt->{'quantity'} || 0 );
		}
		elsif ($is_measure) {
			next unless $appt->{'measures'};
			unless ($appt->{'measured'}) {
				$appt->{'measures'} = eval { return decode_json $appt->{'measures'} } || [];
				$appt->{'measured'} = 'yes';
			}
			foreach my $m ( @{$appt->{'measures'}} ) {
				next unless defined $m->{$circumstance};
				$value += $m->{$circumstance};
				$count++;
			}
			next unless $count;
		}
		$total += $value;
		$samples += $count;
		my $ts = $appt->{'timestamp'} + 0;
		$first = $ts if !defined $first || $ts < $first;
		$last = $ts if !defined $last || $ts > $last;
	}
	my $span = (defined $first && defined $last) ? ($last - $first) : 0;

	foreach my $r ( @windows ) {
		my $width = &subs::time_abbrev_translator(1 . $returner->{$r}->{'symbol'}, $server_time);
		$returner->{$r}->{'duration'} = $width;
		# The reading is the sum spread over the span, not the average of the
		# overlapping per-appointment windows the walk used to take. That average
		# read the short scopes far too high - a window centred on an appointment
		# is never empty, so the count could not fall below one a window - and the
		# long ones too low, since a window wider than the history can only hold
		# the whole of it. Spreading the sum holds all six scopes in step, which is
		# what a typical scope is.
		my $result;
		if ($is_measure && $mcalc eq 'average') {
			# an averaged measure is a level, not a rate: the reading is the mean of
			# its samples, so it stands the same at every window
			$result = $samples ? ($total / $samples) : 0;
		}
		elsif ($span > 0) {
			$result = $total * $width / $span;
		}
		else {
			# a lone reading (or none) has no span to rate against; it is its own
			# whole history
			$result = $total;
		}
		$returner->{$r}->{'result'} = $result;
		if ($circumstance eq 'occurences') {
			$returner->{$r}->{'formatted_result'} = sprintf("%.3f", $result) . '/' . $r;
		}
		elsif ($circumstance eq 'total') {
			$returner->{$r}->{'formatted_result'} = &subs::price_formatter( $result ) . '/' . $returner->{$r}->{'symbol'};
		}
		elsif ($circumstance eq 'duration') {
			$returner->{$r}->{'formatted_result'} = &subs::duration_sayer($result / 1000) . '/' . $r;
		}
		else {
			$returner->{$r}->{'formatted_result'} = sprintf("%.3f", $result) . $circumstance . '/' . $r;
		}
	}

	$returner->{'data'} = {};

	$returner->{'data'}->{'circumstance'} = $circumstance;
	$returner->{'data'}->{'app'} = $app;
	$returner->{'data'}->{'formatted_app'} = &subs::format_name($app);
	$returner->{'data'}->{'timestamp'} = &subs::rightNow();

	&subs::cache_set({app => $app, context => 'autocalc', subcontext => $circumstance }, $returner);
	return $returner;
}

get '/manager/notifications/list' => sub($c) {
	my $content = &notification_grabber({});
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'notifications', title => 'Notifications', contents => $content },$c->param('timestamp'));
	$c->render(text => $contents);
};

get '/manager/notes' => sub($c) {
	# Every note, newest first: the plain rows subs::voice_note_store and the app's
	# own input write. Notes are no longer appointments - a note is just its text.
	my $notes = &subs::db_query('select text, timestamp, uuid from notes order by timestamp desc limit 300')->hashes;
	my $content = $c->render_to_string(
		template => 'notes/notes',
		notes => $notes
	);
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'notes', title => 'Notes', contents => $content }, $c->param('timestamp'));
	$c->render(text => $contents);
};

get '/manager/camera' => sub($c) {
	# The Camera app: a panel whose buttons drive the app's own camera
	# (window.JawnCamera). In a browser there is no bridge, so the panel says so.
	my $content = $c->render_to_string(template => 'apps/camera');
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'camera', title => 'Camera', contents => $content }, $c->param('timestamp'));
	$c->render(text => $contents);
};

get '/manager/phone' => sub($c) {
	# The Phone app: the house's numbers (known, and the numbers that are only
	# numbers), recent calls (the appointments whose subtype is 'phone'), the desk's
	# blocked numbers, and the dial pad. The pad places a call on a phone
	# (termux-telephony-call); the app's own address book and live call state ride
	# the native JawnContacts bridge.
	my $calls = &subs::db_query('select app,uuid,timestamp,type,duration,account from appointments where subtype=? order by timestamp desc limit 60', 'phone')->hashes;
	my $directory = &phone_directory();
	my $blocked = &phone_blocked();
	my %blocked_number = map { $_->{'number'} => 1 } @{$blocked};
	# a row says so itself when any of its lines is on the desk's list, and each
	# line carries its own reading (the number, its type, whether it is blocked) so
	# the template joins them without walking the tuples itself
	foreach my $r ( @{ $directory->{'known'} }, @{ $directory->{'numbers'} } ) {
		my $any = 0;
		foreach my $l ( @{ $r->{'numbers'} } ) {
			$l->{'blocked'} = $blocked_number{ &ticket_contact_clean('phone', $l->{'value'}) } ? 1 : 0;
			$l->{'display'} = &subs::contact_line_label($l);
			$any = 1 if $l->{'blocked'};
		}
		$r->{'blocked'} = $any;
	}
	my $content = $c->render_to_string(
		template => 'apps/phone',
		calls => $calls,
		known => $directory->{'known'},
		numbers => $directory->{'numbers'},
		blocked => $blocked,
	);
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'phone', title => 'Phone', contents => $content }, $c->param('timestamp'));
	$c->render(text => $contents);
};

# --- People: the house crest -------------------------------------------------
# The first pass owns one crest: the house's own drawing. It is scanned or
# uploaded, normalized and hashed, sealed like a picture, and signed by a house
# key kept sealed under the house key. Other houses' crests and the vouches
# between them come next; nothing here writes a peer row.

sub people_citizen {
	my ($c) = @_;
	return (($c->session('privilege') || '') eq 'citizen') ? 1 : 0;
}

# The social people are settings rows (`pos` or `mab` = person), not the
# `people` table's device accounts. One read builds the whole picture: every
# app's effective construct, the settings uuid each device copy carries, and
# the membership arrays (`sc_<singular>`) those rows already keep. The
# Relational cache is deliberately not reused here: it caches rendered
# buckets, and this index is one small query over rows the window needs fresh.
sub people_index {
	my $rows = eval {
		&subs::db_query("select app, device, setting, value, server_time from settings where setting in ('pos','mab','uuid','house_uuid','house_name','house_pubkey','peer_name','peer_construct','peer_profile','web','crest_uuid') or substr(setting,1,3) = 'sc_'")->hashes;
	} || [];
	my $current = &subs::device_setter();
	my %apps;
	my %uuid_app;
	my %effective;
	foreach my $row ( @{$rows} ) {
		my $app = $row->{'app'} // '';
		next unless length $app;
		my $setting = $row->{'setting'} // '';
		$apps{$app} ||= { app => $app, uuids => {}, sc => {}, pos => '', mab => '', house_uuid => '', house_name => '', peer_name => '', web => '', crest_uuid => '' };
		if ($setting eq 'uuid') {
			my $uuid = $row->{'value'} // '';
			next unless length $uuid;
			$apps{$app}->{'uuids'}->{$uuid} = 1;
			$apps{$app}->{'uuid_rows'}->{$uuid} = {
				device => $row->{'device'} // '',
				server_time => $row->{'server_time'} // '',
			};
			$uuid_app{$uuid} = $app;
		}
		elsif ($setting eq 'pos' || $setting eq 'mab') {
			# a device keeps its own copy of a construct; the newest row on a
			# device is that device's answer, and the current device answers
			# for the whole app when it has one
			my $device = $row->{'device'} // '';
			my $stamp = $row->{'server_time'} // '';
			my $slot = $effective{$app}->{$setting}->{$device};
			unless ($slot && $slot->{'server_time'} gt $stamp) {
				$effective{$app}->{$setting}->{$device} = { value => $row->{'value'} // '', server_time => $stamp };
			}
		}
		elsif ($setting eq 'house_uuid' || $setting eq 'house_name' || $setting eq 'peer_name' || $setting eq 'web' || $setting eq 'crest_uuid') {
			# provenance of an imported construct; a local construct has none
			$apps{$app}->{$setting} = $row->{'value'} // '';
		}
		elsif ($setting =~ /^sc_(.+)$/) {
			my $sing = $1;
			my $list = eval { decode_json($row->{'value'} // '') } || [];
			next unless ref $list eq 'ARRAY';
			foreach my $uuid ( @{$list} ) {
				next unless defined $uuid && length $uuid;
				$apps{$app}->{'sc'}->{$sing}->{$uuid} = 1;
			}
		}
	}
	foreach my $app ( keys %apps ) {
		foreach my $setting ( qw/pos mab/ ) {
			my $devices = $effective{$app}->{$setting} || {};
			my $pick = $devices->{$current};
			unless ($pick) {
				foreach my $device ( keys %{$devices} ) {
					my $candidate = $devices->{$device};
					$pick = $candidate if !$pick || $candidate->{'server_time'} gt $pick->{'server_time'};
				}
			}
			$apps{$app}->{$setting} = $pick ? $pick->{'value'} : '';
		}
		# the row this machine writes to: its own device's copy when there is
		# one, otherwise the newest copy another machine made
		my $preferred = '';
		my $newest = '';
		my $newest_stamp = '';
		foreach my $uuid ( keys %{ $apps{$app}->{'uuid_rows'} || {} } ) {
			my $entry = $apps{$app}->{'uuid_rows'}->{$uuid};
			if (($entry->{'device'} || '') eq $current) { $preferred = $uuid; last; }
			if (!$newest || ($entry->{'server_time'} || '') gt $newest_stamp) {
				$newest = $uuid;
				$newest_stamp = $entry->{'server_time'} || '';
			}
		}
		$apps{$app}->{'preferred_uuid'} = $preferred || $newest || '';
	}
	# a membership array names the uuid of the construct's settings row, so
	# the reverse map is what turns "these uuids" into "these construct apps"
	my %member;
	foreach my $app ( keys %apps ) {
		my $sc = $apps{$app}->{'sc'} || {};
		foreach my $sing ( keys %{$sc} ) {
			foreach my $uuid ( keys %{$sc->{$sing}} ) {
				my $construct_app = $uuid_app{$uuid};
				next unless defined $construct_app;
				$member{$sing}->{$construct_app}->{$app} = 1;
			}
		}
	}
	my @person_apps = sort grep {
		my $entry = $apps{$_};
		(($entry->{'pos'} || '') eq 'person' || ($entry->{'mab'} || '') eq 'person') ? 1 : 0;
	} keys %apps;
	my @constructs;
	foreach my $scons ( sort { $a->{'order'} <=> $b->{'order'} } values %{$gb::social_constructs} ) {
		next if $scons->{'name'} eq 'people';
		my $sing = $scons->{'sing'};
		my @rows;
		foreach my $app ( keys %apps ) {
			my $entry = $apps{$app};
			next unless (($entry->{'pos'} || '') eq $sing || ($entry->{'mab'} || '') eq $sing);
			my @members;
			foreach my $member_app ( keys %{ $member{$sing}->{$app} || {} } ) {
				push @members, { app => $member_app, name => &subs::format_name($member_app) };
			}
			@members = sort { lc($a->{'name'}) cmp lc($b->{'name'}) } @members;
			push @rows, {
				app => $app,
				name => $entry->{'peer_name'} || &subs::format_name($app),
				foreign => ($entry->{'house_uuid'} || '') ne '' ? 1 : 0,
				house_uuid => $entry->{'house_uuid'} || '',
				house_name => $entry->{'house_name'} || '',
				web => $entry->{'web'} || '',
				crest_uuid => $entry->{'crest_uuid'} || '',
				member_count => scalar @members,
				members => \@members,
			};
		}
		@rows = sort { lc($a->{'name'}) cmp lc($b->{'name'}) } @rows;
		push @constructs, { name => $scons->{'name'}, sing => $sing, rows => \@rows };
	}
	return {
		apps => \%apps,
		uuid_app => \%uuid_app,
		member => \%member,
		person_apps => \@person_apps,
		constructs => \@constructs,
	};
}

# Keep the people table and the person constructs in step. A person construct
# creates its people row; a row whose construct was deleted from the database
# is removed; a construct that merely changed away from person (to idea, say)
# keeps its row, so a mistaken change does not cost the identity behind it.
sub people_link_sync {
	my $index = &people_index();
	my %person = map { $_ => 1 } @{ $index->{'person_apps'} };
	my %known = map { $_ => 1 } keys %{ $index->{'apps'} };
	my $now = &subs::rightNow();
	my $rows = eval { &subs::db_select('people', undef, {})->hashes } || [];
	my %have;
	foreach my $person ( @{$rows} ) {
		my $app = $person->{'app'} // '';
		next unless length $app;
		$have{$app} = 1;
		if ($person{$app}) {
			unless (($person->{'status'} || '') eq 'active') {
				&subs::db_update('people', { status => 'active', server_time => $now }, { uuid => $person->{'uuid'} });
			}
		}
		elsif (!$known{$app}) {
			# every settings row for that app is gone, so the construct was
			# removed rather than reclassified
			&subs::db_update('people', { status => 'removed', server_time => $now }, { uuid => $person->{'uuid'} });
		}
	}
	foreach my $app ( keys %person ) {
		next if $have{$app};
		&subs::db_insert('people', {
			uuid => &subs::random_string_creator(25),
			app => $app,
			name => &subs::format_name($app),
			privilege => '',
			status => 'active',
			created => $now,
			server_time => $now,
		});
	}
	return $index;
}

# The construct chips a person wears: each membership array names a construct
# app's settings uuid, and the index's reverse map names the app itself.
sub people_chips {
	my ($index, $app) = @_;
	my $entry = $index->{'apps'}->{$app} || {};
	my $sc = $entry->{'sc'} || {};
	my @chips;
	foreach my $scons ( sort { $a->{'order'} <=> $b->{'order'} } values %{$gb::social_constructs} ) {
		my $sing = $scons->{'sing'};
		next unless $sc->{$sing};
		my %seen;
		my @names;
		foreach my $uuid ( keys %{ $sc->{$sing} } ) {
			my $construct_app = $index->{'uuid_app'}->{$uuid} || '';
			next unless length $construct_app;
			next if $seen{$construct_app}++;
			push @names, { app => $construct_app, name => &subs::format_name($construct_app) };
		}
		foreach my $name ( sort { lc($a->{'name'}) cmp lc($b->{'name'}) } @names ) {
			push @chips, {
				construct => $scons->{'name'},
				sing => $sing,
				label => &subs::lang('construct.' . $scons->{'name'}),
				app => $name->{'app'},
				name => $name->{'name'},
			};
		}
	}
	return \@chips;
}

# The peer crest linked to a contact app, as an image the window can show.
sub people_crest_image {
	my ($app) = @_;
	return &people_crest_entry_image(&subs::crest_contact_entry($app));
}

sub people_crest_entry_image {
	my ($entry) = @_;
	return '' unless $entry && ref $entry->{'crest'} eq 'HASH';
	return $entry->{'image_data'} if defined $entry->{'image_data'} && length $entry->{'image_data'};
	my $uuid = $entry->{'crest'}->{'uuid'} || '';
	return '' unless length $uuid;
	return &subs::crest_peer_image_file($entry) ? '/manager/people/crest_image?peer=' . $uuid . '&stamp=' . &subs::rightNow() : '';
}

# The person's own picture. The main_image setting is written per device and
# may be a sealed path or (on a phone) a data URI; /file_open is what unfastens
# a sealed picture for an <img>, and it takes the app alongside the path.
sub people_main_image {
	my ($app) = @_;
	return '' unless defined $app && length $app;
	my $row = eval { &subs::db_query("select value from settings where app=? and setting='main_image' and value<>'' order by server_time desc limit 1", $app)->hashes->[0] };
	return '' unless $row && length($row->{'value'} || '');
	my $value = $row->{'value'};
	return $value if $value =~ /^data:image\//i;
	return '/file_open?file=' . &subs::url_escape_utf8($value) . '&app=' . &subs::url_escape_utf8($app) . '&thumb=ya&timestamp=' . &subs::rightNow();
}

# Met / introduced state for a linked crest, read the same way the crest
# detail panel reads it.
sub people_crest_state {
	my ($entry) = @_;
	my $own = &subs::crest_record_read();
	my $incoming = ref $entry->{'crest'} eq 'HASH' ? $entry->{'crest'} : {};
	my $state = { met => 0, met_at => '', introduced_by => '' };
	if (ref $entry->{'vouch'} eq 'HASH'
		&& &subs::crest_vouch_verify($entry->{'vouch'})
		&& ($entry->{'vouch'}->{'from_uuid'} || '') eq ($own->{'uuid'} || '')
		&& ($entry->{'vouch'}->{'to_uuid'} || '') eq ($incoming->{'uuid'} || '')
		&& ($entry->{'vouch'}->{'to_pubkey'} || '') eq ($incoming->{'pubkey'} || '')) {
		$state->{'met'} = 1;
		$state->{'met_at'} = $entry->{'vouch'}->{'at'} || $entry->{'met_at'} || '';
	}
	my $peer_list = &subs::crest_peer_list_read();
	foreach my $vouch ( @{ $entry->{'vouches'} || [] } ) {
		next unless ref $vouch eq 'HASH';
		next unless ($vouch->{'to_uuid'} || '') eq ($incoming->{'uuid'} || '');
		next unless ($vouch->{'to_pubkey'} || '') eq ($incoming->{'pubkey'} || '');
		my $issuer = &subs::crest_vouch_introducer($vouch, $own, $peer_list);
		next unless $issuer;
		next if ($issuer->{'uuid'} || '') eq ($own->{'uuid'} || '');
		$state->{'introduced_by'} = $issuer->{'name'} || '';
		last;
	}
	return $state;
}

sub people_crest_scan_dir {
	my $folder = &subs::setting_grabber({ app => 'misc', setting => 'scan_location', device => &subs::device_setter() }) || 'Scans';
	my $dir = &subs::home($folder) . '/people';
	unless (-d $dir) { eval { require File::Path; File::Path::make_path($dir) }; }
	return $dir;
}

# The singular a construct app answers to ('community', 'team', ...), or empty
# when the app is not a construct of this house.
sub people_construct_kind {
	my ($app) = @_;
	return '' unless defined $app && length $app;
	foreach my $construct ( @{ &people_index()->{'constructs'} } ) {
		foreach my $row ( @{ $construct->{'rows'} } ) {
			next if $row->{'foreign'};
			return $construct->{'sing'} if ($row->{'app'} || '') eq $app;
		}
	}
	return '';
}

# True when this app is another house's construct, imported read-only. A local
# construct has no house_uuid; the marker is what keeps publication, logos and
# Relational edits away from something this house does not own.
sub people_app_foreign {
	my ($app) = @_;
	return 0 unless defined $app && length $app;
	my $house = &subs::setting_grabber({ app => $app, setting => 'house_uuid', device => 'all' });
	return (defined $house && length $house) ? 1 : 0;
}

sub construct_crest_find_by_uuid {
	my ($uuid) = @_;
	return undef unless defined $uuid && length $uuid;
	foreach my $construct ( @{ &people_index()->{'constructs'} } ) {
		foreach my $row ( @{ $construct->{'rows'} } ) {
			my $crest = &subs::construct_crest_record_read($row->{'app'});
			if (($crest->{'uuid'} || '') ne $uuid && $row->{'foreign'} && ($row->{'crest_uuid'} || '') eq $uuid) {
				# an imported construct keeps its signed record, not a local crest
				my $raw = &subs::setting_grabber({ app => $row->{'app'}, setting => 'peer_construct', device => 'all' });
				$crest = eval { decode_json($raw) } || {};
			}
			next unless ($crest->{'uuid'} || '') eq $uuid;
			return {
				app => $row->{'app'},
				crest => $crest,
				type => $construct->{'name'},
				sing => $construct->{'sing'},
				foreign => $row->{'foreign'} || 0,
			};
		}
	}
	return undef;
}

# A construct is published to another house only when its own public setting
# says so. The setting is kept per device, like the public toggle on the
# appointment itself, and People consolidates the rows it holds: the newest
# choice across the house is the answer the construct row shows and the answer
# a lookup carries.
sub people_construct_public {
	my ($app) = @_;
	return 0 unless defined $app && length $app;
	my $row = eval { &subs::db_query("select value from settings where app=? and setting='public' order by server_time desc limit 1", $app)->hashes->[0] };
	return ($row && ($row->{'value'} || '') eq 'on') ? 1 : 0;
}

# Import another house's construct as settings rows this house can read but not
# change. Its identity is the signed construct crest (uuid + house uuid); the
# local app key is only a label, suffixed when the name is already taken. The
# house crest must already be held: a construct is only trustworthy as part of
# a house this machine knows.
sub foreign_construct_import {
	my ($record) = @_;
	return { ok => 0, error => 'no construct crest' }
		unless ref $record eq 'HASH' && ($record->{'uuid'} || '') ne '';
	return { ok => 0, error => 'that is not a construct crest' }
		unless length($record->{'construct'} || '');
	return { ok => 0, error => 'the construct crest does not verify' }
		unless &subs::crest_verify_record($record);
	my $house_uuid = $record->{'house_uuid'} || '';
	my $house_pub = $record->{'house_pubkey'} || $record->{'pubkey'} || '';
	return { ok => 0, error => 'the construct crest names no house' }
		unless length($house_uuid) && length($house_pub);
	my $own = &subs::crest_record_read();
	return { ok => 0, error => 'that is this house\'s own construct' }
		if ($own->{'uuid'} || '') eq $house_uuid;
	my $entry = &subs::crest_peer_find($house_uuid);
	my $house_crest = $entry ? ($entry->{'crest'} || {}) : undef;
	return { ok => 0, error => 'import that house\'s crest first' }
		unless $house_crest && (($house_crest->{'pubkey'} || '') eq $house_pub);
	my $sing = $record->{'construct_type'} || '';
	my %sings = map { $_->{'sing'} => 1 } values %{$gb::social_constructs};
	return { ok => 0, error => 'the construct crest has no known kind' } unless $sings{$sing};
	my $their_name = $record->{'name'} || &subs::format_name($record->{'construct'});
	my $house_name = $house_crest->{'name'} || '';
	my $index = &people_index();
	my $app = '';
	foreach my $construct ( @{ $index->{'constructs'} || [] } ) {
		foreach my $row ( @{ $construct->{'rows'} || [] } ) {
			next unless $row->{'foreign'};
			next unless ($row->{'crest_uuid'} || '') eq $record->{'uuid'};
			$app = $row->{'app'};
			last;
		}
		last if length $app;
	}
	unless (length $app) {
		my %taken = map { $_ => 1 } keys %{ $index->{'apps'} || {} };
		my $base = &subs::unformat_name($record->{'construct'} || $their_name);
		$base = 'construct' unless length $base;
		$app = $base;
		if ($taken{$app}) {
			$app = $base . '_' . substr($house_uuid, 0, 6);
			my $n = 2;
			while ($taken{$app}) { $app = $base . '_' . substr($house_uuid, 0, 6) . '_' . $n++; }
		}
	}
	my %set = (
		pos => $sing,
		construct_uuid => $record->{'uuid'},
		crest_uuid => $record->{'uuid'},
		house_uuid => $house_uuid,
		house_pubkey => $house_pub,
		house_name => $house_name,
		peer_name => $their_name,
		peer_construct => encode_json($record),
	);
	my $origin = $record->{'origin'} || $house_crest->{'origin'} || &subs::crest_entry_origin({ crest => $house_crest, endpoints => $house_crest->{'endpoints'} });
	$origin =~ s{/+$}{};
	$set{'web'} = $origin if $origin =~ m{^https?://[A-Za-z0-9.:\[\]-]+$};
	foreach my $setting ( keys %set ) {
		&subs::setting_setter({ app => $app, setting => $setting, device => 'all', value => $set{$setting} });
	}
	return {
		ok => 1,
		app => $app,
		name => $their_name,
		house_name => $house_name,
		house_uuid => $house_uuid,
	};
}

# What this house publishes to another house that presents a crest: the house
# name and key, its address, and only the constructs marked public, with the
# names of their members. Nothing here is a permission; the answer is signed by
# the house key so the asker can check it came from the crest it holds.
sub people_crest_profile {
	my $crest = &subs::crest_record_read();
	return undef unless $crest->{'uuid'} && $crest->{'pubkey'};
	my $suds = &subs::suds_grabber();
	my $priv = $suds ? &subs::crest_key_read($suds) : undef;
	return undef unless defined $priv && length $priv == 32;
	my $index = &people_index();
	my @constructs;
	foreach my $construct ( @{ $index->{'constructs'} } ) {
		foreach my $row ( @{ $construct->{'rows'} } ) {
			my $app = $row->{'app'} || '';
			next unless length $app;
			# another house's construct is not ours to publish
			next if $row->{'foreign'};
			next unless &people_construct_public($app);
			push @constructs, {
				type => $construct->{'name'},
				name => &subs::format_name($app),
				members => [ map { $_->{'name'} } @{ $row->{'members'} || [] } ],
			};
		}
	}
	@constructs = sort { lc($a->{'name'}) cmp lc($b->{'name'}) } @constructs;
	my $profile = {
		format => 'jawnos-crest-profile',
		profile_version => 1,
		uuid => $crest->{'uuid'},
		name => $crest->{'name'} || '',
		fingerprint => $crest->{'fingerprint'} || '',
		pubkey => $crest->{'pubkey'},
		origin => &subs::crest_origin(),
		issued => &subs::rightNow(),
		constructs => \@constructs,
		# the machines that back this crest, named by their own signatures; the
		# full statements travel on the card, this list is what a lookup shows
		cosignatures => [ map {
			{ signatorial => $_->{'signatorial'}, hostname => $_->{'hostname'}, at => $_->{'at'} }
		} @{ &subs::crest_member_cosig_list($crest, { include_local => 1 }) } ],
	};
	return &subs::crest_sign_record($profile, $priv);
}

# The public door another house knocks on. The caller shows its own crest the way
# a visitor shows a card; a crest proves only that a house is asking, so no
# trust follows from it. Refused unless the uuid in the path is this house - a
# machine cannot answer for a crest it does not hold.
get '/crest/:uuid/profile' => sub($c) {
	my $uuid = $c->param('uuid') || '';
	my $crest = &subs::crest_record_read();
	unless ($crest->{'uuid'} && length $uuid && $uuid eq $crest->{'uuid'}) {
		$c->render(json => { ok => 0, error => 'no such crest here' });
		return;
	}
	my $code = $c->param('code') || '';
	my $asker = length $code ? &subs::crest_code_parse($code) : undef;
	unless ($asker && &subs::crest_verify_record($asker)) {
		$c->render(json => { ok => 0, error => 'a crest is required to look this house up' });
		return;
	}
	my $profile = &people_crest_profile();
	unless ($profile) {
		$c->render(json => { ok => 0, error => 'this house cannot sign its profile' });
		return;
	}
	$c->render(json => { ok => 1, profile => $profile });
};

sub people_crest_install {
	my ($c, $src) = @_;
	my $suds = &subs::session_suds($c);
	return { ok => 0, error => 'the house key is not available' } unless $suds;
	my $device = &subs::device_setter();
	my $folder = &subs::setting_grabber({ app => 'misc', setting => 'photo_location', device => $device }) || 'Pictures';
	my $dir = &subs::home($folder) . '/me';
	unless (-d $dir) { eval { require File::Path; File::Path::make_path($dir) }; }
	my $old = &subs::crest_record_read();
	my $version = (($old->{'version'} || 0) + 1);
	my $color_png = "$dir/crest.v$version.color.png";
	my $ref_png = "$dir/crest.v$version.ref.png";
	my $rc = system('magick', $src, $color_png);
	unless ($rc == 0 && -e $color_png && -s $color_png > 0) {
		unlink $color_png;
		return { ok => 0, error => 'the picture could not be read' };
	}
	unless (&subs::crest_normalize_image($color_png, $ref_png)) {
		unlink $color_png; unlink $ref_png;
		return { ok => 0, error => 'the picture could not be normalized' };
	}
	my $dhash = &subs::crest_dhash($ref_png);
	my $sha = &subs::crest_sha256_file($ref_png);
	unless (defined $dhash && defined $sha) {
		unlink $color_png; unlink $ref_png;
		return { ok => 0, error => 'the picture could not be hashed' };
	}
	my $standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard', device => $device }) || 'aes-256-ctr';
	my $color_name = "crest.v$version.color.png.enc";
	my $ref_name = "crest.v$version.ref.png.enc";
	my $color_enc = "$dir/$color_name";
	my $ref_enc = "$dir/$ref_name";
	unless (&subs::openssl_file_crypt('e', $standard, $suds, $color_png, $color_enc, 0, 1)
		&& &subs::openssl_file_crypt('e', $standard, $suds, $ref_png, $ref_enc, 0, 1)) {
		unlink $color_png; unlink $ref_png; unlink $color_enc; unlink $ref_enc;
		return { ok => 0, error => 'the picture could not be sealed' };
	}
	unlink $color_png; unlink $ref_png;
	my $priv = &subs::crest_key_read($suds);
	my $pub;
	if (defined $priv && length $priv == 32) {
		$pub = &subs::crest_public_from_private($priv);
	}
	elsif ($old->{'uuid'}) {
		# A record already names a house key. Minting a new one here would turn
		# the house into a stranger without anyone asking; refuse instead.
		return { ok => 0, error => 'the crest key could not be opened; the house identity was left unchanged' };
	}
	else {
		($pub, $priv) = &subs::crest_key_generate();
		unless (defined $pub && defined $priv) {
			return { ok => 0, error => 'the crest key could not be made' };
		}
		unless (&subs::crest_key_write($suds, $priv)) {
			return { ok => 0, error => 'the crest key could not be stored' };
		}
	}
	my $record = {
		uuid => $old->{'uuid'} || &subs::random_string_creator(32),
		house_id => $old->{'house_id'} || &subs::random_string_creator(24),
		name => $old->{'name'} || &subs::crest_house_name_read(),
		pubkey => encode_base64($pub, ''),
		fingerprint => &subs::crest_fingerprint($pub),
		dhash => $dhash,
		sha256 => $sha,
		image => $color_name,
		reference => $ref_name,
		version => $version,
		issued => $old->{'issued'} || &subs::rightNow(),
		server_time => &subs::rightNow(),
		device => $device,
		origin => &subs::crest_origin(),
		members => $old->{'members'} || [ { signatorial => &subs::signatorial_designer(), device => $device } ],
	};
	my $signed = &subs::crest_sign_record($record, $priv);
	unless ($signed && $signed->{'sig'}) {
		return { ok => 0, error => 'the crest could not be signed' };
	}
	unless (&subs::crest_record_write($signed)) {
		return { ok => 0, error => 'the crest could not be saved' };
	}
	my $sync_image = &subs::crest_image_data_uri($color_enc, $suds, $standard, 512);
	&subs::crest_image_sync_store($signed, $sync_image) if defined $sync_image;
	return { ok => 1, crest => $signed };
}

# A construct's crest: the same signed record, card and compact code as the
# house crest, signed by the house key and naming the construct. It lives on the
# construct's own settings rows, so deleting the construct takes its crest with
# it. The drawing is stored beside the house drawing with a name only this
# construct's id makes, so the two never collide.
sub construct_crest_install {
	my ($c, $src, $app) = @_;
	my $sing = &people_construct_kind($app);
	return { ok => 0, error => 'no such construct' } unless $sing;
	my $suds = &subs::session_suds($c);
	return { ok => 0, error => 'the house key is not available' } unless $suds;
	my $priv = &subs::crest_key_read($suds);
	unless (defined $priv && length $priv == 32) {
		return { ok => 0, error => 'the house crest key is not available' };
	}
	my $house = &subs::crest_record_read();
	unless ($house->{'uuid'} && $house->{'pubkey'}) {
		return { ok => 0, error => 'make the house crest first' };
	}
	my $device = &subs::device_setter();
	my $folder = &subs::setting_grabber({ app => 'misc', setting => 'photo_location', device => $device }) || 'Pictures';
	my $dir = &subs::home($folder) . '/me';
	unless (-d $dir) { eval { require File::Path; File::Path::make_path($dir) }; }
	my $old = &subs::construct_crest_record_read($app);
	my $version = (($old->{'version'} || 0) + 1);
	my $uuid = $old->{'uuid'} || &subs::random_string_creator(32);
	my $color_png = "$dir/crest-$uuid.v$version.color.png";
	my $ref_png = "$dir/crest-$uuid.v$version.ref.png";
	my $rc = system('magick', $src, $color_png);
	unless ($rc == 0 && -e $color_png && -s $color_png > 0) {
		unlink $color_png;
		return { ok => 0, error => 'the picture could not be read' };
	}
	unless (&subs::crest_normalize_image($color_png, $ref_png)) {
		unlink $color_png; unlink $ref_png;
		return { ok => 0, error => 'the picture could not be normalized' };
	}
	my $dhash = &subs::crest_dhash($ref_png);
	my $sha = &subs::crest_sha256_file($ref_png);
	unless (defined $dhash && defined $sha) {
		unlink $color_png; unlink $ref_png;
		return { ok => 0, error => 'the picture could not be hashed' };
	}
	my $standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard', device => $device }) || 'aes-256-ctr';
	my $color_name = "crest-$uuid.v$version.color.png.enc";
	my $ref_name = "crest-$uuid.v$version.ref.png.enc";
	my $color_enc = "$dir/$color_name";
	my $ref_enc = "$dir/$ref_name";
	unless (&subs::openssl_file_crypt('e', $standard, $suds, $color_png, $color_enc, 0, 1)
		&& &subs::openssl_file_crypt('e', $standard, $suds, $ref_png, $ref_enc, 0, 1)) {
		unlink $color_png; unlink $ref_png; unlink $color_enc; unlink $ref_enc;
		return { ok => 0, error => 'the picture could not be sealed' };
	}
	unlink $color_png; unlink $ref_png;
	my $record = {
		uuid => $uuid,
		construct => $app,
		construct_type => $sing,
		name => $old->{'name'} || &subs::format_name($app),
		pubkey => $house->{'pubkey'},
		house_uuid => $house->{'uuid'},
		house_pubkey => $house->{'pubkey'},
		dhash => $dhash,
		sha256 => $sha,
		image => $color_name,
		reference => $ref_name,
		version => $version,
		issued => $old->{'issued'} || &subs::rightNow(),
		server_time => &subs::rightNow(),
		device => $device,
		origin => &subs::crest_origin(),
	};
	$record->{'fingerprint'} = &subs::construct_crest_fingerprint($record);
	my $signed = &subs::crest_sign_record($record, $priv);
	unless ($signed && $signed->{'sig'}) {
		return { ok => 0, error => 'the crest could not be signed' };
	}
	unless (&subs::construct_crest_record_write($app, $signed)) {
		return { ok => 0, error => 'the crest could not be saved' };
	}
	my $sync_image = &subs::crest_image_data_uri($color_enc, $suds, $standard, 512);
	&subs::construct_crest_image_sync_store($app, $signed, $sync_image) if defined $sync_image;
	return { ok => 1, crest => $signed, app => $app };
}

sub people_crest_upload_file {
	my ($c) = @_;
	my @uploads = @{ $c->req->uploads || [] };
	return (undef, 'no picture') unless @uploads;
	require File::Temp;
	my ($fh, $path) = File::Temp::tempfile('jawnos-crest-XXXXXX', TMPDIR => 1, UNLINK => 0, SUFFIX => '.img');
	return (undef, 'no temporary file') unless $fh && $path;
	binmode $fh;
	print $fh $uploads[0]->asset->slurp;
	close $fh;
	return ($path, undef);
}

get '/manager/people' => sub($c) {
	unless (&people_citizen($c)) { $c->render(text => ''); return; }
	&subs::crest_image_sync_seed($c);
	&subs::crest_image_materialize($c);
	my $crest = &subs::crest_record_read();
	my $has_image = ($crest->{'uuid'} && &subs::crest_image_file($crest, 'image')) ? 1 : 0;
	my $peer_list = &subs::crest_peer_list_read();
	my @peers;
	foreach my $entry ( @{$peer_list} ) {
		next unless ref $entry eq 'HASH' && ref $entry->{'crest'} eq 'HASH';
		my $incoming = $entry->{'crest'};
		next unless ($incoming->{'uuid'} || '') ne '';
		my $view = {
			uuid => $incoming->{'uuid'},
			crest => $incoming,
			name => $incoming->{'name'} || '',
			fingerprint => $incoming->{'fingerprint'} || '',
			has_image => ((defined $entry->{'image_data'} && length $entry->{'image_data'}) || &subs::crest_peer_image_file($entry)) ? 1 : 0,
			image_src => (defined $entry->{'image_data'} && length $entry->{'image_data'}) ? $entry->{'image_data'} : (&subs::crest_peer_image_file($entry) ? '/manager/people/crest_image?peer=' . $incoming->{'uuid'} . '&stamp=' . &subs::rightNow() : ''),
			met => 0,
			met_at => '',
			introduced_by => '',
		};
		if (ref $entry->{'vouch'} eq 'HASH'
			&& &subs::crest_vouch_verify($entry->{'vouch'})
			&& ($entry->{'vouch'}->{'from_uuid'} || '') eq ($crest->{'uuid'} || '')
			&& ($entry->{'vouch'}->{'to_uuid'} || '') eq $incoming->{'uuid'}
			&& ($entry->{'vouch'}->{'to_pubkey'} || '') eq ($incoming->{'pubkey'} || '')) {
			$view->{'met'} = 1;
			$view->{'met_at'} = $entry->{'vouch'}->{'at'} || $entry->{'met_at'} || '';
		}
		foreach my $vouch ( @{ $entry->{'vouches'} || [] } ) {
			next unless ref $vouch eq 'HASH';
			next unless ($vouch->{'to_uuid'} || '') eq $incoming->{'uuid'};
			next unless ($vouch->{'to_pubkey'} || '') eq ($incoming->{'pubkey'} || '');
			my $issuer = &subs::crest_vouch_introducer($vouch, $crest, $peer_list);
			next unless $issuer;
			next if ($issuer->{'uuid'} || '') eq ($crest->{'uuid'} || '');
			$view->{'introduced_by'} = $issuer->{'name'} || '';
			last;
		}
		push @peers, $view;
	}
	@peers = sort { lc($a->{'name'} || '') cmp lc($b->{'name'} || '') } @peers;
	my $crest_introduced_by = '';
	foreach my $vouch ( @{ &subs::crest_incoming_vouch_list_read() } ) {
		next unless ref $vouch eq 'HASH';
		next unless ($vouch->{'to_uuid'} || '') eq ($crest->{'uuid'} || '');
		next unless ($vouch->{'to_pubkey'} || '') eq ($crest->{'pubkey'} || '');
		my $issuer = &subs::crest_vouch_introducer($vouch, $crest, $peer_list);
		next unless $issuer;
		next if ($issuer->{'uuid'} || '') eq ($crest->{'uuid'} || '');
		$crest_introduced_by = $issuer->{'name'} || '';
		last;
	}
	my $index = &people_link_sync();
	my $backers = &subs::crest_member_cosig_list($crest);
	my %person_app = map { $_ => 1 } @{ $index->{'person_apps'} };
	my $people_rows = eval { &subs::db_select('people', undef, { status => 'active' })->hashes } || [];
	my @people;
	my %seen_person_app;
	foreach my $person ( @{$people_rows} ) {
		my $app = $person->{'app'} // '';
		next unless length $app;
		next unless $person_app{$app};
		# two machines can mint a row for the same construct before they sync;
		# the window shows the person once
		next if $seen_person_app{$app}++;
		$person->{'chips'} = &people_chips($index, $app);
		$person->{'image'} = &people_crest_image($app);
		$person->{'formatted_name'} = &subs::format_name($app);
		push @people, $person;
	}
	@people = sort { lc($a->{'name'} || '') cmp lc($b->{'name'} || '') } @people;
	my %people_by_app = map { ($_->{'app'} || '') => ($_->{'uuid'} || '') } @people;
	# the words the Guide already knows this construct by, shown as chips on its
	# row; a foreign construct's names are its own house's, so it gets none
	my $aka_by_app = &guide_aka_read();
	foreach my $construct ( @{ $index->{'constructs'} } ) {
		foreach my $row ( @{ $construct->{'rows'} } ) {
			$row->{'aka'} = $row->{'foreign'} ? [] : [ @{ $aka_by_app->{ $row->{'app'} } || [] } ];
			$row->{'image'} = &people_crest_image($row->{'app'});
			$row->{'public'} = $row->{'foreign'} ? 0 : &people_construct_public($row->{'app'});
			$row->{'crest_uuid'} = '';
			$row->{'crest_image'} = '';
			unless ($row->{'foreign'}) {
				my $construct_crest = &subs::construct_crest_record_read($row->{'app'});
				if ($construct_crest->{'uuid'}) {
					&subs::construct_crest_image_materialize($c, $row->{'app'});
					$row->{'crest_uuid'} = $construct_crest->{'uuid'};
					$row->{'crest_image'} = &subs::construct_crest_image_src($row->{'app'});
				}
			}
			foreach my $member ( @{ $row->{'members'} } ) {
				$member->{'image'} = &people_crest_image($member->{'app'});
				$member->{'uuid'} = $people_by_app{$member->{'app'}} || '';
			}
		}
	}
	my $feeds = &market_scan_feeds();
	my $scanner = (grep { $_ eq 'flatbed' } @{ $feeds || [] }) ? 1 : 0;
	my $camera = 0;
	if (&subs::device_setter() eq 'mobile' && grep { defined $_ && $_ =~ /^[01]$/ } @{ $gb::capabilities->{'mobile'}->{'camera'} || [] }) {
		$camera = 1;
	}
	my $nfc = (&subs::device_setter() eq 'mobile') ? 1 : 0;
	my $content = $c->render_to_string(
		template => 'apps/people',
		crest => $crest,
		has_image => $has_image,
		introduced_by => $crest_introduced_by,
		peers => \@peers,
		people => \@people,
		backers => $backers,
		constructs => $index->{'constructs'},
		scanner => $scanner,
		camera => $camera,
		nfc => $nfc,
		device => &subs::device_setter(),
	);
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'people', title => &subs::lang('people'), contents => $content }, $c->param('timestamp'));
	$c->render(text => $contents);
};

get '/manager/people/crest/detail' => sub($c) {
	unless (&people_citizen($c)) { return $c->render(json => { ok => 0, error => 'citizen only' }); }
	my $uuid = $c->param('uuid') || '';
	my $entry = &subs::crest_peer_find($uuid);
	return $c->render(json => { ok => 0, error => 'no such crest' }) unless $entry;
	my $incoming = $entry->{'crest'} || {};
	my $own = &subs::crest_record_read();
	my $peer_list = &subs::crest_peer_list_read();
	my $met = 0;
	my $met_at = '';
	if (ref $entry->{'vouch'} eq 'HASH'
		&& &subs::crest_vouch_verify($entry->{'vouch'})
		&& ($entry->{'vouch'}->{'from_uuid'} || '') eq ($own->{'uuid'} || '')
		&& ($entry->{'vouch'}->{'to_uuid'} || '') eq ($incoming->{'uuid'} || '')
		&& ($entry->{'vouch'}->{'to_pubkey'} || '') eq ($incoming->{'pubkey'} || '')) {
		$met = 1;
		$met_at = $entry->{'vouch'}->{'at'} || $entry->{'met_at'} || '';
	}
	my $introduced_by = '';
	foreach my $vouch ( @{ $entry->{'vouches'} || [] } ) {
		next unless ref $vouch eq 'HASH';
		next unless ($vouch->{'to_uuid'} || '') eq ($incoming->{'uuid'} || '');
		next unless ($vouch->{'to_pubkey'} || '') eq ($incoming->{'pubkey'} || '');
		my $issuer = &subs::crest_vouch_introducer($vouch, $own, $peer_list);
		next unless $issuer;
		next if ($issuer->{'uuid'} || '') eq ($own->{'uuid'} || '');
		$introduced_by = $issuer->{'name'} || '';
		last;
	}
	my $endpoints = ref $entry->{'endpoints'} eq 'HASH' ? $entry->{'endpoints'} : {};
	my $linked_app = &subs::crest_contact_app_for_uuid($uuid);
	my %apps;
	foreach my $kind ( qw/phone email/ ) {
		my $lines = eval { &subs::contact_lines($kind) } || {};
		foreach my $app ( keys %{$lines} ) {
			my @lines = @{ $lines->{$app} || [] };
			$apps{$app} ||= { app => $app, name => &subs::format_name($app), phone => '', email => '' };
			$apps{$app}->{'phone'} = $lines[0]->{'value'} || '' if $kind eq 'phone' && @lines;
			$apps{$app}->{'email'} = $lines[0]->{'value'} || '' if $kind eq 'email' && @lines;
		}
	}
	my @contacts = sort { lc($a->{'name'}) cmp lc($b->{'name'}) } values %apps;
	my $tickets = eval { &subs::db_query('select name from tickets')->hashes } || [];
	foreach my $ticket ( @{$tickets} ) {
		my $app = &subs::unformat_name($ticket->{'name'} || '');
		next unless length $app;
		$apps{$app} ||= { app => $app, name => &subs::format_name($app), phone => '', email => '' };
	}
	@contacts = sort { lc($a->{'name'}) cmp lc($b->{'name'}) } values %apps;
	if ($linked_app && !$apps{$linked_app}) {
		foreach my $key ( keys %apps ) {
			if (lc($key) eq lc($linked_app)) { $linked_app = $key; last; }
		}
	}
	my $contact = ($linked_app && $apps{$linked_app}) ? $apps{$linked_app} : undef;
	my $has_image = ((defined $entry->{'image_data'} && length $entry->{'image_data'}) || &subs::crest_peer_image_file($entry)) ? 1 : 0;
	my $image_src = (defined $entry->{'image_data'} && length $entry->{'image_data'})
		? $entry->{'image_data'}
		: ($has_image ? '/manager/people/crest_image?peer=' . $uuid . '&stamp=' . &subs::rightNow() : '');
	return $c->render(json => {
		ok => 1,
		uuid => $uuid,
		name => $incoming->{'name'} || '',
		fingerprint => $incoming->{'fingerprint'} || '',
		met => $met ? 1 : 0,
		met_at => $met_at,
		introduced_by => $introduced_by,
		status => $met ? 'Met in person' : ($introduced_by ? 'Introduced by ' . $introduced_by : 'Imported, not met'),
		image => $image_src,
		origin => &subs::crest_entry_origin($entry),
		profile => (ref $entry->{'profile'} eq 'HASH' ? $entry->{'profile'} : undef),
		home => $endpoints->{'home'} || '',
		store => $endpoints->{'store'} || '',
		manager => $endpoints->{'manager'} || '',
		linked_app => $linked_app,
		contact => $contact,
		contacts => \@contacts,
	});
};

post '/manager/people/crest/lookup' => sub($c) {
	unless (&people_citizen($c)) { return $c->render(json => { ok => 0, error => 'citizen only' }); }
	my $uuid = $c->param('uuid') || '';
	unless ($uuid =~ /^[A-Za-z0-9_-]{8,64}$/) { return $c->render(json => { ok => 0, error => 'no such crest' }); }
	my $entry = &subs::crest_peer_find($uuid);
	return $c->render(json => { ok => 0, error => 'no such crest' }) unless $entry;
	my $origin = &subs::crest_entry_origin($entry);
	unless (length $origin) {
		return $c->render(json => { ok => 0, error => 'this crest does not say where its house can be reached' });
	}
	my $own = &subs::crest_record_read();
	my $suds = &subs::session_suds($c);
	my $priv = $suds ? &subs::crest_key_read($suds) : undef;
	unless ($own->{'uuid'} && defined $priv && length $priv == 32) {
		return $c->render(json => { ok => 0, error => 'this house has no crest to present' });
	}
	my $code = &subs::crest_code_build($own, $priv);
	unless ($code) { return $c->render(json => { ok => 0, error => 'the crest code could not be made' }); }
	my $url = $origin . '/crest/' . $uuid . '/profile';
	my $ua = Mojo::UserAgent->new(connect_timeout => 5, inactivity_timeout => 10, request_timeout => 15);
	$ua->insecure(1);
	my $res = eval { $ua->get($url => form => { code => $code })->result };
	unless ($res) { return $c->render(json => { ok => 0, error => 'the other house did not answer' }); }
	unless ($res->is_success) {
		return $c->render(json => { ok => 0, error => 'the other house refused the lookup (' . $res->code . ')' });
	}
	my $body = eval { decode_json($res->body) } || {};
	my $profile = $body->{'profile'};
	unless (ref $profile eq 'HASH') {
		return $c->render(json => { ok => 0, error => 'the answer was not a crest profile' });
	}
	# The answer must be the crest we hold: same id, same key, and a signature
	# that checks. A host that merely answers the address is not enough.
	my $incoming = ref $entry->{'crest'} eq 'HASH' ? $entry->{'crest'} : {};
	unless (($profile->{'uuid'} || '') eq $uuid
		&& ($profile->{'pubkey'} || '') eq ($incoming->{'pubkey'} || '')
		&& &subs::crest_verify_record($profile)) {
		return $c->render(json => { ok => 0, error => 'the answer was not signed by that crest' });
	}
	my @constructs;
	foreach my $construct ( @{ ref $profile->{'constructs'} eq 'ARRAY' ? $profile->{'constructs'} : [] } ) {
		next unless ref $construct eq 'HASH' && length($construct->{'name'} || '');
		push @constructs, {
			type => $construct->{'type'} || '',
			name => $construct->{'name'} || '',
			members => [ map { defined $_ ? "$_" : '' } @{ ref $construct->{'members'} eq 'ARRAY' ? $construct->{'members'} : [] } ],
		};
	}
	my $store = {
		uuid => $profile->{'uuid'},
		name => $profile->{'name'} || '',
		origin => $profile->{'origin'} || $origin,
		issued => $profile->{'issued'} || '',
		at => &subs::rightNow(),
		constructs => \@constructs,
	};
	&subs::crest_peer_update($uuid, { profile => $store, profile_at => &subs::rightNow() });
	return $c->render(json => { ok => 1, profile => $store });
};

# Publishing a construct to other houses is the same per-app public toggle the
# appointment carries, so it is written for this device: the appointment and
# People then agree on the machine the person is using. People reads every
# device's row and consolidates them (newest wins) when it shows the row or
# answers a lookup.
post '/manager/people/construct/public' => sub($c) {
	unless (&people_citizen($c)) { return $c->render(json => { ok => 0, error => 'citizen only' }); }
	my $app = $c->param('app') || '';
	my $value = (($c->param('value') || '') eq 'on') ? 'on' : '';
	unless (length $app && &people_construct_kind($app)) {
		return $c->render(json => { ok => 0, error => 'no such construct' });
	}
	&subs::setting_setter({ app => $app, setting => 'public', device => &subs::device_setter(), value => $value });
	return $c->render(json => { ok => 1, app => $app, public => ($value eq 'on' ? 1 : 0) });
};

# A member machine hands the crest holder its cosignature. The request carries
# the peer's signature and the statement carries it again, so the roster row
# keeps a signature that still verifies after the request is gone. Only a
# machine on this house's roster can cosign, and only this house's crest.
post '/manager/crest/cosign' => sub($c) {
	my $signatorial = $c->param('signatorial') || '';
	my $rm = $signatorial
		? &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]
		: undef;
	unless ($rm) { return $c->render(json => { ok => 0, error => 'no such machine' }); }
	# A keyless row must not let an unsigned caller in: the cosignature is a
	# signature, so the request has to carry one too.
	unless ($c->req->headers->header('X-Peer-Signature')) {
		return $c->render(json => { ok => 0, error => 'a signed request is required' });
	}
	unless (&subs::peer_verify($c, $rm)) {
		return $c->render(json => { ok => 0, error => 'the signature is not that machine' });
	}
	my $body = eval { $c->req->json } || {};
	my $crest_uuid = $body->{'crest_uuid'} || $c->param('crest_uuid') || '';
	my $cosig = $body->{'cosig'};
	unless (ref $cosig eq 'HASH') {
		my $raw = $c->param('cosig') || '';
		$cosig = eval { decode_json($raw) };
	}
	unless (ref $cosig eq 'HASH') {
		return $c->render(json => { ok => 0, error => 'no cosignature' });
	}
	my $crest = &subs::crest_record_read();
	if ($crest_uuid && ($crest->{'uuid'} || '') ne $crest_uuid) {
		return $c->render(json => { ok => 0, error => 'this house holds another crest' });
	}
	return $c->render(json => &subs::crest_member_cosig_accept($rm, $crest, $cosig));
};

get '/manager/people/person' => sub($c) {
	unless (&people_citizen($c)) { return $c->render(json => { ok => 0, error => 'citizen only' }); }
	my $uuid = $c->param('uuid') || '';
	my $person = eval { &subs::db_select('people', undef, { uuid => $uuid, status => 'active' })->hash };
	return $c->render(json => { ok => 0, error => 'no such person' }) unless $person && length($person->{'app'} || '');
	my $index = &people_link_sync();
	my $app = $person->{'app'};
	my $chips = &people_chips($index, $app);
	my $entry = &subs::crest_contact_entry($app);
	my $crest = {};
	my $crest_uuid = '';
	my $image = '';
	my $home = '';
	my $store = '';
	my $met = 0;
	my $met_at = '';
	my $introduced_by = '';
	if ($entry && ref $entry->{'crest'} eq 'HASH') {
		my $incoming = $entry->{'crest'};
		$crest_uuid = $incoming->{'uuid'} || '';
		$crest = { name => $incoming->{'name'} || '', fingerprint => $incoming->{'fingerprint'} || '' };
		$image = &people_crest_image($app);
		my $endpoints = ref $entry->{'endpoints'} eq 'HASH' ? $entry->{'endpoints'} : {};
		$home = $endpoints->{'home'} || '';
		$store = $endpoints->{'store'} || '';
		my $state = &people_crest_state($entry);
		$met = $state->{'met'};
		$met_at = $state->{'met_at'};
		$introduced_by = $state->{'introduced_by'};
	}
	my ($phone, $email) = ('', '');
	foreach my $kind ( qw/phone email/ ) {
		my $lines = eval { &subs::contact_lines($kind) } || {};
		my $line = $lines->{$app} || $lines->{lc($app)} || [];
		next unless ref $line eq 'ARRAY' && scalar @{$line};
		if ($kind eq 'phone') { $phone = $line->[0]->{'value'} || ''; }
		else { $email = $line->[0]->{'value'} || ''; }
	}
	my @peer_choices;
	foreach my $peer ( @{ &subs::crest_peer_list_read() } ) {
		next unless ref $peer eq 'HASH' && ref $peer->{'crest'} eq 'HASH';
		next unless length($peer->{'crest'}->{'uuid'} || '');
		push @peer_choices, { uuid => $peer->{'crest'}->{'uuid'}, name => $peer->{'crest'}->{'name'} || '' };
	}
	@peer_choices = sort { lc($a->{'name'}) cmp lc($b->{'name'}) } @peer_choices;
	my $html = $c->render_to_string(
		template => 'apps/people_person',
		person => $person,
		app => $app,
		chips => $chips,
		crest => $crest,
		crest_uuid => $crest_uuid,
		image => $image,
		home => $home,
		store => $store,
		met => $met,
		met_at => $met_at,
		introduced_by => $introduced_by,
		phone => $phone,
		email => $email,
		main_image => &people_main_image($app),
		peer_choices => \@peer_choices,
	);
	$c->render(json => { ok => 1, html => $html });
};

post '/manager/people/crest/link' => sub($c) {
	unless (&people_citizen($c)) { return $c->render(json => { ok => 0, error => 'citizen only' }); }
	my $uuid = $c->param('uuid') || '';
	my $app = $c->param('app') // '';
	my $entry = &subs::crest_peer_find($uuid);
	return $c->render(json => { ok => 0, error => 'no such crest' }) unless $entry;
	&subs::crest_contact_link_set($app, $uuid);
	return $c->render(json => { ok => 1 });
};

get '/manager/people/crest/qr' => sub($c) {
	unless (&people_citizen($c)) { $c->rendered(403); return; }
	my $suds = &subs::session_suds($c);
	my $app = $c->param('app') || '';
	my $crest = length $app ? &subs::construct_crest_record_read($app) : &subs::crest_record_read();
	unless ($crest->{'uuid'} && $suds) { $c->rendered(404); return; }
	my $priv = &subs::crest_key_read($suds);
	unless ($priv) { return $c->render(json => { ok => 0, error => 'the crest key is not available' }); }
	my $code = &subs::crest_code_build($crest, $priv);
	unless ($code) { return $c->render(json => { ok => 0, error => 'the crest code could not be made' }); }
	my $png = &subs::crest_qr_png($code);
	if (($c->param('format') || '') eq 'json') {
		return $c->render(json => { ok => 1, code => $code, qr => ($png ? 'data:image/png;base64,' . encode_base64($png, '') : '') });
	}
	unless ($png) { $c->rendered(500); return; }
	$c->res->headers->content_type('image/png');
	$c->res->headers->cache_control('private, max-age=60');
	$c->render(data => $png);
};

sub people_crest_card {
	my ($c, $construct_app) = @_;
	my $suds = &subs::session_suds($c);
	my $construct = defined $construct_app && length $construct_app ? $construct_app : '';
	my $crest = $construct ? &subs::construct_crest_record_read($construct) : &subs::crest_record_read();
	return undef unless $crest->{'uuid'} && $suds;
	my $device = $crest->{'device'} || &subs::device_setter();
	my $standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard', device => $device }) || 'aes-256-ctr';
	my $file = &subs::crest_image_file($crest, 'image');
	my $image = $file ? &subs::crest_image_data_uri($file, $suds, $standard, 512) : undef;
	my @vouches;
	unless ($construct) {
		my $peers = &subs::crest_peer_list_read();
		my %seen_vouch;
		foreach my $vouch ( @{ &subs::crest_incoming_vouch_list_read() } ) {
			next unless ref $vouch eq 'HASH' && &subs::crest_vouch_verify($vouch);
			next unless ($vouch->{'to_uuid'} || '') eq ($crest->{'uuid'} || '');
			next unless ($vouch->{'to_pubkey'} || '') eq ($crest->{'pubkey'} || '');
			next if $seen_vouch{ $vouch->{'sig'} || '' }++;
			push @vouches, $vouch;
		}
		foreach my $entry ( @{$peers} ) {
			next unless ref $entry eq 'HASH' && ref $entry->{'vouch'} eq 'HASH';
			my $vouch = $entry->{'vouch'};
			next unless &subs::crest_vouch_verify($vouch);
			next unless ($vouch->{'from_uuid'} || '') eq ($crest->{'uuid'} || '');
			next if $seen_vouch{ $vouch->{'sig'} || '' }++;
			push @vouches, $vouch;
		}
	}
	my $card = { format => 'jawnos-crest-card', card_version => 1, crest => $crest, vouches => \@vouches };
	$card->{'image'} = $image if defined $image;
	my $config = &subs::config_reader();
	# The card is handed to another house, so name the address they can reach:
	# a loopback domain on a laptop would point them at their own machine.
	my $origin = &subs::crest_origin();
	my $host = $config->{'domain'} || $c->req->url->base->host;
	my $port = $config->{'port'} || 3000;
	my $working = $config->{'working_port'} || $port;
	$origin ||= "https://$host:$working";
	$card->{'endpoints'} = {
		home => $origin . '/',
		store => $origin . '/store',
		manager => $origin . '/manager',
		signatorial => &subs::signatorial_designer(),
	};
	# The machines that back the crest, each with its own signed statement. The
	# crest record is the signed part of the card; a recipient can check each
	# statement against the key it carries. Cosignatures back the house crest,
	# not a construct's.
	$card->{'cosignatures'} = &subs::crest_member_cosig_list($crest, { include_local => 1 }) unless $construct;
	return $card;
}

get '/manager/people/crest/card' => sub($c) {
	unless (&people_citizen($c)) { $c->rendered(403); return; }
	my $card = &people_crest_card($c, $c->param('app') || '');
	unless ($card) { $c->rendered(404); return; }
	my $name = $card->{'crest'}->{'name'} || 'crest';
	$name =~ s/[^\w.\-]+/_/g;
	$c->res->headers->content_type('application/json');
	$c->res->headers->content_disposition('attachment; filename="crest-' . $name . '.json"');
	$c->render(data => encode_json($card));
};

post '/manager/people/crest/card/save' => sub($c) {
	unless (&people_citizen($c)) { return $c->render(json => { ok => 0, error => 'citizen only' }); }
	my $card = &people_crest_card($c, $c->param('app') || '');
	unless ($card) { return $c->render(json => { ok => 0, error => 'no crest yet' }); }
	my $dir = &subs::home('~/Downloads');
	$dir = &subs::home('~/Documents') unless -d $dir;
	$dir = &subs::home('~') unless -d $dir;
	my $name = $card->{'crest'}->{'name'} || 'crest';
	$name =~ s/[^\w.\-]+/_/g;
	my $path = "$dir/crest-$name.json";
	$path = "$dir/crest-$name-" . &subs::rightNow() . '.json' if -e $path;
	my $ok = eval { write_file($path, encode_json($card)); 1 };
	unless ($ok && -e $path) { return $c->render(json => { ok => 0, error => 'the card could not be written' }); }
	return $c->render(json => { ok => 1, path => $path });
};

sub people_crest_import_code {
	my ($c, $code) = @_;
	return { ok => 0, error => 'citizen only' } unless (($c->session('privilege') || '') eq 'citizen');
	my $record = &subs::crest_code_parse($code);
	return { ok => 0, error => 'the crest code is not readable' } unless ref $record eq 'HASH';
	return { ok => 0, error => 'the crest record does not verify' } unless &subs::crest_verify_record($record);
	# A construct crest names a construct, not a house. A tag for one of this
	# house's own constructs opens it; another house's construct is not a house
	# crest and there is nothing here to import it into.
	if (length($record->{'construct'} || '')) {
		my $local = &construct_crest_find_by_uuid($record->{'uuid'});
		if ($local) {
			return {
				ok => 1,
				crest => $record,
				construct_app => $local->{'app'},
				construct_name => $record->{'name'} || $local->{'crest'}->{'name'} || '',
				known => 1,
			};
		}
		my $imported = &foreign_construct_import($record);
		return { ok => 0, error => $imported->{'error'} || 'the construct could not be imported' }
			unless $imported->{'ok'};
		return {
			ok => 1,
			crest => $record,
			construct_app => $imported->{'app'},
			construct_name => $imported->{'name'} || $record->{'name'} || '',
			house_name => $imported->{'house_name'},
			foreign => 1,
		};
	}
	my $own = &subs::crest_record_read();
	return { ok => 0, error => 'that is this house\'s own crest' } if $own->{'uuid'} && $record->{'uuid'} && $own->{'uuid'} eq $record->{'uuid'};
	my $existing = &subs::crest_peer_find($record->{'uuid'});
	my $entry = {
		crest => $record,
		device => &subs::device_setter(),
		imported_at => &subs::rightNow(),
		status => 'imported',
		vouches => [],
	};
	my $known = $existing ? 1 : 0;
	if ($existing) {
		$entry->{'imported_at'} = $existing->{'imported_at'} || $entry->{'imported_at'};
		$entry->{'vouch'} = $existing->{'vouch'} if ref $existing->{'vouch'} eq 'HASH';
		$entry->{'met_at'} = $existing->{'met_at'} if defined $existing->{'met_at'};
		$entry->{'status'} = $existing->{'status'} if (($existing->{'status'} || '') eq 'met');
		$entry->{'image_file'} = $existing->{'image_file'} if $existing->{'image_file'};
		$entry->{'image_data'} = $existing->{'image_data'} if defined $existing->{'image_data'};
		$entry->{'endpoints'} = $existing->{'endpoints'} if ref $existing->{'endpoints'} eq 'HASH';
	}
	return { ok => 0, error => 'the crest could not be stored' } unless &subs::crest_peer_upsert($entry);
	return { ok => 1, crest => $record, entry => $entry, known => $known };
}

post '/manager/people/crest/scan' => sub($c) {
	return $c->render(json => { ok => 0, error => 'citizen only' }) unless &people_citizen($c);
	my $feeds = &market_scan_feeds();
	unless (grep { $_ eq 'flatbed' } @{ $feeds || [] }) {
		return $c->render(json => { ok => 0, error => 'this device has no flatbed scanner' });
	}
	my $base = &people_crest_scan_dir() . '/crest_' . &subs::rightNow();
	my $command = &scanner_scan_command('flatbed', $base);
	unless ($command) {
		return $c->render(json => { ok => 0, error => 'the scanner does not offer the flatbed' });
	}
	`timeout 60 $command 2> $base.log`;
	my @pages = &scanner_page_list($base);
	unless (@pages) {
		my $why = &scanner_log_reason($base . '.log');
		unlink glob("$base*");
		return $c->render(json => { ok => 0, error => 'the scanner produced no page' . ($why ne '' ? ': ' . $why : '') });
	}
	my $result = &people_crest_install($c, $pages[0]);
	unlink @pages;
	unlink $base . '.log';
	return $c->render(json => $result);
};

post '/manager/people/crest/capture' => sub($c) {
	return $c->render(json => { ok => 0, error => 'citizen only' }) unless &people_citizen($c);
	my $camera = $c->param('camera') // '0';
	$camera = '0' unless $camera =~ /^[01]$/;
	my ($file, $ocr) = &take_picture($c, {
		app => 'people',
		camera => $camera,
		timestamp => &subs::rightNow(),
		capture_only => 1,
		no_ocr => 1,
	});
	unless (defined $file && $file ne 'denial' && -e $file) {
		return $c->render(json => { ok => 0, error => (($file || '') eq 'denial') ? 'this device has no camera' : 'the camera did not return a picture' });
	}
	my $result = &people_crest_install($c, $file);
	unlink $file;
	return $c->render(json => $result);
};

post '/manager/people/crest/upload' => sub($c) {
	return $c->render(json => { ok => 0, error => 'citizen only' }) unless &people_citizen($c);
	my ($path, $error) = &people_crest_upload_file($c);
	return $c->render(json => { ok => 0, error => $error }) unless $path;
	my $result = &people_crest_install($c, $path);
	unlink $path;
	return $c->render(json => $result);
};

post '/manager/people/construct/crest/upload' => sub($c) {
	return $c->render(json => { ok => 0, error => 'citizen only' }) unless &people_citizen($c);
	my $app = $c->param('app') || '';
	return $c->render(json => { ok => 0, error => 'no such construct' }) unless &people_construct_kind($app);
	my ($path, $error) = &people_crest_upload_file($c);
	return $c->render(json => { ok => 0, error => $error }) unless $path;
	my $result = &construct_crest_install($c, $path, $app);
	unlink $path;
	return $c->render(json => $result);
};

post '/manager/people/crest/verify' => sub($c) {
	return $c->render(json => { ok => 0, error => 'citizen only' }) unless &people_citizen($c);
	my $record = &subs::crest_record_read();
	return $c->render(json => { ok => 0, error => 'no crest yet' }) unless $record->{'uuid'};
	my ($path, $error) = &people_crest_upload_file($c);
	return $c->render(json => { ok => 0, error => $error }) unless $path;
	my $ref = $path . '.ref.png';
	unless (&subs::crest_normalize_image($path, $ref)) {
		unlink $path; unlink $ref;
		return $c->render(json => { ok => 0, error => 'the picture could not be read' });
	}
	my $dhash = &subs::crest_dhash($ref);
	my $distance = &subs::crest_hamming($record->{'dhash'}, $dhash);
	unlink $path; unlink $ref;
	unless (defined $distance) {
		return $c->render(json => { ok => 0, error => 'the picture could not be compared' });
	}
	return $c->render(json => { ok => 1, distance => $distance, likely => ($distance <= 12 ? 1 : 0), threshold => 12 });
};

post '/manager/people/crest/import' => sub($c) {
	return $c->render(json => { ok => 0, error => 'citizen only' }) unless &people_citizen($c);
	my $fail = sub { return $c->render(json => { ok => 0, error => $_[0] }); };
	my $raw = $c->param('card') // '';
	unless (length $raw) {
		my @uploads = @{ $c->req->uploads || [] };
		$raw = $uploads[0]->asset->slurp if @uploads;
	}
	return $fail->('no card was supplied') unless length $raw;
	return $fail->('that card is too large') if length $raw > 5_000_000;
	if ($raw =~ /^\s*CREST1Z?:/i) {
		return $c->render(json => &people_crest_import_code($c, $raw));
	}
	my $card = eval { decode_json($raw) };
	return $fail->('that card is not readable') unless ref $card eq 'HASH';
	return $fail->('that is not a JawnOS crest card') unless (($card->{'format'} || '') eq 'jawnos-crest-card');
	my $incoming = $card->{'crest'};
	return $fail->('the card has no crest record') unless ref $incoming eq 'HASH';
	return $fail->('the crest record does not verify') unless &subs::crest_verify_record($incoming);
	if (length($incoming->{'construct'} || '')) {
		# A construct card: find this house's own copy first, otherwise import it
		# as another house's construct (which the signed record names).
		my $local = &construct_crest_find_by_uuid($incoming->{'uuid'});
		if ($local) {
			return $c->render(json => {
				ok => 1, crest => $incoming, construct_app => $local->{'app'},
				construct_name => $incoming->{'name'} || $local->{'crest'}->{'name'} || '',
				known => 1,
			});
		}
		my $imported = &foreign_construct_import($incoming);
		unless ($imported->{'ok'}) { return $fail->($imported->{'error'}); }
		return $c->render(json => {
			ok => 1, crest => $incoming, construct_app => $imported->{'app'},
			construct_name => $imported->{'name'}, house_name => $imported->{'house_name'},
			foreign => 1,
		});
	}
	my $own = &subs::crest_record_read();
	return $fail->('that is this house\'s own crest') if $own->{'uuid'} && $incoming->{'uuid'} && $own->{'uuid'} eq $incoming->{'uuid'};
	my $safe_uuid = $incoming->{'uuid'} || '';
	$safe_uuid =~ s/[^A-Za-z0-9_-]//g;
	return $fail->('the crest record has no usable id') unless length $safe_uuid;
	my $suds = &subs::session_suds($c);
	return $fail->('the house key is not available') unless $suds;
	my $device = &subs::device_setter();
	my $folder = &subs::setting_grabber({ app => 'misc', setting => 'photo_location', device => $device }) || 'Pictures';
	my $dir = &subs::home($folder) . '/me';
	unless (-d $dir) { eval { require File::Path; File::Path::make_path($dir) }; }
	my $image_name;
	if (defined $card->{'image'} && length $card->{'image'}) {
		my $bytes = &subs::crest_data_uri_bytes($card->{'image'});
		return $fail->('the card picture is not readable') unless $bytes;
		require File::Temp;
		my ($fh, $tmp) = File::Temp::tempfile('jawnos-crest-import-XXXXXX', TMPDIR => 1, UNLINK => 0);
		return $fail->('no temporary file') unless $fh && $tmp;
		binmode $fh;
		print $fh $bytes;
		close $fh;
		my $ref = $tmp . '.ref.png';
		unless (&subs::crest_normalize_image($tmp, $ref)) {
			unlink $tmp; unlink $ref;
			return $fail->('the card picture could not be read');
		}
		my $dhash = &subs::crest_dhash($ref);
		my $distance = &subs::crest_hamming($incoming->{'dhash'}, $dhash);
		unless (defined $distance && $distance <= 16) {
			unlink $tmp; unlink $ref;
			return $fail->('the card picture does not match its signed hash');
		}
		my $standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard', device => $device }) || 'aes-256-ctr';
		$image_name = 'peer-crest.' . $safe_uuid . '.jpg.enc';
		my $enc = "$dir/$image_name";
		unless (&subs::openssl_file_crypt('e', $standard, $suds, $tmp, $enc, 0, 1)) {
			unlink $tmp; unlink $ref;
			return $fail->('the card picture could not be sealed');
		}
		unlink $tmp; unlink $ref;
	}
	my $existing = &subs::crest_peer_find($incoming->{'uuid'});
	my $entry = {
		crest => $incoming,
		device => $device,
		imported_at => &subs::rightNow(),
		status => 'imported',
		vouches => [],
	};
	$entry->{'endpoints'} = $card->{'endpoints'} if ref $card->{'endpoints'} eq 'HASH';
	$entry->{'image_data'} = $card->{'image'} if defined $card->{'image'} && length $card->{'image'};
	if ($existing) {
		$entry->{'imported_at'} = $existing->{'imported_at'} || $entry->{'imported_at'};
		$entry->{'vouch'} = $existing->{'vouch'} if ref $existing->{'vouch'} eq 'HASH';
		$entry->{'met_at'} = $existing->{'met_at'} if defined $existing->{'met_at'};
		$entry->{'status'} = $existing->{'status'} if (($existing->{'status'} || '') eq 'met');
		$entry->{'image_file'} = $existing->{'image_file'} if !$image_name && $existing->{'image_file'};
		$entry->{'image_data'} = $existing->{'image_data'} if !$entry->{'image_data'} && defined $existing->{'image_data'};
		$entry->{'endpoints'} = $existing->{'endpoints'} if !$entry->{'endpoints'} && ref $existing->{'endpoints'} eq 'HASH';
	}
	$entry->{'image_file'} = $image_name if $image_name;
	my %seen_vouch;
	foreach my $vouch ( @{ $card->{'vouches'} || [] } ) {
		next unless ref $vouch eq 'HASH';
		next unless &subs::crest_vouch_verify($vouch);
		my $sig = $vouch->{'sig'} || '';
		next unless length $sig;
		if (($vouch->{'to_uuid'} || '') eq ($incoming->{'uuid'} || '')
			&& ($vouch->{'to_pubkey'} || '') eq ($incoming->{'pubkey'} || '')) {
			next if $seen_vouch{$sig}++;
			push @{$entry->{'vouches'}}, $vouch if scalar @{$entry->{'vouches'}} < 100;
		}
		if ($own->{'uuid'}
			&& ($vouch->{'from_uuid'} || '') eq ($incoming->{'uuid'} || '')
			&& ($vouch->{'to_uuid'} || '') eq ($own->{'uuid'} || '')
			&& ($vouch->{'to_pubkey'} || '') eq ($own->{'pubkey'} || '')) {
			&subs::crest_incoming_vouch_add($vouch);
		}
	}
	return $fail->('the card could not be stored') unless &subs::crest_peer_upsert($entry);
	return $c->render(json => { ok => 1, crest => $incoming, entry => $entry });
};

post '/manager/people/crest/vouch' => sub($c) {
	return $c->render(json => { ok => 0, error => 'citizen only' }) unless &people_citizen($c);
	my $uuid = $c->param('uuid') || '';
	my $peer = &subs::crest_peer_find($uuid);
	return $c->render(json => { ok => 0, error => 'no such crest' }) unless $peer && ref $peer->{'crest'} eq 'HASH';
	my $own = &subs::crest_record_read();
	return $c->render(json => { ok => 0, error => 'this house has no crest yet' }) unless $own->{'uuid'} && $own->{'pubkey'};
	my $suds = &subs::session_suds($c);
	my $priv = &subs::crest_key_read($suds);
	return $c->render(json => { ok => 0, error => 'the crest key is not available' }) unless $priv;
	my $vouch = {
		from_uuid => $own->{'uuid'},
		from_pubkey => $own->{'pubkey'},
		from_name => $own->{'name'} || '',
		to_uuid => $peer->{'crest'}->{'uuid'} || '',
		to_pubkey => $peer->{'crest'}->{'pubkey'} || '',
		to_name => $peer->{'crest'}->{'name'} || '',
		method => 'in person',
		scope => 'communication',
		at => &subs::rightNow(),
	};
	return $c->render(json => { ok => 0, error => 'the other crest has no key' }) unless length $vouch->{'to_pubkey'};
	my $signed = &subs::crest_vouch_sign($vouch, $priv);
	return $c->render(json => { ok => 0, error => 'the vouch could not be signed' }) unless $signed;
	my $updated = &subs::crest_peer_update($uuid, { vouch => $signed, status => 'met', met_at => $signed->{'at'} });
	return $c->render(json => { ok => 0, error => 'the vouch could not be stored' }) unless $updated;
	return $c->render(json => { ok => 1, vouch => $signed });
};

post '/manager/people/house_name' => sub($c) {
	return $c->render(json => { ok => 0, error => 'citizen only' }) unless &people_citizen($c);
	my $name = $c->param('name') // '';
	$name =~ s/^\s+|\s+$//g;
	$name = substr($name, 0, 120);
	return $c->render(json => { ok => 0, error => 'a name is needed' }) unless length $name;
	my $record = &subs::crest_record_read();
	if ($record->{'uuid'}) {
		my $suds = &subs::session_suds($c);
		my $priv = &subs::crest_key_read($suds);
		return $c->render(json => { ok => 0, error => 'the crest key is not available' }) unless $priv;
		$record->{'name'} = $name;
		$record->{'version'} = ($record->{'version'} || 0) + 1;
		$record->{'server_time'} = &subs::rightNow();
		my $signed = &subs::crest_sign_record($record, $priv);
		return $c->render(json => { ok => 0, error => 'the crest could not be signed' }) unless $signed;
		return $c->render(json => { ok => 0, error => 'the crest could not be saved' }) unless &subs::crest_record_write($signed);
	}
	else {
		&subs::setting_setter({ app => '__president', setting => 'house_name', device => 'all', value => $name });
	}
	return $c->render(json => { ok => 1, name => $name });
};

get '/manager/people/crest_image' => sub($c) {
	unless (&people_citizen($c)) { $c->rendered(403); return; }
	my $peer_uuid = $c->param('peer') || '';
	my $app = $c->param('app') || '';
	my ($file, $device);
	if ($peer_uuid) {
		my $entry = &subs::crest_peer_find($peer_uuid);
		unless ($entry) { $c->rendered(404); return; }
		$file = &subs::crest_peer_image_file($entry);
		$device = $entry->{'device'} || &subs::device_setter();
	}
	elsif ($app) {
		my $record = &subs::construct_crest_record_read($app);
		unless ($record->{'uuid'}) { $c->rendered(404); return; }
		&subs::construct_crest_image_materialize($c, $app);
		my $kind = (($c->param('kind') || '') eq 'reference') ? 'reference' : 'image';
		$file = &subs::crest_image_file($record, $kind);
		$device = $record->{'device'} || &subs::device_setter();
	}
	else {
		my $record = &subs::crest_record_read();
		my $kind = (($c->param('kind') || '') eq 'reference') ? 'reference' : 'image';
		$file = &subs::crest_image_file($record, $kind);
		$device = $record->{'device'} || &subs::device_setter();
	}
	unless ($file) { $c->rendered(404); return; }
	my $suds = &subs::session_suds($c);
	unless ($suds) { $c->rendered(403); return; }
	my $standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard', device => $device }) || 'aes-256-ctr';
	my $data = &subs::openssl_file_read($standard, $suds, $file, 0, 1);
	unless (defined $data && length $data) { $c->rendered(404); return; }
	my $type = $data =~ /^\x89PNG/ ? 'image/png'
		: $data =~ /^\xFF\xD8\xFF/ ? 'image/jpeg'
		: 'application/octet-stream';
	$c->res->headers->content_type($type);
	$c->res->headers->cache_control('private, max-age=60');
	$c->render(data => $data);
};

post '/manager/phone/dial' => sub($c) {
	my $number = $c->param('number') || '';
	$number =~ s/[^\d+#*]//g;
	unless ($number) { $c->render(json => { ok => 0, error => 'No number.' }); return; }
	if (&subs::device_setter() eq 'mobile') {
		my $out = `termux-telephony-call "$number" 2>&1`;
		# a machine with no telephony (a wifi tablet is a 'mobile' device here too)
		# answers this same route: report success only when the dial really went
		# out, so a caller can fall through to the next mobile peer.
		my $ok = ($out =~ /error|exception|unable|denied|not found|no service/i) ? 0 : 1;
		$c->render(json => { ok => $ok, number => $number, out => $out });
		return;
	}
	# Not a phone: hand the call to one through remote_machines, the way an SMS is
	# handed over, so the pad dials for real from the laptop. The phone's own copy
	# of this route is what knows to run the command.
	my $dialled;
	foreach my $rm ( @{ &subs::db_query('select * from remote_machines where connection=? and device=?', 'active', 'mobile')->hashes } ) {
		last if $dialled;
		my $ru = eval { &remote_useragent_maker({ ip => $rm->{'ip'}, signatorial => $rm->{'signatorial'}, rm => $rm }) };
		next unless $ru && $ru->{'ua'} && $ru->{'manager'};
		my $res = eval { $ru->{'ua'}->inactivity_timeout(20)->post($ru->{'manager'} . '/manager/phone/dial?number=' . $number) };
		my $body = eval { decode_json $res->body } || {};
		$dialled = $rm if $body->{'ok'};
	}
	if ($dialled) {
		$c->render(json => { ok => 1, number => $number, via => ($dialled->{'hostname'} || $dialled->{'name'} || $dialled->{'ip'}) });
		return;
	}
	$c->render(json => { ok => 0, error => 'No phone is reachable to dial from.' });
};

post '/manager/phone/call' => sub($c) {
	# The live half of the phone app: 'ring' starts the call's appointment (on the
	# caller's own app when the number is known - the Call screening role supplies
	# it at ring - else the fallback 'phone' app), 'end' stops it and 'miss'
	# cancels it. The house's own call-log poll skips what this wrote, so a live
	# call and its call-log trail are one appointment, not two.
	my $event = $c->param('event') || '';
	my $number = $c->param('number') || '';
	$number =~ s/[^\d+#*]//g;
	my $uuid = $c->param('uuid') || '';
	my $timestamp = &timestamp_adjuster($c);

	my $app = 'phone';
	if ($number) {
		# the caller's own app: their name when the house knows the number, else the
		# number's own app (phone_number_app makes it known), the way the call-log
		# check files an unknown caller - so a stranger's call is an app to rename
		# later rather than a drop on the floor
		$app = &subs::phone_number_app($number) || 'phone';
	}

	if ($event eq 'ring') {
		my $wrote = &appointment_writer($c, {
			app => $app,
			type => 'start',
			subtype => 'phone',
			timestamp => $timestamp,
			account => $number,
			data => encode_json({ direction => ($c->param('direction') || 'incoming'), number => $number }),
		});
		$c->render(json => { ok => 1, app => $app, uuid => $wrote->{'uuid'} });
		return;
	}

	if ($event eq 'ignore') {
		# a call the desk's blacklist turned away: it never rang, so there is no
		# ring to stop - the appointment is written and closed at once, as a
		# cancelled call on the caller's own app. Filing it here also tells the
		# call-log poll (which skips a phone appointment within minutes of a log
		# entry) that this call is already accounted for.
		my $wrote = &appointment_writer($c, {
			app => $app,
			type => 'start',
			subtype => 'phone',
			timestamp => $timestamp,
			account => $number,
			data => encode_json({ direction => 'incoming', number => $number, blocked => 'yes' }),
		});
		unless ($wrote && $wrote->{'uuid'}) {
			$c->render(json => { ok => 0, error => 'no appointment' });
			return;
		}
		&subs::db_update('appointments', {
			type => 'cancel',
			stop_seen => 'yes',
			stop_timestamp => $timestamp,
			server_time => &subs::rightNow(),
		}, { uuid => $wrote->{'uuid'} });
		$c->render(json => { ok => 1, app => $app, uuid => $wrote->{'uuid'} });
		return;
	}

	if ($event eq 'log') {
		# A whole call, filed from the app's own record of it. The dialer role's
		# service sees every call whatever else is running, so this is what makes a
		# call taken with no page up leave an appointment behind (it used to be
		# written only by the page, and a call with the app in the background left
		# nothing). The appointment opens at the ring and closes at the hangup, or
		# cancels when nobody ever answered - a call that went out and was not
		# picked up counts the same way.
		my $started = $c->param('started') || $timestamp;
		my $ended = $c->param('ended') || $started;
		my $answered = ($c->param('answered') || '') eq 'yes';
		my $direction = $c->param('direction') || 'incoming';
		my $wrote = &appointment_writer($c, {
			app => $app,
			type => 'start',
			subtype => 'phone',
			timestamp => $started,
			account => $number,
			data => encode_json({ direction => $direction, number => $number }),
		});
		unless ($wrote && $wrote->{'uuid'}) {
			$c->render(json => { ok => 0, error => 'no appointment' });
			return;
		}
		my %closing = ( stop_seen => 'yes', stop_timestamp => $ended, server_time => &subs::rightNow() );
		if ($answered) {
			$closing{'type'} = 'stop';
			$closing{'duration'} = $ended - $started;
		}
		else {
			$closing{'type'} = 'cancel';
		}
		&subs::db_update('appointments', \%closing, { uuid => $wrote->{'uuid'} });
		$c->render(json => { ok => 1, app => $app, uuid => $wrote->{'uuid'} });
		return;
	}

	if (($event eq 'end' || $event eq 'miss') && $uuid) {
		my $row = &subs::db_select('appointments', undef, { uuid => $uuid })->hashes->[0];
		if ($row && $row->{'app'}) {
			my $data = { stop_seen => 'yes', stop_timestamp => $timestamp, server_time => &subs::rightNow() };
			if ($event eq 'miss') {
				$data->{'type'} = 'cancel';
			}
			else {
				$data->{'type'} = 'stop';
				$data->{'duration'} = $timestamp - $row->{'timestamp'};
			}
			&subs::db_update('appointments', $data, { uuid => $uuid });
		}
		$c->render(json => { ok => 1, event => $event });
		return;
	}

	$c->render(json => { ok => 0, error => 'unknown event' });
};

get '/manager/phone/sync' => sub($c) {
	# What the app's native phone half needs, handed over in one fetch: the desk's
	# blacklist (the CallScreeningService refuses a listed caller before the phone
	# rings), the house's numbers by name (the in-call screen names the caller, and
	# the app's contact list shows the house's own names), and a small picture per
	# person, as a data URI, for the call screen - who is calling, before the phone
	# has finished ringing. The app wears its own logo for anyone without one.
	my %names = %{ &phone_names() };
	my %avatars;
	foreach my $number ( keys %names ) {
		my $picture = &phone_avatar_data($names{$number});
		$avatars{$number} = $picture if $picture;
	}
	$c->render(json => {
		blocked => &ticket_blacklist_numbers(),
		names => \%names,
		avatars => \%avatars,
	});
};

post '/manager/box_office/blacklist/number' => sub($c) {
	# Block a number by hand: the desk's own input, or the Phone app's Block on a
	# recent call. The list is the box office's, so one route serves both. A recent
	# call filed from the device's call log carries the caller's app but not always
	# the number, so an app with no number given is looked up the way the phone's
	# own rows hold it.
	unless (&ticket_desk_allowed($c)) {
		$c->render(json => { error => 'denied' });
		return;
	}
	my $number = $c->param('number') || '';
	my $app = $c->param('app') || '';
	unless ($number =~ /\d/) {
		$number = $app ? (&subs::setting_grabber({ app => $app, setting => 'phone' }) || '') : '';
	}
	my $blocked = &ticket_blacklist_block($number, $c->param('name') || $app, $c->param('note'));
	unless ($blocked) {
		$c->render(json => { ok => 0, error => 'no number' });
		return;
	}
	$log->info('call blacklist: ' . $blocked . ' blocked');
	$c->render(json => { ok => 1, number => $blocked, numbers => &ticket_blacklist_numbers() });
};

post '/manager/configure/notification_sound' => sub($c) {
	# A custom ringtone: the audio an app's notification plays. It lands beside the
	# shipped ones (public/sounds/notifications) so every sound list in Configure
	# picks it up with no further wiring; only audio is accepted, named after the
	# file itself so the list reads well, and never overwriting what is there.
	unless (&authentication_passer($c) eq 'approved') {
		$c->render(json => { ok => 0, error => 'denied' });
		return;
	}
	my $upload = $c->req->upload('sound');
	unless ($upload) {
		$c->render(json => { ok => 0, error => 'no file' });
		return;
	}
	my ($ext) = $upload->filename =~ /\.(mp3|ogg|oga|wav|m4a|aac|opus|flac)$/i;
	unless ($ext) {
		$c->render(json => { ok => 0, error => 'audio files only' });
		return;
	}
	$ext = lc $ext;
	if ($upload->size > 12 * 1024 * 1024) {
		$c->render(json => { ok => 0, error => 'that file is too big' });
		return;
	}
	my $name = $upload->filename;
	$name =~ s/\.[^.]*$//;
	$name = lc $name;
	$name =~ s/[^a-z0-9]+/-/g;
	$name =~ s/^-+|-+$//g;
	$name = 'sound' unless length $name;
	my $dir = 'public/sounds/notifications';
	my $file = "$dir/$name.$ext";
	my $i = 2;
	while (-e $file) { $file = "$dir/$name-" . $i++ . ".$ext"; }
	eval { $upload->move_to($file) };
	unless (-e $file && -s $file > 0) {
		$c->render(json => { ok => 0, error => 'could not save that' });
		return;
	}
	(my $shown = $file) =~ s{.*/}{};
	$shown =~ s/\.[^.]*$//;
	$log->info('notification sound added: ' . $file);
	$c->render(json => { ok => 1, sound => './' . $file, name => &subs::format_name($shown) });
};

post '/manager/note_save' => sub($c) {
	# Write a note by hand, or save one being edited: a uuid that is already a note
	# updates in place, anything else is a new note. Every open Notes window is
	# refreshed, so the list stays live.
	my $uuid = $c->param('uuid');
	my $text = $c->param('text');
	$text = '' unless defined $text;
	$text =~ s/\r\n/\n/g;
	$text =~ s/^\s+|\s+$//g;
	my $now = &subs::rightNow();
	my $exists = $uuid ? &subs::db_select('notes', ['uuid'], { uuid => $uuid })->hash : undef;
	my $created = 0;
	if ($exists && $exists->{'uuid'}) {
		&subs::db_update('notes', { text => $text, server_time => $now }, { uuid => $uuid });
	}
	else {
		$uuid = &subs::random_string_creator(21);
		&subs::db_insert('notes', {
			uuid => $uuid,
			app => 'notes',
			text => $text,
			timestamp => $now,
			server_time => $now
		});
		$created = 1;
	}
	&Websocket::send('tab', { console => 'notesReload();' });
	$c->render(json => { uuid => $uuid, text => $text, created => $created });
};

post '/manager/note_delete' => sub($c) {
	# The Notes app's X (two-click: arm, then delete). Notes live in their own
	# table now, so this is scoped to it.
	my $uuid = $c->param('uuid');
	&subs::db_delete('notes', { uuid => $uuid });
	&Websocket::send('tab', { console => 'notesReload();' });
	$c->render(json => { uuid => $uuid });
};

post '/manager/note_to_appt' => sub($c) {
	# A note dragged onto an appointment window. Dropped on one of the window's
	# appointment rows (an .appointment_detail, which carries its own uuid) the
	# note's text is appended to THAT appointment's notes; dropped anywhere else on
	# the window it becomes a new appointment for the app. Either way the notes are
	# encrypted exactly the way manager_reset encrypts a reset's notes.
	my $uuid = $c->param('uuid');
	my $app = &subs::unformat_name($c->param('app'));
	my $appt_uuid = $c->param('appt_uuid');
	my $note = &subs::db_select('notes', undef, { uuid => $uuid })->hash;
	return $c->render(json => { error => 'no such note' }) unless $note && defined $note->{'text'};
	my $text = $note->{'text'};
	my $suds = &subs::session_suds($c);
	my $now = &subs::rightNow();
	if ($appt_uuid) {
		my $appt = &subs::db_select('appointments', undef, { uuid => $appt_uuid })->hash;
		return $c->render(json => { error => 'no such appointment' }) unless $appt && $appt->{'uuid'};
		my $existing = $appt->{'notes'} ? &subs::note_decrypter($suds, $appt->{'notes'}, $appt->{'server_time'}) : '';
		$existing .= "\n" if $existing =~ /\S/;
		&subs::db_update('appointments', { notes => &subs::note_encrypter($suds, $existing . $text), server_time => $now }, { uuid => $appt->{'uuid'} });
		&Websocket::send('tab', { console => 'appointmentDetailGrabber("' . $app . '","' . $appt->{'uuid'} . '");' });
		return $c->render(json => { app => $app, uuid => $appt->{'uuid'}, created => 0 });
	}
	my $new_uuid = &subs::random_string_creator(21);
	&subs::db_insert('appointments', {
		app => $app,
		timestamp => $now,
		server_time => $now,
		type => 'note',
		pos => &subs::setting_grabber({ app => $app, setting => 'pos' }),
		notes => &subs::note_encrypter($suds, $text),
		uuid => $new_uuid,
		seen => 'yes'
	});
	&Websocket::send('tab', { console => 'appointmentDetailGrabber("' . $app . '","' . $new_uuid . '");' });
	$c->render(json => { app => $app, uuid => $new_uuid, created => 1 });
};

sub notification_grabber($data) {

	my $timestamp = &subs::rightNow();
	my @notifications;
	my $settings = &subs::settings_grabber({ app => 'notifications', benign => 1 });
	my $notifications = { titles => [], apps => [], settings => $settings };
	my ($db,$database,$sql) = &subs::database_grabber();
	my $q = &subs::db_query('select * from notifications order by timestamp DESC LIMIT 100');
	my $more_notifications = $q->hashes;
	if ($device eq 'mobile') {
		my $nl = `termux-notification-list`;
		my $notifications = decode_json($nl);
		my @fresh;
		foreach my $n ( @{$notifications} ) {
			if ($n->{'title'} && !grep { $_->{'id'} eq $n->{'id'} } @{$more_notifications}) {
				my $ts = &subs::ago_calc($n->{'when'},$timestamp);
				&subs::db_insert('notifications', {
					id => $n->{'id'},
					app => &subs::unformat_name($n->{'title'}),
					timestamp => $ts,
					tag => $n->{'tag'},
					message => $n->{'content'},
					title => $n->{'title'},
					key => $n->{'key'},
					image => "/images/make believe/face.png",
					uuid => &subs::random_string_creator(20)
				});
				push @fresh, { key => $n->{'key'}, message => $n->{'content'}, title => $n->{'title'}, timestamp => $ts };
			}
		}
		# a payment the phone has announced is booked as it lands, not when a
		# screen is opened later
		&notification_payable_autobook(\@fresh) if scalar @fresh;
	}

	$q = &subs::db_query('select * from notifications order by timestamp DESC');
	$more_notifications = $q->hashes;

	foreach my $m ( @{$more_notifications}) {
		push @{$notifications->{'apps'}}, $m->{'app'} unless grep { $m->{'app'} eq $_ } @{$notifications->{'apps'}};
	}

	if ($settings->{'filter'} && $settings->{'filter'} ne '' && $settings->{'filter'} ne 'all') {
		@{$more_notifications} = grep { $_->{'app'} eq $settings->{'filter'} } @{$more_notifications};
	}
	if ($settings->{'search'} && $settings->{'search'} ne '') {
		my $search = $settings->{'search'};
		@{$more_notifications} = grep { $_->{'app'} =~ /\Q$search/gi ||  $_->{'message'} =~ /\Q$search/gi } @{$more_notifications};
	}
	if ($data->{'scroll'} eq 'down') {
		my @now_notifications = splice @{$more_notifications}, $data->{'position'} * 100;
		@{$more_notifications} = @now_notifications;

	}
	unless ($data->{'delete'}) {
		splice @{$more_notifications}, 100;
	}
	my $content;

	my $c = &subs::controller_builder();
	foreach my $m ( @{$more_notifications}) {
		$notifications->{'content'} .= $c->render_to_string(
			n => $m,
			template => 'notification',
		);
	}
	$notifications->{'list'} = $more_notifications;
	return $notifications;
}

post '/manager/notifications/remove' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $tag = $c->param('tag');
	my $title = $c->param('title');
	my $uuid = $c->param('uuid');
	my $app = $c->param('app');
	my $server_time = $c->param('server_time');
	my $scope = $c->param('scope');
	my ($db,$database,$sql) = &subs::database_grabber();
	my $deletions = [];
	if ($tag) {
		if ($device eq 'mobile') {
			`termux-notification-remove $tag`;
		}
	}
	if ($scope eq 'all') {
		my $notifications = &notification_grabber({ delete => 'yes' });
		foreach my $n ( @{$notifications->{'list'}} ) {
			&subs::db_delete('notifications', { uuid => $n->{'uuid'} });
			push @{$deletions}, $n->{'uuid'};
			&deletion_registration({ table => 'notifications', uuid => $n->{'uuid'}, server_time => $n->{'server_time'} });
		}
	}
	else {
		&subs::db_delete('notifications', { timestamp => $timestamp, title => $title, uuid => $uuid });
		&deletion_registration({ table => 'notifications', uuid => $uuid, server_time => $server_time });
		push @{$deletions}, $uuid;
	}
	$c->render(json => $deletions );
};

get '/manager/notifications/filter' => sub($c) {
	my $app = $c->param('app');
	&subs::setting_setter({ app => 'notifications', setting => 'filter', value => $app });
	my $returner = notification_grabber({});
	$c->render(json => $returner);
};

get '/manager/notifications/search' => sub($c) {
	my $search = $c->param('search');
	&subs::setting_setter({ app => 'notifications', setting => 'search', value => $search });
	my $returner = &notification_grabber({});
	$c->render(json => $returner);
};

get '/manager/notifications/scroll' => sub($c) {
	my $returner = &notification_grabber({ scroll => 'down', position => $c->param('position') });
	$c->render(json => $returner);
};

get '/manager/configure/backup_now' => sub($c) {
	# The sync rail is gate-exempt (hooks.pl) because a peer's session cookie
	# lapses and a gated reply - the Gate page, not JSON - silently stalled the
	# merge. Authorize here instead: the UI's own session, or a peer that signs
	# the request against its roster row, exactly like the rest of the peer rail.
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($c->session('authentication') eq 'approved' || ($rm && &subs::peer_verify($c, $rm))) {
		$c->rendered(403);
		return;
	}
	unless ($c->param('reason')) {
		$c->param('reason' => 'backup');
	}
	else {
		my $remote_ip = $c->tx->remote_address;
	}
	my $disposition = &subs::backup_now($c);
	$c->render(json => $disposition);
};

post '/manager/configure/delete_backup' => sub($c) {

	my $backup = $c->param('filename');
	if (-e $backup) {
		`shred -u $backup`;
	}
	$c->render(text => 'backup deleted');
};


get '/manager/appointment_viewer' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $readable = $c->param('readable');
	my $timeshift = $c->param('timeshift');
	my $scope = $c->param('scope');
	my $sorts = $c->param('sorts');
	my $time_machine = $c->param('time_machine');
	my $filter = $c->param('filter');
	my $account = $c->param('account');
	my $project = $c->param('project');
	my $appt_view_toggle = $c->param('appt_view_toggle');
	my $layout = $c->param('layout');
	my $stats = eval { return decode_json $c->param('stats') } || {};
	my $timeshift_max;
	my $chosen_appts;
	if ($c->param('appts')) {
		$chosen_appts = decode_json $c->param('appts');
	}
	else { $chosen_appts = \@appointments; }
	if ($time_machine) {
		$timestamp = &time_machine_resolve($time_machine,$timestamp);
	}
	# The centre the time machine alone stands for. The timeline writes a slide back
	# into #time_machine as a relative string, and that string must anchor here -
	# anchoring it on the final centre would fold the separate timeshift into it,
	# and the server would apply the timeshift a second time on every poll, so the
	# view marched further back with every slide.
	my $time_machine_timestamp = $timestamp;
	if ($timeshift && $timeshift =~ /[0-9]/) {
		$timestamp = &subs::ago_calc($timeshift,$timestamp);
	#	$timestamp = $timestamp - ($timeshift);
	}
	my $period = eval { &subs::time_span($scope, $timestamp) };

	my $appts = &log_reader({
		appts => $chosen_appts,
		project => $project,
		account => $account,
		scope => $scope,
		sorts => $sorts,
		'timestamp' => $timestamp,
		filter => $filter,
		appt_view_toggle => $appt_view_toggle,
		view => 'appointment_viewer',
		stats => $stats
	});
	$appts->{'__specs'}->{'layout'} = $layout;
	$appts->{'__specs'}->{'time_machine_timestamp'} = $time_machine_timestamp;
	if ($appts->{'updateable'} eq 'no') {
		$c->render(json => { updateable => 'no', '__specs' => $appts->{'__specs'} });
		$c->rendered;
		return;
	}
	my @results;
	my @log_watch;
	foreach my $a (@{$chosen_appts}) {
		next if $appts->{$a}->{'setting'}->{'visible'} eq 'unchecked';



		foreach my $type (qw/list/) {
			last unless $appts->{$a}->{$type};
			if (@{$appts->{$a}->{$type}} && scalar @{$appts->{$a}->{$type}} > 0) {
				if (my @present = grep { $_->{'timestamp'} > $period && $_->{'timestamp'} < ($timestamp + ($timestamp - $period)) } @{$appts->{$a}->{$type}}) {
					$appts->{$a}->{$scope . '_occurrences'} = scalar @present;

					foreach my $p (@present) {

						$p->{'formatted_name'} = &subs::format_name($p->{'app'});

						my $point = $p->{'timestamp'} - $period;
						my $total = $timestamp - $period;
						my $percent = $point / $total;
						$appts->{$a}->{$scope . '_percent'} = $percent;
						if ($p->{'duration'}) {
							my $point = $p->{'timestamp'} - $p->{'duration'} - $period;
							my $total = $timestamp - $period;
							my $percent = $point / $total;
							$p->{$scope . '_start_percent'} = $percent;
						}


						$p->{$scope . '_percent'} = $percent;
						$p->{$scope . '_occurrences'} = $appts->{$a}->{$scope . '_occurrences'};
						$p->{'start_notes'} = undef;
						$p->{'end_notes'} = undef;

						if ($p->{'type'} eq 'transaction') {
							if ($p->{'amount'} && !$p->{'tax'} && $p->{'total'} > $p->{'amount'}) {
								$appts->{$a}->{$scope . '_tax' } += sprintf("%.2f",($p->{'amount'} * 1.13) - $p->{'amount'});
							}
							$appts->{$a}->{$scope . '_tax' } += sprintf("%.2f", ($p->{'tax'})) if $p->{'tax'};
							$appts->{$a}->{$scope . '_total' } += unformat_number($p->{'total'} || $p->{'amount'}) if $p->{'total'} || $p->{'amount'};
							$appts->{$a}->{$scope . '_amount' } += unformat_number($p->{'amount'}) if $p->{'amount'};
						}
						$appts->{$a}->{$scope . '_quantity' } += $p->{'quantity'} if $p->{'_occurrences'};
						$appts->{$a}->{'since'} = ($timestamp - $p->{'timestamp'}) / 1000;
						if ($p->{'type'} =~ 'start|pause|record' ) {
							$appts->{$a}->{'setting'}->{'status'} = $p->{'type'};
							$appts->{$a}->{$scope . '_duration'} += $timestamp - $p->{'timestamp'};
							$appts->{$a}->{'formatted_since'} = &subs::duration_sayer(($timestamp - $p->{'timestamp'}) / 1000);

						}
						else {
							$appts->{$a}->{$scope . '_duration'} += abs $p->{'duration'} || $appts->{$a}->{'setting'}->{$scope . '_duration'} if (abs $p->{'duration'} || $appts->{$a}->{'setting'}->{$scope . '_duration'});
							$appts->{$a}->{'formatted_since'} = &subs::duration_sayer(($timestamp - $appts->{$a}->{'last_reset'}) / 1000) if $appts->{$a}->{'last_reset'};
						}
						$appts->{$a}->{'formatted_since'} = 'in ' . $appts->{$a}->{'formatted_since'} if ($timestamp - $p->{'timestamp'}) < 0;

						$appts->{$a}->{$scope . '_timestamp'} = $p->{'timestamp'};

						if ($sorts eq 'log') {
							push @{$appts->{'__logwatch'}}, $p;
						}
						foreach my $ts ( &subs::time_span_list() ) {
							if ($type eq 'list') {
								$appts->{'__stash'}->{$ts . '_total_' . $sorts} += (unformat_number($p->{'total'} || $p->{'amount'})) if $p->{'total'} || $p->{'amount'};
							}
							else {
								$appts->{'__stash'}->{$ts . '_total_' . $sorts} += -(unformat_number($p->{'total'} || $p->{'amount'})) if $p->{'total'} || $p->{'amount'};
							}

						}
						$appts->{$a}->{$scope . '_duration_percent'} =  ($appts->{$a}->{$scope . '_duration'} / abs &subs::time_span($scope, 0)) * 100 if $appts->{$a}->{$scope . '_duration'};
						$appts->{$a}->{$scope . '_duration_percent'} = sprintf("%.2f",$appts->{$a}->{$scope . '_duration_percent'}) . "%" if ($appts->{$a}->{$scope . '_duration_percent'} );
					}
				}

			}
			$appts->{$a}->{$scope . '_formatted_duration'} = &subs::duration_sayer($appts->{$a}->{$scope . '_duration'} / 1000) if $appts->{$a}->{$scope . '_duration'};
		}
	};
	# Ghost appointments: the events an app's records say will probably happen, that
	# are not scheduled - drawn faded ahead of now. Gated on the delorean toggle,
	# and only within the view the clock is showing.
	if ((&subs::setting_grabber({ app => 'keyboard', setting => 'ghost_appointments' }) || '') eq 'checked') {
		my $ghost_now = &subs::rightNow();
		my $ghost_end = (defined $period && $period) ? ($timestamp + ($timestamp - $period)) : $timestamp;
		foreach my $a (@{$chosen_appts}) {
			next if $appts->{$a}->{'setting'}->{'visible'} eq 'unchecked';
			my $g = &subs::ghost_rows_for($a, $ghost_now, $ghost_end);
			$appts->{$a}->{'ghosts'} = $g if scalar @{$g};
		}
	}
	$appts->{'__specs'}->{'pseudonyms'} = &pseudonym_maker('viewer','');
	my $clothesline = eval { return decode_json &subs::setting_grabber({ app => '__president', setting => 'clothesline' }) } || [];
	if ($c->param('background_images') eq 'on') {
		$appts->{'__specs'}->{'backgrounds'} = eval { return decode_json &subs::setting_grabber({ app => 'marker', setting => 'backgrounds' }) } || [];
		$appts->{'__specs'}->{'background'} = $appts->{'__specs'}->{'backgrounds'}->[rand(scalar @{$appts->{'__specs'}->{'backgrounds'}})];
	}
	$c->render(
		json => {
			appts => $appts,
			timestamp => $timestamp,
			clothesline => $clothesline
		}
	);
};

# The desk's own rail. With the desk as the background there is no timeline or
# leaderboard to build, so desk.js asks this instead of appointment_viewer once a
# minute: the stored clothesline, and the picture when the background is on.
get '/manager/clothesline_rail' => sub($c) {
	my $clothesline = eval { return decode_json &subs::setting_grabber({ app => '__president', setting => 'clothesline' }) } || [];
	my %payload = ( clothesline => $clothesline, timestamp => &subs::rightNow() );
	if (($c->param('background_images') || '') eq 'on') {
		my $backgrounds = eval { return decode_json &subs::setting_grabber({ app => 'marker', setting => 'backgrounds' }) } || [];
		$payload{'backgrounds'} = $backgrounds;
		$payload{'background'} = $backgrounds->[ int(rand(scalar @{$backgrounds})) ] if scalar @{$backgrounds};
	}
	$c->render(json => \%payload);
};

