get '/manager/centre_view' => sub($c) {
	# the app arrives either as its JSON object or as a bare name. A bare name
	# used to fall through and then be dereferenced as a hash ("Can't use
	# string as a HASH ref"), which killed the worker and dropped the
	# connection instead of answering - the app's own centre_view calls always
	# carry the object, but the watch, the boards and any hand-made request do
	# not, and they took the worker down with them.
	my $ap = eval { return decode_json $c->param('app') };
	$ap = { name => $c->param('app'), app => $c->param('app') } if ref $ap ne 'HASH';
	my $app = $ap;
	my $jp_report = eval { return decode_json $c->param('jp_report') } || {};
	my $timestamp = $c->param('timestamp');
	if ($app->{'name'}) {
		&padlock_time_extender($c);
		my $window = &centre_view_grabber({ c => $c, app => $app->{'name'}, timestamp => $timestamp, jp_report => $jp_report });
		if ($c->param('source') ne 'ws') {
			&Websocket::send('tab', { browser_tab_id => $c->param('browser_tab_id'), not_me => 1, console => 'appointmentGrabber(\'' . $app->{'name'} . '\',\'' . $timestamp .'\',\'ws\');' });
		}
	#	&Websocket::send('tab', { browser_tab_id => $c->stash('browser_tab_id'), app => $app, window => $window, timestamp => $timestamp, not_me => 1 });
		$c->render(text => $window);
	}
	else {
		$c->render(text => '');
	}
};

sub centre_view_grabber($data) {
	my $c = $data->{'c'} || &subs::controller_builder();
	my $app = $data->{'app'};
	my $timestamp = $data->{'timestamp'};
	my $jp_report = $data->{'jp_report'} || [];
	$app = &subs::unformat_name($app);
	my $server_time = &subs::rightNow();

	if ($app) {
		my $appointments = [ $app ];
		my $signature = &subs::render_signature();
		if (my $cache_data = &subs::cache_get({ context => 'template', app => $app })) {
			if (($cache_data->{'signature'} || '') eq $signature && ($data->{'cached'} ne 'no' || $cache_data->{'timestamp'} + 200 > $server_time)) {
				my $window = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => $app, contents => $cache_data->{'contents'} }, $timestamp);
				return $window;
			}
		}
		my $string;
		my $appointment = &subs::db_query('select app,server_time,timestamp from appointments where app=? LIMIT 1',$app);
		# the header worker hands its appointments over so this render does not
		# fetch the same set again
		my $appts = $data->{'appts'} || &log_reader({ app => $app, view => 'centre_view'  });
		if (!$appts->{$app}) {
			$string = $c->render_to_string(
				template => 'denial',
			);
			$app = 'Denied';
		} else {
			# a header-only log_reader skipped the pos/mab markers; the wrapper's
			# details form needs them, so build them once here
			my $markers = (ref $appts->{'__specs'} eq 'HASH') ? ($appts->{'__specs'}->{'markers'} || '') : '';
			&appts_marker_builder($appts) if $markers ne 'yes';
			$appts->{$app}->{'setting'}->{'app_measures'} = eval { return decode_json $appts->{$app}->{'setting'}->{'app_measures'} } || {};
			my $header = $data->{'header'};
			unless ($header || $data->{'resetting'} eq 'yes' || $data->{'cached'} eq 'no') {
				my $hc = &subs::cache_get({ app => $app, context => 'header' });
				$header = $hc->{'header'} if ($hc->{'signature'} || '') eq $signature;
			}
			unless ($header) {
				$header = &subs::appt_header_printer({ appts => $appts, app => $app, timestamp => $timestamp, source => 'centre_view_grabber' });
			}
			$string = $c->render_to_string(
				template => 'appointment_wrapper',
				appts => $appts,
				appointments => $appointments,
				header => $header,
				timestamp => $timestamp,
				device => $device,
				from => 'centre_view',
				config => &subs::config_reader(),
				measures => $gb::measures,
				server_time => $server_time,
				jp_report => $jp_report
			);
		}
		my $window = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => $app, contents => $string, source => 'centre_view_grabber', settings => $appts->{$app}->{'setting'} }, $timestamp);
		&subs::subprocessor(sub {
			&subs::cache_set({app => $app, context => 'template', warranty => '-10d' }, { contents => $string, settings => $window->{'settings'}, signature => $signature });
		}, { name => 'centre view cache set' });
		return $window->{'window'};
	}
}

# The entry a setting wears for this device: the device's own row, then the
# house-wide ('all') one, then whatever row there is.
sub search_index_setting($set, $device) {
	return undef unless ref $set eq 'HASH' && scalar keys %{$set};
	return (defined $device && exists $set->{$device}) ? $set->{$device}
		: (exists $set->{'all'} ? $set->{'all'} : (values %{$set})[0]);
}

# Has anything the search list draws changed? Every write through setting_setter
# stamps a fresh server_time, and a delete (a removed app or its last setting)
# moves the count, so these two aggregates are the cheap watch. The icon set is
# included because the row pictures follow it; manager_background_colour picks
# the light or dark cut of that set.
sub search_index_signature {
	my $s = &subs::db_query("select count(*) as n, max(cast(server_time as integer)) as t from settings where setting in ('pos','visible','main_image','icon_set','manager_background_colour')")->hashes->[0] || {};
	my $g = &subs::db_query('select count(*) as n, max(cast(server_time as integer)) as t from appointments where account = ?', 'gallery')->hashes->[0] || {};
	return join ':', ($s->{'n'} // 0), ($s->{'t'} // 0), ($g->{'n'} // 0), ($g->{'t'} // 0);
}

# The picture an app's search row wears: the same one its window does - the
# app's own main image first, then the built-in drawing, then the pos tile.
sub search_index_icon($data) {
	my $app = $data->{'app'};
	my $main_image = $data->{'main_image'} || '';
	if (length $main_image) {
		return $main_image if $main_image =~ /^data:/;
		my ($destination, $asset) = &subs::file_device_renamer({ file => $main_image, app => $app, type => 'image' });
		if (defined $destination && defined $asset && -e ($destination . $asset)) {
			# the setting's own stamp keeps a replaced picture from being read
			# back out of the browser's cache under the same path
			my $stamp = $data->{'stamp'} || '';
			return '/file_open?file=' . $destination . $asset . (length $stamp ? '&v=' . $stamp : '');
		}
	}
	if ($gb::known_appts->{$app} && $gb::known_appts->{$app}->{'icon'}) {
		return &subs::icon_for($gb::known_appts->{$app}->{'icon'});
	}
	if (length($data->{'pos'} || '') && -e 'public/icons/pos/' . $data->{'pos'} . '.png') {
		return &subs::icon_for('/icons/pos/' . $data->{'pos'} . '.png');
	}
	return &subs::icon_for('/images/decipherable/gear.png');
}

# The whole searchable app list, read once by the manager and filtered in the
# browser. The settings table is small enough to hand over in one go, which is
# what makes typing local (and so instant) instead of a request per keystroke.
# Each entry is the key a window opens with, the name a person reads, and the
# icon the window wears. `version` lets the manager ask a tiny question - "has
# anything changed?" - without pulling the list again while it is unchanged.
get '/manager/search_index' => sub($c) {
	my $version = &search_index_signature();
	if ($c->param('check')) {
		$c->render(json => { version => $version });
		return;
	}
	my $rows = &subs::db_query("select app, device, setting, value, server_time from settings where app is not null and app != '' and setting in ('pos','visible','main_image')")->hashes;
	my %settings_by_app;
	foreach my $r ( @{$rows} ) {
		next unless defined $r->{'app'} && length $r->{'app'};
		$settings_by_app{$r->{'app'}}->{$r->{'setting'}}->{$r->{'device'} || ''} = { value => $r->{'value'}, server_time => $r->{'server_time'} };
	}
	# the music player writes the tracks it plays with account gallery, and the
	# dock's search is not the place for those to surface as apps
	my $gallery = {};
	foreach my $g ( @{ &subs::db_query('select distinct app from appointments where account = ? and app is not null', 'gallery')->hashes } ) {
		$gallery->{$g->{'app'}} = 1;
	}
	my (@apps, %indexed);
	foreach my $app ( sort keys %settings_by_app ) {
		my $s = $settings_by_app{$app};
		my $vis_entry = &search_index_setting($s->{'visible'}, $device);
		my $visible = defined $vis_entry ? (ref $vis_entry eq 'HASH' ? $vis_entry->{'value'} : $vis_entry) : 'checked';
		next if (($visible // '') ne 'checked');
		# a known app stays even when it has gallery rows; those rows are its work
		next if $gallery->{$app} && !$gb::known_appts->{$app};
		my $pos_entry = &search_index_setting($s->{'pos'}, $device);
		my $pos = defined $pos_entry ? (ref $pos_entry eq 'HASH' ? $pos_entry->{'value'} : $pos_entry) : '';
		my $mi_entry = &search_index_setting($s->{'main_image'}, $device);
		my $main_image = defined $mi_entry ? (ref $mi_entry eq 'HASH' ? $mi_entry->{'value'} : $mi_entry) : '';
		my $stamp = ref $mi_entry eq 'HASH' ? ($mi_entry->{'server_time'} || '') : '';
		push @apps, { app => $app, name => &subs::format_name($app), icon => &search_index_icon({ app => $app, pos => $pos, main_image => $main_image, stamp => $stamp }) };
		$indexed{$app} = 1;
	}
	# the menu's own apps are code, not appointments: help, folders and mailbox
	# carry no visible row at all, and some have no appointment history either,
	# yet the box should still find and open them
	my %builtin = map { $_ => 1 } qw(
		configure handbook budget travel mailbox music embedded box_office cards security
		terminal ide gallery synth editor marker twirl studio store relational web warehouse
		measures folders process_monitor market notes phone people email chat pen help
	);
	foreach my $app ( sort keys %builtin ) {
		next if $indexed{$app};
		# a built-in with no visible row is always an app; one the person has
		# explicitly hidden stays hidden
		next if $settings_by_app{$app} && $settings_by_app{$app}->{'visible'};
		push @apps, { app => $app, name => &subs::format_name($app), icon => &search_index_icon({ app => $app }) };
	}
	$c->render(json => { apps => \@apps, version => $version });
};

get '/manager/keyup_search' => sub($c) {
	my $search = $c->param('search');
	my $timestamp = $c->param('timestamp');
	if ($search) {
		my $movement;
		($search,undef,$movement) = &subs::typesetter(&subs::unformat_name($search),'no');
		$search = &subs::format_name($search);
		my @search = split ' ', $search;

		$search = join '%', @search;

		$search = '%' . $search . '%';
		my ($db) = &subs::database_grabber();
		# the music player writes the tracks it plays with account gallery, and the
		# dock's search is not the place for those to surface as apps
		my $results = &subs::db_query('select DISTINCT(app) from settings where device = ? and setting=? and value = ? and app like ? and app not in (select distinct app from appointments where account = ? and app is not null) LIMIT 7', $device, 'visible','checked', $search, 'gallery')->hashes;
		my $resulted = $c->render_to_string(template => 'search/manager', results => $results);

		$c->render(json => { results => $resulted, count => scalar @{$results}, timestamp => $timestamp });
	}
	else {
		$c->render(json => { count => 0, timestamp => $timestamp });
	}
};

get '/manager/search' => sub($c) {
	my $search = &subs::unformat_name($c->param('search')) || &subs::unformat_name($c->param('s'));
	my $chosen_appts = $c->param('chosen_appts');
	my $timestamp = $c->param('timestamp');

	my $appts = &log_reader({ search => $search }) if $search;

	my (@s_appointments);
	my ($template);

	if ($search) {
		while (my ($a, $value) = each %{$appts}) {

			if ($a eq $search) {
				unshift @s_appointments, $a unless grep { lc $_ eq lc $appts->{$a}->{'formatted_name'}} @s_appointments;
				$appts->{$a}->{'header'} = 	&subs::appt_header_printer({ app => $a, timestamp => $timestamp });
			}
			elsif ($a =~ /($search)/) {

				push @s_appointments, $a unless grep { lc $_ eq lc $appts->{$a}->{'formatted_name'}} @s_appointments;
				$appts->{$a}->{'header'} = 	&subs::appt_header_printer({ app => $a, timestamp => $timestamp });
			}
		}
		@appointments = @s_appointments;
	}
	else { }
	$template = 'appointment_wrapper';
	$appts->{'__stash'}->{'header'} = 'yes';
	my $search_engines = $config->{'search_engines'};
	my $contents;
	if ($timestamp =~ /[0-9]/) {
		$contents = $c->render_to_string(
			template => $template,
			appointments => \@appointments,
			appts => $appts,
			timestamp => $timestamp,
			search => $search,
			device => $device,
			from => 'search',
			config => &subs::config_reader(),
			measures => $gb::measures,
			header => '',
			search_engines => $search_engines
		);

		$contents = &window_maker({ user_agent => $c->param('user_agent'), app => $search, title => 'search', contents => $contents },$timestamp);


	}
	$c->render(text => $contents);
};

