sub search_engine_grabber($c) {

	my $search_engines;
	my $timestamp = (&subs::rightNow());
	my $search = $c->param('search');
	my $website = $c->param('website');
	my $contents = &website_grabber({
		app => $c->param('app'),
		search => $search,
		website => $website,
		timestamp => $timestamp
	});
	my $window_data = { app=> $c->param('app'), contents => &website_grabber($c) };
