get '/manager/terminal' => sub ($c) {

	my $timestamp = $c->param('timestamp');
	my $whoami = `whoami`;
	chomp $whoami;
	my $hostname = `hostname`;
	chomp $hostname;
	my $settings = &subs::settings_grabber({ app => 'terminal' });
	$settings->{'errors'} = eval { return decode_json $settings->{'errors'} } || [];
	$settings->{'log'} = eval { return decode_json $settings->{'log'} } || [];
	$settings->{'errors'} = [] unless ref $settings->{'errors'} eq 'ARRAY';
	$settings->{'log'} = [] unless ref $settings->{'log'} eq 'ARRAY';
	# The files can grow for months. A reader shows the newest page, not the whole
	# archive: hundreds of stale entries made the window slow to draw and hid the
	# one that matters. The counts stay truthful, and the stored arrays are
	# capped where they are written.
	my $errors_total = scalar(@{$settings->{'errors'}});
	my $logs_total = scalar(@{$settings->{'log'}});
	$settings->{'errors'} = [ @{$settings->{'errors'}}[-200 .. -1] ] if $errors_total > 200;
	$settings->{'log'} = [ @{$settings->{'log'}}[-150 .. -1] ] if $logs_total > 150;
	# A fresh terminal used to render every view hidden (the saved view was unset),
	# so the window opened completely blank. Default to the live shell.
	my $view = $settings->{'view'} || 'interactive_terminal';
	$view = 'interactive_terminal' unless grep { $_ eq $view } qw/interactive_terminal terminal errors log/;
	$settings->{'view'} = $view;
	my $font_size = $settings->{'font_size'};
	$font_size = 15 unless (defined $font_size && $font_size =~ /^\d+$/ && $font_size >= 10 && $font_size <= 32);
	# The machine list for the configuration panel. A remote's own stored user and
	# port win; otherwise this machine's login name and the sshd port JawnOS uses.
	my $remote_settings = eval { return decode_json($settings->{'remotes'} || '') } || {};
	my @remotes;
	my %seen_remote;
	foreach my $rm ( @{ &subs::remote_machine_lister({ self => 'no' }) } ) {
		my $host = $rm->{'lan_ip'} || $rm->{'ip'} || $rm->{'fqdn'} || $rm->{'hostname'} || '';
		next unless $host ne '';
		next if $host =~ /^(?:127\.0\.0\.1|localhost|::1)$/i;
		my $key = $rm->{'uuid'} || $rm->{'signatorial'} || $host;
		next if $seen_remote{$key}++;
		my $saved = $remote_settings->{$key} || {};
		push @remotes, {
			key => $key,
			host => $host,
			address => $rm->{'fqdn'} || $rm->{'lan_ip'} || $rm->{'ip'} || $host,
			name => $rm->{'hostname'} || $rm->{'fqdn'} || $host,
			device => $rm->{'device'} || '',
			connection => $rm->{'connection'} || '',
			user => (defined $saved->{'user'} && $saved->{'user'} =~ /^[A-Za-z0-9._@\-]+$/) ? $saved->{'user'} : $whoami,
			port => (defined $saved->{'port'} && $saved->{'port'} =~ /^\d+$/ && $saved->{'port'} > 0 && $saved->{'port'} < 65536) ? $saved->{'port'} : 8022
		};
	}
	@remotes = sort { lc($a->{'name'}) cmp lc($b->{'name'}) } @remotes;
	# One pty per window: the client names the session, the websocket worker keeps
	# it alive. The route only needs an id it can put on the window.
	my $terminal_id = $c->param('terminal_id') // '';
	$terminal_id =~ s/[^A-Za-z0-9_\-]//g;
	$terminal_id = substr($terminal_id, 0, 64);
	$terminal_id = 't' . &subs::random_string_creator(12) if length($terminal_id) < 4;
	my $window_name = $c->param('window_name') // '';
	$window_name =~ s/[<>\r\n]//g;
	$window_name = substr($window_name, 0, 80);
	$window_name = &subs::ui('Terminal') unless length $window_name;
	my $session_host = $c->param('session_host') // '';
	$session_host = '' unless $session_host =~ /^[A-Za-z0-9._:\-\[\]]{1,255}$/;
	my $session_user = $c->param('session_user') // '';
	$session_user = '' unless $session_user =~ /^[A-Za-z0-9._\-]{1,64}$/;
	my $session_port = $c->param('session_port') // '';
	$session_port = '' unless $session_port =~ /^\d+$/ && $session_port > 0 && $session_port < 65536;
	# Sessions the websocket worker started and has not seen end. Opening one makes
	# a window that attaches to the pty still running on the server.
	my $session_map = &subs::cache_get({ app => 'terminal', context => 'sessions' }) || {};
	my @open_sessions;
	if (ref $session_map eq 'HASH') {
		foreach my $sid ( keys %{$session_map} ) {
			my $s = $session_map->{$sid};
			next unless ref $s eq 'HASH';
			next unless $sid =~ /^[A-Za-z0-9_\-]{4,64}$/;
			push @open_sessions, {
				id => $sid,
				label => $s->{'label'} || $sid,
				host => $s->{'host'} || '',
				user => $s->{'user'} || '',
				port => $s->{'port'} || '',
				state => $s->{'state'} || 'open',
				at => $s->{'at'} || 0
			};
		}
	}
	@open_sessions = sort { $b->{'at'} <=> $a->{'at'} } @open_sessions;
	splice @open_sessions, 20;
	my $local = { user => $whoami, host => $hostname, label => $whoami . '@' . $hostname, local => 1 };
	my $current = $local;
	my $contents = $c->render_to_string(
		template => 'terminal/terminal',
		window_maker => 'yes',
		whoami => $whoami,
		hostname => $hostname,
		settings => $settings,
		view => $view,
		font_size => $font_size,
		remotes => \@remotes,
		local => $local,
		current => $current,
		errors_total => $errors_total,
		logs_total => $logs_total,
		terminal_id => $terminal_id,
		window_name => $window_name,
		session_host => $session_host,
		session_user => $session_user,
		session_port => $session_port,
		open_sessions => \@open_sessions
	);
	if ($c->param('window_maker') eq 'yes') {
		my $website = &Manager::window_maker({
			user_agent => $c->param('user_agent'),
			app => 'terminal',
			terminal_id => $terminal_id,
			window_name => $window_name,
			contents => $contents
		}, $timestamp);
		$c->render(text => $website);
	}
	else {
		$c->render(text => $contents);
	}
};



post '/manager/terminal/error_report' => sub($c) {
	# The browser's own failures (a route that answered 500, a script that threw)
	# join the same log the server writes to. Keep it bounded and small: this is a
	# reader for a person, not an archive.
	my $errors = eval { return decode_json $c->param('errors') } || [];
	if (ref $errors eq 'ARRAY' && scalar @{$errors} > 0) {
		my $old_errors = eval { return decode_json &subs::setting_grabber({ app => 'terminal', setting => 'errors' }) } || [];
		foreach my $e ( @{$errors} ) {
			next unless ref $e eq 'HASH';
			push @{$old_errors}, {
				timestamp => &subs::rightNow(),
				code => substr($e->{'code'} // 'browser', 0, 40),
				msg => substr($e->{'msg'} // $e->{'message'} // 'unknown browser error', 0, 4000),
				uuid => &subs::random_string_creator(12)
			};
		}
		splice @{$old_errors}, 0, scalar(@{$old_errors}) - 200 if scalar @{$old_errors} > 200;
		&subs::setting_setter({ app => 'terminal', setting => 'errors', value => encode_json $old_errors });
	}
	$c->render(json => []);
};

post '/manager/window_closer' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $app = &subs::unformat_name($c->param('app'));
	# Closing the app closes its padlock: the grant is dropped before the window
	# goes, so reopening it (or the app after a restart) opens locked.
	if (grep { $_ eq $app } @media_unlock_apps) {
		my $device = &media_unlock_device($c);
		&media_unlock_clear($device, $app) if length $device;
	}
	&subs::window_closer($app, $c->param('browser_tab_id'));
	my $settings = &subs::settings_grabber({ app => &subs::unformat_name($app) });

	if ($settings->{'enc'} eq 'on') {
		&subs::file_encrypter({ app => $app, timestamp => $timestamp, suds => &subs::session_suds($c) });
	}
	else {
		&subs::file_decrypter({ app => $app, timestamp => $timestamp, suds => &subs::session_suds($c) });
	}
	$c->render('text' => 'ok');
};

post '/manager/terminal' => sub ($c) {
	my $timestamp = $c->param('timestamp');
	$c->render(text => 'ok');

	if ($c->param('command') eq 'telephone') {
		&subs::telephone_contacts_check();
		&subs::telephone_call_log_check();
	}
	else {
		my $return = &subs::run_command('terminal',$c->param('command'),$timestamp);
	}
	$c->render('text' => 'ok');
};

# The Gallery shell. The old route built every tile into the response and let
# /file_open make missing thumbnails inside the request; a library opened that
# way held every prefork worker and the rest of the UI stopped answering. The
# tiles now come in pages from /manager/gallery/data, and the client only asks
# for the images it is about to show.
get '/manager/gallery' => sub ($c) {
	my $permissive = media_unlock_open($c, 'gallery') ? 1 : 0;
	my $unlock = $permissive ? ($c->param('unlock') || '') : '';
	my $settings = &subs::settings_grabber({ app => 'gallery' });
	my $contents = $c->render_to_string(
		template => 'apps/gallery',
		unlock => $unlock,
		permissive => $permissive,
		settings => $settings,
		c => $c
	);
	my $website = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'gallery', contents => $contents }, $c->param('timestamp') || &subs::rightNow());
	$c->render(json => { window => $website, locked => ($permissive ? 0 : 1), unlock => $unlock });
};

# One page of tiles. A tile carries the thumbnail it should show (the stored
# one when there is one) and the full file for the viewer.
get '/manager/gallery/data' => sub ($c) {
	my $permissive = media_unlock_open($c, 'gallery') ? 1 : 0;
	my $revealed = $permissive ? 1 : 0;
	my $search = lc($c->param('search') || '');
	my $sort = ($c->param('sort') || 'desc') eq 'asc' ? 'asc' : 'desc';
	my $offset = int($c->param('offset') || 0);
	my $limit = int($c->param('limit') || 160);
	$limit = 160 if $limit < 1 || $limit > 300;
	my $apps = eval { return decode_json $c->param('apps') } || [];
	$apps = [] unless ref $apps eq 'ARRAY';
	my $jfiles = $c->param('files');
	my $settings = &subs::settings_grabber({ app => 'gallery' });
	my @all;
	my %albums;
	my %hidden_albums;
	my %aset_cache;
	my $uenc = sub {
		my $v = shift;
		return '' unless defined $v;
		my $copy = "$v";
		# uri_encode is pure Perl and costs half a millisecond a call; a gallery
		# page builds four URLs per tile, which was over a second per page and
		# held a worker that long. This is the same encoding, and it also escapes
		# # and ? that the old one left to break the query.
		utf8::encode($copy) if utf8::is_utf8($copy);
		return url_escape($copy, '^A-Za-z0-9\-._~/')
	};
	my $archive_lookup;

	my $tile_for = sub {
		my ($app, $appt, $f, $explicit) = @_;
		my $path = $f->{'f'} || '';
		return undef unless length $path;
		my $type = $f->{'type'} || $appt->{'type'} || 'image';
		my $server_time = $f->{'server_time'} || $appt->{'server_time'} || 0;
		# The app's own timestamp is when the thing happened; server_time is when
		# the row was written or synced, which can be days later. Sort and date by
		# the former when the appointment carries one.
		my $sort_time = $appt->{'timestamp'} || $f->{'timestamp'} || $f->{'server_time'} || $server_time || 0;
		# A row synced from another machine keeps that machine's path. The copy on
		# this one lives under its own photo (or video) location, and the same
		# renamer the rest of the manager uses maps it there. Without this a phone
		# shows only the photos it took itself, and a laptop trips over a
		# main_image that names a phone path.
		if (!-e $path) {
			my ($dir, $asset) = &subs::file_device_renamer({ file => $path, app => $app, type => $type });
			my $local = (defined $dir && defined $asset) ? $dir . $asset : '';
			$path = $local if length $local && -e $local;
		}
		# The padlock is for what the person hid, not for every sealed file: an
		# album marked visible is theirs to browse, so only a hidden album's
		# photos wait for an unlock. A list handed over by another app (Folders,
		# the IDE) has already been through that app's own rule - the file was
		# chosen from a listing the person could see - and it is not one of this
		# gallery's albums, so its names are not filtered again here.
		if (!$explicit) {
			my $aset = $aset_cache{$app} ||= &subs::settings_grabber({ app => $app, settings => ['main_image', 'visible'] });
			my $app_visible = (($aset->{'visible'} || '') eq 'checked') ? 1 : 0;
			return undef if !$permissive && !$app_visible && $path =~ /\.enc$/i;
		}
		if (!-e $path && !$f->{'remote_uuid'}) {
			return undef unless ($settings->{'archive'} || '') eq 'on';
			$archive_lookup = &subs::archive_image_lookup({}) unless $archive_lookup;
			my $archived = ($archive_lookup && $archive_lookup->{'locate'}) ? $archive_lookup->{'locate'}->($path) : undef;
			return undef unless $archived;
			$path = $archived->{'path'};
			$f->{'f'} = $path;
			$f->{'remote_uuid'} = $archived->{'remote_uuid'};
		}
		if ($f->{'thumb'} && !-e $f->{'thumb'}) {
			my ($tdir, $tasset) = &subs::file_device_renamer({ file => $f->{'thumb'}, app => $app, type => $type });
			my $tlocal = (defined $tdir && defined $tasset) ? $tdir . $tasset : '';
			$f->{'thumb'} = $tlocal if length $tlocal && -e $tlocal;
		}
		my $thumb_ok = ($f->{'thumb'} && -e $f->{'thumb'} && (-s $f->{'thumb'}) > 100) ? 1 : 0;
		my $thumb_path = $thumb_ok ? $f->{'thumb'} : $path;
		my $thumb = '/file_open?file=' . $uenc->($thumb_path)
			. '&app=' . $uenc->($app)
			. '&app_uuid=' . $uenc->($appt->{'uuid'} || '')
			. '&timestamp=' . $uenc->($server_time)
			. ($f->{'uuid'} ? '&file_uuid=' . $uenc->($f->{'uuid'}) : '')
			# a photo living on a peer (or the archive) must relay its thumb too,
			# not just the full-size file the viewer asks for
			. ($f->{'remote_uuid'} ? '&remote_uuid=' . $uenc->($f->{'remote_uuid'}) : '')
			. ($thumb_ok ? '' : '&thumb=ya');
		my $full = '/play?app=' . $uenc->($app)
			. '&track=' . $uenc->($path)
			. '&timestamp=' . $uenc->($server_time)
			. ($f->{'remote_uuid'} ? '&remote_uuid=' . $uenc->($f->{'remote_uuid'}) : '');
		my $name = $path;
		$name =~ s{.*/}{};
		return {
			uuid => $f->{'uuid'} || '',
			app => $app,
			label => $f->{'label'} || &subs::format_name($app),
			app_uuid => $appt->{'uuid'} || '',
			type => $type,
			f => $path,
			name => $name,
			thumb => $thumb,
			file => $full,
			server_time => $server_time,
			sort_time => $sort_time,
			timestamp => $appt->{'timestamp'} || 0,
			remote_uuid => $f->{'remote_uuid'} || '',
			info => $f->{'info'} || {},
		};
	};

	if ($jfiles) {
		my $files = eval { return decode_json $jfiles } || [];
		foreach my $f ( @{$files} ) {
			my $app = $f->{'app'} || 'ide';
			my $tile = $tile_for->($app, { timestamp => &subs::rightNow(), server_time => &subs::rightNow(), uuid => &subs::random_string_creator(12), type => $f->{'type'} || 'image' }, $f, 1);
			next unless $tile;
			push @all, $tile;
		}
	}
	else {
		my $rows = &subs::db_query('select * from appointments where file is not null and (type = ? or type = ?) order by timestamp', 'image', 'video')->hashes;
		foreach my $appt ( @{$rows} ) {
			my $app = $appt->{'app'} || '';
			next if scalar @{$apps} && !grep { $_ eq $app } @{$apps};
			my $aset = $aset_cache{$app} ||= &subs::settings_grabber({ app => $app, settings => ['main_image', 'visible'] });
			if ((($aset->{'visible'}) || '') ne 'checked' && $revealed == 0) { $hidden_albums{$app} = 1; next; }
			my $files = eval { return decode_json $appt->{'file'} } || [];
			foreach my $f ( @{$files} ) {
				next if $search && index(lc($app), $search) < 0 && index(lc($f->{'f'} || ''), $search) < 0;
				my $tile = $tile_for->($app, $appt, $f);
				next unless $tile;
				push @all, $tile;
				my $album = $albums{$app} ||= { app => $app, label => &subs::format_name($app), count => 0, cover => '' };
				$album->{'count'}++;
				$album->{'cover'} ||= $tile->{'thumb'};
			}
		}
		# a chosen cover beats the newest photo
		foreach my $album ( values %albums ) {
			my $main = &subs::setting_grabber({ app => $album->{'app'}, setting => 'main_image' });
			next unless defined $main && length $main;
			# the choice may name a path from the machine that set it; this
			# machine's copy is under its own location
			if (!-e $main) {
				my ($dir, $asset) = &subs::file_device_renamer({ file => $main, app => $album->{'app'}, type => 'image' });
				my $local = (defined $dir && defined $asset) ? $dir . $asset : '';
				$main = $local if length $local && -e $local;
			}
			# a cover the tiles can already show is cheapest from its stored thumb
			my ($tile) = grep { ($_->{'f'} || '') eq $main } @all;
			if ($tile) { $album->{'cover'} = $tile->{'thumb'}; }
			elsif (-e $main) {
				$album->{'cover'} = '/file_open?file=' . $uenc->($main) . '&app=' . $uenc->($album->{'app'}) . '&thumb=ya';
			}
			# A choice that resolves to nothing on this machine (a photo taken on
			# the phone that never synced) keeps the newest photo's cover above.
		}
	}

	my @ordered = sort { $sort eq 'asc' ? $a->{'sort_time'} <=> $b->{'sort_time'} : $b->{'sort_time'} <=> $a->{'sort_time'} } @all;
	my $total = scalar @ordered;
	my @page;
	if ($offset < $total) {
		my $last = $offset + $limit - 1;
		$last = $total - 1 if $last > $total - 1;
		@page = @ordered[$offset .. $last];
	}
	$log->info('gallery data: locked, unlock=' . length($c->param('unlock') || '') . ' albums=' . scalar(keys %albums) . ' total=' . $total . ' revealed=' . $revealed . ' at_home=' . help_at_home())
		if (!$permissive && !$offset);
	$c->render(json => {
		items => \@page,
		total => $total,
		albums => [ sort { $a->{'label'} cmp $b->{'label'} } values %albums ],
		# albums the visibility rule kept out: the window offers its Unlock
		# button for them even on a device whose padlock context list is bare
		hidden => scalar(keys %hidden_albums),
		locked => ($permissive ? 0 : 1),
		unlock => ($permissive ? ($c->param('unlock') || '') : ''),
		sort => $sort,
	});
};

get '/manager/gallery/scroll' => sub($c) {
	my $settings = &subs::settings_grabber({ app => 'gallery' });
	my $apps = eval { return decode_json $c->param('apps') } || [];
	my $search = $c->param('search');
	my $count = $c->param('count');
	my $count_timestamp = $c->param('count_timestamp');
	my $direction = $c->param('direction');
	my $first_count = $c->param('first_count');
	my $returner = { apps => $apps, count => $count, count_timestamp => $count_timestamp };
	my $permissive = media_unlock_open($c, 'gallery') ? 1 : 0;
	my $revealed = $permissive ? 1 : 0;
	$returner->{'html'} = $c->render_to_string(
		template => 'apps/gallery_album',
		settings => $settings,
		asettings => {},
		permissive => $permissive,
		revealed => $revealed,
		pre_count => $count,
		first_count => $first_count,
		view => 'album',
		apps => $apps,
		load => $direction,
		appts => []
	);
	$c->render(json => $returner);
};

get '/manager/file/information' => sub($c) {
	my $file = $c->param('file');
	my $app = $c->param('app');
	my $file_uuid = $c->param('file_uuid');
	my $app_uuid = $c->param('app_uuid');
	my $mouse = eval { return decode_json $c->param('mouse') } || {};
	my $scope = $c->param('scope');
	my $timestamp = $c->param('timestamp');
	my $uuid = &subs::random_string_creator(12);
	my $appt = &subs::db_select('appointments', undef, { uuid => $app_uuid, app => $app })->hashes->[0];
	my $files = eval { return decode_json $appt->{'file'} } || [];
	@{$files} = grep { $_->{'uuid'} eq $file_uuid } @{$files};
	$file = $files->[0];
	if ($file->{'ocr'}) {
		$file->{'ocr'} = &subs::note_decrypter(&subs::session_suds($c), $file->{'ocr'}, $file->{'server_time'});
		$file->{'ocr'} =~ s/\n/<br>/gi;
	}


	my $returner = { app => $app, mouse => $mouse, uuid => $uuid, file => $file, appt => $appt };
	$returner->{'appts'} = &log_reader({ app => $app, timestamp => $appt->{'timestamp'}, filter => 'all', scope => $scope, view => 'appointment_details' });
	$c->param('duty' => 'information');
	my $job = &rock_and_roll($c);

	$returner->{'id'} = 'file_information_' . $uuid;
	$returner->{'html'} = $c->render_to_string(
		template => 'file_information',
		file => $file,
		app => $app,
		mouse => $mouse,
		uuid => $uuid,
		job => $job,
		appt => $appt,
		appts => $returner->{'appts'},
	);
	$c->render(json => $returner);
};

post '/manager/file/information_updater' => sub($c) {
	my $attribute = $c->param('attribute');
	my $file_uuid = $c->param('file_uuid');
	my $app_uuid = $c->param('app_uuid');
	my $app = $c->param('app');
	my $value = $c->param('value');

	my $appt = &subs::db_select('appointments', undef, { app => $app, uuid => $app_uuid })->hashes->[0];
	my $files = eval { return decode_json $appt->{'file'} } || [];

	foreach my $f ( @{$files} ) {
		if ($file_uuid eq $f->{'uuid'}) {
			if ($attribute eq 'warranty') {
				$value = &subs::ago_calc($value, &subs::rightNow());
				$appt->{'warranty'} = $value;
			}
		}
	}
	my $jf = encode_json $files;
	&subs::db_update('appointments', { server_time => &subs::rightNow(), file => $jf, warranty => $appt->{'warranty'} }, { uuid => $appt->{'uuid'}, app => $appt->{'app'} });

	$c->render(json => { value => $value, files => $files, appt => $appt });

};

get '/manager/cards' => sub ($c) {
	my $timestamp = $c->param('timestamp');
	my $mode = &subs::setting_grabber({ app => 'cards', setting => 'mode' });
	my $history = eval { return decode_json &subs::setting_grabber({ app => 'cards', setting => $mode }) } || [];
	my $contents = $c->render_to_string(
		template => 'cards',
		history => $history,
		mode => $mode
	);
	my $website = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'cards', contents => $contents }, $timestamp);
	$c->render('text' => $website);
};


get '/manager/card_picker' => sub ($c) {
	my $timestamp = $c->param('timestamp');
	my $new_card = $c->param('new_card');
	my $tree = &subs::inventory_grabber();

	my $mode = &subs::setting_grabber({ app => 'cards', setting => 'mode' });


	my $history = [];

	if ($mode && $mode ne 'all') {
		$history = eval { return decode_json &subs::setting_grabber({ app => 'cards', setting => $mode }) } || [];
	}
	elsif ($mode eq 'all') {
		my $cards = `ls ./public/images/cards`;
		my @cards = split /\n/, $cards;
		foreach my $ca ( @cards ) {
			my @ca = split /\./, $ca;
			my @stat = stat './public/images/cards/' . $ca;
			push @{$history}, { title => $ca[0], timestamp => $stat[10] * 1000 };
		}
	}

	my ($card,$stream,$title);
	if ($new_card eq 'new') {
		if ($mode eq 'day') {
			$card = &card_of_the_day();
			$title = $card;
			$title =~ s/.png$//gi;
		}
		elsif ($mode eq 'week') {
			$card = &card_of_the_week();
			$title = $card;
			$title =~ s/.png$//gi;
		}
		elsif ($mode eq 'month') {
			$card = &card_of_the_month();
			$title = $card;
			$title =~ s/.png$//gi;
		}
		elsif ($mode eq 'year') {
			$card = &card_of_the_year();
			$title = $card;
			$title =~ s/.png$//gi;
		}
		elsif ($mode eq 'spread') {
			my @cards;
			for (my $n = 0; $n <= 2; $n++) {
				my ($ca,$car);

				$ca = &random_card_picker();
				$car = './public/images/cards/' . &subs::terminal_name($ca);
				while (grep { $car eq $_ } @cards) {

					$ca = &random_card_picker();
					$car = './public/images/cards/' . &subs::terminal_name($ca);

				}

				$cards[$n] = $car;
				my $montage_cmd = 'magick montage ' . $cards[0] . ' ' . $cards[1] . ' ' . $cards[2] . ' -';
				my $montage = `$montage_cmd`;
				$ca =~ s/.png$//gi;
				$title .= &subs::format_name($ca) . '<br> ';
				$stream = 'data:image/png;base64,' . encode_base64 $montage;
				splice @{$history}, 10;
			}
		}
		else {
			$card = &random_card_picker();
			$title = $card;
			$title =~ s/.png$//gi;
		}
	}
	else {
		if ($history->[0]->{'stream'}) {
			$stream = $history->[0]->{'stream'};
			$title = $history->[0]->{'title'};
		}
		else {
			$card = $history->[0]->{'title'} . '.png';
			$title = $history->[0]->{'title'};
		}
	}

	if (($mode eq 'free' || $mode eq 'cycle' || $mode eq 'spread') && $new_card eq 'new') {
		splice @{$history}, 40;
		unshift @{$history}, { title => $title, timestamp => $timestamp, stream => $stream };
		my $jhistory = eval { return encode_json $history };
		&subs::setting_setter({ app => 'cards', setting => $mode, value => $jhistory });
	}

	foreach my $h ( @{$history} ) {
		$h->{'description'} = $tree->{$h->{'title'} . '.png'};

	}
	my $html = $c->render_to_string(
		template => 'cards',
		history => $history,
		mode => $mode
	);
	$c->render(json => {
		html => $html,
		description => $tree->{$card},
		title => &subs::format_name($title),
		filename => $card,
		history => $history,
		mode => $mode,
		stream => $stream
	});
};

sub random_card_picker() {
	my $cards = `ls public/images/cards`;
	my @cards = shuffle split /\n/, $cards;

	@cards = shuffle grep { $_ ne 'title.png' && $_ ne 'back.png' } shuffle @cards;
	my $card = $cards[rand(scalar @cards)];

	return $card;
}

sub card_of_the_day() {
	my $card;
	my $cards = eval { decode_json &subs::setting_grabber({ app => 'cards', setting => 'day' }) } || [];
	splice @{$cards}, 40;
	my $last_card = $cards->[0];
	$card = $last_card->{'title'};
	my @time = localtime($last_card->{'timestamp'} / 1000);
	my @now = localtime(&subs::rightNow() / 1000);

	if ($time[3] != $now[3]) {
		my $new_card = &random_card_picker();
		$new_card =~ s/.png$//gi;
		my $car = { title => $new_card, timestamp => &subs::rightNow() };
		$card = $car->{'title'};
		unshift @{$cards}, $car;
		my $jcards = encode_json $cards;
		&subs::setting_setter({ app => 'cards', setting => 'day', value => $jcards });
	}

	return $card . '.png';
}

sub card_of_the_week() {
	my $card;
	my $cards = eval { decode_json &subs::setting_grabber({ app => 'cards', setting => 'week' }) } || [];
	splice @{$cards}, 40;
	my $last_card = $cards->[0] || {};
	$card = $last_card->{'title'};
	# the week a moment is in, named by the Sunday it opens on, so the card turns
	# over with the week the rest of the house counts - father_time's weeks start
	# on Sunday. This used to divide yday by seven, which drifts across the year
	# and here happened to turn the card on a Monday.
	my $week_opens = sub {
		my $ms = shift || 0;
		my @t = localtime($ms / 1000);
		my $sunday = timegm(0, 0, 0, $t[3], $t[4], $t[5]) - $t[6] * 86400;
		my @d = gmtime($sunday);
		return sprintf('%04d-%02d-%02d', $d[5] + 1900, $d[4] + 1, $d[3]);
	};
	if ($week_opens->($last_card->{'timestamp'}) ne $week_opens->(&subs::rightNow())) {
		my $new_card = &random_card_picker();
		$new_card =~ s/.png$//gi;
		my $car = { title => $new_card, timestamp => &subs::rightNow() };
		$card = $car->{'title'};
		unshift @{$cards}, $car;
		my $jcards = encode_json $cards;
		&subs::setting_setter({ app => 'cards', setting => 'week', value => $jcards });
	}
	return $card . '.png';
}

sub card_of_the_month() {
	my $card;
	my $cards = eval { decode_json &subs::setting_grabber({ app => 'cards', setting => 'month' }) } || [];
	splice @{$cards}, 40;
	my $last_card = $cards->[0];
	$card = $last_card->{'title'};
	my @time = localtime($last_card->{'timestamp'} / 1000);
	my @now = localtime(&subs::rightNow() / 1000);
	if ($time[4] != $now[4]) {
		my $new_card = &random_card_picker();
		$new_card =~ s/.png$//gi;
		my $car = { title => $new_card, timestamp => &subs::rightNow() };
		$card = $car->{'title'};
		unshift @{$cards}, $car;
		my $jcards = encode_json $cards;
		&subs::setting_setter({ app => 'cards', setting => 'month', value => $jcards });
	}
	return $card . '.png';
}

sub card_of_the_year() {
	my $card;
	my $cards = eval { decode_json &subs::setting_grabber({ app => 'cards', setting => 'year' }) } || [];
	splice @{$cards}, 40;
	my $last_card = $cards->[0];
	$card = $last_card->{'title'};
	my @time = localtime($last_card->{'timestamp'} / 1000);
	my @now = localtime(&subs::rightNow() / 1000);
	if ($time[5] != $now[5]) {
		my $new_card = &random_card_picker();
		$new_card =~ s/.png$//gi;
		my $car = { title => $new_card, timestamp => &subs::rightNow() };
		$card = $car->{'title'};
		unshift @{$cards}, $car;
		my $jcards = encode_json $cards;
		&subs::setting_setter({ app => 'cards', setting => 'year', value => $jcards });
	}
	return $card . '.png';
}

