# --- Relational: the social-construct workspace ------------------------------
# The workspace is built from the same index the People window uses. The old
# matcher rendered each bucket through the relational cache; this one reads the
# settings rows once and hands the client a single JSON board, so adding a link
# is one request rather than a partial re-render per pane.

sub relational_social_sing {
	my ($entry) = @_;
	return '' unless ref $entry eq 'HASH';
	my %social = map { $_->{'sing'} => 1 } values %{$gb::social_constructs};
	return $entry->{'pos'} if ($entry->{'pos'} || '') ne '' && $social{ $entry->{'pos'} };
	return $entry->{'mab'} if ($entry->{'mab'} || '') ne '' && $social{ $entry->{'mab'} };
	return '';
}

sub relational_colours {
	my $rows = eval { &subs::db_query("select app, value from settings where setting='colour' and value<>''")->hashes } || [];
	my %colours;
	foreach my $row ( @{$rows} ) {
		my $app = $row->{'app'} || '';
		next unless length $app;
		$colours{$app} ||= $row->{'value'};
	}
	return \%colours;
}

sub relational_workspace {
	my ($focus) = @_;
	my $index = &people_index();
	my %apps = %{ $index->{'apps'} || {} };
	$focus = '' unless defined $focus && length $focus && $apps{$focus}
		&& !(($apps{$focus}->{'house_uuid'} || '') ne '');
	my $colours = &relational_colours();
	my %social_by_sing = map { $_->{'sing'} => $_ } values %{$gb::social_constructs};
	my $type_label = sub {
		my ($scons) = @_;
		my $key = 'construct.' . $scons->{'name'};
		my $label = &subs::lang($key);
		return $label if defined $label && length $label && $label ne $key;
		return &subs::format_name($scons->{'name'});
	};
	my @types;
	foreach my $scons ( sort { $a->{'order'} <=> $b->{'order'} } values %{$gb::social_constructs} ) {
		my @rows;
		foreach my $app ( sort keys %apps ) {
			my $entry = $apps{$app};
			# another house's construct is read-only here; the Relational board
			# shows only what this house may change
			next if ($entry->{'house_uuid'} || '') ne '';
			next unless (($entry->{'pos'} || '') eq $scons->{'sing'} || ($entry->{'mab'} || '') eq $scons->{'sing'});
			push @rows, {
				app => $app,
				name => &subs::format_name($app),
				type => $scons->{'name'},
				sing => $scons->{'sing'},
				colour => $colours->{$app} || '',
				uuid => $entry->{'preferred_uuid'} || '',
				focus => ($app eq $focus ? 1 : 0),
			};
		}
		@rows = sort { lc($a->{'name'}) cmp lc($b->{'name'}) } @rows;
		push @types, {
			name => $scons->{'name'},
			sing => $scons->{'sing'},
			label => $type_label->($scons),
			count => scalar @rows,
			rows => \@rows,
		};
	}
	my %memberships;
	my $focus_data;
	if ($focus) {
		my $entry = $apps{$focus};
		my $focus_sing = &relational_social_sing($entry);
		my %focus_uuids = map { $_ => 1 } keys %{ $entry->{'uuids'} || {} };
		my %candidate;
		foreach my $sing ( keys %{ $entry->{'sc'} || {} } ) {
			foreach my $uuid ( keys %{ $entry->{'sc'}->{$sing} } ) {
				my $app = $index->{'uuid_app'}->{$uuid};
				next unless defined $app && $app ne $focus;
				$candidate{$app} = 1;
			}
		}
		if ($focus_sing) {
			foreach my $app ( keys %apps ) {
				next if $app eq $focus;
				foreach my $uuid ( keys %{ $apps{$app}->{'sc'}->{$focus_sing} || {} } ) {
					if ($focus_uuids{$uuid}) { $candidate{$app} = 1; last; }
				}
			}
		}
		foreach my $app ( keys %candidate ) {
			my $member = $apps{$app};
			my $sing = &relational_social_sing($member);
			next unless $sing;
			my $scons = $social_by_sing{$sing};
			next unless $scons;
			push @{ $memberships{ $scons->{'name'} } }, {
				app => $app,
				name => &subs::format_name($app),
				type => $scons->{'name'},
				sing => $sing,
				colour => $colours->{$app} || '',
			};
		}
		foreach my $name ( keys %memberships ) {
			@{ $memberships{$name} } = sort { lc($a->{'name'}) cmp lc($b->{'name'}) } @{ $memberships{$name} };
		}
		my $scons = $social_by_sing{$focus_sing};
		my $people_row = eval { &subs::db_select('people', undef, { app => $focus, status => 'active' })->hashes->[0] };
		$focus_data = {
			app => $focus,
			name => &subs::format_name($focus),
			type => $scons ? $scons->{'name'} : '',
			type_label => $scons ? $type_label->($scons) : '',
			sing => $focus_sing,
			pos => $entry->{'pos'} || '',
			mab => $entry->{'mab'} || '',
			colour => $colours->{$focus} || '',
			uuid => $entry->{'preferred_uuid'} || '',
			image => &people_main_image($focus),
			people_uuid => $people_row ? ($people_row->{'uuid'} || '') : '',
		};
	}
	my @pos_options = map { { value => $_, label => &subs::format_name($_) } } sort keys %{$gb::relationals};
	return {
		ok => 1,
		focus => $focus_data,
		memberships => \%memberships,
		types => \@types,
		pos_options => \@pos_options,
		labels => {
			library => &subs::ui('Constructs'),
			search => &subs::ui('Search'),
			add => &subs::ui('Add'),
			add_placeholder => &subs::ui('New name'),
			details => &subs::ui('Details'),
			open_people => &subs::ui('Open People'),
			drop_to_remove => &subs::ui('Drop here to remove'),
			empty_members => &subs::ui('Nothing here yet'),
			overview => &subs::ui('Choose a construct to work on'),
			focus_hint => &subs::ui('Drag a construct from the left into one of these groups, or press + on a card.'),
			all_constructs => &subs::ui('All constructs'),
		},
	};
}

# Write the membership array on every device copy of an app. The workspace
# unions those copies, so changing only this device's row would leave the
# member visible on the others.
sub relational_sc_update_all {
	my ($app, $sing, $add_uuid, $remove_uuids) = @_;
	return 0 unless defined $app && length $app && defined $sing && length $sing;
	my $setting = 'sc_' . $sing;
	my $rows = eval { &subs::db_query('select uuid, value from settings where app=? and setting=?', $app, $setting)->hashes } || [];
	my $found = 0;
	foreach my $row ( @{$rows} ) {
		my $list = eval { decode_json($row->{'value'} || '') } || [];
		$list = [] unless ref $list eq 'ARRAY';
		my %set;
		foreach my $uuid ( @{$list} ) {
			next unless defined $uuid && length $uuid && $uuid ne 'all';
			$set{$uuid} = 1;
		}
		$set{$add_uuid} = 1 if defined $add_uuid && length $add_uuid;
		delete $set{$_} for (ref $remove_uuids eq 'HASH' ? keys %{$remove_uuids} : ());
		&subs::db_update('settings', {
			value => encode_json([ sort keys %set ]),
			server_time => &subs::rightNow(),
		}, { uuid => $row->{'uuid'} });
		$found++;
	}
	unless ($found) {
		my %set;
		$set{$add_uuid} = 1 if defined $add_uuid && length $add_uuid;
		delete $set{$_} for (ref $remove_uuids eq 'HASH' ? keys %{$remove_uuids} : ());
		if (scalar keys %set) {
			&subs::setting_setter({ app => $app, setting => $setting, value => encode_json([ sort keys %set ]) });
		}
	}
	return 1;
}

sub relational_link {
	my ($focus, $member, $type, $movement) = @_;
	return 0 unless defined $focus && length $focus && defined $member && length $member && defined $type && length $type;
	return 0 if $focus eq $member;
	my $index = &people_index();
	my $f = $index->{'apps'}->{$focus};
	my $m = $index->{'apps'}->{$member};
	return 0 unless $f && $m;
	# an imported construct belongs to another house: its links are theirs
	return 0 if ($f->{'house_uuid'} || '') ne '' || ($m->{'house_uuid'} || '') ne '';
	my $scons = $gb::social_constructs->{$type};
	unless ($scons) {
		($scons) = grep { $_->{'sing'} eq $type } values %{$gb::social_constructs};
	}
	return 0 unless $scons;
	my $sing = $scons->{'sing'};
	my $focus_sing = &relational_social_sing($f);
	return 0 unless $focus_sing;
	my $f_uuid = $f->{'preferred_uuid'} || '';
	my $m_uuid = $m->{'preferred_uuid'} || '';
	return 0 unless $f_uuid && $m_uuid;
	if ($movement eq 'delete') {
		my %focus_uuids = map { $_ => 1 } keys %{ $f->{'uuids'} || {} };
		my %member_uuids = map { $_ => 1 } keys %{ $m->{'uuids'} || {} };
		&relational_sc_update_all($focus, $sing, undef, \%member_uuids);
		&relational_sc_update_all($member, $focus_sing, undef, \%focus_uuids);
	}
	else {
		&relational_sc_update_all($focus, $sing, $m_uuid, undef);
		&relational_sc_update_all($member, $focus_sing, $f_uuid, undef);
	}
	return 1;
}

sub relationalizer($data) {
	my $timestamp = $data->{'timestamp'};
	my $c = $data->{'c'};
	my $focus = defined $data->{'focus'} ? $data->{'focus'} : ($c ? ($c->param('focus') || '') : '');
	my $settings = &subs::settings_grabber({ app => 'relational' });
	my $dims = eval { decode_json($settings->{'dimensions'} || '') } || {};
	$dims = {} unless ref $dims eq 'HASH';
	# the two-pane matcher was happy at 500px; the board is not, and a window
	# parked past the right edge of a 1280px screen looks broken. Grow it once,
	# then leave whatever size the person chooses alone.
	$dims->{'width'} = 980 if !($dims->{'width'} || 0) || $dims->{'width'} < 720;
	$dims->{'height'} = 720 if !($dims->{'height'} || 0) || $dims->{'height'} < 560;
	$dims->{'left'} = 80 if !defined $dims->{'left'} || $dims->{'left'} > 900;
	$dims->{'top'} = 60 if !defined $dims->{'top'} || $dims->{'top'} > 200;
	$settings->{'dimensions'} = encode_json($dims);
	my $returner = {};
	$returner->{'contents'} = $c->render_to_string(
		template => 'relational/workspace',
		focus => $focus,
	);
	$returner->{'window'} = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'relational', settings => $settings, contents => $returner->{'contents'} }, $timestamp);
	return $returner;
}

get '/manager/relational/workspace' => sub($c) {
	my $focus = $c->param('focus') || '';
	$c->render(json => &relational_workspace($focus));
};

post '/manager/relational/link' => sub($c) {
	my $focus = $c->param('focus') || '';
	my $member = $c->param('member') || '';
	my $type = $c->param('type') || '';
	my $movement = ($c->param('movement') || 'add') eq 'delete' ? 'delete' : 'add';
	my $ok = &relational_link($focus, $member, $type, $movement);
	my $workspace = &relational_workspace($focus);
	$workspace->{'ok'} = $ok ? 1 : 0;
	$workspace->{'error'} = $ok ? undef : 'could not link';
	$c->render(json => $workspace);
};

get '/manager/relational/select' => sub($c) {
	my $construct = $c->param('construct');
	my $setting = $c->param('setting');
	&subs::setting_setter({ 'app' => 'relational', setting => $setting, value => $construct });
	my $server_time = &subs::rightNow();
	my $settings = &subs::settings_grabber({ app => 'relational' });
	my $relationals;
	%{$relationals} = %{$gb::relationals};
	foreach my $sc ( keys %{$gb::relationals} ) {
		$relationals->{$sc}->{'list'} =	&subs::db_query('select * from settings where (setting = ? or setting = ?) and value = ?', 'pos', 'mab', $gb::relationals->{$sc}->{'sing'})->hashes;
	}
	my $returner = { settings => $settings, relationalizer => &relationalizer({ settings => $settings, timestamp => $server_time, c => $c }) };

	$c->render(json => $returner);
};

post '/manager/relational/adder' => sub($c) {
	my $construct = $c->param('construct');
	my $server_time = &subs::rightNow();
	my $addition = &subs::unformat_name($c->param('addition'));
	my $settings = &subs::settings_grabber({ app => $addition });
	if (!$settings->{'pos'}) {
		$settings = &subs::setting_initializer($addition . '_' . $construct,$server_time);
	}
	elsif (!$settings->{'mab'} && $settings->{'pos'} ne $construct) {
		&subs::setting_setter({ app => $addition, setting => 'mab', value => $construct });
		$settings->{'mab'} = $construct;
	}


	my @constructs = grep { $_->{'sing'} eq $construct } values %{$gb::relationals};

	my $returner = { ok => 1, app => $addition, settings => $settings, sc => $constructs[0] };

	# a new person construct is a person the moment it is made
	&people_link_sync() if ($construct eq 'person');

	$c->render(json => $returner);
};

get '/manager/relational/search' => sub($c) {
	my $server_time = &subs::rightNow();
	if ($c->param('search_tool') eq 'categories') {
		&subs::setting_setter({ app => 'relational', 'setting' => 'category_search', 'value' => &subs::unformat_name($c->param('search')) });
	}
	else {
		&subs::setting_setter({ app => 'relational', 'setting' => 'contents_search', 'value' => &subs::unformat_name($c->param('search')) });
	}
	my $settings = &subs::settings_grabber({ app => 'relational' });
	my $returner = { settings => $settings, relationalizer => &relationalizer({ timestamp => $server_time, c => $c }) };
	$c->render(json => $returner);

};

post '/manager/relational/sorter' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $uuid = $c->param('uuid');
	my $construct = $c->param('construct');
	my $b_uuid = $c->param('b_uuid');
	my $b_construct = $c->param('b_construct');
	my $movement = $c->param('movement');


	my $bubble = &subs::settings_grabber({ uuid => $uuid });
	my $bucket = &subs::settings_grabber({ uuid => $b_uuid });
	$b_construct = $bucket->{'pos'};
	$construct = $bubble->{'pos'};
	my $sc = eval { return decode_json $bucket->{'sc_' . $construct} } || [];

	push @{$sc}, $bubble->{'uuid'} unless grep { $_ eq $bubble->{'uuid'} } @{$sc};

	if ($movement eq 'delete') {
		@{$sc} = grep { $_ ne $bubble->{'uuid'} } @{$sc};
	}
	@{$sc} = grep { $_ ne 'all' } @{$sc};



	my $bc = eval { return decode_json $bubble->{'sc_' . $b_construct} } || [];
	push @{$bc}, $bucket->{'uuid'} unless grep { $_ eq $bucket->{'uuid'} } @{$bc};

	if ($movement eq 'delete') {
		@{$bc} = grep { $_ ne $bucket->{'uuid'} } @{$bc};
	}
	@{$bc} = grep { $_ ne 'all' } @{$bc};


	my $jsc = encode_json $sc;
	&subs::setting_setter({ app => $bucket->{'app'}, setting => 'sc_' . $construct, value => $jsc });
	my $jbc = encode_json $bc;
	&subs::setting_setter({ app => $bubble->{'app'}, setting => 'sc_' . $b_construct, value => $jbc });
	$bucket->{'sc_' . $construct} = $jsc;
	$bubble->{'sc_' . $b_construct} = $jbc;
	$gb::relational_construct->{$construct}->{'list'} = [];
	$gb::relational_construct->{$b_construct}->{'list'} = [];

	my $settings = &subs::settings_grabber({ app => 'relational' });
	my $returner = { movement => $movement, bucket_uuid => $bucket->{'uuid'}, bubble => $bubble, bucket => $bucket, sc => $sc, bc => $bc };
	$returner->{'bucket'} = $c->render_to_string(
		template => 'relational/bucket',
		all_settings => {},
		settings => $settings,
		const => $bucket,
		contents_search => $settings->{'contents_search'}
	);

	$returner->{'bubble'} = $c->render_to_string(
		template => 'relational/bucket',
		all_settings => {},
		settings => $settings,
		const => $bubble,
		contents_search => $settings->{'contents_search'}
	);

	$c->render(json => $returner);
};

post '/manager/relational/autocalc' => sub($c) {
	my $uuid = $c->param('uuid');
	my $construct = $c->param('construct');
	my $returner = {
		tasks => [],
		model => [],
		option => [],
		optioncategory => [],
		subcategory => [],
		transactions => [],
		locations => []
	};
	my $rel = &subs::db_query('select * from settings where setting=? and value=?', 'uuid', $uuid)->hashes->[0];
	my $settings = &subs::settings_grabber({ app => $rel->{'app'} });
	foreach my $a ( qw/model option option_category subcategory/ ) {
		my $as = &subs::db_query('select * from ' . $a . ' where app=? or name=?',$rel->{'app'},$rel->{'app'})->hashes;
		foreach my $at ( @{$as} ) {
			my $name = $at->{'app'} eq $rel->{'app'} ? $at->{'name'} : $at->{'app'};
			my $set = &subs::settings_grabber({ app => $name });
			push @{$returner->{$a}}, { uuid => $set->{'uuid'}, app => $set->{'app'}, settings => $set };
		}
	}
	my $tasks = &subs::task_grabber($rel->{'app'});

	foreach my $t ( grep { $_->{'task'} } @{$tasks->{'tasks'}}) {
		my $set = &subs::settings_grabber({ app => $t->{'task'} });
		push @{$returner->{'tasks'}}, { uuid => $set->{'uuid'}, app => $set->{'app'}, settings => $set };
	}

	my $appts = &subs::db_query('select * from appointments where app=? and type=? and data is not null', $rel->{'app'}, 'transaction')->hashes;
	foreach my $appt ( @{$appts} ) {
		my $data = eval { return decode_json $appt->{'data'} } || {};
		foreach my $dk ( keys %{$data} ) {
			foreach my $d ( keys %{$data->{$dk}} ) {
				foreach my $i ( qw/item vendor manufacturer/ ) {
					if ($data->{$dk}->{$d}->{$i}) {
						my $tapp = &subs::unformat_name($data->{$dk}->{$d}->{$i});
						unless ( grep { $_->{'app'} eq $tapp } @{$returner->{'transactions'}}) {
							my $set = &subs::settings_grabber({ app => $tapp });
							push @{$returner->{'transactions'}}, { uuid => $set->{'uuid'}, app => $set->{'app'}, settings => $set };
						}
					}
				}
			}
		}
	}
	if ($settings->{'home_plate'}) {
		my $hp = eval { return decode_json $settings->{'home_plate'} };
		my $mult = .00001;
		my $continent = &subs::db_query('select distinct(app) from continent where latitude >= ? and latitude <= ? and longitude >= ? and longitude <= ?',
			($hp->{'latitude'} - $mult), ($hp->{'latitude'} + $mult), ($hp->{'longitude'} + $mult), ($hp->{'longitude'} - $mult))->hashes;
		foreach my $con ( @{$continent} ) {
			my $set = &subs::settings_grabber({ app => $con->{'app'} });
			push @{$returner->{'locations'}}, { uuid => $set->{'uuid'}, app => $set->{'app'}, settings => $set };
		}
	}

	# What the house has noticed running beside this app, so a relationship it
	# found can be filed by hand: the apps whose occurrences the evaluation's
	# event scan puts around this one more than chance would, each shown with the
	# lift and ticked to relate right here.
	my @noticed;
	my %noticed_seen = ( $rel->{'app'} => 1 );
	foreach my $entry ( @{ &subs::evaluation_context_scan($rel->{'app'}, &subs::rightNow() - 60 * 86400000, 30 * 60000, 6) } ) {
		next if $noticed_seen{ $entry->{'app'} }++;
		my $set = &subs::settings_grabber({ app => $entry->{'app'} });
		next unless $set->{'uuid'};
		push @noticed, { uuid => $set->{'uuid'}, app => $set->{'app'}, settings => $set, lift => $entry->{'lift'}, hits => $entry->{'hits'} };
	}
	$returner->{'noticed'} = \@noticed;

	$returner->{'html'} = $c->render_to_string(
		template => 'relational/autocalc',
		returner => $returner,
		uuid => $uuid,
		construct => $construct
	);



	$c->render(json => $returner);
};

get '/manager/relational/tree' => sub($c) {
	my $uuid = $c->param('uuid');

	my $rel = &subs::db_select('settings', undef, { setting => 'uuid', value => $uuid })->hashes->[0];
	my $settings = &subs::settings_grabber({ app => $rel->{'app'} });
	$settings->{'formatted_name'} = &subs::format_name($settings->{'app'});
	my $relationships = {};
	foreach my $s ( grep { $_ =~ /^sc_/gi } keys %{$settings} ) {
		my $sc = $s;
		$sc =~ s/^sc_//gi;
		$settings->{$s} = eval { return decode_json $settings->{$s} } || [];
		foreach my $scs ( @{$settings->{$s}} ) {
			my $rel_settings = &subs::db_query('select * from settings where setting=? and value=?', 'uuid', $scs)->hashes->[0];
			$rel_settings->{'formatted_name'} = &subs::format_name($rel_settings->{'app'});
			push @{$relationships->{$sc}}, $rel_settings;
		}
	}

	my $returner = { rel => $rel, settings => $settings, relationships => $relationships };

	$returner->{'html'} = $c->render_to_string(
		template => 'relational/tree',
		rel => $rel,
		settings => $settings,
		relationships => $relationships
	);

	$c->render(json => $returner);
};



get '/manager/twirl' => sub ($c) {
	my $timestamp = $c->param('timestamp');
	my $contents = $c->render_to_string(
		settings => &subs::settings_grabber({ app => 'twirl' }),
		template => 'twirl',
		window_maker => $c->param('window_maker')
	);
	my $website = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'twirl', contents => $contents }, $timestamp);
	$c->render(text => $website);
};

post '/manager/folders' => sub($c) {
	my $timestamp = $c->param('timestamp');
	# a machine picked in the toolbar: the listing has to come from that machine,
	# which is also the only machine that can stat its own paths
	if ($c->param('remote_uuid') && $c->param('remoted') ne 'yes') {
		my $result = &Manager::remote_relay_request($c);
		if (length $result) {
			# the relay hands the reply back as a plain string and the browser
			# parses it as JSON, so put the content type back
			$c->res->headers->content_type('application/json');
			$c->render(text => $result);
			return;
		}
	}
	my $folder = $c->param('folder') || &subs::home('~');
	my $command = $c->param('command');
	# One id per window and one per tab. The id is what keeps two Folders
	# windows apart while windowMaker answers a refresh; the tab id is what the
	# window's own tab strip selects between.
	my $folders_id = $c->param('window_id') // '';
	$folders_id =~ s/[^A-Za-z0-9_\-]//g;
	$folders_id = substr($folders_id, 0, 64);
	$folders_id = 'f' . &subs::random_string_creator(12) if length($folders_id) < 4;
	my $tab_id = $c->param('tab_id') // '';
	$tab_id =~ s/[^A-Za-z0-9_\-]//g;
	$tab_id = substr($tab_id, 0, 64);
	$tab_id = 't' . &subs::random_string_creator(12) if length($tab_id) < 4;
	my $settings = &subs::settings_grabber({ app => 'folders' });
	# an app opens locked: only the token this window holds, minted by the
	# phone's unlock, may list a sealed name
	my $unlocked = media_unlock_open($c, 'folders') ? 1 : 0;
	my $unlock = $unlocked ? $c->param('unlock') : '';

	my $show_hidden = $c->param('show_hidden') ? 1 : 0;
	my $fo = &folders_opener({ folder => $folder, command => $command, c => $c, unlocked => $unlocked, show_hidden => $show_hidden });
	# the bar names the folder being read, not its whole path, in the same words
	# the address bar uses; every command still works on the real path
	my $named_folder = $fo->{'display_name'} || '';
	my $window_name = &subs::ui('Folders') . (length $named_folder ? ' - ' . $named_folder : '');
	my $remote_uuid = $c->param('remote_uuid') || '';
	my $machines = &subs::remote_machine_lister({ self => 'no' });
	# A remote listing is rendered by the machine being read, where that machine
	# is "self" and so absent from its peer list. Keep an option for it: the
	# toolbar must always name the machine whose files are on screen.
	if ($remote_uuid && !grep { ($_->{'uuid'} || '') eq $remote_uuid } @{$machines}) {
		my $rm = &subs::db_select('remote_machines', undef, { uuid => $remote_uuid })->hashes->[0] || {};
		my $label = $rm->{'hostname'} || $rm->{'fqdn'} || $rm->{'ip'} || '';
		unless (length $label) {
			# a relayed rendering: this uuid is the source's name for us
			if (($c->param('remoted') || '') eq 'yes') {
				$label = `hostname`;
				chomp $label;
			}
		}
		$label = $remote_uuid unless length $label;
		push @{$machines}, { uuid => $remote_uuid, hostname => $label };
	}
	my $contents = $c->render_to_string(
		template => 'folders/folders',
		settings => $settings,
		fo => $fo,
		folder => $folder,
		folders_id => $folders_id,
		tab_id => $tab_id,
		unlocked => $unlocked,
		unlock => $unlock,
		machines => $machines,
		remote_uuid => $remote_uuid
	);

	my $html = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'folders', window_id => $folders_id, window_name => $window_name, contents => $contents }, $timestamp);
	$c->render(json => { html => $html, fo => $fo, window_id => $folders_id, tab_id => $tab_id, window_name => $window_name, unlocked => $unlocked });
};

# Apps that are not launchable from the app menu: citizen kinds and the
# handbook's older alias. They must not be offered as desk shortcuts.
my %folders_desk_not_app = map { $_ => 1 } qw(citizen resident guest blacklisted library);

# The folder the desk shows. A chosen desktop_folder wins; otherwise ~/Desktop
# is used only when it has something in it (an empty desktop reads as broken),
# and the home folder stands in for both.
sub folders_desk_folder {
	my $set = &subs::setting_grabber({ app => 'folders', setting => 'desktop_folder' });
	if (defined $set && length $set) {
		my $chosen = &subs::home($set);
		$chosen =~ s{/+$}{} unless $chosen eq '/';
		return $chosen if -d $chosen;
	}
	my $desktop = &subs::home('~/Desktop');
	$desktop =~ s{/+$}{} unless $desktop eq '/';
	if (-d $desktop) {
		my @names = &folders_entry_names($desktop);
		return $desktop if scalar @names;
	}
	my $home = &subs::home('~/');
	$home =~ s{/+$}{};
	$home = '/' unless length $home;
	return $home;
}

# The apps pinned to the desk, in the order they were pinned.
sub folders_desk_pinned {
	my $raw = eval { decode_json &subs::setting_grabber({ app => 'folders', setting => 'desktop_apps' }) };
	my @list = ref $raw eq 'ARRAY' ? @{$raw} : ();
	my %seen;
	return grep {
		defined $_ && length $_ && !$seen{$_}++
			&& $gb::known_appts->{$_} && !$folders_desk_not_app{$_}
	} @list;
}

# Every app a person may pin, with the name and icon the picker draws.
sub folders_pinable_apps {
	return [ map {
		{
			app => $_,
			name => &subs::format_name($_),
			icon => &subs::icon_for($gb::known_appts->{$_}->{'icon'})
		}
	} grep { !$folders_desk_not_app{$_} } sort { lc($a) cmp lc($b) } keys %{$gb::known_appts} ];
}

# The desk behind the manager: the same Folders listing drawn as icons on the
# desktop background, plus any app shortcuts pinned there. The padlock is the
# Folders window's own token, so a sealed name appears here only while this
# screen has Folders open.
get '/manager/folders/desk' => sub($c) {
	my $folder = &folders_desk_folder();
	my $unlocked = media_unlock_open($c, 'folders') ? 1 : 0;
	my $show_hidden = $c->param('show_hidden') ? 1 : 0;
	my $listing = &folders_listing($folder, $unlocked, $c, $show_hidden);
	my @apps = map {
		{
			app => $_,
			name => &subs::format_name($_),
			icon => &subs::icon_for($gb::known_appts->{$_}->{'icon'})
		}
	} &folders_desk_pinned();
	my $trash = &folders_trash_files_dir();
	my $trash_count = &folders_trash_count();
	$c->render(json => {
		folder => $folder,
		files => $listing->{'files'},
		apps => \@apps,
		disk => $listing->{'disk'},
		# the two fixed places: Computer opens the root, the bin its own folder
		computer => {
			name => &subs::ui('Computer'),
			icon => &subs::icon_for('/images/decipherable/computer.png'),
			path => '/'
		},
		trash => {
			name => &subs::ui('Recycle Bin'),
			icon => &subs::icon_for('/icons/trash.png'),
			path => $trash,
			count => $trash_count
		},
		trash_folder => $trash,
		trash_count => $trash_count,
		unlocked => $unlocked
	});
};

# The app picker the desk's background menu opens.
get '/manager/folders/desk/apps' => sub($c) {
	my %pinned = map { $_ => 1 } &folders_desk_pinned();
	my $content = $c->render_to_string(
		template => 'folders/app_picker',
		apps => &folders_pinable_apps(),
		pinned => \%pinned
	);
	my $uuid = &subs::random_string_creator(12);
	my $dialog = $c->render_to_string(
		template => 'folders/dialog_box',
		folders => { folder => &folders_desk_folder() },
		box => {
			name => &subs::ui('Pin apps to the desk'),
			command => 'pin_app',
			content => $content,
			height => '70%',
			width => 'min(680px, 94vw)',
			ok_label => &subs::ui('Pin'),
			cancel_label => &subs::ui('Cancel')
		},
		uuid => $uuid
	);
	$c->render(json => { dialog => $dialog });
};

# Save the pinned list. Only known, launchable apps are kept; the list is capped
# so the desk never turns into an app drawer.
post '/manager/folders/desk/apps' => sub($c) {
	my $apps = eval { decode_json $c->param('apps') } || [];
	my %seen;
	my @clean;
	foreach my $app ( @{$apps} ) {
		next unless defined $app && $app =~ /^[a-z0-9_]+$/;
		next unless $gb::known_appts->{$app} && !$folders_desk_not_app{$app};
		push @clean, $app unless $seen{$app}++;
	}
	@clean = @clean[0 .. 19] if scalar @clean > 20;
	&subs::setting_setter({ app => 'folders', setting => 'desktop_apps', value => encode_json(\@clean) });
	$c->render(json => { ok => 1, apps => \@clean });
};

# Choose the folder the desk shows. An empty path returns to the automatic
# choice (~/Desktop when it has something in it, else home).
post '/manager/folders/desk/folder' => sub($c) {
	my $folder = $c->param('folder');
	if (!defined $folder || !length $folder) {
		&subs::setting_deleter({ app => 'folders', setting => 'desktop_folder' });
		$c->render(json => { ok => 1, folder => &folders_desk_folder() });
		return;
	}
	$folder = &subs::home($folder);
	$folder =~ s{/+$}{} unless $folder eq '/';
	unless (-d $folder) {
		$c->render(json => { ok => 0, error => &subs::ui('That folder is not there.') });
		return;
	}
	&subs::setting_setter({ app => 'folders', setting => 'desktop_folder', value => $folder });
	$c->render(json => { ok => 1, folder => $folder });
};

# The app a path belongs to: the first segment under a known location root
# (~/Pictures/<app>/...). Used to apply the visibility rule to a listing.
sub folders_owning_app($path) {
	return undef unless defined $path && length $path;
	my $misc = &misc_setting_list();
	my $device = &subs::device_setter();
	foreach my $k ( keys %{ $misc->{$device} || {} } ) {
		next unless $k =~ /_location$/;
		my $root = $misc->{$device}->{$k};
		next unless defined $root && length $root;
		$root = &subs::home($root);
		$root =~ s{/+$}{};
		next unless length $root;
		next unless index($path, $root . '/') == 0;
		my $rest = substr($path, length($root) + 1);
		my ($seg) = split '/', $rest;
		return $seg if defined $seg && length $seg;
	}
	return undef;
}

# The house's own apps are written to disk under their key form - path_name() of
# the app name - so a folder the program made reads as a word salad in the
# listing. The apps the settings table knows are collected here once per folder.
sub folders_app_names {
	my %apps = map { $_ => 1 } keys %{ $gb::known_appts || {} };
	my $names = &subs::appointment_names() || {};
	$apps{$_} = 1 for keys %{$names};
	return \%apps;
}

# One path segment as the address bar reads it: a component a program wrote
# carries its percent escapes (path_name), so decode it first; then the house's
# own words, the same format_name every other name gets.
sub folders_display_segment($seg) {
	$seg = '' unless defined $seg;
	if ($seg =~ /%[0-9A-Fa-f]{2}/) {
		my $decoded = eval { &url_unescape($seg) };
		$seg = $decoded if defined $decoded && length $decoded;
	}
	return &subs::format_name($seg);
}

# The folder a person reads along the top and in the title bar. This is the eye
# only: folder, path, history and every command keep the real path.
sub folders_display_path($path) {
	return '' unless defined $path && length $path;
	my $lead = (substr($path, 0, 1) eq '/') ? '/' : '';
	my @parts = grep { length } split '/', $path;
	return '/' unless scalar @parts;
	return $lead . join('/', map { &folders_display_segment($_) } @parts);
}

# The name the window's title bar adds after "Folders": the folder on screen,
# not its whole path.
sub folders_display_name($path) {
	return '' unless defined $path && length $path;
	return '/' if $path eq '/';
	my $display = &folders_display_path($path);
	$display =~ s{.*/}{};
	return length $display ? $display : '/';
}

# The folder a media location wrote for an app reads as the app's own name. Only
# a location's top level is renamed; a folder inside an app folder keeps the
# name it has on disk.
sub folders_app_folder_display($path, $apps) {
	return undef unless defined $path && length $path && $apps;
	my $base = $path;
	$base =~ s{.*/}{};
	my $seg = &folders_owning_app($path);
	return undef unless defined $seg && length $seg && $seg eq $base;
	my $app = &url_unescape($seg);
	utf8::decode($app) if !utf8::is_utf8($app);
	return undef unless $apps->{$app};
	my $display = &subs::format_name($app);
	return ($display eq $base) ? undef : $display;
}

# A sealed name carries no words of its own. A row that points at it may name it
# - a map's place, a document's title - and that name wins; otherwise it reads as
# the app that wrote it and the moment it was made, "Autumn 10162026 3:30pm".
sub folders_sealed_display($path, $apps, $references) {
	return undef unless defined $path && length $path;
	my $blob;
	my $row_app = '';
	foreach my $spot ( @{ ($references && $references->{'paths'}->{$path}) || [] } ) {
		next unless ($spot->{'kind'} || '') eq 'f';
		$blob = $spot->{'blob'};
		$row_app = $spot->{'info'}->{'app'} || '';
		last;
	}
	my $named = $blob ? ($blob->{'name'} || '') : '';
	if ($named =~ /\S/) {
		my $display = &subs::format_name($named);
		return $display if length $display;
	}
	my $app = '';
	my $seg = &folders_owning_app($path);
	if (defined $seg && length $seg) {
		my $candidate = &url_unescape($seg);
		utf8::decode($candidate) if !utf8::is_utf8($candidate);
		$app = $candidate if $apps && $apps->{$candidate};
	}
	$app = $row_app unless length $app;
	my $stamp = 0;
	my $base = $path;
	$base =~ s{.*/}{};
	if ($base =~ /_(\d{12,14})\.[^.]+\.enc$/i) { $stamp = $1 + 0; }
	elsif ($blob && ($blob->{'server_time'} || '') =~ /^(\d{10,14})$/) { $stamp = $1 + 0; }
	else { my @st = stat($path); $stamp = ($st[9] || 0) * 1000; }
	my $when = &folders_stamp_words($stamp);
	if (length $app) {
		my $app_name = &subs::format_name($app);
		return $app_name . (length $when ? ' ' . $when : '');
	}
	# nothing ties it to an app: the name it went in under is still better than
	# the random one the seal carries
	if ($blob && ($blob->{'of'} || '') =~ /\S/) {
		my $of = $blob->{'of'};
		$of =~ s{.*/}{};
		return $of if length $of;
	}
	return undef;
}

# The moment a sealed file was made, in the house's short form: 10162026 3:30pm.
sub folders_stamp_words($ms) {
	return '' unless $ms && $ms > 0;
	my @t = localtime(int($ms / 1000));
	my $hour = $t[2] % 12;
	$hour = 12 unless $hour;
	return sprintf('%02d%02d%04d %d:%02d%s', $t[4] + 1, $t[3], $t[5] + 1900, $hour, $t[1], ($t[2] < 12 ? 'am' : 'pm'));
}

# Whether Folders may list sealed names comes from the window's own unlock
# token (media_unlock_open), never from the secret left in settings: a fresh
# open is locked, while the refresh after an unlock carries the token.
sub folders_opener($data) {
	my $folder = $data->{'folder'};
	my $command = $data->{'command'};
	my $c = $data->{'c'};
	my $unlocked = $data->{'unlocked'} ? 1 : 0;
	if (defined $command && $command eq 'up') {
		my @folders = split '/', $folder;
		pop @folders if scalar @folders;
		$folder = join '/', @folders;
	}
	elsif (defined $command && $command eq 'home') {
		$folder = &subs::home('~/');
	}
	# a trailing slash makes every path below it look like a double slash
	$folder =~ s{/+$}{} if (defined $folder && $folder ne '/');
	my $formatted_folder = &subs::terminal_name($folder);
	my $listing = &folders_listing($folder, $unlocked, $c, $data->{'show_hidden'});
	return { %{$listing},
		formatted_folder => $formatted_folder,
		folder => $folder,
		display_folder => &folders_display_path($folder),
		display_name => &folders_display_name($folder) };
}

# The names in a folder, in the order a file manager lists them. `readdir` rather
# than a shell `ls`: a name is data, and one holding a space, a quote, a star or a
# newline used to be split or expanded by the shell before the app ever saw it.
# Dotfiles stay out of the listing, as they did with `ls`.
sub folders_entry_names {
	my ($folder, $show_hidden) = @_;
	unless (defined $folder && length $folder && -d $folder) { return (); }
	opendir(my $dh, $folder) or return ();
	# dotfiles stay out of the listing unless the window has been told to show
	# hidden files from its background menu
	my @names = grep { $_ ne '.' && $_ ne '..' && ($show_hidden || substr($_, 0, 1) ne '.') } readdir $dh;
	closedir $dh;
	return sort { lc($a) cmp lc($b) || $a cmp $b } @names;
}

# One folder read as the app (and the desktop behind it) shows it: its entries,
# the folders apart from the files and the disk's own figures. The padlock rule
# is the same one the gallery reads, so a not-visible app's files stay out until
# this screen's Folders padlock is open.
sub folders_listing($folder, $unlocked, $c, $show_hidden) {
	my $formatted_folder = &subs::terminal_name($folder);
	my $files = [];
	my $total_size = 0;
	foreach my $f ( &folders_entry_names($folder, $show_hidden) ) {
		my $file = &folders_property_grabber({ folder => $folder, file => $f });
		$total_size += $file->{'size'} unless $file->{'type'} eq 'folder';
		push @{$files}, $file;
	}
	# a thing the person hid (visible ne checked) is not listed unless this
	# window holds a valid Folders token - the same per-window rule the gallery
	# reads, so a grant left by a closed window reveals nothing
	my $revealed = $unlocked ? 1 : 0;
	# a sealed name (.enc) is listed without a padlock when its app is marked
	# visible; only a name belonging to a hidden app waits for the unlock
	@{$files} = grep {
		my $app = folders_owning_app($_->{'path'});
		my $hidden = ($app && help_app_hidden($app) && !$revealed);
		my $sealed_name = (!$unlocked && ($_->{'name'} // '') =~ /\.enc$/i && (!$app || help_app_hidden($app)));
		!$hidden && !$sealed_name;
	} @{$files};
	my @folders = grep { $_->{'type'} eq 'folder' } @{$files};
	@{$files} = grep { $_->{'type'} ne 'folder' } @{$files};
	# the names the house gave its own folders and seals, for the eye only: the
	# path every command works on is still the real one
	my $apps = &folders_app_names();
	foreach my $file ( @folders ) {
		next if defined $file->{'display'};
		my $display = &folders_app_folder_display($file->{'path'}, $apps);
		$file->{'display'} = $display if defined $display;
	}
	my @sealed = grep { ($_->{'name'} // '') =~ /\.enc$/i } @{$files};
	if (scalar @sealed) {
		my $references = &subs::file_reference_read();
		foreach my $file ( @sealed ) {
			next if defined $file->{'display'};
			my $display = &folders_sealed_display($file->{'path'}, $apps, $references);
			$file->{'display'} = $display if defined $display && length $display;
		}
	}
	my $disk = {
		folders => scalar @folders,
		files => scalar @{$files},
		total_size => &subs::data_size($total_size)
	};
	unshift @{$files}, @folders;
	# In the bin the stored name (name, name.1, ...) is only the move's own; the
	# person reads the name it had where it came from, so list by that.
	if (&folders_in_trash($folder)) {
		@{$files} = sort {
			lc($_->{'display'} || $_->{'name'}) cmp lc($_->{'display'} || $_->{'name'})
				|| ($_->{'display'} || $_->{'name'}) cmp ($_->{'display'} || $_->{'name'})
		} @{$files};
	}
	# the disk figures belong to the path being read; `--` keeps a path that
	# starts with a dash from being read as an option
	my $df = `df -h -- $formatted_folder 2>/dev/null`;
	my @df = split /\n/, $df;
	my @first_line = split(/\s+/, $df[0] // '');
	my @data_line = split(/\s+/, $df[1] // '');
	for ( my $n = 0; $n < scalar @first_line; $n++) {
		$disk->{$first_line[$n]} = $data_line[$n];
	}
	return { files => $files, folders => \@folders, disk => $disk };
}

sub folders_property_grabber($data) {
	my $folder = $data->{'folder'};
	my $f = $data->{'file'};
	my $path = $folder . '/' . $f;
	my $file = {
		name => $f,
		path => $path
	};
	my $ftype = &file_type_recognizer($path);
	$file->{'type'} = $ftype->{'type'} || 'file';
	$file->{'icon'} = $ftype->{'icon'};
	# In the Recycle Bin the stored name is only the move's own; show the name
	# it had where it came from, and remember the whole path for Properties.
	if (&folders_in_trash($folder)) {
		my $original = &folders_trash_original($f);
		if (length $original) {
			my @orig = split '/', $original;
			$file->{'display'} = pop @orig;
			$file->{'trash_original'} = $original;
		}
	}
	my $thumb_dir = $folder . '/.thumbs';
	if (-e $thumb_dir && $file->{'type'} eq 'video') {
		my $formatted_thumbs_dir = &subs::terminal_name($thumb_dir);
		my $thumbs = `ls $formatted_thumbs_dir`;
		my @f = split /\./, $f;
		pop @f;
		my $f_thumb = join '.', @f;
		my @thumbs = grep { $_ =~ /\Q$f_thumb/ } split /\n/, $thumbs;
		$file->{'thumbs'} = [ map { $thumb_dir . '/' . $_ }  @thumbs ];
		$file->{'icon'} = '/file_open?file=' . uri_encode $thumb_dir . '/' . $thumbs[0];

	}



	# A generic file, a folder, a track, subtitles and a sealed file fall back to
	# the hand-drawn pictures; an icon set names those same pictures, so the
	# listing (and the desk drawn from it) wears the chosen set like the rest of
	# the interface. A generated thumbnail is the file's own picture and stays.
	if (($file->{'icon'} || '') =~ m{^/(?:images|icons)/}) { $file->{'icon'} = &subs::icon_for($file->{'icon'}); }

	# in list context, so the template can read the mtime the way it reads any
	# other stat result; a scalar stat here gives back a count, not the fields
	my @stat = stat($path);
	$file->{'stat'} = \@stat;
	$file->{'size'} = -s $path;

	$file->{'path'} = $path;

	return $file;
}

# One name inside a folder, as a file manager means it: no slash, no climbing
# out of the folder, and nothing that is only whitespace.
sub folders_name_cleaner {
	my $name = shift;
	return undef unless defined $name;
	$name =~ s{^\s+|\s+$}{}g;
	return undef if ($name eq '' || $name eq '.' || $name eq '..');
	return undef if $name =~ m{/};
	return $name;
}

# What a folders command works on: what is selected, else the file the menu was
# opened on, else nothing at all. The background menu names no item.
sub folders_command_items {
	my $folders = shift;
	my @items = grep { defined $_->{'path'} && length $_->{'path'} } @{$folders->{'selected'} || []};
	push @items, { path => $folders->{'path'} } if (!scalar @items && $folders->{'path'});
	return @items;
}

# ---- the Recycle Bin ---------------------------------------------------------
# Deleting a file moves it here instead of unlinking it; a shred still destroys
# it. The layout is the freedesktop one (~/.local/share/Trash/files beside
# info/*.trashinfo), so the bin also works with the rest of the desktop.
sub folders_trash_root {
	my $root = &subs::home('~/.local/share/Trash');
	$root =~ s{/+$}{};
	return $root;
}
sub folders_trash_files_dir {
	my $dir = &folders_trash_root() . '/files';
	File::Path::make_path($dir) unless -d $dir;
	return $dir;
}
sub folders_trash_info_dir {
	my $dir = &folders_trash_root() . '/info';
	File::Path::make_path($dir) unless -d $dir;
	return $dir;
}
sub folders_in_trash($folder) {
	return 0 unless defined $folder && length $folder;
	my $dir = &folders_trash_root();
	$folder =~ s{/+$}{} unless $folder eq '/';
	return ($folder eq $dir || $folder eq $dir . '/files' || $folder eq $dir . '/info') ? 1 : 0;
}

# A move that works across filesystems: rename is the cheap same-disk case; a
# folder is walked otherwise, so a file deleted onto another drive still lands
# in the bin rather than being shredded to make the move fit.
sub folders_move_path($from, $to) {
	return 0 unless defined $from && length $from && -e $from;
	return 1 if rename($from, $to);
	if (!-d $from) {
		return File::Copy::move($from, $to) ? 1 : 0;
	}
	File::Path::make_path($to) unless -d $to;
	opendir(my $dh, $from) or return 0;
	my @names = grep { $_ ne '.' && $_ ne '..' } readdir $dh;
	closedir $dh;
	foreach my $name ( @names ) {
		return 0 unless &folders_move_path($from . '/' . $name, $to . '/' . $name);
	}
	rmdir $from;
	return 1;
}

# Put one path in the bin, with a .trashinfo naming where it came from.
sub folders_trash_move($path) {
	return 'no path' unless (defined $path && length $path);
	return $path . ': it is not there' unless -e $path;
	my $files = &folders_trash_files_dir();
	my $info = &folders_trash_info_dir();
	my @parts = split '/', $path;
	my $name = pop @parts;
	$name = 'item' unless (defined $name && length $name);
	my $base = $name;
	my $n = 1;
	while (-e $files . '/' . $name || -e $info . '/' . $name . '.trashinfo') {
		$name = $base . '.' . $n++;
	}
	my $dest = $files . '/' . $name;
	return $path . ': it could not be moved to the Recycle Bin' unless &folders_move_path($path, $dest);
	my $when = POSIX::strftime('%Y-%m-%dT%H:%M:%S', localtime());
	my $encoded = uri_encode($path);
	write_file($info . '/' . $name . '.trashinfo', "[Trash Info]\nPath=" . $encoded . "\nDeletionDate=" . $when . "\n");
	return undef;
}

# The original path a bin entry remembers, or '' when there is no info file.
sub folders_trash_original($name) {
	return '' unless (defined $name && length $name && $name !~ m{/});
	my $file = &folders_trash_info_dir() . '/' . $name . '.trashinfo';
	return '' unless -e $file;
	my $raw = eval { read_file($file) } || '';
	return '' unless $raw =~ /^Path=(.*)$/m;
	my $path = $1;
	$path =~ s/\r$//;
	$path = uri_decode($path);
	return $path;
}

# Put one bin entry back where it came from. A restored name that is already
# taken is kept beside it as name.restored, never written over.
sub folders_trash_restore($name) {
	return { ok => 0, error => 'That is not a bin entry.' } unless (defined $name && length $name && $name !~ m{/} && $name ne '.' && $name ne '..');
	my $src = &folders_trash_files_dir() . '/' . $name;
	return { ok => 0, error => 'That item is no longer in the bin.' } unless -e $src;
	my $original = &folders_trash_original($name);
	return { ok => 0, error => 'The bin does not remember where that came from.' } unless length $original && $original =~ m{^/};
	my @parts = split '/', $original;
	my $base = pop @parts;
	my $parent = join('/', @parts) || '/';
	File::Path::make_path($parent) unless -d $parent;
	return { ok => 0, error => 'The folder it came from is not there.' } unless -d $parent;
	my $dest = $parent . '/' . $base;
	if (-e $dest) {
		$dest = $dest . '.restored';
		my $n = 1;
		while (-e $dest) { $dest = $parent . '/' . $base . '.restored.' . $n++; }
	}
	return { ok => 0, error => 'It could not be put back.' } unless &folders_move_path($src, $dest);
	unlink &folders_trash_info_dir() . '/' . $name . '.trashinfo';
	return { ok => 1, path => $dest, name => $name };
}

# Permanently take away every entry in the bin.
sub folders_trash_empty {
	my $files = &folders_trash_files_dir();
	my $info = &folders_trash_info_dir();
	my $count = 0;
	foreach my $name ( &folders_entry_names($files) ) {
		my $error = &subs::folders_job_take_away($files . '/' . $name);
		$count++ unless $error;
	}
	foreach my $entry ( &folders_entry_names($info) ) {
		unlink $info . '/' . $entry if $entry =~ /\.trashinfo$/;
	}
	return $count;
}
sub folders_trash_count {
	my @names = &folders_entry_names(&folders_trash_files_dir());
	return scalar @names;
}

# Take a folders selection away. Anything an appointment has attached goes
# through the app's own file deletion first, so the appointment lets go of it,
# the thumb goes with it, and the other machines hear about it; the rows
# besides appointments that named the file - a mailbox's attachments, the
# store's rows - are trimmed of it, and a backup whose sealed file it was goes
# the way a pruned backup goes. Whatever is left after that is deleted or
# shredded where it lies. Returns the errors.
sub folders_delete_away {
	my ($command, $items) = @_;
	my @errors;
	my $bin = &folders_trash_files_dir();
	foreach my $item ( @{$items} ) {
		my $path = $item->{'path'};
		# An item already in the bin has nowhere left to be moved to, so a delete
		# there (the keyboard's Delete, since the menu hides it) is permanent.
		my @leaf = split '/', ($path || '');
		my $leaf = pop @leaf;
		my $in_bin = (join('/', @leaf) eq $bin);
		my $shred = ($command eq 'shred' || ($command eq 'delete' && $in_bin)) ? 1 : 0;
		foreach my $attached ( @{ &subs::folders_appt_entries($path) } ) {
			&delete_file($attached);
		}
		&subs::folders_entry_trim($path);
		&folders_delete_backups($path);
		next unless -e $path;
		my $error = $shred ? &subs::folders_job_shred($path) : &folders_trash_move($path);
		# taking a bin entry away also takes its note, or the bin keeps an entry
		# it can no longer restore
		if (!$error && $shred && $in_bin) { unlink &folders_trash_info_dir() . '/' . $leaf . '.trashinfo'; }
		push @errors, $error if $error;
	}
	return \@errors;
}

# A backup whose sealed file is being taken away goes with it: the row is
# deleted and the other machines are told to drop it, the same as when
# backup_now rotates a backup out. Returns how many were pruned.
sub folders_delete_backups {
	my $path = shift;
	return 0 unless (defined $path && length $path);
	my @names = (-d $path) ? &subs::folders_job_files([ { path => $path } ]) : ( $path );
	my %wanted = map { $_ => 1 } @names;
	my $backups = &subs::db_query('select uuid, server_time, enc_file from backups where enc_file is not null and enc_file != ?', '')->hashes;
	my $pruned = 0;
	foreach my $backup ( @{$backups} ) {
		next unless $wanted{ $backup->{'enc_file'} };
		&deletion_registration({ table => 'backups', uuid => $backup->{'uuid'}, scope => 'single', server_time => $backup->{'server_time'} });
		&subs::db_delete('backups', { uuid => $backup->{'uuid'} });
		$pruned++;
	}
	return $pruned;
}

post '/manager/folders/context' => sub($c) {
	my $file = $c->param('file');
	my $folders = eval { return decode_json $c->param('folders') } || {};
	my $context = $c->param('context');
	my $returner = {
		call_uuid => &subs::random_string_creator(21),
		folders => $folders
	};

	$returner->{'html'} = $c->render_to_string(
		template => 'folders/context',
		folders => $folders,
		uuid => $returner->{'call_uuid'},
		context => $context
	);
	$c->render(json => $returner);
};

get '/manager/folders/context/command' => sub($c) {
	my $command = $c->param('command');
	my $folders = eval { return decode_json $c->param('folders') } || {};
	my $folder = $c->param('folder');
	my $context = $c->param('context');
	my $uuid = &subs::random_string_creator(255);
	my $returner = {};
	my $box;
	my @items = &folders_command_items($folders);
	my @names = map { &subs::format_name( (split '/', $_->{'path'})[-1] ) } @items;

	if ($command eq 'new_file') {
		$box = {
			name => 'New File',
			inputs => [{
				placeholder => 'Filename',
				name => 'filename'
			}]
		};
	}
	elsif ($command eq 'new_folder') {
		$box = {
			name => 'New Folder',
			inputs => [{
				placeholder => 'Folder Name',
				name => 'foldername'
			}]
		};
	}
	elsif ($command eq 'rename') {
		my @parts = split '/', ($folders->{'path'} || '');
		my $name = pop @parts;
		$box = {
			name => 'Rename ' . (&subs::format_name($name) || ''),
			inputs => [{
				placeholder => 'Filename',
				name => 'filename',
				value => $name
			}]
		};
	}
	elsif ($command eq 'archive') {
		$box = {
			name => 'Archive'
		};
	}
	elsif ($command eq 'delete' || $command eq 'shred') {
		my $in_bin = &folders_in_trash($folders->{'folder'});
		my $text;
		if ($command eq 'delete') {
			$text = $in_bin
				? &subs::ui('Delete') . ' ' . scalar(@items) . ' ' . &subs::ui('item(s)? They are taken out of the Recycle Bin for good.') . "\n\n"
				: &subs::ui('Delete') . ' ' . scalar(@items) . ' ' . &subs::ui('item(s)? They go to the Recycle Bin. A folder goes with everything in it.') . "\n\n";
		}
		else {
			$text = &subs::ui('Shred') . ' ' . scalar(@items) . ' ' . &subs::ui('item(s)? Nothing shredded can be read again.') . "\n\n";
		}
		$box = {
			name => &subs::format_name($command),
			text => $text . join("\n", @names),
			height => '320px'
		};
	}
	elsif ($command eq 'empty_trash') {
		my $count = &folders_trash_count();
		$box = {
			name => &subs::ui('Empty Recycle Bin'),
			text => $count . ' ' . &subs::ui('item(s) will be permanently deleted. This cannot be undone.'),
			height => '260px'
		};
	}
	elsif ($command eq 'encrypt' || $command eq 'decrypt') {
		my $text = ($command eq 'encrypt')
			? 'Seal ' . scalar(@items) . " item(s) with the suds? Every file gets a name of its own and the plaintext is shredded behind it.\n\n"
			: 'Open ' . scalar(@items) . " sealed item(s) with the suds? The seal is shredded once the file is out.\n\n";
		$box = {
			name => &subs::format_name($command),
			text => $text . join("\n", @names),
			height => '320px'
		};
	}
	elsif ($command eq 'paste') {

	}
	elsif ($command eq 'properties') {
		# the background menu asks about the folder being looked at, which is
		# not a selection of anything
		@items = ( { path => $folders->{'folder'} } ) if (!scalar @items && $folders->{'folder'} && length $folders->{'folder'});
		my $total_size = 0;
		my @files;
		foreach my $item ( @items ) {
			my @parts = split '/', $item->{'path'};
			my $name = pop @parts;
			my $file = &folders_property_grabber({ file => $name, folder => join('/', @parts) });
			$file->{'parent'} = join('/', @parts) || '/';
			$total_size += $file->{'size'} unless (($file->{'type'} || '') eq 'folder');
			# a folder's own inode is not what the person wants to know; the
			# number of things inside it is
			$file->{'children'} = scalar &folders_entry_names($file->{'path'}) if (($file->{'type'} || '') eq 'folder');
			push @files, $file;
		}
		my $text = $c->render_to_string(
			template => 'folders/properties',
			total_size => $total_size,
			files => \@files,
			folders => $folders
		);


		$box = {
			ok => 'no',
			cancel => 'yes',
			cancel_label => &subs::ui('Close'),
			height => '70%',
			width => 'min(660px, 94vw)',
			name => &subs::ui('Properties'),
			content => $text
		};
	}
	if ($box) {
		$box->{'command'} = $command;
		my $dialog = $c->render_to_string(
			template => 'folders/dialog_box',
			folders => $folders,
			box => $box,
			uuid => $uuid
		);
		$returner->{'dialog'} = $dialog;
	}
	$c->render(json => $returner);
};

# What the OK of a folders dialog does. The things that only touch the folder
# being looked at happen here; anything that walks a disk - a paste, a seal, an
# opening - is queued for the worker, and the answer is a dialog the app keeps
# asking after until the job is done with.
post '/manager/folders/context/command' => sub($c) {
	my $command = $c->param('command');
	my $inputs = eval { return decode_json $c->param('inputs') } || {};
	my $folders = eval { return decode_json $c->param('folders') } || {};
	my $folder = $folders->{'folder'};
	my $returner = {};
	my $answer = sub {
		my $box = shift;
		$returner->{'dialog'} = $c->render_to_string(
			template => 'folders/dialog_box',
			folders => $folders,
			box => $box,
			uuid => &subs::random_string_creator(10)
		);
		return;
	};

	if ($command eq 'new_file' || $command eq 'new_folder') {
		my $is_folder = ($command eq 'new_folder') ? 1 : 0;
		my $name = &folders_name_cleaner($inputs->{ $is_folder ? 'foldername' : 'filename' });
		my $name_of = $is_folder ? 'New Folder' : 'New File';
		if (!defined $name || !defined $folder || !length $folder) {
			$answer->({ name => $name_of, text => 'That is not a name a file can have.', cancel => 'no' });
		}
		elsif (-e $folder . '/' . $name) {
			$answer->({ name => $name_of, text => &subs::format_name($name) . ' is already there.', cancel => 'no' });
		}
		else {
			if ($is_folder) { Mojo::File->new($folder . '/' . $name)->make_path; }
			else { open my $fh, '>', $folder . '/' . $name; close $fh; }
			$returner->{'status'} = 'ok';
		}
	}
	elsif ($command eq 'rename') {
		my $path = $folders->{'path'};
		my $name = &folders_name_cleaner($inputs->{'filename'});
		my @parts = split '/', ($path || '');
		my $was = pop @parts;
		my $into = join '/', @parts;
		if (!defined $name || !defined $path || !length $path) {
			$answer->({ name => 'Rename', text => 'That is not a name a file can have.', cancel => 'no' });
		}
		elsif ($name eq $was) {
			$returner->{'status'} = 'ok';
		}
		elsif (-e $into . '/' . $name) {
			$answer->({ name => 'Rename', text => &subs::format_name($name) . ' is already there.', cancel => 'no' });
		}
		elsif (rename($path, $into . '/' . $name)) {
			$returner->{'status'} = 'ok';
		}
		else {
			$answer->({ name => 'Rename', text => &subs::format_name($was) . ' could not be renamed.', cancel => 'no' });
		}
	}
	elsif ($command eq 'delete' || $command eq 'shred') {
		my @errors = @{ &folders_delete_away($command, [ &folders_command_items($folders) ]) };
		if (scalar @errors) {
			$answer->({ name => &subs::format_name($command), text => join("\n", @errors), cancel => 'no' });
			$returner->{'status'} = 'error';
			$returner->{'error'} = join '; ', @errors;
		}
		else {
			$returner->{'status'} = 'ok';
		}
	}
	elsif ($command eq 'restore_trash') {
		my @items = &folders_command_items($folders);
		my @errors;
		foreach my $item ( @items ) {
			my @parts = split '/', ($item->{'path'} || '');
			my $name = pop @parts;
			my $restored = &folders_trash_restore($name);
			push @errors, $restored->{'error'} unless $restored->{'ok'};
		}
		if (scalar @errors) {
			$answer->({ name => &subs::ui('Restore'), text => join("\n", @errors), cancel => 'no' });
			$returner->{'status'} = 'error';
			$returner->{'error'} = join '; ', @errors;
		}
		else { $returner->{'status'} = 'ok'; }
	}
	elsif ($command eq 'empty_trash') {
		my $emptied = &folders_trash_empty();
		$returner->{'status'} = 'ok';
		$returner->{'emptied'} = $emptied;
	}
	elsif ($command eq 'paste') {
		my @items = @{$folders->{'clipboard'} || []};
		my $move = (($folders->{'command'} || '') eq 'cut') ? 1 : 0;
		if (!scalar @items) {
			$answer->({ name => 'Paste', text => 'The clipboard is empty.', cancel => 'no' });
		}
		elsif (!defined $folder || !length $folder || !-d $folder) {
			$answer->({ name => 'Paste', text => 'The folder to paste into is not there.', cancel => 'no' });
		}
		else {
			my $id = &subs::minion_grabber()->enqueue(folders_copy => [ { items => \@items, to => $folder, move => $move } ] => { retries => 1 });
			$answer->({
				name => $move ? 'Moving' : 'Copying',
				text => scalar(@items) . ' item(s) into ' . $folder,
				job => $id,
				progress => 'starting',
				ok => 'no',
				cancel => 'no',
				height => '220px'
			});
			$returner->{'status'} = 'ok';
		}
	}
	elsif ($command eq 'encrypt' || $command eq 'decrypt') {
		my @items = &folders_command_items($folders);
		my $suds = eval { &subs::suds_grabber() };
		if (!scalar @items) {
			$answer->({ name => &subs::format_name($command), text => 'Nothing is selected.', cancel => 'no' });
		}
		elsif (!defined $suds || !length $suds) {
			$answer->({ name => &subs::format_name($command), text => 'There is no suds on duty to use.', cancel => 'no' });
		}
		else {
			my $task = ($command eq 'encrypt') ? 'folders_encrypt' : 'folders_decrypt';
			my $id = &subs::minion_grabber()->enqueue($task => [ { items => \@items, suds => $suds } ] => { retries => 1 });
			$answer->({
				name => ($command eq 'encrypt') ? 'Encrypting' : 'Decrypting',
				text => scalar(@items) . ' item(s)',
				job => $id,
				progress => 'starting',
				ok => 'no',
				cancel => 'no',
				height => '220px'
			});
			$returner->{'status'} = 'ok';
		}
	}
	$c->render(json => $returner);
};

# How a job the folders app queued is getting on: the note the worker last
# wrote on it and where it ended, which is what the dialog box that started it
# shows while it runs.
get '/manager/folders/job' => sub($c) {
	my $job = &subs::minion_grabber()->job($c->param('id'));
	unless ($job) {
		$c->render(json => { status => 'error', error => 'no such job' });
		return;
	}
	my $info = $job->info || {};
	my $payload = $info->{'result'} || $info->{'error'} || {};
	$payload = {} unless ref $payload;
	$c->render(json => {
		status => 'ok',
		state => $info->{'state'},
		progress => ($info->{'notes'} || {})->{'progress'},
		errors => $payload->{'errors'},
		payload => $payload
	});
};

# Stop a queued job, or ask a running one to stop. A job that has not started
# is simply removed; one that is already going cannot be killed from this
# process, so it is told instead and looks for the note between files.
post '/manager/folders/job/cancel' => sub($c) {
	my $job = &subs::minion_grabber()->job($c->param('id'));
	unless ($job) {
		$c->render(json => { status => 'error', error => 'no such job' });
		return;
	}
	my $state = $job->info->{'state'};
	if ($state eq 'active') {
		$job->note(cancel => 1);
		$c->render(json => { status => 'ok', state => $state, asked => 1 });
		return;
	}
	$job->remove;
	$c->render(json => { status => 'ok', state => 'removed' });
};

# Open what is selected with whatever this machine opens that kind of file
# with: the desktop's own choice, which is the one thing a file manager can
# offer that the apps cannot. A remote listing is read-only and never gets
# here, so this always opens on the machine in front of the screen.
post '/manager/folders/open_with' => sub($c) {
	my $folders = eval { return decode_json $c->param('folders') } || {};
	my @paths = map { $_->{'path'} } grep { -e $_->{'path'} } &folders_command_items($folders);
	&subs::subprocessor(sub {
		my $opener;
		if ($ENV{'TERMUX_VERSION'} || -d '/data/data/com.termux') { $opener = 'termux-open' }
		elsif (-x '/usr/bin/xdg-open') { $opener = '/usr/bin/xdg-open' }
		return unless $opener;
		foreach my $path ( @paths ) {
			system($opener, $path);
		}
	}, { name => 'folders open with' });
	$c->render(json => { status => 'ok', opened => scalar @paths });
};

post '/manager/folders/archive' => sub($c) {
	my $folders = eval { return decode_json $c->param('folders') } || {};
	my $items = $folders->{'selected'} || [];
	# the background menu archives the folder being looked at, which is not a
	# selection of anything
	@{$items} = ( { path => ($folders->{'path'} || $folders->{'folder'}), type => 'folder' } ) if !scalar @{$items} && ($folders->{'path'} || $folders->{'folder'});
	my $device = &subs::device_setter();
	my $misc = &Manager::misc_setting_list();
	my $plan = &subs::archive_plan({
		items => $items,
		settings => $misc->{$device} || {},
		machines => &subs::remote_machine_lister({})
	});
	my $minion = &subs::minion_grabber();
	my @queued;
	foreach my $item ( @{$plan->{'jobs'}} ) {
		push @queued, { %{$item}, id => $minion->enqueue(archive_transfer => [ $item ] => { retries => 3 }) };
	}
	$log->info('archive: queued ' . scalar(@queued) . ' item(s), refused ' . scalar @{$plan->{'refused'}});
	# the answer the folders app shows: plain text, the dialog template escapes it
	my @refused_text = map { $_->{'path'} . ' (' . $_->{'reason'} . ')' } @{$plan->{'refused'}};
	my $text = 'Nothing to archive.';
	if (scalar @queued && scalar @refused_text) {
		$text = scalar(@queued) . ' item(s) queued for the archive; not queued: ' . join '; ', @refused_text;
	}
	elsif (scalar @queued) {
		$text = scalar(@queued) . ' item(s) queued for the archive.';
	}
	elsif (scalar @refused_text) {
		$text = 'Nothing was queued: ' . join '; ', @refused_text;
	}
	my $dialog = $c->render_to_string(
		template => 'folders/dialog_box',
		folders => $folders,
		box => { name => 'Archive', text => $text, cancel => 'no', height => '220px' },
		uuid => &subs::random_string_creator(10)
	);
	$c->render(json => { status => 'ok', queued => \@queued, refused => $plan->{'refused'}, dialog => $dialog });
};

# Stop a queued item, or ask a running one to stop. A job that has not started
# is simply removed; one that is already going cannot be killed from this
# process, so it is told instead and the transfer checks between files.
post '/manager/folders/archive/cancel' => sub($c) {
	my $minion = &subs::minion_grabber();
	my $job = $minion->job($c->param('id'));
	unless ($job) {
		$c->render(json => { status => 'error', error => 'no such job' });
		return;
	}
	my $state = $job->info->{'state'};
	if ($state eq 'active') {
		$job->note(cancel => 1);
		$c->render(json => { status => 'ok', state => $state, asked => 1 });
		return;
	}
	$job->remove;
	$c->render(json => { status => 'ok', state => 'removed' });
};

# Put a failed or finished item back on the queue. The transfer skips whatever
# already landed, so the retry only carries what did not.
post '/manager/folders/archive/retry' => sub($c) {
	my $minion = &subs::minion_grabber();
	my $job = $minion->job($c->param('id'));
	unless ($job) {
		$c->render(json => { status => 'error', error => 'no such job' });
		return;
	}
	$job->retry({ delay => 0 });
	$c->render(json => { status => 'ok', id => $c->param('id') });
};

# Which location an archived path belongs to and where it sits inside it, asked
# of the machine that owns the drive. A caller that only has a path on that
# machine - a selection in folders, a track, a photo - asks this first, and the
# answer is what a fetch needs.
post '/manager/folders/archive/locate' => sub($c) {
	if ($c->param('remote_uuid') && $c->param('remoted') ne 'yes') {
		my $result = &Manager::remote_relay_request($c);
		if (length $result) {
			$c->res->headers->content_type('application/json');
			$c->render(text => $result);
			return;
		}
	}
	my $root = &subs::archive_root();
	if (!$root || !-d $root) {
		$c->render(json => { status => 'error', error => 'this machine is not an archive' });
		return;
	}
	my $path = $c->param('path');
	$path =~ s{/+$}{} if defined $path;
	foreach my $location ( &subs::location_types() ) {
		my $folder = $root . '/' . $location;
		next unless (defined $path && $path =~ m{^\Q$folder\E/});
		$c->render(json => {
			status => 'ok',
			location => $location,
			relative => substr($path, length($folder) + 1),
			folder => $folder,
			folder_path => (-d $path ? 1 : 0)
		});
		return;
	}
	$c->render(json => { status => 'error', error => 'not inside any archive location' });
};

# Bring something that lives in an archive back to this machine. The path as it
# is on the other machine is enough: that machine says which location it is and
# where it sits inside it, and this one puts it back where it came from. One
# item per request, folder or file, so a series or an album comes home whole.
post '/manager/folders/archive/fetch' => sub($c) {
	my $remote_uuid = $c->param('remote_uuid');
	my $path = $c->param('path');
	unless ($remote_uuid && defined $path && length $path) {
		$c->render(json => { status => 'error', error => 'a path and the machine holding it are needed' });
		return;
	}
	my $located = &subs::archive_remote_locate({ remote_uuid => $remote_uuid, path => $path });
	if ($located->{'error'}) {
		$c->render(json => { status => 'error', error => $located->{'error' } });
		return;
	}
	my $into = &subs::archive_local_destination({ location => $located->{'location'}, relative => $located->{'relative'} });
	if ($into->{'error'}) {
		$c->render(json => { status => 'error', error => $into->{'error'} });
		return;
	}
	my $id = &subs::minion_grabber()->enqueue(archive_fetch_home => [ {
		remote_uuid => $remote_uuid,
		location => $located->{'location'},
		relative => $located->{'relative'},
		folder => $located->{'folder_path'},
		archive_path => $path
	} ] => { retries => 2 });
	$c->render(json => {
		status => 'ok',
		id => $id,
		location => $located->{'location'},
		relative => $located->{'relative'},
		to => $into->{'path'}
	});
};

# The queue as the folders app shows it: every archive job this machine holds,
# newest first, with the note the worker last wrote on it, and the locations
# this device archives so the panel can offer a rescan for one.
get '/manager/folders/archive' => sub($c) {
	my $list = &subs::minion_grabber()->backend->list_jobs(0, 200, { tasks => ['archive_transfer', 'archive_manifest_rescan', 'archive_fetch_home'] })->{'jobs'} || [];
	my @jobs;
	foreach my $job ( @{$list} ) {
		my $item = ($job->{'args'} || [])->[0] || {};
		my $result = $job->{'result'} || {};
		push @jobs, {
			id => $job->{'id'},
			task => $job->{'task'},
			state => $job->{'state'},
			attempts => $job->{'attempts'},
			retries => $job->{'retries'},
			created => $job->{'created'},
			finished => $job->{'finished'},
			item => $item,
			progress => ($job->{'notes'} || {})->{'progress'},
			sent => $result->{'sent'},
			skipped => $result->{'skipped'},
			bytes => $result->{'bytes'},
			files => $result->{'files'},
			rows => $result->{'rows'},
			errors => $result->{'errors'}
		};
	}
	my $misc = &Manager::misc_setting_list();
	my $device = &subs::device_setter();
	my $machines = &subs::remote_machine_lister({ self => 'no' });
	my %machine_for;
	foreach my $rm ( @{$machines} ) {
		$machine_for{$rm->{'signatorial'}} = $rm if $rm->{'signatorial'};
	}
	my @locations;
	foreach my $location ( &subs::location_types() ) {
		my $where = $misc->{$device}->{$location . '_location'};
		my $archive = $misc->{$device}->{$location . '_archive'};
		next unless ($where && $archive);
		push @locations, {
			location => $location,
			where => $where,
			remote_uuid => $machine_for{$archive} ? $machine_for{$archive}->{'uuid'} : '',
			remote_hostname => $machine_for{$archive} ? $machine_for{$archive}->{'hostname'} : $archive
		};
	}
	$c->render(json => { status => 'ok', jobs => \@jobs, locations => \@locations });
};

# Where a finished transfer puts what it delivered: one line for the whole job,
# because the listing underneath is only rewritten when the journal piles up.
post '/manager/folders/archive/manifest/append' => sub($c) {
	my $location = $c->param('location');
	my $rows = eval { return decode_json $c->param('rows') } || [];
	my $dest = &subs::archive_destination({ location => $location, path => '' });
	if ($dest->{'error'}) {
		$c->render(json => { status => 'error', error => $dest->{'error'} });
		return;
	}
	my @clean;
	foreach my $row ( @{$rows} ) {
		next unless (ref $row && defined $row->{'relative'} && length $row->{'relative'});
		# resolved the way a receive would resolve it, so what is listed is what
		# would be written and nothing can point outside the location folder
		my $into = &subs::archive_destination({ location => $location, path => $row->{'relative'} });
		next if $into->{'error'};
		push @clean, { %{$row}, relative => $into->{'relative'} };
	}
	Mojo::File->new($dest->{'folder'})->make_path;
	write_file($dest->{'folder'} . '/manifest.jsonl', { append => 1 }, encode_json(\@clean) . "\n") if scalar @clean;
	# fold the journal into the listing once it has piled up, so a read is not a
	# hundred lines to walk through every time
	my $manifest = &subs::archive_manifest_read({ dir => $dest->{'folder'} });
	my $compacted = 0;
	if ($manifest->{'journal_lines'} > 200) {
		&subs::archive_manifest_write({ dir => $dest->{'folder'}, rows => $manifest->{'rows'} });
		$compacted = 1;
	}
	$log->info('archive: manifest for ' . $location . ' +' . scalar(@clean) . ' row(s)' . ($compacted ? ', compacted' : ''));
	$c->render(json => { status => 'ok', rows => scalar @clean, compacted => $compacted });
};

# What an archive holds for a location: relative paths, sizes, times and the
# media facts, so a library can be built from one small request instead of a
# walk over the tunnel.
post '/manager/folders/archive/manifest' => sub($c) {
	if ($c->param('remote_uuid') && $c->param('remoted') ne 'yes') {
		my $result = &Manager::remote_relay_request($c);
		if (length $result) {
			$c->res->headers->content_type('application/json');
			$c->render(text => $result);
			return;
		}
	}
	my $location = $c->param('location');
	my $dest = &subs::archive_destination({ location => $location, path => '' });
	if ($dest->{'error'}) {
		$c->render(json => { status => 'error', error => $dest->{'error'} });
		return;
	}
	my $manifest = &subs::archive_manifest_read({ dir => $dest->{'folder'} });
	$c->render(json => {
		status => 'ok',
		location => $location,
		folder => $dest->{'folder'},
		rows => $manifest->{'rows'},
		journal_lines => $manifest->{'journal_lines'}
	});
};

# Read an archive location again from the drive, as a job, because it opens
# every file it finds.
post '/manager/folders/archive/manifest/rescan' => sub($c) {
	if ($c->param('remote_uuid') && $c->param('remoted') ne 'yes') {
		my $result = &Manager::remote_relay_request($c);
		if (length $result) {
			$c->res->headers->content_type('application/json');
			$c->render(text => $result);
			return;
		}
	}
	my $location = $c->param('location');
	my $dest = &subs::archive_destination({ location => $location, path => '' });
	if ($dest->{'error'}) {
		$c->render(json => { status => 'error', error => $dest->{'error'} });
		return;
	}
	my $id = &subs::minion_grabber()->enqueue(archive_manifest_rescan => [ { location => $location } ] => { retries => 1 });
	$c->render(json => { status => 'ok', id => $id, location => $location });
};

# The archive root's per-location folders, made and checked on demand, so the
# folders app can show what an archive holds.
get '/manager/folders/archive/dirs' => sub($c) {
	$c->render(json => &subs::archive_scaffolder());
};

# An archive machine answering for its own root. A sending machine asks first
# whether the item is already there, so a second pass over a folder costs one
# small request per file instead of the file itself.
post '/manager/folders/archive/probe' => sub($c) {
	my $dest = &subs::archive_destination({ location => $c->param('location'), path => $c->param('path') });
	if ($dest->{'error'}) {
		$c->render(json => { status => 'error', error => $dest->{'error'} });
		return;
	}
	my $exists = -e $dest->{'path'} ? 1 : 0;
	my @stat = $exists ? stat($dest->{'path'}) : ();
	$c->render(json => {
		status => 'ok',
		path => $dest->{'path'},
		exists => $exists,
		# so the sender can skip a file it has already delivered unchanged
		size => $exists ? -s $dest->{'path'} : undef,
		mtime => $exists ? $stat[9] : undef
	});
};

# The upload half of archiving: the item is posted here and lands in
# <archive root>/<location>/<path>, so transfers ride the same tunnel and
# session as every other manager to manager request instead of rsync.
post '/manager/folders/archive/receive' => sub($c) {
	my @uploads = @{$c->req->uploads};
	my $upload = $uploads[0];
	unless ($upload) {
		$c->render(json => { status => 'error', error => 'no file in the request' });
		return;
	}
	my $dest = &subs::archive_destination({ location => $c->param('location'), path => $c->param('path') });
	if ($dest->{'error'}) {
		$c->render(json => { status => 'error', error => $dest->{'error'} });
		return;
	}
	Mojo::File->new($dest->{'parent'})->make_path;
	eval { $upload->move_to($dest->{'path'}) };
	if ($@) {
		$c->render(json => { status => 'error', error => "$@", path => $dest->{'path'} });
		return;
	}
	my $written = -s $dest->{'path'};
	# keep the source's time, so the next pass over the same folder can tell an
	# unchanged file from a changed one by size and time instead of by the file
	my $mtime = $c->param('mtime');
	utime $mtime, $mtime, $dest->{'path'} if ($mtime && $mtime =~ /^\d+$/);
	$log->info('archive: received ' . $dest->{'path'} . ' (' . $written . ' bytes)');
	$c->render(json => { status => 'ok', path => $dest->{'path'}, size => $written });
};

post '/manager/folders/file/open' => sub ($c) {

	my $folders = eval { return decode_json $c->param('folders') } || {};
	my $type = $folders->{'type'};
	my $path = $folders->{'path'};
	my ($raw_files,$files) = [];
	my $app;
	# the same padlock this window holds for its own listing
	my $unlocked = media_unlock_open($c, 'folders') ? 1 : 0;

	if ($type eq 'image') {
		$app = 'gallery';
	} elsif ($type eq 'audio') {
		$app = 'music';
	} elsif ($type eq 'video') {
		$app = 'music';
	} elsif ($type eq 'document' || $type eq 'subtitles') {
		$app = 'ide';
	}
	# What the app is handed: the clicked file first, then its siblings of the
	# same kind from the same folder. A gallery and a player are a set, not one
	# file - opening a photo should offer the rest of the photos beside it, the
	# way a desktop viewer does; opening a track should queue the album. IDE is
	# deliberately left alone: each raw file opens its own editor tab, so handing
	# it a folder's worth would open a folder's worth of editors.
	my @chosen = grep { ($_->{'type'} || '') eq $type } @{ $folders->{'selected'} || [] };
	my $first = $folders->{'path'};
	$first = $chosen[0]->{'path'} if (!defined $first || !length $first) && scalar @chosen;
	if (defined $first && length $first) {
		my @front = grep { $_->{'path'} eq $first } @chosen;
		@chosen = ( @front, grep { $_->{'path'} ne $first } @chosen );
		@chosen = ( { path => $first, type => $type }, @chosen ) unless scalar @front;
	}
	# The folder these files came from is the album the gallery shows behind the
	# photo, so name it the way Folders names that folder.
	my $album = '';
	if (defined $first && length $first) {
		my $dir = $first;
		$dir =~ s{/[^/]*$}{};
		$dir = '/' unless length $dir;
		$album = &folders_display_name($dir);
		$album = '/' unless length $album;
	}
	if (!$folders->{'remote_uuid'} && $app && ($app eq 'gallery' || $app eq 'music') && scalar @chosen) {
		my $dir = $chosen[0]->{'path'};
		$dir =~ s{/[^/]*$}{};
		$dir = '/' unless length $dir;
		# the listing applies the same padlock and hidden-app rules the window
		# saw, so a sibling cannot be opened that the listing kept out of sight
		my $listing = &folders_listing($dir, $unlocked, $c, $folders->{'show_hidden'} ? 1 : 0);
		my %seen = map { $_->{'path'} => 1 } @chosen;
		foreach my $sibling ( @{ $listing->{'files'} || [] } ) {
			next if $seen{ $sibling->{'path'} }++;
			next unless (($sibling->{'type'} || '') eq $type);
			push @chosen, { path => $sibling->{'path'}, type => $sibling->{'type'} };
		}
	}
	foreach my $fs ( @chosen ) {
		my @stat = stat($fs->{'path'});
		my $temp = {};
		$temp->{'size'} = $stat[7];
		$temp->{'modified'} = $stat[9];
		$temp->{'created'} = $stat[10];
		$temp->{'accessed'} = $stat[8];
		push @{$raw_files}, $fs->{'path'};
		push @{$files},	{
			app => '__president',
			source => 'folders',
			f => $fs->{'path'},
			file => $fs->{'path'},
			uuid => &subs::random_string_creator(10),
			server_time => $temp->{'created'} * 1000,
			type => $fs->{'type'},
			label => $album
		};
	}
	# `target` is the file the person picked: the gallery opens it in the viewer
	# with this folder's photos behind it, so closing it lands on the album.
	my $returner = { raw_files => $raw_files, files => $files, app => $app, target => ($first // ''), album => $album };


	$c->render(json => $returner);

};

sub file_type_recognizer($f) {

	my $file_type;
	$file_type = 'image' if $f =~ /jpg|png|bmp|tiff|xcf/;
	$file_type = 'audio' if $f =~ /wav|mp3|aiff|weba|m4a|flac/;
	$file_type = 'video' if $f =~ /mp4|avi|mov|webm|mkv/;
	$file_type = 'pdf' if $f =~ /pdf/;
	$file_type = 'document' if $f =~ /doc|docx|xls|xlsx|pub|pubx|txt|rtf/;
	$file_type = 'subtitles' if $f =~ /vtt|srt/;
	my $file = {
		type => $file_type,
		icon => '/images/decipherable/file.png'
	};
	if ( -d $f) {
		$file->{'type'} = 'folder';
		$file->{'icon'} = '/images/decipherable/folder.png';
	}
	elsif ($f =~ /\.enc$/i) {
		# a sealed file wears the extension of what it holds - sealing keeps
		# it so opening can hand the file back as itself - so a picture inside
		# can still show itself and open in the images app, which reads it
		# through /file_open like any other picture; anything else says only
		# that it is sealed
		if ($file_type && $file_type eq 'image') {
			$file->{'icon'} = '/file_open?file=' . uri_encode $f;
		}
		else {
			$file->{'type'} = 'encrypted';
			$file->{'icon'} = '/images/make believe/lock.png';
		}
	}
	elsif ($file_type eq 'image' || $file_type eq 'video') {
		$file->{'icon'} = '/file_open?file=' . uri_encode $f;
	}
	elsif ($file_type eq 'subtitles') {
		$file->{'icon'} = '/images/decipherable/list.png';
	}
	elsif ($file_type eq 'audio') {
		$file->{'icon'} = '/images/make believe/music.png';
	}
	return $file;
}

get '/manager/ide' => sub ($c) {
	my $timestamp = $c->param('timestamp');

	my $website = &ide_opener({ timestamp => $timestamp });
	$c->render(json => $website);
};

sub ide_opener($data) {
	my $timestamp = $data->{'timestamp'};
	my $c = &subs::controller_builder();
	my $settings = &subs::settings_grabber({ app => 'ide' });
	my $search = $data->{'search'};
	my $folder = $data->{'folder'};
	my $root = &subs::home($folder) || &subs::home($settings->{'folder_selector'}) || './';
	# Opening the editor lists only the root's own children; a folder's children
	# arrive from /manager/ide/folder_open when it unfolds. A search still has to
	# read the whole tree - that is what the person asked for - so it keeps the
	# full walk.
	my $files = $search ? &subs::ide_files($root) : &subs::ide_folder_listing($root);

	if ($search) {
		my $searched_files;
		foreach my $f ( @{$files} ) {
			my $fi = $folder . $f->{'file'};
			if ($folder ne './') { $fi = $f->{'file'}; }


			my $contents;
			if (-e $fi) {
				$contents = read_file($fi);
			}
			if ($contents =~ /\Q$search/gi || $fi =~ /\Q$search/gi ) {
				push @{$searched_files}, $f, unless grep { $_->{'file'} eq $f->{'file'} } @{$searched_files};
			}
			$files = $searched_files;
		}

	}


	my $open_tabs = eval { return decode_json $settings->{'open_tabs'} } || {};
	my $tabs = {};
	foreach my $f ( keys %{$open_tabs} ) {
		if ($open_tabs->{$f}->{'status'} eq 'open') {
			my ($tab,$content,$file) = &ide_file_open($f,'load');
			$tabs->{$f} = { tab => $tab, content => $content, file => $file};

		}
	}
	# the folders the person had unfolded, so the tree comes back the way they
	# left it; the client unfolds them from these paths, one level at a time
	my @open_folders = eval { @{ decode_json( $settings->{'open_folders'} || '[]' ) } };
	my $open_folders_json = encode_json(\@open_folders);
	# where the file list and each open file were scrolled to
	my $list_scroll = eval { decode_json( $settings->{'list_scroll'} || '{}' ) } || {};
	$list_scroll = {} unless ref $list_scroll eq 'HASH';
	my $editor_scroll = eval { decode_json( $settings->{'editor_scroll'} || '{}' ) } || {};
	$editor_scroll = {} unless ref $editor_scroll eq 'HASH';
	# which pane was showing: the file list or the editor
	my $view = ($settings->{'view'} && $settings->{'view'} eq 'editor') ? 'editor' : 'list';
	my $bgc = &subs::setting_grabber({ app => 'misc', setting => 'ide_sidebar_container_background_colour', device => $device });
	my $contents = $c->render_to_string(
		files => $files,
		template => 'ide',
		tabs => $tabs,
		window_maker => $c->param('window_maker'),
		background_colour => $bgc,
		misc_settings => &misc_setting_list(),
		device => $device,
		settings => $settings,
		search => $search,
		open_folders_json => $open_folders_json,
		list_scroll_json => encode_json($list_scroll),
		editor_scroll_json => encode_json($editor_scroll),
		view_json => encode_json($view)
	);
	my $website = &Manager::window_maker({ user_agent => $c->param('user_agent'), app => 'ide', contents => $contents }, $timestamp);
	return { html => $website, tabs => $tabs, settings => $settings, open_folders => \@open_folders };
}

post '/manager/ide/folder_selector' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $folder = $c->param('folder');
	my $search = $c->param('search');
	my $previous = &subs::setting_grabber({ app => 'ide', setting => 'folder_selector' });
	# a chosen root that actually changed starts clean: folders remembered under the
	# old root have no rows here to unfold into. An empty folder is the start-menu
	# open, which keeps whatever the person had unfolded.
	if (defined $folder && length $folder && $folder ne ($previous // '')) {
		&subs::setting_setter({ app => 'ide', setting => 'open_folders', value => '[]' });
	}
	&subs::setting_setter({ app => 'ide', setting => 'folder_selector', value => $folder });
	my $website = &ide_opener({ timestamp => $timestamp, folder => $folder, search => $search });
	$c->render(json => $website);
};

