# The paired-device plumbing shared by pair, device login, recovery and the
# approval door.
sub device_pubkey_clean($armor) {
	return unless $armor;
	return $armor if $armor =~ /BEGIN PUBLIC KEY/;
	return "-----BEGIN PUBLIC KEY-----\n" . $armor . "\n-----END PUBLIC KEY-----\n" if $armor =~ /^[A-Za-z0-9+\/=\r\n]+$/;
	return;
}

sub device_store_pubkey($armor, $name, $agent, $person_uuid) {
	my $pem = &device_pubkey_clean($armor);
	return unless $pem;
	my $now = &subs::rightNow();
	my $uuid = &subs::random_string_creator(25);
	# The kind is a hint for the Security page: a phone, a browser, or the
	# desktop's WebKit windows. An app key or a biometric added later promotes
	# the row to app/phone.
	my $ua = $agent // '';
	my $kind = ($ua =~ /Android|iPhone|iPad|Mobile/i) ? 'phone'
		: ($ua =~ /AppleWebKit\/605/ && $ua =~ /Linux|X11/) ? 'webview'
		: 'browser';
	my $data = {
		uuid => $uuid,
		name => substr($name || 'Device', 0, 60),
		pubkey => $pem,
		privilege => 'citizen',
		status => 'active',
		timestamp => $now,
		server_time => $now,
		agent => substr($agent // '', 0, 400),
		kind => $kind
	};
	$data->{'person_uuid'} = $person_uuid if defined $person_uuid && length $person_uuid;
	&subs::db_insert('paired_devices', $data);
	return $uuid;
}

sub device_session_mint($c, $device_uuid) {
	my ($db,$database) = &subs::database_grabber();
	return unless $db;
	my $now = &subs::rightNow();
	my $warranty = &subs::ago_calc(&subs::setting_grabber({ app => 'me', setting => 'login_warranty' }) || '-3h', $now);
	my $person = &subs::person_for_device($device_uuid);
	# A device nobody has claimed is not a citizen: the person is the identity.
	# The owner backfill attaches the devices that predate this rule; a device
	# paired later waits, as guest, until a citizen assigns it.
	my $privilege = &subs::person_privilege($person);
	$c->session('authentication' => 'approved');
	$c->session('database' => $database);
	$c->session('suds_id' => &subs::suds_id(&subs::session_suds($c)));
	$c->session('warranty' => $warranty);
	$c->session('string' => &subs::random_string_creator());
	$c->session('name' => &subs::setting_grabber({ app => 'me', setting => 'name' }));
	$c->session('privilege' => $privilege);
	$c->session('person_uuid' => ($person ? $person->{'uuid'} : undef));
	$c->session('source' => 'device');
	$c->session('device_uuid' => $device_uuid);
	$c->session('server_time' => $now);
	&subs::db_update('paired_devices', { last_seen => $now }, { uuid => $device_uuid }) if $device_uuid;
	return 1;
}

# --- paired devices -----------------------------------------------------------
# A citizen session pairs the browser it runs in: the ticket scan (or the
# password login) is the pairing grant, one public key is stored, and after
# that the device logs itself in with a signed challenge - no ticket to lose,
# no password, any network. The private key never leaves the device.
post '/manager/device/pair' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0, error => 'citizen session required' });
		return;
	}
	# A locked screen must not mint a fresh identity: padlock_device_until is
	# keyed by device uuid, so pairing again would hand the page a uuid with no
	# lock row and let it walk straight past a single-screen lock (the exact
	# "I locked it and still have full access" escape). The recovery route is
	# the door for a screen with no usable key.
	if (&padlock_locked_now($c)) {
		$c->render(json => { ok => 0, error => 'locked' });
		return;
	}
	my $name = substr($c->param('name') || 'Device', 0, 60);
	my $person_uuid = $c->session('person_uuid') || &subs::people_owner_ensure();
	my $uuid = &device_store_pubkey($c->param('pubkey'), $name, $c->req->headers->user_agent, $person_uuid);
	unless ($uuid) { $c->render(json => { ok => 0, error => 'no key' }); return; }
	$c->session('device_uuid' => $uuid);
	$c->render(json => { ok => 1, device_uuid => $uuid, name => $name });
};

post '/manager/device/challenge' => sub($c) {
	my $device_uuid = $c->param('device_uuid') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	unless ($device) { $c->render(json => { ok => 0 }); return; }
	my $nonce = &subs::random_string_creator(40);
	my $now = &subs::rightNow();
	&subs::db_query('delete from cache where context = ? and uuid like ?', 'device_nonce', $device_uuid . ':%');
	&subs::db_query('insert into cache (uuid, context, app, server_time, timestamp) values (?,?,?,?,?)', $device_uuid . ':' . $nonce, 'device_nonce', '__president', $now, $now);
	$c->render(json => { ok => 1, nonce => $nonce });
};

post '/manager/device/login' => sub($c) {
	# A locked screen does not renew itself by logging in a device: that path
	# would switch the session to any paired uuid (including a fresh one) and
	# leave the lock behind. Unlocking is padlock_unlock / biometric_unlock.
	if (&padlock_locked_now($c)) {
		$c->render(json => { ok => 0, error => 'locked' });
		return;
	}
	my $device_uuid = $c->param('device_uuid') || '';
	my $nonce = $c->param('nonce') || '';
	my $signature = $c->param('signature') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	unless ($device && $nonce =~ /^[A-Za-z0-9]{8,64}$/) { $c->render(json => { ok => 0 }); return; }
	my ($db,$database) = &subs::database_grabber();
	unless ($db) { $c->render(json => { ok => 0 }); return; }
	my $stamp = $device_uuid . ':' . $nonce;
	my $now = &subs::rightNow();
	my $seen = &subs::db_query('select server_time from cache where context = ? and uuid = ? limit 1', 'device_nonce', $stamp)->hashes->[0];
	unless ($seen && $seen->{'server_time'} && $seen->{'server_time'} > $now - 120000) { $c->render(json => { ok => 0 }); return; }
	my $msg = join "\n", ('device-login', $device_uuid, $nonce);
	unless (&subs::signature_verify($device->{'pubkey'}, $msg, $signature)) { $c->render(json => { ok => 0 }); return; }
	&subs::db_query('delete from cache where context = ? and uuid = ?', 'device_nonce', $stamp);
	&device_session_mint($c, $device_uuid);
	$c->render(json => { ok => 1, name => $device->{'name'} });
};

# --- app keys ----------------------------------------------------------------
# The private manager is reachable only when the session carries a native app
# key proof. A phone's key is its Android Keystore biometric key; a desktop's is
# a key the desktop app holds and signs with. A browser has neither, so it can
# pair and log in but never become an app session.
post '/manager/device/app_challenge' => sub($c) {
	&app_schema_ensure();
	my $device_uuid = $c->param('device_uuid') || $c->session('device_uuid') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	unless ($device) { return $c->render(json => { ok => 0, error => 'not paired' }); }
	my $purpose = ($c->param('purpose') || '') eq 'enroll' ? 'enroll' : 'login';
	my $ip = $c->tx->remote_address || '?';
	my $now = &subs::rightNow();
	my $recent = &subs::db_query('select count(*) as n from cache where context = ? and uuid like ? and server_time > ?', 'app_challenge', $ip . ':%', $now - 60000)->hash->{'n'} || 0;
	if ($recent >= 30) { return $c->render(json => { ok => 0, error => 'too many' }); }
	&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'app_challenge', app => '__president', server_time => $now, timestamp => $now });
	my $nonce = &subs::random_string_creator(40);
	&subs::db_query('delete from cache where context = ? and server_time < ?', 'app_nonce', $now - 180000);
	&subs::db_insert('cache', { uuid => $purpose . ':' . $device_uuid . ':' . $nonce, context => 'app_nonce', app => '__president', server_time => $now, timestamp => $now });
	$c->render(json => { ok => 1, nonce => $nonce, seconds => 120 });
};

sub app_nonce_take {
	my ($purpose, $device_uuid, $nonce, $ttl) = @_;
	$ttl ||= 120000;
	return 0 unless defined $nonce && $nonce =~ /^[A-Za-z0-9]{8,64}$/;
	my $stamp = $purpose . ':' . $device_uuid . ':' . $nonce;
	my $seen = &subs::db_query('select server_time from cache where context = ? and uuid = ? limit 1', 'app_nonce', $stamp)->hashes->[0];
	return 0 unless $seen && $seen->{'server_time'} && $seen->{'server_time'} > &subs::rightNow() - $ttl;
	&subs::db_query('delete from cache where context = ? and uuid = ?', 'app_nonce', $stamp);
	return 1;
}

post '/manager/device/app_login' => sub($c) {
	&app_schema_ensure();
	my $device_uuid = $c->param('device_uuid') || $c->session('device_uuid') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	unless ($device) { return $c->render(json => { ok => 0, error => 'not paired' }); }
	my ($pubkey, $kind) = &app_key_for($device);
	return $c->render(json => { ok => 0, error => 'no app key' }) unless $pubkey;
	my $nonce = $c->param('nonce') || '';
	return $c->render(json => { ok => 0, error => 'no challenge' }) unless &app_nonce_take('login', $device_uuid, $nonce);
	my $msg = join("\n", 'app-login', $device_uuid, $nonce);
	unless (&app_signature_ok($pubkey, $kind, $msg, $c->param('signature') || '')) {
		$log->info('app gate: app login refused for ' . ($device->{'name'} || $device_uuid) . ' from ' . ($c->tx->remote_address || '?'));
		return $c->render(json => { ok => 0, error => 'not accepted' });
	}
	my $until = &subs::rightNow() + 43200000;
	$c->session('app' => 1);
	$c->session('app_until' => $until);
	$c->session('app_device' => $device_uuid);
	$log->info('app gate: app login for ' . ($device->{'name'} || $device_uuid) . ' from ' . ($c->tx->remote_address || '?') . ' host=' . ($c->req->url->host || '-'));
	# The app key is the citizen door: a bootstrap session that pairs an app is
	# promoted here, or the citizen-only routes would still read guest.
	# A person is the identity; the device is how they carry it. The session
	# records the person when the device has one, and its privilege is the
	# person's. An unclaimed device is a guest, never a citizen; the owner
	# backfill attaches devices that predate the rule, and a later pairing
	# waits for an assignment.
	my $person = &subs::person_for_device($device_uuid);
	my $privilege = &subs::person_privilege($person);
	$c->session('authentication' => 'approved');
	$c->session('privilege' => $privilege);
	$c->session('person_uuid' => ($person ? $person->{'uuid'} : undef));
	$c->session('bootstrap' => undef);
	$log->info('app gate: app login ' . ($device->{'name'} || $device_uuid) . ' kind=' . $kind . ' until=' . $until
		. ' person=' . ($person ? $person->{'uuid'} . '/' . $privilege : 'unassigned'));
	$c->render(json => { ok => 1, until => $until, kind => $kind, name => $device->{'name'} });
};

get '/manager/device/app_status' => sub($c) {
	&app_schema_ensure();
	my $device_uuid = $c->param('device_uuid') || $c->session('device_uuid') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	return $c->render(json => { ok => 0, error => 'not paired' }) unless $device;
	my ($pubkey, $kind) = &app_key_for($device);
	my $pending = &subs::db_select('device_requests', undef, { device_uuid => $device_uuid, kind => 'app', status => 'pending' })->hashes->[0];
	if ($pending && ($pending->{'server_time'} || 0) < &subs::rightNow() - 3600000) {
		# Too old for a person to still be looking at it. Expire it here so the
		# app-required page asks again instead of waiting on a dead request.
		&subs::db_update('device_requests', { status => 'expired', server_time => &subs::rightNow() }, { uuid => $pending->{'uuid'} });
		$pending = undef;
	}
	$c->render(json => {
		ok => 1,
		device => $device_uuid,
		has_app => ($pubkey ? 1 : 0),
		kind => ($kind || ''),
		app_session => (&app_session_ok($c) ? 1 : 0),
		pending => ($pending ? $pending->{'code'} : ''),
	});
};

# The installed app can lose the WebKit profile that held its device uuid (a
# cleared cache, a restored profile) while its key is still the one paired with
# the house. The public key is not a secret and the uuid is not a credential -
# app_login still needs a signature - so name the paired device that owns the
# key, and the page can seed its localStorage and sign in again.
post '/manager/device/app_identify' => sub($c) {
	my $pubkey = $c->param('app_pubkey') || '';
	return $c->render(json => { ok => 0, error => 'no key' }) unless $pubkey =~ /BEGIN PUBLIC KEY/;
	my $device = &subs::db_select('paired_devices', [ 'uuid', 'name' ], { app_pubkey => $pubkey, status => 'active' })->hash;
	return $c->render(json => { ok => 0, error => 'not paired' }) unless $device && ($device->{'uuid'} || '') ne '';
	$log->info('app identify: paired device ' . $device->{'uuid'});
	$c->render(json => { ok => 1, uuid => $device->{'uuid'}, name => ($device->{'name'} || '') });
};

# A desktop app asks to add its native key to an already-paired device. It is
# approved on a trusted app (the phone), so a browser that can reach this route
# cannot mint an app identity for itself.
post '/manager/device/app_request' => sub($c) {
	&app_schema_ensure();
	return $c->render(json => { ok => 0, error => 'not signed in' }) unless $c->session('authentication') eq 'approved';
	my $device_uuid = $c->param('device_uuid') || $c->session('device_uuid') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	return $c->render(json => { ok => 0, error => 'not paired' }) unless $device;
	my ($existing) = &app_key_for($device);
	return $c->render(json => { ok => 1, already => 1 }) if $existing;
	my $nonce = $c->param('nonce') || '';
	return $c->render(json => { ok => 0, error => 'no challenge' }) unless &app_nonce_take('enroll', $device_uuid, $nonce);
	my $pubkey = $c->param('app_pubkey') || '';
	my $kind = ($c->param('app_kind') || 'ed25519') eq 'ec' ? 'ec' : 'ed25519';
	my $ok_key = $kind eq 'ec' ? &subs::ecdsa_public_key_ok($pubkey) : ($pubkey =~ /BEGIN PUBLIC KEY/ ? 1 : 0);
	return $c->render(json => { ok => 0, error => 'bad key' }) unless $ok_key;
	require Digest::SHA;
	my $msg = join("\n", 'app-request', $device_uuid, $nonce, Digest::SHA::sha256_hex($pubkey));
	# The pairing key signs the request when the app still has it. A desktop
	# app whose key lived in an older WebKit profile has the device uuid in
	# localStorage but no private key, so it cannot sign. It may still ASK, but
	# only for the device its own session is bound to - never a uuid the caller
	# picks - and the request still waits for a person to approve it on a
	# trusted app. That approval, not the signature, is the trust boundary.
	my $signed = 0;
	if ($c->param('device_signature')) {
		$signed = 1 if &subs::signature_verify($device->{'pubkey'}, $msg, $c->param('device_signature'));
	}
	unless ($signed) {
		my $session_device = $c->session('device_uuid') || '';
		unless ($session_device && $session_device eq $device_uuid) {
			$log->info('app gate: app request refused unsigned for ' . $device_uuid
				. ' (session device ' . ($session_device || 'none') . ')');
			return $c->render(json => { ok => 0, error => 'not accepted' });
		}
		$log->info('app gate: unsigned app request for ' . $device_uuid . ' (waits for approval)');
	}
	my $name = substr($c->param('name') || 'Desktop app', 0, 60);
	my $now = &subs::rightNow();
	my $code = &subs::device_request_code();
	my $uuid = &subs::random_string_creator(25);
	&subs::db_insert('device_requests', {
		uuid => $uuid, name => $name, pubkey => $device->{'pubkey'}, agent => substr($c->req->headers->user_agent // '', 0, 400),
		code => $code, status => 'pending', device_uuid => $device_uuid, kind => 'app',
		app_pubkey => $pubkey, app_kind => $kind, remote_address => ($c->tx->remote_address || ''),
		timestamp => $now, server_time => $now,
	});
	&device_request_notify($c, $name, $code);
	$c->render(json => { ok => 1, uuid => $uuid, code => $code });
};

post '/manager/security/device_revoke' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { html => '<p>citizen only</p>' });
		return;
	}
	my $uuid = $c->param('uuid');
	&subs::db_delete('paired_devices', { uuid => $uuid }) if $uuid;
	&subs::house_key_share_revoke_device($uuid) if $uuid;
	&subs::db_delete('security', { level => 'padlock_device', uuid => $uuid }) if $uuid;
	&subs::db_query('delete from settings where app = ? and setting = ? and device = ?', '__president', 'padlock_device_time', $uuid) if $uuid;
	$c->render(json => &security_initializer($c));
};

post '/manager/security/person_assign' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0, error => 'citizen only' });
		return;
	}
	my $device_uuid = $c->param('device_uuid') // '';
	my $person_uuid = $c->param('person_uuid') // '';
	my ($ok, $why) = &subs::person_assign_check($device_uuid, $person_uuid, $c->session('device_uuid') || '');
	unless ($ok) { $c->render(json => { ok => 0, error => $why }); return; }
	&subs::db_update('paired_devices', { person_uuid => $person_uuid, server_time => &subs::rightNow() }, { uuid => $device_uuid });
	my $sec = &security_initializer($c);
	$c->render(json => { ok => 1, html => $sec->{'html'} });
};

post '/manager/security/person_create' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0, error => 'citizen only' });
		return;
	}
	my $name = &subs::unformat_name($c->param('name') // '');
	my $privilege = lc($c->param('privilege') // 'resident');
	$privilege = 'resident' unless $privilege =~ /^(?:citizen|resident|guest)$/;
	unless (length $name) { $c->render(json => { ok => 0, error => 'name' }); return; }
	my $now = &subs::rightNow();
	my $uuid = &subs::random_string_creator(25);
	my $made = &subs::db_insert('people', {
		uuid => $uuid,
		name => $name,
		privilege => $privilege,
		status => 'active',
		created => $now,
		server_time => $now,
	});
	unless ($made) { $c->render(json => { ok => 0 }); return; }
	my $sec = &security_initializer($c);
	$c->render(json => { ok => 1, uuid => $uuid, html => $sec->{'html'} });
};

post '/manager/security/shares/create' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0 });
		return;
	}
	my $suds = &subs::session_suds($c);
	unless ($suds && length $suds) { $c->render(json => { ok => 0 }); return; }
	my ($k, $n) = &subs::shamir_policy();
	my $shares = &subs::shamir_split($suds, $k, $n);
	unless ($shares) { $c->render(json => { ok => 0 }); return; }
	# the policy is public and syncs; the shares are shown once and stored nowhere
	my $now = &subs::rightNow();
	&subs::db_query('delete from settings where app = ? and setting = ?', '__president', 'shamir');
	&subs::db_insert('settings', { app => '__president', setting => 'shamir', device => 'all', value => "$k:$n", timestamp => $now, server_time => $now });
	my @codes = map { &subs::shamir_share_encode_paper($_) } @$shares;
	my $qr = &subs::shamir_qr_save(\@codes, 'paper shares');
	my $sec = &security_initializer($c);
	$c->render(json => { ok => 1, k => $k, n => $n, shares => \@codes, qr => $qr, html => $sec->{'html'} });
};

post '/manager/security/person_revoke' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0, error => 'citizen only' });
		return;
	}
	my $person_uuid = $c->param('person_uuid') // '';
	my ($ok, $why) = &subs::person_revoke_check($person_uuid, $c->session('device_uuid') || '');
	unless ($ok) { $c->render(json => { ok => 0, error => $why }); return; }
	my $result = &subs::person_revoke($person_uuid);
	unless ($result) { $c->render(json => { ok => 0, error => 'not revoked' }); return; }
	my $sec = &security_initializer($c);
	$c->render(json => { ok => 1, revoked => $result, html => $sec->{'html'} });
};

post '/manager/security/shares/key' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0 });
		return;
	}
	my $device_uuid = $c->session('device_uuid') || '';
	unless ($device_uuid) { $c->render(json => { ok => 0, error => 'no device' }); return; }
	my $raw = eval { decode_base64($c->param('share_pubkey') // '') };
	unless (defined $raw && length($raw) == 32) { $c->render(json => { ok => 0, error => 'bad key' }); return; }
	&subs::db_update('paired_devices', { share_pubkey => encode_base64($raw, ''), server_time => &subs::rightNow() }, { uuid => $device_uuid });
	$c->render(json => { ok => 1 });
};

# Split this house's key and wrap a share to each chosen device. The shares a
# device takes are stored sealed to its own X25519 key; any share left is
# returned once as paper. One wrapped share per person.
post '/manager/security/shares/wrap' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0 });
		return;
	}
	my $suds = &subs::session_suds($c);
	unless ($suds && length $suds) { $c->render(json => { ok => 0 }); return; }
	my @holders;
	my $picked = $c->param('holders') // '';
	if ($picked =~ /\S/) {
		@holders = grep { /\S/ } split /[\s,]+/, $picked;
	}
	else {
		# one device per person among the devices that registered a share key
		my $rows = eval { &subs::db_query("select uuid, person_uuid from paired_devices where status = 'active' and share_pubkey is not null and share_pubkey != '' order by last_seen desc, server_time desc")->hashes } || [];
		my %seen;
		foreach my $d ( @{$rows} ) {
			my $key = ($d->{'person_uuid'} || '') ne '' ? 'p:' . $d->{'person_uuid'} : 'd:' . $d->{'uuid'};
			next if $seen{$key}++;
			push @holders, $d->{'uuid'};
		}
	}
	my $made = &subs::house_key_share_create_set($suds, \@holders);
	unless ($made) { $c->render(json => { ok => 0 }); return; }
	my $qr = (@{ $made->{'paper'} || [] }) ? &subs::shamir_qr_save($made->{'paper'}, 'paper shares') : undef;
	my $sec = &security_initializer($c);
	$c->render(json => {
		ok => 1,
		set_id => $made->{'set_id'},
		k => $made->{'k'},
		n => $made->{'n'},
		assigned => $made->{'assigned'},
		paper => $made->{'paper'},
		qr => $qr,
		skipped => $made->{'skipped'},
		html => $sec->{'html'},
	});
};

# The wrapped shares this device holds. They are useless to any other device.
post '/manager/security/shares/mine' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0 });
		return;
	}
	my $device_uuid = $c->session('device_uuid') || '';
	unless ($device_uuid) { $c->render(json => { ok => 0, error => 'no device' }); return; }
	# a request names the set it was made against; a holder may hold shares in
	# several sets, so let the caller name the one it means
	my $set_id = $c->param('set_id') || &subs::house_key_share_set_current();
	my $rows = &subs::house_key_share_for_device($device_uuid, $set_id);
	my ($k, $n) = &subs::shamir_policy();
	$c->render(json => {
		ok => 1,
		set_id => $set_id,
		k => $k,
		n => $n,
		shares => [ map { { set_id => $_->{'set_id'}, share_index => $_->{'share_index'}, wrapped => $_->{'wrapped'} } } @{$rows} ],
	});
};

# A recovering machine is asking. Its public key is public; the holders answer
# with blobs this server cannot open.
post '/manager/security/shares/requests' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0 });
		return;
	}
	&subs::house_key_share_cleanup();
	my $rows = &subs::house_key_share_requests_open();
	my $out = [];
	foreach my $r ( @{$rows} ) {
		push @{$out}, {
			uuid => $r->{'uuid'},
			code => $r->{'code'},
			name => $r->{'name'},
			need => $r->{'need'},
			have => $r->{'available'},
			set_id => $r->{'set_id'},
			asker_pubkey => $r->{'asker_pubkey'},
			created => $r->{'created'},
		};
	}
	$c->render(json => { ok => 1, requests => $out });
};

post '/manager/security/shares/release' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0, error => 'citizen only' });
		return;
	}
	my $device_uuid = $c->session('device_uuid') || '';
	my $request_uuid = $c->param('request_uuid') // '';
	my $share_index = $c->param('share_index');
	my $wrapped = $c->param('wrapped') // '';
	my ($ok, $why) = &subs::house_key_share_release_add($request_uuid, $device_uuid, $share_index, $wrapped);
	$c->render(json => { ok => $ok ? 1 : 0, error => $why });
};

post '/manager/security/recovery/create' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0 });
		return;
	}
	my $code = &subs::recovery_code_make();
	my $canon = &subs::recovery_code_clean($code);
	my $suds = &subs::session_suds($c);
	my $sealed = ($suds && length $suds) ? &subs::note_encrypter($canon, $suds) : undef;
	unless ($sealed) { $c->render(json => { ok => 0 }); return; }
	my $now = &subs::rightNow();
	&subs::db_query('delete from settings where app = ? and setting = ?', '__president', 'recovery');
	&subs::db_query('delete from settings where app = ? and setting = ?', '__president', 'recovery_stale');
	&subs::db_insert('settings', { app => '__president', setting => 'recovery', device => 'all', value => $sealed, timestamp => $now, server_time => $now });
	my $sec = &security_initializer($c);
	$c->render(json => { ok => 1, code => $code, html => $sec->{'html'} });
};

post '/manager/security/rotate_key' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0 });
		return;
	}
	my $result = &subs::rotate_house_key();
	if ($result->{'ok'}) {
		# the sweep re-sealed the database; the sealed files on disk go to the
		# queue, which walks them resumably and re-seals each one in place, and
		# the push hands the new key to every linked machine the same sweep
		eval { &subs::minion_grabber()->enqueue('folders_reseal' => [ { before => $result->{'at'}, budget => 600 } ] => { attempts => 2 }) };
		eval { &subs::minion_grabber()->enqueue('key_push' => [ {} ] => { attempts => 3 }) };
	}
	my $sec = &security_initializer($c);
	$c->render(json => {
		ok => $result->{'ok'} ? 1 : 0,
		summary => { settings => $result->{'settings'}, security => $result->{'security'}, links => $result->{'links'} },
		html => $sec->{'html'}
	});
};

post '/manager/security/legacy_reseal' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0 });
		return;
	}
	my $local = &subs::legacy_reseal();
	my $mesh = &subs::legacy_reseal_mesh();
	$c->render(json => { ok => $local->{'ok'} ? 1 : 0, local => $local, mesh => $mesh });
};

# A machine with no key asks the house for its shares. It posts an ephemeral
# X25519 public key; holders re-wrap to it and the server only relays. The key
# itself never reaches the server, and a request that nobody answers expires.
post '/manager/device/shares/request' => sub($c) {
	my $pubkey = $c->param('pubkey') // '';
	my $raw = eval { decode_base64($pubkey) };
	unless (defined $raw && length($raw) == 32) { $c->render(json => { ok => 0, error => 'bad key' }); return; }
	my $ip = $c->tx->remote_address;
	my $now = &subs::rightNow();
	&subs::house_key_share_cleanup();
	my $tries = &subs::db_query('select count(*) as n from cache where context = ? and uuid like ? and server_time > ?', 'share_ask', $ip . ':%', $now - 3600000)->hashes->[0]{'n'} || 0;
	my $waiting = &subs::db_query('select count(*) as n from house_key_share_requests where status = ? and server_time >= ?', 'open', $now - 1800000)->hashes->[0]{'n'} || 0;
	if ($tries >= 10 || $waiting >= 5) { $c->render(json => { ok => 0, error => 'too many' }); return; }
	&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'share_ask', app => '__president', server_time => $now, timestamp => $now });
	my $made = &subs::house_key_share_request_create($pubkey, $c->param('name'));
	unless ($made) { $c->render(json => { ok => 0, error => 'not made' }); return; }
	$c->render(json => {
		ok => 1,
		uuid => $made->{'uuid'},
		code => $made->{'code'},
		need => $made->{'need'},
		have => $made->{'have'},
		enough => ($made->{'have'} >= $made->{'need'} ? 1 : 0),
	});
};

# The asking machine polls this. The release blobs are sealed to the key it
# minted, so the server's answer is opaque to everyone else.
get '/manager/device/shares/status' => sub($c) {
	my $uuid = $c->param('uuid') // '';
	my $req = &subs::house_key_share_request_open($uuid);
	unless ($req) { $c->render(json => { ok => 0, status => 'expired' }); return; }
	my $releases = &subs::house_key_share_releases($uuid);
	$c->render(json => {
		ok => 1,
		status => 'open',
		need => $req->{'need'},
		available => $req->{'available'},
		set_id => $req->{'set_id'},
		have => scalar(@{$releases}),
		releases => [ map { { share_index => $_->{'share_index'}, wrapped => $_->{'wrapped'} } } @{$releases} ],
	});
};

# The gate's recovery door: the paper code unwraps the sealed suds and the
# browser is paired on the spot. Throttled per address, and a stale code (the
# house key changed since it was made) is refused by the canary check.
post '/manager/device/recover' => sub($c) {
	my $code = &subs::recovery_code_clean($c->param('code'));
	my $raw_code = $c->param('code') // '';
	# three shares pasted on separate lines (or separated by commas) are a third
	# way in; base64 is case-sensitive, so these are read from the raw field
	my @share_codes = grep { /\S/ } split /[\s,]+/, $raw_code;
	unless (length $code >= 20 || @share_codes) { $c->render(json => { ok => 0, error => 'not accepted' }); return; }
	my $ip = $c->tx->remote_address;
	my $now = &subs::rightNow();
	my $tries = &subs::db_query('select count(*) as n from cache where context = ? and uuid like ? and server_time > ?', 'recovery_attempt', $ip . ':%', $now - 3600000)->hash->{'n'} || 0;
	if ($tries >= 5) { $c->render(json => { ok => 0, error => 'too many' }); return; }
	&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'recovery_attempt', app => '__president', server_time => $now, timestamp => $now });
	# The paper code or three shares. The password is a login, not a recovery
	# share: it no longer unwraps the house key, so a lost key needs the code or
	# a threshold, never one remembered secret.
	my $suds;
	if (length $code >= 20) {
		my $row = &subs::db_query('select value from settings where app = ? and setting = ? order by server_time desc limit 1', '__president', 'recovery')->hashes->[0];
		$suds = eval { &subs::note_decrypter($code, $row->{'value'}) } if $row && $row->{'value'};
	}
	if (!(defined $suds && length $suds) && @share_codes) {
		$suds = &subs::shamir_open_shares(\@share_codes);
	}
	$suds =~ s/\s+$// if $suds;
	unless ($suds && &subs::suds_current($suds)) { $c->render(json => { ok => 0, error => 'not accepted' }); return; }
	&subs::vault_seed($suds, 1);
	# this worker must resolve the recovered key at once (the session's suds_id
	# is minted from it), and the duty stamp nudges the other workers to re-read
	# the vault instead of their memoized copy
	$gb::suds = $suds;
	# the paper code is also the way past a padlock: the same recovery that
	# unwraps the house key opens the lock, so a forgotten phone is not a lockout
	if (&subs::db_select('security', undef, { level => 'padlock' })->hashes->[0]) {
		&padlock_mark_unlocked($c, 'locker');
	}
	&subs::setting_setter({ app => '__president', setting => 'remote_duty', value => &subs::rightNow() });
	my $name = substr($c->param('name') || 'Recovered Device', 0, 60);
	my $person_uuid = &subs::people_owner_ensure();
	my $uuid = &device_store_pubkey($c->param('pubkey'), $name, $c->req->headers->user_agent, $person_uuid);
	unless ($uuid) { $c->render(json => { ok => 0, error => 'no key' }); return; }
	&device_session_mint($c, $uuid);
	$c->render(json => { ok => 1, device_uuid => $uuid, name => $name });
};

# A new device's ask: it posts its public key before it has any session, and a
# citizen approves it from a device that is already signed in. The short code
# is the same on both screens, so the wrong request is not approved by habit.
post '/manager/device/request' => sub($c) {
	my $pem = &device_pubkey_clean($c->param('pubkey'));
	unless ($pem) { $c->render(json => { ok => 0, error => 'no key' }); return; }
	my ($db) = &subs::database_grabber();
	unless ($db) { $c->render(json => { ok => 0, error => 'no database' }); return; }
	my $now = &subs::rightNow();
	&subs::db_query('delete from device_requests where status = ? and server_time < ?', 'pending', $now - 3600000);
	my $open = &subs::db_select('device_requests', undef, { pubkey => $pem, status => 'pending' })->hashes->[0];
	if ($open) { $c->render(json => { ok => 1, uuid => $open->{'uuid'}, code => $open->{'code'} }); return; }
	# the door's throttle: ten asks per address per hour, five waiting at once
	my $ip = $c->tx->remote_address;
	my $tries = &subs::db_query('select count(*) as n from cache where context = ? and uuid like ? and server_time > ?', 'device_request', $ip . ':%', $now - 3600000)->hash->{'n'} || 0;
	my $waiting = &subs::db_query('select count(*) as n from device_requests where status = ?', 'pending')->hash->{'n'} || 0;
	if ($tries >= 10 || $waiting >= 5) { $c->render(json => { ok => 0, error => 'too many' }); return; }
	&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'device_request', app => '__president', server_time => $now, timestamp => $now });
	my $uuid = &subs::random_string_creator(25);
	my $name = substr($c->param('name') || 'Device', 0, 60);
	my $agent = substr($c->req->headers->user_agent // '', 0, 400);
	my $code = &subs::device_request_code();
	&subs::db_insert('device_requests', {
		uuid => $uuid,
		name => $name,
		pubkey => $pem,
		agent => $agent,
		code => $code,
		status => 'pending',
		remote_address => $ip,
		timestamp => $now,
		server_time => $now
	});
	&device_request_notify($c, $name, $code);
	$c->render(json => { ok => 1, uuid => $uuid, code => $code });
};

# The asking device polls this. Approval made on another machine shows up here
# as fast as the roster merges - the key itself is the proof, so the status is
# right even before the request row's own copy of the decision arrives.
post '/manager/device/request_status' => sub($c) {
	my $uuid = $c->param('uuid') || '';
	my $row = ($uuid && &subs::db_select('device_requests', undef, { uuid => $uuid })->hashes->[0]);
	unless ($row) { $c->render(json => { ok => 0, status => 'unknown' }); return; }
	my $now = &subs::rightNow();
	if ($row->{'status'} eq 'pending') {
		if ($row->{'server_time'} < $now - 600000) {
			&subs::db_update('device_requests', { status => 'expired', server_time => $now }, { uuid => $uuid });
			$c->render(json => { ok => 1, status => 'expired' }); return;
		}
		my $paired = &subs::db_select('paired_devices', undef, { pubkey => $row->{'pubkey'}, status => 'active' })->hashes->[0];
		if ($paired) {
			&subs::db_update('device_requests', { status => 'approved', device_uuid => $paired->{'uuid'}, server_time => $now }, { uuid => $uuid });
			$c->render(json => { ok => 1, status => 'approved', device_uuid => $paired->{'uuid'} }); return;
		}
		$c->render(json => { ok => 1, status => 'pending' }); return;
	}
	$c->render(json => { ok => 1, status => $row->{'status'}, device_uuid => $row->{'device_uuid'} || '' });
};

sub device_request_notify($c, $name, $code) {
	my $who = $name || 'A device';
	my (undef,$database) = &subs::database_grabber();
	&notification_sender({ app => 'security', role => 'citizen', title => 'Device Request', message => $who . ' asks to pair (code ' . $code . ')', image => $gb::known_appts->{'security'}->{'icon'} }, $database);
}

post '/manager/security/device_request_decide' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0, html => '<p>citizen only</p>' });
		return;
	}
	my $uuid = $c->param('uuid') || '';
	my $decision = ($c->param('decision') || '') eq 'approve' ? 'approve' : 'deny';
	my $now = &subs::rightNow();
	my $row = ($uuid && &subs::db_select('device_requests', undef, { uuid => $uuid, status => 'pending' })->hashes->[0]);
	if ($row && $row->{'server_time'} > $now - 3600000) {
		# A synced copy may reach an approving machine before the new columns do:
		# the request's own app_pubkey is enough to recognise an app request even
		# when `kind` is still blank there. Without this, the old pairing branch
		# marked it approved and dropped the key.
		my $is_app = ((($row->{'kind'} || '') eq 'app') || (($row->{'app_pubkey'} || '') ne '')) ? 1 : 0;
		if ($is_app && $decision eq 'approve') {
			# An app key joins an existing paired device; it does not mint a new one.
			my $target = $row->{'device_uuid'} || '';
			my $device = ($target && &subs::db_select('paired_devices', undef, { uuid => $target, status => 'active' })->hashes->[0]);
			my $app_pubkey = $row->{'app_pubkey'} || '';
			my $app_kind = ($row->{'app_kind'} || 'ed25519') eq 'ec' ? 'ec' : 'ed25519';
			if ($device && $app_pubkey) {
				&subs::db_update('paired_devices', { app_pubkey => $app_pubkey, app_kind => $app_kind, kind => 'app', server_time => $now }, { uuid => $target });
				&subs::db_update('device_requests', { status => 'approved', device_uuid => $target, server_time => $now }, { uuid => $uuid });
				$log->info('app gate: app key approved for ' . ($device->{'name'} || $target) . ' from ' . ($c->tx->remote_address || '?'));
			}
			else {
				$log->info('app gate: app approval incomplete for ' . ($target || '?')
					. ' (device ' . ($device ? 1 : 0) . ', key ' . length($app_pubkey) . ')');
			}
		}
		elsif ($decision eq 'approve') {
			my $person_uuid = $c->session('person_uuid') || &subs::people_owner_ensure();
			my $device_uuid = &device_store_pubkey($row->{'pubkey'}, $row->{'name'}, $row->{'agent'}, $person_uuid);
			if ($device_uuid) {
				&subs::db_update('device_requests', { status => 'approved', device_uuid => $device_uuid, server_time => $now }, { uuid => $uuid });
			}
		}
		else {
			&subs::db_update('device_requests', { status => 'denied', server_time => $now }, { uuid => $uuid });
		}	}
	my $sec = &security_initializer($c);
	$c->render(json => { ok => 1, html => $sec->{'html'} });
};

post '/manager/security/neighbour_link_delete' => sub($c) {
	my $uuid = $c->param('uuid');
	if ($uuid) {
		&subs::db_delete('neighbour_link', { uuid => $uuid });
	}
	$c->render(text => &security_initializer($c));
};

post '/manager/security/padlock' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $combo = $c->param('combo');
	my $pulled = $c->param('pulled');
	my ($j_pulled,$salt,$salty,$saved_pulled);
	my ($db) = &subs::database_grabber();
	my $padlocker = &subs::db_select('security', undef, { level => 'padlock' })->hashes || [];
	my $padlock = $padlocker->[0];
	$pulled = eval { return decode_json $pulled } || [];
	if (scalar @{$padlocker} > 0 && scalar @{$pulled} == 0) {

		$c->render(json => { status => 'failed cuz 0'});
	}
	if (scalar @{$pulled} > 0 && scalar @{$padlocker} > 0) {
		$j_pulled = eval { return encode_json $pulled };
		$salty = join '', @{$pulled};
		$saved_pulled = &subs::note_decrypter($salty . &subs::session_suds($c) . $salty, $padlock->{'credential'});
	}
	if ((scalar @{$padlocker} == 0) || (secure_compare( $j_pulled, $saved_pulled )) ) {
		$combo = eval { return decode_json $combo };
		$salt = join '', @{$combo};
		my $combination = eval { return encode_json $combo };
		$combo = &subs::note_encrypter($salt . &subs::session_suds($c) . $salt,$combination);
		my $activity_timeout = &subs::setting_grabber({ app => 'me', setting => 'activity_timeout' }) || '2h';
		$activity_timeout = &subs::time_abbrev_translator($activity_timeout);
		$c->session('padlock', $activity_timeout);
		&subs::db_delete('security', { level => 'padlock' });
		&subs::db_insert('security', { level => 'padlock', credential => $combo, timestamp => $timestamp, server_time => &subs::rightNow(), uuid => &subs::random_string_creator(30) });
		$c->render(json => { status => 'saved' });
	}
	else {
		$c->render(json => { status => 'failed cuz different'});
	}
};

post '/manager/security/padlock/delete' => sub ($c) {
	&subs::db_delete('security', { level => 'padlock' });
	&subs::db_delete('security', { level => 'padlock_device' });
	&subs::db_query('delete from settings where app = ? and setting = ?', '__president', 'padlock_device_time');
	&subs::db_delete('settings', { app => '__president', setting => 'pl_time' });
	&subs::db_delete('settings', { app => '__president', setting => 'padlock_pulls' });
	&Websocket::send('server', { padlock_open => 1, mode => 'locker', target => '', timestamp => &subs::rightNow() });
	$c->render(text => 'ok');
};

# The gate is a row, not a combination any more: the dial and the camera key
# are gone, so there is nothing to set. Enabling it makes the server deny
# everything behind it; the phone's signed challenge (and the paper code) are
# the ways in.
post '/manager/security/gate/enable' => sub ($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		return $c->render(json => { ok => 0, error => 'citizen only' });
	}
	my $padlock = &subs::db_select('security', undef, { level => 'padlock' })->hashes->[0];
	unless ($padlock) {
		my $now = &subs::rightNow();
		&subs::db_insert('security', { level => 'padlock', credential => '', timestamp => $now, server_time => $now, uuid => &subs::random_string_creator(30) });
	}
	my $contexts = eval { decode_json &subs::setting_grabber({ app => '__president', setting => 'padlock_contexts' }) } || [];
	unless (scalar @{$contexts}) {
		&subs::setting_setter({ app => '__president', setting => 'padlock_contexts', value => '["general"]' });
	}
	# A fresh gate gets a full inactivity window, so the timer has a baseline
	# and turning it on does not read as an expired lock on the next request.
	my $pl = &subs::db_query('select server_time from settings where app = ? and setting = ? limit 1', '__president', 'pl_time')->hashes->[0];
	unless ($pl) {
		my $window = &subs::setting_grabber({ app => 'me', setting => 'activity_timeout' }) || '-2h';
		$window = abs &subs::time_abbrev_translator($window);
		&subs::setting_setter({ app => '__president', setting => 'pl_time', value => &subs::rightNow() + $window });
	}
	# an explicit Turn the gate on/off is the house's choice from now on; the
	# boot-time default only fills a house that has never made one
	&subs::setting_setter({ app => '__president', setting => 'padlock_gate_initialized', value => 'yes' });
	my $sec = &security_initializer($c);
	&Websocket::send('server', { padlock_gate => 1, timestamp => &subs::rightNow() });
	$c->render(json => { ok => 1, html => $sec->{'html'}, has_padlock => 1 });
};

post '/manager/security/gate/disable' => sub ($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		return $c->render(json => { ok => 0, error => 'citizen only' });
	}
	&subs::db_delete('security', { level => 'padlock' });
	&subs::db_delete('security', { level => 'padlock_device' });
	&subs::db_query('delete from settings where app = ? and setting = ?', '__president', 'padlock_device_time');
	&subs::db_delete('settings', { app => '__president', setting => 'pl_time' });
	&subs::db_delete('settings', { app => '__president', setting => 'padlock_pulls' });
	&subs::setting_setter({ app => '__president', setting => 'padlock_gate_initialized', value => 'yes' });
	&Websocket::send('server', { padlock_open => 1, mode => 'locker', target => '', timestamp => &subs::rightNow() });
	&Websocket::send('server', { padlock_gate => 0, timestamp => &subs::rightNow() });
	my $sec = &security_initializer($c);
	$c->render(json => { ok => 1, html => $sec->{'html'}, has_padlock => 0 });
};

post '/manager/security/padlock_pull' => sub($c) {
	$c->render(json => { status => 'fail', error => 'the dial is disabled' });
};

# The dial and the camera key were removed in v0.1.804: the signed challenge
# is the only remote unlock, and the paper code is the emergency. Nothing here
# starts a camera or accepts a combination any more.

# --- the lock gate ---------------------------------------------------------
# The padlock used to be a client overlay: every route still answered behind
# it. The gate is the server-side half. 'shadow' writes what it would refuse
# and still answers (so the list can be checked on a live machine); 'enforce'
# refuses everything except the ways in.
sub padlock_gate_mode {
	my $mode = &subs::setting_grabber({ app => '__president', setting => 'padlock_gate' });
	return (defined $mode && $mode eq 'shadow') ? 'shadow' : 'enforce';
}

# --- the app gate ----------------------------------------------------------
# The installed apps are the only browser engines allowed to see /manager. A
# browser may read the public homepage and store, and the embedded devices keep
# their own rotated-token rail. 'shadow' logs what it would deny; 'enforce'
# answers with the open-in-the-app page.
sub app_access_mode {
	# A machine that cannot enroll an app key may opt itself out: a row named by
	# this machine's signatorial wins over the house-wide 'all' row, so one device
	# being unable to set up its unlock does not open (or close) the rest of the
	# house. Peers read their own signatorial, so this row never becomes their
	# answer.
	my $sig = &subs::signatorial_designer();
	if ($sig) {
		my $own = &subs::setting_grabber({ app => '__president', setting => 'app_access', device => $sig });
		return $own if defined $own && $own =~ /^(?:off|enforce|shadow)$/;
	}
	# The house-wide policy, shared as device 'all' so every machine and every
	# device class that has no row of its own reads one answer.
	my $mode = &subs::setting_grabber({ app => '__president', setting => 'app_access', device => 'all' });
	return 'off' if defined $mode && $mode eq 'off';
	return $mode eq 'enforce' ? 'enforce' : 'shadow';
}

sub app_public_path {
	my ($path) = @_;
	return 0 unless defined $path;
	return 1 if $path eq '/' || $path eq '/homepage' || $path eq '/index.html';
	return 1 if $path =~ m{^/store(?:/|$)};
	return 1 if $path =~ m{^/(?:css|js|images|icons|sounds|fonts|public|i18n)/};
	return 1 if $path =~ m{^/(?:favicon\.ico|manifest\.json|service_worker\.js|robots\.txt|privacy|mugshot|payment|play|file_open|denial)$};
	return 1 if $path =~ m{^/(?:manager/)?box_office(?:/|$)};
	return 1 if $path =~ m{^/public_view(?:/|$)};
	return 1 if $path eq '/sesh_check' || $path eq '/gate';
	return 1 if $path eq '/manager/health';
	return 1 if $path =~ m{^/manager/webauthn/login/(?:begin|finish)$};
	return 1 if $path eq '/manager/ws' || $path eq '/manager/tunnel/ws';
	# The padlock is its own small protocol: a locked screen must still be able
	# to ask another device for a print even when its app window has lapsed, and
	# every one of these routes checks its own device key or pairing.
	return 1 if $path =~ m{^/manager/security/(?:padlock_|fingerprint_unlock|biometric_)};
	return 1 if $path =~ m{^/manager/device(?:/|$)};
	return 1 if $path =~ m{^/manager/app_release(?:/|$)};
	return 1 if $path =~ m{^/manager/app_download(?:/|$)};
	# A crest lookup is house to house: the caller presents its own crest and the
	# reply is signed by this house's key, so no session or app key is involved.
	return 1 if $path =~ m{^/crest(?:/|$)};
	# A member machine hands over its crest cosignature on the same peer rail:
	# the route requires and verifies the machine's signature itself.
	return 1 if $path eq '/manager/crest/cosign';
	# The embedded devices authenticate themselves with the rotated Now Me
	# pair; they are not browsers and must keep their rail.
	return 1 if $path =~ m{^/(?:watch|teletype|embedded)(?:/|$)};
	return 0;
}

sub app_session_ok {
	my ($c) = @_;
	# No loopback bypass here: a tunnel proxy can make a remote browser look
	# local. The recovery code or the app key is the way back in.
	if (($c->session('peer') || '') eq '1') {
		my $ssig = $c->session('peer_signatorial') || '';
		# A first-contact or pre-upgrade session carries no proved name; keep its
		# existing access until it logs in again.
		return 1 if $ssig eq '';
		my $rm = &subs::db_select('remote_machines', undef, { signatorial => $ssig })->hash;
		# the row is gone: the session is revoked with it
		return 0 unless $rm;
		my $key = $rm->{'uuid'} || $rm->{'signatorial'};
		$c->stash('peer_verified_key' => $key) if $key;
		return &subs::peer_allows($c, $rm, 'visitor') ? 1 : 0;
	}
	my $until = $c->session('app_until') || 0;
	return $until > &subs::rightNow() ? 1 : 0;
}

# The other way in is the signed peer rail. A linked machine's request is not
# a browser and has no app key; its proof is the pinned key on its roster row.
# Some peer routes verify that themselves, but the app gate runs first, so a
# peer whose session cookie was lost (or a tunnelled peer whose calls cross a
# restart) was answered with the app-required page before its signature was
# ever read. Require a real signature and an already-pinned key - not the
# trust-on-first-contact path - so a browser quoting a signatorial cannot use
# this door. peer_verify memoises its answer on the stash, so a route that
# checks again after this does not fail on the already-spent nonce.
sub app_peer_ok {
	my ($c) = @_;
	my $sig = $c->req->headers->header('X-Peer-Signature');
	my $offered = $c->req->headers->header('X-Peer-Key');
	return 0 unless $sig && $offered;
	# The offered key names the caller; find the roster row that already pins it
	# and verify against that. Looking the row up by the key (not by a
	# signatorial the caller could quote) means a browser cannot borrow a
	# linked machine's name, and a route's own request need not carry a name.
	my $pub = eval { b64_decode($offered) } || '';
	return 0 unless $pub && index($pub, '-----BEGIN PUBLIC KEY-----') == 0;
	my $rm = &subs::db_select('remote_machines', undef, { pubkey => $pub })->hashes->[0];
	return 0 unless $rm;
	return &subs::peer_verify($c, $rm) ? 1 : 0;
}

sub app_key_for {
	my ($device) = @_;
	return () unless $device;
	if ($device->{'app_pubkey'}) {
		my $kind = $device->{'app_kind'} || '';
		$kind = 'ec' if !$kind && $device->{'app_pubkey'} !~ /BEGIN PUBLIC KEY/;
		return ($device->{'app_pubkey'}, ($kind eq 'ec' ? 'ec' : 'ed25519'));
	}
	# A phone's already-enrolled Keystore fingerprint is its app key. The
	# private half cannot leave Android Keystore, so it is genuinely app-only.
	return ($device->{'bio_pubkey'}, 'ec') if $device->{'bio_pubkey'};
	return ();
}

sub app_signature_ok {
	my ($pubkey, $kind, $msg, $sig) = @_;
	return 0 unless $pubkey && defined $msg && $sig;
	return $kind eq 'ec'
		? &subs::ecdsa_verify($pubkey, $msg, $sig)
		: &subs::signature_verify($pubkey, $msg, $sig);
}

our $app_schema_done;
sub app_schema_ensure {
	return if $app_schema_done;
	$app_schema_done = 1;
	foreach my $spec (
		[ 'paired_devices', 'app_pubkey', 'LONGTEXT' ],
		[ 'paired_devices', 'app_kind', 'VARCHAR(16)' ],
		[ 'paired_devices', 'kind', 'VARCHAR(25)' ],
		[ 'device_requests', 'kind', 'VARCHAR(16)' ],
		[ 'device_requests', 'app_pubkey', 'LONGTEXT' ],
		[ 'device_requests', 'app_kind', 'VARCHAR(16)' ],
	) {
		my ($table, $column, $type) = @{$spec};
		eval { &subs::db_query("ALTER TABLE $table ADD COLUMN $column $type") };
	}
	# Backfill the rows that predate the column. Idempotent: only blanks move.
	eval { &subs::db_query("update paired_devices set kind = case
		when bio_pubkey is not null and bio_pubkey != '' then 'phone'
		when app_pubkey is not null and app_pubkey != '' then 'app'
		when agent like '%AppleWebKit/605%' then 'webview'
		else 'browser' end
		where kind is null or kind = ''") };
}

# A lock is local to the machine that saw it, but an explicit unlock request
# must reach every screen in the house. This hands the same padlock_key_show to
# the peers over the signed rail; each one broadcasts to its own websockets and
# carries the message on, and relay_id stops a loop. `prompt` marks a request
# the person made on the locked screen (not a lock being announced), so only
# that kind may put a confirmation in front of another device.
sub padlock_key_show_relay {
	my ($c, $mode, $target, $show, $prompt, $request_id, $device_name, $source_device, $source_hostname) = @_;
	return unless $c;
	my $signatorial = &subs::signatorial_designer();
	my $relay_id = &subs::random_string_creator(30);
	&subs::relay_fresh($relay_id);
	&subs::subprocessor(sub {
		Mojo::IOLoop->reset;
		&remote_relay_request($c, {
			override => 'manual',
			url => '/manager/security/padlock_key_show_peer',
			type => 'post',
			dissemination => 'yes',
			params => {
				signatorial => $signatorial,
				mode => $mode,
				target => $target,
				show => ($show ? 1 : 0),
				prompt => ($prompt ? 1 : 0),
				request_id => ($request_id || ''),
				device_name => ($device_name || ''),
				source_device => ($source_device || ''),
				source_hostname => ($source_hostname || ''),
				source => $signatorial,
				house => (($target || '') eq '' ? 1 : 0),
				dissemination => 'yes',
				source_signatorial => $signatorial,
				relay_from => $signatorial,
				relay_id => $relay_id,
			},
		});
	}, { name => 'padlock key show relay' });
}

# ---- explicit unlock requests --------------------------------------------
# A locked screen no longer pulls every phone and laptop onto the unlock page.
# The person presses Unlock on the locked screen; that writes a short-lived
# request (local cache, never synced) and broadcasts it. A device that is
# already open shows a fingerprint prompt in place, signs the target screen
# open, and goes back to what it was doing. The request is also readable from
# padlock_state, so a phone that was asleep when the button was pressed finds
# it on its next connection.
sub padlock_request_store {
	my ($target, $mode, $source, $id, $device_name, $source_device, $source_hostname, $tab) = @_;
	my $now = &subs::rightNow();
	$id ||= &subs::random_string_creator(24);
	$tab = '' unless defined $tab && $tab =~ /^[A-Za-z0-9_-]{1,64}$/;
	my $data = encode_json({
		id => $id,
		target => $target || '',
		mode => $mode || 'locker',
		source => $source || '',
		device_name => $device_name || '',
		source_device => $source_device || '',
		source_hostname => $source_hostname || '',
		tab => $tab,
		house => (($target || '') eq '' ? 1 : 0),
		time => $now,
	});
	&subs::db_query('delete from cache where context = ? and server_time < ?', 'padlock_request', $now - 600000);
	my $existing = &subs::db_select('cache', undef, { context => 'padlock_request', uuid => $id })->hashes->[0];
	if ($existing) {
		&subs::db_update('cache', { data => $data, server_time => $now, timestamp => $now }, { context => 'padlock_request', uuid => $id });
	}
	else {
		&subs::db_insert('cache', {
			uuid => $id,
			context => 'padlock_request',
			app => '__president',
			data => $data,
			timestamp => $now,
			server_time => $now,
		});
	}
	return $id;
}

# The request a media mint may read: the newest one naming this screen. Its
# `source` says which machine holds the screen, and its `tab` says which window
# asked, so the token goes to that window alone.
sub padlock_request_for_target {
	my ($target) = @_;
	return {} unless defined $target && $target =~ /^[A-Za-z0-9]{8,64}$/;
	my $now = &subs::rightNow();
	my $rows = &subs::db_query('select uuid, data, server_time from cache where context = ? and server_time > ? order by server_time desc', 'padlock_request', $now - 300000)->hashes || [];
	foreach my $row ( @{$rows} ) {
		my $d = eval { decode_json $row->{'data'} } || {};
		next unless (($d->{'target'} || '') eq $target);
		$d->{'id'} ||= $row->{'uuid'};
		return $d;
	}
	return {};
}

sub padlock_request_get {
	my ($id) = @_;
	my $now = &subs::rightNow();
	my $row;
	if (defined $id && $id =~ /^[A-Za-z0-9]{8,64}$/) {
		$row = &subs::db_query('select uuid, data, server_time from cache where context = ? and uuid = ? and server_time > ? limit 1', 'padlock_request', $id, $now - 300000)->hashes->[0];
	}
	else {
		$row = &subs::db_query('select uuid, data, server_time from cache where context = ? and server_time > ? order by server_time desc limit 1', 'padlock_request', $now - 300000)->hashes->[0];
	}
	return {} unless $row;
	my $d = eval { decode_json $row->{'data'} } || {};
	$d->{'id'} ||= $row->{'uuid'};
	$d->{'time'} ||= $row->{'server_time'};
	return $d;
}

# One screen opening does not answer a request for another screen, and a
# whole-house open answers every request.
sub padlock_request_clear {
	my ($target) = @_;
	return unless defined $target;
	if ($target eq '') {
		my $all = &subs::db_query('select uuid from cache where context = ?', 'padlock_request')->hashes || [];
		&padlock_request_clear_id($_->{'uuid'}) for @{$all};
		return;
	}
	my $rows = &subs::db_query('select uuid, data from cache where context = ?', 'padlock_request')->hashes || [];
	foreach my $r ( @{$rows} ) {
		my $d = eval { decode_json $r->{'data'} } || {};
		&padlock_request_clear_id($r->{'uuid'}) if (($d->{'target'} || '') eq $target);
	}
}

# Clearing a request is also the signal that stops the prompt everywhere. The
# request's own id travels with it, so a screen can tell this one from a newer
# request that happens to name the same device.
sub padlock_request_clear_id {
	my ($id) = @_;
	return unless defined $id && $id =~ /^[A-Za-z0-9]{8,64}$/;
	&subs::db_query('delete from cache where context = ? and uuid = ?', 'padlock_request', $id);
	&Websocket::send('server', { padlock_key_clear => 1, request_id => $id, timestamp => &subs::rightNow() });
}

# --- Go approvals ---------------------------------------------------------
# A Go pressed in the installed app is already authenticated by the app key,
# but the person may ask for a second factor before the peer ticket is minted:
# this machine's reader, the phone's own Keystore print, or another paired
# device's print. The request itself stays local to this machine; only asking a
# device puts it on the padlock prompt rail, so a laptop fingerprint does not
# buzz every phone in the house.
sub go_approvers {
	my ($c, $source_device) = @_;
	my $local = (&fingerprint_available() && &padlock_request_is_local($c)) ? 1 : 0;
	my $self_bio = 0;
	if ($source_device) {
		my $d = &subs::db_select('paired_devices', undef, { uuid => $source_device, status => 'active' })->hashes->[0];
		$self_bio = ($d && ($d->{'bio_pubkey'} || '') ne '') ? 1 : 0;
	}
	my @devices = grep { ($_->{'bio_pubkey'} || '') ne '' && ($_->{'uuid'} || '') ne ($source_device || '') }
		@{ &subs::db_select('paired_devices', undef, { status => 'active' })->hashes || [] };
	return ($local, $self_bio, \@devices);
}

sub go_hostname {
	my $hostname = &subs::machine_name() || '';
	my $host = `hostname`;
	chomp $host;
	$hostname .= ' (' . $host . ')' if $host && $host ne $hostname;
	$hostname =~ s/[\r\n\t]//g;
	return substr($hostname, 0, 120);
}

# One pending Go per session. The row carries the peer the ticket is for, so
# go_status can mint it after the approval; the session names the request so a
# second page cannot redeem someone else's approval.
sub go_request_create {
	my ($c, $rm, $source_device, $manager, $name) = @_;
	my $now = &subs::rightNow();
	my $id = &subs::random_string_creator(24);
	my $peer_name = $rm->{'hostname'} || $rm->{'fqdn'} || $rm->{'domain'} || $rm->{'ip'} || 'remote';
	my $data = encode_json({
		id => $id,
		peer_uuid => ($rm->{'uuid'} || ''),
		peer_name => $peer_name,
		source => &subs::signatorial_designer(),
		source_device => ($source_device || ''),
		source_hostname => &go_hostname(),
		time => $now,
	});
	&subs::db_query('delete from cache where context = ? and server_time < ?', 'go_request', $now - 300000);
	my $old = $c->session('go_request') || '';
	if ($old =~ /^[A-Za-z0-9]{8,64}$/) {
		&subs::db_query('delete from cache where context = ? and uuid = ?', 'go_request', 'gor' . $old);
		&subs::db_query('delete from cache where context = ? and uuid = ?', 'go_approval', 'goa' . $old);
		&padlock_request_clear($old);
		&go_dismiss($old);
	}
	# cache.uuid is unique across contexts; the padlock prompt and the request
	# both carry the public id, so only the stored rows take a prefix.
	&subs::db_insert('cache', {
		uuid => ('gor' . $id), context => 'go_request', app => '__president',
		data => $data, timestamp => $now, server_time => $now,
	});
	$c->session('go_request' => $id);
	$c->session('go_peer_uuid' => ($rm->{'uuid'} || ''));
	$c->session('go_manager' => ($manager || ''));
	$c->session('go_name' => ($name || ''));
	return $id;
}

sub go_request_get {
	my ($id) = @_;
	return {} unless defined $id && $id =~ /^[A-Za-z0-9]{8,64}$/;
	my $row = &subs::db_query('select uuid, data, server_time from cache where context = ? and uuid = ? and server_time > ? limit 1', 'go_request', 'gor' . $id, &subs::rightNow() - 300000)->hashes->[0];
	return {} unless $row;
	my $d = eval { decode_json $row->{'data'} } || {};
	$d->{'id'} ||= $id;
	$d->{'time'} ||= $row->{'server_time'};
	return $d;
}

sub go_request_clear {
	my ($id) = @_;
	return unless defined $id && $id =~ /^[A-Za-z0-9]{8,64}$/;
	&subs::db_query('delete from cache where context = ? and uuid = ?', 'go_request', 'gor' . $id);
}

sub go_approval_record {
	my ($id, $by, $device_uuid, $name) = @_;
	return unless defined $id && $id =~ /^[A-Za-z0-9]{8,64}$/;
	my $now = &subs::rightNow();
	my $row_uuid = 'goa' . $id;
	&subs::db_query('delete from cache where context = ? and server_time < ?', 'go_approval', $now - 120000);
	&subs::db_query('delete from cache where context = ? and uuid = ?', 'go_approval', $row_uuid);
	&subs::db_insert('cache', {
		uuid => $row_uuid, context => 'go_approval', app => '__president',
		data => encode_json({ approved => 1, by => ($by || ''), device => ($device_uuid || ''), name => ($name || ''), time => $now }),
		timestamp => $now, server_time => $now,
	});
}

sub go_approval_get {
	my ($id) = @_;
	return {} unless defined $id && $id =~ /^[A-Za-z0-9]{8,64}$/;
	my $row = &subs::db_query('select data, server_time from cache where context = ? and uuid = ? and server_time > ? limit 1', 'go_approval', 'goa' . $id, &subs::rightNow() - 120000)->hashes->[0];
	return {} unless $row;
	my $d = eval { decode_json $row->{'data'} } || {};
	$d->{'time'} ||= $row->{'server_time'};
	return $d;
}

sub go_approval_clear {
	my ($id) = @_;
	return unless defined $id && $id =~ /^[A-Za-z0-9]{8,64}$/;
	&subs::db_query('delete from cache where context = ? and uuid = ?', 'go_approval', 'goa' . $id);
}

# Dismiss any device prompt still showing this request (the target is the
# request id, not a screen, so the padlock handler only dismisses and stops).
sub go_dismiss {
	my ($id) = @_;
	&Websocket::send('server', { padlock_open => 1, mode => 'go', target => ($id || ''), timestamp => &subs::rightNow() });
}

# A request that came from this machine itself. The phone/tablet is remote, so
# its signature opens the lock; the locked screen's own key may not.
sub padlock_request_is_local {
	my ($c) = @_;
	my $local = $c->tx->local_address || '';
	my $remote = $c->tx->remote_address || '';
	return 1 if $local eq $remote;
	return 1 if $remote =~ /^(?:127\.|::1$|::ffff:127\.)/;
	# a browser reaching this machine by its LAN name (or through a hairpin)
	# still counts as this machine: the phone is never one of our own addresses
	our $padlock_mine_at = 0;
	our @padlock_mine;
	if (!$padlock_mine_at || time - $padlock_mine_at > 60) {
		@padlock_mine = split /\s+/, `hostname -I 2>/dev/null`;
		# `hostname -I` is not on every distro (this laptop's hostname rejects
		# it), and an empty list made its own browser look remote: the local
		# fingerprint was refused and the host would not refuse its own
		# signature. Read the addresses from ip(8) instead, then hostname -i.
		unless (@padlock_mine) {
			my $ipout = `ip -4 -o addr show 2>/dev/null`;
			while ($ipout =~ /inet\s+([0-9]+\.[0-9]+\.[0-9]+\.[0-9]+)/g) { push @padlock_mine, $1; }
		}
		unless (@padlock_mine) {
			@padlock_mine = split /\s+/, `hostname -i 2>/dev/null`;
		}
		$padlock_mine_at = time;
	}
	return 1 if grep { $_ eq $remote } @padlock_mine;
	return 0;
}

# The server machine's own fingerprint reader, if it has an enrolled finger.
# Checked at most once a minute: fprintd-list talks to D-Bus.
our ($fingerprint_checked_at, $fingerprint_ok);
# A phone that enrolled its Keystore fingerprint: the lock screen should offer
# that fingerprint even when the page itself cannot see the native bridge (the
# button then explains that the app is needed rather than hiding silently).
sub biometric_enrolled_for {
	my ($device_uuid) = @_;
	return 0 unless $device_uuid;
	my $d = &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0];
	return ($d && $d->{'bio_pubkey'}) ? 1 : 0;
}

sub fingerprint_available {
	return 0 unless -x '/usr/bin/fprintd-verify';
	my $now = time;
	if (!$fingerprint_checked_at || $now - $fingerprint_checked_at > 60) {
		my $user = $ENV{USER} || getpwuid($<) || 'jawn';
		$user =~ s/[^\w.-]//g;
		my $out = `fprintd-list $user 2>/dev/null`;
		$fingerprint_ok = ($out =~ /Fingerprints for user/i && $out !~ /no finger/i) ? 1 : 0;
		$fingerprint_checked_at = $now;
	}
	return $fingerprint_ok || 0;
}

sub padlock_gate_allows {
	my ($path) = @_;
	return 1 if $path =~ m{^/(?:css|js|images|icons|sounds|fonts|public)/};
	return 1 if $path =~ m{^/(?:favicon\.ico|manifest\.json|service_worker\.js|robots\.txt)$};
	return 1 if $path eq '/manager/ws' || $path eq '/manager/health';
	return 1 if $path =~ m{^/(?:manager/)?box_office(?:/|$)};
	# the device rail authenticates itself and must reach the gate's recovery
	return 1 if $path =~ m{^/manager/device(?:/|$)};
	return 1 if $path eq '/manager/security/padlock_phone_show';
	return 1 if $path eq '/manager/security/padlock_challenge';
	return 1 if $path eq '/manager/security/padlock_unlock';
	return 1 if $path eq '/manager/security/padlock_open_peer';
	return 1 if $path eq '/manager/security/padlock_key_show_peer';
	return 1 if $path eq '/manager/security/padlock_state';
	return 1 if $path eq '/manager/security/media_lock';
	return 1 if $path eq '/manager/security/padlock_key';
	return 1 if $path eq '/manager/security/fingerprint_unlock_status';
	return 1 if $path eq '/manager/security/fingerprint_unlock';
	return 1 if $path eq '/manager/security/biometric_challenge';
	return 1 if $path eq '/manager/security/biometric_unlock';
	# the Android dashboard's Update app asks the local jawn to pull the newest
	# APK; it needs no house data and is session-gated inside the route, so a
	# locked screen can still take its own update
	return 1 if $path eq '/manager/app_release_sync';
	return 0;
}

sub padlock_device_locked {
	my ($device_uuid) = @_;
	return 0 unless $device_uuid;
	return &subs::db_select('security', undef, { level => 'padlock_device', uuid => $device_uuid })->hashes->[0] ? 1 : 0;
}

# The screen's own unlock stamp, used only when the whole house is locked: it
# is what lets one screen open without opening every screen.
sub padlock_device_until {
	my ($device_uuid) = @_;
	return 0 unless $device_uuid;
	my $row = &subs::db_query('select value from settings where app = ? and setting = ? and device = ? order by server_time desc limit 1', '__president', 'padlock_device_time', $device_uuid)->hashes->[0];
	return $row ? (&padlock_time_value(&subs::suds_grabber(), $row->{'value'}) || 0) : 0;
}

sub padlock_device_set_time {
	my ($device_uuid, $until) = @_;
	return unless $device_uuid && $until;
	&subs::db_query('delete from settings where app = ? and setting = ? and device = ?', '__president', 'padlock_device_time', $device_uuid);
	my $now = &subs::rightNow();
	&subs::db_insert('settings', { app => '__president', setting => 'padlock_device_time', device => $device_uuid, value => $until, server_time => $now, timestamp => $now, uuid => &subs::random_string_creator(25) });
}

sub padlock_device_clear_time {
	my ($device_uuid) = @_;
	return unless $device_uuid;
	&subs::db_query('delete from settings where app = ? and setting = ? and device = ?', '__president', 'padlock_device_time', $device_uuid);
}

# What a target's unlock request is asking about: a manual row always locks;
# a screen timer decides on its own; otherwise the house-wide timer does.
sub padlock_target_locked {
	my ($target, $c) = @_;
	return 0 unless $target;
	return 1 if &padlock_device_locked($target);
	my $until = &padlock_device_until($target);
	return (&subs::rightNow() > $until) ? 1 : 0 if $until;
	return &padlock_global_locked($c);
}

# The lock timers are milliseconds, not secrets: a plain number is readable by
# every worker, and an older sealed value still decrypts.
sub padlock_time_value {
	my ($suds, $raw) = @_;
	return 0 unless defined $raw && length $raw;
	return $raw if $raw =~ /^\d{10,}$/;
	return &subs::decrypter($suds || &subs::suds_grabber(), $raw) || 0;
}

sub padlock_global_locked {
	my ($c) = @_;
	my $padlock = &subs::db_select('security', undef, { level => 'padlock' })->hashes->[0];
	return 0 unless $padlock;
	my $contexts = eval { decode_json &subs::setting_grabber({ app => '__president', setting => 'padlock_contexts' }) } || [];
	return 0 unless grep { $_ eq 'general' } @{$contexts};
	my $row = &subs::db_query('select value from settings where app = ? and setting = ? order by server_time desc limit 1', '__president', 'pl_time')->hashes->[0];
	# No stamp means this machine has never been locked since the gate was set;
	# it is not an expired lock. A lock always writes the stamp, so absence is
	# open. (A peer that has not pulled the row yet must not claim the house is
	# locked and hide the phone's Unlock button.)
	return 0 unless $row;
	my $pl = &padlock_time_value(&subs::suds_grabber(), $row->{'value'}) || 0;
	return (&subs::rightNow() > $pl) ? 1 : 0;
}

sub padlock_locked_now {
	my ($c, $device) = @_;
	my $padlock = &subs::db_select('security', undef, { level => 'padlock' })->hashes->[0];
	return 0 unless $padlock;
	my $contexts = eval { decode_json &subs::setting_grabber({ app => '__president', setting => 'padlock_contexts' }) } || [];
	return 0 unless grep { $_ eq 'general' } @{$contexts};
	$device = $c->session('device_uuid') || '' unless defined $device;
	if ($device) {
		return 1 if &padlock_device_locked($device);
		my $until = &padlock_device_until($device);
		return (&subs::rightNow() > $until) ? 1 : 0 if $until;
	}
	return &padlock_global_locked($c);
}

sub padlock_gate_shadow {
	my ($c) = @_;
	my $path = $c->req->url->path->to_string;
	my $method = $c->req->method || 'GET';
	my $remote = $c->tx->remote_address || '?';
	$log->info("padlock shadow: would deny $method $path from $remote");
}

sub padlock_gate_answer {
	my ($c) = @_;
	my $path = $c->req->url->path->to_string;
	my $xhr = (($c->req->headers->header('X-Requested-With') // '') =~ /XMLHttpRequest/i);
	my $json = (($c->req->headers->accept // '') =~ m{application/json}i);
	if ($xhr || $json || $path =~ /\.json$/) {
		$c->res->code(423);
		$c->render(json => { error => 'locked', locked => 1, gate => &padlock_gate_mode() });
		return;
	}
	my $padlock = &subs::db_select('security', undef, { level => 'padlock' })->hashes->[0];
	$c->res->code(423);
	$c->res->headers->cache_control('no-store, max-age=0');
	$c->render(template => 'locked', layout => 'locked', has_padlock => ($padlock ? 1 : 0), target => ($c->session('device_uuid') || ''), locked_device => ($c->session('device_uuid') || ''), fingerprint => (&fingerprint_available() && &padlock_request_is_local($c)) ? 1 : 0, biometric => &biometric_enrolled_for($c->session('device_uuid') || ''), signatorial => &subs::signatorial_designer());
	return;
}

# One way to open: a paired device's signature, the paper recovery code, and
# the emergency paths all land here. A manual gate locks one device; a target
# names it, an empty target is the house-wide timeout lock. The global timer is
# moved past now either way, so the unlocked screen is not re-locked at once.
sub padlock_mark_unlocked {
	my ($c, $mode, $target, $tab_override) = @_;
	$mode ||= 'locker';
	$mode = 'locker' unless $mode =~ /^(?:locker|gallery|music|folders)$/;
	my $suds = &subs::suds_grabber() || &subs::session_suds($c) || $gb::suds;
	return 0 unless $suds;
	# Opening an app's padlock makes that app one of the lock's contexts. A
	# device whose contexts were only "general" otherwise has no such padlock:
	# it shows no Unlock button, and the token the unlock mints could never
	# validate there (media_unlock_open reads this same list).
	if ($mode ne 'locker') {
		my $contexts = eval { decode_json &subs::setting_grabber({ app => '__president', setting => 'padlock_contexts' }) } || [];
		unless (grep { $_ eq $mode } @{$contexts}) {
			push @{$contexts}, $mode;
			&subs::setting_setter({ app => '__president', setting => 'padlock_contexts', value => encode_json $contexts });
		}
	}
	my $activity_timeout = &subs::setting_grabber({ app => 'me', setting => 'activity_timeout' }) || '-2h';
	$activity_timeout = abs &subs::time_abbrev_translator($activity_timeout);
	my $new_timeout = &subs::rightNow() + $activity_timeout;
	$target = $c->session('device_uuid') || '' unless defined $target;
	if ($target) {
		&subs::db_delete('security', { level => 'padlock_device', uuid => $target });
		# a screen opened while the whole house is locked keeps a timer of its
		# own; the other screens stay locked on the house-wide stamp
		if (&padlock_global_locked($c)) {
			&padlock_device_set_time($target, $new_timeout);
		}
		else {
			&padlock_device_clear_time($target);
		}
	}
	else {
		# a whole-house open clears every screen's own lock too: a leftover
		# padlock_device row keeps that screen behind the gate even though the
		# house stamp says open (the "unlock, see the manager, lock again" loop)
		&subs::db_delete('security', { level => 'padlock_device' });
		&subs::db_query('delete from settings where app = ? and setting = ?', '__president', 'padlock_device_time');
		&subs::setting_setter({ app => '__president', setting => 'pl_time', value => $new_timeout });
	}
	$c->session('pl_time' => $new_timeout);
	&subs::setting_setter({ app => '__president', setting => 'padlock_pulls', value => &subs::note_encrypter($suds, 0) });
	if ($mode =~ /^(?:gallery|music|folders)$/) {
		my $device = $target || &media_unlock_device($c);
		my $request = &padlock_request_for_target($device);
		# the request row names the screen that pressed Unlock; the caller's own
		# tab is only a fallback (a phone confirming another screen carries its
		# own tab, which must not receive that screen's token)
		my $tab = $tab_override || $request->{'tab'} || $c->param('browser_tab_id') || '';
		$tab = '' unless $tab =~ /^[A-Za-z0-9_-]{1,64}$/;
		# Only the machine that holds the screen may mint its app grant. The
		# unlock is relayed to every peer so the screen's own jawn hears it, and
		# each peer used to mint a grant of its own - the app then opened on
		# machines nobody had asked about. A local print or button, or a request
		# this machine wrote for this screen, is the whole test; a peer's relay
		# is never local even when a tunnel makes its address look so.
		my $peer_route = (($c->req->url->path // '') eq '/manager/security/padlock_open_peer') ? 1 : 0;
		my $mine = &media_unlock_device($c);
		# A local reader or button opens the screen it is attached to. A local
		# phone confirming ANOTHER screen is not that screen's host: its own
		# grant would sit in the wrong database, so the relay below mints it.
		my $hosted = (!$peer_route && &padlock_request_is_local($c) && length $mine && $target eq $mine) ? 1 : 0;
		$hosted = 1 if (!$hosted && $request->{'id'}
			&& (($request->{'source'} || '') eq &subs::signatorial_designer()));
		if ($hosted && length $device) {
			my $token = &media_unlock_store($mode, $device, $tab);
			if (length $token) {
				my $js = ($mode eq 'gallery')
					? '$("#gallery").attr("unlock", "' . $token . '"); imageViewer({ "view":"home" });'
					: ($mode eq 'music')
					? '$("#music").attr("unlock", "' . $token . '"); $("#music").show(); $("#music_padlock").hide(); if (typeof searchMusic === "function") { searchMusic(); }'
					: '$("#folders").attr("unlock", "' . $token . '"); if (typeof foldersOpener === "function") { foldersOpener(); }';
				# one window's message, so another tab of the same screen stays
				# shut and no peer is told to drop a token it never held
				&Websocket::send('server', { console => $js, browser_tab_id => $tab }) if length $tab;
			}
		}
	}
	else {
		&Websocket::send('server', { padlock_open => 1, mode => $mode, target => $target, timestamp => &subs::rightNow() });
		# a targeted open is the phone's message to one screen; the console form
		# would run on every tab, so it is only used for a whole-house open
		&Websocket::send('server', { console => '$("#padlock_frame").html(""); $("#padlock_frame").hide();$("#everything").show();' }) unless $target;
	}
	# this request has been answered; a device that wakes later must not ask
	# the person to confirm an unlock that already happened
	&padlock_request_clear($target);
	return 1;
}

# The camera key is gone: the signed challenge is the only remote unlock.
# Kept so an old tab gets a clear answer instead of a 404.
post '/manager/security/padlock_watch' => sub ($c) {
	$c->render(json => { ok => 0, error => 'the camera key is disabled' });
};

# The person pressed Unlock on a locked screen. This writes a short-lived
# request and asks every paired phone/tablet to confirm it with a fingerprint.
# The route only sends the request; it cannot unlock anything by itself, and a
# device that is already open is never sent away from the page it is on.
post '/manager/security/padlock_phone_show' => sub ($c) {
	my $mode = $c->param('mode') || 'locker';
	$mode = 'locker' unless $mode =~ /^(?:locker|gallery|music|folders)$/;
	my $target = $c->param('target') || '';
	$target = '' unless $target =~ /^[A-Za-z0-9]{8,64}$/;
	my $device_name = '';
	if ($target) {
		my $device = &subs::db_select('paired_devices', undef, { uuid => $target, status => 'active' })->hashes->[0];
		$device_name = $device->{'name'} || '' if $device;
	}
	# the screen that pressed the button is not asked to confirm its own request
	my $source_device = $c->param('device_uuid') || $c->session('device_uuid') || '';
	$source_device = '' unless $source_device =~ /^[A-Za-z0-9]{8,64}$/;
	my $source = &subs::signatorial_designer();
	my $source_hostname = &subs::machine_name() || '';
	my $host = `hostname`;
	chomp $host;
	$source_hostname .= ' (' . $host . ')' if $host && $host ne $source_hostname;
	$source_hostname =~ s/[\r\n\t]//g;
	$source_hostname = substr($source_hostname, 0, 120);
	my $source_tab = $c->param('browser_tab_id') || '';
	$source_tab = '' unless $source_tab =~ /^[A-Za-z0-9_-]{1,64}$/;
	my $request_id = &padlock_request_store($target, $mode, $source, undef, $device_name, $source_device, $source_hostname, $source_tab);
	$log->info('padlock: prompt asked for ' . ($target || 'house') . ($device_name ? ' (' . $device_name . ')' : '') . ' by ' . ($source_device || '?') . ' on ' . $source_hostname . ' id=' . $request_id);
	&Websocket::send('server', { padlock_key_show => 1, prompt => 1, request_id => $request_id, device_name => $device_name, source_device => $source_device, source => $source, source_hostname => $source_hostname, house => (($target || '') eq '' ? 1 : 0), mode => $mode, target => $target, show => 1, timestamp => &subs::rightNow() });
	# another machine's screens are part of the house too
	unless (($c->param('remoted') || '') eq 'yes' || ($c->param('dissemination') || '') eq 'yes') {
		&padlock_key_show_relay($c, $mode, $target, 1, 1, $request_id, $device_name, $source_device, $source_hostname);
	}
	$c->render(json => { ok => 1, mode => $mode, target => $target, request_id => $request_id });
};

# "Not now", or a prompt that has gone stale: clear the request and tell every
# screen that showed it, so the print prompt does not linger elsewhere.
post '/manager/security/padlock_request_cancel' => sub ($c) {
	my $id = $c->param('request_id') || '';
	&padlock_request_clear_id($id);
	$c->render(json => { ok => 1, request_id => $id });
};

# The app window, the screen or the tree is going away: drop this device's
# media grant and tell the window that asked to show its locked view. The delete
# is keyed by device, so another screen - or a peer - keeps what it had.
post '/manager/security/media_lock' => sub ($c) {
	my $device = &media_unlock_device($c);
	my $app = $c->param('app') || '';
	$app = '' unless $app =~ /^(?:gallery|music|folders)$/;
	my $tab = $c->param('browser_tab_id') || '';
	$tab = '' unless $tab =~ /^[A-Za-z0-9_-]{1,64}$/;
	&media_unlock_clear($device, $app) if length $device;
	my @apps = $app ? ($app) : @media_unlock_apps;
	foreach my $a ( @apps ) {
		&Websocket::send('server', { console => 'jawnosMediaLockdown("' . $a . '")', browser_tab_id => $tab }) if length $tab;
	}
	$c->render(json => { ok => 1, app => $app, device => $device });
};

# A local fingerprint is an alternative to the phone for the screen it is on.
# The request must come from this machine and the session must be approved;
# fprintd prompts the reader, and only the screen named (or the current one) is
# opened. `mode` is the padlock being opened - an app's own padlock names that
# mode so the print also mints that app's unlock token.
#
# fprintd-verify waits for a finger (up to 20 seconds), so it runs in a child
# process: a blocking system() in the request froze the whole manager worker,
# which is what made the UI go quiet while the reader waited.
post '/manager/security/fingerprint_unlock' => sub ($c) {
	my $ip = $c->tx->remote_address || '?';
	unless (&padlock_request_is_local($c)) {
		$log->info('padlock: local fingerprint refused from ' . $ip . ' (not a local address)');
		return $c->render(json => { ok => 0, error => 'local only' });
	}
	return $c->render(json => { ok => 0, error => 'not signed in' }) unless $c->session('authentication') eq 'approved';
	return $c->render(json => { ok => 0, error => 'no fingerprint' }) unless &fingerprint_available();
	# A Go approval uses the same reader but mints no padlock: the session must
	# be the one that asked, and the print is the second factor for the ticket.
	my $purpose = ($c->param('purpose') || '') eq 'go' ? 'go' : '';
	my $go_request = '';
	my $mode;
	my $target;
	my $device = $c->session('device_uuid') || $c->session('app_device') || '';
	if ($purpose eq 'go') {
		$go_request = $c->param('request_id') || '';
		unless (($c->session('app_device') || '') ne ''
			&& $go_request =~ /^[A-Za-z0-9]{8,64}$/
			&& ($c->session('go_request') || '') eq $go_request
			&& (&go_request_get($go_request))->{'id'}) {
			return $c->render(json => { ok => 0, error => 'no request' });
		}
		$mode = 'go';
		$target = $go_request;
	}
	else {
		$mode = $c->param('mode') || 'locker';
		$mode = 'locker' unless $mode =~ /^(?:locker|gallery|music|folders)$/;
		$device = &media_unlock_device($c) unless length $device;
		# the reader opens the screen it is attached to: an app padlock names that
		# screen too, so the unlock never becomes a house-wide one
		$target = ($mode ne 'locker') ? $device : '';
		if ($mode ne 'locker' && !length $target) {
			return $c->render(json => { ok => 0, error => 'no device' });
		}
	}
	my $lockfile = '/tmp/jawnos_fingerprint.lock';
	# a worker that died mid-read left the latch behind; it is not a reader that
	# is still busy, and without this the button answered busy forever
	if (-e $lockfile && time - (stat($lockfile))[9] > 30) {
		unlink $lockfile;
		$log->info('padlock: removed a stale fingerprint lock');
	}
	my $fh;
	unless (sysopen($fh, $lockfile, O_CREAT|O_EXCL|O_WRONLY)) {
		$log->info('padlock: local fingerprint busy from ' . $ip);
		return $c->render(json => { ok => 0, error => 'busy' });
	}
	close $fh;
	my $user = $ENV{USER} || getpwuid($<) || 'jawn';
	$user =~ s/[^\w.-]//g;
	my $token = &subs::random_string_creator(24);
	my $now = &subs::rightNow();
	my %fingerprint = (pending => 1, device => $device, ip => $ip, mode => $mode, target => $target);
	my $source_tab = $c->param('browser_tab_id') || '';
	$source_tab = '' unless $source_tab =~ /^[A-Za-z0-9_-]{1,64}$/;
	$fingerprint{'tab'} = $source_tab;
	$fingerprint{'device_param'} = &media_unlock_device($c);
	$fingerprint{'purpose'} = 'go' if $purpose eq 'go';
	$fingerprint{'request_id'} = $go_request if $purpose eq 'go';
	&subs::db_query('delete from cache where context = ? and server_time < ?', 'padlock_fingerprint', $now - 300000);
	&subs::db_insert('cache', {
		uuid => $token, context => 'padlock_fingerprint', app => '__president',
		data => encode_json(\%fingerprint),
		server_time => $now, timestamp => $now,
	});
	Mojo::IOLoop->subprocess(
		sub {
			my $rc = system('timeout', '20', 'fprintd-verify', $user);
			return (defined $rc ? $rc : -1);
		},
		sub {
			my ($loop, $err, $rc) = @_;
			unlink $lockfile;
			# The subprocess carries the child's $@ as $err. It is an EMPTY
			# string on a clean run, not undef; treating defined-but-empty as
			# a failure is what reported a matching print (rc=0) as refused.
			my $child_error = (defined $err && $err ne '') ? $err : '';
			my $ok = (!$child_error && defined $rc && $rc == 0) ? 1 : 0;
			my $error = $ok ? '' : ($child_error ? 'reader error' : ((defined $rc && $rc == 31744) ? 'timeout' : 'not accepted'));
			my %result = (pending => 0, ok => $ok, error => $error, device => $device, ip => $ip, mode => $mode, target => $target, tab => $source_tab, device_param => &media_unlock_device($c));
			$result{'purpose'} = 'go' if $purpose eq 'go';
			$result{'request_id'} = $go_request if $purpose eq 'go';
			&subs::db_query('update cache set data = ?, server_time = ? where context = ? and uuid = ?',
				encode_json(\%result),
				&subs::rightNow(), 'padlock_fingerprint', $token);
			eval { $log->info('padlock: local fingerprint ' . ($ok ? 'accepted' : 'refused') . ' from ' . $ip . ' rc=' . (defined $rc ? $rc : '?')) };
		}
	);
	$c->render(json => { ok => 0, pending => 1, token => $token });
};

# The reader is still waiting. The locked page polls this until the child above
# records a result; only an accepted print opens the session's own screen.
get '/manager/security/fingerprint_unlock_status' => sub ($c) {
	return $c->render(json => { ok => 0, error => 'not signed in' }) unless $c->session('authentication') eq 'approved';
	my $token = $c->param('token') || '';
	return $c->render(json => { ok => 0, error => 'no challenge' }) unless $token =~ /^[A-Za-z0-9]{8,64}$/;
	my $row = &subs::db_query('select data, server_time from cache where context = ? and uuid = ? limit 1', 'padlock_fingerprint', $token)->hashes->[0];
	unless ($row) { return $c->render(json => { ok => 0, error => 'no result' }); }
	my $d = eval { decode_json $row->{'data'} } || {};
	if ($d->{'pending'}) {
		if (($row->{'server_time'} || 0) < &subs::rightNow() - 30000) {
			&subs::db_query('delete from cache where context = ? and uuid = ?', 'padlock_fingerprint', $token);
			return $c->render(json => { ok => 0, error => 'timeout' });
		}
		return $c->render(json => { ok => 0, pending => 1 });
	}
	&subs::db_query('delete from cache where context = ? and uuid = ?', 'padlock_fingerprint', $token);
	unless ($d->{'ok'}) { return $c->render(json => { ok => 0, error => ($d->{'error'} || 'not accepted') }); }
	# A Go approval confirms the ticket, not a screen: record it and leave the
	# mint to go_status, which is the session that asked.
	if (($d->{'purpose'} || '') eq 'go') {
		my $rid = $d->{'request_id'} || '';
		unless ($rid =~ /^[A-Za-z0-9]{8,64}$/ && ($c->session('go_request') || '') eq $rid) {
			return $c->render(json => { ok => 0, error => 'no request' });
		}
		&go_approval_record($rid, 'fingerprint', ($d->{'device'} || $c->session('device_uuid') || ''), 'this computer');
		&padlock_request_clear($rid);
		&go_dismiss($rid);
		$log->info('go: local fingerprint approved request=' . $rid);
		return $c->render(json => { ok => 1, approved => 1 });
	}
	# the print was accepted: open the screen and padlock it was asked for
	my $device = $c->session('device_uuid') || $d->{'device'} || '';
	my $mode = $d->{'mode'} || 'locker';
	$mode = 'locker' unless $mode =~ /^(?:locker|gallery|music|folders)$/;
	my $target = $d->{'target'} || $device;
	if ($mode ne 'locker' && !length $target) {
		return $c->render(json => { ok => 0, error => 'no device' });
	}
	# the token belongs to the window that pressed the button, not every tab
	my $tab = $c->param('browser_tab_id') || $d->{'tab'} || '';
	$tab = '' unless $tab =~ /^[A-Za-z0-9_-]{1,64}$/;
	my $opened = &padlock_mark_unlocked($c, $mode, $target, $tab);
	$log->info('padlock: local fingerprint opened ' . ($mode ne 'locker' ? "$mode padlock on " : '') . ($target || 'this screen'));
	my $unlock_token = ($mode ne 'locker' && $opened) ? &media_unlock_token($mode, $target) : '';
	$c->render(json => { ok => ($opened ? 1 : 0), unlocked => ($opened ? 1 : 0), unlock => $unlock_token });
};

# --- Go approvals ----------------------------------------------------------
# The installed app asks for a second factor before the peer ticket is minted.
# go_status polls for the approval and mints the ticket once; go_ask puts the
# request on the padlock prompt rail so a phone/tablet can answer it; go_approve
# verifies the device's signature and hands the approval to the machine that
# made the request (the phone often talks to a different jawn).
get '/manager/security/go_status' => sub ($c) {
	return $c->render(json => { ok => 0, error => 'not signed in' }) unless $c->session('authentication') eq 'approved';
	my $id = $c->param('request_id') || '';
	return $c->render(json => { ok => 0, error => 'no request' })
		unless $id =~ /^[A-Za-z0-9]{8,64}$/ && ($c->session('go_request') || '') eq $id;
	my $request = &go_request_get($id);
	unless ($request->{'id'}) { return $c->render(json => { ok => 0, error => 'expired' }); }
	my $approval = &go_approval_get($id);
	unless ($approval->{'approved'}) { return $c->render(json => { ok => 1, pending => 1 }); }
	my $rm = $request->{'peer_uuid'}
		? &subs::remote_machine_lister({ uuid => $request->{'peer_uuid'}, self => 'no', limit => 1 })
		: undef;
	unless (ref $rm eq 'HASH' && $rm->{'manager'}) { return $c->render(json => { ok => 0, error => 'no machine' }); }
	my $ticket = eval { &remote_manager_ticket($c, $rm) } || '';
	unless ($ticket) {
		$log->info('go: ticket mint failed for ' . ($request->{'peer_name'} || $request->{'peer_uuid'} || '?') . ' request=' . $id);
		return $c->render(json => { ok => 0, error => 'ticket' });
	}
	&go_approval_clear($id);
	&go_request_clear($id);
	&padlock_request_clear($id);
	my $manager = $c->session('go_manager') || '';
	$c->session('go_request' => undef);
	$c->session('go_peer_uuid' => undef);
	$c->session('go_manager' => undef);
	$c->session('go_name' => undef);
	# Every machine that relayed the request may still be showing the prompt.
	&subs::subprocessor(sub {
		Mojo::IOLoop->reset;
		&remote_relay_request($c, {
			override => 'manual',
			url => '/manager/security/go_clear_peer',
			type => 'get',
			dissemination => 'yes',
			params => { signatorial => &subs::signatorial_designer(), request_id => $id },
		});
	}, { name => 'go approval clear relay' });
	$log->info('go: approved (' . ($approval->{'by'} || '?') . ') and ticket minted for ' . ($request->{'peer_name'} || '?') . ' request=' . $id);
	$c->render(json => {
		ok => 1, approved => 1, ticket_url => $ticket,
		manager => $manager, uuid => ($rm->{'uuid'} || ''), name => ($request->{'peer_name'} || ''),
		device_uuid => ($c->session('app_device') || ''),
	});
};

post '/manager/security/go_ask' => sub ($c) {
	return $c->render(json => { ok => 0, error => 'not signed in' }) unless ($c->session('app_device') || '') ne '';
	my $id = $c->param('request_id') || '';
	return $c->render(json => { ok => 0, error => 'no request' })
		unless $id =~ /^[A-Za-z0-9]{8,64}$/ && ($c->session('go_request') || '') eq $id;
	my $request = &go_request_get($id);
	unless ($request->{'id'}) { return $c->render(json => { ok => 0, error => 'expired' }); }
	my $mode = 'go';
	my $device_name = $request->{'peer_name'} || '';
	my $source_device = $request->{'source_device'} || '';
	my $source = $request->{'source'} || &subs::signatorial_designer();
	my $source_hostname = $request->{'source_hostname'} || '';
	&padlock_request_store($id, $mode, $source, $id, $device_name, $source_device, $source_hostname);
	&Websocket::send('server', {
		padlock_key_show => 1, prompt => 1, request_id => $id,
		device_name => $device_name, source_device => $source_device, source => $source,
		source_hostname => $source_hostname, house => 0, mode => $mode, target => $id, show => 0,
		timestamp => &subs::rightNow(),
	});
	&padlock_key_show_relay($c, $mode, $id, 0, 1, $id, $device_name, $source_device, $source_hostname);
	$log->info('go: asked the house to approve ' . ($device_name || '?') . ' request=' . $id);
	$c->render(json => { ok => 1, request_id => $id });
};

post '/manager/security/go_approve' => sub ($c) {
	my $device_uuid = $c->param('device_uuid') || '';
	my $request_id = $c->param('request_id') || '';
	my $nonce = $c->param('nonce') || '';
	my $signature = $c->param('signature') || '';
	my $kind = ($c->param('kind') || 'pair') eq 'bio' ? 'bio' : 'pair';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	return $c->render(json => { ok => 0, error => 'not paired' }) unless $device;
	return $c->render(json => { ok => 0, error => 'no request' })
		unless $request_id =~ /^[A-Za-z0-9]{8,64}$/ && $nonce =~ /^[A-Za-z0-9]{8,64}$/;
	my $request = &padlock_request_get($request_id);
	unless (($request->{'id'} || '') eq $request_id && ($request->{'mode'} || '') eq 'go') {
		# A phone approving its own Go (or this machine's live page) has no
		# padlock prompt to read: the request it answers is go_request here.
		my $own = &go_request_get($request_id);
		$request = ($own->{'id'} && (($own->{'source'} || '') eq &subs::signatorial_designer())) ? $own : {};
	}
	unless ($request->{'id'}) {
		return $c->render(json => { ok => 0, error => 'no request' });
	}
	my $msg = join("\n", 'go-approve', $device_uuid, $request_id, $nonce);
	my $ok = 0;
	if ($kind eq 'bio') {
		$ok = (&biometric_nonce_take('go', $device_uuid, $nonce)
			&& ($device->{'bio_pubkey'} || '') ne ''
			&& &subs::ecdsa_verify($device->{'bio_pubkey'}, $msg, $signature)) ? 1 : 0;
	}
	else {
		my $seen = &subs::db_query('select server_time from cache where context = ? and uuid = ? limit 1', 'padlock_nonce', $device_uuid . ':' . $nonce)->hashes->[0];
		$ok = (($device->{'pubkey'} || '') ne ''
			&& $seen && $seen->{'server_time'} && $seen->{'server_time'} > &subs::rightNow() - 60000
			&& &subs::signature_verify($device->{'pubkey'}, $msg, $signature)) ? 1 : 0;
		&subs::db_query('delete from cache where context = ? and uuid = ?', 'padlock_nonce', $device_uuid . ':' . $nonce) if $ok;
	}
	unless ($ok) {
		$log->info('go: approval refused for ' . ($device->{'name'} || $device_uuid) . ' request=' . $request_id);
		return $c->render(json => { ok => 0, error => 'not accepted' });
	}
	my $source = $request->{'source'} || '';
	my $self = &subs::signatorial_designer();
	my $name = $device->{'name'} || '';
	if ($source eq $self) {
		&go_approval_record($request_id, $kind, $device_uuid, $name);
	}
	else {
		my $rm = $source ? &subs::db_select('remote_machines', undef, { signatorial => $source })->hashes->[0] : undef;
		unless ($rm && $rm->{'uuid'}) { return $c->render(json => { ok => 0, error => 'source' }); }
		&subs::subprocessor(sub {
			Mojo::IOLoop->reset;
			&remote_relay_request($c, {
				override => 'manual',
				remote_uuid => $rm->{'uuid'},
				url => '/manager/security/go_open_peer',
				type => 'get',
				params => {
					signatorial => &subs::signatorial_designer(),
					request_id => $request_id,
					device_uuid => $device_uuid,
					device_name => $name,
					kind => $kind,
				},
			});
		}, { name => 'go approval relay' });
	}
	&padlock_request_clear($request_id);
	&go_dismiss($request_id);
	$log->info('go: approved by ' . ($name || $device_uuid) . ' request=' . $request_id . ' kind=' . $kind);
	$c->render(json => { ok => 1, approved => 1 });
};

get '/manager/security/go_open_peer' => sub ($c) {
	my $signatorial = $c->param('signatorial') || '';
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm)) {
		$log->info('go: peer approval refused from ' . ($signatorial || '?') . ' at ' . ($c->tx->remote_address || '?'));
		return $c->rendered(403);
	}
	my $request_id = $c->param('request_id') || '';
	return $c->rendered(400) unless $request_id =~ /^[A-Za-z0-9]{8,64}$/;
	my $device_uuid = $c->param('device_uuid') || '';
	$device_uuid = '' unless $device_uuid =~ /^[A-Za-z0-9]{8,64}$/;
	my $device_name = $c->param('device_name') || '';
	$device_name =~ s/[\r\n\t]//g;
	$device_name = substr($device_name, 0, 120);
	my $kind = ($c->param('kind') || 'pair') eq 'bio' ? 'bio' : 'pair';
	&go_approval_record($request_id, $kind, $device_uuid, $device_name);
	&padlock_request_clear($request_id);
	&go_dismiss($request_id);
	$log->info('go: approval relayed from ' . ($rm->{'hostname'} || $signatorial) . ' request=' . $request_id . ' by ' . ($device_name || $device_uuid || '?'));
	$c->render(json => { ok => 1 });
};

# The ticket is minted on the machine that pressed Go; every machine that
# relayed the prompt drops it here, so the other devices stop asking.
get '/manager/security/go_clear_peer' => sub ($c) {
	my $signatorial = $c->param('signatorial') || '';
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm)) {
		return $c->rendered(403);
	}
	my $request_id = $c->param('request_id') || '';
	return $c->rendered(400) unless $request_id =~ /^[A-Za-z0-9]{8,64}$/;
	&padlock_request_clear($request_id);
	&go_dismiss($request_id);
	$c->render(json => { ok => 1 });
};

# --- local biometric unlock ------------------------------------------------
# The phone's Android app keeps an EC P-256 key in the Android Keystore with
# setUserAuthenticationRequired: the OS will not use it until the person passes
# the fingerprint prompt. The house verifies the key's signature, so this is a
# real factor - unlike the JS confirmation the phone-as-key page uses - and it
# is the one signature a local request may present. It opens only the screen it
# is on, never another device and never the whole house.
sub biometric_nonce_take {
	my ($purpose, $device_uuid, $nonce, $ttl) = @_;
	$ttl ||= 60000;
	return 0 unless defined $nonce && $nonce =~ /^[A-Za-z0-9]{8,64}$/;
	my $stamp = $purpose . ':' . $device_uuid . ':' . $nonce;
	my $seen = &subs::db_query('select server_time from cache where context = ? and uuid = ? limit 1', 'padlock_bio_nonce', $stamp)->hashes->[0];
	return 0 unless $seen && $seen->{'server_time'} && $seen->{'server_time'} > &subs::rightNow() - $ttl;
	&subs::db_query('delete from cache where context = ? and uuid = ?', 'padlock_bio_nonce', $stamp);
	return 1;
}

# A payment is confirmed by the current device's enrolled biometric key: the
# phone signs a verify challenge, the same proof used before replacing a
# fingerprint. A device with no key has no biometric to ask for, so the signed-in
# citizen is the fallback there; the panel says which path it will use.
sub biometric_payment_confirmed {
	my ($c) = @_;
	my $device_uuid = $c->session('device_uuid') || '';
	my $device = $device_uuid
		? &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]
		: undef;
	# A device with no key of its own asks a fingerprinted device in the house.
	# If the house has none, the signed-in citizen is the fallback.
	unless ($device && $device->{'bio_pubkey'}) {
		my $other = &house_bio_device($device_uuid);
		return { ok => 1, enrolled => 0, no_bio => 1 } unless $other;
		return { ok => 0, enrolled => 0, other => 1, other_name => $other->{'name'} || '' };
	}
	my $nonce = $c->param('bio_nonce') || '';
	my $signature = $c->param('bio_signature') || '';
	return { ok => 0, enrolled => 1, self => 1 } unless length $nonce && length $signature;
	return { ok => 0, enrolled => 1, self => 1 } unless &biometric_nonce_take('verify', $device_uuid, $nonce, 600000);
	my $msg = join("\n", 'padlock-bio-verify', $device_uuid, $nonce);
	return { ok => &subs::ecdsa_verify($device->{'bio_pubkey'}, $msg, $signature) ? 1 : 0, enrolled => 1, self => 1 };
}

post '/manager/security/biometric_challenge' => sub ($c) {
	my $purpose = $c->param('purpose') || 'unlock';
	$purpose = 'unlock' unless $purpose =~ /^(?:enroll|unlock|verify|go|pay)$/;
	my $device_uuid = $c->param('device_uuid') || $c->session('device_uuid') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	unless ($device) { return $c->render(json => { ok => 0, error => 'not paired' }); }
	my $ip = $c->tx->remote_address || '?';
	my $now = &subs::rightNow();
	my $fails = &subs::db_query('select count(*) as n from cache where context = ? and uuid like ? and server_time > ?', 'padlock_bio_fail', $ip . ':%', $now - 300000)->hash->{'n'} || 0;
	if ($fails >= 5) { return $c->render(json => { ok => 0, error => 'too many' }); }
	my $recent = &subs::db_query('select count(*) as n from cache where context = ? and uuid like ? and server_time > ?', 'padlock_bio_challenge', $ip . ':%', $now - 60000)->hash->{'n'} || 0;
	if ($recent >= 20) { return $c->render(json => { ok => 0, error => 'too many' }); }
	&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'padlock_bio_challenge', app => '__president', server_time => $now, timestamp => $now });
	my $nonce = &subs::random_string_creator(40);
	&subs::db_query('delete from cache where context = ? and server_time < ? and uuid not like ?', 'padlock_bio_nonce', $now - 120000, 'verify:%');
	&subs::db_query('delete from cache where context = ? and server_time < ?', 'padlock_bio_nonce', $now - 900000);
	&subs::db_insert('cache', { uuid => $purpose . ':' . $device_uuid . ':' . $nonce, context => 'padlock_bio_nonce', app => '__president', server_time => $now, timestamp => $now });
	$c->render(json => { ok => 1, nonce => $nonce, seconds => 60 });
};

# Enrollment is bound to the device's existing Ed25519 key: the page signs the
# new public key with the key it was paired with. The EC key itself is made by
# the Android app only after its own biometric prompt.
post '/manager/security/biometric_enroll' => sub ($c) {
	return $c->render(json => { ok => 0, error => 'locked' }) if &padlock_locked_now($c);
	return $c->render(json => { ok => 0, error => 'not signed in' }) unless $c->session('authentication') eq 'approved';
	my $device_uuid = $c->param('device_uuid') || $c->session('device_uuid') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	return $c->render(json => { ok => 0, error => 'not paired' }) unless $device;
	my $nonce = $c->param('nonce') || '';
	my $device_sig = $c->param('device_signature') || '';
	my $pubkey = $c->param('pubkey') || '';
	return $c->render(json => { ok => 0, error => 'bad key' }) unless &subs::ecdsa_public_key_ok($pubkey);
	my $ip = $c->tx->remote_address || '?';
	my $now = &subs::rightNow();
	# An enrolled fingerprint is a second factor, so replacing it must present
	# that factor: the old EC key signs a fresh verify challenge. Without this,
	# the device's pairing key alone could swap the fingerprint behind the
	# person's back.
	if ($device->{'bio_pubkey'}) {
		my $bio_nonce = $c->param('bio_nonce') || '';
		my $bio_signature = $c->param('bio_signature') || '';
		my $confirmed = &biometric_nonce_take('verify', $device_uuid, $bio_nonce, 600000)
			&& &subs::ecdsa_verify($device->{'bio_pubkey'}, join("\n", 'padlock-bio-verify', $device_uuid, $bio_nonce), $bio_signature);
		unless ($confirmed) {
			&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'padlock_bio_fail', app => '__president', server_time => $now, timestamp => $now });
			$log->info('padlock: biometric replacement refused for ' . ($device->{'name'} || $device_uuid) . ' from ' . $ip);
			return $c->render(json => { ok => 0, error => 'confirm fingerprint' });
		}
	}
	my $fresh = &biometric_nonce_take('enroll', $device_uuid, $nonce);
	unless ($fresh) { return $c->render(json => { ok => 0, error => 'no challenge' }); }
	require Digest::SHA;
	my $msg = join("\n", 'padlock-bio-enroll', $device_uuid, $nonce, Digest::SHA::sha256_hex($pubkey));
	unless (&subs::signature_verify($device->{'pubkey'}, $msg, $device_sig)) {
		&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'padlock_bio_fail', app => '__president', server_time => $now, timestamp => $now });
		$log->info('padlock: biometric enrollment refused for ' . ($device->{'name'} || $device_uuid) . ' from ' . $ip);
		return $c->render(json => { ok => 0, error => 'not accepted' });
	}
	&subs::db_update('paired_devices', { bio_pubkey => $pubkey, kind => 'phone' }, { uuid => $device_uuid });
	&subs::db_query('delete from cache where context = ? and uuid like ?', 'padlock_bio_fail', $ip . ':%');
	$log->info('padlock: biometric key enrolled for ' . ($device->{'name'} || $device_uuid) . ' from ' . $ip);
	$c->render(json => { ok => 1, device_uuid => $device_uuid });
};

post '/manager/security/biometric_unlock' => sub ($c) {
	my $device_uuid = $c->param('device_uuid') || $c->session('device_uuid') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	return $c->render(json => { ok => 0, error => 'not paired' }) unless $device;
	return $c->render(json => { ok => 0, error => 'no biometric key' }) unless $device->{'bio_pubkey'};
	my $nonce = $c->param('nonce') || '';
	my $signature = $c->param('signature') || '';
	my $mode = $c->param('mode') || 'locker';
	$mode = 'locker' unless $mode =~ /^(?:locker|gallery|music|folders)$/;
	# The phone may confirm an unlock for ANOTHER screen (the person presses
	# Unlock on the laptop, then touches the phone). The target is bound into the
	# signed message, so a signature made for one screen cannot be replayed for
	# another. An empty target is the phone's own screen.
	my $target = $c->param('target') || '';
	$target = '' unless $target =~ /^[A-Za-z0-9]{8,64}$/;
	# An empty target is the house-wide lock (the locked screen had no device
	# identity), not this phone's own screen. `house` binds that meaning into
	# the signature and keeps the open from being applied to the phone instead.
	my $house = $c->param('house') ? 1 : 0;
	if ($target && !&subs::db_select('paired_devices', undef, { uuid => $target, status => 'active' })->hashes->[0]) {
		return $c->render(json => { ok => 0, error => 'not paired' });
	}
	my $ip = $c->tx->remote_address || '?';
	my $now = &subs::rightNow();
	my $fresh = &biometric_nonce_take('unlock', $device_uuid, $nonce);
	unless ($fresh) { return $c->render(json => { ok => 0, error => 'no challenge' }); }
	my $signed_target = $house ? 'house' : $target;
	my $msg = $signed_target
		? join("\n", 'padlock-bio-unlock', $device_uuid, $signed_target, $nonce)
		: join("\n", 'padlock-bio-unlock', $device_uuid, $nonce);
	unless (&subs::ecdsa_verify($device->{'bio_pubkey'}, $msg, $signature)) {
		&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'padlock_bio_fail', app => '__president', server_time => $now, timestamp => $now });
		$log->info('padlock: biometric signature refused for ' . ($device->{'name'} || $device_uuid) . ' from ' . $ip);
		return $c->render(json => { ok => 0, error => 'not accepted' });
	}
	&subs::db_query('delete from cache where context = ? and uuid like ?', 'padlock_bio_fail', $ip . ':%');
	my $open_target = $house ? '' : ($target || $device_uuid);
	# A whole-house lock keeps the other screens locked on the house-wide stamp.
	my $opened = &padlock_mark_unlocked($c, $mode, $open_target);
	&padlock_request_clear($open_target);
	# the authoritative lock may live on another peer: hand the open over the
	# signed rail, the same way a phone-as-key unlock does
	&subs::subprocessor(sub {
		Mojo::IOLoop->reset;
		&remote_relay_request($c, {
			override => 'manual',
			url => '/manager/security/padlock_open_peer',
			type => 'get',
			dissemination => 'yes',
			params => {
				signatorial => &subs::signatorial_designer(),
				target => $open_target,
				mode => $mode,
				house => ($house ? 1 : 0),
			},
		});
	}, { name => 'padlock biometric relay' });
	$log->info('padlock: biometric open by ' . ($device->{'name'} || $device_uuid) . ' from ' . $ip . ' target=' . ($target || 'self'));
	my $unlock_token = ($mode ne 'locker' && $opened) ? &media_unlock_token($mode, $open_target) : '';
	$c->render(json => { ok => ($opened ? 1 : 0), unlocked => ($opened ? 1 : 0), name => $device->{'name'}, target => $open_target, unlock => $unlock_token });
};

# --- opening the lock with a paired device's signature ---------------------
# The phone/tablet asks for a short-lived nonce, signs
# "padlock-unlock\n<uuid>\n<nonce>" with the key it was paired with, and the
# house verifies it. The nonce is single-use; a request from this machine
# itself is refused, so the locked screen cannot open its own door.
post '/manager/security/padlock_challenge' => sub ($c) {
	my $device_uuid = $c->param('device_uuid') || '';
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	unless ($device) { return $c->render(json => { ok => 0 }); }
	my $ip = $c->tx->remote_address || '?';
	my $now = &subs::rightNow();
	my $fails = &subs::db_query('select count(*) as n from cache where context = ? and uuid like ? and server_time > ?', 'padlock_fail', $ip . ':%', $now - 300000)->hash->{'n'} || 0;
	if ($fails >= 5) { return $c->render(json => { ok => 0, error => 'too many' }); }
	# A challenge from someone else must not knock the phone's nonce out of the
	# cache, so expired ones are pruned instead of every nonce for the device;
	# the per-address count keeps the cache from being filled.
	my $recent = &subs::db_query('select count(*) as n from cache where context = ? and uuid like ? and server_time > ?', 'padlock_challenge', $ip . ':%', $now - 60000)->hash->{'n'} || 0;
	if ($recent >= 20) { return $c->render(json => { ok => 0, error => 'too many' }); }
	&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'padlock_challenge', app => '__president', server_time => $now, timestamp => $now });
	my $nonce = &subs::random_string_creator(40);
	&subs::db_query('delete from cache where context = ? and server_time < ?', 'padlock_nonce', $now - 120000);
	&subs::db_insert('cache', { uuid => $device_uuid . ':' . $nonce, context => 'padlock_nonce', app => '__president', server_time => $now, timestamp => $now });
	$c->render(json => { ok => 1, nonce => $nonce, seconds => 60 });
};

post '/manager/security/padlock_unlock' => sub ($c) {
	my $device_uuid = $c->param('device_uuid') || '';
	my $nonce = $c->param('nonce') || '';
	my $signature = $c->param('signature') || '';
	my $mode = $c->param('mode') || 'locker';
	$mode = 'locker' unless $mode =~ /^(?:locker|gallery|music|folders)$/;
	my $target = $c->param('target') || '';
	$target = '' unless $target =~ /^[A-Za-z0-9]{8,64}$/;
	my $house = $c->param('house') ? 1 : 0;
	my $device = ($device_uuid && &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0]);
	unless ($device && $nonce =~ /^[A-Za-z0-9]{8,64}$/) { return $c->render(json => { ok => 0 }); }
	my $ip = $c->tx->remote_address || '?';
	my $now = &subs::rightNow();
	my $stamp = $device_uuid . ':' . $nonce;
	my $seen = &subs::db_query('select server_time from cache where context = ? and uuid = ? limit 1', 'padlock_nonce', $stamp)->hashes->[0];
	unless ($seen && $seen->{'server_time'} && $seen->{'server_time'} > $now - 60000) {
		&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'padlock_fail', app => '__president', server_time => $now, timestamp => $now });
		return $c->render(json => { ok => 0 });
	}
	my $signed_target = $house ? 'house' : $target;
	my $msg = $signed_target
		? join("\n", ('padlock-unlock', $device_uuid, $signed_target, $nonce))
		: join("\n", ('padlock-unlock', $device_uuid, $nonce));
	unless (&subs::signature_verify($device->{'pubkey'}, $msg, $signature)) {
		&subs::db_insert('cache', { uuid => $ip . ':' . &subs::random_string_creator(12), context => 'padlock_fail', app => '__president', server_time => $now, timestamp => $now });
		$log->info('padlock: signature refused for ' . ($device->{'name'} || $device_uuid) . ' from ' . $ip);
		return $c->render(json => { ok => 0 });
	}
	# the phone, not the locked screen: a local signature would let a desktop
	# open its own door. A *handheld* is the exception - its own screen is the
	# one being opened, and the key is the paired device key in its own browser
	# (the desktop cannot reach it). Without this the phone's own "Open the
	# unlock page on this phone" answered error=local while the person was
	# holding the phone, which read as "open it on your phone" from the phone.
	# A local screen may still sign for ANOTHER screen (the unlock page is sent
	# to any device in the house); only its own screen and the whole-house lock
	# are refused.
	if (&padlock_request_is_local($c) && &subs::device_setter() ne 'mobile') {
		my $for_other = ($target && $target ne $device_uuid
			&& &subs::db_select('paired_devices', undef, { uuid => $target, status => 'active' })->hashes->[0]) ? 1 : 0;
		unless ($for_other) {
			$log->info('padlock: local signature refused from ' . $ip);
			return $c->render(json => { ok => 0, error => 'local' });
		}
	}
	&subs::db_query('delete from cache where context = ? and uuid = ?', 'padlock_nonce', $stamp);
	&subs::db_query('delete from cache where context = ? and uuid like ?', 'padlock_fail', $ip . ':%');
	my $open_target = $house ? '' : $target;
	my $locked = $open_target ? &padlock_target_locked($open_target, $c)
		: (&padlock_locked_now($c) || &padlock_global_locked($c));
	# A phone often talks to its own jawn, while the lock is authoritative on the
	# machine that made it. Clearing it here alone leaves that screen locked (the
	# device row never syncs as a deletion). The signature is verified above, so
	# hand the open to the peers over the signed rail; the machine that holds the
	# lock is the one that clears it.
	&subs::subprocessor(sub {
		Mojo::IOLoop->reset;
		&remote_relay_request($c, {
			override => 'manual',
			url => '/manager/security/padlock_open_peer',
			type => 'get',
			dissemination => 'yes',
			params => { signatorial => &subs::signatorial_designer(), target => $open_target, mode => $mode, house => ($house ? 1 : 0) },
		});
	}, { name => 'padlock unlock relay' });
	# A media padlock is not the screen timer: the app opens locked while the
	# screen itself is open, so its grant must be minted even then. Clearing the
	# request first would also lose the tab the token belongs to.
	if (!$locked && $mode eq 'locker') {
		&padlock_request_clear($open_target);
		return $c->render(json => { ok => 1, unlocked => 1, already => 1, relayed => ($open_target ? 1 : 0), name => $device->{'name'} });
	}
	my $opened = &padlock_mark_unlocked($c, $mode, $open_target);
	&padlock_request_clear($open_target);
	$log->info('padlock: opened by ' . ($device->{'name'} || $device_uuid) . ' from ' . $ip . ' mode=' . $mode . ($open_target ? ' target=' . $open_target : ' house'));
	$c->render(json => { ok => ($opened ? 1 : 0), unlocked => ($opened ? 1 : 0), name => $device->{'name'}, target => $open_target });
};

# The peer half of an unlock. A phone signs the challenge on whichever jawn it
# is talking to; that machine verifies the paired key and relays the open here,
# so the machine that actually holds the lock clears it. The relay is a signed
# peer request (peer_verify), so the target cannot be altered on the way.
get '/manager/security/padlock_open_peer' => sub ($c) {
	my $signatorial = $c->param('signatorial') || '';
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm)) {
		$log->info('padlock: peer unlock refused from ' . ($signatorial || '?') . ' at ' . ($c->tx->remote_address || '?'));
		return $c->rendered(403);
	}
	my $target = $c->param('target') || '';
	$target = '' unless $target =~ /^[A-Za-z0-9]{8,64}$/;
	my $mode = $c->param('mode') || 'locker';
	$mode = 'locker' unless $mode =~ /^(?:locker|gallery|music|folders)$/;
	my $opened = &padlock_mark_unlocked($c, $mode, $target);
	&padlock_request_clear($target);
	$log->info('padlock: peer unlock from ' . ($rm->{'hostname'} || $signatorial) . ' mode=' . $mode . ($target ? ' target=' . $target : ' house'));
	# A phone may reach the peer that holds the lock only through a machine in
	# between (a phone's roster is small). Carry the open on once, so the
	# machine that actually holds the lock hears it; relay_id stops a loop and
	# the source is not handed its own open back.
	my $relay_id = $c->param('relay_id') || '';
	if ($relay_id) {
		my $self = &subs::signatorial_designer();
		my $origin = $c->param('source_signatorial') || $signatorial;
		&subs::subprocessor(sub {
			Mojo::IOLoop->reset;
			&remote_relay_request($c, {
				override => 'manual',
				url => '/manager/security/padlock_open_peer',
				type => 'get',
				dissemination => 'yes',
				params => {
					signatorial => $self,
					target => $target,
					mode => $mode,
					house => ($target ? 0 : 1),
					dissemination => 'yes',
					source_signatorial => $origin,
					relay_from => $self,
					relay_id => $relay_id,
				},
			});
		}, { name => 'padlock open relay' });
	}
	$c->render(json => { ok => ($opened ? 1 : 0), target => $target });
};

# The peer half of "send the unlock page": the machine that holds the lock hands
# the message to every peer, and each one broadcasts it to its own screens. The
# caller is authenticated by its pinned peer signature, and relay_id lets the
# message walk a multi-hop mesh without looping.
post '/manager/security/padlock_key_show_peer' => sub ($c) {
	my $signatorial = $c->param('signatorial') || '';
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm)) {
		$log->info('padlock: key show refused from ' . ($signatorial || '?') . ' at ' . ($c->tx->remote_address || '?'));
		return $c->rendered(403);
	}
	my $mode = $c->param('mode') || 'locker';
	$mode = 'locker' unless $mode =~ /^(?:locker|gallery|music|folders|go)$/;
	my $target = $c->param('target') || '';
	$target = '' unless $target =~ /^[A-Za-z0-9]{8,64}$/;
	my $show = $c->param('show') ? 1 : 0;
	my $prompt = $c->param('prompt') ? 1 : 0;
	my $request_id = $c->param('request_id') || '';
	$request_id = '' unless $request_id =~ /^[A-Za-z0-9]{8,64}$/;
	my $device_name = $c->param('device_name') || '';
	$device_name =~ s/[\r\n\t]//g;
	$device_name = substr($device_name, 0, 120);
	my $source_device = $c->param('source_device') || '';
	$source_device = '' unless $source_device =~ /^[A-Za-z0-9]{8,64}$/;
	# the machine that actually holds the lock, not the peer relaying its prompt
	my $source = $c->param('source') || $signatorial;
	$source = '' unless $source =~ /^[A-Za-z0-9]{8,64}$/;
	my $source_hostname = $c->param('source_hostname') || ($rm->{'hostname'} || '');
	$source_hostname =~ s/[\r\n\t]//g;
	$source_hostname = substr($source_hostname, 0, 120);
	# keep the request readable on this machine too: a phone that is asleep
	# when the button is pressed finds it in padlock_state on its next wake
	if ($prompt) {
		$request_id = &padlock_request_store($target, $mode, $source, $request_id || undef, $device_name, $source_device, $source_hostname);
		$log->info('padlock: prompt received from ' . ($source_hostname || $signatorial) . ' for ' . ($target || 'house') . ' id=' . $request_id);
	}
	&Websocket::send('server', { padlock_key_show => 1, prompt => $prompt, request_id => $request_id, device_name => $device_name, source_device => $source_device, source => $source, source_hostname => $source_hostname, house => (($target || '') eq '' ? 1 : 0), mode => $mode, target => $target, show => $show, timestamp => &subs::rightNow() });
	my $relay_id = $c->param('relay_id') || '';
	if ($relay_id) {
		my $self = &subs::signatorial_designer();
		&subs::subprocessor(sub {
			Mojo::IOLoop->reset;
			&remote_relay_request($c, {
				override => 'manual',
				url => '/manager/security/padlock_key_show_peer',
				type => 'post',
				dissemination => 'yes',
				params => {
					signatorial => $self,
					mode => $mode,
					target => $target,
					show => $show,
					prompt => $prompt,
					request_id => $request_id,
					device_name => $device_name,
					source_device => $source_device,
					source_hostname => $source_hostname,
					source => $source,
					house => (($target || '') eq '' ? 1 : 0),
					dissemination => 'yes',
					source_signatorial => $self,
					relay_from => $self,
					relay_id => $relay_id,
				},
			});
		}, { name => 'padlock key show relay onward' });
	}
	$c->render(json => { ok => 1 });
};

get '/manager/security/padlock_state' => sub ($c) {
	my $padlock = &subs::db_select('security', undef, { level => 'padlock' })->hashes->[0];
	my $locks = &subs::db_select('security', undef, { level => 'padlock_device' })->hashes || [];
	my @targets;
	foreach my $lock ( @{$locks} ) {
		my $d = &subs::db_select('paired_devices', undef, { uuid => $lock->{'uuid'} })->hashes->[0];
		push @targets, { uuid => $lock->{'uuid'}, name => ($d ? $d->{'name'} : 'Unknown device') };
	}
	# A page may carry its device in localStorage even when the session cookie
	# has lost device_uuid (a cookieless webview wake, or a ticket that signed in
	# without one). Accept a parameter only for a paired, active device, and bind
	# it to the session: the gate and every lock route read the session, so the
	# next page load can no longer look like an unidentified screen (which the
	# gate treated as an open house).
	my $session_du = $c->session('device_uuid') || '';
	my $param_du = $c->param('device_uuid') || '';
	my $du = '';
	if ($session_du && $session_du =~ /^[A-Za-z0-9]{8,64}$/
		&& &subs::db_select('paired_devices', undef, { uuid => $session_du, status => 'active' })->hashes->[0]) {
		# An established session keeps its own device: a locked screen must not
		# be able to name an unlocked device and step out of its own lock.
		$du = $session_du;
	}
	elsif ($param_du && $param_du =~ /^[A-Za-z0-9]{8,64}$/
		&& &subs::db_select('paired_devices', undef, { uuid => $param_du, status => 'active' })->hashes->[0]) {
		# A session that lost its device (a cookieless webview wake, or a ticket
		# signed in without one) adopts the page's paired device once.
		$du = $param_du;
		$c->session('device_uuid' => $du);
	}
	# The page's own device is the one that carries the fingerprint (a re-pair,
	# or an app session made before pairing). Adopt it unless doing so would
	# open a locked screen by naming a device that is already open: a locked
	# session may adopt a device that is also locked (adding restriction), but
	# never one with its own open timer.
	if ($param_du && $param_du ne $du && $param_du =~ /^[A-Za-z0-9]{8,64}$/
		&& &subs::db_select('paired_devices', undef, { uuid => $param_du, status => 'active' })->hashes->[0]) {
		my $session_locked = $du ? (&padlock_locked_now($c, $du) ? 1 : 0) : (&padlock_global_locked($c) ? 1 : 0);
		my $param_locked = &padlock_locked_now($c, $param_du) ? 1 : 0;
		if ($param_locked || !$session_locked) {
			$du = $param_du;
			$c->session('device_uuid' => $du);
		}
	}
	my $request = &padlock_request_get();
	$c->render(json => {
		ok => 1,
		has_padlock => ($padlock ? 1 : 0),
		locked => (&padlock_locked_now($c, $du) ? 1 : 0),
		global_locked => (&padlock_global_locked($c) ? 1 : 0),
		gate => &padlock_gate_mode(),
		device => $du,
		device_until => (&padlock_device_until($du) || 0),
		biometric_enrolled => (&biometric_enrolled_for($du) ? 1 : 0),
		targets => \@targets,
		request => $request
	});
};

get '/manager/security/padlock_key' => sub ($c) {
	unless ($c->session('authentication') eq 'approved') {
		return $c->render(template => 'guest_layouts/denial', message => 'Sign in before showing the phone key.');
	}
	my $padlock = &subs::db_select('security', undef, { level => 'padlock' })->hashes->[0];
	$c->render(template => 'padlock_key', layout => 'padlock_key', has_padlock => ($padlock ? 1 : 0));
};

get '/manager/security/padlock_key/frame' => sub ($c) {
	return $c->render(json => { error => 'the camera key is disabled' });
};

get '/manager/security/padlock_key/active' => sub ($c) {
	return $c->render(json => { watching => 0, disabled => 1 });
};

sub padlock_time_extender($c) {
#	&subs::subprocessor(sub {
		my $session_timeout = $c->session('pl_time');
		my $server_time = &subs::rightNow();
		my $padlock = &subs::db_select('security', undef, { level => 'padlock' })->hashes;
		my $device = $c->session('device_uuid') || '';
		my $device_until = $device ? &padlock_device_until($device) : 0;
		if ($c->session('authentication') eq 'approved' && scalar @{$padlock} > 0 && (($device_until && $device_until > $server_time) || $session_timeout > $server_time)) {
			my $attempts = &subs::note_decrypter(&subs::session_suds($c), &subs::setting_grabber({ app => '__president', setting => 'padlock_pulls' }));
			if ($attempts < 5) {
				my $activity_timeout = &subs::setting_grabber({ app => 'me', setting => 'activity_timeout' }) || '-2h';
				$activity_timeout = abs &subs::time_abbrev_translator($activity_timeout);
				my $new_time = $server_time + $activity_timeout;
				if ($device_until && $device_until > $server_time) {
					&padlock_device_set_time($device, $new_time);
					$c->session('pl_time' => $new_time);
				}
				else {
					my $padlock_time = &padlock_time_value(&subs::suds_grabber(), &subs::setting_grabber({ app => '__president', setting => 'pl_time' }) );
					if ($padlock_time > $server_time) {
						&subs::setting_setter({ app => '__president', setting => 'pl_time', value => $new_time });
						$c->session('pl_time' => $new_time);
					}
				}
			}
		}
#	}, { name => 'padlock time extender' });
}

# A self-contained page command for a phone-side send: the new bundle's helper
# when it is there, the bridge when the bundle is old but the app is new, and
# the phone's own termux when neither has landed yet - so a message always goes
# out during the hand-over from termux-sms-send.
sub sms_send_command($digits, $message) {
	# json_chars hands back characters, not UTF-8 bytes: the console string is
	# concatenated with character literals and then JSON-encoded again for the
	# socket, so bytes here would be read as Latin-1 and an emoji would reach the
	# bridge as mojibake (or be refused).
	my $d = &subs::json_chars($digits);
	my $m = &subs::json_chars($message);
	return 'typeof jawnSmsSend === "function" ? jawnSmsSend(' . $d . ',' . $m . ')'
		. ' : (window.JawnSms && window.JawnSms.send ? (window.JawnSms.send(' . $d . ',' . $m . '), "bridge")'
		. ' : (function(){ $.post("/manager/sms/termux_fallback", {digits: ' . $d . ', message: ' . $m . '}); return "termux"; })())';
}
sub sms_mms_command($digits, $text, $parts, $jawn_uuid) {
	my $d = &subs::json_chars($digits);
	my $t = &subs::json_chars($text);
	my $p = &subs::json_chars($parts);
	my $u = &subs::json_chars($jawn_uuid || '');
	my $call = 'jawnSmsMms(' . $d . ',' . $t . ',' . $p . ',' . $u . ')';
	# The command names its own outcome in the phone's log: 'ok' means the page
	# had the bridge and called it, 'no bridge' means the app page is old or this
	# is not the JawnOS app. The bridge then posts its own result (via mms/share),
	# including the system MMS row it filed (its id, date and thread) so the
	# house row can wear the same identity instead of standing beside it.
	return '(function(){ try { var r = (typeof jawnSmsMms === "function") ? ' . $call . ' : "no bridge";'
		. ' if (typeof window.__jawnSmsResult === "function") { window.__jawnSmsResult({ ok: (r === "ok" ? 1 : 0), via: "mms_command", error: (r === "ok" ? "" : r) }); }'
		. ' return r; } catch (e) { if (typeof window.__jawnSmsResult === "function") { window.__jawnSmsResult({ ok: 0, via: "mms_command", error: String(e) }); } return "error"; } })()';
}

# This machine's radio. termux-telephony-deviceinfo is the same source the
# Phone app trusts: a phone answers phone_type=gsm/cdma with a ready SIM, a
# wifi-only tablet answers phone_type=none, and a desktop has no termux at all.
sub telephony_status() {
	my $state = { telephony => 0, phone_type => 'none', sim_state => '', network_type => '' };
	return $state unless &subs::device_setter() eq 'mobile';
	my $json = `timeout 8 termux-telephony-deviceinfo 2>/dev/null`;
	my $info = eval { return decode_json $json } || {};
	my $type = lc($info->{'phone_type'} || 'none');
	my $sim = lc($info->{'sim_state'} || '');
	$state->{'phone_type'} = $type;
	$state->{'sim_state'} = $sim;
	$state->{'network_type'} = $info->{'network_type'} || '';
	$state->{'telephony'} = (($type ne '' && $type ne 'none') && $sim eq 'ready') ? 1 : 0;
	return $state;
}

# A peer's radio, asked before an MMS is handed over: a laptop with a phone and
# a wifi tablet must not send the picture to the tablet and call it a phone.
sub peer_telephony($ru) {
	return undef unless $ru && $ru->{'ua'} && $ru->{'manager'};
	my $tx = eval { $ru->{'ua'}->inactivity_timeout(10)->get($ru->{'manager'} . '/manager/telephony') };
	return undef unless $tx && !$tx->error && $tx->res->is_success;
	my $info = eval { return decode_json $tx->res->body };
	return (ref $info eq 'HASH') ? $info : undef;
}

get '/manager/telephony' => sub($c) {
	$c->render(json => { ok => 1, %{ &telephony_status() } });
};

# The app's FileProvider is rooted at getFilesDir() (/data/user/0/...), while
# subs::home() and TermuxConstants say /data/data/.... Hand the bridge the
# provider's own spelling so getUriForFile finds the file; a path outside that
# root is what made the share() hand-off fail.
sub bridge_path($path) {
	my $data = $ENV{'TERMUX_APP__DATA_DIR'};
	return $path unless $data && $path =~ m{^/data/data/[^/]+/files(?:/|$)};
	$path =~ s{^/data/data/[^/]+/files}{$data/files};
	return $path;
}

# MMS carriers are happiest below about a megabyte; an original photo can be
# several. A copy is shrunk to fit (and auto-oriented), leaving the filed
# original alone. No ImageMagick, or a failure, keeps the original for the
# bridge's own Bitmap compression to handle.
sub mms_part_prepare($path, $mime) {
	return ($path, $mime) unless $path && -e $path;
	return ($path, $mime) unless ($mime || '') =~ m{^image/}i;
	my $size = -s $path || 0;
	return ($path, $mime) if $size <= 0 || $size <= (320 * 1024);
	my $dir = &subs::home('~/.shots/sms_parts');
	`mkdir -p "$dir"` unless -e $dir;
	my $out = $dir . '/' . &subs::random_string_creator(8) . '-mms.jpg';
	my $rc = system('magick', $path, '-auto-orient', '-strip', '-resize', '1280x960>', '-quality', '82', $out);
	return (($rc == 0 && -e $out && (-s $out) > 0) ? ($out, 'image/jpeg') : ($path, $mime));
}

sub sms_message_send($digits,$message) {
	$digits =~ s/\S\d(?=\d{10})//;
	my $via = 'relay';
	if (&subs::device_setter() eq 'mobile') {
		if ( $digits ) {
			# the app's own bridge sends it natively (SmsManager): the page calls
			# window.JawnSms.send, or falls back to termux-sms-send while the app
			# that carries the bridge has not landed. No page open: termux, since
			# there is no WebView to bridge through.
			my $tabs = &subs::db_query("select browser_tab_id from websockets where app = ?", 'tab')->hashes;
			if (scalar @{$tabs} > 0) {
				&Websocket::send('tab', { console => &sms_send_command($digits, $message) });
				$via = 'bridge';
			}
			else {
				$message =~ s/\$/\\\$/gi;
				`termux-sms-send -n $digits "$message"`;
				$via = 'termux';
			}
		}
	}
	else {
		&subs::subprocessor(sub {
	    Mojo::IOLoop->reset;

			my $remote_machines = &subs::db_query('select * from remote_machines where connection=? and device=?', 'active', 'mobile')->hashes;
			foreach my $rm ( @{$remote_machines} ) {
				$rm = &remote_useragent_maker({ ip => $rm->{'ip'}, signatorial => $rm->{'signatorial'}, rm => $rm });
				my $wire = $message;
				utf8::encode($wire) if utf8::is_utf8($wire);
				my $res = $rm->{'ua'}->post($rm->{'manager'} . '/manager/sms/message?digits=' . $digits . '&message=' . uri_encode($wire));
				if (eval {decode_json $res}) {
					next;
				}
			}
		}, { name => 'sms msg send' });
	}
	return ($digits,$message,$via);
}

# The page's fallback when the app that carries the JawnSms bridge has not
# landed yet: the phone's own termux sends it the old way, so a message still
# goes out during the hand-over. Retires with termux-sms-send itself.
post '/manager/sms/termux_fallback' => sub($c) {
	my $digits = $c->param('digits') || '';
	my $message = $c->param('message') || '';
	$digits =~ s/\S\d(?=\d{10})//;
	if ($digits) {
		$message =~ s/\$/\\\$/gi;
		`termux-sms-send -n $digits "$message"`;
	}
	$c->render(json => { ok => 1, via => 'termux' });
};

# The bridge's answer (window.__jawnSmsResult posts here): the send is logged,
# so a message that failed is visible in the log even when the UI is not. A
# saved MMS row also leaves its id for the mms route's short wait, and updates
# the house row if this machine already holds it (same uuid, now linked).
post '/manager/sms/result' => sub($c) {
	my $ok = $c->param('ok');
	my $error = $c->param('error') || '';
	my $via = $c->param('via') || 'sms';
	my $id = $c->param('id') || '';
	my $mms_id = $c->param('mms_id') || 0;
	my $mms_date = $c->param('mms_date') || 0;
	my $mms_thread = $c->param('mms_thread') || 0;
	my $jawn_uuid = $c->param('jawn_uuid') || '';
	$log->info('sms bridge result: ok=' . ($ok || '?') . ' via=' . $via . ' id=' . $id . ' mms_id=' . $mms_id . ' mms_date=' . $mms_date . ' error=' . $error);
	# Only the mms bridge's own answer is the mms outcome. The page also reports
	# the hand-over itself ('mms_command', an immediate ok) and the plain text's
	# own send ('sms'); either would overwrite the real answer before the mms
	# route reads it, leaving the house row unlinked while the picture sits in
	# the system thread with no house row pointing at it.
	if ($jawn_uuid && $via ne 'mms_command' && $via ne 'sms') {
		my $result_file = &subs::home('~/.shots/sms_mms_result_' . $jawn_uuid . '.json');
		&write_file($result_file, encode_json({ ok => $ok, via => $via, mms_id => $mms_id, mms_date => $mms_date, mms_thread => $mms_thread, error => $error, server_time => &subs::rightNow() }));
		my $row = &subs::db_select('mailbox', undef, { uuid => $jawn_uuid })->hashes->[0];
		if ($row && $mms_id) {
			&subs::db_update('mailbox', &sms_mms_row_link($mms_id, $mms_date), { uuid => $jawn_uuid });
		}
	}
	$c->render(json => { received => 1 });
};

# A message with attachments on the sms road rides an MMS. The parts arrive as
# base64 (the sending machine may be any device in the house); they are written
# where the app can read them (the house's own termux home, same UID) and the
# page is handed the paths - window.JawnSms.mms sends them, or share() hands the
# OS messaging app the first when JawnOS is not the default sms app.
post '/manager/sms/mms' => sub($c) {
	my $jawn_uuid = $c->param('jawn_uuid') || '';
	my $digits = $c->param('digits') || '';
	my $subject = $c->param('subject') || '';
	my $parts = eval { return decode_json $c->param('parts') } || [];
	# a wifi-only tablet is a 'mobile' device in the house, but it has no radio to
	# carry an MMS; answer so a relay can fall through to the phone
	if (&subs::device_setter() eq 'mobile' && !&telephony_status()->{'telephony'}) {
		$c->render(json => { ok => 0, error => 'no telephony on this device', parts => 0 });
		return;
	}
	$digits =~ s/\D+//g;
	$digits =~ s/^1//;
	my @local;
	foreach my $p ( @{$parts} ) {
		my $data = $p->{'data'} || '';
		next unless $data;
		my $name = $p->{'name'} || 'part';
		$name =~ s{[^A-Za-z0-9._-]}{_}g;
		my $mime = $p->{'mime'} || 'image/jpeg';
		my $dir = &subs::home('~/.shots/sms_parts');
		`mkdir -p $dir` unless -e $dir;
		my $file = $dir . '/' . &subs::random_string_creator(8) . '-' . $name;
		my $bytes = decode_base64($data);
		&write_file($file, $bytes);
		push @local, { path => &bridge_path($file), mime => $mime };
	}
	my $tabs = &subs::db_query("select browser_tab_id from websockets where app = ?", 'tab')->hashes;
	if (scalar @local == 0) {
		$c->render(json => { ok => 0, error => 'no parts', parts => 0 });
	}
	elsif (scalar @{$tabs} > 0) {
		&Websocket::send('tab', { console => &sms_mms_command($digits, $subject, \@local, $jawn_uuid) });
		# The page posts the saved MMS row's id back to /manager/sms/result. Wait
		# briefly so the sender can link that system message to the house row.
		my ($mms_id, $mms_date, $mms_thread) = (0, 0, 0);
		if ($jawn_uuid) {
			my $result_file = &subs::home('~/.shots/sms_mms_result_' . $jawn_uuid . '.json');
			for my $try ( 1 .. 25 ) {
				if (-e $result_file) {
					my $answer = eval { decode_json(scalar &read_file($result_file)) };
					if ($answer && $answer->{'mms_id'}) {
						$mms_id = $answer->{'mms_id'};
						$mms_date = $answer->{'mms_date'} || 0;
						$mms_thread = $answer->{'mms_thread'} || 0;
					}
					unlink $result_file;
					last;
				}
				select(undef, undef, undef, 0.2);
			}
		}
		$c->render(json => { ok => 1, via => 'bridge', parts => scalar @local, mms_id => $mms_id, mms_date => $mms_date, mms_thread => $mms_thread });
	}
	else {
		$c->render(json => { ok => 0, error => 'no app page open for mms', parts => scalar @local });
	}
};

# The house encrypts files at rest, renaming them to random .enc paths; an
# attachment carried on a message names its file by uuid, so the current paths
# are read from the filing the upload made, not from the snapshot the page sent.
# Returns (f, thumb, encryption_standard) - f is the current path, possibly .enc.
sub attachment_resolve($att) {
	my $fu = $att->{'uuid'} || '';
	my $f = $att->{'f'} || '';
	return ($f, $att->{'thumb'}, undef) if $f && -e $f;
	return (undef, undef, undef) unless $fu;
	my $row = &subs::db_query('select * from appointments where file like ? limit 1', '%' . $fu . '%')->hashes->[0];
	return (undef, undef, undef) unless $row;
	my $files = eval { return decode_json $row->{'file'} } || [];
	$files = [ $files ] if eval { $files->{'f'} };
	my ($entry) = grep { ($_->{'uuid'} || '') eq $fu } @{$files};
	return (undef, undef, undef) unless $entry;
	return ($entry->{'f'}, $entry->{'thumb'}, $row->{'encryption_standard'});
}

# An attachment's file as plain bytes on disk: encrypted at rest, so a copy is
# decrypted to the house's sms_parts drawer and that path is returned.
sub attachment_plain_path($att) {
	my ($f, undef, $standard) = &attachment_resolve($att);
	return undef unless $f && -e $f;
	return $f unless $f =~ /\.enc$/;
	my $dir = &subs::home('~/.shots/sms_parts');
	`mkdir -p $dir` unless -e $dir;
	my $name = $att->{'name'} || 'part';
	$name =~ s{[^A-Za-z0-9._-]}{_}g;
	my $plain = $dir . '/' . &subs::random_string_creator(8) . '-' . $name;
	$standard ||= &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard' }) || 'aes-256-ctr';
	my $secret = &subs::suds_grabber();
	&subs::openssl_file_crypt('d', $standard, $secret, $f, $plain, 0, 1);
	return (-e $plain) ? $plain : undef;
}

# An attachment on the sms road: on the phone the parts are already local files
# the bridge reads; anywhere else they are read, base64'd and relayed to the
# phone's /manager/sms/mms. A phone is found by asking its radio, not by taking
# the first mobile peer (the house may also hold a wifi-only tablet).

# The house row a message was filed as before it touched the sms stack wears
# the system's own identity once the phone has filed the same message: the
# system thread keeps the sent copy, and this row IS that message here, so the
# poll, a re-read and every other machine see one message rather than two. The
# system's date also becomes the row's time, so a poll matches it exactly.
sub sms_mms_row_link($mms_id, $mms_date) {
	my %set = (message_id => 'mms:' . $mms_id, server_time => &subs::rightNow());
	$set{'timestamp'} = $mms_date * 1000 if $mms_date && $mms_date =~ /^\d+$/;
	return \%set;
}

sub sms_mms_relay($digits, $text, $attachments, $jawn_uuid) {
	my $parts = [];
	foreach my $att ( @{$attachments || []} ) {
		my $f = &attachment_plain_path($att);
		my $mime = $att->{'mime'} || $att->{'type'} || 'image/jpeg';
		next unless $f;
		($f, $mime) = &mms_part_prepare($f, $mime);
		if (&subs::device_setter() eq 'mobile') {
			push @{$parts}, { path => &bridge_path($f), mime => $mime };
		}
		else {
			next unless -e $f;
			my $size = -s $f;
			next if $size <= 0 || $size > (8 * 1024 * 1024);
			open my $fh, '<', $f or next;
			binmode $fh;
			local $/;
			my $bytes = <$fh>;
			close $fh;
			my ($name) = $f =~ m{([^/]+)$};
			push @{$parts}, { name => $name || 'part', mime => $mime, data => encode_base64($bytes) };
		}
	}
	return { ok => 0, error => 'no parts' } unless scalar @{$parts} > 0;
	if (&subs::device_setter() eq 'mobile') {
		# a wifi tablet can read a picture but has no radio to carry it
		return { ok => 0, error => 'this device has no telephony' } unless &telephony_status()->{'telephony'};
		my $tabs = &subs::db_query("select browser_tab_id from websockets where app = ?", 'tab')->hashes;
		return { ok => 0, error => 'no app page open' } unless scalar @{$tabs} > 0;
		&Websocket::send('tab', { console => &sms_mms_command($digits, $text, $parts, $jawn_uuid) });
		return { ok => 1, via => 'bridge' };
	}
	my $remote_machines = &subs::db_query('select * from remote_machines where connection=? and device=?', 'active', 'mobile')->hashes;
	# confirmed radios first; a peer that will not answer the check stays a
	# candidate rather than silently disabling a working phone on an old build
	my ( @phones, @unknown );
	foreach my $rm ( @{$remote_machines} ) {
		my $ru = eval { &remote_useragent_maker({ ip => $rm->{'ip'}, signatorial => $rm->{'signatorial'}, rm => $rm }) };
		next unless $ru && $ru->{'ua'} && $ru->{'manager'};
		my $tel = &peer_telephony($ru);
		if ($tel && defined $tel->{'telephony'}) {
			push @phones, [ $rm, $ru ] if $tel->{'telephony'};
		}
		else {
			push @unknown, [ $rm, $ru ];
		}
	}
	my $last = 'no phone reached';
	foreach my $pair ( @phones, @unknown ) {
		my ($rm, $ru) = @{$pair};
		# parentheses matter here: `parts => encode_json $parts, jawn_uuid => ...`
		# hands the uuid to encode_json as another argument, so the relay quietly
		# sent no jawn_uuid and the house row never learned its system id
		my %form = ( digits => $digits, subject => $text, parts => encode_json($parts), jawn_uuid => $jawn_uuid );
		my $tx = eval { $ru->{'ua'}->inactivity_timeout(30)->post($ru->{'manager'} . '/manager/sms/mms', form => \%form) };
		if (!$tx) { $last = 'no answer'; next; }
		if ($tx->error) { $last = $tx->error->{'message'} || 'no answer'; next; }
		my $answer = eval { return decode_json $tx->res->body };
		if ($answer && $answer->{'ok'}) {
			return { ok => 1, via => 'relay', phone => ($rm->{'hostname'} || $rm->{'name'} || $rm->{'ip'}), parts => ($answer->{'parts'} || 0), mms_id => ($answer->{'mms_id'} || 0), mms_date => ($answer->{'mms_date'} || 0), mms_thread => ($answer->{'mms_thread'} || 0) };
		}
		$last = (ref $answer eq 'HASH' && $answer->{'error'}) ? $answer->{'error'} : ('HTTP ' . $tx->res->code);
	}
	return { ok => 0, error => $last };
};

# ---------------------------------------------------------------------------
# LoRaWAN: the Chat app's radio mode.
#
# The T-Deck carries an SX1262 and RadioLib's LoRaWANNode; JawnOS keeps the
# network credentials, pushes them to the deck that is on the LAN, and offers a
# webhook a network server (TTN, ChirpStack, Helium) can post uplinks to. The
# message itself is filed on the `lora` contact, the same way sms is filed on a
# number and a ticket on its uuid, so the conversation survives a restart.
# ---------------------------------------------------------------------------

sub lorawan_settings {
	my %s;
	foreach my $k (qw/enabled band subband join_eui dev_eui app_key fport confirmed webhook_token/) {
		my $v = &subs::setting_grabber({ app => 'mail', setting => 'lorawan_' . $k, device => 'all' });
		$s{$k} = defined $v ? $v : '';
	}
	$s{'band'} = 'EU433' unless length $s{'band'};
	$s{'subband'} = 1 unless $s{'subband'} =~ /^\d+$/ && $s{'subband'} >= 1 && $s{'subband'} <= 8;
	$s{'fport'} = 1 unless $s{'fport'} =~ /^\d+$/ && $s{'fport'} >= 1 && $s{'fport'} <= 223;
	$s{'enabled'} = 'off' unless $s{'enabled'} eq 'on';
	$s{'confirmed'} = 'off' unless $s{'confirmed'} eq 'on';
	unless (length $s{'webhook_token'}) {
		$s{'webhook_token'} = &subs::random_string_creator(40);
		&subs::setting_setter({ app => 'mail', setting => 'lorawan_webhook_token', value => $s{'webhook_token'}, device => 'all' });
	}
	return \%s;
}

sub lorawan_public_settings($c) {
	my $s = &lorawan_settings();
	my $webhook = '';
	if ($c) {
		$webhook = eval { $c->url_for('/watch/lorawan')->query(token => $s->{'webhook_token'})->to_abs->to_string } || '';
	}
	return {
		enabled => $s->{'enabled'},
		band => $s->{'band'},
		subband => $s->{'subband'},
		join_eui => $s->{'join_eui'},
		dev_eui => $s->{'dev_eui'},
		fport => $s->{'fport'},
		confirmed => $s->{'confirmed'},
		has_app_key => (length $s->{'app_key'} ? 1 : 0),
		webhook_url => $webhook,
	};
}

# The T-Deck's HTTP server uses the same port the embedded fleet already knows.
sub lorawan_devices {
	my $list = &subs::device_lister(&subs::rightNow(), 'teletype', undef, 'all');
	my @rows = eval { @{$list} };
	my ( @out, %seen );
	foreach my $d (@rows) {
		next unless ref $d eq 'HASH' && $d->{'ip'} && !$seen{ $d->{'ip'} }++;
		my $caps = $d->{'capabilities'} || $d->{'caps'} || '';
		$caps = encode_json($caps) if ref $caps;
		next unless (($d->{'purpose'} || '') eq 'teletype' || $caps =~ /lora/i);
		push @out, {
			name => $d->{'name'} || $d->{'computer_name'} || $d->{'chip_id'} || $d->{'ip'},
			ip => $d->{'ip'},
			chip_id => $d->{'chip_id'},
		};
	}
	return \@out;
}

sub lorawan_secret($c) {
	my $od = &subs::setting_grabber({ app => 'watch', setting => 'operator_door' });
	my $op = eval { decode_json $od } || {};
	my $patience = $op->{'__shutup'}->{'patience'};
	my $suds = eval { &subs::session_suds($c) };
	return 'manager' unless $patience && $suds;
	my $secret = &subs::note_encrypter($patience, $suds);
	$secret =~ s/\s+//g;
	return MIME::Base64::encode_base64($secret, '');
}

sub lorawan_deck_call($path, $form) {
	my $decks = &lorawan_devices();
	return { ok => 0, error => 'No LoRa-capable T-Deck is online.' } unless scalar @{$decks};
	my @results;
	foreach my $d ( @{$decks} ) {
		my $url = 'http://' . $d->{'ip'} . ':' . ($config->{'port'} || 80) . $path;
		my $ua = Mojo::UserAgent->new(connect_timeout => 2, inactivity_timeout => 60, request_timeout => 65);
		my $tx = eval { $ua->post($url => form => $form) };
		my $res = ( $tx && !$tx->error ) ? eval { decode_json($tx->res->body) } : undef;
		if ( $tx && !$tx->error && $tx->res->is_success && ref $res eq 'HASH' ) {
			push @results, { device => $d->{'name'}, ip => $d->{'ip'}, ok => 1, result => $res };
		}
		else {
			my $why = ( $tx && $tx->error ) ? ( $tx->error->{'message'} || 'no answer' ) : 'no answer';
			push @results, { device => $d->{'name'}, ip => $d->{'ip'}, ok => 0, error => $why };
		}
	}
	my ($good) = grep { $_->{'ok'} } @results;
	return $good if $good;
	return { ok => 0, error => 'No T-Deck answered.', devices => \@results };
}

sub lorawan_push_config($c) {
	my $s = &lorawan_settings();
	return &lorawan_deck_call('/lorawan_config', {
		s => &lorawan_secret($c),
		enabled => $s->{'enabled'},
		band => $s->{'band'},
		subband => $s->{'subband'},
		join_eui => $s->{'join_eui'},
		dev_eui => $s->{'dev_eui'},
		app_key => $s->{'app_key'},
		fport => $s->{'fport'},
		confirmed => $s->{'confirmed'},
	});
}

sub lorawan_send_text($text) {
	my $s = &lorawan_settings();
	return { ok => 0, error => 'LoRaWAN is not enabled.' } unless $s->{'enabled'} eq 'on';
	return { ok => 0, error => 'There is nothing to send.' } unless defined $text && length $text;
	return &lorawan_deck_call('/lorawan_send', {
		s => 'manager',
		message => $text,
		confirmed => $s->{'confirmed'},
	});
}

sub lorawan_webhook_text($body) {
	my $text = '';
	if ( ref $body->{'uplink_message'} eq 'HASH' ) {
		my $up = $body->{'uplink_message'};
		if ( ref $up->{'decoded_payload'} eq 'HASH' ) {
			$text = $up->{'decoded_payload'}->{'text'} || $up->{'decoded_payload'}->{'message'} || $up->{'decoded_payload'}->{'msg'} || '';
		}
		if ( !length $text && $up->{'frm_payload'} ) {
			my $bytes = eval { decode_base64($up->{'frm_payload'}) };
			if ( defined $bytes && length $bytes ) {
				my $decoded = eval { decode_json($bytes) };
				if ( ref $decoded eq 'HASH' ) {
					$text = $decoded->{'text'} || $decoded->{'message'} || $decoded->{'msg'} || '';
				}
				else {
					$text = $bytes;
				}
			}
		}
	}
	$text ||= $body->{'text'} || $body->{'message'} || $body->{'msg'} || $body->{'payload'} || '';
	if ( ref $text ) {
		$text = $text->{'text'} || $text->{'message'} || '' if ref $text eq 'HASH';
	}
	$text = "$text";
	$text =~ s/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]+//g;
	$text =~ s/^\s+|\s+$//g;
	return $text;
}

get '/manager/lorawan/settings' => sub($c) {
	my $s = &lorawan_public_settings($c);
	$s->{'devices'} = &lorawan_devices();
	$c->render(json => { ok => 1, %{$s} });
};

post '/manager/lorawan/settings' => sub($c) {
	my %allowed = map { $_ => 1 } qw/EU433 EU868 US915 AU915 AS923 AS923_2 AS923_3 AS923_4 KR920 IN865 CN470/;
	my $band = $c->param('band') // 'EU433';
	return $c->render(json => { ok => 0, error => 'unknown LoRaWAN band' }) unless $allowed{$band};
	my $hex = sub {
		my ($v, $len) = @_;
		$v = defined $v ? uc $v : '';
		$v =~ s/[^0-9A-F]//g;
		return ( length($v) == $len ) ? $v : undef;
	};
	my $join = $hex->($c->param('join_eui'), 16);
	my $dev = $hex->($c->param('dev_eui'), 16);
	return $c->render(json => { ok => 0, error => 'Join EUI must be 16 hex characters' }) unless $join;
	return $c->render(json => { ok => 0, error => 'Dev EUI must be 16 hex characters' }) unless $dev;
	my $key = $c->param('app_key') // '';
	if ( length $key ) {
		$key = $hex->($key, 32);
		return $c->render(json => { ok => 0, error => 'App key must be 32 hex characters' }) unless $key;
	}
	my $subband = int($c->param('subband') // 1);
	$subband = 1 if $subband < 1 || $subband > 8;
	my $fport = int($c->param('fport') // 1);
	$fport = 1 if $fport < 1 || $fport > 223;
	my %set = (
		enabled => ($c->param('enabled') ? 'on' : 'off'),
		band => $band,
		subband => $subband,
		join_eui => $join,
		dev_eui => $dev,
		fport => $fport,
		confirmed => ($c->param('confirmed') ? 'on' : 'off'),
	);
	$set{'app_key'} = $key if length $key;
	foreach my $k ( keys %set ) {
		&subs::setting_setter({ app => 'mail', setting => 'lorawan_' . $k, value => $set{$k}, device => 'all' });
	}
	my $push = &lorawan_push_config($c);
	$c->render(json => { ok => 1, push => $push, settings => &lorawan_public_settings($c) });
};

post '/manager/lorawan/join' => sub($c) {
	my $res = &lorawan_deck_call('/lorawan_join', { s => &lorawan_secret($c) });
	$c->render(json => $res);
};

post '/manager/lorawan/send' => sub($c) {
	my $text = $c->param('message') // '';
	$c->render(json => &lorawan_send_text($text));
};

get '/manager/lorawan/status' => sub($c) {
	my $res = &lorawan_deck_call('/lorawan_status', { s => 'manager' });
	$c->render(json => $res);
};

# The network server's uplink webhook. It has no browser session, so the task
# token in the query is the gate; hooks.pl lets this one path through for that
# reason. TTN v3 (uplink_message.decoded_payload), TTN v2 (payload_fields) and a
# plain JSON {text:...} body are all accepted.
any '/watch/lorawan' => sub($c) {
	my $s = &lorawan_settings();
	my $token = $c->param('token') // '';
	unless ( length($s->{'webhook_token'}) && &secure_compare($token, $s->{'webhook_token'}) ) {
		return $c->render(status => 403, json => { ok => 0, error => 'bad token' });
	}
	my $body = eval { $c->req->json } || {};
	$body = {} unless ref $body eq 'HASH';
	foreach my $k (qw/text message msg payload/) {
		$body->{$k} = $c->param($k) if !defined $body->{$k} && defined $c->param($k);
	}
	my $text = &lorawan_webhook_text($body);
	return $c->render(json => { ok => 0, error => 'nothing to file' }) unless length $text;
	my $from = 'LoRa';
	if ( ref $body->{'end_device_ids'} eq 'HASH' && $body->{'end_device_ids'}->{'device_id'} ) {
		$from = $body->{'end_device_ids'}->{'device_id'};
	}
	elsif ( $body->{'dev_id'} ) { $from = $body->{'dev_id'}; }
	elsif ( $body->{'device'} && !ref $body->{'device'} ) { $from = $body->{'device'}; }
	$from = 'LoRa' if ref $from;
	my $uuid = &subs::random_string_creator(25);
	my $row = {
		uuid => $uuid,
		timestamp => &subs::rightNow(),
		server_time => &subs::rightNow(),
		body => $text,
		manager_file => $from,
		status => 'public',
		contact => 'lora',
	};
	&subs::db_insert('mailbox', $row);
	&subs::mail_arrival({ c => $c, %{$row} });
	$c->render(json => { ok => 1, uuid => $uuid });
};

post '/manager/sms/message' => sub($c) {
	my $digits = $c->param('digits');
	my $message = $c->param('message');

	my $sms = &sms_message_send($digits,$message);

	$c->render(json => $sms);

};

get '/manager/configure/sms_list_check' => sub ($c) {
	my $returner = &subs::sms_list_check();
	$c->render(text => $returner);
};

post '/manager/delete_app' => sub($c) {
	my $app = $c->param('app');
	my $uuid = $c->param('uuid');
	my $timestamp = $c->param('timestamp');
	my $type = $c->param('type');
	my $server_time = $c->param('server_time');
	&subs::subprocessor(sub {
    Mojo::IOLoop->reset;
		&remote_relay_request($c, { dissemination => 'yes' });
	}, { name => 'delete app remote relay' });
	my $deleter = &delete_app($app,$uuid,$server_time,'manual delete');
	&padlock_time_extender($c);

	my $cv = &centre_view_grabber({ c => $c, app => &subs::unformat_name($app), timestamp => $timestamp, cached => 'no' });
	$c->render(json => { centre_view => $cv, deleter => $deleter });

};

sub delete_app($app,$uuid,$server_time,$reason) {
	# The rows are fetched before the websocket send, not after it: send dials the
	# database, and the kept handle finishes whatever statement was left unfetched
	# on its way past, so a result read after it comes back empty. Fetched late,
	# this sub only ever removed the appointment from the page, never the table.
	my $appts = &subs::db_select('appointments', undef, { uuid => $uuid, app => $app })->hashes;
	&Websocket::send($app, { console => '$(\'appointment_detail[app="' . $app . '"][uuid="' . $uuid . '"]\').remove();'});
	my $status = '';
	if (scalar @{$appts} > 0) {

		# a transaction that paid an invoice left a payment on the invoice's
		# data; deleting the transaction takes the payment back out with it,
		# or the invoice stays paid by a row that no longer exists
		foreach my $app ( @{$appts} ) {
			&invoice_payment_deleter($app->{'uuid'});
		}

		foreach my $app ( @{$appts} ) {
			&subs::db_update('appointments', { status => 'deleting' }, { uuid => $app->{'uuid'}, app => $app->{'app'} });
			$status = $app->{'type'};
			&subs::db_delete('continent', { app => $app->{'app'}, uuid => $app->{'uuid'} });
			&subs::db_query('delete from continent where app = ? and uuid like ?', $app->{'app'}, $app->{'uuid'} . '%' );

			if ($app->{'file'} && $app->{'source'} ne 'music' && $app->{'account'} ne 'gallery' && $app->{'type'} ne 'view' && $app->{'type'} ne 'listen') {
				my $filings = eval { return decode_json $app->{'file'} } || [];
				foreach my $f (@{$filings}) {
					my $filing = $f->{'f'};
					&delete_file({ app => $app->{'app'}, app_uuid => $uuid, file_uuid => $f->{'uuid'}, reason => 'delete_app' });
					if ($f->{'mail_uuid'}) {
						$log->info('got the mail_uuid ' . $f->{'mail_uuid'});

						&subs::db_delete('mailbox', { uuid => $f->{'mail_uuid'} });
						&Websocket::send('tab', { console => '$(\'.mailbox_message[uuid="' . $f->{'mail_uuid'} . '"]\').remove();' });
					#	&subs::deletion_registration({ table => 'mailbox', uuid => $f->{'mail_uuid'}, scope => 'single', server_time => $f->{'server_time'} });
					}
				}
			}
			&subs::db_delete('appointments', { uuid => $app->{'uuid'} });
			# a deleted row takes its warehouse rows with it - the money move, the
			# balance anchor, and the stock movement it recorded (each is keyed to the
			# source uuid, so nothing else is touched)
			&subs::db_query('delete from warehouse where kind = ? and uuid = ?', 'money', $app->{'uuid'});
			&subs::db_query("delete from warehouse where kind = 'inventory' and app_uuid = ?", $app->{'uuid'});
			&subs::db_query("delete from warehouse where kind = 'stock' and app_uuid = ?", $app->{'uuid'});
		}

		&embedded_app_deleter({ appt_uuid => $uuid });
		my $sources = &subs::db_select('appointments', undef, { source_uuid => $uuid })->hashes;
		my %so_seen;
		foreach my $so ( @{$sources} ) {
			next if $so_seen{ $so->{'uuid'} }++;
			&embedded_app_deleter({ appt_uuid => $so->{'uuid'} });
			&delete_app($so->{'app'},$so->{'uuid'},$so->{'server_time'},'source deletion');
		}
		&Websocket::send('tab', { console => '$(\'.appointment_detail[app="' . $app . '"][uuid="' . $uuid . '"]\').remove();'});
		&deletion_registration({ table => 'appointments', app => $app, uuid => $uuid, scope => 'single', server_time => $server_time });
		&subs::vacuum($app);
		&subs::log_writer('deletion ' . $app . ' '  . $reason);

		&budget_runner($app);
		&centre_view_grabber({ c => &subs::controller_builder(), app => $app, timestamp => &subs::rightNow(), cached => 'no' });
	}
	return { appts => $appts, status => $status };
}

sub invoice_payment_deleter($uuid) {
	# called when an appointment is deleted: if it was the transaction a
	# payment on an invoice points at, the payment is unwound - removed from
	# the invoice's payments and its amount put back on the balance, and a
	# document marked completed reopens
	my $invoices = &subs::db_query("select * from appointments where type = ? and data like ?", 'invoice', '%' . $uuid . '%')->hashes;
	foreach my $inv ( @{$invoices} ) {
		my $data = eval { return decode_json $inv->{'data'} } || {};
		my $payments = $data->{'payments'} || [];
		my @kept = grep { ($_->{'appt_uuid'} || '') ne $uuid } @{$payments};
		next if scalar @kept == scalar @{$payments};
		my $reversed = 0;
		foreach my $p ( @{$payments} ) {
			$reversed += $p->{'amount'} if ($p->{'appt_uuid'} || '') eq $uuid && defined $p->{'amount'};
		}
		$data->{'payments'} = \@kept;
		$data->{'numbers'}->{'balance'} = ($data->{'numbers'}->{'balance'} || 0) + $reversed;
		my $inv_status = $inv->{'status'};
		$inv_status = 'open' if $inv_status eq 'completed' && $data->{'numbers'}->{'balance'} > 0;
		# encode_json is a list operator: without its own parentheses it eats the
		# rest of the hash, so status and server_time were never sent and the
		# balance was restored without the document reopening.
		&subs::db_update('appointments', { data => encode_json($data), status => $inv_status, server_time => &subs::rightNow() }, { app => $inv->{'app'}, uuid => $inv->{'uuid'} });
		$log->info('payment of ' . $reversed . ' reversed on ' . $inv->{'app'} . ' ' . $inv->{'uuid'} . ' (deleted ' . $uuid . ')');
		&Websocket::send('server', { console => 'appointmentDetailGrabber(\'' . $inv->{'app'} . '\',\'' . $inv->{'uuid'} .'\');' });
	}
}

sub is_folder_empty {
	my $dirname = shift;
	opendir(my $dh, $dirname);# or die "Not a directory";
	return scalar(grep { $_ ne "." && $_ ne ".." } readdir($dh)) == 0;
}

sub delete_file($data) {
	my $file_uuid = $data->{'file_uuid'};
	return unless $data->{'file_uuid'};
	my $app_uuid = $data->{'app_uuid'};
	my $app = $data->{'app'};

	my $appt = &subs::db_select('appointments', undef, { app => $app, uuid => $app_uuid })->hashes->[0];
	my $files = eval { return decode_json $appt->{'file'} } || [];
	my $removed = 0;
	foreach my $file ( grep { $_->{'uuid'} eq $file_uuid } @{$files} ) {
		$removed++;
		my $filing = $file->{'f'};
		my $thumb = $file->{'thumb'};
		if ($file->{'att'}) {
			my $att_file = &subs::db_select($file->{'att'}, undef, { uuid => $file->{'att_uuid'}, app => $appt->{'app'} })->hashes->[0];

			my $atf = eval { return decode_json $att_file->{'file'} } || [];
			@{$atf} = grep { $_->{'uuid'} ne $file->{'uuid'} } @{$atf};

			my $jaf = encode_json $atf;
			&subs::db_update($file->{'att'}, { file => $jaf, server_time => &subs::rightNow() }, { uuid => $att_file->{'uuid'}, app => $att_file->{'app'} });
		}

		if ($file->{'function'} eq 'signatorial') {
			my $signatorials = eval { return decode_json &subs::setting_grabber({ app => 'customs', setting => 'signatorials' }) } || [];
			@{$signatorials} = grep { $_->{'uuid'} ne $file->{'uuid'} } @{$signatorials};
			my $jsignatorials = encode_json $signatorials;
			&subs::setting_setter({ app => 'customs', setting => 'signatorials', value => $jsignatorials });
		}
		elsif ($file->{'function'} eq 'receipt') {
			my $receipts = eval { return decode_json &subs::setting_grabber({ app => 'budget', setting => 'receipts' }) } || [];
			@{$receipts} = grep { $_->{'uuid'} ne $file->{'uuid'} } @{$receipts};
			my $jreceipts = encode_json $receipts;
			&subs::setting_setter({ app => 'budget', setting => 'receipts', value => $jreceipts });
		}
		elsif ($file->{'function'} eq 'map') {
			my $maps = eval { return decode_json &subs::setting_grabber({ app => 'travel', setting => 'maps' }) } || [];
			@{$maps} = grep { $_->{'uuid'} ne $file->{'uuid'} } @{$maps};
			my $jmaps = encode_json $maps;
			&subs::setting_setter({ app => 'travel', setting => 'maps', value => $jmaps });
		}
		elsif ($file->{'function'} eq 'diagram') {
			my $diagrams = eval { return decode_json &subs::setting_grabber({ app => 'handbook', setting => 'diagrams' }) } || [];
			@{$diagrams} = grep { $_->{'uuid'} ne $file->{'uuid'} } @{$diagrams};
			my $jdiagrams = encode_json $diagrams;
			&subs::setting_setter({ app => 'handbook', setting => 'diagrams', value => $jdiagrams });
		}
		elsif ($file->{'function'} eq 'background') {
			my $backgrounds = eval { return decode_json &subs::setting_grabber({ app => 'marker', setting => 'backgrounds' }) } || [];
			@{$backgrounds} = grep { $_->{'uuid'} ne $file->{'uuid'} } @{$backgrounds};
			my $jbackgrounds = encode_json $backgrounds;
			&subs::setting_setter({ app => 'marker', setting => 'background', value => $jbackgrounds });
		}

		if ($thumb && -e $thumb) {
			`shred -u $thumb`;
			my @folder = split '/', $thumb;
			pop @folder;
			my $folder = join '/', @folder;
			if (&is_folder_empty($folder)) {
				rmdir( $folder );
			}
		}

		if (-e $filing) {
			my $file = $filing;
			`shred -u $file`;
			my @folder = split '/', $file;
			pop @folder;
			my $folder = join '/', @folder;

			my $thumb_folder = $folder . '/.thumbs';
			if (-e $thumb_folder) {
				if (&is_folder_empty($thumb_folder)) {
					rmdir( $thumb_folder );
				}
			}

			if (&is_folder_empty($folder)) {
				rmdir( $folder );
			}
		}
	}
	# A repeated deletion (a peer echoing the tombstone back, a late click) is a
	# no-op. Without this it wrote a fresh tombstone and a websocket update every
	# time the same uuid arrived, so the durable log grew on every sync pass.
	return unless $removed;
	@{$files} = grep { $_->{'uuid'} ne $file_uuid } @{$files};
	my $jfiles = encode_json $files;
	if (scalar @{$files} == 0 && $data->{'reason'} ne 'delete_app' && grep { $appt->{'type'} eq $_ } qw/image video scan/) {
		&delete_app($app,$app_uuid,$appt->{'server_time'},'file deletion');
	}
	&subs::db_update('appointments', { server_time => &subs::rightNow(), file => $jfiles }, { app => $app, uuid => $app_uuid });
	&Websocket::send('tab', { console => 'appointmentDetailGrabber(\'' . $app . '\',\'' . $app_uuid .'\');'});
	&deletion_registration({ table => 'appointments', app => $app, uuid => $app_uuid, file_uuid => $file_uuid, scope => 'file', server_time => $appt->{'server_time'} });
}

post '/manager/delete_file' => sub($c) {
	my $app = &subs::unformat_name($c->param('app'));
	my $file_uuid = $c->param('file_uuid');
	my $app_uuid = $c->param('app_uuid');
	&delete_file({ app => $app, file_uuid => $file_uuid, app_uuid => $app_uuid });

	$c->render(json => { app => $app, file_uuid => $file_uuid, app_uuid => $app_uuid });
};

sub deletion_registration($data) {
	# Record one durable tombstone. It stays in sync_log until every remote
	# machine has confirmed reading past it, so an offline machine still learns
	# of the deletion whenever it next connects.
	my $additional = $data->{'additional'};
	# A file deletion must name the file it removes: a peer applies it by uuid,
	# and without one the tombstone reached the other machines and did nothing.
	$additional = encode_json({ file_uuid => $data->{'file_uuid'} }) if !$additional && $data->{'file_uuid'};
	&subs::tombstone_writer({
		table => $data->{'table'}, app => $data->{'app'},
		uuid => $data->{'uuid'}, scope => $data->{'scope'},
		additional => $additional,
	});
	my $app = $data->{'app'};
	my $uuid = $data->{'uuid'};
	my $scope = $data->{'scope'};
	my $table = $data->{'table'};
	my $server_time = $data->{'server_time'};
	my $remote_machines = &subs::db_select('remote_machines')->hashes;
	foreach my $rm ( @{$remote_machines} ) {
		my $deletions = eval { return decode_json $rm->{'deletions'} } || [];
		push @{$deletions}, { table => $table, app => $app, uuid => $uuid, scope => $scope, initialization => &subs::rightNow(), server_time => $server_time, additional => $additional };
		my $del = encode_json $deletions;
		&subs::db_update('remote_machines', { deletions => $del }, { uuid => $rm->{'uuid'}, signatorial => $rm->{'signatorial'} });
	}
}

sub deletion_performer($json) {
	my $deletions = eval { return decode_json $json } || [];
	my $returner = [];
	if (scalar @{$deletions} == 0) { return []; }
	foreach my $deletion ( @{$deletions} ) {
		if ($deletion->{'table'} eq 'appointments') {
			if ($deletion->{'scope'} eq 'single') {
				&delete_app($deletion->{'app'},$deletion->{'uuid'},$deletion->{'server_time'},'deletion performer single');
			}
			elsif ( $deletion->{'scope'} eq 'vacuum' ) {
				&subs::vacuum_app($deletion->{'app'});
			}
			elsif ( $deletion->{'scope'} eq 'file' ) {
				my $extra = eval { return decode_json $deletion->{'additional'} } || {};
				my $file_uuid = $deletion->{'file_uuid'} || $extra->{'file_uuid'};
				&delete_file({ app => $deletion->{'app'}, app_uuid => $deletion->{'uuid'}, file_uuid => $file_uuid }) if defined $file_uuid && length $file_uuid;
			}
		}
	#	elsif ($deletion->{'table'} eq 'settings') {
	#		if ($deletion->{'subsetting'}) {
	#			&subs::setting_deleter({ app => $deletion->{'app'}, setting => $deletion->{'setting'}, subsetting => $deletion->{'subsetting'} });
	#		}
	#		else {
	#			&subs::setting_deleter({ app => $deletion->{'app'}, setting => $deletion->{'setting'} });
	#		}
	#	}
		else {
			&subs::db_delete($deletion->{'table'}, { uuid => $deletion->{'uuid'} });
		}
		push @{$returner}, $deletion;
	}
	return $returner;
}

