post '/manager/calculate' => sub($c) {
	my $formula = $c->param('formula');
	if ($formula =~ /=/gi) {
		my @formulas = split '=', $formula;
		$formula = $formulas[-1];
	}
	my ($evaluation,$uom,$format);
	($formula,$evaluation,$uom,$format) = &formula_calculator($formula);

	$c->render(json => { format => $format, formula => $formula, evaluation => $evaluation, uom => $uom });
};

# The keyboard's conversion row: a quantity typed as "$32.31", "5jpy" or
# "32.33L" names its unit, and every other unit of the same kind is offered
# beside it. The old calculator's formulas are the non-currency source; the
# live rate snapshot is the currency source.
get '/manager/keyboard/convert' => sub($c) {
	my $value = $c->param('value');
	$value =~ s/[^0-9.\-]//g if defined $value;
	return $c->render(json => { ok => 0 }) unless defined $value && $value =~ /^-?(?:\d+(?:\.\d+)?|\.\d+)$/;
	$c->render(json => &measure_conversion_rows($c->param('unit'), 0 + $value));
};

# Is a measure code a currency (a fiat code, a coin, or a crypto asset)?
sub currency_unit($unit) {
	return 0 unless defined $unit && length $unit;
	return 1 if &subs::crypto_asset($unit);
	return 1 if &subs::crypto_fiat($unit);
	my $m = $gb::measures->{$unit} || $gb::measures->{uc $unit} || $gb::measures->{lc $unit};
	return 0 unless $m && ref $m->{'types'} eq 'ARRAY';
	return scalar( grep { $_ eq 'currency' } @{$m->{'types'}} ) ? 1 : 0;
}

sub formula_calculator($formula) {
	my @formula = split / /, $formula;
	my ($evaluation,$uom,$format);
	my $formulas = [];
	if ($formula =~ /[a-zA-Z]/) {
		for (my $n = 0; $n <= scalar @formula; $n++ ) {
			if ($formula[$n] eq 'to') {
				my $pre = $formula[$n - 1];
				my $pre_unit = $pre;
				my $pre_number = $pre;
				$pre_number =~ s/[A-Za-z]//gi;
				$pre_unit =~ s/[0-9.-]//gi;
				# "5 USD to CAD" puts the number one token earlier; the compact
				# "5USD to CAD" is the usual form, but read the spaced one too.
				if ($pre_number eq '' && $n >= 2 && $formula[$n - 2] =~ /^\d/) {
					$pre_number = $formula[$n - 2];
				}

				my $post = $formula[$n + 1];
				my $post_number = $post;
				my $post_unit = $post;

				$post_number =~ s/[A-Za-z]//gi;
				$post_unit =~ s/[0-9.-]//gi;

				my $post_measure = $gb::measures->{$post_unit};
				unless ($post_measure) {
					foreach my $pu ( ( lc $post_unit, uc $post_unit ) ) {
						$post_measure = $gb::measures->{$pu};
						if ($post_measure->{'name'}) { last; }
					}
				}



				# A currency pair is a live rate now (Configure -> Plat -> Crypto
				# refreshes the snapshot every half hour). gb.pl's constants are the
				# offline fallback while no snapshot exists yet.
				if (&currency_unit($pre_unit) && &currency_unit($post_unit)) {
					my $rate = &subs::exchange_rate($pre_unit, $post_unit);
					if (defined $rate) {
						my $n = $pre_number;
						$n = 1 if $n eq '' || $n eq '-' || $n eq '+';
						$evaluation = $n * $rate;
						$uom = $post_unit;
						$format = $post_measure ? ($post_measure->{'format'} || '0.00') : '0.00';
						push @{$formulas}, $n . ' * ' . $rate . $post_unit;
					}
				}
				unless (defined $evaluation) {
				foreach my $for ( @{$gb::measures->{$pre_unit}->{'formulas'}} ) {
					if ($for =~ /\Q$post_unit/gi) {
						$for =~ s/x/\Q$pre_number/gi;
						$for =~ s/\Q$post_unit//gi;
						$for =~ s/\\//gi;

						push @{$formulas}, $for;
						$evaluation = eval  $for;
						last if $post_unit eq $post;
						if ($gb::measures->{$post_unit}->{'format'}) {
							$format = $gb::measures->{$post_unit}->{'format'};
						}
						else {
							$format = '0.000';
						}
						$uom = $post_unit;
					}
				}
				}

#				foreach my $for ( @{$gb::measures->{$post_unit}->{'formulas'}} ) {
#					if ($for =~ /\Q$pre_unit/gi) {
#						$for =~ s/x/\Q$pre_number/gi;
#						$for =~ s/\Q$pre_unit//gi;
#						$for =~ s/\\//gi;
#						push @{$formulas}, $for;
#						$evaluation = eval { $for };
#						if ($gb::measures->{$post_unit}->{'format'}) {
#							$format = $gb::measures->{$post_unit}->{'format'};
#						}
#						else {
#							$format = '0.000';
#						}
#						$uom = $post_unit;
#					}
#				}
			}
		}
	}
	else {
		$evaluation = eval $formula;
	}
	return ($formula,$evaluation,$uom,$format);
}

# ---- the keyboard's units of conversion -----------------------------------
# A unit resolved from whatever a person typed: the registry key ("JPY", "L",
# "m"), the same code in another case, the unit's own name, or its plural.
sub measure_unit_resolve($raw, $units) {
	return (undef, undef) unless defined $raw;
	$raw =~ s/^\s+|\s+$//g;
	return (undef, undef) unless length $raw;
	$raw = &subs::crypto_report_currency() if $raw eq '$';
	$units ||= &measures_all();
	foreach my $t ( $raw, uc $raw, lc $raw ) {
		return ($t, $units->{$t}) if ref $units->{$t} eq 'HASH';
	}
	my $low = lc $raw;
	foreach my $k ( keys %{$units} ) {
		my $def = $units->{$k};
		next unless ref $def eq 'HASH';
		foreach my $n ( $def->{'name'}, $def->{'plural'} ) {
			next unless defined $n && length $n;
			return ($k, $def) if lc($n) eq $low;
		}
	}
	return (undef, undef) unless length $low > 3 && $low =~ /s$/;
	return &measure_unit_resolve(substr($low, 0, -1), $units);
}

# The old calculator's formulas are directed ("x * 1000mL" says one litre is a
# thousand millilitres), so the graph carries each edge and its reciprocal and a
# short walk reaches any unit of the same kind (Litre -> mL -> teaspoon).
sub measure_conversion_edges($units) {
	my %edge;
	foreach my $from ( keys %{$units} ) {
		my $fs = $units->{$from}->{'formulas'};
		next unless ref $fs eq 'ARRAY';
		foreach my $f ( @{$fs} ) {
			next unless defined $f;
			next unless $f =~ /^\s*x\s*\*\s*([0-9]*\.?[0-9]+)\s*([A-Za-z\/]+)\s*$/i;
			my ($factor, $target) = ($1 + 0, $2);
			next unless $factor > 0;
			my ($to) = &measure_unit_resolve($target, $units);
			next unless defined $to && length $to;
			$edge{$from}->{$to} = $factor unless defined $edge{$from}->{$to};
		}
	}
	return \%edge;
}

# units of $to per one $from, walked over the formula graph
sub measure_conversion_factor($edges, $from, $to) {
	return undef unless defined $from && defined $to;
	return 1 if $from eq $to;
	my %seen = ( $from => 1 );
	my @queue = ( [ $from, 1 ] );
	my $walked = 0;
	while ( scalar @queue && $walked++ < 400 ) {
		my ($u, $factor) = @{ shift @queue };
		my %next;
		foreach my $v ( keys %{ $edges->{$u} || {} } ) { $next{$v} = $edges->{$u}->{$v}; }
		foreach my $v ( keys %{$edges} ) {
			my $back = $edges->{$v}->{$u};
			next unless defined $back && $back > 0;
			$next{$v} = 1 / $back unless defined $next{$v};
		}
		foreach my $v ( keys %next ) {
			next if $seen{$v}++;
			my $f = $factor * $next{$v};
			return $f if $v eq $to;
			push @queue, [ $v, $f ];
		}
	}
	return undef;
}

sub measure_temperature_convert($from, $to, $value) {
	return $value if $from eq $to;
	return $value * 9 / 5 + 32 if $from eq 'C' && $to eq 'F';
	return ($value - 32) * 5 / 9 if $from eq 'F' && $to eq 'C';
	return undef;
}

sub measure_value_text($value, $unit, $currency) {
	my $abs = abs($value);
	my $dec = $abs >= 1 ? 2 : ($abs >= 0.01 ? 4 : 8);
	my $text = sprintf("%.${dec}f", $value);
	if ($currency) {
		if ($dec > 2) { $text =~ s/0+$//; $text =~ s/\.$//; }
	}
	else {
		$text =~ s/0+$// if $text =~ /\.\d/;
		$text =~ s/\.$//;
	}
	return $text . ' ' . $unit;
}

sub measure_unit_name($key, $def) {
	my $asset = &subs::crypto_asset($key);
	return $asset->{'name'} if $asset && $asset->{'name'};
	foreach my $f ( @{ &subs::crypto_fiat_table() } ) {
		return $f->{'name'} if $f->{'code'} eq uc $key;
	}
	my $name = ref $def eq 'HASH' ? ($def->{'name'} || '') : '';
	return length $name ? $name : $key;
}

# The live snapshot gives every fiat pair and every coin in one read: a code's
# rate is the reporting currency per one unit, so the pair is the ratio of the
# two. While no snapshot exists yet, the old calculator's static formulas answer.
sub measure_currency_conversions($key, $value, $units) {
	my $snap = &subs::crypto_rates_read();
	my $table = $snap->{'rates'} || {};
	my $from = $table->{uc $key};
	my @order = ( &subs::crypto_report_currency(), qw/USD EUR GBP JPY CNY AUD CHF MXN INR BRL/,
		( @{ &subs::crypto_enabled_assets() } ),
		( map { $_->{'code'} } @{ &subs::crypto_fiat_table() } ),
		( map { $_->{'code'} } @{ &subs::crypto_assets() } ) );
	my (@codes, %seen);
	foreach my $c ( @order ) {
		next unless defined $c && length $c;
		my $code = uc $c;
		next if $seen{$code}++;
		push @codes, $code;
	}
	my ($edges, @rows);
	foreach my $to ( @codes ) {
		next if $to eq uc $key;
		my $rate;
		if ( defined $from && $from > 0 && defined $table->{$to} && $table->{$to} > 0 ) {
			$rate = $from / $table->{$to};
		}
		else {
			$edges ||= &measure_conversion_edges($units);
			$rate = &measure_conversion_factor($edges, $key, $to);
		}
		next unless defined $rate && $rate > 0 && $rate < 1e15;
		my $v = $value * $rate;
		push @rows, { unit => $to, name => &measure_unit_name($to, $units->{$to}), value => 0 + $v, text => &measure_value_text($v, $to, 1) };
		last if scalar @rows >= 30;
	}
	return \@rows;
}

sub measure_unit_conversions($key, $def, $value, $units) {
	my %type = map { $_ => 1 } @{ $def->{'types'} || [] };
	my @order = qw/mm cm m km in ft mi mL L tsp tbsp cup pint gal oz g mg kg lb C F/;
	my %pref;
	my $i = 0;
	$pref{$_} = $i++ for @order;
	my @targets = grep {
		$_ ne $key && ref $units->{$_} eq 'HASH'
			&& !&currency_unit($_)
			&& grep { $type{$_} } @{ $units->{$_}->{'types'} || [] }
	} keys %{$units};
	@targets = sort { ($pref{$a} // 999) <=> ($pref{$b} // 999) || $a cmp $b } @targets;
	my $edges = &measure_conversion_edges($units);
	my $temp = $type{'temperature'} ? 1 : 0;
	my @rows;
	foreach my $to ( @targets ) {
		my $v;
		if ($temp) { $v = &measure_temperature_convert($key, $to, $value); }
		else {
			my $factor = &measure_conversion_factor($edges, $key, $to);
			$v = $value * $factor if defined $factor;
		}
		next unless defined $v && $v == $v && abs($v) < 1e15;
		push @rows, { unit => $to, name => &measure_unit_name($to, $units->{$to}), value => 0 + $v, text => &measure_value_text($v, $to, 0) };
	}
	return \@rows;
}

sub measure_conversion_rows($unit, $value) {
	my $units = &measures_all();
	my ($key, $def) = &measure_unit_resolve($unit, $units);
	if (!defined $key) {
		# a coin or a fiat code is not in the units registry, but the snapshot
		# knows both
		my $asset = &subs::crypto_asset(uc($unit || ''));
		if ($asset) {
			$key = uc $asset->{'code'};
			$def = { name => $asset->{'name'}, types => [ 'currency' ], symbol => $asset->{'symbol'} || '' };
		}
		else {
			my $fiat = &subs::crypto_fiat(uc($unit || ''));
			if ($fiat) {
				$key = uc $fiat->{'code'};
				$def = { name => $fiat->{'name'}, types => [ 'currency' ] };
			}
		}
	}
	return { ok => 0 } unless defined $key && ref $def eq 'HASH';
	$value = 0 unless defined $value && $value =~ /^-?\d/;
	my $rows = &currency_unit($key)
		? &measure_currency_conversions($key, $value, $units)
		: &measure_unit_conversions($key, $def, $value, $units);
	return { ok => 0, unit => $key } unless scalar @{$rows};
	return {
		ok => 1,
		unit => $key,
		name => &measure_unit_name($key, $def),
		value => 0 + $value,
		text => &measure_value_text($value, $key, &currency_unit($key)),
		rows => $rows,
	};
}


post '/manager/keyboard' => sub($c) {
	my $toggle = $c->param('toggle');
	my $remote_uuid = $c->param('remote_uuid');
	my $remote_control = &subs::setting_grabber({ app => 'me', setting => $toggle . '_machine' });
	# The picker's choice rides in this request and is the authority for this
	# render: the setting POST that saves it can land after us, and an explicit
	# empty pick (Me) must not fall back to the stored machine. Do not relay the
	# panel to the peer to fill its view: the panel already renders the local
	# pick, while a relayed copy shows that machine's own view ("ME!") and can
	# stall the render while it waits on an unreachable peer.
	my $picked = defined $remote_uuid ? $remote_uuid : $remote_control;
	my $kb = &keyboard_maker($c, $picked);

	$c->render(json => { keyboard => $kb });
};

sub keyboard_maker($c, $remote_pick) {
	my $timestamp = $c->param('timestamp');
	my $browser_tab_id = $c->param('browser_tab_id');
	my $remote_machines = $c->param('remote_machines');
	my $remote_control = defined $remote_pick ? $remote_pick : $c->param('remote_control');
	my $toggle = $c->param('toggle');
	my $accts = [];
	my $projs = [];
	my $accounts = &subs::db_query("select * from settings where (setting = ? or setting =?) and value=?",'pos', 'mab', 'account');
	my $acc = $accounts->hashes;
	my $keys = {};
	my $measures = clone $gb::measures;
	if ($toggle eq 'keyboard' || $toggle eq 'calculator') {
		foreach my $key (@{$gb::inputs}) {
			$keys->{$key->{'c'}} = &subs::random_string_creator();
		}
		foreach my $key (keys %{$measures}) {
			if ( $keys->{$key} ) {
				my $data = clone $measures->{$key};
				$key = '_' . $key;
				$measures->{$key} = $data;
			}
			$keys->{$key} = $key;
		}
		my $key_cutter = &subs::encrypter(&subs::session_suds($c), encode_json($keys));
		&subs::setting_setter({ app => 'keyboard', setting => $toggle, value => $key_cutter, timestamp => $timestamp, browser_tab_id => $browser_tab_id });
	}
	if ($toggle eq 'delorean') {
		foreach my $a ( reverse @{$acc} ) {
			push @{$accts},$a unless grep { $_->{'app'} eq $a->{'app'}} @{$accts};
			$a->{'formatted_name'} = &subs::format_name($a->{'app'});
		}
		my $projects = &subs::db_query("select * from settings where (setting = ? or setting = ?) and value=?",'pos', 'mab', 'project');
		my $proj = $projects->hashes;

		foreach my $a ( reverse @{$proj} ) {
			push @{$projs},$a unless grep { $_->{'app'} eq $a->{'app'}} @{$projs};
			$a->{'formatted_name'} = &subs::format_name($a->{'app'});
		}
	}

	my ($av_data);
	if ($c->param('avData') && $toggle eq 'walkboy') {
		$av_data = decode_json($c->param('avData'));

		foreach my $av (@{$av_data}) {
			if ($av->{'kind'} eq 'audioinput') {
				$av->{'icon'} = 'microphone';
			}
			elsif ($av->{'kind'} eq 'videoinput') {
				if ($av->{'label'} =~ /front/gi) {
					$av->{'icon'} = 'camera front';
				}
				else {
					$av->{'icon'} = 'camera back';
				}

			}
			elsif ($av->{'kind'} eq 'audiooutput') {
				$av->{'icon'} = 'speaker';
			}
		}
	}
	my $websockets;
	if ($toggle eq 'sessions' || $toggle eq 'controller') {
		my $web_query = &subs::db_query('select * from websockets where browser_tab_id = ?',$browser_tab_id);
		$websockets = $web_query->hashes;
	}
	my $notifications;
	if ($toggle eq 'notifications') {
		$notifications = &notification_grabber({});
	};
	my $config = &subs::config_reader();
	my $remote_connect = $gb::ws;
	my $kb = $c->render_to_string(
		browser_tab_id => $browser_tab_id,
		accounts => $accts,
		projects => $projs,
		template => 'keyboard',
		'keys' => $keys,
		toggle => $toggle,
		device => $device,
		av_data => $av_data,
		websockets => $websockets,
		notifications => $notifications,
		remote_machines => $remote_machines,
		remote_control => $remote_control,
		config => $config,
		manager_file => &manager_file_maker($c->session('name')),
		pseudonyms => &pseudonym_maker('viewer', ''),
		measures => $measures,
		ws => $gb::ws,
	);
	return $kb;
}

get '/manager/keyboard/config' => sub($c) {
	my $toggle = $c->param('toggle');
	my $remote_uuid = $c->param('remote_uuid');
	my $remoted = $c->param('remoted');
	my $returner = {};
	if ($remote_uuid && !$remoted) {
		$returner = &Manager::remote_relay_request($c);
		$returner = eval { return decode_json $returner } || {};
	}
	else {

		$returner->{'html'} = $c->render_to_string(
			template => 'keyboard_config',
			toggle => $toggle,
			remote_uuid => $remote_uuid
		);
	}
	$c->render(json => $returner);
};

sub manager_file_maker($session_name = '') {
	my ($my_name,$computer_name,$hostname,$hostnamer,$database_name);
	my ($db,$database) = &subs::database_grabber();
	$hostname = `hostname`;
	chomp $hostname;
	$hostnamer = eval { return &subs::db_select('devices', ['name'], { hostname => $hostname } )->hash->{name} };
	$my_name = $session_name || &subs::setting_grabber({ app => 'me', setting => 'my_name' });
	$computer_name = &subs::config_reader()->{'name'} || &subs::setting_grabber({ app => 'me', setting => 'computer_name' });
	$database_name = $database;
	$database_name =~ s/^database\///;
	$database_name =~ s/.db$//gi;
	my @database_name = split '/', $database_name;
	$database_name = $database_name[-1];

	return ($my_name || $hostnamer || $hostname) . '@' . $database_name . '.' . ($computer_name || $hostname);

};

get '/manager/keyboard_alias' => sub($c) {
	my $key = $c->param('key');
	my $toggle = $c->param('toggle');
	my $browser_tab_id = $c->param('browser_tab_id');
	my $value = &subs::db_select('settings', ['value','timestamp'], { app => 'keyboard', setting => $toggle, browser_tab_id => $browser_tab_id })->hash;
	my $key_cutter = &subs::decrypter(&subs::session_suds($c),$value->{'value'});
	$key_cutter = decode_json $key_cutter;
	foreach my $k (keys %{$key_cutter}) {
		if ($key_cutter->{$k} eq $key) {
			$key = $k;
		}
	}
	my $path = './public/icons/lettering/' . $key . '.png';
	if (! -e $path) {
		$path = './public/icons/lymeboard' . $key . '.png';
		if (! -e $path) {
			my @b = grep { $_->{'c'} eq $key } @{$gb::inputs};
			if ($b[0]->{'img'}) {
				$path = './public/icons/lymeboard/' . lc $b[0]->{'img'} . '.png';
			}
		}
	}
	my $paths = Mojo::File->new($path);
	$c->render_file('filepath' => $paths->to_string);
};

post '/manager/keyboard_presser' => sub($c) {

	my $key = $c->param('key');
	my $toggle = $c->param('toggle');
	my $shift = $c->param('shift');
	my $ctrl = $c->param('ctrl');
	my $cushion = $c->param('cushion');
	my $fn = $c->param('fn');
	my $timestamp = $c->param('timestamp');
	my $destination = $c->param('destination');
	my $browser_tab_id = $c->param('browser_tab_id');
	my $value = &subs::db_select('settings', ['value','timestamp'], { app => 'keyboard', setting => $toggle, browser_tab_id => $browser_tab_id })->hash;
	my $key_cutter = &subs::decrypter(&subs::session_suds($c),$value->{'value'});
	$key_cutter = decode_json $key_cutter;
	foreach my $k (keys %{$key_cutter}) {
		if ($key_cutter->{$k} eq $key) {
			$key = $k;
			$key = uc $key if $shift eq 'yes';
		}
	}
	if ($cushion) {
		$key = $cushion . $key . $cushion;
	}
	&Websocket::send('server', { key => $key, origin => $browser_tab_id, destination => $destination, toggle => $toggle, timestamp => $timestamp });
  $c->render(json => { key => $key });
};


get '/manager/say_it' => sub ($c) {
	my $timestamp = $c->param('timestamp');
	my $words = $c->param('words');
	my $voice = $c->param('voice');
	&subs::say_it($words, $voice);
	$c->render(text => 'said ' . $words);
	&Websocket::send('server', { json => { type => 'command', command => 'say_it', params => $words, timestamp => $timestamp } });
};



sub lock_screen($c) {
	if ($c) {
		my $authentication = $c->session('authentication');
		if (-e $database && $device eq 'mobile') {
		}
	}
}


sub unlock_screen($c) {
	my $authentication = $c->session('authentication');
	if (-e $database && $device eq 'mobile') {
		my $finger = `termux-fingerprint`;
		if (my $fingerprint = eval { return decode_json $finger }) {
			if ($fingerprint->{'auth_result'} eq 'AUTH_RESULT_SUCCESS') {
				$c->session('authentication' => 'approved');
			}
			else {
				$c->session('authentication' => 'rejected');
			}
		}
	}
}



sub notification_sender($m,$db) {
	my $origin = &subs::format_name(&subs::config_reader()->{'name'} || &subs::setting_grabber({ app => 'me', setting => 'computer_name' })) ||&subs::shorthand_name(`hostname`);

	my $message = $m->{'message'};
	my ($database,$sql);
	($db,$database,$sql) = &subs::database_grabber();
	my $app = &subs::unformat_name($m->{'app'} || '');
	$m->{'settings'} = &subs::settings_grabber({ app => $app, settings => [
		'start_notification_text', 'stop_notification_text', 'budget_notification_text', 'notification_text',
		'start_notification_sound', 'stop_notification_sound', 'budget_notification_sound', 'notification_sound'
	] }) unless $m->{'settings'};
	my $title = ($origin) . ': ' . $m->{'title'};

	$m->{'timestamp'} = &subs::rightNow();
	# the uuid has to exist before the live notification is rendered: the X button
	# carries it and the stored row is keyed by it, and they have to match. Callers
	# that do not supply one used to land here with uuid "", so the rendered X had
	# nothing to remove and the row could not be cleared
	$m->{'uuid'} ||= &subs::random_string_creator(20);
	my $sound = $m->{'sound'} || 'ding.mp3';
	my $sound_file = $m->{'settings'}->{$m->{'type'} . '_notification_sound'} || './public/sounds/notifications/' . $sound;
	my $words = $m->{'words'} || $m->{'message'} || $m->{'settings'}->{$m->{'type'} ? $m->{'type'} . '_notification_text' : 'notification_text'};
	if ($m->{'synth'}) {
		&subs::subprocessor(sub {
			&subs::run_command($m->{'synth'} . ' &');
			if ($m->{'words'}) {
				&subs::say_it($m->{'words'});
			}
		}, { name => "Audio file player" });
	}
	else {
		&subs::subprocessor(sub {
			if ($sound) {
				my $co = 'play -q ' . $sound_file;
				`$co`;
			}
			if ($words) {
				&subs::say_it($words);
			}
		}, { name => "Synth player" });
	}

	my $image;
	my $pwd = `pwd`;
	chomp $pwd;
	if ($m->{'image'}) {
		$image = $pwd . '/public' . $m->{'image'};
	}
	else {
		$image = &subs::setting_grabber({ app => &subs::unformat_name($m->{'title'}), setting => 'main_image' });
		unless (-e $image) {
			$image = $pwd . '/public/images/jonathans/logo red yellow.png';
		}
	}
	$image =~ s/ /\\ /gi;
	if ($device eq 'mobile') {
		my $id = &subs::random_string_creator();
		my $url = 'https://127.0.0.1:' . $ENV{PORT_AHOY} . '/manager?app=' . $m->{'app'} . '&timestamp=' . $m->{'timestamp'};
		# The app posts it (JawnNotifyReceiver), so the badge lands on the app's
		# own launcher icon; termux-notification belongs to the API app, which has
		# no icon to badge, so it is only the fallback when the app is absent.
		my ($t, $b) = ($title, $message);
		$t =~ s/"/'/g;
		$b =~ s/"/'/g;
		my $bc = `am broadcast -n com.termux/.app.JawnNotifyReceiver -a com.termux.app.JAWN_NOTIFY --es title "$t" --es message "$b" --es tag "$id" 2>&1`;
		unless ($bc =~ /Broadcast completed/) {
			`echo "$message" | termux-notification -i $id -t "$title" --vibrate "200,150,200,150" --image-path $image`;
		}
	}
	elsif ( eval { $sql->db } && $sql->dsn !~ /:$/) {

		my $c = &subs::controller_builder();
		my $content = $c->render_to_string(
			n => $m,
			template => 'notification',
		);
		if ($m->{'role'} ne '0') {
			&Websocket::send('server', {
				app => $m->{'app'},
				type => 'notification',
				title => $m->{'title'},
				role => $m->{'role'} || 'guest',
				message => $m->{'message'},
				icon => $m->{'image'},
				timestamp => $m->{'timestamp'},
				html => $content
			});
		}

	}
	foreach my $embedded (qw/ watch teletype /) {
		my $watch = &subs::device_lister($m->{'timestamp'},$embedded);
		if (eval {$watch->{'ip'}}) {

			my $ping = 'timeout .2 ping -c 1 ' . $watch->{'ip'};
			my $ping_test = `$ping`;
			if ($ping_test =~ /ttl/gi) {
				my $ua = Mojo::UserAgent->new();
				$ua->connect_timeout(1);
				my $watch_home = 'http://' . $watch->{'ip'} . ':' . $config->{'port'} . '/notification?title=' . $title .
					'&notification=' . $message . '&sound=/' . $sound . '&sound_file=' . $sound_file;
				&subs::subprocessor(sub {
					my $res = eval { return $ua->insecure(1)->get($watch_home)->result };
				}, { name => "Watch notification sender" });
			}
		}
	}
	if (eval { $sql->db } && $sql->dsn !~ /:$/) {
		my $db = $sql->db;

		&subs::db_insert('notifications', {
			app => $m->{'app'},
			role => $m->{'role'} || 3,
			title => $m->{'title'},
			image => $m->{'image'},
			message => $m->{'message'},
			timestamp => $m->{'timestamp'},
			uuid => $m->{'uuid'}
		});
	}

}

sub authentication_passer($c) {
	my $server_time = &subs::rightNow();

	# The app gate runs before the login gate: a browser must not be handed the
	# manager's login page or any private route at all. The public homepage,
	# store and the embedded devices' own token rail are allowed through.
	my $app_mode = &app_access_mode();
	if ($app_mode ne 'off') {
		&app_schema_ensure();
		my $app_path = $c->req->url->path->to_string;
		# The Gate is the front door for a person without an app key. A browser
		# that has not signed in must be able to see it, because the passkey is
		# the login that then admits the session (webauthn=1). An approved
		# session with no passkey is still refused, so the app-only rule holds.
		my $gate_only = ($app_path eq '/manager' && (($c->session('authentication') || '') ne 'approved')) ? 1 : 0;
		unless (&app_public_path($app_path) || &app_session_ok($c) || &app_peer_ok($c) || $c->session('webauthn') || $gate_only) {
			if ($app_mode eq 'enforce') {
				$c->render(template => 'app_required', layout => undef,
					device_uuid => ($c->session('device_uuid') || ''),
					signatorial => &subs::signatorial_designer());
				return;
			}
			$log->info('app gate shadow: would deny ' . $c->req->method . ' ' . $app_path . ' from ' . ($c->tx->remote_address || '?'));
		}
	}

	# A password-only login from off the machine is a bootstrap session: it may
	# pair a device, restore a backup or recover, but never open the manager.
	# This holds even when app_access is off, so the password cannot reopen the
	# door the app gate would otherwise leave open.
	if (($c->session('bootstrap') || '') eq '1'
		&& !&app_public_path($c->req->url->path->to_string)
		&& !&app_session_ok($c)
		&& !&app_peer_ok($c)) {
		$c->render(template => 'app_required', layout => undef,
			device_uuid => ($c->session('device_uuid') || ''),
			signatorial => &subs::signatorial_designer());
		return;
	}

	my $authentication = $c->session('authentication') || 'revoked';
	if ($c->session('authentication') eq 'denial' || $c->session('reject_count') > 3 || ($c->stash('no') && $c->stash('no') == 1)) {
		my $denial = $c->render(template => 'guest_layouts/denial', message => '... access denied.');
		$c->session('authentication' => 'denied');
		$authentication = 'denial';
		$c->rendered;
		return;
	}
	elsif ($authentication eq 'approved' && $c->session('server_time') > $server_time - 5100
		&& &subs::session_principal_active($c->session('person_uuid'), $c->session('device_uuid'))
		&& !&subs::db_select('security', undef, { level => 'padlock' })->hashes->[0]) {
		# The fast path may skip the full auth pass, but never the padlock:
		# every request refreshes session server_time, so a locked screen that
		# kept a request in flight every few seconds returned here forever and
		# was never gated ("I locked it and still have full access").
		$c->session('server_time' => $server_time);
		return $authentication;
	}

	$c->session('server_time' => $server_time);
	my $dob = $c->session('database');
	my $name = $c->param('name');
	my $warranty = $c->session('warranty');

	my $visitor = $c->tx->local_address eq $c->tx->remote_address ? 'Me' : ($c->param('manager_file') || $c->tx->remote_address);
	my $string = $c->tx->req->url->path->to_string;
	unless ($c->stash('browser_tab_id') && ($authentication eq 'approved' || $authentication eq 'revoked')) {
		# Not every retry deserves a Dingaling: a browser reconnecting after a
		# network change hammers this, so alert at most once per visitor per
		# few minutes. The cache row is the throttle stamp (local, unsynced).
		my ($db,$database) = &subs::database_grabber();
		my $now = &subs::rightNow();
		my $seen = $db ? &subs::db_query('select server_time from cache where context=? and uuid=? order by server_time desc limit 1', 'dingaling', $visitor)->hashes->[0] : undef;
		unless ($seen->{'server_time'} && $seen->{'server_time'} > $now - 300000) {
			if ($db) {
				&subs::db_query('delete from cache where context=? and uuid=?', 'dingaling', $visitor);
				&subs::db_query('insert into cache (uuid, context, app, server_time, timestamp) values (?,?,?,?,?)', $visitor, 'dingaling', '__president', $now, $now);
			}
			&notification_sender({ app => 'customs', role => 'citizen', type => 'authentication', title => 'Dingaling', message => $visitor . ' ' . $string, image => "/images/make believe/lock.png" },$dob);
		}
	}
	if (! -e $dob) {
		$authentication = "revoked";
	}
	else {
		my ($db,$database,$sql) = &subs::database_grabber();
		my $current_suds = eval { &subs::suds_grabber() };
		my $suds_id = $c->session('suds_id');
		unless ($current_suds && $suds_id && secure_compare($suds_id, &subs::suds_id($current_suds))) {
			$authentication = 'revoked';
		}
		# a device session lives only while its roster row does: revoking the
		# device revokes the cookie at the next check
		if (my $device_uuid = $c->session('device_uuid')) {
			my $device = &subs::db_select('paired_devices', undef, { uuid => $device_uuid, status => 'active' })->hashes->[0];
			unless ($device) { $authentication = 'revoked'; }
		}
		# and a person session lives only while the person does; a revoked
		# person's ticket or device session is refused here even if its cookie
		# still names a live warranty
		my $person_uuid = $c->session('person_uuid') || '';
		if ($person_uuid && !&subs::person_active($person_uuid)) { $authentication = 'revoked'; }
		my $pres_settings = &subs::settings_grabber({ app => '__president', settings => [ 'padlock_contexts', 'pl_time' ] });
		my $padlock_sightings = eval { return decode_json $pres_settings->{'padlock_contexts'} } || [];
		my $padlock = [];
		my $padlock_time = $server_time;
		if ( grep { $_ eq 'general' } @{$padlock_sightings} ) {
			$padlock = &subs::db_select('security', undef, { level => 'padlock' })->hashes;

			my $activity_timeout = &subs::setting_grabber({ app => 'me', setting => 'activity_timeout' }) || '-2h';
			$activity_timeout = &subs::time_abbrev_translator($activity_timeout);

			# A missing stamp means this machine has never been locked since the
			# gate was set - open, not an expired lock (the same rule
			# padlock_global_locked applies). Treating undef as 0 made every
			# request look expired and started a lock out of nothing.
			my $pl_raw = $pres_settings->{'pl_time'};
			$padlock_time = (defined $pl_raw && length $pl_raw)
				? (&padlock_time_value(&subs::suds_grabber(), $pl_raw) || 0)
				: $server_time;

			$c->stash('pl_time' => $padlock_time);
		}

		my $locked_now = 0;
		if ($c->session('authentication') eq 'approved' && scalar @{$padlock} > 0) {
			# the house-wide inactivity timer: only when the global stamp expired,
			# and not for a screen that was opened after a whole-house lock
			my $did_lock = 0;
			if ($server_time > $padlock_time) {
				my $dev = $c->session('device_uuid') || '';
				my $until = $dev ? &padlock_device_until($dev) : 0;
				# An unlocked screen has its own future stamp. A screen that is
				# already locked (no stamp, or a past one) must not run the lock
				# again: the whole-house branch re-stamps pl_time = now, so the
				# very next request saw it expired and closed the same windows
				# again - a table with no fingerprint, sitting on a manager
				# page, did exactly that on every poll. Answer the gate; do not
				# re-lock what is already locked.
				my $already = ($until && $until > $server_time) ? 1 : (&padlock_locked_now($c, $dev) ? 1 : 0);
				$did_lock = &lock_session($c) unless $already;
			}
			# The request that meets the expired timer is the one that locked:
			# gate it now. lock_session stamps pl_time = now, so re-checking the
			# clock a moment later could still read it as open and render the
			# page, with the lock overlay arriving after it had painted.
			$locked_now = $did_lock ? 1 : &padlock_locked_now($c);
			if ($locked_now) {
				my $gate_path = $c->req->url->path->to_string;
				if (!&padlock_gate_allows($gate_path)) {
					if (&padlock_gate_mode() eq 'enforce') {
						&padlock_gate_answer($c);
						return;
					}
					&padlock_gate_shadow($c);
				}
			}
		}
		if (!$locked_now && $c->session('source') eq 'ticket' && $c->session('authentication') eq 'approved') {
			my $tick = &subs::db_query('select * from tickets where uuid=?', $c->session('ticket_uuid') );
			my $ticket = $tick->hashes->[0];
			$c->stash('debriefer' => $ticket->{'debriefer'});
			if ($c->session('server_time') < $ticket->{'server_time'}) {
				# a legacy ticket may still carry the key; a retired one carries
				# nothing and the machine's vault is the key
				my $suds;
				if ($ticket->{'suds'}) {
					my $secretive = $ticket->{'secret'};
					my $ver = url_unescape `echo "$secretive" | base64 --decode`;
					my $ts = &subs::note_decrypter($ticket->{'password'},$ver);
					my $sj = decode_json $ts;
					$suds = &subs::note_decrypter($sj->{'p'}, $ticket->{'suds'});
					chomp $suds if $suds;
				}
				$suds ||= eval { &subs::suds_grabber() };
				&subs::vault_seed($suds) if $suds;
				$c->session('suds_id' => &subs::suds_id($suds)) if $suds;
				$c->session('server_time' => $server_time);
				$authentication = 'approved';
			}
			if ($ticket->{'warranty'} <= $server_time || $ticket->{'status'} ne 'active') {
				$authentication = 'revoked';
			}
			else {
				$c->session('warranty' => $ticket->{'warranty'});
			}

		}
		elsif ($c->session('warranty') < $server_time) {
			$authentication = 'revoked';
		}
	}
	unless ($authentication eq 'approved') {
		$c->session('authentication' => 'revoked');
		$c->session('bti', $c->stash('browser_tab_id'));
		my $restore_list = [];
		$c->session('database' => undef);
		$c->session('suds_id' => undef);
		unless (-e $database) {
			if ($c->param('restore_list')) {
				my $list = $c->param('restore_list');
				$restore_list = &subs::restore_list($list);
				@{$restore_list} = grep { $_->{'filename'} =~ /enc$/gi } @{$restore_list};
			}
		}
		# An XHR that meets the gate is answered JSON, not the Gate page: a stale
		# session cookie - the cookieless request a webview sends as it wakes - that
		# came back as HTML was parsed as data and froze the viewer (appts became
		# undefined, so the poll threw and the pan threw). A 401 lets the caller see it.
		if (($c->req->headers->header('X-Requested-With') // '') =~ /XMLHttpRequest/i) {
			$c->res->code(401);
			$c->render(json => { error => 'session lapsed', authentication => 'revoked' });
			$c->rendered;
			return;
		}
		if ($c->param('neighbour')) {
			$c->render(json => { name => $name, purpose => $device, 'restore_list' => $restore_list, signatorial => &subs::signatorial_designer() });
		}
		else {
			$c->render(
				template => 'gate',
				layout => 'gate',
				restore_list => $restore_list,
				webauthn_available => (scalar @{ &webauthn::credentials() } ? 1 : 0),
				# no home path on the gate: shown before anyone has signed in
				start_dir => '',
				config => { 'gate' => {'background_colour' => $config->{'gate'}->{'background_colour'} } },
			);
		}
	}
	return $authentication;
}

post '/manager/configure/password_update' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $server_time = &subs::rightNow();
	my ($db,$database,$sql) = &subs::database_grabber();
	$c->param('reason' => 'password_update');
	&subs::backup_now($c);
	my $numerics = &password_maker($c);
	if ($numerics eq 'noway') {
		$c->render(json => { result => 'ok' });
		$c->rendered;
		return;
	}
	# a password change re-keys only the door. The house key stays: the vault,
	# the canary and every sealed value are untouched, and the recovery code
	# keeps working. The old credential rows are normalised to the key so
	# note_decrypter's historical tries stay usable.
	my $K = &subs::session_suds($c);
	if ($K && &subs::door_set($numerics)) {
		my $cred_hunt = &subs::db_select('security', ['credential','level','server_time','timestamp'], { });
		my $creds = $cred_hunt->hashes;
		@{$creds} = grep { $_->{'level'} ne 'padlock' && $_->{'level'} ne 'door' && $_->{'level'} ne 1 } @{$creds};
		foreach my $cr ( @{$creds} ) {
			my $credjawntial = &subs::decrypter($K,$cr->{'credential'});
			next unless defined $credjawntial && length $credjawntial;
			my $newjawntial = &subs::encrypter($K,$credjawntial);
			next unless $newjawntial;
			&subs::db_update('security', { credential => $newjawntial }, { timestamp => $cr->{'timestamp'}, server_time => $cr->{'server_time'} });
		}
		$c->session('suds_id' => &subs::suds_id($K));
		&subs::db_delete('security', { level => 'padlock' });
		&subs::db_delete('settings', { app => '__president', setting => 'pl_time' });
		&subs::db_delete('settings', { app => '__president', setting => 'padlock_pulls' });
		$c->render(json => { result => 'ok' });
		&subs::say_it('Password has been updated');
	}
	else {
		&subs::say_it('no dice mister!');
		$c->render(json => { result => 'fail' });
	}
};



