	my $timestamp = $c->param('timestamp') || &subs::rightNow();
	$timestamp = &subs::ago_calc($ago,$timestamp);
	$c->render(text => $timestamp);
};

post '/manager/assistant' => sub($c) {
	my $image = $c->param('image');
	my $audio = $c->param('audio');
	my $id = $c->param('id');
	my $title = $c->param('title') || 'Assistant';
	my $uuid = &subs::random_string_creator(45);
	&subs::subprocessor(sub {
		if ($audio) {
	    $audio =~ s/^data:audio\/[a-zA-Z0-9]+;base64,//;

	    $audio =~ s/[^A-Za-z0-9\+\/\=]//g;

			$log->info(Dumper $audio);
			my $raw_wav = decode_base64 $audio;
			use IPC::Open3;
			use Symbol 'gensym';

			 my ($stdin, $stdout, $stderr);
				$stderr = gensym;

				# 1. Resolve your absolute home directory paths first so they pass smoothly into the shell string
				my $whisper_bin   = &subs::home('~/whisper.cpp/build/bin/whisper-cli');
				my $whisper_model = &subs::home('~/whisper.cpp/models/ggml-base.bin');

				my $pipeline_cmd = sprintf(
					'ffmpeg -loglevel error -i - -blocksize 4096 -f wav -ar 16000 -ac 1 -acodec pcm_s16le - | %s -m %s --output-txt --file -',
					$whisper_bin,
					$whisper_model
				);

				# 3. Spawn the execution bridge using shell evaluation
				my $pid = open3($stdin, $stdout, $stderr, 'sh', '-c', $pipeline_cmd);

				# 4. Stream your raw decoded payload directly into FFmpeg's standard input
				binmode($stdin);
				print $stdin $raw_wav;
		    $stdin->flush();

				close($stdin);

				# 5. Read the transcription text coming out of stdout
				my $transcription = '';
				my $temp_trans = '';
				while (my $line = <$stdout>) {
				  $transcription .= $line;
					$temp_trans = $transcription;
					$transcription =~ s/^\s+|\s+$//g;
					$transcription =~ s/\n/<br>/gi;
					$transcription =~ s/'/\\'/gi;
					&Websocket::send('tab', {
						console => '$(\'.assistant_content[uuid="' . $uuid . '"]\').html(\'' . $transcription . '\');'
					});
					$transcription = $temp_trans;
				}
				close($stdout);
        my $error_output = '';
        while (my $err_line = <$stderr>) {
            $error_output .= $err_line;
        }
        close($stderr);

        waitpid($pid, 0);

        if ($error_output) {
            $log->error("Pipeline Stderr Logs:\n" . $error_output);
        }

					# Clean up formatting whitespace
					$transcription =~ s/^\s+|\s+$//g;
					$log->info($transcription);
					$transcription =~ s/\n/<br>/gi;
					$transcription =~ s/'/\\'/gi;

					# 6. Return transcription back to your client application
#					return $c->render(json => { text => $transcription });




		} elsif ($image) {
			my $m = {
				system_msg => 'This is an image',
				msg => 'What do you see?',
				images => [ $image ],
				type => 'assistant',
				uuid => $uuid,
				mail_contact => 'assistant'
			};
			my ($response_text,$attachments) = &subs::pen_message($m);
		}
	}, { name => 'Assistant' });

	my $returner = {
		uuid => $uuid,
		id => $id,
		title => $title
	};
	$c->render(json => $returner);
};


websocket '/observer/ws' => sub ($c) {
	my $browser_tab_id = $c->param('browser_tab_id');
	$gb::paperboy->{$browser_tab_id} = $c->tx;
	$c->on(message => sub ($ows, $msg) {
		my $m = from_json $msg;
		if ($m->{'type'} eq 'heartbeat') {
			$ows->send($msg);
		}
		elsif ($m->{'type'} eq 'refresher') {
			my ($db,$database,$sql) = &subs::database_grabber();
			my $server_time = &subs::rightNow();
			my $q = &subs::db_query('select * from magazine where timestamp >= ? and timestamp <= ? and status=?', $m->{'last_paper_delivered'},$server_time,'publish');
			my $papers = $q->hashes;
			foreach my $p ( @{$papers} ) {
				# A hash under json is encoded once by Mojo; handing it the bytes
				# encode_json made would encode them a second time.
				$ows->send({ json => $p });
			}
		}
	});
	$c->on(close => sub ($ows, $msg) {
		$gb::paperboy->{$browser_tab_id} = undef;
	});
};

websocket '/mail/ws' => sub ($c) {
	my $me = &manager_file_maker($c->session('name'));
	my $browser_tab_id = $c->param('browser_tab_id');

	my $picker = eval { return decode_json $c->param('picker') } || {};
	# One entry per browser tab, carrying the address it is watching: a phone
	# number, an email address, a contact, a guest's ticket, or the social
	# construct tuple a dial or list tab picked. The old registry nested the
	# constructs as hash levels - people->projects->teams->clubs->communities -
	# which left a sender no way to tell one shape from another; the address
	# keeps that nest as plain data instead.
	$gb::mailws->{$browser_tab_id} = {
		tx => $c->tx,
		address => &mailws_address($c, $picker)
	};
	my $name = $c->session('name');
	$c->on(message => sub ($mws, $msg) {
		my $m = from_json $msg;
		$m->{'uuid'} = &subs::random_string_creator(35);

		if ($m->{'type'} eq 'heartbeat') {
			if ($c->session('privilege') eq 'citizen') {
				my ($db,$database,$sql) = &subs::database_grabber();
				&mail_depublicizer($c);
			}
			if ($c->session('privilege') eq 'guest') {
				# a tune is re-checked for as long as it is held: the house may
				# have taken the advertised dial back, and a guest then slides
				# home to their ticket rather than keeping the channel
				my $entry = $gb::mailws->{$browser_tab_id};
				if ($entry && $entry->{'address'}->{'picker'} && !&mail_public_channel_allows($entry->{'address'}->{'picker'})) {
					$entry->{'address'} = { ticket => $c->session('ticket_uuid') };
				}
			}
			if (scalar @{$m->{'decrypteds'}} > 0) {

				foreach my $d ( @{$m->{'decrypteds'}} ) {
					my $dm = &subs::db_query('select * from mailbox where uuid = ?', $d)->hashes->[0];
					$dm->{'body'} = &mail_text_chars(&subs::note_decrypter(&subs::session_suds($c),$dm->{'body'},$dm->{'ost'}));

					$dm->{'decrypted'} = 'yes';
					my $content = $c->render_to_string(
						template => 'mail/message',
						'm' => $dm,
						me => $me
					);
					&Websocket::send('mailbox', {  type => 'mailbox_message', selector => '.mailbox_message[uuid="' . $dm->{'uuid'} . '"]', content => $content, browser_tab_id => $c->param('browser_tab_id') });
				}
			}
			$mws->send($msg);
		}
		elsif ($m->{'type'} eq 'delete') {
			# only a trusted session may unsend: a visitor's browser can drop
			# what it is showing, but not the house's record of it
			if (&mailws_trusted($c) && $m->{'msg'}->{'uuid'}) {
				&subs::db_delete('mailbox', { uuid => $m->{'msg'}->{'uuid'} });
				my $message = &subs::db_select('mailbox', undef, { uuid => $m->{'msg'}->{'uuid'} })->hashes->[0];
				&deletion_registration({ table => 'mailbox', uuid => $message->{'uuid'}, scope => 'single', server_time => $message->{'server_time'} });
				&Websocket::send('tab', { console => '$(\'.email_message[uuid="' . $m->{'msg'}->{'uuid'} . '"]\').remove();$(\'.mailbox_message[uuid="' . $m->{'msg'}->{'uuid'} . '\').remove();' });
			}
		}
		elsif ($m->{'type'} eq 'message') {
			$m->{'decrypted'} = 'yes';
			foreach my $strip ( qw/msg manager_file/ ) {
				my $hs = HTML::Strip->new();
				$m->{$strip} = $hs->parse( $m->{$strip} );
				$hs->eof;
			}
			my $manager_file = &manager_file_maker($name);
			$m->{'manager_file'} = $manager_file;
			if ($c->session('privilege') eq 'guest') {
				# a guest may write to a dial the house advertises; any other
				# address falls back to the ticket - the one thread the house
				# opened for them. A guest speaks through the box, never through
				# a phone number, a mailbox server or the Pen.
				my $dialled = eval { return from_json $m->{'picker'} } || {};
				if (&mail_public_channel_allows($dialled)) {
					$m->{'picker'} = encode_json $dialled;
					$m->{'mail_contact'} = undef;
				}
				else {
					$m->{'mail_contact'} = $c->session('ticket_uuid');
					delete $m->{'picker'};
				}
				$m->{'phone'} = undef;
				$m->{'email'} = undef;
			}
			my $trusted = &mailws_trusted($c);
			# the one thread a guest was invited into - their ticket - is filed
			# like correspondence, while the rooms stay heard-not-kept (below)
			my $filed = $trusted || ($c->session('privilege') eq 'guest' && $m->{'mail_contact'} && $m->{'mail_contact'} eq $c->session('ticket_uuid'));
			if (!$trusted) {
				# a guest's words are not filed, so they are bounded: a length
				# cap and a per-ticket pace that a flood cannot pass
				$m->{'msg'} = substr($m->{'msg'} || '', 0, 4000);
				unless (&mailws_untrusted_throttle($c->session('ticket_uuid') || $browser_tab_id)) {
					$log->info('mail throttle: dropped a guest message on ' . ($browser_tab_id || '?'));
					return;
				}
			}
			$m->{'body'} = $m->{'msg'};
			$m->{'msg'} =~ s/\n/<br>/gi;
			my $e_msg = &subs::note_encrypter(&subs::suds_grabber(),$m->{'msg'});

			my $picker = eval { return from_json $m->{'picker'} } || {};
			# a phone is stored and read bare (digits only, no leading country
			# code), whatever road wore it - the reader strips the same way, so the
			# thread a message is filed on is the thread that reads it back
			if ($m->{'phone'}) {
				$m->{'phone'} =~ s/\D+//g;
				$m->{'phone'} =~ s/^1//;
			}
			# the social constructs are defaulted the way the mailbox reads them,
			# so a message sent from a tab with its pickers hidden still lands on
			# the thread the reader will open; a message addressed to a phone, an
			# email or a contact keeps its construct columns empty
			my $constructs = &mailws_constructs($picker);
			if ($m->{'mail_contact'} || $m->{'phone'} || $m->{'email'}) { $constructs = {}; }
			# the row's construct columns, named from the same registry the
			# reader queries with, so a new construct lands in its own column
			my %construct_columns;
			foreach my $k ( keys %{$gb::social_constructs} ) {
				$construct_columns{ $gb::social_constructs->{$k}->{'sing'} } = $constructs->{$k};
			}
			my ($db,$database,$sql) = &subs::database_grabber();
			# the house encrypts files at rest and renames them, so the paths the
			# page sent are stale by the time the message files: each attachment's
			# current paths are read from the upload's filing (by file uuid)
			my $m_attachments = undef;
			if (ref $m->{'attachments'} eq 'ARRAY' && scalar @{$m->{'attachments'}} > 0) {
				my @atts;
				foreach my $att ( @{$m->{'attachments'}} ) {
					my ($f, $thumb, undef) = &attachment_resolve($att);
					$att->{'f'} = $f if $f;
					$att->{'thumb'} = $thumb if $thumb;
					push @atts, $att;
				}
				$m_attachments = encode_json \@atts;
			}
			my $msg = {
				uuid => $m->{'uuid'},
				timestamp => $m->{'timestamp'},
				server_time => &subs::rightNow(),
				body => $e_msg,
				%construct_columns,
				manager_file => $m->{'manager_file'},
				status => 'sent',
				contact => $m->{'mail_contact'},
				phone => $m->{'phone'},
				email => $m->{'email'},
				conversation_uuid => $m->{'conversation_uuid'},
				attachments => $m_attachments
			};
			# filed words are stored; a visitor's room words are only ever heard
			# live by whoever is tuned in, so they are never written down
			&subs::db_insert('mailbox', $msg) if $filed;
			$m->{'ephemeral'} = 'yes' unless $filed;
			$m->{'envelope'} = $c->render_to_string(
				template => 'mail/message',
				'm' => $m,
				'me' => $me
			);
			# one sender carries the message to every address shape the registry
			# can hold: a phone number, an email address, a contact (a ticket or
			# the pen), a guest's ticket, or the nested social construct chain a
			# dial or list tab is watching
			&mailws_sender($m);
			if ($trusted && $m->{'phone'}) {
				# the phone wants the words, not the display copy: msg wears <br>
				# for the thread, body (set above, before that) is the raw text,
				# minus the trailing newline Enter left in the composer
				my $sms_msg = $m->{'body'} || $m->{'msg'};
				$sms_msg =~ s/\n+$//;
				# A picture is one message, not two: the words ride the mms as its
				# text part instead of also going out as a separate text (the
				# system thread showed a text bubble and a picture bubble for the
				# one thing the person sent).
				my $rides_mms = (ref $m->{'attachments'} eq 'ARRAY' && scalar @{$m->{'attachments'}} > 0);
				&sms_message_send($m->{'phone'}, $sms_msg) unless $rides_mms;
				if ($rides_mms) {
					my $mms = &sms_mms_relay($m->{'phone'}, $sms_msg, $m->{'attachments'}, $m->{'uuid'});
					$log->info('mms relay: ' . ($mms->{'via'} || $mms->{'error'} || '?'));
					if ($mms->{'mms_id'}) {
						&subs::db_update('mailbox', &sms_mms_row_link($mms->{'mms_id'}, $mms->{'mms_date'}), { uuid => $m->{'uuid'} });
						$log->info('mms system id ' . $mms->{'mms_id'} . ' linked to ' . $m->{'uuid'});
					}
				}
			}
			elsif ($trusted && ($m->{'transport'} // '') eq 'lora') {
				# the LoRaWAN uplink can take a few seconds (join, duty cycle, the
				# receive windows), so it leaves the socket's turn to a worker
				my $lora_msg = $m->{'body'} || $m->{'msg'} || '';
				$lora_msg =~ s/\n+$//;
				if (length $lora_msg) {
					&subs::subprocessor(sub {
						Mojo::IOLoop->reset;
						my $res = &lorawan_send_text($lora_msg);
						$log->info('lorawan send: ' . encode_json($res));
					}, { name => 'lorawan send' });
				}
			}
			if ($m->{'mail_contact'} && $m->{'mail_contact'} eq 'pen') {
				my $mesg = {
					uuid => &subs::random_string_creator(25),
					conversation_uuid => $m->{'conversation_uuid'},
					timestamp => &subs::rightNow(),
					server_time => &subs::rightNow(),
					manager_file => &subs::manager_file_maker('pen'),
					status => 'public',
					contact => 'pen'
				};
				&subs::db_query('delete from mailbox where contact = ? and conversation_uuid is null', 'pen');
				&subs::db_insert('mailbox', $mesg);
				&subs::subprocessor(sub {
					$m->{'msg_data'} = $mesg;
					$m->{'uuid'} = $mesg->{'uuid'};
					my ($response_text,$attachments) = &subs::pen_message($m);
					&subs::db_update('mailbox', {
						body => $response_text,
						status => 'public',
						server_time => &subs::rightNow(),
						attachments => encode_json $attachments
					}, { uuid => $mesg->{'uuid'} });
					# the envelope delivered now must wear the reply: the template reads
					# $mesg (not the row just written), so without this the live reply
					# is blank and only the depublicizer's later pass carries the text
					$mesg->{'body'} = $response_text;
					$mesg->{'decrypted'} = 'yes';
					$log->info(Dumper $mesg);
					my $returner = encode_json $mesg;
					print $returner;
					$mesg->{'envelope'} = $c->render_to_string(
						template => 'mail/message',
						'm' => $mesg,
						'me' => $me
					);
					$mesg->{'type'} = 'message';
					&Websocket::mail_send($mesg);

					&subs::db_query('delete from mailbox where contact = ? and conversation_uuid is null', 'pen');

				}, { name => 'Mail Assistant' });
				$mesg->{'envelope'} = $c->render_to_string(
					template => 'mail/message',
					'm' => $mesg,
					'me' => $me
				);
				$mesg->{'type'} = 'message';
				# the placeholder wears the pen's own contact address; the reply
				# comes back from the forked worker over the mail socket
				&mailws_sender($mesg);
			}
			elsif (!$m->{'phone'} && !$m->{'email'} && !$m->{'mail_contact'}) {
				my $mail_msg = {
					uuid => $m->{'uuid'},
					timestamp => $m->{'timestamp'},
					server_time => &subs::rightNow(),
					body => $m->{'msg'},
					%construct_columns,
					manager_file => $m->{'manager_file'},
					status => 'public',
					contact => $m->{'mail_contact'},
					phone => $m->{'phone'},
					email => $m->{'email'},
					# an unfiled letter travels the mesh marked ephemeral: the
					# machines that catch it deliver it live and keep nothing
					ephemeral => ($trusted ? undef : 'yes')
				};
				my $remote_machines = &subs::db_select('remote_machines', undef, { connection => 'active' })->hashes;
				my $form_data = {
					signatorial => &subs::signatorial_designer(),
					msg => encode_json $mail_msg
				};
				foreach my $rm ( @{$remote_machines} ) {
					&subs::subprocessor(sub {
				    Mojo::IOLoop->reset;

						$rm = &remote_useragent_maker({ ip => $rm->{'ip'}, signatorial => $rm->{'signatorial'}, rm => $rm });
						my $url = $rm->{'manager'} . '/mail/msg';
						my $res = $rm->{'ua'}->post($url => form => $form_data)->result;
						if ($res->is_success) {

						}
					}, { name => 'embedded mail msg' });
					if ($trusted && &subs::setting_grabber({ app => 'mail', setting => 'lora_toggle' }) eq 'on') {
						foreach my $device_type ( qw/watch teletype microcontroller/ ) {
							my $chips = &subs::device_lister(&subs::rightNow(), $device_type, undef, 'all');
							foreach my $watch ( @{$chips} ) {
								if (eval {$watch->{'ip'} }) {
									my $watch_port = $ENV{PORT_ARM};
									my $ws_port = $ENV{PORT_MSG};
									my $od = &subs::setting_grabber({ app => 'watch', setting => 'operator_door' });
									my $op_d = eval { decode_json $od } || {};
									my $secret = &subs::note_encrypter($op_d->{'__shutup'}->{'patience'}, &subs::session_suds($c));
									$secret = `echo "$secret" | base64 -w 0`;
									my $watch_home = 'http://' . $watch->{'ip'} . ':' . $config->{'port'} . '/chat_received?s=' . $secret . '&timestamp=' . $m->{'timestamp'} . '&uuid=' . $m->{'uuid'};

									my $ping = 'timeout .2 ping -c 1 ' . $watch->{'ip'};
									my $ping_test = `$ping`;
									if ($ping_test =~ /ttl/gi) {
										&subs::subprocessor(sub {
									    Mojo::IOLoop->reset;

											my $ua = Mojo::UserAgent->new();
											my $res = $ua->insecure(1)->get($watch_home)->result;
										}, { name => 'lora embedded sender' });
									}
								}
							}
						}
					}
				}

			}
			&mail_depublicizer($c) if $trusted;
		}
		elsif ($m->{'type'} eq 'refresher') {
			my ($db,$database,$sql) = &subs::database_grabber();
			# the tab's own address is the thread to catch up on - the client
			# sends nothing but the timestamp of the last message it saw
			my $address = $gb::mailws->{$browser_tab_id}->{'address'} || {};
			my $picker = $address->{'picker'} || {};
			my $last_message = $m->{'last_message'} || 0;
			my $q;
			if ($address->{'phone'}) {
				$q = &subs::db_fresh('select * from mailbox where timestamp > ? and phone = ? and coalesce(status, \'\') != \'ignored\' order by timestamp desc LIMIT 20', $last_message, $address->{'phone'});
			}
			elsif ($address->{'email'}) {
				$q = &subs::db_fresh('select * from mailbox where timestamp > ? and email = ? order by timestamp desc LIMIT 20', $last_message, $address->{'email'});
			}
			elsif ($address->{'contact'} || $address->{'ticket'}) {
				my $contact = $address->{'contact'} || $address->{'ticket'};
				$q = &subs::db_fresh('select * from mailbox where timestamp > ? and contact = ? and coalesce(status, \'\') != \'ignored\' order by timestamp desc LIMIT 20', $last_message, $contact);
			}
			else {
				my @cols = &mail_construct_columns();
				my $where = join ' and ', map { "$_ = ?" } @cols;
				my $constructs = &mailws_constructs($picker);
				$q = &subs::db_fresh("select * from mailbox where timestamp > ? and coalesce(status, '') != 'ignored' and $where order by timestamp desc LIMIT 20",
					$last_message, map { $constructs->{$_} } sort keys %{$gb::social_constructs}
				);
			}
			my $messaging = ref($q) eq 'ARRAY' ? $q : $q->hashes;
			foreach my $mess ( @{$messaging} ) {
				if ($mess->{'status'} eq 'public' && $c->session('privilege') eq 'citizen') {
					&subs::db_query('update mailbox set status=?, body =? where uuid =?', 'sent', &subs::note_encrypter(&subs::session_suds($c), $mess->{'body'}, $mess->{'timestamp'}), $mess->{'uuid'});
				}
				else {
					$mess->{'body'} = &mail_text_chars(&subs::note_decrypter(&subs::suds_grabber(), $mess->{'body'}, $mess->{'ost'}));
				}
				if ($mess->{'subject'}) {
					$mess->{'subject'} = &mail_text_chars(&subs::note_decrypter(&subs::session_suds($c), $mess->{'subject'}, $mess->{'ost'}));
				}
				$mess->{'decrypted'} = 'yes';
				$mess->{'envelope'} = $c->render_to_string(
					template => 'mail/message',
					'm' => $mess,
					'me' => $me
				);
			}
			$mws->send({ json => { messages => $messaging, 'type' => 'refresher' } });
		}
	});
	$c->on(finish => sub ($c, $code, $reason) {
		# a reconnect - a wake, a new section - registers the new connection
		# before this older one is noticed to be gone: only the connection
		# still on duty may take the tab's entry away
		my $entry = $gb::mailws->{$browser_tab_id};
		if ($entry && $entry->{'tx'} && $entry->{'tx'} == $c->tx) {
			delete $gb::mailws->{$browser_tab_id};
		}
	});
};

post '/mail/msg' => sub($c) {
	my $msg = {};

	$msg = eval { return decode_json $c->param('msg') } || {};
	# a hand-over from the mesh must come from the mesh: a signatorial this
	# house knows, a live session, or the machine itself. Without one this is an
	# open insert into the mailbox - the one door that must stay shut, since a
	# message nobody sent is exactly what "not written down" promises against
	my $signatorial = $c->param('signatorial');
	my $local_door = $c->tx->remote_address eq $c->tx->local_address;
	my $known_neighbour = $signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0];
	my $approved = ($c->session('authentication') || '') eq 'approved';
	# A hand-over that names a neighbour must be signed by that neighbour's pinned
	# key: a signatorial is a name, and a name alone once let anyone insert a
	# letter into this mailbox. A signed peer is then held to its lease: a reply
	# to a thread this house already holds needs visitor; a conversation it starts
	# needs resident.
	my $signed_peer = 0;
	if (!$local_door && $known_neighbour && $known_neighbour->{'pubkey'}) {
		$signed_peer = &subs::peer_verify($c, $known_neighbour) ? 1 : 0;
		unless ($signed_peer) {
			$log->info('mail hand-over refused: ' . $signatorial . ' did not sign');
			$c->render(json => { ok => 0, error => 'not signed' });
			return;
		}
	}
	unless ($local_door || $signed_peer || ($approved && !$known_neighbour)) {
		$log->info('mail hand-over refused from ' . $c->tx->remote_address . ' signatorial=' . ($signatorial || 'none'));
		$c->render(json => { ok => 0, error => 'unknown neighbour' });
		return;
	}
	if ($signed_peer) {
		my $thread = $msg->{'conversation_uuid'} || '';
		my $is_reply = 0;
		if ($thread ne '') {
			$is_reply = 1 if &subs::db_query('select 1 from mailbox where conversation_uuid = ? limit 1', $thread)->hashes->[0];
		}
		if (!$is_reply && ($msg->{'in_reply_to'} || '') ne '') {
			$is_reply = 1 if &subs::db_query('select 1 from mailbox where message_id = ? limit 1', $msg->{'in_reply_to'})->hashes->[0];
		}
		my $need = &subs::peer_action_scope($is_reply ? 'mail_reply' : 'mail_start') || 'resident';
		unless (&subs::peer_allows($c, $known_neighbour, $need)) {
			$log->info('mail hand-over refused: ' . $signatorial . ' holds no ' . $need . ' grant');
			$c->render(json => { ok => 0, error => 'not permitted' });
			return;
		}
		unless (&subs::peer_rate_ok($known_neighbour, 'message')) {
			$log->info('mail hand-over rate limited: ' . $signatorial);
			$c->render(json => { ok => 0, error => 'rate limited' }, status => 429);
			return;
		}
	}
	if ($msg->{'uuid'}) {
		# an ephemeral letter is only ever heard live: the machine that catches
		# it delivers it to whoever is tuned in and writes nothing down
		if ($msg->{'ephemeral'}) {
			$msg->{'decrypted'} = 'yes';
			$msg->{'envelope'} = $c->render_to_string(
				template => 'mail/message',
				'm' => $msg,
				'me' => ''
			);
			&mailws_sender($msg);
			$c->render(json => $msg);
			return;
		}
		my $pre_msg = &subs::db_query('select uuid from mailbox where uuid=? and manager_file=?', $msg->{'uuid'}, $msg->{'manager_file'})->hashes->[0];
		unless ($pre_msg->{'uuid'}) {
			&subs::db_insert('mailbox', $msg);
			# a neighbour handed a message over: the browsers hear about it
			# here, not only on the machine the letter started from
			&subs::mail_arrival({ c => $c, %{$msg} });
			my $remote_machines = &subs::db_select('remote_machines', undef, { connection => 'active' })->hashes;
			my $form_data = {
				signatorial => &subs::signatorial_designer(),
				msg => encode_json $msg
			};
			foreach my $rm ( @{$remote_machines} ) {
				&subs::subprocessor(sub {
			    Mojo::IOLoop->reset;
					$rm = &remote_useragent_maker({ ip => $rm->{'ip'}, signatorial => $rm->{'signatorial'}, rm => $rm });
					my $url = $rm->{'manager'} . '/mail/msg';
					my $res = $rm->{'ua'}->post($url => form => $form_data)->result;
					if ($res->is_success) {

					}
				}, { name => 'embedded mail msg' });
			}
		}
	}

	$c->render(json => $msg);
};



sub mail_depublicizer($c) {
	my $me = &manager_file_maker($c->session('name'));
	my $publics = &subs::db_query('select * from mailbox where status=?', 'public');
	my $public = $publics->hashes;
	foreach my $p ( @{$public} ) {
		my $enc_body = &subs::note_encrypter(&subs::session_suds($c), $p->{'body'}, $p->{'timestamp'});
		&subs::db_query('update mailbox set status=?, body =? where uuid =?', 'sent', $enc_body, $p->{'uuid'});

		my %depublicized;
		foreach my $k ( keys %{$gb::social_constructs} ) {
			$depublicized{$k} = $p->{ $gb::social_constructs->{$k}->{'sing'} };
		}
		my $messenger = {
			# the client replaces a message whose uuid is already on screen,
			# so this envelope must wear the row's uuid or it only ever appends
			uuid => $p->{'uuid'},
			msg => $p->{'body'},
			timestamp => $p->{'timestamp'},
			type => 'message',
			mail_contact => $p->{'contact'},
			picker => \%depublicized,
			manager_file => $p->{'manager_file'},
			decrypted => 'yes'
		};
		$p->{'body'} = $p->{'body'};
		$p->{'decrypted'} = 'yes';
		$messenger->{'envelope'} = $c->render_to_string(
			template => 'mail/message',
			'm' => $p,
			'me' => $me
		);
		&mailws_sender($messenger);
	}

}

post '/manager/president' => sub($c) {
	my $command = $c->param('command');
	my $remote_signatorial = $c->param('signatorial');

	my $rm = &subs::db_select('remote_machines', undef, { signatorial => $remote_signatorial })->hashes->[0];
	$log->info('president route: command=' . ($command || '') . ' from=' . ($remote_signatorial || '') . ' ip=' . $c->tx->remote_address) if $log;
	if ($rm && &subs::peer_verify($c, $rm) && $command eq 'restart') {
		&president_restarter();
	}
	$c->render(json => { command => $command, remote_signatorial => $remote_signatorial });
};

post '/manager/president/restart' => sub($c) {
	&president_restarter();
	$c->render(text => 'restarting');
};

sub president_restarter() {
	my $trace = do { require Carp; Carp::longmess('president_restarter') };
	$log->info("president_restarter called from:\n" . $trace) if $log;
	my $status_file = &subs::home('~/.president/status');
	write_file($status_file, 'restart');
}


get '/manager/remote_auth_test' => sub($c) {

	my $ip = $c->tx->remote_address;
	my $home_ip = $c->tx->local_address;
	my $remote_domain = $c->param('domain') || $ip;
	my $chip_chyea = $c->param('chip_chyea');
	my $signatorial = $c->param('signatorial');

	# The peer rail authenticates by signature, not by session: the request must
	# name a known machine and carry that machine's fresh signature (an unsigned
	# call passes only while no key is on file yet, so machines can upgrade
	# without a flag day). The session gate steps aside for this route in
	# hooks.pl, so a peer whose session has lapsed can still handshake - this
	# check is the whole of the route's access control.
	#
	# Try every row for the signatorial, not just the last: repeated discovery
	# can leave a second row behind, and verifying only `[-1]` meant a stale
	# duplicate key rejected a peer whose real row was fine. Rows with a key are
	# tried first; a keyless row is the trust-on-first-contact fallback.
	my $rm_rows = &subs::db_query('select * from remote_machines where signatorial = ?', $signatorial)->hashes;
	my $verified;
	foreach my $cand ( sort { (($b->{'pubkey'} || '') ne '') <=> (($a->{'pubkey'} || '') ne '') } @{$rm_rows} ) {
		if (&subs::peer_verify($c, $cand)) { $verified = $cand; last; }
	}
	unless ($verified) {
		$c->rendered(403);
		return;
	}
	my $rm = [ $verified ];

	if ($chip_chyea) {
		&subs::setting_setter({ app => '__president', setting => 'chip_chyea', subsetting => $signatorial, value => $chip_chyea });
		$c->render(json => { chip_chyea => $chip_chyea });
	}
	elsif ($c->param('auth_test') eq 'yes') {
		my $now = &subs::rightNow();
		my $appt = &subs::db_query('select server_time,app from appointments where (status is null or status != ?) and server_time < ? order by server_time DESC LIMIT 1', 'deleting', $now - 2500)->hashes->[0];
		if (scalar @{$rm} > 0) {
			if ($rm->[-1]->{'signatorial'}) {
				my @domain = split '\.', $config->{'domain'};
				shift @domain;
				my $domain = join '.', @domain;

				my $my_signatorial = &subs::signatorial_designer();

				my @ws_auth = (
					$ip, $my_signatorial
				);
				my $ws_joiner = join $universal_splitter, @ws_auth;
				my $pa = &subs::random_string_creator(25);
				my $ws_auth = &subs::encrypter($pa, $ws_joiner);
				&subs::setting_setter({ app => '__president', setting => 'ws_pa', value => $pa});

				# Age out a dead worker's marker, and check the owner it names: a
				# peer told "merging" forever stops this machine from ever pulling
				# its newer rows. An older value is a bare 'running' (no pid), so
				# trust the age bound for it.
				my $merge_row = &subs::db_query('select value,server_time from settings where app = ? and setting = ? order by cast(server_time as integer) desc limit 1', '__president', 'remote_upgrade')->hashes->[0] || {};
				my ($m_flag, $m_pid) = split /:/, ($merge_row->{'value'} || ''), 2;
				$m_flag ||= '';
				my $m_live = ($m_flag eq 'running' && (!$m_pid || ($m_pid =~ /^\d+$/ && $m_pid > 1 && kill(0, $m_pid)))) ? 1 : 0;
				my $merging = ($m_live && int($merge_row->{'server_time'} || 0) + 600000 > $now) ? 'running' : '';

				# Only a machine with a real GPS advertises its place in the handshake.
				# A computer's own row is borrowed from a phone, and lending that on
				# would let a third machine adopt a copy of a copy.
				my $location;
				if (&subs::navigation_gps_present()) {
					$location = &subs::db_query('select * from continent where signatorial=? and type=? and server_time >= ? order by server_time desc limit 1', $my_signatorial, 'temporary',&subs::rightNow() - (5 * 60 * 1000))->hashes->[0];
				}

				# The caller handed us the watermark it already holds (?since=); this
				# is how many of our appointments sit above it, so the caller can tell
				# whether it is behind (and by how much) without pulling the export,
				# and can check the two machines' pictures against each other.
				my $pending = &subs::appointments_since($c->param('since')) || { count => 0, max_server_time => 0 };
				# A pending device request must also make the hub pull this machine.
				# The table is a leaf and has no new appointment when its app asks for
				# a key, so the digest alone left the request waiting for the next
				# scheduled pass (and it nearly expired first).
				my $dr_pending = &subs::db_query('select count(*) as n from device_requests where status = ? and server_time > ?', 'pending', &subs::rightNow() - 3600000)->hash->{'n'} || 0;
				if ($dr_pending) {
					$pending->{'count'} = ($pending->{'count'} || 0) + $dr_pending;
					$pending->{'device_requests'} = $dr_pending;
				}
				# Everything deleted here above the caller's confirmed cursor; the
				# caller applies these and reports its new cursor on the next request.
				my $reader_cursor = $c->param('tombstone_cursor');
				my $tombstones = &subs::tombstones_since($reader_cursor);

				# The caller's per-table cuts (its newest `server_time` in each
				# table). Answering with our own count/sum/max above each cut is what
				# lets it tell a strict forward delta (it is missing only rows newer
				# than the cut) from a real divergence (an offline device holds a row
				# nobody else saw), which needs a full table rather than a window.
				my $cuts = &subs::sync_map_decode($c->param('cuts'));
				my %above;
				if (scalar keys %{$cuts}) {
					my %allowed = map { $_ => 1 } (@{ &subs::sync_table_list() }, 'settings_durable');
					foreach my $t ( sort keys %{$cuts} ) {
						next unless $allowed{$t};
						my $a = &subs::sync_table_above($t, $cuts->{$t});
						$above{$t} = $a if $a;
					}
				}

				my $json = {
					server_time => $appt->{'server_time'},
					app => $appt->{'app'},
					port => $ENV{PORT_AHOY},
					ws_port => $ENV{PORT_MSG},
					signatorial => $my_signatorial,
					now => $now,
					me => $c->tx->local_address,
					you => $c->tx->remote_address,
					deletions => $rm->[-1]->{'deletions'},
					fqdn => (&subs::public_origin_host() || $config->{'domain'}),
					domain => $domain,
					ws_auth => $ws_auth,
					env => $ENV{PORT_ENV},
					merging => $merging,
					location => $location,
					same_net => &subs::same_net_test($home_ip,$ip),
					network => &subs::network_interface_reporter(),
					revision => &subs::code_revision(),
					version => &subs::jawn_version(),
					sync => &subs::appointment_watermark(),
					tombstones => $tombstones,
					sync_cursor => &subs::tombstone_max(),
					pending => $pending,
					sync_version => 3,
					# This build can answer a per-band map, so a peer that can read one
					# may localise a divergence instead of reading the whole table.
					bands => 1,
					digest => &subs::sync_digest_map(),
					above => \%above,
				};
				$c->render(json => $json);

				my $deletions = eval { return decode_json $rm->[-1]->{'deletions'} } || [];
				@{$deletions} = grep { $_->{'initialization'} + 60000 > &subs::rightNow() } @{$deletions};
				$deletions = eval { return encode_json $deletions };

				&subs::db_update('remote_machines', { deletions => $deletions }, { signatorial => $rm->[-1]->{'signatorial'} }) if eval { decode_json $rm->[-1]->{'deletions'} };

				# Advance this reader's confirmed cursor to what it last reported,
				# then drop any tombstone every machine has now read past.
				if (defined $reader_cursor && $reader_cursor =~ /^[0-9]+$/) {
					&subs::db_query('insert or replace into sync_cursors (signatorial, cursor) values (?, ?)', $rm->[-1]->{'signatorial'}, $reader_cursor);
				}
				&subs::tombstone_purge();


			}
		}
		else {
			$c->render(json => {});
		}
	} else {
		$c->render(json => {});
	}
};

# The yellow dot's expanded panel: the active sync plus the last few completed
# remote pulls, from this machine's point of view. The active peer name rides in
# the yellow message itself; this route supplies the history. Only confirmed
# pulls (remote_upgraded) are listed - remote_update is the in-flight row.
get '/manager/sync_history' => sub($c) {
	my $me = &subs::signatorial_designer();
	my $limit = 8;
	my $rows = &subs::db_query(
		'select recipient, signatorial, server_time, size from backups where reason = ? and (recipient = ? or signatorial = ?) order by cast(server_time as integer) desc limit ?',
		'remote_upgraded', $me, $me, $limit * 3
	)->hashes || [];
	my %label;
	foreach my $rm ( @{ &subs::db_select('remote_machines')->hashes || [] } ) {
		my $name = $rm->{'ip'} || $rm->{'hostname'} || $rm->{'fqdn'} || '';
		$label{$rm->{'signatorial'}} = $name if $name ne '';
	}
	$label{$me} = 'this machine';
	my @recent;
	my %seen;
	foreach my $r ( @{$rows} ) {
		my $recipient = $r->{'recipient'} || '';
		my $signatorial = $r->{'signatorial'} || '';
		# A snapshot's `signatorial` is the machine that served it and its
		# `recipient` is the caller. A row naming us as the server is an
		# outbound serve (the peer pulled from us); one naming us as the
		# recipient is an inbound pull. These were the wrong way round.
		my ($direction, $peer);
		if ($recipient eq $me) { $direction = 'in'; $peer = $signatorial; }
		elsif ($signatorial eq $me) { $direction = 'out'; $peer = $recipient; }
		else { next; }
		my $second = int(($r->{'server_time'} || 0) / 1000);
		next if $seen{$peer . ':' . $second}++;
		push @recent, {
			time => int($r->{'server_time'} || 0),
			direction => $direction,
			peer => $label{$peer} || $peer,
			size => int($r->{'size'} || 0),
		};
		last if scalar @recent >= $limit;
	}
	my $lock = &subs::db_query('select value,server_time from settings where app = ? and setting = ?', '__president', 'remote_backup_lock')->hashes->[0] || {};
	my $upgrade = &subs::db_query('select value,server_time from settings where app = ? and setting = ? order by cast(server_time as integer) desc limit 1', '__president', 'remote_upgrade')->hashes->[0] || {};
	my ($u_flag, $u_pid) = split /:/, ($upgrade->{'value'} || ''), 2;
	$u_flag ||= '';
	my $u_live = ($u_flag eq 'running' && (!$u_pid || ($u_pid =~ /^\d+$/ && $u_pid > 1 && kill(0, $u_pid)))) ? 1 : 0;
	my $now = &subs::rightNow();
	# The job table is the live picture: one row per pull/serve, with the steps
	# (one bar each) that the panel draws across the top.
	my $jobs = &subs::sync_job_list(12);
	my ($active) = grep { ($_->{'state'} || '') eq 'running' } @{$jobs};
	$c->render(json => {
		current => {
			serving => (($lock->{'value'} || '') ne '' && int($lock->{'server_time'} || 0) + 600000 > $now) ? 1 : 0,
			pulling => ($u_live && int($upgrade->{'server_time'} || 0) + 600000 > $now) ? 1 : 0,
			job => $active,
		},
		jobs => $jobs,
		recent => \@recent,
	});
};




# Log a peer back in so the session cookie we keep for it is fresh. The relay and
# the sync rail post to a peer's ordinary routes carrying that cookie, and those
# routes are gated; the cookie lapses without a word - most often when the peer
# renames its database, which the session remembers - so a relayed request comes
# back with the Gate page where the route's reply was expected. Reuses the same
# credentialed login (the peer's /sesh_check) the reconnect path uses.
sub remote_machine_reauth($c, $rm, $timestamp, $ip, $browser_tab_id, $browser_tab) {
	my $rdc = {
		manager => $rm->{'manager'},
		filename => $rm->{'data'}->{'database'},
		timestamp => $timestamp,
		ip => $ip,
		password => &subs::session_suds($c),
		name => $c->session('name'),
		browser_tab_id => $browser_tab_id,
		browser_tab => $browser_tab,
		port => $rm->{'port'},
		signatorial => $rm->{'signatorial'},
		nic => $rm->{'nic'},
		tunnel => $rm->{'tunnel'}
	};
	$rm->{'cookie'} = undef;
	return &remote_device_connect($rdc);
}

# The sync topology is a house setting (`sync/topology`, so the settings merge
# carries it to every machine). The Dev panel writes one shared `device => 'all'`
# row; an older override can still sit on a machine's own device row or in
# `__president/sync_topology`, so read those as fallbacks. A blank or unknown
# value means auto.
sub sync_topology_get {
	my $v = &subs::setting_grabber({ app => 'sync', setting => 'topology', device => 'all' });
	$v = &subs::setting_grabber({ app => 'sync', setting => 'topology' }) unless defined $v && length $v;
	$v = &subs::setting_grabber({ app => '__president', setting => 'sync_topology' }) unless defined $v && length $v;
	$v = 'auto' unless defined $v && $v =~ /^(?:auto|mesh|hub)$/;
	return $v;
}

# A hub is healthy enough to collapse a spoke's pass to hub-and-spoke when its
# last handshake is recent and, if we reach it through a tunnel, that tunnel still
# has a fresh pong (the same freshness the tunnel checker reads).
sub sync_hub_status {
	my ($hub) = @_;
	return 0 unless $hub && $hub->{'signatorial'};
	return 0 if (&subs::rightNow() - int($hub->{'server_time'} || 0)) > 6 * 60 * 1000;
	if (($hub->{'tunnel'} || '') eq 'yes') {
		my $age = eval { &Tunnel::alive_age($hub->{'manager'}) };
		my $ports = eval { &Tunnel::alive_ports($hub->{'manager'}) };
		return 0 unless defined $age && $age < 45000 && (!defined $ports || $ports >= 1);
	}
	return 1;
}

# Pick the hub once per pass and persist it, so roster churn cannot silently move
# the mesh's centre. A server is its own hub; a spoke learns its server's
# signatorial from the roster and keeps the saved one while its row is recent.
sub sync_hub_pick {
	my ($machines, $is_hub) = @_;
	return &subs::signatorial_designer() if $is_hub;
	my $saved = &subs::setting_grabber({ app => '__president', setting => 'sync_hub' }) || '';
	my @servers = grep { ($_->{'device'} || '') eq 'server' && ($_->{'signatorial'} || '') } @{ $machines || [] };
	return $saved unless scalar @servers;
	my ($best) = sort { int($b->{'server_time'} || 0) <=> int($a->{'server_time'} || 0) } @servers;
	return $saved unless $best;
	my ($saved_row) = grep { ($_->{'signatorial'} || '') eq $saved } @{ $machines || [] };
	my $saved_fresh = $saved_row && (&subs::rightNow() - int($saved_row->{'server_time'} || 0)) < 30 * 60 * 1000;
	return $saved if $saved && $saved_fresh;
	if (($best->{'signatorial'} || '') ne $saved) {
		&subs::setting_setter({ app => '__president', setting => 'sync_hub', value => $best->{'signatorial'} });
	}
	return $best->{'signatorial'} || '';
}

sub remote_machine_reconnector($c) {


	&subs::setting_setter({ app => '__president', setting => 'remote_connect_timer', value => &subs::rightNow() });
	my $timestamp = &subs::rightNow();
	my $browser_tab_id = $c->param('browser_tab_id');
	my $browser_tab = $c->param('browser_tab');
	my $ws_auth;
	my $signatorial = &subs::signatorial_designer();
	eval {
		my $remote_machines = &subs::remote_machine_lister({ });
		# Hub-and-spoke while the server is live: a spoke stops dialling peers it
		# can only reach through the hub, and falls back to the full mesh when the
		# hub's handshake or its tunnel goes stale. The hub itself always walks the
		# whole roster (it is the union), and a peer on our own LAN is still direct.
		my $topology = &sync_topology_get();
		my $hub_sig = &sync_hub_pick($remote_machines, ($device eq 'server') ? 1 : 0);
		my ($hub_row) = $hub_sig ? grep { ($_->{'signatorial'} || '') eq $hub_sig } @{$remote_machines} : ();
		my $hub_ok = ($device eq 'server') ? 1 : &sync_hub_status($hub_row);
		my $hub_mode = ($device ne 'server' && $hub_sig && ($topology eq 'hub' || ($topology eq 'auto' && $hub_ok))) ? 1 : 0;

		# A peer's stored session cookie lapses unnoticed: the handshake below is
		# signed and gate-exempt, so it keeps answering JSON while every relayed
		# request to a gated route comes back as the Gate page, and the relay quietly
		# does nothing. Every few minutes, once per pass, probe a peer with its stored
		# cookie and log it back in when the cookie no longer authenticates, so the
		# relay and the sync rail ride a fresh session.
		my $auth_probe_due = (&subs::rightNow() - (&subs::setting_grabber({ app => '__president', setting => 'remote_auth_probe_timer' }) || 0)) > 180000;
		my $auth_probe_filed = 0;
		my @accomplished;
		foreach my $rm ( @{$remote_machines} ) {
			# never a turn for ourselves: the 'me' pseudo and any self row that
			# slipped in would otherwise burn the tick (and decode the hub's own
			# giant data blob) before a real peer is reached.
			next if ($rm->{'signatorial'} || '') eq $signatorial;
			next if grep { $_ eq $rm->{'signatorial'} } @accomplished;
			if ($hub_mode) {
				# The hub, and anything we can reach on our own LAN, stay in the pass;
				# a peer whose only path is the hub is left to the hub to pull.
				my $direct = (($rm->{'signatorial'} || '') eq $hub_sig) ? 1 : 0;
				$direct ||= (($rm->{'lan'} || '') eq 'yes') ? 1 : 0;
				$direct ||= &subs::peer_lan_address($rm) ? 1 : 0;
				next unless $direct;
			}
			eval {

				my $ip = $rm->{'ip'};
				my $ping_test;
				my $ping = &remote_machine_online({ rm => $rm, ip => $ip, port => $rm->{'port'}, signatorial => $rm->{'signatorial'} });

				if ($ping == 0) { $ping_test = 'no'; }

				my $auuid = &subs::random_string_creator();
				my $is_tunnel = $rm->{'tunnel'};

				if ($device ne 'server' && !$rm->{'tunnel'} && $ping =~ /127\.0\.0\.1/) {
					$ping = '';
					$rm->{'connection'} = 'inactive';
					$ping_test = 'no';
					if ($ping_test eq 'no' && $rm->{'pseudonyms'}) {
						($ping,$ping_test,$rm) = &remote_pseudonyms($rm);
					}
				}
				elsif ($ping_test eq 'no' && $rm->{'pseudonyms'}) {
					($ping,$ping_test,$rm) = &remote_pseudonyms($rm);
				}

				sub remote_pseudonyms($rm) {
					my $pseu = eval { return decode_json $rm->{'pseudonyms'} } || {};
					# No `my` on $ping/$ping_test here: shadowing them inside the block threw
					# the probe's answer away, so a reachable pseudonym still read as
					# no-answer and the full handshake below never ran on the new network.
					my ($ping,$ping_test);
					if ($pseu->{'ip'}) {
						$ping = &remote_machine_online({ rm => $rm, ip => $pseu->{'ip'}, port => $pseu->{'port'}, signatorial => $rm->{'signatorial'} });

						if ($ping == 0) {
							$ping_test = 'no';
						} else {
							# rebuild the manager in the base form the handshake expects
							# (host:port, no /manager path): the stored pseudonym carries the
							# peer's advertised `.../manager`, which would double up when the
							# handshake appends its own '/manager/remote_auth_test'.
							my $port = $pseu->{'port'} || $rm->{'port'};
							$rm->{'ip'} = $pseu->{'ip'};
							$rm->{'manager'} = 'https://' . $pseu->{'ip'} . ':' . $port;
							$rm->{'port'} = $port;
							$rm->{'ws_port'} = $pseu->{'ws_port'};
						}
					}
					return ($ping, $ping_test, $rm);
				}


				if ($ping == 1) {

					$ip = $rm->{'ip'};
					# Hand the peer the watermark we already hold from it, so its auth
					# route can say (with a count) whether it has anything newer instead
					# of our pulling its window on every tick. The per-table digest is the
					# real signal: it catches a table that moved without a new appointment
					# and an offline peer holding a row nobody else saw.
					my $peer_watermark = &subs::db_query('select server_time from backups where reason=? and signatorial=? and recipient=? order by server_time DESC LIMIT 1', 'remote_upgraded', $rm->{'signatorial'}, $signatorial)->hashes->[0];
					my $my_digest = &subs::sync_digest_map();
					$rm = &remote_useragent_maker({ signatorial => $rm->{'signatorial'}, rm => $rm, auth_test => 'yes', tombstone_cursor => ($rm->{'sync_cursor'} || 0), since => ($peer_watermark->{'server_time'} || 0), digest => $my_digest });
					my $manager = $rm->{'manager'};
					my $port = $rm->{'port'};
					my $port_dock = $rm->{'dock_port'};
					$manager =~ s/:$port/:$port_dock/gi;
					if (!$rm->{'res'}) {
						$ping_test = 'no';
					}
					if (!eval { return decode_json $rm->{'res'}->body }) {
						$ping_test = 'no';
						if ($rm->{'data'}->{'database'}) {
							my $auuid = &subs::random_string_creator();
							my $manager_file = &manager_file_maker($c->session('name'));
							my $html = '<h2>Reconnecting to ' . $ip . '</h2>';
							&Websocket::send('tab', { green => $html, uuid => $auuid });
							my $returner = &remote_machine_reauth($c, $rm, $timestamp, $ip, $browser_tab_id, $browser_tab);
							if ($returner->{'body'}->{'signatorial'}) {
								$ping_test = 'ok';
							}
							else {
								$ping_test = 'no';
							}
						}
						else { $ping_test = 'ok'; }
					}
					else {
						my $rj = eval { return decode_json $rm->{'res'}->body };
						# The handshake answered JSON, but a gate-exempt route answers even to
						# a lapsed cookie, so ask a gated but read-only route with the stored
						# cookie too. HTML back (not the route's JSON) means the session is
						# dead; log in again so the relay stops handing the caller the Gate.
						if ($auth_probe_due && $rm->{'ua'} && $rm->{'data'}->{'database'}) {
							if (!$auth_probe_filed) { &subs::setting_setter({ app => '__president', setting => 'remote_auth_probe_timer', value => &subs::rightNow() }); $auth_probe_filed = 1; }
							my $probe_tx = eval { $rm->{'ua'}->inactivity_timeout(10)->get($rm->{'manager'} . '/manager/configure/tunnel/list' => { Accept => 'application/json, text/html' }) };
							my $probe_body = eval { $probe_tx->res->body } || '';
							&remote_machine_reauth($c, $rm, $timestamp, $ip, $browser_tab_id, $browser_tab) if length $probe_body && $probe_body !~ /^\s*[\{\[]/;
						}
						next if $rj->{'signatorial'} eq $signatorial;
						my $appt = &subs::db_query('select server_time,app from appointments order by server_time DESC LIMIT 1')->hashes->[0];
						if ($rj->{'fqdn'}) {
							my @domain = split '\.', $rj->{'fqdn'};
							my $subdomain = $domain[0];

							if ($rj->{'ws_auth'}) {
								$ws_auth = url_escape $rj->{'ws_auth'};
							}

						}
						$rm->{'port'} = $rj->{'port'};
						$rm->{'ws_port'} = $rj->{'ws_port'};
						$ping_test = 'ok';
						my $backup = &subs::db_query('select * from backups where reason=? and signatorial=? and recipient=? order by server_time DESC LIMIT 1',
							'remote_upgraded',$rj->{'signatorial'},$signatorial)->hashes->[0];
						# The guarded plan: the digest says whether a table's picture differs,
						# and `above` proves whether the difference is a strict forward delta.
						# The plan is handed over from the first pull too: `sync_plan` already
						# skips a table whose picture meets ours and only asks for a full read
						# when the divergence cannot be a forward delta, so a cold peer gets
						# its one full reconciliation now instead of a bounded window that
						# leaves old unique rows behind forever.
						my $seen = &subs::sync_seen_get($rj->{'signatorial'});
						# The band map is what turns a divergent picture into a handful of
						# moved blocks; without it the planner must either skip a small
						# old-row gap or read the table whole.
						my $bands = &subs::sync_bands_peer($rj->{'version'}, $rj->{'bands'});
						my $plan = &subs::sync_plan($my_digest, $rj->{'digest'}, $rj->{'above'} || {}, $seen, $bands);
						my $plan_differs = (ref $plan eq 'HASH' && scalar keys %{$plan}) ? 1 : 0;
						my $plan_pull = $plan_differs ? 1 : 0;
						if ($rj->{'deletions'}) {
							&deletion_performer($rj->{'deletions'});
						}
						# Apply the peer's durable tombstones and record how far we have
						# read its log, so its next purge can drop what we have seen.
						if ($rj->{'tombstones'}) {
							my @dels = map { { table => $_->{'tbl'}, app => $_->{'app'}, uuid => $_->{'uuid'}, scope => $_->{'scope'}, server_time => $_->{'server_time'}, additional => $_->{'additional'} } } @{$rj->{'tombstones'}};
							&deletion_performer(encode_json \@dels) if scalar @dels;
							&subs::db_update('remote_machines', { sync_cursor => ($rj->{'sync_cursor'} || 0) }, { signatorial => $rj->{'signatorial'} });
						}
						# Refresh the live flags on every successful tick: connection/status
						# were only ever set on a full reconnect, so a row could read
						# 'inactive' while the peer was answering every handshake (the hub
						# showed that here). version rides along so "who is behind" is a
						# column, not a guess.
						my $flags = { connection => 'active', status => 'connected', server_time => &subs::rightNow() };
						$flags->{'version'} = $rj->{'version'} if $rj->{'version'};
						&subs::db_update('remote_machines', $flags, { signatorial => $rj->{'signatorial'} });
						if ($rj->{'location'} && &subs::device_setter() ne 'mobile') {
							# Only a machine with no GPS of its own adopts a peer's place. A
							# phone that has its own GPS keeps its own fix; borrowing one
							# here is what let a computer's copy of a place overwrite the
							# real fix (and read as public until the next manual fix).
							my $same_net = &subs::same_net_test($rj->{'you'},$rj->{'me'});
							my $location_source = &subs::remote_machine_lister({ signatorial => $rj->{'location'}->{'signatorial'}, mirrors => 'none', limit => 1 });
							if ($same_net eq 'yes' && $rj->{'same_net'} eq 'yes') {

								if (&remote_machine_online({ rm => $location_source }) == 1) {

									&subs::db_delete('continent', { type => 'temporary', signatorial => $rj->{'signatorial'} });
									my $tlocation = &subs::db_select('continent', undef, { type => 'temporary', signatorial => $signatorial })->hashes->[0];
									$rj->{'location'}->{'type'} = 'temporary';
									$rj->{'location'}->{'uuid'} = &subs::random_string_creator(12);
									$rj->{'location'}->{'app'} = '__president';
									&subs::db_insert('continent', $rj->{'location'});


									if (!$tlocation->{'latitude'}) {
										if (!$rj->{'location'}->{'server_time'} || $rj->{'location'}->{'server_time'} >= &subs::rightNow() - ( 5 * 60 * 1000)) {

											$rj->{'location'}->{'uuid'} = &subs::random_string_creator(22);
											$rj->{'location'}->{'signatorial'} = $signatorial;
											$rj->{'location'}->{'warranty'} = &subs::ago_calc('-5m', &subs::rightNow());
											&subs::db_delete('continent', { type => 'temporary', signatorial => $signatorial });
											&subs::db_insert('continent', $rj->{'location'});
										}
									}
								}
							}
						}
						if ($rj->{'network'}) {
							$rm->{'network'} = encode_json $rj->{'network'};
						}
						if ($device eq 'computer') {
							my $diff = ($rj->{'now'} - &subs::rightNow());
							if (abs $diff > 500 && $rj->{'now'}) {
								my $now = $rj->{'now'} / 1000;
								my $uc = 'sudo date -s @' . $now;
							#	my $update = `$uc`;
							}
						}
						# Pull when the peer's newest appointment sits above the watermark we
						# handed it, or when its `pending` count says it holds anything newer
						# (the peer computes that count from the watermark). A deep (nightly)
						# sync still runs - it reconciles a gap the watermark cannot see.
						my $deep = $c->session('gimme') || $c->param('gimme');
						my $has_new = $rj->{'server_time'} > $backup->{'server_time'};
						# A table picture that differs from the one we last reconciled is a
						# reason to pull even when no appointment moved (settings, a website,
						# an offline row). The plan itself is handed over only once the peer's
						# picture has a baseline; the first pull runs the legacy window.
						$has_new = 1 if $plan_differs;
						# pending can only ADD a pull: a peer on older code computes it with a
						# NULL-unsafe status filter (appointments_since) and can answer zero
						# while plainly holding newer appointments, so its zero must not
						# suppress the pull the timestamp comparison already wants.
						$has_new = 1 if (defined $rj->{'pending'} && ($rj->{'pending'}->{'count'} || 0) > 0);
						# A peer that told us its export was busy gets a short rest; asking
						# every tick only makes both machines spend the export over and over.
						# One pull at a time on this machine too. `remote_upgrade` guards
						# itself, but the reconnector can fork several children before the first
						# has written its marker; they then queue on the peer's single export
						# lock and starve one another (and fill the job list with waiters).
						my $own_up = &subs::db_query('select value,server_time from settings where app = ? and setting = ? order by cast(server_time as integer) desc limit 1', '__president', 'remote_upgrade')->hashes->[0] || {};
						my ($own_flag, $own_pid) = split /:/, ($own_up->{'value'} || ''), 2;
						$own_flag ||= '';
						my $own_live = ($own_flag eq 'running' && $own_pid && $own_pid =~ /^\d+$/ && $own_pid > 1 && kill(0, $own_pid)) ? 1 : 0;
						my $own_busy = ($own_live && int($own_up->{'server_time'} || 0) + 1800000 > &subs::rightNow()) ? 1 : 0;
						if (($has_new || $deep) && !$own_busy && $rj->{'merging'} ne 'running' && !&subs::sync_backoff_active($rj->{'signatorial'})) {
							my $whoami = `whoami`;
							chomp $whoami;
							my $hostname = `hostname`;
							chomp $hostname;
							my $gimme = $deep;
							my $params = {
								timestamp => $rj->{'now'},
								ip => $rm->{'ip'},
								ssh_port => $rm->{'data'}->{'ssh_port'} || $config->{'ssh_port'},
								database => $rm->{'data'}->{'database'},
								remote_signatorial => $rj->{'signatorial'},
								remote_device => $rm->{'data'}->{'device'},
								peer => ($rm->{'ip'} || $rm->{'hostname'} || $rj->{'fqdn'} || ''),
								gimme => $gimme,
								sync_version => ($rj->{'sync_version'} || 0),
								default_cut => ($peer_watermark->{'server_time'} || (&subs::rightNow() - (24 * 60 * 60 * 1000))),
								plan => ($plan_pull ? $plan : undef),
								# Remembered after a confirmed, non-windowed pull so the next
								# handshake can skip this exact peer picture.
								remote_digest => (ref $rj->{'digest'} eq 'HASH' ? $rj->{'digest'} : undef)
							};
							if ($ENV{PORT_ENV} eq 'production' && $rj->{'env'} eq 'production') {
								# Claim the marker before the fork, so the next peer in this
								# tick sees a live owner even if the child has not run yet.
								my $up_marker = 'running:' . $$;
								&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => $up_marker });
								$params->{'marker'} = $up_marker;
								# Name the decision: a pull that falls back to the snapshot path is
								# the expensive one, and the job note alone does not say which of
								# sync_version/full/gimme sent it there.
								$log->info('sync pull ' . ($rj->{'signatorial'} || '?') . ' version=' . ($rj->{'version'} || '?') . ' sync_version=' . ($rj->{'sync_version'} || 0) . ' deep=' . (defined $deep && length $deep ? $deep : '-') . ' plan=' . (ref $plan eq 'HASH' ? scalar(keys %{$plan}) : 0));
								# A pull/merge over a big table can outlive the prefork
								# heartbeat. Fork it, as the on-demand route does, so this
								# worker keeps answering (and syncing appointments) while
								# the child does the work.
								&subs::subprocessor(sub {
									my $status = &remote_upgrade($c,$params);
									if (($status || '') eq 'busy') {
										&subs::sync_backoff_set($rj->{'signatorial'}, 120);
									}
									elsif (($status || '') eq 'failed') {
										# A peer whose snapshot will not merge must not hold the one
										# pull slot every tick: give it a rest so a healthy peer (the
										# phone that is ahead) gets its turn.
										&subs::sync_backoff_set($rj->{'signatorial'}, 300);
									}
								}, { name => 'remote upgrade', fork => 1 });
							}
						}
						else {
						}
					}
				}
				else {
					my $dev_info = &device_network_updater($rm);
				}
				&Websocket::send('tab', { green => ' ', 'close' => 'yes' });
				if ($ping_test eq 'no') {
					if ($rm->{'connection'} eq 'active') {
						my $appts = &subs::db_select('appointments', undef, { app => &subs::unformat_name($rm->{'hostname'}), type => 'start' })->hashes;
						foreach my $appt ( @{$appts} ) {
							&appointment_writer($c, {
								type => 'stop',
								uuid => $appt->{'uuid'},
								app => $appt->{'app'}
							});
							&subs::appt_header_printer({ app => $appt->{'app'} });
							&Websocket::send('server', { console => 'appointmentDetailGrabber(\'' . $appt->{'app'} . '\',\'' . $appt->{'uuid'} .'\');'});
						}
					}
					$rm->{'connection'} = 'inactive';
				}
				else {
					push @accomplished, $rm->{'signatorial'};
					$rm->{'connection'} = 'active';
				}
				my $tuns = &subs::device_setter() eq 'server' ? &subs::tunnel_port_mapper({ ip => $rm->{'ip'} }) : {};

				&subs::db_update('remote_machines', { ws_auth => $ws_auth, network => $rm->{'network'}, ws_port => ($tuns->{'POST_MSG'} || $rm->{'ws_port'}), port => ($tuns->{'PORT_AHOY'} || $rm->{'port'}), connection => $rm->{'connection'} }, { signatorial => $rm->{'signatorial'} });
			}
		}
	}
}


sub device_network_updater($rm) {
	my $srms = &subs::db_select('remote_machines', undef, { connection => 'active', device => 'server' })->hashes;
	my $remote_signatorial = $rm->{'signatorial'};
	my $signatorial = &subs::signatorial_designer();
	my $me = &subs::network_interface_reporter();

	my $you = {};
	foreach my $srm ( @{$srms} ) {
		my $mirrors = eval { return decode_json $srm->{'mirrors'} } || [];
		foreach my $mirror ( @{$mirrors} ) {
			if ($mirror->{'network'}) {
				my $network = $mirror->{'network'};

				if ($mirror->{'signatorial'} eq $remote_signatorial) {
					$you = $network;
				}
			}
		}
	}

	foreach my $nic ( keys %{$you} ) {
		next if $nic eq 'public_address';
		foreach my $nicc ( keys %{$me} ) {
			next if $nicc eq 'public_address';
			my $test = &subs::same_net_test($you->{$nic}->{'ip'},$me->{$nicc}->{'ip'});
			if ($test eq 'yes') {
				my $success = 0;
				my $ip = $you->{$nic}->{'ip'};
				$success = &remote_machine_online({ rm => $rm, ip => $you->{$nic}->{'ip'}, port => $you->{$nic}->{'port'}, signatorial => $remote_signatorial });
				if ($success == 1) {
					my $pseu = encode_json $you->{$nic};
					&subs::db_update('remote_machines', { connection => 'active', pseudonyms => $pseu }, { signatorial => $rm->{'signatorial'} });
				}
				elsif ($success == 0 && $rm->{'pseudonyms'}) {
					&subs::db_update('remote_machines', { connection => undef, pseudonyms => undef }, { signatorial => $rm->{'signatorial'} });
				}
			}
		}
	}
}

sub remote_machine_online($data) {
	my $rm = $data->{'rm'} || &subs::remote_machine_lister({ signatorial => $data->{'signatorial'}, mirror => $data->{'mirror'}, limit => 1 });
	my $ip = $data->{'ip'} =~ /[0-9a-z]/ ? $data->{'ip'} : $rm->{'ip'};
	my $port = $data->{'port'} =~ /[0-9]/ ? $data->{'port'} : $rm->{'port'};
	# The manager url carries the port, so a peer reached only by its url - a
	# tunnel-only server, or a row that was paired again and came back with no
	# port - is still addressable. Without this fallback a NULL port returned 0
	# before anything was tried, so the handshake that would have filled the port
	# back in never ran (the local sat inactive with a working key and tunnel).
	$port = $1 if ((!$port || $port !~ /[0-9]/) && ($rm->{'manager'} || '') =~ m{:([0-9]{1,5})/?$});
	my $remote_signatorial = $data->{'signatorial'} =~ /[0-9a-zA-Z]/ ? $data->{'signatorial'} : $rm->{'signatorial'};
	my $success = 0;
	if ($ip && $port && $remote_signatorial) {
		# Try the stored address first, then the peer's fqdn. The stored address is
		# refreshed to the LAN address while the peer is on our network; when it
		# leaves, the fqdn/tunnel is still there to reach it.
		my @candidates = ($ip);
		my $fqdn = $rm->{'fqdn'} || '';
		push @candidates, $fqdn if $fqdn && $fqdn ne $ip;
		foreach my $candidate (@candidates) {
			next unless defined $candidate && length $candidate;
			my $ping = `timeout 1 ping -c 1 $candidate`;
			next unless $ping && $ping =~ /ttl/;
			my $ua = Mojo::UserAgent->new();
			$ua->inactivity_timeout(15);
			my $rs = &subs::encrypter(&subs::shorthand_name(&subs::rightNow(), 5) . &subs::shorthand_name($remote_signatorial, 5), $remote_signatorial);
			# When we were handed a bare LAN address (a same-net probe, or a peer's
			# stored pseudonym), call THAT address. Its manager url is usually its
			# fqdn, which resolves back to us on a machine whose hosts/dnsmasq maps
			# the peer's name to loopback - the ping answers but the call lands on
			# ourselves, so the peer never answers with its own signatorial and the
			# two machines never meet on the new network. A candidate that is not a
			# literal address uses the stored manager, which is also the tunnel on
			# the hub.
			my $base;
			if ($candidate =~ /^\d+\.\d+\.\d+\.\d+$/) {
				$base = 'https://' . $candidate . ':' . $port;
			}
			elsif ($fqdn ne '' && $candidate eq $fqdn
				&& ($rm->{'tunnel'} || '') ne 'yes'
				&& ($rm->{'manager'} || '') =~ m{^https?://\d{1,3}(?:\.\d{1,3}){3}}
				&& ($rm->{'manager'} || '') !~ m{^https?://127\.}) {
				# The stored manager is a bare LAN address the peer has since left;
				# the name is the only thing that can still reach it, so build the
				# URL from the name rather than the stale manager.
				$base = 'https://' . $fqdn . ':' . $port;
			}
			else {
				$base = $rm->{'manager'};
			}
			my $url = $base . '/?signatorial=' . url_escape $rs;
			my $user_agent = $remote_signatorial;
			my $res = $ua->insecure(1)->get($url => {user_agent => $user_agent});
			if ( $res->result->is_success ) {
				if ($res->result->body eq $remote_signatorial) {
					# Keep the address that actually answered for the rest of this
					# pass: the handshake that follows uses $rm->{manager}.
					$rm->{'manager'} = $base;
					$rm->{'port'} = $port if $port;
					$success = 1;
					last;
				}
			}
		}
	}
	if ($success == 0 && $rm->{'tunnel'} eq 'yes') {

		# tunnel work here
		foreach my $k ( keys %{$rm} ) {
			$log->info($k . ' ' . $rm->{$k}) if $k =~ /source/;
		}

	}
	return $success;
}

our $ws_server;

# Fill in the variables a text editor says: ${vape}->duration; becomes the
# setting itself, shown as an illusion that remembers what was written, so a
# click hands the words back. The name may wear braces and a dollar or neither
# - ${vape}->duration, $vape->duration and vape->duration all name the same app
# and setting, read the way the manager reads names. A dollar with a digit
# behind it - $5, $500 - is a number, not a name, and is left alone. A word
# whose setting does not exist is left exactly as it was written, never eaten.
# The whole text comes back with the token its spans wear, so the caret can be
# put back after the last one; the token is undefined when nothing was found.
#
# $self->total names the thing the editor is about rather than an app: the
# appointment it sits in, the quote/invoice and its customer the compose window
# was opened for, or the person a letter is addressed to and the newest thing
# they were sent. The context rides on the editor's magic_vars attribute; when
# it names no record - a template, before it belongs to a document - the words
# are left as written, because a template is where they are meant to wait.
#
# Two flourishes for fields that are not rich editors. 'plain' answers with the
# value itself, no illusion, and does not need the semicolon - it is for the
# compose subject, which cannot wear spans and is prose. 'self_only' refuses
# the app->setting spellings and only says $self: a subject is prose, and
# prose must not have its arrows eaten. Tags are stepped over, so an illusion
# already in the text keeps its remembrance of the words through a later pass.
sub text_area_magic($text, $context, $options = undef) {
	$options ||= {};
	my $plain = $options->{'plain'};
	my $self_only = $options->{'self_only'};
	my $terminator = $plain ? ';?' : ';';
	my $token = &subs::random_string_creator(10);
	my $found = 0;
	my @pieces = split /(<[^>]*>)/, $text;
	foreach my $piece ( @pieces ) {
		next if ($piece =~ /^</);
		# the name after a dollar must begin with a letter or an underscore, so
		# $5 and $500 are numbers and are never taken for names; an arrow the
		# browser serialised arrives as -&gt;
		$piece =~ s!
			(
				\$\{[^}&\n]+\}                       # ${vape}
				| \$?[A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_][A-Za-z0-9_]*)*   # $vape or vape
			)
			(?:-&gt;|->)([A-Za-z0-9_]+)$terminator
		!
			my ($raw_app,$raw_set,$whole) = ($1,$2,$&);
			my $app = $raw_app;
			$app =~ s/^\$\{//; $app =~ s/\}$//; $app =~ s/^\$//;
			my $value;
			if ($app eq 'self') {
				$value = &text_editor_context_value($context, $raw_set);
			}
			else {
				$value = &subs::setting_grabber({
					app => &subs::unformat_name($app),
					setting => &subs::unformat_name($raw_set)
				}) unless ($self_only);
			}
			unless (defined $value) {
				$whole;
			}
			elsif ($plain) {
				$found++;
				$value;
			}
			else {
				$found++;
				my $shown = xml_escape $value;
				my $said = xml_escape html_unescape $whole;
				'<span class="text_editor_illusion" te_token="' . $token . '" original="' . $said . '" trick="' . $shown . '" displaying="trick">' . $shown . '</span>';
			}
		!gex;
	}
	my $magic = join '', @pieces;
	return ($magic, $found ? $token : undef);
}

# The context an upgraded text editor carries in its magic_vars attribute:
# comma separated key:value pairs. The keys name the kinds of thing an editor
# can be about - appointment, document, customer, template. It is deliberately
# small, and both sides of the wire build or read it in one line.
sub text_area_context($string) {
	my $context = {};
	foreach my $pair ( split ',', ($string || '') ) {
		my ($key,$value) = split ':', $pair, 2;
		next unless defined $key && length $key;
		$context->{$key} = defined $value ? $value : '';
	}
	return $context;
}

# The newest thing a customer was sent - whatever carries numbers, so a quote,
# invoice, receipt or the like - is what a letter about them is about. Only
# papers this house printed are asked for, by the numbers they carry.
sub text_editor_latest_document($app) {
	return unless $app;
	return &subs::db_query('select * from appointments where app = ? and data like ? order by timestamp desc limit 1', $app, '%"numbers"%')->hashes->[0];
}

# What $self->name and its brothers answer for a context. An appointment
# answers from itself and its settings, and names its app rather than a record -
# the newest record that app wrote is the one its numbers come from; a document
# answers from its numbers (total, balance, the id it printed under) and from
# its customer (name, email, phone, address); a letter to a customer answers
# the same way, with the newest document standing in for the one the words are
# about; a context that names no record answers nothing, so the words wait to
# be said by whoever applies them.
sub text_editor_context_value($context, $key) {
	my $lookup = &subs::unformat_name($key);
	my $appt;
	my $named_app;
	if ($context->{'appointment'}) {
		$named_app = &subs::unformat_name($context->{'appointment'});
		$appt = &subs::db_query('select * from appointments where app = ? order by timestamp desc limit 1', $named_app)->hashes->[0];
	}
	elsif ($context->{'document'}) {
		$appt = &subs::db_select('appointments', undef, { uuid => $context->{'document'} })->hashes->[0];
	}
	my $customer;
	if ($context->{'customer'}) {
		$customer = &subs::db_select('settings', undef, { setting => 'uuid', value => $context->{'customer'} })->hashes->[0];
		$appt = &text_editor_latest_document($customer->{'app'}) if ($customer && !$appt);
	}
	my $data = {};
	$data = eval { return decode_json($appt->{'data'}) } || {} if ($appt && $appt->{'data'});
	my $numbers = $data->{'numbers'};
	if ($numbers && defined $numbers->{$lookup}) {
		return $numbers->{$lookup};
	}
	if ($lookup eq 'id' && defined $data->{'id'}) {
		return $data->{'id'};
	}
	# a document is about its customer; an appointment is about itself
	my $about = $named_app || ($appt ? $appt->{'app'} : ($customer ? $customer->{'app'} : undef));
	$about = $customer->{'app'} if (defined $context->{'document'} && $customer);
	return unless $about;
	return &subs::format_name($about) if ($lookup eq 'name');
	if ($context->{'document'} || $context->{'customer'}) {
		my $settings = &subs::settings_grabber({ app => $about });
		return $settings->{$lookup};
	}
	return &subs::setting_grabber({ app => $about, setting => $lookup });
}

# The legend an upgraded text editor shows across its top: the names $self
# can say in this context, each with the value it would show right now when
# there is something to resolve it against. A template is shown the same
# names without values - they are what it will say once it belongs to a
# document, and seeing them is how a template is written at all.
sub text_editor_variables($context) {
	my @names;
	if ($context->{'appointment'}) {
		@names = qw/name ago duration quantity schedule warranty notes/;
		my $appt = &subs::db_query('select * from appointments where app = ? order by timestamp desc limit 1', &subs::unformat_name($context->{'appointment'}))->hashes->[0];
		my $data = {};
		$data = eval { return decode_json($appt->{'data'}) } || {} if ($appt && $appt->{'data'});
		if ($data->{'numbers'} || defined $data->{'id'}) {
			push @names, qw/id subtotal discount tax aux total balance/;
		}
	}
	elsif (defined $context->{'document'} || defined $context->{'template'}) {
		@names = qw/name email phone address id subtotal discount tax aux total balance/;
	}
	elsif ($context->{'customer'}) {
		@names = qw/name email phone address/;
		# the numbers of the newest document, when the customer has one
		my $newest = &text_editor_context_value($context, 'total');
		$newest = &text_editor_context_value($context, 'id') unless defined $newest;
		push @names, qw/id subtotal discount tax aux total balance/ if defined $newest;
	}
	else {
		return [];
	}
	my @variables;
	foreach my $name ( @names ) {
		my $value = &text_editor_context_value($context, $name);
		push @variables, {
			name => '$self->' . $name,
			value => (defined $value && length $value) ? $value : undef
		};
	}
	return \@variables;
}

websocket '/manager/ws' => sub ($c) {
	my $ug    = Data::UUID->new;
	my $uuid = $ug->create_str();
	my ($db,$database,$sql) = &subs::database_grabber();
	my $app = $c->param('app');
	unless ($ws_server->{$app}) {
		$ws_server->{$app} = &ws_server_socket({ app => $app });
	}
	my $remote_address = $c->tx->remote_address;
#	$c->render(template => 'guest_layouts/denial') unless $app eq 'music' || $app eq 'server' || $app eq 'tab';
	my $timestamp = $c->param('timestamp');
	my $browser_tab_id = $c->param('browser_tab_id');
	my $browser_tab = $c->param('browser_tab');
	my $me_settings = &subs::settings_grabber({ app => 'me', settings => [ 'computer_name', 'log_me' ] });
	my $computer_name = &subs::config_reader()->{'name'} || $me_settings->{'computer_name'};
	my $log_me = $me_settings->{'log_me'};
	if ($c->param('browser_tab_id') eq '') {
		$c->render('text' => 'no');
		return;
	}
	my $user_agent = $c->param('user_agent') || $gb::user_agent;

	my $server_time = &subs::rightNow();
	my $hostname = `hostname`;
	chomp($hostname);
	my $connection_id = $c->tx;
	$connection_id = $connection_id->connection;
	my $code_rev = &subs::code_revision();
	my $init_data = {
		browser_tab_id => $browser_tab_id,
		browser_tab => $browser_tab,
		db => $database,
		'uuid' => $uuid,
		timestamp => $timestamp,
		connected => $timestamp,
		server_time => $server_time,
		type => 'connect',
		app => $app,
		hostname => $hostname,
		connection_id => $connection_id,
		user_agent => $user_agent,
		random_string => &subs::random_string_creator(25),
		# the code this machine is running; the client follows it when it changes -
		# part by part, so it knows whether a stylesheet, a template, a script or
		# the shell moved (see jawnosRevisionArrived in websocket.js). The parts and
		# the version ride the wire only, added just before the send: the websockets
		# row is a session record, not a home for the code's state, and the table
		# has no columns for them (an insert that carries them is refused).
		revision => ($code_rev->{'commit'} || $code_rev->{'fingerprint'}),
		href => $c->param('href'),
		pathname => $c->param('pathname'),
		ticket_uuid => $c->session('ticket_uuid')
	};
	if ($c->param('remote') eq 'yes') {
		my @app = split /\@/, $app;
		my $sapp = $app[0];
		$gb::remote_ws->{$sapp}->{$browser_tab_id} = $c->tx;
	}
	else {

	}
	$gb::ws->{$app}->{$browser_tab_id} = $c->tx;
	$gb::ws->{$app}->{$browser_tab_id}->{'privilege'} = $c->session('privilege');
	$gb::ws->{$app}->{$browser_tab_id}->{'device_uuid'} = $c->session('device_uuid') || '';
	my $tab_check = &subs::db_query('select * from websockets where browser_tab_id = ? and remote_address = ? and app = ?',$browser_tab_id, $remote_address, $app );
	my $existing_websockets = $tab_check->hashes;

	unless (scalar @{$existing_websockets} > 0) {
		my $app = $c->session('app');
		my $app_warranty = &subs::setting_grabber({ app => $app, setting => 'warranty' });
		my $warranty = &subs::ago_calc($app_warranty || &subs::setting_grabber({ app => 'me', setting => 'warranty' }), $server_time);
		$init_data->{'warranty'} = $warranty;
		&subs::db_insert('websockets', $init_data);

	}
	else {



	}



	# the wire carries what the row must not: the change-tracking parts and the
	# version the client compares before deciding how to follow an update
	$init_data->{'revision_parts'} = $code_rev->{'parts'};
	$init_data->{'version'} = &subs::jawn_version();
	&Websocket::send($app, $init_data);
	if ($c->param('app') eq 'music') {
		if ($log_me eq 'on') {
			my $appts = &subs::db_query('select * from appointments where source_uuid = ? and app = ? order by timestamp desc limit 30', $browser_tab, $computer_name)->hashes;
			my $resolved = 0;
			if (scalar @{$appts} > 0) {
				foreach my $appt ( @{$appts } ) {
					if ($appt->{'type'} eq 'stop') {
						if (($appt->{'timestamp'} - $appt->{'duration'}) > &subs::rightNow() - 120000) {
							$resolved = 1;
							&subs::db_update('appointments', { server_time => &subs::rightNow(), type => 'start' }, { uuid => $appt->{'uuid'}, app => $appt->{'app'} });
							&subs::intelligent_automation_toggle({ appt_uuid => $appt->{'uuid'}, app => $appt->{'app'}, 'state' => 'on', timestamp => $timestamp });
							&subs::appt_header_printer({ app => $appt->{'app'} });
							&Websocket::send('server', { console => 'appointmentDetailGrabber(\'' . $appt->{'app'} . '\',\'' . $appt->{'uuid'} .'\');'});
							my $sources = &subs::db_select('appointments', undef, { source_uuid => $appt->{'uuid'} })->hashes;
							my %so_seen;
							foreach my $so ( @{$sources} ) {
								next if $so_seen{ $so->{'uuid'} }++;
								push @{$sources}, @{&subs::db_select('appointments', undef, { source_uuid => $so->{'uuid'} })->hashes};
								if ( $so->{'type'} eq 'stop' ) {
									my $dur = $so->{'timestamp'} - $timestamp;
									&subs::db_update('appointments', { stop_seen => 'yes', type => 'start', duration => $dur, server_time => $server_time }, { source_uuid => $so->{'source_uuid'}, uuid => $so->{'uuid'}, app => $so->{'app'} });
									&budget_runner($so->{'app'});
									&subs::intelligent_automation_toggle({ appt_uuid => $so->{'uuid'}, app => $so->{'app'}, 'state' => 'on', timestamp => $timestamp });
									&Websocket::send('tab', { console => 'appointmentDetailGrabber(\'' . $so->{'app'} . '\',\'' . $so->{'uuid'} .'\');'});
								}
							}
						}
					}
					elsif ($appt->{'type'} eq 'start') {
						$resolved = 1;
					}
				}
			}

			if ($resolved == 0) {
				my $jdata = encode_json { duty_time => $gb::duty_time };
				my $data = {
					app => $computer_name,
					type => 'start',
					data => $jdata,
					timestamp => $timestamp,
					source_uuid => $browser_tab
				};
				&appointment_writer($c,$data);
			}
		}
	}
#	$c->send({json => $init_data});
	if ($app eq 'server') {
		&Websocket::send('server', { magic_wand => $browser_tab_id, action => 'open', timestamp => $timestamp });



	}

	$c->on(message => sub ($ws, $msg) {
		my $data = eval { return from_json $msg };
		my $app = $data->{'app'};
		my $apper = $data->{'app'};
		if ($app =~ /@/gi) {
			my @app = split /\@/, $app;
			$apper = $app[0];
		}
		unless ($ws_server->{$app}) {
			$ws_server->{$app} = &ws_server_socket({ app => $app });
		}
		my $remote_machines;
		if ($data->{'type'} eq 'stayingAlive') {
			my $server_time = &subs::rightNow();
			$timestamp = $data->{'timestamp'};
			my $connection = $ws->tx;
			my $connection_id = $connection->connection;
			my $local_address = $ws->tx->local_address;
			my $remote_address = $ws->tx->remote_address;
			if ($app eq 'music') {
				$data->{'music_data'} = encode_json $data->{'music_data'} if $data->{'music_data'};
			}
			if ($app eq 'server') {
				$data->{'jp_data'} = encode_json $data->{'jp_data'} if $data->{'jp_data'};
			#	my $remote_upgrade = &subs::setting_grabber({ app => '__president', setting => 'remote_upgrade' });
			#	my $remote_connect_timer =  &subs::setting_grabber({ app => '__president', setting => 'remote_connect_timer' });
			#	if ($remote_connect_timer + (60 * 7 * 1000) < $timestamp) {
			#		&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => '' });
			#	}
			#	if ($remote_upgrade ne 'running' && $remote_connect_timer + 30000 < $timestamp) {
			#		&remote_machine_reconnector($c);
			#	}
				if ($data->{'controller_visible'} eq 'yes') {
					my $remote_machine_query = &subs::db_query('select buttons,uuid,status,signatorial,ip,data,connection,fqdn from remote_machines' );
					$remote_machines = $remote_machine_query->hashes;
					foreach my $rm ( @{$remote_machines} ) {
						$rm->{'data'} = eval { return decode_json $rm->{'data'} } || {};
					}
				}

			}
			if ($app eq 'tab') {
				if ($data->{'windows'}) {
					my $windows = eval { return from_json $data->{'windows'} } || [];

					foreach my $w ( keys %{$windows} ) {
						foreach my $set ( qw/scrollTop jopen/ ) {
							if ($set eq 'jopen') {
								$windows->{$w}->{$set} = encode_json $windows->{$w}->{$set};
							}
							&subs::setting_setter({ app => $windows->{$w}->{'app'}, setting => $set, value => $windows->{$w}->{$set} });
						}
						if ($windows->{$w}->{'headerUpdate'}) {
							my $header = &subs::db_query('select * from cache where app = ? and context = ? and timestamp > ?', $windows->{$w}->{'app'}, 'header', $windows->{$w}->{'headerUpdate'})->hashes;

							foreach my $head ( @{$header} ) {
								my $data = decode_sereal $head->{'data'};
								&Websocket::send($app, { type => 'header', app => $windows->{$w}->{'app'}, timestamp => $head->{'timestamp'}, header => $data->{'header'} });
							}
						}
					}
				}
			}
			# Only touch the heavy columns when the client actually sent them, so a
			# light heartbeat doesn't blank out the last known layout.
			my $ws_update = {
				timestamp => $timestamp,
				server_time => $server_time,
				type => $data->{'type'},
				connection_id => $connection_id,
				local_address => $local_address,
				remote_address => $remote_address,
				href => $data->{'href'},
				pathname => $data->{'pathname'}
			};
			foreach my $optional ( qw/windows music_data jp_data/ ) {
				$ws_update->{$optional} = $data->{$optional} if defined $data->{$optional};
			}
			my $ws_updated = &subs::db_update('websockets', $ws_update, {
				browser_tab_id => $browser_tab_id,
				app => $data->{'app'}
			});
			# The row can vanish underneath a live socket: stale-row sweeps,
			# warranty expiry while a tab slept, or older builds that deleted
			# too broadly. A heartbeat that matched no row means the controller
			# can no longer see this websocket, so put the row back.
			unless ($ws_updated && $ws_updated->rows) {
				# Same as the connect insert: warranty settings are negative
				# offsets ('-1d' puts the row a day ahead), so alarm_haircut
				# won't cull a freshly healed row.
				my $app_warranty = &subs::setting_grabber({ app => $c->session('app'), setting => 'warranty' });
				my $warranty = &subs::ago_calc($app_warranty || &subs::setting_grabber({ app => 'me', setting => 'warranty' }), $server_time);
				&subs::db_insert('websockets', {
					%{$ws_update},
					browser_tab_id => $browser_tab_id,
					browser_tab => $browser_tab,
					db => $database,
					'uuid' => $uuid,
					app => $data->{'app'},
					connected => $init_data->{'connected'} || $timestamp,
					hostname => $hostname,
					user_agent => $user_agent,
					random_string => &subs::random_string_creator(25),
					ticket_uuid => $c->session('ticket_uuid'),
					warranty => $warranty
				});
			}
			if ($data->{'debriefer'}) {
				if ($c->session('ticket_uuid')) {
					&subs::db_query('update tickets set debriefer = ? where uuid = ?', $data->{'debriefer'}, $c->session('ticket_uuid'));
				}
				if ($c->session('privilege') eq 'citizen') {
					my $hostname = `hostname`;
					chomp($hostname);
					&subs::setting_setter({ app => '__DEBRIEFING__', setting => $hostname, value => $data->{'debriefer'} });
				}
			}
			my $community = &subs::db_query('select * from websockets where ( app = ? or app like ? ) and type = ? and server_time >= ? order by server_time DESC',$app, $app . '@%', 'stayingAlive',$server_time - 5000);
			my $neighbours = $community->hashes;
			foreach my $n ( @{$neighbours} ) {
				my $neighbour_windows = $n->{'windows'};
				my $neighbourhood = eval { return decode_json $n->{'windows'} } || {};
				$n->{'user_agent'} = &subs::abbreviate_name($n->{'user_agent'});
				foreach my $nw ( keys %{$neighbourhood} ) {
					$neighbourhood->{$nw}->{'formatted_name'} = &subs::format_name($neighbourhood->{$nw}->{'app'});
					$neighbourhood->{$nw}->{'shorthand_name'} = &subs::shorthand_name($neighbourhood->{$nw}->{'formatted_name'});
				}
				$n->{'windows'} = encode_json $neighbourhood;
			}

			my $return_data = {
				browser_tab_id => $browser_tab_id,
				browser_tab => $browser_tab,
				'uuid' => $uuid,
				timestamp => $timestamp,
				app => $data->{'app'},
				neighbours => $neighbours,
				from => $hostname,
				connection_id => $connection_id,
				user_agent => $user_agent,
				type => $data->{'type'},
				local_address => $local_address,
				remote_address => $remote_address,
				input => $data->{'input'},
				remote => $remote_machines
			};
			if (-e './templates/websockets/' . &subs::path_name($app) . '.html.ep') {
				$return_data->{'template'} = $c->render_to_string(
					template => 'websockets/' . &subs::path_name($app),
					ws => $return_data
				);
				if ($app eq 'server') { delete $return_data->{'remote'}; }
			}

			&Websocket::send($app,$return_data);

		}
		elsif (($data->{'type'} || '') eq 'terminal_open' && $app eq 'server') {
			# Every Terminal window names its own pty. A window opened from the
			# session list attaches to the one still running; a new window starts one.
			my $id = &terminal_session_id_clean($data->{'terminal_id'});
			my $existed = ($gb::terminal_sessions->{$id} ? 1 : 0);
			if (!$existed) {
				&terminal_session_start($id, {
					host => $data->{'host'},
					user => $data->{'user'},
					port => $data->{'port'}
				});
			}
			else {
				&terminal_session_status($id);
			}
			&Websocket::send('server', { terminal_id => $id, terminal_opened => ($existed ? 0 : 1) });
		}
		elsif ($data->{'pty'} && $app eq 'server') {
			# Keys arrive as the bytes a terminal should receive (the client
			# encodes arrows, Backspace, Tab, Ctrl+C and the rest). Old clients sent
			# the browser's key name and a handful were mapped here. Anything the
			# browser calls a modifier key is not input at all - it used to be
			# echoed back and printed "Shift" on the screen.
			my $input = $data->{'input'};
			if (!defined $input && defined $data->{'command'} && (($data->{'keyCode'} || 0) == 13)) {
				$input = $data->{'command'} . "\r";
			}
			if (defined $input && length $input) {
				$input = &terminal_input_bytes($input);
				&terminal_session_write($data->{'terminal_id'}, $input) if length $input;
			}
		}
		elsif (($data->{'type'} || '') eq 'terminal_connect' && $app eq 'server') {
			# Switch this window's shell to another machine over ssh. The host, user
			# and port are validated in terminal_shell_clean; no shell is involved
			# in starting it, so the values never reach a command line string.
			&terminal_session_start($data->{'terminal_id'}, {
				host => $data->{'host'},
				user => $data->{'user'},
				port => $data->{'port'}
			});
		}
		elsif (($data->{'type'} || '') eq 'terminal_local' && $app eq 'server') {
			&terminal_session_start($data->{'terminal_id'}, {});
		}
		elsif (($data->{'type'} || '') eq 'terminal_end' && $app eq 'server') {
			&terminal_session_stop($data->{'terminal_id'});
		}
		elsif (($data->{'type'} || '') eq 'terminal_refresh' && $app eq 'server') {
			# A window that has just attached to a running session asks the shell to
			# draw its prompt again. It only does this on a blank screen.
			&terminal_session_write($data->{'terminal_id'}, "\r");
		}
		elsif (($data->{'type'} || '') eq 'terminal_resize' && $app eq 'server') {
			my $rows = int($data->{'rows'} || 0);
			my $cols = int($data->{'cols'} || 0);
			if ($rows > 0 && $rows <= 500 && $cols > 0 && $cols <= 1000) {
				&terminal_session_resize($data->{'terminal_id'}, $rows, $cols);
			}
		}
		elsif ($data->{'type'} eq 'synth' && $app eq 'music') {
			my $freq = $data->{'freq'};
			my $waveform = $data->{'waveform'};
			my $length = $data->{'length'};
      &subs::subprocessor(sub {
		    Mojo::IOLoop->reset;

				`play "|sox -n -p synth $length $waveform $freq " &`;
			}, { name => 'synth ws player' });
		}
		elsif ($data->{'method'} eq 'playerCache') {
			&subs::cache_set({ app => 'music', context => 'player' }, $data);
		}
		elsif ($data->{'method'} eq 'transmitter') {
			$data->{'browser_tab_id'} = $browser_tab_id;
			&subs::music_transmitter($c, $data);
		}
		elsif ($data->{'method'} eq 'textAreaMagic') {
			my $context = &text_area_context($data->{'magic_vars'});
			my ($magic,$token) = &text_area_magic($data->{'text'}, $context, { plain => $data->{'plain'} });
			if ($magic ne $data->{'text'}) {
				$data->{'text'} = $magic;
				$data->{'token'} = $token;
				&Websocket::send('tab', { textAreaMagic => $data });
			}
		}
		else {
			$data->{'not_me'} = 1;
			$data->{'browser_tab_id'} = $browser_tab_id;

			&Websocket::send($app, $data);
		}
	});
	$c->on(finish => sub ($c,$code,$reason) {
		# A resume that rebuilds sockets (a phone waking) can register a new
		# connection for the same tab before this older, silently dead one is
		# noticed to be gone. Only a connection still on duty may clear the tab
		# out and log the stop, or the fresh socket goes deaf.
		my $on_duty = $gb::ws->{$app}->{$browser_tab_id};
		if ($on_duty && $on_duty == $c->tx) {
			# A socket that is gone leaves no row behind unless it was parked in a
			# named room - the parking lot keeps those on purpose. It used to be
			# marked type=closed instead, and with a warranty years out those rows
			# were never culled (about 870 dead rows had piled up).
			&subs::db_query('delete from websockets where app = ? and browser_tab_id = ? and room is null', $app, $browser_tab_id);
			delete $gb::ws->{$app}->{$browser_tab_id};
			&Websocket::send('server', { magic_wand => $browser_tab_id, action => 'closed', timestamp => $timestamp });
			if ($app eq 'music') {
				if ($log_me eq 'on') {
					my $appts = &subs::db_query('select * from appointments where source_uuid = ? and app = ? and type = ? order by timestamp desc limit 30', $browser_tab, $computer_name,'start')->hashes;
					foreach my $appt ( @{$appts} ) {
						&appointment_writer($c, {
							type => 'stop',
							uuid => $appt->{'uuid'},
							app => $appt->{'app'}
						});
						&subs::appt_header_printer({ app => $appt->{'app'} });
						&Websocket::send('server', { console => 'appointmentDetailGrabber(\'' . $appt->{'app'} . '\',\'' . $appt->{'uuid'} .'\');'});
					}
				}
			}
		}
		&websocket_close($app);
		# Tidy stale rows for this tab only. This used to run against a
		# *future* timestamp, so closing any socket deleted every other
		# tab's rows too and the controller list stayed empty until the
		# next reconnect. ago_calc counts backwards: '1d' is yesterday,
		# '-1d' is tomorrow.
		my $stale = &subs::ago_calc('1d', &subs::rightNow());
		&subs::db_query('delete from websockets where room is null and browser_tab_id = ? and server_time < ?', $browser_tab_id, $stale)->hashes;
	});

	unless (1 == 0 && $c->param('remote') eq 'yes') {
		my $remote_machine_query = &subs::db_query('select * from remote_machines where connection=?','active' );
		my $remote_machines = $remote_machine_query->hashes;
		foreach my $rm ( @{$remote_machines} ) {
			my $id = '';
			my @ip = split /\./, $rm->{'ip'};
			if ($rm->{'ip'} =~ /[A-Za-z]/gi) {
				$id = $ip[0];
			}
			else {
				$id = $ip[-1];
			}
			my $command = { console => 'websocketStart(\''. $app . '@' . $id . '\',\'wss://' . $rm->{'ip'} . ':' . $rm->{'ws_port'} . '/manager/ws?remote=yes&app=' . $app . '@' . $id . '&browser_tab_id=' . $rm->{'signatorial'} . '&timestamp=' . &subs::rightNow() . '&ws_auth=' . $rm->{'ws_auth'} . '\');' };
			#&Websocket::send('server', $command);# if !grep { $_ eq $app } qw/music server tab/;
		}
	}
};


# The bytes a key press should send down the pty. The browser now sends those
# bytes itself, so this only has to keep an older page working: a whole-string
# key name is mapped, a modifier name is dropped (it is not input), and any
# other string passes through unchanged.
sub terminal_input_bytes {
	my $input = shift;
	return '' unless defined $input && length $input;
	my %named = (
		Enter => "\r", Return => "\r",
		Backspace => "\x7f", Delete => "\x1b[3~", Insert => "\x1b[2~",
		Tab => "\t", Escape => "\x1b", Esc => "\x1b",
		ArrowUp => "\x1b[A", ArrowDown => "\x1b[B", ArrowRight => "\x1b[C", ArrowLeft => "\x1b[D",
		Home => "\x1b[H", End => "\x1b[F",
		PageUp => "\x1b[5~", PageDown => "\x1b[6~",
		F1 => "\x1bOP", F2 => "\x1bOQ", F3 => "\x1bOR", F4 => "\x1bOS",
		F5 => "\x1b[15~", F6 => "\x1b[17~", F7 => "\x1b[18~", F8 => "\x1b[19~",
		F9 => "\x1b[20~", F10 => "\x1b[21~", F11 => "\x1b[23~", F12 => "\x1b[24~"
	);
	return $named{$input} if exists $named{$input};
	# A lone modifier is a key event, not a character: printing its name was the
	# old "Shift" and "Control" appearing in the middle of a command.
	return '' if $input =~ /^(?:Shift|ShiftLeft|ShiftRight|Control|ControlLeft|ControlRight|Alt|AltLeft|AltRight|AltGraph|Meta|MetaLeft|MetaRight|OS|Super|Hyper|CapsLock|NumLock|ScrollLock|Fn|FnLock|Symbol|SymbolLock|ContextMenu|Dead|Process|Unidentified)$/;
	utf8::encode($input) if utf8::is_utf8($input);
	return $input;
}

# Only values that can name a host, an ssh login and a port get through; the
# start below passes them as separate argv entries, never through a shell.
sub terminal_shell_clean {
	my ($spec) = @_;
	$spec = {} unless ref $spec eq 'HASH';
	my $host = $spec->{'host'} // '';
	my $user = $spec->{'user'} // '';
	my $port = $spec->{'port'} // 8022;
	$host = '' unless $host =~ /^[A-Za-z0-9._:\-\[\]]{1,255}$/;
	$user = '' unless $user =~ /^[A-Za-z0-9._\-]{1,64}$/;
	if ($host ne '' && $user eq '') {
		$user = `whoami`;
		chomp $user;
		$user = '' unless $user =~ /^[A-Za-z0-9._\-]{1,64}$/;
	}
	$port = 8022 unless $port =~ /^\d+$/ && $port > 0 && $port < 65536;
	return { host => $host, user => ($host ne '' ? $user : ''), port => 0 + $port };
}

sub terminal_shell_label {
	my ($spec) = @_;
	my $who = `whoami`;
	chomp $who;
	my $host = `hostname`;
	chomp $host;
	return ((($spec->{'user'} // '') ne '') ? $spec->{'user'} : $who) . '@' . $spec->{'host'}
		if (($spec->{'host'} // '') ne '');
	return $who . '@' . $host;
}

sub terminal_session_id_clean {
	my $id = shift // '';
	$id =~ s/[^A-Za-z0-9_\-]//g;
	$id = substr($id, 0, 64);
	$id = 't' . &subs::random_string_creator(12) if length($id) < 4;
	return $id;
}

# The live session list the Terminal settings panel shows. The websocket worker
# writes it, the manager route reads it; an ended shell is removed here.
sub terminal_sessions_note {
	my ($id, $session, $state) = @_;
	my $now = &subs::rightNow();
	# cache is local and never synced: which shells are alive is this machine's
	# own fact, not house data another machine should adopt.
	my $map = &subs::cache_get({ app => 'terminal', context => 'sessions' }) || {};
	$map = {} unless ref $map eq 'HASH';
	if (($state // '') eq 'ended') {
		delete $map->{$id};
	}
	else {
		my $spec = $session->{'spec'} || {};
		$map->{$id} = {
			id => $id,
			label => &terminal_shell_label($spec),
			host => $spec->{'host'} || '',
			user => $spec->{'user'} || '',
			port => $spec->{'port'} || '',
			state => $state,
			at => $now
		};
		foreach my $k ( keys %{$map} ) {
			delete $map->{$k} if (($map->{$k}->{'at'} || 0) < $now - 86400000);
		}
	}
	&subs::cache_set({ app => 'terminal', context => 'sessions', warranty => '-1d' }, $map);
}

sub terminal_session_for {
	my ($id) = @_;
	return undef unless ref $gb::terminal_sessions eq 'HASH';
	if ($id && $gb::terminal_sessions->{$id}) { return $gb::terminal_sessions->{$id}; }
	my @ids = keys %{$gb::terminal_sessions};
	return $gb::terminal_sessions->{$ids[0]} if scalar(@ids) == 1;
	return undef;
}

sub terminal_session_stop {
	my ($id, $quiet) = @_;
	my $session = $gb::terminal_sessions->{$id};
	return unless $session;
	delete $gb::terminal_sessions->{$id};
	if (my $fork = $session->{'fork'}) {
		eval {
			$fork->write("exit\r");
			$fork->close;
			$fork->kill('TERM');
		};
	}
	&terminal_sessions_note($id, $session, 'ended') unless $quiet;
	unless ($quiet) {
		&Websocket::send('server', { terminal_id => $id, terminal_shell => {
			state => 'ended',
			label => &terminal_shell_label($session->{'spec'} || {}),
			message => &subs::ui('The shell ended.')
		} });
	}
}

sub terminal_session_start {
	my ($id, $spec) = @_;
	$id = &terminal_session_id_clean($id);
	$spec = &terminal_shell_clean($spec);
	&terminal_session_stop($id, 1);
	my $session = { id => $id, spec => $spec, live => 0, rows => 24, cols => 80 };
	my $fork = Mojo::IOLoop::ReadWriteFork->new;
	$fork->conduit({ raw => 1, type => 'pty' });
	$fork->on(read => sub {
		my ($f, $bytes) = @_;
		return unless $gb::terminal_sessions->{$id} && $gb::terminal_sessions->{$id}->{'fork'} == $f;
		&Websocket::send('server', { terminal => encode_base64($bytes), terminal_id => $id });
		if (!$session->{'live'}) {
			$session->{'live'} = 1;
			my $state = (($spec->{'host'} // '') ne '') ? 'live' : 'local';
			&Websocket::send('server', { terminal_id => $id, terminal_shell => {
				state => $state, label => &terminal_shell_label($spec),
				host => $spec->{'host'}, user => $spec->{'user'}, port => $spec->{'port'}
			} });
			&terminal_sessions_note($id, $session, $state);
		}
	});
	$fork->on(close => sub {
		my ($f) = @_;
		return unless $gb::terminal_sessions->{$id} && $gb::terminal_sessions->{$id}->{'fork'} == $f;
		delete $gb::terminal_sessions->{$id};
		&Websocket::send('server', { terminal_id => $id, terminal_shell => {
			state => 'ended',
			label => &terminal_shell_label($spec),
			message => &subs::ui('The shell ended.')
		} });
		&terminal_sessions_note($id, $session, 'ended');
	});
	# stty sane matters: IO::Pty hands the child a raw pty, so without it the shell
	# neither echoes the keys a person types nor turns Ctrl+C into a signal.
	my ($program, @args) = ('sh', '-c', 'stty sane 2>/dev/null; exec bash -i');
	my %env = (
		%ENV,
		INPUTRC => '/dev/null',
		PROMPT_COMMAND => '',
		TERM => 'xterm-256color',
		COLORTERM => 'truecolor',
		TERM_PROGRAM => 'JawnOS',
		LANG => ($ENV{'LANG'} || 'C.UTF-8')
	);
	my $state = 'local';
	if (($spec->{'host'} // '') ne '') {
		$state = 'connecting';
		($program, @args) = ('ssh', '-tt', '-p', $spec->{'port'},
			'-o', 'StrictHostKeyChecking=accept-new',
			'-o', 'ConnectTimeout=10',
			'-o', 'ServerAliveInterval=30',
			$spec->{'user'} . '@' . $spec->{'host'});
	}
	$fork->start({ program => $program, program_args => \@args, env => \%env });
	$session->{'fork'} = $fork;
	$gb::terminal_sessions->{$id} = $session;
	my $label = &terminal_shell_label($spec);
	my $notice = "\r\n\x1b[38;5;114m[JawnOS]\x1b[0m "
		. ($state eq 'local' ? &subs::ui('local shell') : &subs::ui('connecting to') . ' ' . $label)
		. "\r\n";
	Mojo::IOLoop->timer(0 => sub {
		return unless $gb::terminal_sessions->{$id} && $gb::terminal_sessions->{$id}->{'fork'} == $fork;
		&Websocket::send('server', {
			terminal => encode_base64($notice),
			terminal_id => $id,
			terminal_shell => { state => $state, label => $label, host => $spec->{'host'}, user => $spec->{'user'}, port => $spec->{'port'} }
		});
	});
	# The fork is forked on the next tick, so the pty handle exists a moment later.
	Mojo::IOLoop->timer(0.4 => sub {
		return unless $gb::terminal_sessions->{$id} && $gb::terminal_sessions->{$id}->{'fork'} == $fork;
		if (my $pty = $fork->read_handle) {
			eval { $pty->set_winsize($session->{'rows'}, $session->{'cols'}, 0, 0) };
		}
	});
	&terminal_sessions_note($id, $session, $state);
	return $session;
}

sub terminal_session_write {
	my ($id, $bytes) = @_;
	my $session = &terminal_session_for($id);
	return unless $session && $session->{'fork'} && defined $bytes && length $bytes;
	$session->{'fork'}->write($bytes);
}

sub terminal_session_resize {
	my ($id, $rows, $cols) = @_;
	my $session = &terminal_session_for($id);
	return unless $session;
	$session->{'rows'} = $rows;
	$session->{'cols'} = $cols;
	if (my $fork = $session->{'fork'}) {
		if (my $pty = $fork->read_handle) {
			eval { $pty->set_winsize($rows, $cols, 0, 0) };
		}
	}
}

sub terminal_session_status {
	my ($id) = @_;
	my $session = &terminal_session_for($id);
	return unless $session;
	my $spec = $session->{'spec'} || {};
	my $state = (($spec->{'host'} // '') ne '')
		? ($session->{'live'} ? 'live' : 'connecting')
		: 'local';
	&Websocket::send('server', { terminal_id => $session->{'id'}, terminal_shell => {
		state => $state, label => &terminal_shell_label($spec),
		host => $spec->{'host'}, user => $spec->{'user'}, port => $spec->{'port'}
	} });
}

# Kept for callers from older code: sessions now start when a window opens.
sub terminal_pty_runner {
	return;
}

post 'manager/ws/remote_control' => sub($c) {
	my $destination = $c->param('destination');
	my $value = $c->param('value');
	my $app = &subs::unformat_name($c->param('app'));
	my $control = $c->param('control');
	&Websocket::send($app, {
		value => $value,
		app => $app,
		control => $control,
		destination => $destination,
		type => 'remote_control'
	});
	$c->render(text => 'ok');

};

get '/manager/remote_refresh' => sub ($c) {
	my $bti = $c->param('bti');
	my $browser_tab_id = $c->param('browser_tab_id');
	my $timestamp = $c->param('timestamp');
	&Websocket::send('server', { console => 'location.reload()', origin => $browser_tab_id, destination => $bti, timestamp => $timestamp });
};


sub paperRoute($msg) {
	my ($db,$database,$sql) = &subs::database_grabber();
	my $original_msg = $msg;
	if ( eval { encode_json $msg }) {
		my $m = encode_json $msg;
		if (eval { $sql->db } && $sql->dsn !~ /:$/) {
			my $server_time = &subs::rightNow();
			my $uuid = &subs::random_string_creator(20);
			&subs::db_insert('websocket_messages', {
				timestamp => $original_msg->{'timestamp'},
				message => $m,
				server_time => $server_time,
				uuid => $uuid,
				sent_count => 0,
				environment => 'papers'
			});
		}
	}
}

if ($ENV{PURPOSE} && ($ENV{PURPOSE} eq 'alarm' || ($ENV{PORT_ENV} eq 'development' && $ENV{PURPOSE} eq 'main'))) {
	#require './Alarm.pl';
	#&Alarm::alarm_clock();;
}


if ($ENV{PURPOSE} && ($ENV{PURPOSE} eq 'websocket' || ($ENV{PORT_ENV} eq 'development' && $ENV{PURPOSE} eq 'main'))) {
	# Sessions are ptys owned by this worker: a restarted worker has none, so
	# the list a person sees must not promise shells that no longer exist.
	$gb::terminal_sessions = {};
	&subs::cache_set({ app => 'terminal', context => 'sessions', warranty => '-1d' }, {});


	my %buffers;

	# These sockets are how a manager worker hands a live push to the websocket
	# worker that holds the page's socket. The websocket worker must bind them
	# *itself*, after the fork: bound earlier (in the process that loads this
	# file), the pre-fork server's start registers the listeners as MOJO_REUSE
	# descriptors and the forked worker then "reuses" a file descriptor while
	# no path exists on disk. Every push then looked delivered to the caller
	# while the page never saw it - the phone's silent MMS failure. Bound here,
	# on the worker's first tick, the path is real; and a worker that is
	# recycled leaves a stale path behind, so any path that stops answering is
	# bound again. (See ws_server_socket: it also clears this path from
	# MOJO_REUSE, which is what made the reuse win over a real bind.)
	my $ws_binder_pid = $$;
	my $ws_bind_all = sub {
		my ($check) = @_;
		foreach my $ws ( @{$gb::ws_apps} ) {
			my $file = $gb::tmp_dir . '/ws/' . &subs::path_name($ws);
			if ($check && -e $file) {
				my $probe = IO::Socket::UNIX->new(Peer => $file, Type => SOCK_STREAM);
				if ($probe) { close $probe; next; }
			}
			$ws_server->{$ws} = &ws_server_socket({ app => $ws });
		}
	};
	# only a forked worker binds: the loader's own loop never accepts, so a
	# listener it held would swallow a push with no page socket to deliver to
	Mojo::IOLoop->next_tick(sub { $ws_bind_all->(0) if $$ != $ws_binder_pid });
	Mojo::IOLoop->recurring(5 => sub { $ws_bind_all->(1) if $$ != $ws_binder_pid });
	sub ws_server_socket($data) {
		my $app = $data->{'app'} || 'general';
		my $folder = $gb::tmp_dir . '/ws';
		`mkdir -p $folder` unless -e $folder;
		my $file = $folder . '/' . &subs::path_name($app);
		# a reused descriptor wins over a real bind in Mojo's listen(), and the
		# pre-fork server put this path in MOJO_REUSE from the loader's own
		# listeners; drop it so the bind really creates the path
		if ($ENV{'MOJO_REUSE'}) {
			$ENV{'MOJO_REUSE'} = join ',', grep { !/^unix:\Q$file\E:/ } split /,/, $ENV{'MOJO_REUSE'};
		}
		unlink $file if -e $file;
		my $server = eval {
			Mojo::IOLoop->server({ path => $file } => sub ($loop,$stream,$id) {
				$stream->handle->autoflush(1);
				$stream->high_water_mark(8 * 1024 * 1024);
				$buffers{$id} = '';
				$stream->on(read => sub ($stream, $bytes) {
					$buffers{$id} .= $bytes;


					while (1) {
						last if length($buffers{$id}) < 4;

			      my $payload_length = unpack('N', substr($buffers{$id}, 0, 4));

			      # If we don't have the full payload yet, wait for next event loop tick
			      last if length($buffers{$id}) < (4 + $payload_length);

			      # Extract header and data cleanly using 4-argument substr for speed
			      substr($buffers{$id}, 0, 4, '');
			      my $sereal_blob = substr($buffers{$id}, 0, $payload_length, '');

			      my $wsm = eval { $decoder->decode($sereal_blob) };

            if ($@) {
                warn "Worker $$: Failed to parse Sereal: $@";
                next;
            }
						&websocket_sender($wsm);



						$stream->write($wsm->{'uuid'}) if defined $wsm->{'uuid'} && $wsm->{'uuid'};
					}
				});
				$stream->on(close => sub {
					delete $buffers{$id};
				});
			});
		};
		my $err = $@;
		$log->error('ws socket ' . $file . ' could not bind: ' . ($err || 'no acceptor')) if $err || !defined $server;
		return $server;
	}

	my $mailfile = $gb::tmp_dir . '/ws/mailws';

	my $mailws_server;
	my $mailws_listener = sub {
		# the loader no longer binds the per-app sockets (a fork child must),
		# so this process makes the folder rather than finding it made
		my $ws_folder = $gb::tmp_dir . '/ws';
		`mkdir -p $ws_folder` unless -d $ws_folder;
		unlink $mailfile if -e $mailfile;
		$mailws_server = eval { Mojo::IOLoop->server({ path => $mailfile } => sub ($loop,$stream,$id) {
			$stream->handle->autoflush(1);
			$stream->high_water_mark(8 * 1024 * 1024);
			$buffers{$id} = '';
			$stream->on(read => sub ($stream, $bytes) {
				$buffers{$id} .= $bytes;


				while (1) {
					last if length($buffers{$id}) < 4;

			      my $payload_length = unpack('N', substr($buffers{$id}, 0, 4));

			      # If we don't have the full payload yet, wait for next event loop tick
			      last if length($buffers{$id}) < (4 + $payload_length);


			      # Extract header and data cleanly using 4-argument substr for speed
			      substr($buffers{$id}, 0, 4, '');
			      my $sereal_blob = substr($buffers{$id}, 0, $payload_length, '');
			      my $m = eval { $decoder->decode($sereal_blob) };
		        if ($@) {
		            warn "Worker $$: Failed to parse mail message: $@";
		            next;
		        }

					# one sender matches it against every tab's address
					my $count = &mailws_sender($m);

					# mail_arrival marked what the server just accepted: the tab socket
					# hears it for the start menu dot, and when no mailbox is watching
					# that thread the regular notification speaks
					if ($m->{'arrival'}) {
						&Websocket::send('tab', { type => 'mail_arrival', uuid => $m->{'uuid'}, message => $m->{'arrival_message'}, timestamp => $m->{'timestamp'} || &subs::rightNow() });
						unless ($count) {
							&notification_sender({ app => 'mailbox', role => 'all', title => 'Mail', message => $m->{'arrival_message'} || 'New mail', image => '/images/decipherable/envelope.png' });
						}
					}

				  $stream->write($m->{'uuid'});
				}
		    });
				$stream->on(close => sub {
						delete $buffers{$id};
				});
			});
		};
		$log->error('mailws could not bind: ' . $@) if $@;
	};
	$mailws_listener->();
	# like the per-app sockets above, the mail socket is put back up if it dies
	Mojo::IOLoop->recurring(5 => sub {
		my $is_running = defined Mojo::IOLoop->acceptor($mailws_server) ? 1 : 0;
		if (!$is_running) { $mailws_listener->(); }
	});
	sub websocket_close($app) {
		$app = $app;
		unless (grep { $app eq $_ } @{$gb::ws_apps}) {
			if (scalar keys %{$gb::ws->{$app}} == 0) {
				Mojo::IOLoop->remove($ws_server->{$app});
				my $folder = $gb::tmp_dir . '/ws';
				my $file = $folder . '/' . &subs::path_name($app);
				`rm -R $file` if -e $file;
				delete $ws_server->{$app};
			}



		}
	}
}

sub websocket_sender($wsm) {
	my $returner;
	my $return_msg = { save => [] };
	# The message travels as the bytes encode_json made. Mojo encodes a plain
	# string to UTF-8 again when it builds a text frame, so an emoji or an accent
	# would reach the browser double-encoded (and reach the phone's SMS bridge as
	# mojibake). Hand the frame characters instead, and encode exactly once.
	my $wire = $wsm->{'message'};
	utf8::decode($wire) if defined $wire && length $wire && !utf8::is_utf8($wire);
	if ($wsm->{'environment'} eq 'papers') {
		foreach my $subscriber ( keys %{$gb::paperboy} ) {
			$gb::paperboy->{$subscriber}->send($wire);
		}
	}
	else {
		my $original_msg = eval { return decode_json $wsm->{'message'} } || {};
		#return unless $original_msg->{'app'};
		if ($original_msg->{'pty'}) {
			&terminal_session_write($original_msg->{'terminal_id'}, $original_msg->{'input'});
		}
		my $msg = $original_msg;
		my $app = $wsm->{'app'};
		my $server_time = $wsm->{'server_time'};
		my $timestamp = $wsm->{'timestamp'};
		# the overlay/open/key/console pushes are how a locked device is driven
		# and how the phone hears about the lock; everything else that a server
		# pushes to a tab is dropped for a device with a manual padlock row
		my $locked_ok = $original_msg->{'padlock'} || $original_msg->{'padlock_open'} || $original_msg->{'padlock_key_show'} || $original_msg->{'console'};
		my $server_push = ($app eq 'server' && !$locked_ok) ? 1 : 0;
		my $recipient_locked = sub {
			my ($conn) = @_;
			return 0 unless $server_push && $conn;
			my $dev = $conn->{'device_uuid'} || '';
			return 0 unless $dev;
			return &padlock_device_locked($dev);
		};
		my $count = 0;

		foreach my $ws ( $gb::ws, $gb::remote_ws ) {
			if ($count != 0) {
				my @app = split /\@/, $app;
				$app = $app[0];
			}
			else {

			}
			if ($original_msg->{'remote_only'}) {
				if ($original_msg->{'remote_only'} eq 'yes' && $count == 0) {
					next;
				}
			}
			if ( $original_msg->{'destination'}) {
				if (my $conn = $ws->{$app}->{$wsm->{'destination'}}) {
					$conn->send($wire) unless $recipient_locked->($conn);
				}
				elsif ($wsm->{'server_time'} > &subs::rightNow() - 10000) {
					push @{$return_msg->{'save'}}, $wsm;
				}
			}
			elsif ($original_msg->{'not_me'}) {
				foreach my $w ( keys %{$ws->{$app}} ) {
					if (my $conn = $ws->{$app}->{$w}) {
						next if $w eq $original_msg->{'browser_tab_id'};
						next if $recipient_locked->($conn);
						if ($msg->{'role'} && $msg->{'role'} ne 'all') {
							if ($msg->{'role'} ne $conn->{'privilege'}) {
								next;
							}
						}
						$returner = $conn->send($wire);
					}
				}
			}
			else {
				foreach my $w ( keys %{$ws->{$app}}) {
					if (my $conn = $ws->{$app}->{$w}) {
						next if $recipient_locked->($conn);
						if ($msg->{'role'} && $msg->{'role'} ne 'all') {
							if ($msg->{'role'} ne $conn->{'privilege'}) {
								next;
							}
						}
						$returner = $conn->send($wire);
					}
				}
			}
			$count++;
		}

	}
	return $return_msg;
}

# The construct columns in the fixed order a channel tuple names them: the
# plural keys sorted, which is what mail_channel_key joins and what a list
# row's uuid concatenates. Changing $gb::social_constructs changes the tuple,
# so every place that builds or splits one asks here instead of naming six.
sub mail_construct_columns() {
	return map { $gb::social_constructs->{$_}->{'sing'} } sort keys %{$gb::social_constructs};
}

# The social constructs with every value filled: what the client leaves out
# falls back to the same default the mailbox reader reaches for, so a tab with
# its pickers hidden (a phone) still has an address a message can find.
sub mailws_constructs($picker) {
	my $constructs = {};
	foreach my $k ( keys %{$gb::social_constructs} ) {
		my $value = $picker->{$k};
		$value = undef unless defined $value && length $value;
		$constructs->{$k} = $value || $gb::social_constructs->{$k}->{'def'};
	}
	return $constructs;
}

# The house's trust rule for words: a citizen or a resident holds a ticket
# this house issued and named, so what they write is filed - stored, synced
# and readable later like any mail. A guest is a visitor whose words are only
# ever heard live by whoever is tuned in: they are never written down.
# Moving a privilege between the two lists is the whole policy.
sub mailws_trusted($c) {
	my $privilege = $c->session('privilege');
	return ($privilege eq 'citizen' || $privilege eq 'resident') ? 1 : 0;
}

# A dialled picker: at least one social construct chosen by hand. A tab with
# an empty picker has no dial of its own - a guest on their ticket, say - not
# a tab dialled to the defaults.
sub mailws_picker_dialled($picker) {
	return 0 unless ref $picker eq 'HASH';
	foreach my $k ( keys %{$gb::social_constructs} ) {
		return 1 if defined $picker->{$k} && length $picker->{$k};
	}
	return 0;
}

# One tuple of construct values names one thread; this is how two dials are
# compared, whatever order their keys arrived in.
sub mail_channel_key($constructs) {
	return join "\x1f", map { defined $constructs->{$_} ? $constructs->{$_} : '' } sort keys %{$gb::social_constructs};
}

# The dials this house advertises to guests, each filled to the same six
# values a message carries, so comparing one to a dial is comparing threads.
sub mail_public_channels() {
	my $channels = eval { return decode_json &subs::setting_grabber({ app => 'mail', setting => 'public_channels' }) } || [];
	my @out;
	foreach my $ch ( @{$channels} ) {
		push @out, &mailws_constructs($ch) if ref $ch eq 'HASH';
	}
	return \@out;
}

# A channel is public only when the house advertised exactly this tuple; a
# guest may watch or write to advertised dials and nothing else.
sub mail_public_channel_allows($picker) {
	return 0 unless &mailws_picker_dialled($picker);
	my $key = &mail_channel_key(&mailws_constructs($picker));
	foreach my $ch ( @{&mail_public_channels()} ) {
		return 1 if &mail_channel_key($ch) eq $key;
	}
	return 0;
}

# The human name of a dial: its construct values in the order the dial lists them.
sub mail_channel_label($constructs) {
	return join ' ', map { &subs::format_name($constructs->{$_->{'name'}}) }
		sort { $a->{'order'} <=> $b->{'order'} } values %{$gb::social_constructs};
}

# An unfiled letter's pace: a guest speaks at most this many times a minute.
our %mailws_untrusted_rate = ();
sub mailws_untrusted_throttle($id) {
	my $now = time();
	my $entry = $mailws_untrusted_rate{$id};
	if (!$entry || $now - $entry->{'at'} > 60) {
		$entry = $mailws_untrusted_rate{$id} = { at => $now, count => 0 };
	}
	$entry->{'count'}++;
	return $entry->{'count'} <= 20 ? 1 : 0;
}

# What one mail tab is watching when it connects: a guest watches a dial the
# house advertises when they tuned one, and their ticket otherwise; everyone
# else watches whichever of a phone number, an email address, a contact or a
# social construct chain their section put in the url.
sub mailws_address($c, $picker) {
	my $address = {};
	if ($c->session('privilege') eq 'guest' && $c->session('ticket_uuid')) {
		if ($picker && &mail_public_channel_allows($picker)) {
			$address->{'picker'} = &mailws_constructs($picker);
		}
		else {
			$address->{'ticket'} = $c->session('ticket_uuid');
		}
	}
	else {
		my $phone = $c->param('phone');
		my $email = $c->param('email');
		my $contact = $c->param('mail_contact');
		if ($phone && $phone ne 'null' && $phone ne 'undefined') {
			$address->{'phone'} = $phone;
		}
		elsif ($email && $email ne 'null' && $email ne 'undefined') {
			$address->{'email'} = $email;
		}
		elsif ($contact && $contact ne 'null') {
			$address->{'contact'} = $contact;
		}
		else {
			$address->{'picker'} = &mailws_constructs($picker);
		}
	}
	return $address;
}

# The constructs a message is addressed to - undef when it wears a phone, an
# email or a contact instead.
sub mailws_message_constructs($m) {
	return undef if $m->{'phone'} || $m->{'email'} || $m->{'mail_contact'} || $m->{'contact'};
	my $picker = $m->{'picker'};
	$picker = eval { return decode_json $picker } unless ref $picker eq 'HASH';
	$picker = {} unless ref $picker eq 'HASH';
	return &mailws_constructs($picker);
}

sub mailws_address_matches($address, $m, $constructs) {
	return 0 unless $address;
	if ($m->{'phone'}) {
		return (defined $address->{'phone'} && $address->{'phone'} eq $m->{'phone'}) ? 1 : 0;
	}
	if ($m->{'email'}) {
		return (defined $address->{'email'} && lc $address->{'email'} eq lc $m->{'email'}) ? 1 : 0;
	}
	my $contact = $m->{'mail_contact'} || $m->{'contact'};
	if ($contact) {
		return 1 if defined $address->{'contact'} && $address->{'contact'} eq $contact;
		return 1 if defined $address->{'ticket'} && $address->{'ticket'} eq $contact;
		return 0;
	}
	return 0 unless $address->{'picker'} && $constructs;
	foreach my $k ( keys %{$constructs} ) {
		my $watched = $address->{'picker'}->{$k};
		return 0 unless defined $watched && $watched eq $constructs->{$k};
	}
	return 1;
}

# Deliver one mail message to every tab it is addressed to. The registry is
# flat now - one entry per browser tab - so the address does the matching
# instead of a hand-walked nest of hash levels, and every door a message can
# come through (a browser, the mail unix socket, the depublicizer) ends up
# here.
sub mailws_sender($m) {
	my $constructs = &mailws_message_constructs($m);
	my $pmsg = encode_json $m;
	# Mojo encodes a plain string to UTF-8 when it builds a text frame, so the
	# JSON bytes above would be encoded a second time and an emoji would land in
	# the browser as mojibake. Send characters, encoded once.
	my $wire = $pmsg;
	utf8::decode($wire) if !utf8::is_utf8($wire);
	my $sent = 0;
	foreach my $bti ( keys %{$gb::mailws} ) {
		my $entry = $gb::mailws->{$bti};
		next unless $entry && $entry->{'tx'};
		next unless &mailws_address_matches($entry->{'address'}, $m, $constructs);
		my $ok = eval { $entry->{'tx'}->send($wire); 1 };
		unless ($ok) {
			warn "Worker $$: mail send failed for $bti: $@";
			delete $gb::mailws->{$bti};
			next;
		}
		$sent++;
	}
	return $sent;
}


get '/manager/ws_close' => sub($c) {
	my $websocket = &subs::db_select('websockets', undef, { app => $c->param('app'), browser_tab_id => $c->param('browser_tab_id') })->hash;
	unless ($websocket->{'room'}) {
		&subs::db_delete('websockets', { app => $c->param('app'), browser_tab_id => $c->param('browser_tab_id') });
	}
	$c->render('text' => 'ok');
};


if ($ENV{PURPOSE} && ($ENV{PURPOSE} ne "alarm" && $ENV{PURPOSE} ne "watch" && $ENV{PURPOSE} ne "teletype")) {

	app->sessions->samesite('lax');
	$ENV{MOJO_MAX_MESSAGE_SIZE} = 1023423423473741824;
	app->renderer->cache->max_keys(0);
	app->sessions->encrypted(1);
	app->secrets($gb::secret_maker);
	app->sessions->cookie_name($ENV{'cookie_name'});
	if ($config->{'environment'} eq 'production') {
		app->log->level('error');
	} else {
		app->log->level('debug');
	}

	app->start;
}
else {
	1;
}
